  str_skill_href_desc_name_30058 = "始原のカード",
  str_skill_href_desc_desc_30058 = "始原のカードは太陽、月、星の3種類。3枚のカードを選び、カードの組み合わせによって異なる効果が発動する。\nすべて同じ――「集う光」：<color=#00F6FF>現在の隊長</color>がジェノの基礎攻撃力の<color=#00F6FF>8%</color>の追加攻撃力を獲得する。\nすべて異なる――「凌日の星月」：<color=#00F6FF>現在の最後尾の光霊</color>がジェノの基礎攻撃力の<color=#00F6FF>7%</color>の追加攻撃力を獲得する。\nその他――「異色の双輝」：この戦闘での隊長変更回数+1。失った理性値の<color=#00F6FF>18%</color>を回復する。\n攻撃力上昇の効果は戦闘終了まで持続。同一効果は累積されない。",
  str_skill_href_desc_name_30059 = "始原のカード",
  str_skill_href_desc_desc_30059 = "始原のカードは太陽、月、星の3種類。3枚のカードを選び、カードの組み合わせによって異なる効果が発動する。\nすべて同じ――「集う光」：<color=#00F6FF>現在の隊長</color>がジェノの基礎攻撃力の<color=#00F6FF>8%</color>の追加攻撃力を獲得する。\nすべて異なる――「凌日の星月」：<color=#00F6FF>現在の最後尾の光霊</color>がジェノの基礎攻撃力の<color=#00F6FF>7%</color>の追加攻撃力を獲得する。\nその他――「異色の双輝」：この戦闘での隊長変更回数+1。失った理性値の<color=#00F6FF>18%</color>を回復する。\n攻撃力上昇の効果は戦闘終了まで持続。同一効果は累積されない。",
  str_skill_href_desc_name_30060 = "始原のカード",
  str_skill_href_desc_desc_30060 = "始原のカードは太陽、月、星の3種類。3枚のカードを選び、組み合わせのタイプによって異なる効果が発動する。\nすべて同じ――「集う光」：<color=#00F6FF>現在の隊長</color>がジェノの基礎攻撃力の<color=#00F6FF>8%</color>の追加攻撃力を獲得する。\nすべて異なる――「凌日の星月」：<color=#00F6FF>現在の最後尾の光霊</color>がジェノの基礎攻撃力の<color=#00F6FF>7%</color>の追加攻撃力を獲得する。\nその他――「異色の双輝」：この戦闘での隊長変更回数+1。失った理性値の<color=#00F6FF>25%</color>を回復する。\n攻撃力上昇の効果は戦闘終了まで持続。同一効果は累積されない。",
  str_skill_href_desc_name_30061 = "噴流の印",
  str_skill_href_desc_desc_30061 = "噴流の印は<color=#00F6FF>3</color>ターン後に戦場から消滅する",
  str_skill_href_desc_name_30062 = "律法の像",
  str_skill_href_desc_desc_30062 = "律法の像の最大レベルはLv5。他の光霊の設置物があると設置できず、敵が通過すると消滅する",
  str_skill_href_desc_name_30063 = "銃剣値",
  str_skill_href_desc_desc_30063 = "毎ターン開始時に<color=#00F6FF>1</color>獲得する",
  str_skill_href_desc_name_30064 = "銃剣値",
  str_skill_href_desc_desc_30064 = "戦闘開始時に<color=#00F6FF>2</color>獲得。毎ターン開始時に<color=#00F6FF>1</color>獲得",
  str_skill_href_desc_name_30065 = "吸収",
  str_skill_href_desc_desc_30065 = "連鎖による強化マス発動と同一のダメージ増加効果がある。光霊の強化マスに対応する効果を発動できる",
  str_skill_href_desc_name_30066 = "撮影フレーム",
  str_skill_href_desc_desc_30066 = "連鎖技発動後、<color=#00F6FF>撮影フレーム</color>の外にいる場合、その連鎖技の範囲に新しい撮影フレームを1つ生成する。フィールド上に同時に最多で<color=#00F6FF>2</color>つの撮影フレームが存在でき、超過するともっとも古いものが消える",
  str_skill_href_desc_name_30067 = "撮影フレーム",
  str_skill_href_desc_desc_30067 = "連鎖技発動後、<color=#00F6FF>撮影フレーム</color>の外にいる場合、その連鎖技の範囲に新しい撮影フレームを1つ生成する。フィールド上に同時に最多<color=#00F6FF>3</color>つの撮影フレームが存在でき、超過するともっとも古いものが消える",
  str_skill_href_desc_name_30068 = "撮影フレーム",
  str_skill_href_desc_desc_30068 = "連鎖技発動後、<color=#00F6FF>撮影フレーム</color>の外にいる場合、その連鎖技の範囲に新しい撮影フレームを1つ生成する。フィールド上に同時に最多<color=#00F6FF>3</color>つの撮影フレームが存在でき、超過するともっとも古いものが消える。戦闘開始時、初期地点に<color=#00F6FF>菱形12マス</color>の範囲をもつ撮影フレームを1つ生成する",
  str_skill_href_desc_name_30069 = "キュービックエネルギー",
  str_skill_href_desc_desc_30069 = "毎ターン<color=#00F6FF>1</color>獲得。最大<color=#00F6FF>9</color>まで",
  str_skill_href_desc_name_30070 = "キュービックエネルギー",
  str_skill_href_desc_desc_30070 = "戦闘開始時に<color=#00F6FF>2</color>増加。毎ターン<color=#00F6FF>1</color>増加。最大<color=#00F6FF>9</color>まで",
  str_skill_href_desc_name_30071 = "スキャンモジュール",
  str_skill_href_desc_desc_30071 = "スキャンモジュールを使用して能動技の効果を切り換えることができる。スキャンモジュールには、その戦闘中に呼び出された<color=#00F6FF>雷属性の光霊の一部の召喚物</color>が記録される。\n<color=#00F6FF>特殊なマス</color>：濃色マス、プリズムマス、クロスプリズムマス\n<color=#00F6FF>味方光霊</color>の召喚物：アメモリ、レインハト、バップ、ロイ 、シエル、ナディーン、エイミー",
  str_skill_href_desc_name_30072 = "ヒーリングボール",
  str_skill_href_desc_desc_30072 = "存在ターン数<color=#00F6FF>0/1/2～</color>に応じて、光霊が通過または能動技で吸収した時、アクセリアの攻撃力の<color=#00F6FF>40%/100%/200%</color>相当のHPを回復する",
  str_skill_href_desc_name_30073 = "ヒーリングボール",
  str_skill_href_desc_desc_30073 = "存在ターン数<color=#00F6FF>0/1/2～</color>に応じて、光霊が通過した時、アクセリアの攻撃力の<color=#00F6FF>40%/100%/250%</color>相当のHPを回復する。能動技で吸収する時の回復効果が<color=#00F6FF>80%/180%/400%</color>に増加する。",
  str_skill_href_desc_name_30074 = "浄龍輝",
  str_skill_href_desc_desc_30074 = "<color=#00F6FF>2|3|4</color>段階目の連鎖技発動でそれぞれ対応する「浄龍輝」が点灯する。「浄龍輝」が<color=#00F6FF>3</color>つ点灯すると能動技が発動可能になる。能動技発動後はすべての「浄龍輝」が消灯する",
  str_skill_href_desc_name_30075 = "洞察点",
  str_skill_href_desc_desc_30075 = "火属性のマスを1つ通過するごとに<color=#00F6FF>1</color>獲得する",
  str_skill_href_desc_name_30076 = "洞察点",
  str_skill_href_desc_desc_30076 = "火属性のマスを1つ通過するごとに<color=#00F6FF>1</color>獲得する。戦闘開始時に<color=#00F6FF>5</color>獲得、各ウェーブ開始時に<color=#00F6FF>5</color>獲得する",
  str_skill_href_desc_name_30077 = "洞察点",
  str_skill_href_desc_desc_30077 = "1マス通過するごとに<color=#00F6FF>1</color>獲得する。戦闘開始時に<color=#00F6FF>5</color>獲得、各ウェーブ開始時に<color=#00F6FF>5</color>獲得する",
  str_skill_href_desc_name_30078 = "過熱値",
  str_skill_href_desc_desc_30078 = "通常攻撃のたびに<color=#00F6FF>5</color>獲得。最大<color=#00F6FF>100</color>",
  str_skill_href_desc_name_30079 = "弾薬貯蔵",
  str_skill_href_desc_desc_30079 = "各ターンの開始時に弾薬1発、自身の能動技発動時に弾薬5発を貯蔵できる。どの属性の光霊が能動技を発動しても弾薬1発を貯蔵できる",
  str_skill_href_desc_name_30080 = "クロスプリズムマス",
  str_skill_href_desc_desc_30080 = "連鎖時、クロスプリズムマスの周囲十字方向4マスをクロスプリズムマスと同じ属性に変える",
  str_skill_href_desc_name_30081 = "集結",
  str_skill_href_desc_desc_30081 = "引き寄せが可能なターゲットにのみ有効。先に選択したターゲットが優先的に中央へ移動する",
  str_skill_href_desc_name_30082 = "集合",
  str_skill_href_desc_desc_30082 = "ターゲットの周囲1マスに他のターゲットが存在する",
  str_skill_href_desc_name_30083 = "聖裁",
  str_skill_href_desc_desc_30083 = "最大HPがないターゲットは聖裁値を追加されない",
  str_skill_href_desc_name_30084 = "集合",
  str_skill_href_desc_desc_30084 = "マスの属性のみを並べ替え、その列/行の水属性のマスを選択したマスの周囲に出現させる。マスにいる敵、召喚物、特殊マスの位置は変わらない",
  str_skill_href_desc_name_30085 = "水紋",
  str_skill_href_desc_desc_30085 = "最大99スタック。毎回少なくとも7の倍数分のスタック数を消費する。HP最大時はスタック数を消費しない",
  str_skill_href_desc_name_30086 = "水紋",
  str_skill_href_desc_desc_30086 = "最大99スタック。毎回少なくとも5の倍数分のスタック数を消費する。HP最大時はスタック数を消費しない",
  str_skill_href_desc_name_30087 = "鉄トカゲ",
  str_skill_href_desc_desc_30087 = "鉄トカゲは最大2ターン存在できる。フィールド上に同時に存在できるのは1体のみ",
  str_skill_href_desc_name_30088 = "鉄トカゲ",
  str_skill_href_desc_desc_30088 = "毎ターン、鉄トカゲをタップすると能力を使用できる。鉄トカゲは最大2ターン存在できる。フィールド上に同時に存在できるのは1体のみ",
  str_skill_href_desc_name_30089 = "「リードコール」",
  str_skill_href_desc_desc_30089 = "周囲2マス以内にいる敵を1マス引き寄せ、消滅する",
  str_skill_href_desc_name_30090 = "「フラッドプル」",
  str_skill_href_desc_desc_30090 = "発動ターンバップは連鎖技が鉄トカゲの存在する方向に向きを変え、範囲がフィールドの端まで拡大される",
  str_skill_href_desc_name_30091 = "接触",
  str_skill_href_desc_desc_30091 = "敵の足下に晶鉱が生成された/敵が晶鉱のある位置に移動した時、ダメージを与える。敵の足下に晶鉱が複数回生成される場合も繰り返しダメージを発動する",
  str_skill_href_desc_name_30092 = "位置移動",
  str_skill_href_desc_desc_30092 = "味方の光霊の能動技による瞬間移動、敵スキルによるノックバック/引き寄せ、ワームホールの使用などを含む",
  str_skill_href_desc_name_30093 = "濃色マス",
  str_skill_href_desc_desc_30093 = "このマスに次に出現するマスは、必ず現在の属性と同じになる",
  str_skill_href_desc_name_30094 = "侵食",
  str_skill_href_desc_desc_30094 = "最大40スタック。1スタックにつき、3ターン持続",
  str_skill_href_desc_name_30095 = "機械設計図",
  str_skill_href_desc_desc_30095 = "戦闘開始時、3枚獲得する。その後、各ターン開始時に1枚獲得する。",
  str_skill_href_desc_name_30096 = "影の天賦",
  str_skill_href_desc_desc_30096 = "毎ターン開始時に1Pt、濃色マスを通過するごとに1Pt獲得する",
  str_skill_href_desc_name_30097 = "影の天賦",
  str_skill_href_desc_desc_30097 = "戦闘開始時に5Pt、毎ターン開始時に1Pt、濃色マスを通過するごとに1Pt獲得する",
  str_skill_href_desc_name_30098 = "影の天賦",
  str_skill_href_desc_desc_30098 = "戦闘開始時に5Pt、毎ターン開始時に1Pt、各ウェーブ開始時に2Pt、濃色マスを通過するごとに1Pt獲得する",
  str_skill_href_desc_name_30099 = "影の天賦",
  str_skill_href_desc_desc_30099 = "毎ターン開始時に1Pt、各ウェーブ開始時に2Pt、濃色マスを通過するごとに1Pt獲得する",
  str_skill_href_desc_name_510218 = "投資戦略",
  str_skill_href_desc_desc_510218 = "水属性のマスを5個/濃色マスを1個通過するごとに資本を1Pt獲得する。\n資本が2/5/8Ptに到達したとき、それぞれ能動技、連鎖技、通常攻撃に対応する3組の新しい戦闘能力を順次解放する。毎回、以下の各組の2つの能力から1つを選択して獲得できる。\n絡みつく影蛇：能動技の範囲が菱形13マスに拡大\n駆り立てる霧：能動技のダメージ+50%\n買収工作：連鎖技で最も遠くにいるターゲットに追加攻撃1回。命中回数による減衰をカウントしない\n大一番：濃色マスを1つ通過するごとに、その連鎖中の連鎖技ダメージ+1回\n資本拡張：斜め方向に攻撃できる\n投機攻撃：濃色マスを1つ通過するごとに、その連鎖中の通常攻撃ダメージ+20%、ダメージは最大で2倍",
  str_skill_href_desc_name_513218 = "投資戦略",
  str_skill_href_desc_desc_513218 = "水属性のマスを5個/濃色マスを1個通過するごとに資本を1Pt獲得する。2回目の投資終了後、その後に獲得する投資1Ptにつき、シェオルの攻撃力+1%、最大で40Ptまで換算（覚醒3で解放）\n資本が2/5/8Ptに到達したとき、それぞれ能動技、連鎖技、通常攻撃に対応する3組の新しい戦闘能力を順次解放する。毎回、以下の各組の2つの能力から1つを選択して獲得できる。\n絡みつく影蛇：能動技の範囲が菱形13マスに拡大される\n駆り立てる霧：能動技のダメージ+50%\n買収工作：連鎖技で最も遠くにいるターゲットにダメージ1回の追加攻撃。命中回数による減衰をカウントしない\n大一番：濃色マスを1つ通過するごとに、その連鎖中の連鎖技ダメージ+1回\n資本拡張：斜め方向に攻撃できる\n投機攻撃：濃色マスを1つ通過するごとに、その連鎖中の通常攻撃ダメージ+20%、ダメージは最大で2倍",
  str_skill_href_desc_name_516218 = "投資戦略",
  str_skill_href_desc_desc_516218 = "戦闘開始時に資本を5Pt獲得する。水属性のマスを5個/濃色マスを1個通過するごとに資本を1Pt獲得する。2巡目の投資終了後、その後に獲得する投資1Ptにつき、シェオルの攻撃力+1%、最大で40Ptまで換算（覚醒3で解放）\n資本が2/5/8Ptに到達したとき、それぞれ能動技、連鎖技、通常攻撃に対応する3組の新しい戦闘能力を順次解放する。毎回、以下の各組の2つの能力から1つを選択して獲得できる。\n絡みつく影蛇：能動技の範囲が菱形13マスに拡大される\n駆り立てる霧：能動技のダメージ+50%\n買収工作：連鎖技で最も遠くにいるターゲットにダメージ1回の追加攻撃。命中回数による減衰をカウントしない\n大一番：濃色マスを1つ通過するごとに、その連鎖中の連鎖技ダメージ+1回\n資本拡張：斜め方向に攻撃できる\n投機攻撃：濃色マスを1つ通過するごとに、その連鎖中の通常攻撃ダメージ+20%、ダメージは最大で2倍",
  str_skill_href_desc_name_530218 = "投資戦略",
  str_skill_href_desc_desc_530218 = "水属性のマスを5個/濃色マスを1個通過するごとに資本を1Pt獲得する\n資本が2/5/8Ptに到達したとき、それぞれ能動技、連鎖技、通常攻撃に対応する3組の新しい戦闘能力を順次解放する。毎回、以下の各組の2つの能力から1つを選択して獲得できる。1巡目の終了後、2巡目に1巡目で未獲得の能力を獲得できる。\n絡みつく影蛇：能動技の範囲が菱形13マスに拡大\n駆り立てる霧：能動技のダメージ+50%\n買収工作：連鎖技で最も遠くにいるターゲットに追加攻撃1回。命中回数による減衰をカウントしない\n大一番：濃色マスを1つ通過するごとに、その連鎖中の連鎖技ダメージ+1回\n資本拡張：斜め方向に攻撃できる\n投機攻撃：濃色マスを1つ通過するごとに、その連鎖中の通常攻撃ダメージ+20%、ダメージは最大で2倍",
  str_skill_href_desc_name_533218 = "投資戦略",
  str_skill_href_desc_desc_533218 = "水属性のマスを5個/濃色マスを1個通過するごとに資本を1Pt獲得する。2巡目の投資終了後、その後に獲得する投資1Ptにつき、シェオルの攻撃力+1%、最大で40Ptまで換算\n1巡目の解放終了後、2巡目の投資を続けることができ、1巡目で未獲得の能力を獲得できる。資本が2/5/8Ptに到達したとき、それぞれ能動技、連鎖技、通常攻撃に対応する3組の新しい戦闘能力を順次解放する。毎回、以下の各組の2つの能力から1つを選択して獲得できる。\n絡みつく影蛇：能動技の範囲が菱形13マスに拡大される\n駆り立てる霧：能動技のダメージ+50%\n買収工作：連鎖技で最も遠くにいるターゲットにダメージ1回の追加攻撃。命中回数による減衰をカウントしない\n大一番：濃色マスを1つ通過するごとに、その連鎖中の連鎖技ダメージ+1回\n資本拡張：斜め方向に攻撃できる\n投機攻撃：濃色マスを1つ通過するごとに、その連鎖中の通常攻撃ダメージ+20%、ダメージは最大で2倍",
  str_skill_href_desc_name_536218 = "投資戦略",
  str_skill_href_desc_desc_536218 = "戦闘開始時に資本を5Pt獲得する。水属性のマスを5個/濃色マスを1個通過するごとに資本を1Pt獲得する。2巡目の投資終了後、その後に獲得する投資1Ptにつき、シェオルの攻撃力+1%、最大で40Ptまで換算\n資本が2/5/8Ptに到達したとき、それぞれ能動技、連鎖技、通常攻撃に対応する3組の新しい戦闘能力を順次解放する。毎回、以下の各組の2つの能力から1つを選択して獲得できる。1巡目の終了後、2巡目の投資を続けることができ、1巡目で未獲得の能力を獲得できる。\n絡みつく影蛇：能動技の範囲が菱形13マスに拡大される\n駆り立てる霧：能動技のダメージ+50%\n買収工作：連鎖技で最も遠くにいるターゲットにダメージ1回の追加攻撃。命中回数による減衰をカウントしない\n大一番：濃色マスを1つ通過するごとに、その連鎖中の連鎖技ダメージ+1回\n資本拡張：斜め方向に攻撃できる\n投機攻撃：濃色マスを1つ通過するごとに、その連鎖中の通常攻撃ダメージ+20%、ダメージは最大で2倍",
  str_skill_href_desc_name_30100 = "パレット",
  str_skill_href_desc_desc_30100 = "ゼタは以下の方法でパレットを埋めることができる。色を全て埋めれば、能動技【華麗なる秘技】を発動できる\n1．能動技【ミックス爆撃】で選択したマスがリセットされる時、マスの色が記録される。その色がパレットに入る\n2．能動技【華麗なる秘技】で召喚した「クナン」が攻撃の過程で、通過するマスの色を取る。その色がパレットに入る",
  str_skill_href_desc_name_30110 = "フォールブロック",
  str_skill_href_desc_desc_30110 = "【フォールブロック】の形状は全部で7種類ある。表示されるブロック形状がバティアの能動技の転色範囲となる。\nバティアが能動技を発動するたびに、ブロックの形状がシャッフルされる",
  str_skill_href_desc_name_30111 = "フォールブロック",
  str_skill_href_desc_desc_30111 = "【フォールブロック】の形状は全部で7種類ある。表示されるブロック形状がバティアの能動技の転色範囲となる。\nバティアが能動技を発動するたびに、ブロックの形状がシャッフルされる。\nエネルギーを5消費して【フォールブロック】の形状をシャッフルできる。火属性のマスを通過するとエネルギーを1チャージでき、次に能動技を発動するまで、シャッフルするごとに消費エネルギーが5ずつ増える",
  str_skill_href_desc_name_30112 = "フォールブロック",
  str_skill_href_desc_desc_30112 = "【フォールブロック】の形状は全部で7種類ある。表示されるブロック形状がバティアの能動技の転色範囲となる。\nバティアが能動技を発動するたびに、ブロックの形状がシャッフルされる。\nエネルギーを5消費して【フォールブロック】の形状をシャッフルできる。初期エネルギーは10で、火属性のマスを通過すると1チャージでき、次に能動技を発動するまで、シャッフルするごとに消費エネルギーが5ずつ増える",
  str_skill_href_desc_name_30113 = "フォールブロック",
  str_skill_href_desc_desc_30113 = "【フォールブロック】の形状は全部で7種類ある。表示されるブロック形状がバティアの能動技の転色範囲となる。\nバティアが能動技を発動するたびに、ブロックの形状がシャッフルされる。\nエネルギーを5消費して【フォールブロック】の形状をシャッフルできる。初期エネルギーは10で、火属性のマスを通過すると1チャージできる",
  str_skill_href_desc_name_30114 = "フォールブロック",
  str_skill_href_desc_desc_30114 = "【フォールブロック】の形状は全部で7種類あり、表示中の形状がバティアの能動技の転色範囲となる\nバティアが能動技を発動するたびに、ブロックの形状がシャッフルされる\nまた、エネルギーを5消費して【フォールブロック】の形状をシャッフルできる。火属性のマスを通過するたびにエネルギーを1チャージでき、次に能動技を発動するまで、シャッフルするごとに消費エネルギーが5ずつ増える\n【フォールブロック】の形状をロックできる。ロックした後はブロックの形状がシャッフルしなくなる。ロック状態でシャッフル機能を使用すると、現在のブロックを強化できる。強化するたびに、能動技を発動したとき、追加でその中のランダムな1カ所に濃色マスを生成する",
  str_skill_href_desc_name_30115 = "フォールブロック",
  str_skill_href_desc_desc_30115 = "【フォールブロック】の形状は全部で7種類あり、表示中の形状がバティアの能動技の転色範囲となる\nバティアが能動技を発動するたびに、ブロックの形状がシャッフルされる\nまた、エネルギーを5消費して【フォールブロック】の形状をシャッフルできる。初期エネルギーは10で、火属性のマスを通過するたびにエネルギーを1チャージでき、次に能動技を発動するまで、シャッフルするごとに消費エネルギーが5ずつ増える\n【フォールブロック】の形状をロックできる。ロックした後はブロックの形状がシャッフルしなくなる。ロック状態でシャッフル機能を使用すると、現在のブロックを強化できる。強化するたびに、能動技を発動したとき、追加でその中のランダムな1カ所に濃色マスを生成する",
  str_skill_href_desc_name_30116 = "フォールブロック",
  str_skill_href_desc_desc_30116 = "【フォールブロック】の形状は全部で7種類あり、表示中の形状がバティアの能動技の転色範囲となる\nバティアが能動技を発動するたびに、ブロックの形状がシャッフルされる\nまた、エネルギーを5消費して【フォールブロック】の形状をシャッフルできる。初期エネルギーは10で、火属性のマスを通過するたびにエネルギーを1チャージできる\n【フォールブロック】の形状をロックできる。ロックした後はブロックの形状がシャッフルしなくなる。ロック状態でシャッフル機能を使用すると、現在のブロックを強化できる。強化するたびに、能動技を発動したとき、追加でその中のランダムな1カ所に濃色マスを生成する",
  str_skill_href_desc_name_30117 = "鎮魂の印",
  str_skill_href_desc_desc_30117 = "連鎖技または通常攻撃時に雷を落として敵を攻撃するたびに、1スタック獲得できる",
  str_skill_href_desc_name_30118 = "真主の契約",
  str_skill_href_desc_desc_30118 = "フィールド上で2体以上同時に真主の契約を保有できない",
  str_skill_href_desc_name_30119 = "AP",
  str_skill_href_desc_desc_30119 = " 『ライザのアトリエ２』のコラボキャラはAPポイントを共有しており、各キャラクターは毎ターン最大1回能動技を発動する。キャラクターが能動技を発動しなかったターンは、ターン終了時にポイントを10獲得する",
  str_skill_href_desc_name_30120 = "AP",
  str_skill_href_desc_desc_30120 = " 『ライザのアトリエ２』のコラボキャラはAPポイントを共有しており、各キャラクターは毎ターン最大1回能動技を発動する。ポイントは戦闘開始時に20獲得し、キャラクターが能動技を発動しなかったターンは、ターン終了時にポイントを10獲得する",
  str_skill_href_desc_name_30121 = "AP",
  str_skill_href_desc_desc_30121 = " 『ライザのアトリエ２』のコラボキャラはAPポイントを共有しており、各キャラクターは毎ターン最大1回能動技を発動する。ポイントは戦闘開始時に20獲得し、毎ターン終了時にポイントを10獲得する",
  str_skill_href_desc_name_30122 = "戦術システム",
  str_skill_href_desc_desc_30122 = "戦闘中は行動に応じて戦術値を獲得でき、戦術値が指定値に達すると対応する効果を獲得する\n戦術値10-Level1： 『ライザのアトリエ２』コラボキャラの連鎖技最終ダメージ+15%\n戦術値40-Level2：毎ターン開始時にランダムな位置に濃色マスを1つ生成する\n戦術値70-Level3：ライザ、パトリツィアの連鎖技が敵に命中した後、火傷を1スタック付与する。クラウディアの連鎖技が敵に命中した後、毒を1スタック付与する\n戦術値100-Level4： 『ライザのアトリエ２』コラボキャラの能動技最終ダメージ+50%\n戦術値130-Level5：毎ターン開始時にランダムな位置に濃色マスを1つ生成する",
  str_skill_href_desc_name_30123 = "戦術システム",
  str_skill_href_desc_desc_30123 = "戦闘中は行動に応じて戦術値を獲得でき、戦術値が指定値に達すると対応する効果を獲得する。初期状態での最大レベルは5。戦闘開始後、戦術システムの最大レベル+1\n戦術値10-Level1： 『ライザのアトリエ２』コラボキャラの連鎖技最終ダメージ+15%\n戦術値40-Level2：毎ターン開始時にランダムな位置に濃色マスを1つ生成する\n戦術値70-Level3：ライザ、パトリツィアの連鎖技が敵に命中した後、火傷を1スタック付与する。クラウディアの連鎖技が敵に命中した後、毒を1スタック付与する\n戦術値100-Level4： 『ライザのアトリエ２』コラボキャラの能動技最終ダメージ+50%\n戦術値130-Level5：毎ターン開始時にランダムな位置に濃色マスを1つ生成する\n戦術値160-Level6： 『ライザのアトリエ２』コラボキャラの基礎攻撃力+10%\n戦術値200-Level7：毎ターン開始時にランダムな位置に濃色マスを1つ生成する",
  str_skill_href_desc_name_30124 = "吸収",
  str_skill_href_desc_desc_30124 = "該当する光霊の技効果（マス通過による発動と同じ効果）をもたらす",
  str_skill_href_desc_name_30125 = "フォース",
  str_skill_href_desc_desc_30125 = "チームが2マス連鎖するごとに、フォースを1獲得する",
  str_skill_href_desc_name_30126 = "フォース",
  str_skill_href_desc_desc_30126 = "チームが2マス連鎖するごとに、フォースを1獲得する。毎ターン開始時にフォースを5獲得する",
  str_skill_href_desc_name_30127 = "連鎖操作",
  str_skill_href_desc_desc_30127 = "マスの色を無視して連鎖する。1マス連鎖するごとにフォースを1消費",
  str_skill_href_desc_name_30128 = "離脱状態",
  str_skill_href_desc_desc_30128 = "チーム離脱中、祭剣座は隊長になれず、チームの連鎖攻撃にも参加できない",
