  str_skill_name_590028106 = "チャージI",
  str_skill_desc_590028106 = "召喚師はその場でエネルギーをチャージし、広範囲攻撃発動の準備をする。星標の数が多いほど、攻撃の範囲が広がる。",
  str_skill_name_590028107 = "チャージII",
  str_skill_desc_590028107 = "召喚師はターゲットの付近に瞬間移動してエネルギーをチャージし、広範囲攻撃発動の準備をする。星標の数が多いほど、攻撃の範囲が広がる。",
  str_skill_name_590028108 = "沈黙",
