  str_skill_desc_510002 = "硬い頭部を使い攻撃範囲内にいるターゲットに突進攻撃をする",
  str_skill_desc_510003 = "拳を振り回して攻撃範囲内にいるターゲットに叩きつける",
  str_skill_desc_511003 = "拳を振り回して攻撃範囲内にいるターゲットに叩きつけ、次のターンで周囲の敵にダメージを与えて眩暈状態にする",
  str_skill_desc_510004 = "攻撃範囲の同じ行または同じ列にいるターゲットに遠距離攻撃を行う",
  str_skill_desc_510005 = "牙で攻撃範囲内にいるターゲットに噛み付く",
