  str_skill_desc_29203121 = "アグアンがブレードを手にして攻撃範囲内にいるターゲットを2回攻撃し、出血状態を付与する",
  str_skill_desc_29203123 = "アグアンがブレードを手にして攻撃範囲内にいるターゲットを2回攻撃し、出血と疲労状態を付与する",
  str_skill_desc_510011 = "クロバコが特製の兵刃を使って攻撃範囲内のターゲットを攻撃する",
  str_skill_desc_510012 = "バリアを展開し、攻撃を3回防ぐ。",
  str_skill_desc_510013 = "レーザーを使って1マス離れたターゲットを攻撃する",
  str_skill_desc_510014 = "攻撃範囲内のターゲットを攻撃し、攻撃後シーン内の任意の位置へ瞬間移動する",
  str_skill_desc_510015 = "ランスを使って攻撃範囲内にいるターゲットを攻撃する",
  str_skill_desc_510016 = "大盾を使って攻撃範囲内にいるターゲットを攻撃する",
  str_skill_desc_510017 = "銃器を使って攻撃範囲の同じ行または同じ列にいるターゲットに遠距離攻撃を行う",
  str_skill_desc_510018 = "周囲4方向の目の前の1マスにダメージを1回与え、命中したターゲットを1マスノックバックさせる",
  str_skill_desc_510019 = "前方の広範囲にダメージを与える",
  str_skill_desc_510020 = "範囲内のユニットにダメージを与える",
  str_skill_desc_510021 = "前方3列の範囲にダメージを与え、命中したターゲットをノックバックさせる",
  str_skill_desc_510022 = "暗力の盾を召喚して身を守り、暗力1スタックにつきダメージを1回無効にできる",
  str_skill_desc_510023 = "範囲内のターゲットに火炎ダメージを与える",
  str_skill_desc_510024 = "砲弾を発射して、直線上にいるターゲットをノックバックさせる",
  str_skill_desc_510025 = "コントローラーに触れると、攻城塔が向いている方向に矢を1本放ち、命中したターゲットにダメージを与える",
  str_skill_desc_510026 = "フェニィがエネルギーを使って、攻撃範囲内のターゲットに遠距離攻撃を行う",
  str_skill_desc_510027 = "フェニィがエネルギーを使って、フェネクスのHPを回復させる",
  str_skill_desc_510028 = "フェネクスが守御を振り回し、攻撃範囲内のターゲットを攻撃する",
  str_skill_desc_510029 = "フェネクスが守御にエネルギーを注入して地面を叩き、範囲内のターゲットにダメージを与えて眩暈状態にする",
  str_skill_desc_510030 = "バーサーカーが両拳を振り回して激しく地面を叩き、範囲内のターゲットにダメージを与えて眩暈状態にする",
  str_skill_desc_510031 = "2ターンごとに自身の周囲1マスのターゲットに1回ダメージを与える",
  str_skill_desc_510032 = "通過したマスにトゲトゲを設置し、通り過ぎるターゲットにダメージを与える",
  str_skill_desc_510033 = "範囲内のターゲットにダメージを与え、命中したターゲットをノックバックする",
  str_skill_desc_510034 = "範囲内のターゲットを1回攻撃する",
  str_skill_desc_510035 = "ボアドムが力を凝縮して十字の広範囲への火属性攻撃発動の準備をし、命中したターゲットにダメージを与え、火傷効果を付与する。力の凝縮中は中断されない。",
  str_skill_desc_510036 = "ボアドムが周囲1マス内の自身と同属性のマスのエネルギーを吸収し、範囲内のターゲットに攻撃する（吸収したマスが多いほど、ダメージも大きくなる）。攻撃が命中すると火傷状態を付与する。",
  str_skill_desc_510037 = "ボアドムが力を凝縮して十字の広範囲への雷属性攻撃発動の準備をし、命中したターゲットにダメージを与え、麻痺効果を付与する。力の凝縮中は中断されない。",
  str_skill_desc_510038 = "ボアドムが周囲1マス内の自身と同属性のマスのエネルギーを吸収し、範囲内のターゲットに攻撃する（吸収したマスが多いほど、ダメージも大きくなる）。攻撃が命中すると麻痺状態を付与する。",
  str_skill_desc_500039 = "スイェートが太い尾で攻撃範囲内にいるターゲットを攻撃し、ダメージを2回与える",
  str_skill_desc_500040 = "シャイアが尾に集めたエネルギーニードルで攻撃範囲内にいるターゲットに遠距離攻撃を行い、ダメージを2回与える",
  str_skill_desc_510039 = "スイェートが太い尾で攻撃範囲内にいるターゲットを攻撃する",
  str_skill_desc_510040 = "シャイアが尾に集めたエネルギーニードルで攻撃範囲内のターゲットに遠距離攻撃を行う",
  str_skill_desc_510041 = "コントローラーに触れると攻城塔が向いている方向に毒矢を1本放ち、命中したターゲットにダメージを与えると同時に毒状態を付与する",
  str_skill_desc_510042 = "コントローラーに触れると攻城塔が向いている方向に麻痺矢を1本放つ。命中した光霊は移動を中断し、次のターンでも1マスしか移動できなくなる",
  str_skill_desc_510043 = "殲星爆弾が保管される装置。常に殲星爆弾庫を1つ搭載している。",
  str_skill_desc_510044 = "タブハッドは鋭い爪を振り回して攻撃範囲内のターゲットにダメージを与える。",
  str_skill_desc_510045 = "すべてのターゲットにダメージを1回与える。",
  str_skill_desc_510046 = "ユニメートが作った不思議なアイテム。置かれたマスを通過すると発動する。全光霊にユニメートの10%の攻撃力を追加する",
  str_skill_desc_510047 = "ユニメートが作った不思議なアイテム。置かれたマスを通過すると発動する。チームにユニメートの10%の防御力を追加する",
  str_skill_desc_80001 = "ユニメートが落雷の結晶を真似して作った模倣品。置かれたマスを通過すると発動する。発動すると、稲妻を召喚して全ての敵ターゲットにユニメートの50%のダメージを与える",
  str_skill_desc_80002 = "ユニメートが隕石の結晶を真似して作った模倣品。置かれたマスを通過すると発動する。発動すると、隕石を召喚してHPが最も高い敵ターゲットにユニメートの100%のダメージを与える",
  str_skill_desc_80003 = "ユニメートが作った不思議なアイテム。置かれたマスを通過すると発動する。全光霊がユニメートの攻撃力の100%のHPを回復する",
  str_skill_desc_510048 = "最大HP20%分回復する",
  str_skill_desc_5100482 = "最大HP10%分回復する",
  str_skill_desc_510049 = "出撃中の光霊のスキルターン数-1",
  str_skill_desc_510050 = "ノックバックできる。その最中にターゲットまたは障害物に当たると強烈な爆発を起こし、周囲1マスに範囲ダメージを与える",
  str_skill_desc_510051 = "戦闘エリアに置かれた非常に硬い石。破壊することはできない。遠距離弾道攻撃を防げる。",
  str_skill_desc_510052 = "普通の岩石。範囲攻撃技で粉砕できる",
  str_skill_desc_510053 = "宝箱を開けるためのスイッチ。3つある装置を踏むと中央にある宝箱を開けることができる。",
  str_skill_desc_510054 = "旧首都に保管されている物資が大量に入った宝箱。周囲にある3つのコントロールスイッチを踏むと開けられ、大量の物資を獲得できる。",
  str_skill_desc_500216 = "ボリングが次のターンでチャージ状態になる。チャージ状態の時に殲星爆弾が暗鬼の中央に命中するとボリングは麻痺状態になる。1ターン持続",
  str_skill_desc_510216 = "ボリングは殲星爆弾を放った後チャージ状態になる。チャージ状態の時に殲星爆弾が暗鬼の中央に命中するとボリングは麻痺状態になる。1ターン持続",
  str_skill_desc_500217 = "ボリングがフィールドの2×2エリア6か所に飛散爆弾を放ち、ターゲットを攻撃する（殲星爆弾が中央部分に命中すると、ボリングは麻痺状態になる）",
  str_skill_desc_500218 = "ボリングが蓄積したエネルギーを放ち、敵全体にダメージを与え、ノックバックする",
  str_skill_name_510219 = "錯乱",
  str_skill_desc_510219 = "範囲内のターゲットを1回攻撃する。さらに全ての光霊の能動技CDターン数+1",
  str_skill_name_510220 = "躍撃",
  str_skill_desc_510220 = "ジャンプして範囲内のターゲットを1回攻撃する",
  str_skill_name_510221 = "光力封印",
  str_skill_desc_510221 = "光力を封印し、周囲1マス以内のマスをロックする。ロックされたマスは転色できない",
  str_skill_name_510222 = "狙撃",
  str_skill_desc_510222 = "範囲内のターゲットに1回遠距離攻撃をする。ターゲットが遠くにいるほど、与えるダメージが大きくなる",
  str_skill_name_510223 = "シャープクロー",
  str_skill_desc_510223 = "範囲内のターゲットを1回攻撃する",
  str_skill_name_510224 = "剛力",
  str_skill_desc_510224 = "範囲内のターゲットにダメージを与え、範囲内の全てのマスを粉砕する",
  str_skill_name_510225 = "怨念",
  str_skill_desc_510225 = "範囲内のターゲットにダメージを与える。ターゲットに命中すると、自身の属性と同じ光霊（隊長以外）を呪う。呪われた光霊は攻撃不能になり、能動技が使用不能になる。カースが撃破されると、同じ属性の光霊に与えた呪いの効果が除去される",
  str_skill_name_510226 = "魂火",
  str_skill_desc_510226 = "範囲内のターゲットに1回遠距離攻撃をする",
  str_skill_name_510227 = "囚われの接触",
  str_skill_desc_510227 = "ターゲットに突撃し、自分の周囲まで弾き飛ばす。さらに自分のいる位置から周囲2マス以内のマスの属性を変える",
  str_skill_name_510228 = "震動の光",
  str_skill_desc_510228 = "範囲内のターゲットに大ダメージを与える",
  str_skill_name_510229 = "静謐の日差し",
  str_skill_desc_510229 = "範囲内のターゲットに比較的大きなダメージを与える。ターゲットに命中した場合、そのターゲットの周囲1マス以内のマスの属性を変える",
  str_skill_name_1001811 = "ムーンリング",
  str_skill_desc_1001811 = "タルタロスがムーンリングと化し、範囲内のターゲットにダメージを与える。さらに攻撃範囲の中間エリアのマスをロックする",
  str_skill_name_1001821 = "ムーンキャップ",
  str_skill_desc_1001821 = "タルタロスがエネルギーを放ち、縦横4列の範囲にダメージを与える。さらに攻撃範囲内のランダムの8マスをロックする",
  str_skill_name_1001831 = "ムーンインパルス",
  str_skill_desc_1001831 = "タルタロスがムーンリングとなり、範囲内のターゲットにダメージを与え、フィールドの反対側に移動する。移動後、自身の周囲2マスをロックする。ロックされたマスは転色されない。",
  str_skill_name_1002111 = "クラッシュ",
  str_skill_desc_1002111 = "範囲内のターゲットにダメージを与える。ターゲットに命中すると、そのターゲットを端までノックバックする",
  str_skill_name_1002121 = "ウィンドインパルス",
  str_skill_desc_1002121 = "自身の周囲2マス内にいるターゲットに大ダメージを与え、かつノックバックする。同時に攻撃範囲内の全てのマスを粉砕する",
  str_skill_name_1002131 = "パワーサージ",
  str_skill_desc_1002131 = "縦横4列の範囲にダメージを与え、ターゲットに命中すると、そのターゲットを端までノックバックする",
  str_skill_name_1002211 = "落雷の神符（強化）",
  str_skill_desc_1002211 = "大量の雷を落とし範囲内のターゲットにダメージを与える",
  str_skill_name_1002221 = "シャープネス",
  str_skill_desc_1002221 = "移動後、自身を起点として十字形の最大範囲内にいるターゲットにダメージを与える",
  str_skill_name_1002231 = "巨像・唸る音波",
  str_skill_desc_1002231 = "スーモアは巨像をコントロールして音波攻撃を繰り出し、全域のターゲットを攻撃する。",
  str_skill_name_1002251 = "魔物召喚",
  str_skill_desc_1002251 = "スーモアが移動後にターゲットを端までノックバックし、付近に魔物を召喚する。召喚された魔物は自身の周囲2マスの範囲内のターゲットにダメージを与える",
  str_skill_name_1002261 = "エネルギー暴走",
  str_skill_desc_1002261 = "スーモアが強烈なエネルギーを放ち、全域のターゲットを攻撃する。スーモアとの距離が離れているほど、ターゲットの被ダメージが大きくなる",
  str_skill_name_1002271 = "スプリント",
  str_skill_desc_1002271 = "スーモアがターゲットから離れ、攻撃エリアにスプリントを放って範囲内のターゲットにダメージを与える",
  str_skill_name_29002421 = "燃焼",
  str_skill_desc_29002421 = "前方5列の範囲内のターゲットにダメージを与える",
  str_skill_name_29002422 = "烈火の大地",
  str_skill_desc_29002422 = "火炎を放って全範囲にダメージを与え、さらに戦場の端から4行の範囲内のターゲットに比較的大きな追加ダメージを1回与える",
  str_skill_name_29002423 = "プローバノス召喚",
  str_skill_desc_29002423 = "プローバノス2体を戦場に召喚する",
  str_skill_name_1002603 = "エネルギーパルス",
  str_skill_desc_1002603 = "エネルギーを凝縮して目の前のターゲットを攻撃、命中したターゲットをノックバックする",
  str_skill_name_1002604 = "反射バリア",
  str_skill_desc_1002604 = "バリアを展開し、自分の被ダメージを減少する。バリアが存在している間は被ダメージの一部をターゲットに跳ね返す",
  str_skill_name_1002605 = "スタティックリペア",
  str_skill_desc_1002605 = "T1024はその場にとどまって損傷部位を修復し、自分のHPを一定量回復する",
  str_skill_name_1004501 = "禁固",
  str_skill_desc_1004501 = "範囲内のターゲットにダメージを与える。ターゲットに命中すると、周囲1マス以内のマスをロックする。ロックされたマスは転色できない",
  str_skill_name_1002702 = "ダイナミックリペア",
  str_skill_desc_1002702 = "攻撃範囲の同じ行または同じ列にいるターゲットに遠距離攻撃を行う",
  str_skill_name_1000901 = "様子見",
  str_skill_desc_1000901 = "ターゲットとの距離の遠近にもとづいて行動を決定する。ターゲットとの距離が近い場合はそのターゲットに大ダメージを与え、ターゲットとの距離が離れている場合はそのターゲットを自分の近くに引き寄せる",
  str_skill_name_1000911 = "様子見",
  str_skill_desc_1000911 = "ターゲットとの距離にもとづいて行動を決定する。ターゲットとの距離が近い場合はそのターゲットに大ダメージを与え、ターゲットとの距離が離れている場合はそのターゲットを自分の近くに引き寄せ、その後自身の周囲1マスの範囲にトゲトゲを召喚する",
  str_skill_name_1000921 = "応変",
  str_skill_desc_1000921 = "ターゲットとの距離に応じて行動パターンを変化させ、側にトゲトゲを配置する。ターゲットとの距離が近い場合、ターゲットに大きなダメージを与え、ターゲットとの距離が遠い場合、ターゲットを自身の近くに引き寄せる",
  str_skill_name_1000931 = "応変",
  str_skill_desc_1000931 = "ターゲットとの距離に応じて行動パターンを変化させ、側にトゲトゲを配置する。ターゲットとの距離が近い場合、ターゲットに大きなダメージを与え、ターゲットとの距離が遠い場合、ターゲットを自身の近くに引き寄せる",
  str_skill_name_1001001 = "エネルギー強奪",
  str_skill_desc_1001001 = "能動技クールダウンターン数が最も少ない光霊のエネルギーを奪う。その光霊の能動技クールダウンターン数+3",
  str_skill_name_1001611 = "乱・孤島",
  str_skill_desc_1001611 = "範囲内のターゲットを自分の周囲まで突進させ、自分のいる位置と周囲2マスの属性を変える",
  str_skill_name_1001621 = "乱・爆発",
  str_skill_desc_1001621 = "範囲内のターゲットに比較的大きなダメージを与える。ターゲットに命中した場合、そのターゲットの周囲1マスの属性を変える",
  str_skill_name_1001631 = "乱・灰燼",
  str_skill_desc_1001631 = "戦場のランダムな7ヵ所に2×2の範囲ダメージを与える。ターゲットに命中した場合、そのターゲットのいる位置の周囲1マスの属性を変える",
  str_skill_name_1001711 = "スペクター・爆破",
  str_skill_desc_1001711 = "周囲2マスの範囲内にいるターゲットにダメージを与える。そのターゲットによる攻撃が命中した場合、チーム内の全光霊の能動技CDターン数+2",
  str_skill_name_1001721 = "スペクター・余波",
  str_skill_desc_1001721 = "十字方向の最大範囲にダメージを与える。そのターゲットによる攻撃が命中した場合、チーム内の全光霊の能動技CDターン数+2",
  str_skill_name_1001741 = "滅・追撃",
  str_skill_desc_1001741 = "範囲内のターゲットにダメージを与える。そのターゲットによる攻撃が命中した場合、チーム内の全光霊の能動技CDターン数+1",
  str_skill_name_1001751 = "滅・余韻",
  str_skill_desc_1001751 = "十字方向の最大範囲にダメージを与える。そのターゲットによる攻撃が命中した場合、チーム内の全光霊の能動技CDターン数+1",
  str_skill_name_1001771 = "追撃",
  str_skill_desc_1001771 = "十字方向の最大範囲にダメージを与える。そのターゲットによる攻撃が命中した場合、能動技のCDターン数が最も少ない光霊のCDターン数+3",
  str_skill_name_1001781 = "エネルギー強奪",
  str_skill_desc_1001781 = "範囲内のターゲットにダメージを与える。そのターゲットによる攻撃が命中した場合、能動技のCDターン数が最も少ない光霊のCDターン数+3",
  str_skill_name_500411 = "エネルギー供給",
  str_skill_desc_500411 = "ビーコンがその場に留まり、エネルギーリンク経由で召喚師にダメージ軽減効果を与える",
  str_skill_name_500244 = "落雷の結晶",
  str_skill_desc_500244 = "神秘的な光の結晶で、これがあるマスを通過する時に発動可能。発動すると雷電を召喚し、すべての敵ターゲットを攻撃する。",
  str_skill_name_500245 = "隕石の結晶",
  str_skill_desc_500245 = "神秘的な光の結晶で、これがあるマスを通過する時に発動可能。発動すると隕石を召喚して、HPが最も高い敵ターゲットを攻撃する。",
  str_skill_name_500170 = "鎌攻撃",
  str_skill_desc_500170 = "ゴーストが属性攻撃を1回行う",
  str_skill_name_500171 = "鎌攻撃+",
  str_skill_desc_500171 = "狂暴なゴーストが属性攻撃を2回行い、ダメージが大きく増幅する",
  str_skill_name_500172 = "重なる災難",
  str_skill_desc_500172 = "ゴーストが十字範囲に属性ダメージを与える",
  str_skill_name_500173 = "重なる災難+",
  str_skill_desc_500173 = "狂暴なゴーストがすべてのマスに属性ダメージを与える",
  str_skill_name_500174 = "幻影サポート",
  str_skill_desc_500174 = "幻影を1つ召喚してゴースト本体に加勢する。戦場に既に幻影が存在している場合は、既存の幻影を呼び戻してから新たな幻影を召喚する。",
  str_skill_name_500227 = "サーチ",
  str_skill_desc_500227 = "摂魂輪が自身の属性と同じマスの近くに移動し、マスの属性エネルギーを吸収する態勢に入る",
  str_skill_name_500228 = "エネルギー溜め",
  str_skill_desc_500228 = "摂魂輪が自身及び周囲1マス内の同属性のマスのエネルギーを吸収し、エネルギーボールを放って敵全体を攻撃する。吸収したマスが多いほどダメージは大きくなる",
  str_skill_desc_520228 = "摂魂輪が現在地及び周囲1マス内の同属性のマスのエネルギーを吸収する。さらに、範囲内の火属性のマスを粉砕し、その後エネルギー弾を放って敵全体を攻撃する。吸収したマスが多いほどダメージは大きくなる",
  str_skill_name_501001 = "幻雷",
  str_skill_desc_501001 = "鳴灼はフィールド内のランダムなエリアに雷電を召喚し、ターゲットに属性ダメージを与えて麻痺状態にする。",
  str_skill_name_501003 = "火雨",
  str_skill_desc_501003 = "鳴灼はフィールド内のランダムな位置に火雨を召喚し、ターゲットに属性ダメージを与えて火傷状態にする。",
  str_skill_name_501011 = "遠距離攻撃",
  str_skill_desc_501011 = "暗影は周囲2マスの十字方向の最大範囲に衝撃波を放ち、範囲内のターゲットにダメージを与える",
  str_skill_name_501015 = "鼓舞",
  str_skill_desc_501015 = "暗影は味方ユニットが最も多いエリアに移動し、周囲12マスの味方に強勢の印を付与する。印を得た味方は攻撃力がアップする。",
  str_skill_name_501021 = "頭突き",
  str_skill_desc_501021 = "崩蟻が硬い頭部を使用して範囲内のターゲットにダメージを与える。HPが比較的低い場合、不安定状態になり、プレイヤーの方向に移動して自爆する",
  str_skill_name_501025 = "焼尽",
  str_skill_desc_501025 = "崩蟻が最後の命を燃やし、移動後に自爆して周囲1マス以内のターゲットにダメージを与える",
  str_skill_name_501031 = "汚染",
  str_skill_desc_501031 = "範囲内のターゲットを汚染で攻撃する。弥染には強力な属性耐性があり、相性のいい属性に対してさらに大きなダメージを与えられる",
  str_skill_name_501032 = "汚染",
  str_skill_desc_501032 = "範囲内のターゲットを攻撃し、移動ルート上のマスを自身と同じ属性に変える",
  str_skill_name_501042 = "咆吼",
  str_skill_desc_501042 = "グスドの従者が自身の周囲2マス範囲内にいるターゲットに破裂の印を付与する。印1スタックにつき、ターゲットの防御力が一定程度減少し、印のスタック数が多いほど防御力が下がる",
  str_skill_name_501052 = "巨像・鋒鋭",
  str_skill_desc_501052 = "スーモアが十字範囲内のターゲットにダメージを与える。",
  str_skill_name_501053 = "雷電の力",
  str_skill_desc_501053 = "スーモアが雷を起こしてランダムで複数のエリアにダメージを与える。",
  str_skill_name_501054 = "巨像・唸る音波",
  str_skill_desc_501054 = "スーモアは巨像をコントロールして音波攻撃を繰り出し、全域のターゲットを攻撃する。",
  str_skill_name_501056 = "巨像・触手",
  str_skill_desc_501056 = "スーモアは巨像をコントロールして前方の広範囲にダメージを与える。",
  str_skill_name_501057 = "巨像・唸る音波",
  str_skill_desc_501057 = "スーモアは巨像をコントロールして全域に攻撃を行うと同時に、ランダムな位置に落雷の結晶を召喚する。光霊が落雷の結晶を通過すると結晶は消える。",
  str_skill_name_501058 = "落雷の神符召喚",
  str_skill_desc_501058 = "スーモアはランダムな位置に落雷の結晶を設置する。落雷の結晶が踏まれなければ、次のターンでスーモアがその位置に雷を呼び出し、ダメージを与える。",
  str_skill_name_501059 = "雷鳴の音",
  str_skill_desc_501059 = "スーモアは落雷の結晶に向けて雷を呼び出し大ダメージを与えると同時に、命中したターゲットに麻痺状態を付与する。光霊が落雷の結晶を通過すると結晶は消える。",
  str_skill_name_501061 = "領域",
  str_skill_desc_501061 = "スーモアが攻撃範囲内のターゲットに遠距離攻撃を繰り出す。",
  str_skill_name_501062 = "震爆",
  str_skill_desc_501062 = "スーモアが範囲内のターゲットに震動攻撃を繰り出し、大ダメージを与える。",
  str_skill_name_501063 = "同期の境地",
  str_skill_desc_501063 = "スーモアがHP同期を行う。残りHPが最も高いスーモアを基準とし、他のすべてのスーモアのHPをこれに同期させる。自身のHPを最大で30%回復させる",
  str_skill_desc_511063 = "スーモアがHP同期を行う。残りHPが最も高いスーモアを基準とし、他のすべてのスーモアのHPをこれに同期させる。戦場に他のスーモアがいない場合、自身の最大HPの20%を回復する",
  str_skill_name_501082 = "従者覚醒",
  str_skill_desc_501082 = "グスドがランダム位置に、移動できないグスドの従者を2体召喚する。",
  str_skill_name_501083 = "裂地",
  str_skill_desc_501083 = "グスドが範囲内のターゲットに攻撃を加え、破裂の印を1スタック付与する。印のスタック数が多いほどターゲットの防御力が下がる",
  str_skill_name_501084 = "咆吼",
  str_skill_desc_501084 = "グスドが咆吼し、範囲内の敵ターゲットに破裂の印を2スタック付与する。印スタック数が多いほどターゲットの防御力が下がる",
  str_skill_name_501085 = "起爆",
  str_skill_desc_501085 = "グスドがターゲットの破裂の印を爆破させ、そのターゲットに大ダメージを与える。印のスタック数が多いほどダメージが大きくなる",
  str_skill_name_501087 = "従者覚醒強化",
  str_skill_desc_501087 = "グスドがランダムなエリアに従者を3体召喚する。従者は移動できない。",
  str_skill_name_501088 = "強化裂地",
  str_skill_desc_501088 = "グスドが範囲内のターゲットに2回猛攻撃を加え、破裂の印を2スタック付与する。スタック数が多いほどターゲットの防御力が下がる",
  str_skill_name_501089 = "咆吼強化",
  str_skill_desc_501089 = "グスドが死に際の咆吼とともに範囲内のターゲットに破裂の印を3スタック付与する。スタック数が多いほどターゲットの防御力が下がる",
  str_skill_name_501092 = "引き裂く闇",
  str_skill_desc_501092 = "マクガフィンは前方の空間を歪めて切り裂き、攻撃範囲内のターゲットにダメージを与える。",
  str_skill_name_501093 = "輪廻の使者",
  str_skill_desc_501093 = "マクガフィンは白夜と満潮の到来に備えてエネルギーを蓄積する。",
  str_skill_name_501095 = "白夜と満潮",
  str_skill_desc_501095 = "マクガフィンが戦場の固定エリアに集中爆撃を行う。",
  str_skill_name_501192 = "引き裂く闇",
  str_skill_desc_501192 = "マクガフィモが前方の空間を歪めて切り裂き、攻撃範囲内のターゲットにダメージを与える",
  str_skill_name_501193 = "輪廻の使者",
  str_skill_desc_501193 = "マクガフィモが白夜と満潮の到来に備えてエネルギーを蓄積する",
  str_skill_name_501195 = "白夜と満潮",
  str_skill_desc_501195 = "マクガフィンが戦場の固定エリアに集中爆撃を行う",
  str_skill_name_501102 = "地潜り",
  str_skill_desc_501102 = "マラゾール",
  str_skill_name_501103 = "砂炎",
  str_skill_desc_501103 = "火を噴いて範囲内のターゲットにダメージを与える",
  str_skill_name_501104 = "召喚",
  str_skill_desc_501104 = "マラゾールが崩蟻3匹を戦場に召喚する。",
  str_skill_desc_580043104 = "マラゾールが戦場に爆裂を3体召喚する",
  str_skill_name_501113 = "石割り",
  str_skill_desc_501113 = "黒蹄角が範囲内のターゲットを攻撃してノックバックさせる。",
  str_skill_name_501114 = "水晶召喚",
  str_skill_desc_501114 = "黒蹄角がランダムな位置に増殖水晶を2個召喚する。",
  str_skill_name_501115 = "地裂斬",
  str_skill_desc_501115 = "黒蹄角が範囲内のターゲットを攻撃してノックバックさせる。ターゲットがノックバックされたら、その前に追加で元素岩石を1つ生成する。",
  str_skill_name_501116 = "岩落とし",
  str_skill_desc_501116 = "黒蹄角がすべての元素岩石を集中させてターゲットにダメージを与える。元素岩石の数が多いほどダメージが大きくなる。",
  str_skill_name_501141 = "岩石召喚",
  str_skill_desc_501141 = "増殖水晶",
  str_skill_name_515002 = "蔓延",
  str_skill_desc_515002 = "チェンジはターゲットの方向へ幅2マスの衝撃波を1発放ち、命中したターゲットにダメージを与える。",
  str_skill_name_515003 = "チェンジの罠",
  str_skill_desc_515003 = "チェンジは範囲内のターゲットにダメージを与えて引き寄せる。ターゲットを攻撃するしないにかかわらず、自身の周囲2マスをリセットする。",
  str_skill_name_534001 = "脱出経路",
  str_skill_name_510244 = "審判突撃",
  str_skill_desc_510244 = "タブハッドはサイドに瞬間移動し、ターゲットの位置へ突撃する態勢に入る。",
  str_skill_desc_534001 = "逃げるのが大得意な盗掘者たちは、いつも追跡者の手から逃れようとしている。",
  str_skill_name_500638 = "地炎",
  str_skill_desc_500638 = "マクガフィンは地面を切り裂き、地炎を放って範囲内のターゲットにダメージを与える。さらに狂犬を2体召喚する",
  str_skill_desc_5006381 = "マクガフィンは地面を切り裂き、地炎を放って範囲内のターゲットにダメージを与える",
  str_skill_name_500639 = "壊滅",
  str_skill_desc_500639 = "マクガフィンは凝集した力を噴き出し、前方3列の範囲のターゲットにダメージを与える。",
  str_skill_name_500640 = "炎の息",
  str_skill_desc_500640 = "マクガフィンが羽ばたいて青い炎を放ち、敵全体にダメージを与える",
  str_skill_desc_5006401 = "マクガフィンが羽ばたいて青い炎を放ち、敵全体にダメージを与えるとともに自身に被ダメージ無効のバリアを展開する",
  str_skill_desc_49005111 = "マクガフィンが羽ばたいて青い炎を放ち、敵全体にダメージを与える。さらに3マスノックバックし、その後一定の位置にシャドウマンを召喚する",
  str_skill_name_505106 = "背襲",
  str_skill_desc_505106 = "ミラーが光の壁から飛び出して、ターゲットにダメージを与える。さらにターゲットのいる縦または横の列のマスの属性をリセットする",
  str_skill_name_505109 = "黒潮",
  str_skill_desc_505109 = "ミラーが移動し、範囲内のターゲットに遠距離攻撃を行う。さらに毎ターン幻影1体を戦場の端に召喚する",
  str_skill_name_504901 = "影撃",
  str_skill_desc_504901 = "幻影が攻撃範囲内のターゲットにダメージを与える",
  str_skill_name_505121 = "光の壁",
  str_skill_desc_505121 = "ミラーが変化したもの。ミラーは敵から最も遠い光の壁の中に隠れている（その光の壁は攻撃可能）。光の壁が破壊されると、幻影を召喚して敵を攻撃する。光の壁を2つ破壊すると全ての光の壁が消え、ミラーの本体が現れる",
  str_skill_name_500251 = "変幻の嵐",
  str_skill_desc_500251 = "ウェンディの羽を使い、味方のキャラを羽のある場所にワープさせる",
  str_skill_name_500252 = "銃剣",
  str_skill_desc_500252 = "範囲内のターゲットを1回攻撃する",
  str_skill_name_1002811 = "装甲暗鬼",
  str_skill_desc_1002811 = "輸送任務を担う暗鬼。倒すと輸送している白夜コインを獲得できる",
  str_skill_name_515121 = "光の壁",
  str_skill_desc_515121 = "ミラーが変化したもの。ミラーは敵から最も遠い光の壁の中に隠れている（その光の壁は攻撃可能）。光の壁が破壊されると、幻影を召喚して敵を攻撃する。光の壁を3つ破壊すると全ての光の壁が消え、ミラーの本体が現れる",
  str_skill_name_1003401 = "戦力アップ",
  str_skill_desc_1003401 = "抱擁者は周囲1マス以内の暗鬼に取り付き、シールドを与えると同時に攻撃力を強化する",
  str_skill_name_1003421 = "理性喪失",
  str_skill_desc_1003421 = "錯乱の抱擁者が周囲1マス以内にいる光霊に憑依し、光霊の理性値を下げ続ける。",
  str_skill_name_1003501 = "回復",
  str_skill_desc_1003501 = "ドーンの周囲1マスまで近づくと、その体内に溶け込んでHPを回復する",
  str_skill_name_1003502 = "回復強化",
  str_skill_desc_1003502 = "ドーンの周囲1マスまで近づくと、その体内に溶け込んでHPを回復し、シールドを与える",
  str_skill_name_1003601 = "暁に咲く花",
  str_skill_desc_1003601 = "周囲2マス以内のターゲットに大ダメージを与える",
  str_skill_name_1003611 = "林を抜ける嵐",
  str_skill_desc_1003611 = "ハリケーンを発動し、敵全体に比較的大きなダメージを与える。フィールド上のヨアケバナの精の数が多いほど、与えるダメージは大きくなる",
  str_skill_name_1003621 = "ヨアケバナの精召喚",
  str_skill_desc_1003621 = "回復能力を持つヨアケバナの精を召喚する。ヨアケバナの精はドーンの周囲1マスまで近づくと、HPを回復させることができる",
  str_skill_name_1003622 = "召喚強化・ヨアケバナの精",
  str_skill_desc_1003622 = "ドーンが回復能力を持つヨアケバナの精を召喚する。ヨアケバナの精はドーンの周囲1マスまで近づくと、HPを回復してシールド与える",
  str_skill_name_1003800 = "孤兵",
  str_skill_desc_1003800 = "移動後、自身の周囲の十字方向4マスにダメージを与える",
  str_skill_name_1003901 = "直撃",
  str_skill_desc_1003901 = "十字方向に移動できる。移動後、自身の周囲1マス内のターゲットにダメージを与える。移動中にぶつかったターゲットには比較的大きなダメージを与え、フィールドの端までノックバックする",
  str_skill_name_1003902 = "縦横",
  str_skill_desc_1003902 = "十字方向に移動できる。移動後、自身の周囲2マス内のターゲットにダメージを与える。移動中にぶつかったターゲットには比較的大きなダメージを与え、フィールドの端までノックバックする",
  str_skill_name_1003912 = "硬化",
  str_skill_desc_1003912 = "空間ごと固定されたかのように移動や攻撃ができなくなるが、ダメージを受けることもない。次のウェーブで解除され行動できるようになる",
  str_skill_name_1004001 = "躍撃",
  str_skill_desc_1004001 = "着地後、自身の十字方向4マスにダメージを与える。着地点にターゲットがいた場合はターゲットに大ダメージ、眩暈、ノックバックを与える",
  str_skill_name_1004002 = "踏み潰し",
  str_skill_desc_1004002 = "着地後、自身の周囲1マスにダメージを与える。着地点にターゲットがいた場合はターゲットに大ダメージ、眩暈、ノックバックを与える",
  str_skill_desc_1104002 = "着地後、自身の周囲1マスにダメージを与え、範囲内にトゲトゲを設置する。着地点にターゲットがいた場合はターゲットに大ダメージ、眩暈、ノックバックを与える",
  str_skill_name_1004101 = "斜走撃",
  str_skill_desc_1004101 = "斜め方向に移動できる。移動後、十字方向の最大範囲内のターゲットにダメージを与える",
  str_skill_name_1004102 = "斜走撃破",
  str_skill_desc_1004102 = "斜め方向に移動できる。移動後、十字方向の最大範囲内のターゲットにダメージを与え、ターゲットの防御力を減少させる",
  str_skill_desc_1104102 = "斜め方向に移動できる。移動後、十字方向の最大範囲内のターゲットにダメージを与え、ターゲットの防御力を大幅に減少させる",
  str_skill_name_1004201 = "クイーンサイド",
  str_skill_desc_1004201 = "自身の縦、横、斜めの最大方向上のターゲットに、その最大HPを基準とした割合ダメージを与える",
  str_skill_name_1004202 = "拠点防御",
  str_skill_desc_1004202 = "自身の縦、横、斜めの最大範囲上のターゲットに、その最大HPを基準とした割合ダメージを与える。自身の周囲8方向にターゲットがいない場合は自身にバリアを展開する。さらに味方のHPを回復させる",
  str_skill_desc_1104202 = "自身の縦、横、斜めの最大範囲上のターゲットに、その最大HPを基準とした割合ダメージを与える。自身の周囲8方向にターゲットがいない場合は自身にバリアを展開し、光霊の理性値を低下させる。さらに味方のHPを回復させる",
  str_skill_name_1004301 = "号令",
  str_skill_desc_1004301 = "兵は命令を受け、自身の周囲1マスのターゲットにダメージを与える",
  str_skill_name_1004302 = "抗拒",
  str_skill_desc_1004302 = "範囲内のターゲットを技の攻撃範囲からはじき出す",
  str_skill_name_1004303 = "君主の領域",
  str_skill_desc_1004303 = "全ての敵にダメージを与える",
  str_skill_name_1006511 = "突進攻撃",
  str_skill_desc_1006511 = "範囲内のターゲットにダメージを与える",
  str_skill_name_1006521 = "爆裂",
  str_skill_desc_1006521 = "体内のエネルギーを爆発させ、範囲内のターゲットにダメージを与える。さらに今いるマスを破壊する",
  str_skill_name_1007001 = "エスケープ",
  str_skill_desc_1007001 = "目標範囲に粉砕されたマスがある場合、地面を潜ってターゲット付近の粉砕されたマスから飛び出し、ダメージを与える。さらに周囲のマスを粉砕する。光霊が粉砕マスを移動しても連鎖数は増加しない",
  str_skill_name_1007011 = "裂地",
  str_skill_desc_1007011 = "ターゲットの周囲に粉砕されたマスがない場合、自身から2マスの距離に移動し、周囲1マスを粉砕する。光霊が粉砕マスを移動しても連鎖数は増加しない",
  str_skill_name_29010011 = "絶叫",
  str_skill_desc_29010011 = "ターゲット周囲に粉砕されたマスがある場合、ターゲット付近の粉砕されたマスに移動してダメージを与え、ターゲットをノックバックする",
  str_skill_name_29010012 = "迫撃",
  str_skill_desc_29010012 = "ターゲットが縦、横、斜めの範囲内にいる時、ターゲットの近くに移動し、ターゲットにダメージを与えてノックバックする。さらにターゲットと自身のいる場所を結ぶ直線範囲のマスを粉砕する",
  str_skill_name_1007102 = "ウィップ",
  str_skill_desc_1007102 = "範囲内のターゲットにダメージを与える",
  str_skill_desc_10071021 = "範囲内のターゲットを即撃破する",
  str_skill_desc_220091202 = "範囲内のマスを粉砕し、さらに範囲内にいるターゲットにダメージを与える",
  str_skill_name_1007103 = "デスパルス",
  str_skill_desc_1007103 = "前のターンにターゲットがいた場所およびその周囲1マスに衝撃波を放つ。衝撃波の範囲内にいるターゲットに、大ダメージを与える",
  str_skill_desc_1107103 = "前ターンのターゲットのいた位置およびその周囲1マス以内に衝撃波を発動し、範囲内にいるターゲットを即死させる",
  str_skill_desc_220091201 = "前ターンのターゲットのいた位置およびその周囲1マスに衝撃波を放って範囲内のマスを粉砕し、さらに範囲内にいるターゲットを即死させる",
  str_skill_name_1007104 = "音波カバー",
  str_skill_desc_1007104 = "範囲内のターゲットにダメージを与え、ノックバックする",
  str_skill_desc_10071041 = "範囲内のターゲットにダメージを与えてノックバックする。光霊の理性値を低下させる触手を同時に複数召喚する",
  str_skill_name_1007112 = "ビームパルス",
  str_skill_desc_1007112 = "ターゲットが前のターンにいた場所にビームパルスを放ち、途中および目標地点にいるターゲットにダメージを与える（暗鬼は撃破から2ターン後、その場に復活する）",
  str_skill_desc_10071121 = "ターゲットが前のターンにいた位置に光線を放ち、目標位置とその途中にいるターゲットにダメージを与える",
  str_skill_name_1007113 = "ウィンドレイド",
  str_skill_desc_1007113 = "範囲内のターゲットを戦場中央までノックバックする（暗鬼は撃破から2ターン後、その場に復活する）",
  str_skill_name_39004511 = "黒流",
  str_skill_desc_39004511 = "ミラーが移動し、範囲内のターゲットに遠距離攻撃を行う。さらに幻影2体を戦場の端に召喚する",
  str_skill_name_39004512 = "背襲",
  str_skill_desc_39004512 = "ミラーがターゲットの近くに移動してダメージを与える。さらにターゲットの周囲に幻影を1体生み出す",
  str_skill_name_20005011 = "応変",
  str_skill_desc_20005011 = "ターゲットとの距離に応じて行動パターンを変化させ、側にトゲトゲを配置する。ターゲットとの距離が近い場合、ターゲットに大きなダメージを与え、ターゲットとの距離が遠い場合、ターゲットを自身の近くに引き寄せる",
  str_skill_name_20002441 = "暗鬼召喚",
