  str_skill_name_200024221 = "召喚・双剣 塵僕",
  str_skill_name_200024231 = "召喚・双剣 プローバノス",
  str_skill_desc_200024221 = "毎ターン双剣と塵僕が戦場に召喚される",
  str_skill_desc_200024231 = "毎ターン双剣とプローバノスが戦場に召喚される",
  str_skill_name_10000021 = "召喚・塵僕",
  str_skill_desc_10000021 = "毎ターン塵僕が戦場に召喚される",
  str_skill_name_28002411 = "プレッシャー",
  str_skill_desc_28002411 = "毎ターン、ノラがターゲットをノックバックする",
  str_skill_name_390041101 = "罪業・裂地",
  str_skill_desc_390041101 = "グスドが範囲内のターゲットに2回猛攻撃を加え、破裂の印を2スタック付与する。スタック数が多いほどターゲットの攻撃力がダウン。さらに、グスドの従者4体を一定の位置に召喚する",
  str_skill_name_390041102 = "罪業・裂地",
  str_skill_desc_390041102 = "グスドが範囲内のターゲットに2回猛攻撃を加え、破裂の印を2スタック付与する。スタック数が多いほどターゲットの攻撃力がダウン。さらに、グスドの従者4体を一定の位置に召喚する",
  str_skill_name_390041103 = "罪業・咆吼強化",
  str_skill_desc_390041103 = "グスドが死に際の咆吼とともに範囲内のターゲットに破裂の印を3スタック付与する。スタック数が多いほどターゲットの防御力が下がる",
  str_skill_name_390041104 = "罪業・起爆",
  str_skill_desc_390041104 = "グスドがターゲットの破裂の印を爆破させ、そのターゲットに大ダメージを与える。印のスタック数が多いほどダメージが大きくなる。破裂の印は爆破後、クリアされない",
  str_skill_name_300045101 = "罪業・咆吼",
  str_skill_desc_300045101 = "グスドの従者が自身の周囲2マス以内にいるターゲットに破裂の印を付与する。印1スタックにつき、ターゲットの防御力が一定程度減少。印のスタック数が多いほど防御力が下がる",
  str_skill_name_391028101 = "ダーククロス",
