  str_skill_name_391028102 = "チャージ",
  str_skill_desc_391028102 = "召喚師が現在地でエネルギーを蓄え、星標4個を一定の位置に召喚する。さらにすべての星標のHPを回復させる",
  str_skill_name_391028103 = "虚無",
