  str_skill_name_391028104 = "ダーククロス",
  str_skill_desc_391028104 = "召喚師が十字方向の最大範囲内のターゲットにダメージを与える。さらに星標2個を指定した位置に召喚する",
  str_skill_name_300040101 = "超エネルギー供給",
  str_skill_desc_300040101 = "星標がエネルギーリンクを通じて召喚師にエネルギーを供給する。星標1個につき召喚師の攻撃力+5%",
