  str_skill_name_390021104 = "罪業・岩石フォール",
  str_skill_desc_390021104 = "黒蹄が戦場にある岩石を吸収し、その数に基づいて敵にダメージを与える",
  str_skill_name_390025101 = "罪業・鎌攻撃",
  str_skill_desc_390025101 = "ゴーストが属性攻撃を1回行う",
  str_skill_name_390025102 = "罪業・重なる災難",
  str_skill_desc_390025102 = "ゴーストが十字範囲に属性ダメージを与える",
  str_skill_name_390025103 = "幻影召喚",
  str_skill_desc_390025103 = "狂暴な幽霊の幻影を1体召喚し、幻影を操って全範囲の敵にダメージを与える。ターゲットのHPが低いほど、与えるダメージが大きくなる",
  str_skill_name_1007211 = "ソレイスの暗躍",
  str_skill_desc_1007211 = "ミュートは自身の前方2マスの長方形最大範囲内に衝撃波を放ち、範囲内のターゲットにダメージを与える",
  str_skill_name_1007221 = "ソレイスの人形",
  str_skill_desc_1007221 = "ミュートが召喚する特定の暗鬼で、ミュートを助けて光霊の行動を阻害する",
  str_skill_name_290120101 = "闇を歩む光",
  str_skill_desc_290120101 = "祭剣座は連鎖でターゲット付近に移動できない場合、暗鬼と同じ移動方法をとり、移動後範囲内にいるターゲットを斬りつけ、ダメージを与える。同時に1回攻撃を防ぐバリアを張る",
  str_skill_name_290120102 = "擬光",
  str_skill_desc_290120102 = "祭剣座は連鎖でターゲット近くに移動できる場合、光霊と同じ移動方法をとり、移動後ターゲットに大ダメージを与える",
  str_skill_name_290120103 = "影の猟殺",
  str_skill_desc_290120103 = "祭剣座がフィールド中央に瞬間移動し、強大な力で中央の十字範囲のマスを破壊する。さらにフィールド内の3つの領域を暗力で覆い、領域内の光力を一時的に消失させる",
  str_skill_name_290130101 = "退散",
  str_skill_desc_290130101 = "心の魔物が技の範囲内にいる敵を攻撃し、ダメージを与えてターゲットをノックバックする",
  str_skill_name_290130102 = "悪夢",
  str_skill_desc_290130102 = "心の魔物が全範囲のターゲットにダメージを与える",
  str_skill_name_290130103 = "腐壊",
  str_skill_desc_290130103 = "心の魔物が周囲2マスの範囲内にいるターゲットにダメージを与え、技の範囲内のマスを転色するとともに技の範囲内のマスの一部をロックする。その後、戦場に従僕を3体召喚する",
  str_skill_desc_290130113 = "心の魔物が周囲2マスの範囲内にいるターゲットにダメージを与え、技の範囲内のマスを転色するとともに技の範囲内のマスの一部をロックする。その後、戦場に従僕を2体召喚する",
  str_skill_desc_290130123 = "心の魔物が周囲2マスの範囲内にいるターゲットにダメージを与え、技の範囲内のマスを転色するとともに技の範囲内のマスの一部をロックする。その後、戦場に従者を4体召喚する",
  str_skill_name_290134101 = "退散",
  str_skill_desc_290134101 = "心の魔物が技の範囲内にいる敵を攻撃し、ダメージを与えてターゲットをノックバックする。その後、戦場に心の魔物の従者を召喚する",
  str_skill_name_290134102 = "悪夢",
  str_skill_desc_290134102 = "心の魔物が全範囲のターゲットにダメージを与え、戦場内に弱化マスを生成する",
