  str_skill_name_200134101 = "闇討",
  str_skill_desc_200134101 = "範囲内にいる敵ターゲットに大ダメージを1回与える",
  str_skill_name_200134105 = "闇討",
  str_skill_desc_200134105 = "戦場にいる敵ターゲットに大ダメージを1回与える",
  str_skill_desc_200130102 = "戦場にいる敵ターゲットに大ダメージを1回与え、さらに心の魔物の印を付与する。印1スタックにつき、ターゲットの防御力が一定程度減少。印のスタック数が多いほど防御力が下がる。極光タイム発動時、すべての心の魔物の印がクリアされる",
