  str_skill_name_290180401 = "指令・粛清",
  str_skill_desc_290180401 = "範囲内のターゲットに1回遠距離攻撃を行い、その後フィールド上にプリズム塔と妨害装置を配置する。妨害装置の存在できる数には上限がある",
  str_skill_name_51104811 = "幻影召喚",
  str_skill_desc_51104811 = "真正面のマス上にプレイヤーの幻影を召喚する",
  str_skill_desc_39104512 = "ミラーがターゲットの近くに移動してダメージを与える。さらにターゲットの周囲に幻影を1体召喚する。残りの壁の数が少ないほど、幻影は強化される",
  str_skill_desc_39204512 = "ミラーがターゲットの近くに移動してダメージを与える。さらにターゲットの周囲に幻影を1体召喚し、周囲1マスの範囲をロックする。残りの壁の数が少ないほど、幻影は強化される",
  str_skill_desc_39104522 = "ミラーがターゲットの近くに移動してダメージを与える。さらに残りの壁の数に応じて、1体から2体の幻影を生み出す。残りの壁の数が少ないほど、幻影は強化される",
  str_skill_desc_39204522 = "ミラーがターゲットの近くに移動してダメージを与える。さらに残りの壁の数に応じて、1体から2体の幻影を生み出し、同時に周囲1マス以内のマスをロックする。残りの壁の数が少ないほど、幻影は強化される",
  str_skill_desc_39104511 = "ミラーは移動後、範囲内のターゲットに遠距離攻撃を行う",
