  str_skill_desc_290039102 = "ボリングが戦場中7ヵ所の2×2のエリアを爆撃し、範囲内の殲星爆弾を起爆する",
  str_skill_desc_290139102 = "ボリングが戦場中7ヵ所の2×2のエリアを爆撃する。範囲内のマスをリセットし、さらに範囲内の殲星爆弾を起爆する",
