  str_skill_name_13005802 = "旗幟黎明",
  str_skill_desc_13005802 = "1マス選択してエイミーの旗槍を設置する。光霊と旗槍の距離が近いほど防御力が増加。最大で防御力+<color=#00F6FF>30%</color>。敵が旗槍に触れると消える",
