  str_skill_name_200553 = "誅伏",
  str_skill_desc_300050 = "<color=#00F6FF>縦、横、斜めの16マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_320050 = "<color=#00F6FF>縦、横、斜めの16マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらにノックバックした敵の防御力-10%",
  str_skill_desc_300022 = "<color=#00F6FF>周囲1マス以内</color>と<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_303022 = "<color=#00F6FF>周囲1マス以内</color>と<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_310022 = "<color=#00F6FF>周囲1マス以内</color>と<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_313022 = "<color=#00F6FF>周囲1マス以内</color>と<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_300047 = "ゾーヤの攻撃力の<color=#00F6FF>150%</color>相当のチームHPを回復する。戦場にある水属性のマス1つにつき回復量+<color=#00F6FF>5%</color>",
  str_skill_desc_303047 = "ゾーヤの攻撃力の<color=#00F6FF>150%</color>相当のチームHPを回復する。戦場にある水属性のマス1つにつき回復量+<color=#00F6FF>5%</color>",
  str_skill_desc_320047 = "ゾーヤの攻撃力の<color=#00F6FF>150%</color>相当のチームHPを回復する。戦場にある水属性のマス1つにつき回復量+<color=#00F6FF>8%</color>",
  str_skill_desc_323047 = "ゾーヤの攻撃力の<color=#00F6FF>150%</color>相当のチームHPを回復する。戦場にある水属性のマス1つにつき回復量+<color=#00F6FF>8%</color>",
  str_skill_desc_300049 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_303049 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320049 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。同時に攻撃範囲内の火属性のマスを他の属性にリセットする",
  str_skill_desc_323049 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。同時に攻撃範囲内の火属性のマスを他の属性にリセットする",
  str_skill_desc_300051 = "1方向を選んで攻撃し、最初に命中した敵とその<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>240%</color>のダメージを与える",
  str_skill_desc_310051 = "1方向を選んで攻撃し、最初に命中した敵とその<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>240%</color>のダメージを与える",
  str_skill_desc_320051 = "1方向を選んで攻撃し、最初に命中した敵および<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>240%</color>のダメージを与え、2ターン<link=\"10002\"><#FFAE07><u>火傷</u></color></link>状態にする（最初の敵に2スタック、その他に1スタック）",
  str_skill_desc_300052 = "任意の方向の3マス以内の位置に瞬間移動し、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_310052 = "任意の方向の3マス以内の位置に瞬間移動し、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320052 = "任意の方向3マス以内の位置に瞬間移動し、その<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300007 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320007 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える。ターゲットが毒状態の場合、その毒状態のスタック数を2倍にする。毒状態のスタック数が上限の5スタックに達している場合、能動技のダメージ+<color=#00F6FF>50%</color>",
  str_skill_desc_300008 = "進入可能なマスを1つ選び、火属性の<link=\"30001\"><#FFAE07><u>プリズムマス</u></color></link>に変える",
  str_skill_desc_310008 = "進入可能なマスを1つ選び、火属性の<link=\"30001\"><#FFAE07><u>プリズムマス</u></color></link>に変える",
  str_skill_desc_300032 = "フィールド上のランダムな敵に<color=#00F6FF>100%</color>のダメージを<color=#00F6FF>6～10</color>回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する",
  str_skill_desc_310032 = "フィールド上のランダムな敵に<color=#00F6FF>100%</color>のダメージを<color=#00F6FF>6～10</color>回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する",
  str_skill_desc_300035 = "自分の<color=#00F6FF>周囲2マス</color>以内の任意の位置に瞬間移動できる",
  str_skill_desc_310035 = "自分の<color=#00F6FF>周囲2マス</color>以内の任意の位置に瞬間移動できる",
  str_skill_desc_320035 = "自分の<color=#00F6FF>周囲2マス</color>以内の任意の位置に瞬間移動できる",
  str_skill_desc_300058 = "任意のマスに旗槍を設置する。エイミーと旗槍が近いほど防御は高くなり、最大で防御+<color=#00F6FF>100%</color>。旗槍は敵に触れられると消える",
  str_skill_desc_303058 = "任意のマスに旗槍を設置する。エイミーと旗槍が近いほど防御は高くなり、最大で防御+<color=#00F6FF>100%</color>。旗槍は敵に触れられると消える",
  str_skill_desc_310058 = "任意のマスに旗槍を設置する。エイミーと旗槍が近いほど防御は高くなり、最大で防御+<color=#00F6FF>100%</color>。旗槍は敵に触れられると消える",
  str_skill_desc_313058 = "任意のマスに旗槍を設置する。エイミーと旗槍が近いほど防御は高くなり、最大で防御+<color=#00F6FF>100%</color>。旗槍は敵に触れられると消える",
  str_skill_desc_300053 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>150%</color>のダメージを与える。敵が1体しかいない場合、ダメージが<color=#00F6FF>1.5</color>倍になる",
  str_skill_desc_303053 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>150%</color>のダメージを与える。敵が1体しかいない場合、ダメージが<color=#00F6FF>1.5</color>倍になる。能動技でターゲットを倒すと再び使用できる",
  str_skill_desc_310053 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>150%</color>のダメージを与える。敵が1体しかいない場合、ダメージが<color=#00F6FF>1.5</color>倍になる",
  str_skill_desc_313053 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>150%</color>のダメージを与える。敵が1体しかいない場合、ダメージが<color=#00F6FF>1.5</color>倍になる。能動技でターゲットを倒すと再び使用できる",
  str_skill_desc_320053 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>150%</color>のダメージを与える。敵が1体しかいない場合、ダメージが<color=#00F6FF>2</color>倍になる",
  str_skill_desc_323053 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>150%</color>のダメージを与える。敵が1体しかいない場合、ダメージは<color=#00F6FF>2</color>倍になる。能動技でターゲットを倒すと再び使用できる",
  str_skill_desc_300074 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵を自身の周囲に引き寄せる",
  str_skill_desc_310074 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵を自身の周囲に引き寄せる",
  str_skill_desc_320074 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、自身の周囲に敵を引き寄せる。敵は<color=#00F6FF>1</color>マス引き寄せられるごとに、最終ダメージ+<color=#00F6FF>10%</color>",
  str_skill_desc_300017 = "指定の位置に瞬間移動し、<color=#00F6FF>十字方向4マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_320017 = "指定の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与え、ノックバックする",
  str_skill_desc_300040 = "<color=#00F6FF>周囲2マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の全てのマスをリセットする",
  str_skill_desc_330040 = "<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。さらに範囲内全ての<color=#00F6FF>非火属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で火属性のマスに変える",
  str_skill_desc_300041 = "<color=#00F6FF>十字方向4マス</color>を水属性に変える",
  str_skill_desc_304041 = "<color=#00F6FF>十字方向4マス</color>を水属性に変える。マスの生成時、一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで",
  str_skill_desc_300021 = "戦場の全てのマスをリセットし、<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の数を保ったまま再配置する",
  str_skill_desc_310021 = "戦場の全てのマスをリセットし、<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の数を保ったまま再配置する",
  str_skill_desc_330021 = "戦場の全てのマスをリセットし、<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の数を保ったまま再配置する。<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が森属性のマスに現れる確率が上がる",
  str_skill_desc_300004 = "1マス選択し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320004 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_330004 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、攻撃範囲内のランダムな<color=#00F6FF>2</color>マスを水属性に変える",
  str_skill_desc_300073 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320073 = "1マス選択し、<color=#00F6FF>菱形13マス</color>にダメージを与える。選択したマスに<color=#00F6FF>300%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>225%</color>のダメージを与える。他のマスには<color=#00F6FF>150%</color>のダメージを与える",
