  str_skill_desc_3300543 = "2ターン存在する提灯を1つ設置し、提灯が存在する間そのマスは雷属性に固定される。チームが提灯を通り過ぎるたびに攻撃力<color=#00F6FF>180%</color>のHPを回復する。提灯は敵が触れると消える",
  str_skill_desc_3100544 = "2ターン存在する提灯を1つ設置し、提灯が存在する間そのマスは雷属性に固定される。チームが提灯を通り過ぎるたびに攻撃力<color=#00F6FF>180%</color>のHPを回復する。提灯は敵が触れると消える",
  str_skill_desc_3300544 = "2ターン存在する提灯を1つ設置し、提灯が存在する間そのマスは雷属性に固定される。チームが提灯を通り過ぎるたびに攻撃力<color=#00F6FF>180%</color>のHPを回復する。提灯は敵が触れると消える",
  str_skill_desc_300016 = "自身を起点とする<color=#00F6FF>8</color>方向から2方向を選択して射撃、あるいは1方向を選択して2回射撃する。射撃ごとに、その方向のすべてのマスに<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_310016 = "自身を起点とする<color=#00F6FF>8</color>方向から2方向を選択して射撃、あるいは1方向を選択して2回射撃する。射撃ごとに、その方向のすべてのマスに<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_320016 = "選択可能なマスを<color=#00F6FF>2</color>マス選択して射撃、または1マスを選択して2回射撃する。射撃ごとに、その方向のすべてのマスに<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_300044 = "<color=#00F6FF>周囲3マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与え、敵のいるマス1つを雷属性に変える",
  str_skill_desc_305044 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵のいるマス1つを雷属性に変える",
  str_skill_desc_320044 = "<color=#00F6FF>周囲3マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与え、敵のいるマス1つを雷属性に変える。このターン全体の雷属性光霊の連鎖発動条件<color=#00F6FF>-1</color>",
  str_skill_desc_325044 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵のいるマス1つを雷属性に変える。このターン全体の雷属性光霊の連鎖発動条件<color=#00F6FF>-1</color>",
  str_skill_desc_300048 = "1マス選択し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_302048 = "1マス選択し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵のいるマス1つを雷属性に変える",
  str_skill_desc_320048 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_322048 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵のいるマス1つを雷属性に変える",
  str_skill_desc_300009 = "最も近くの雷属性のマス<color=#00F6FF>4</color>つを火属性に変える",
  str_skill_desc_302009 = "最も近くの雷属性のマス<color=#00F6FF>4</color>つを火属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_305009 = "最も近くの雷属性のマス<color=#00F6FF>5</color>つを火属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_330009 = "最も近くの雷属性のマス<color=#00F6FF>4</color>つを火属性に変える。一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで",
  str_skill_desc_332009 = "最も近くの雷属性のマス<color=#00F6FF>4</color>つを火属性に変える。一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_335009 = "最も近くの雷属性のマス<color=#00F6FF>5</color>つを火属性に変える。一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_300012 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、ノックバックする。さらに攻撃範囲内のマスを雷属性に変える",
  str_skill_desc_302012 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、ノックバックする。さらに攻撃範囲内のマスを雷属性に変える",
  str_skill_desc_300013 = "水属性のマス1つにつき、ノーアのHP<color=#00F6FF>8%</color>のシールドを獲得する。1ターン持続",
  str_skill_desc_305013 = "水属性のマス1つにつき、ノーアのHPの<color=#00F6FF>10%</color>のシールドを獲得する。1ターン持続",
  str_skill_desc_320013 = "水属性のマス1つにつき、ノーアのHPの<color=#00F6FF>8%</color>のシールドを獲得する。1ターン持続。能動技を発動するとノーアの防御力+<color=#00F6FF>50%</color>。1ターン持続",
  str_skill_desc_325013 = "水属性のマス1つにつき、ノーアのHPの<color=#00F6FF>10%</color>のシールドを獲得する。1ターン持続。能動技を発動するとノーアの防御力+<color=#00F6FF>50%</color>。1ターン持続",
  str_skill_desc_300018 = "太陽フレアを引き起こし、敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。また自身を中心に、命中した敵を四方にノックバックする",
  str_skill_desc_305018 = "太陽フレアを引き起こし、敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。また自身を中心に、命中した敵を四方にノックバックする",
  str_skill_desc_300033 = "戦場のランダムな敵に<color=#00F6FF>80%</color>のダメージを<color=#00F6FF>5</color>回与え、現在地の<color=#00F6FF>周囲1マス</color>にある水属性のマス1つにつき、追加で1回攻撃する",
  str_skill_desc_305033 = "戦場のランダムな敵に<color=#00F6FF>80%</color>のダメージを<color=#00F6FF>6</color>回与え、現在地の<color=#00F6FF>菱形12マス</color>以内にある水属性のマス1つにつき、追加で1回攻撃する",
  str_skill_desc_320033 = "戦場のランダムな敵に<color=#00F6FF>95%</color>のダメージを<color=#00F6FF>5</color>回与え、現在地の<color=#00F6FF>周囲1マス</color>にある水属性のマス1つにつき、追加で1回攻撃する",
  str_skill_desc_325033 = "戦場のランダムな敵に<color=#00F6FF>95%</color>のダメージを<color=#00F6FF>6</color>回与え、現在地の<color=#00F6FF>菱形12マス</color>以内にある水属性のマス1つにつき、追加で1回攻撃する",
  str_skill_desc_300036 = "使用すると、そのターンで水属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての水属性光霊の攻撃力がヒドライの攻撃力の<color=#00F6FF>70%</color>になる",
  str_skill_desc_305036 = "使用すると、そのターンで水属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての水属性光霊の攻撃力がヒドライの攻撃力の<color=#00F6FF>70%</color>になる",
  str_skill_desc_330036 = "使用すると、そのターンで水属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての水属性光霊の攻撃力がヒドライの攻撃力の<color=#00F6FF>85%</color>になる",
  str_skill_desc_335036 = "使用すると、そのターンで水属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての水属性光霊の攻撃力がヒドライの攻撃力の<color=#00F6FF>85%</color>になる",
  str_skill_desc_300010 = "使用すると、そのターンで森属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての森属性光霊の攻撃力がルイスの攻撃力の<color=#00F6FF>70%</color>になる",
  str_skill_desc_305010 = "使用すると、そのターンで森属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての森属性光霊の攻撃力がルイスの攻撃力の<color=#00F6FF>70%</color>になる",
  str_skill_desc_330010 = "使用すると、そのターンで森属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての森属性光霊の攻撃力がルイスの攻撃力の<color=#00F6FF>85%</color>になる",
  str_skill_desc_335010 = "使用すると、そのターンで森属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての森属性光霊の攻撃力がルイスの攻撃力の<color=#00F6FF>85%</color>になる",
  str_skill_desc_300014 = "敵<color=#00F6FF>全体</color>に対し、ターゲットの現HPの<color=#00F6FF>10%</color>を付与して<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_302014 = "敵<color=#00F6FF>全体</color>に対し、ターゲットの現HPの<color=#00F6FF>10%</color>を付与して<color=#00F6FF>{1}%</color>のダメージを与える（ボス以外のHP<color=#00F6FF>10%</color>未満の敵を瞬殺する）",
  str_skill_desc_320014 = "敵<color=#00F6FF>全体</color>に対し、ターゲットの現HPの<color=#00F6FF>10%</color>を付与して<color=#00F6FF>{1}%</color>のダメージを与える。ソルラドの防御力が高いほど能動技の与えるダメージが大きくなる。最大で+<color=#00F6FF>5%</color>",
  str_skill_desc_322014 = "敵<color=#00F6FF>全体</color>に対し、ターゲットの現HPの<color=#00F6FF>10%</color>を付与して<color=#00F6FF>{1}%</color>のダメージを与える（ボス以外のHP<color=#00F6FF>10%</color>未満の敵を瞬殺する）。ソルラドの防御力が高いほど能動技の与えるダメージが大きくなる。最大で+<color=#00F6FF>5%</color>",
  str_skill_desc_300078 = "1マス選択し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_302078 = "1マス選択し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。さらに敵のいるマス1つを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える",
