  str_skill_desc_335076 = "最も近くの森属性のマス<color=#00F6FF>5</color>つを水属性に変える（一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで）。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
