  str_skill_desc_306001 = "最も近くの火または雷属性のマス<color=#00F6FF>5</color>つを森属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_330001 = "最も近くの火または雷属性のマス<color=#00F6FF>4</color>つを森属性に変える（一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで）",
  str_skill_desc_333001 = "最も近くの火または雷属性のマス<color=#00F6FF>4</color>つを森属性に変える（一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで）。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_336001 = "最も近くの火または雷属性のマス<color=#00F6FF>5</color>つを森属性に変える（一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで）。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_300011 = "指定した位置に瞬間移動し、<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320011 = "指定位置に瞬間移動し、<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、龍牙の印を<color=#00F6FF>2</color>スタック付与する（敵を撃破した場合、範囲内の他の敵のスタック数を最大限まで増加させる）",
  str_skill_desc_330011 = "指定位置に瞬間移動し、<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、龍牙の印を<color=#00F6FF>2</color>スタック付与する（敵を撃破した場合、範囲内の他の敵のスタック数を最大限まで増加させる）",
  str_skill_desc_300019 = "<color=#00F6FF>周囲3マス</color>にいる最大3体の敵に<color=#00F6FF>250%</color>のダメージを与える。敵が1体だけの場合は<color=#00F6FF>250%</color>の防御力無視のダメージを与え、そのダメージの25%のHPを回復する",
  str_skill_desc_303019 = "<color=#00F6FF>周囲3マス</color>にいる最大3体の敵に<color=#00F6FF>250%</color>のダメージを与える。敵が1体だけの場合は<color=#00F6FF>250%</color>の防御力無視のダメージを与え、そのダメージの35%のHPを回復する",
  str_skill_desc_306019 = "最も近くにいる敵3体に<color=#00F6FF>250%</color>のダメージを与える。敵が1体だけの場合は<color=#00F6FF>250%</color>の防御力無視のダメージを与え、そのダメージの35%のHPを回復する",
  str_skill_desc_320019 = "<color=#00F6FF>周囲3マス</color>にいる最大3体の敵に<color=#00F6FF>250%</color>のダメージを与える。敵が1体だけの場合は<color=#00F6FF>250%</color>の防御力無視のダメージを与え、そのダメージの25%のHPを回復する。ターゲットは出血状態1スタックにつき最終ダメージ+10%",
  str_skill_desc_323019 = "<color=#00F6FF>周囲3マス</color>にいる最大3体の敵に<color=#00F6FF>250%</color>のダメージを与える。敵が1体だけの場合は<color=#00F6FF>250%</color>の防御力無視のダメージを与え、そのダメージの35%のHPを回復する。ターゲットは出血状態1スタックにつき最終ダメージ+10%",
  str_skill_desc_326019 = "最も近くにいる敵3体に<color=#00F6FF>250%</color>のダメージを与える。敵が1体だけの場合は<color=#00F6FF>250%</color>の防御力無視のダメージを与え、そのダメージの35%のHPを回復する。ターゲットは出血状態1スタックにつき最終ダメージ+10%",
