  str_skill_desc_306002 = "選択した<color=#00F6FF>2</color>マスを森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変え、それぞれのマスから<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>240%</color>のダメージを与える",
  str_skill_desc_320002 = "選択した<color=#00F6FF>2</color>マスを森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変え、それぞれのマスから<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>200%</color>のダメージを与える",
  str_skill_desc_323002 = "選択した<color=#00F6FF>2</color>マスを森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変え、それぞれのマスから<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>240%</color>のダメージを与える",
  str_skill_desc_326002 = "選択した<color=#00F6FF>2</color>マスを森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変え、それぞれのマスから<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>240%</color>のダメージを与える",
  str_skill_desc_16000213 = "指定した2つのマスを森属性の強化マスに変換し、そのマスを中心とする十字方向の最大範囲にダメージを与える",
  str_skill_desc_300005 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）",
  str_skill_desc_306005 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）",
  str_skill_desc_310005 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）",
  str_skill_desc_316005 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）",
  str_skill_desc_330005 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）",
  str_skill_desc_336005 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）",
  str_skill_desc_300006 = "指定した位置に瞬間移動し、<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲のマスを水属性に変える",
  str_skill_desc_303006 = "指定した位置に瞬間移動し、<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲のマスを水属性に変える",
  str_skill_desc_300025 = "<color=#00F6FF>3列</color>か<color=#00F6FF>3行</color>かを選んで、<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。範囲内の<color=#00F6FF>非火属性</color>のマスをリセットする",
  str_skill_desc_306025 = "<color=#00F6FF>3列</color>か<color=#00F6FF>3行</color>かを選んで、<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。範囲内の<color=#00F6FF>非火属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で火属性のマスに変える",
  str_skill_desc_320025 = "<color=#00F6FF>3列</color>か<color=#00F6FF>3行</color>かを選んで、<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。真ん中の行か列のダメージは両側の1.5倍。範囲内の<color=#00F6FF>非火属性</color>のマスをリセットする",
  str_skill_desc_326025 = "<color=#00F6FF>3列</color>か<color=#00F6FF>3行</color>かを選んで、<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。真ん中の行か列のダメージは両側の1.5倍。範囲内の<color=#00F6FF>非火属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で火属性のマスに変える",
  str_skill_desc_300026 = "<color=#00F6FF>全ての非火属性</color>のマスをリセットする。<color=#00F6FF>低確率</color>で火属性のマスに変わるが、最低でも敵がいるマス1つが火属性になる",
  str_skill_desc_306026 = "<color=#00F6FF>全ての非火属性</color>のマスをリセットする。<color=#00F6FF>低確率</color>で火属性のマスに変わるが、最低でも敵がいるマス1つが火属性になる",
  str_skill_desc_300028 = "ラファエルの攻撃力の<color=#00F6FF>200%</color>相当のチームHPを回復し、<color=#00F6FF>周囲3マスの非水属性</color>のマスをリセットする",
  str_skill_desc_306028 = "ラファエルの攻撃力の<color=#00F6FF>200%</color>相当のチームHPを回復する。さらに<color=#00F6FF>周囲3マスの非水属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で水属性のマスに変える",
  str_skill_desc_330028 = "ラファエルの攻撃力の<color=#00F6FF>200%</color>相当のチームHPを回復し、<color=#00F6FF>全ての非水属性</color>のマスをリセットする",
  str_skill_desc_336028 = "ラファエルの攻撃力の<color=#00F6FF>200%</color>相当のチームHPを回復する。さらに<color=#00F6FF>全ての非水属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で水属性のマスに変える",
  str_skill_desc_300029 = "水、火、雷属性のマスから<color=#00F6FF>1</color>種類選び、他の属性にリセットするが、マスの強化属性は保たれる",
  str_skill_desc_306029 = "水、火、雷属性のマスから<color=#00F6FF>1</color>種類選び、他の属性にリセットするが、マスの強化属性は保たれる",
  str_skill_desc_320029 = "水、火、雷属性のマスから<color=#00F6FF>1</color>種類選び、他の属性にリセットするが、マスの強化属性は保たれる。<color=#00F6FF>10</color>マスをリセットするごとに、必ず<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が1つ現れる",
  str_skill_desc_326029 = "水、火、雷属性のマスから<color=#00F6FF>1</color>種類選び、他の属性にリセットするが、マスの強化属性は保たれる。<color=#00F6FF>10</color>マスをリセットするごとに、必ず<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が1つ現れる",
