  str_skill_desc_325075 = "敵<color=#00F6FF>全体</color>に{1}%のダメージを与え、2ターン持続する<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態にする。さらに<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を2スタック付与する。2ターン持続",
  str_skill_desc_300086 = "ユーライアのHP上限の<color=#00F6FF>60%</color>相当のチームHPを回復。HPの回復量が上限を超えた場合、最も近くの森属性のマスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変換する",
  str_skill_desc_304086 = "ユーライアのHP上限の<color=#00F6FF>70%</color>相当のチームHPを回復。HPの回復量が上限を超えた場合、最も近くの森属性のマスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変換する",
  str_skill_desc_330086 = "ユーライアのHP上限の<color=#00F6FF>60%</color>相当のチームHPを回復。HPの回復量が上限を超えた場合、最も近くの森属性のマスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変換する。<link=\"30010\"><#FFAE07><u>極光タイム</u></color></link>が発動すると、能動技を使用できるようになる",
  str_skill_desc_334086 = "ユーライアのHP上限の<color=#00F6FF>70%</color>相当のチームHPを回復。HPの回復量が上限を超えた場合、最も近くの森属性のマスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変換する。<link=\"30010\"><#FFAE07><u>極光タイム</u></color></link>が発動すると、能動技を使用できるようになる",
  str_skill_desc_300068 = "任意の位置に瞬間移動し、移動前の位置にウェンディの羽を1個生成する。ウェンディの羽をタップすると移動前の位置に戻れる。戦場に存在できるウェンディの羽は1個まで",
  str_skill_desc_320068 = "戦闘開始時、戦場にウェンディの羽を1個生成する。また、能動技で移動後、移動前の位置にウェンディの羽を1個生成する。ウェンディの羽をタップすると移動前の位置に戻れる。戦場に存在できるウェンディの羽は1個まで",
  str_skill_desc_300082 = "<color=#00F6FF>2</color>個のマスを選択し、そのマスの属性を交換する",
  str_skill_desc_320082 = "<color=#00F6FF>2</color>個のマスを選択し、そのマスの属性を交換する。交換したマスに森属性が含まれている場合、そのマスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変更する",
  str_skill_desc_300057 = "任意の位置に瞬間移動し、フィリスの攻撃力の<color=#00F6FF>250%</color>相当のチームHPを回復する。瞬間移動した位置の<color=#00F6FF>周囲2マス</color>以内にいる敵1体につき、回復効果+<color=#00F6FF>10%</color>",
  str_skill_desc_305057 = "任意の位置に瞬間移動し、フィリスの攻撃力の<color=#00F6FF>250%</color>相当のチームHPを回復する。瞬間移動した位置の<color=#00F6FF>周囲3マス</color>以内にいる敵1体につき、回復効果+<color=#00F6FF>15%</color>",
  str_skill_desc_320057 = "任意の位置に瞬間移動し、フィリスの攻撃力の<color=#00F6FF>250%</color>相当のチームHPを回復する。瞬間移動した位置の<color=#00F6FF>周囲2マス</color> 以内にいる敵1体につき、HP上限の<color=#00F6FF>30%</color>相当のシールドと<color=#00F6FF>10%</color> の回復効果をフィリスに付与する",
  str_skill_desc_325057 = "任意の位置に瞬間移動し、フィリスの攻撃力の<color=#00F6FF>250%</color>相当のチームHPを回復する。瞬間移動した位置の<color=#00F6FF>周囲3マス</color> 以内にいる敵1体につき、HP上限の<color=#00F6FF>30%</color>相当のシールドと<color=#00F6FF>15%</color>の回復効果をフィリスに付与する",
  str_skill_desc_300091 = "発動すると、戦場にある水属性のマス1つにつき、クロエの攻撃力の<color=#00F6FF>0.5%</color>に相当する攻撃力バフを出撃メンバーに付与する。2ターン持続",
  str_skill_desc_320091 = "<link=\"30006\"><#FFAE07><u>協奏の印</u></color></link>を獲得できる。発動すると、戦場にある水属性のマス1つ、または印1スタックごとに、出撃メンバーにクロエの攻撃力の<color=#00F6FF>0.5%</color>相当の攻撃力バフを付与する。2ターン持続",
  str_skill_desc_300079 = "<color=#00F6FF>周囲2マス</color>以内にいる敵に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の全てのマスをリセットする",
  str_skill_desc_330079 = "<color=#00F6FF>周囲2マス</color>内の敵に<color=#00F6FF>{1}%</color>のダメージを与える。さらに範囲内全ての<color=#00F6FF>非水属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で水属性のマスに変える",
  str_skill_desc_300085 = "<color=#00F6FF>HP比率の最も低い</color>敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320085 = "<color=#00F6FF>HP比率の最も低い</color>敵に<color=#00F6FF>{1}%</color>のダメージを与える。能動技でターゲットを倒すと再び使用できる",
  str_skill_desc_330085 = "<color=#00F6FF>HP比率の最も低い</color>敵に<color=#00F6FF>{1}%</color>のダメージを与える。<link=\"30005\"><#FFAE07><u>記録の印</u></color></link>を獲得できる。印1スタックごとに水属性の光霊の攻撃力+<color=#00F6FF>1%</color>。能動技でターゲットを倒すと再び使用できる",
  str_skill_desc_300089 = "選択した<color=#00F6FF>2</color>マスを雷属性の<link=\"30001\"><#FFAE07><u>プリズムマス</u></color></link>に変える",
  str_skill_desc_16008901 = "任意の2つのマスを雷属性のプリズムマスに変換する",
  str_skill_desc_303089 = "選択した<color=#00F6FF>2</color>マスを雷属性のプリズム<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変換できる",
  str_skill_desc_300027 = "選択した場所までダッシュし、途中のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_303027 = "選択した位置までダッシュし、途中のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与える。さらに移動距離に応じて選択した位置で連鎖技を1回発動する",
  str_skill_desc_330027 = "選択した場所までダッシュし、途中のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与える。さらに敵の現在のHPの<color=#00F6FF>5%</color>のダメージを追加で与える",
  str_skill_desc_333027 = "選択した位置までダッシュし、途中のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与える。さらに敵の現在のHPの<color=#00F6FF>5%</color>のダメージを追加で与え、移動距離に応じて選択した位置で連鎖技を1回発動する",
  str_skill_desc_300060 = "「真昼」状態になり、ジョナの攻撃力+<color=#00F6FF>10%</color>、連鎖技ダメージ+<color=#00F6FF>30%</color>。2ターン持続",
  str_skill_desc_303060 = "「真昼」状態になり、ジョナの攻撃力+<color=#00F6FF>10%</color>、連鎖技ダメージ+<color=#00F6FF>30%</color>。2ターン持続",
  str_skill_desc_306060 = "「真昼」状態になり、ジョナの攻撃力+<color=#00F6FF>15%</color>、連鎖技ダメージ+<color=#00F6FF>30%</color>。2ターン持続",
  str_skill_desc_330060 = "「真昼」状態になり、ジョナの攻撃力+<color=#00F6FF>10%</color>、連鎖技ダメージ+<color=#00F6FF>30%</color>。さらに火属性光霊の連鎖技発動に必要なマスの数<color=#00F6FF>-2</color>。2ターン持続",
  str_skill_desc_333060 = "「真昼」状態になり、ジョナの攻撃力+<color=#00F6FF>10%</color>、連鎖技ダメージ+<color=#00F6FF>30%</color>。さらに火属性光霊の連鎖技発動に必要なマスの数<color=#00F6FF>-2</color>。2ターン持続",
  str_skill_desc_336060 = "「真昼」状態になり、ジョナの攻撃力+<color=#00F6FF>15%</color>、連鎖技ダメージ+<color=#00F6FF>30%</color>。さらに火属性の光霊の連鎖技発動に必要なマスの数<color=#00F6FF>-2</color>。2ターン持続",
  str_skill_desc_300064 = "オーバーロード状態になり、ラスの連鎖技ダメージ+<color=#00F6FF>50%</color>、かつ最も近くの敵1体にダメージを2回与える。2ターン持続",
  str_skill_desc_303064 = "オーバーロード状態になり、ラスの連鎖技ダメージ+<color=#00F6FF>50%</color>、かつ最も近くの敵1体にダメージを2回与える。2ターン持続",
  str_skill_desc_306064 = "オーバーロード状態になり、ラスの連鎖技ダメージ+<color=#00F6FF>50%</color>、かつ最も近くの敵1体にダメージを2回与える。2ターン持続",
  str_skill_desc_320064 = "オーバーロード状態になり、ラスの連鎖技ダメージ+<color=#00F6FF>50%</color>、かつ最も近くの敵1体にダメージを2回与える。2ターン持続",
  str_skill_desc_323064 = "オーバーロード状態になり、ラスの連鎖技ダメージ+<color=#00F6FF>50%</color>、かつ最も近くの敵1体にダメージを2回与える。2ターン持続",
  str_skill_desc_326064 = "オーバーロード状態になり、ラスの連鎖技ダメージ+<color=#00F6FF>50%</color>、かつ最も近くの敵1体にダメージを2回与える。2ターン持続",
  str_skill_desc_300070 = "戦場のランダムな敵に<color=#00F6FF>90%</color>のダメージを<color=#00F6FF>5</color>回与え、現在地の<color=#00F6FF>周囲1マス</color>にある火属性のマス1つにつき、追加で1回攻撃する",
  str_skill_desc_302070 = "戦場のランダムな敵に<color=#00F6FF>90%</color>のダメージを<color=#00F6FF>5</color>回与え、現在地の<color=#00F6FF>周囲1マス</color>にある火属性のマス1つにつき、追加で1回攻撃する",
  str_skill_desc_305070 = "戦場のランダムな敵に<color=#00F6FF>90%</color>のダメージを<color=#00F6FF>6</color>回与え、現在地の<color=#00F6FF>菱形12マス</color>以内にある火属性のマス1つにつき、追加で1回攻撃する",
  str_skill_desc_300088 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、ノックバックする。さらに攻撃範囲内のマスを火属性に変える",
  str_skill_desc_302088 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、ノックバックする。さらに攻撃範囲内のマスを火属性に変換する",
  str_skill_desc_305088 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、ノックバックする。さらに攻撃範囲内のマスを火属性に変換する",
  str_skill_desc_300084 = "使用すると、そのターンで火属性の光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての火属性の光霊の攻撃力がイスタバンの攻撃力の<color=#00F6FF>70%</color>になる",
  str_skill_desc_302084 = "使用すると、そのターンで火属性の光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての火属性の光霊の攻撃力がイスタバンの攻撃力の<color=#00F6FF>70%</color>になる",
  str_skill_desc_305084 = "使用すると、そのターンで火属性の光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての火属性の光霊の攻撃力がイスタバンの攻撃力の<color=#00F6FF>70%</color>になる",
  str_skill_desc_330084 = "使用すると、そのターンで火属性の光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての火属性の光霊の攻撃力がイスタバンの攻撃力の<color=#00F6FF>85%</color>になる",
  str_skill_desc_332084 = "使用すると、そのターンで火属性の光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての火属性の光霊の攻撃力がイスタバンの攻撃力の<color=#00F6FF>85%</color>になる",
  str_skill_desc_335084 = "使用すると、そのターンで火属性の光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての火属性の光霊の攻撃力がイスタバンの攻撃力の<color=#00F6FF>85%</color>になる",
  str_skill_desc_300090 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与え、火属性のマスにいる敵を必ず眩暈状態にする",
  str_skill_desc_302090 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与え、火属性のマスにいる敵を必ず眩暈状態にする",
  str_skill_desc_320090 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。火属性のマスにいる敵を必ず眩暈状態にし、他の属性のマスにいる敵を<color=#00F6FF>35%</color>の確率で眩暈状態にする",
  str_skill_desc_322090 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。火属性のマスにいる敵を必ず眩暈状態にし、他の属性のマスにいる敵を<color=#00F6FF>35%</color>の確率で眩暈状態にする",
  str_skill_desc_300045 = "マスを1つ選択し、自身のHP<color=#00F6FF>15%</color>を消費して、<color=#00F6FF>正方形9マス</color>範囲内の敵に消費したHPと同量の防御力無視ダメージを1回与える。さらに<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_320045 = "マスを1つ選択し、自身のHPの<color=#00F6FF>15%</color>を消費して、<color=#00F6FF>正方形9マス</color>範囲内の敵に消費したHPと同量の防御力無視ダメージを1回与える。さらに出血状態を<link=\"30004\"><#FFAE07><u>1スタック</u></color></link>付与する。2ターン持続",
  str_skill_desc_330045 = "マスを1つ選択し、自身のHPの<color=#00F6FF>15%</color>を消費して、<color=#00F6FF>正方形9マス</color>範囲内の敵に消費したHPと同量の防御力無視ダメージを1回与える。さらに出血状態を<link=\"30004\"><#FFAE07><u>1スタック</u></color></link>付与する。2ターン持続。ネイルスのHP上限+<color=#00F6FF>50%</color>",
  str_skill_desc_300081 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。さらに敵全体を自分の周囲に引き寄せる",
  str_skill_desc_320081 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。さらに敵全体を自分の周囲に引き寄せ、敵が1マス移動するごとに最終ダメージ+<color=#00F6FF>10%</color>",
  str_skill_desc_300083 = "1マス選択し、その場所から<color=#00F6FF>十字方向4マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを与え、ノックバックする",
  str_skill_desc_320083 = "1マス選択し、その場所の<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_330083 = "1マス選択し、その場所から<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらにその敵の防御力を減少させる。減少割合はこのスキルで与えるダメージの比率と同じ。2ターン持続",
  str_skill_desc_300059 = "自分の<color=#00F6FF>周囲1マス</color>以内の任意の位置に移動できる",
  str_skill_desc_3000591 = "自分の<color=#00F6FF>周囲1マス</color>以内の好きな位置に移動できる",
  str_skill_desc_3000592 = "自分の<color=#00F6FF>周囲2マス</color>以内の任意の位置に移動できる",
  str_skill_desc_3000593 = "自分の<color=#00F6FF>周囲3マス</color>以内の任意の位置に移動できる",
  str_skill_desc_3000594 = "自分の<color=#00F6FF>周囲4マス</color>以内の任意の位置に移動できる",
  str_skill_desc_3000595 = "自分の<color=#00F6FF>周囲5マス</color>以内の任意の位置に移動できる",
  str_skill_desc_300080 = "選択した1マスに缶を投げ、そのマスを雷属性にする。さらに落雷の結晶、隕石の結晶、包帯、攻撃力、防御力の中からランダムで1種類のアイテムをそのマスに生成する",
  str_skill_desc_320080 = "選択した1マスに缶を投げ、そのマスを雷属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>にする。さらに落雷の結晶、隕石の結晶、包帯、攻撃力、防御力の中からランダムで1種類のアイテムをそのマスに生成する",
  str_skill_desc_300093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは２倍になる",
  str_skill_desc_306093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは２倍になる。能動技で敵を倒すと再び使用できる（1ターンに1回のみ）",
  str_skill_desc_310093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは２倍になる",
  str_skill_desc_316093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは２倍になる。能動技で敵を倒すと再び使用できる（1ターンに1回のみ）",
  str_skill_desc_320093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは２倍になる。敵1体を倒すごとに最終ダメージ+<color=#00F6FF>15%</color>。10回まで累積できる",
  str_skill_desc_326093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは２倍になる。敵1体を倒すごとに最終ダメージ+<color=#00F6FF>15%</color>。10回まで累積できる。能動技で敵を倒すと再び使用できるが、1ターンに1回のみ",
  str_skill_desc_330093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは２倍になる。敵1体を倒すごとに最終ダメージ+<color=#00F6FF>15%</color>。10回まで累積できる",
  str_skill_desc_336093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは２倍になる。敵1体を倒すごとに最終ダメージ+<color=#00F6FF>15%</color>。10回まで累積できる。能動技で敵を倒すと再び使用できるが、1ターンに1回のみ",
  str_skill_desc_300097 = "任意の位置に瞬間移動し、スタート地点と到着地点の間の長方形の範囲内にいる敵にダメージを与える。長方形の範囲が小さいほど、与えるダメージが大きくなり、最大で<color=#00F6FF>480%</color>のダメージを与える",
  str_skill_desc_302097 = "任意の位置に瞬間移動し、スタート地点と到着地点の間の長方形の範囲内にいる敵にダメージを与える。長方形の範囲が小さいほど、与えるダメージが大きくなり、最大で<color=#00F6FF>600%</color>のダメージを与える",
  str_skill_desc_300095 = "1マス選択し、その位置<color=#00F6FF>とX形の4マス</color>の範囲にそれぞれ地雷を1個設置する。地雷に触れた敵に<color=#00F6FF>190%</color>のダメージを与え、<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_320095 = "1マス選択し、その位置<color=#00F6FF>とX形の4マス</color>の範囲にそれぞれ地雷を1個設置する。地雷に触れた敵に<color=#00F6FF>190%</color>のダメージ（選択したマスはダメージ2倍）を与え、<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_330095 = "1マス選択し、その位置<color=#00F6FF>とX形の4マス</color>の範囲にそれぞれ地雷を1個設置する。地雷に触れた敵に<color=#00F6FF>190%</color>のダメージ（選択したマスはダメージ2倍）を与え、<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_300062 = "自分の周囲<color=#00F6FF>8</color>方向の最も遠いマスから1つ選択し、その位置までダッシュする。さらに途中のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320062 = "戦場の端にあるマスから1つ選択し、その位置までダッシュする。さらに途中のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300024 = "マス1つをマークする。今回の連鎖マスの数が連鎖技発動に必要な数の<color=#00F6FF>2</color>倍に到達すると、マークした位置でも連鎖技を1回発動する",
  str_skill_desc_305024 = "マス1つをマークする。今回の連鎖マスの数が連鎖技発動に必要な数の<color=#00F6FF>2</color>倍に到達すると、マークした位置でも連鎖技を1回発動する",
  str_skill_desc_320024 = "マス1つをマークする。今回の連鎖マスの数が連鎖技発動に必要な数の<color=#00F6FF>2</color>倍に到達すると、マークした位置でも連鎖技を1回発動する（2ヵ所の連鎖技の最終ダメージはいずれも+<color=#00F6FF>30%</color>）",
  str_skill_desc_325024 = "マス1つをマークする。今回の連鎖マスの数が連鎖技発動に必要な数の<color=#00F6FF>2</color>倍に到達すると、マークした位置でも連鎖技を1回発動する（2ヵ所の連鎖技の最終ダメージはいずれも+<color=#00F6FF>30%</color>）",
  str_skill_desc_330024 = "マス1つをマークする。今回の連鎖マスの数が連鎖技発動に必要な数の<color=#00F6FF>1.5</color>倍に到達すると、マークした位置でも連鎖技を1回発動する（2ヵ所の連鎖技の最終ダメージはいずれも+<color=#00F6FF>30%</color>）",
  str_skill_desc_335024 = "マス1つをマークする。今回の連鎖マスの数が連鎖技発動に必要な数の<color=#00F6FF>1.5</color>倍に到達すると、マークした位置でも連鎖技を1回発動する（2ヵ所の連鎖技の最終ダメージはいずれも+<color=#00F6FF>30%</color>）",
  str_skill_desc_300087 = "最も近くの火属性のマス<color=#00F6FF>4</color>つを雷属性に変える",
  str_skill_desc_302087 = "最も近くの火属性のマス<color=#00F6FF>4</color>つを雷属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_305087 = "最も近くの火属性のマス<color=#00F6FF>5</color>つを雷属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_330087 = "最も近くの火属性のマス<color=#00F6FF>4</color>つを雷属性に変える。一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで",
  str_skill_desc_332087 = "最も近くの火属性のマス<color=#00F6FF>4</color>つを雷属性に変える。一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_335087 = "最も近くの火属性のマス<color=#00F6FF>5</color>つを雷属性に変える。一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3020871 = "最も近くの火属性のマス<color=#00F6FF>4</color>つを雷属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3050871 = "最も近くの火属性のマス<color=#00F6FF>5</color>つを雷属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3320871 = "最も近くの火属性のマス<color=#00F6FF>4</color>つを雷属性に変える。一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3350871 = "最も近くの火属性のマス<color=#00F6FF>5</color>つを雷属性に変える。一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_300101 = "<color=#00F6FF>周囲2マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の全てのマスをリセットする",
  str_skill_desc_330101 = "<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。さらに範囲内全ての<color=#00F6FF>非雷属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で雷属性のマスに変える",
  str_skill_desc_300102 = "自分の周囲<color=#00F6FF>4</color>方向から1つを選択し、選択した方向とその隣接する行または列にいる全ての敵を引き寄せる。さらに引き寄せた敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300099 = "魔剣を発動させ、このターンの自分の攻撃力+<color=#00F6FF>20%</color>。終了後、攻撃力と防御力-<color=#00F6FF>50%</color>、1ターン持続",
  str_skill_desc_305099 = "魔剣を発動させ、このターンの自分の攻撃力+<color=#00F6FF>25%</color>。終了後、攻撃力と防御力-<color=#00F6FF>50%</color>、1ターン持続",
  str_skill_desc_330099 = "魔剣を発動させ、このターンの自分の攻撃力+<color=#00F6FF>20%</color>。終了後、攻撃力と防御力-<color=#00F6FF>50%</color>、1ターン持続。魔剣が発動している間に敵を倒すと、攻撃力・防御力の低下状態を無効化する",
  str_skill_desc_335099 = "魔剣を発動させ、このターンの自分の攻撃力+<color=#00F6FF>25%</color>。終了後、攻撃力と防御力-<color=#00F6FF>50%</color>、1ターン持続。魔剣が発動している間に敵を倒すと、攻撃力・防御力の低下状態を無効化する",
  str_skill_desc_300100 = "十字方向の最大範囲に<color=#00F6FF>{1}%</color>のダメージを与え、ノックバックする。さらに攻撃範囲内のマスを森属性に変える",
  str_skill_desc_302100 = "十字方向の最大範囲に<color=#00F6FF>{1}%</color>のダメージを与え、ノックバックする。さらに攻撃範囲内のマスを森属性に変換する",
  str_skill_desc_300098 = "自分の<color=#00F6FF>周囲3マス</color>以内から敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。その敵が小型でノックバックが可能な場合、攻撃範囲内の選択した位置に移動させる",
  str_skill_desc_305098 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。その敵が小型でノックバックが可能な場合、攻撃範囲内の選択した位置に移動させる",
  str_skill_desc_330098 = "自身の<color=#00F6FF>周囲3マス</color>以内から敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。その敵が小型でノックバックが可能な場合、攻撃範囲内の選択した位置に移動させる。印のあるターゲットを倒すと、その<color=#00F6FF>周囲1マス</color>の敵にクスッタの攻撃力の<color=#00F6FF>40%</color>の防御力無視のダメージを与える",
  str_skill_desc_335098 = "任意の敵1体を選び、<color=#00F6FF>{1}%</color>のダメージを与える。その敵が小型でノックバックが可能な場合、攻撃範囲内の選択した位置に移動させる。印のあるターゲットを倒すと、その<color=#00F6FF>周囲1マス</color>の敵にクスッタの攻撃力<color=#00F6FF>40%</color>の防御力無視ダメージを与える",
  str_skill_desc_300094 = "現在地を記録し、光霊の連鎖技あるいは移動が終了すると記録した位置に戻る",
  str_skill_desc_300096 = "最も近くの火または森属性のマス<color=#00F6FF>4</color>つを水属性に変える",
  str_skill_desc_303096 = "最も近くの火または森属性のマス<color=#00F6FF>4</color>つを水属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_306096 = "最も近くの火または森属性のマス<color=#00F6FF>5</color>つを水属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_330096 = "最も近くの火または森属性のマス<color=#00F6FF>4</color>つを水属性に変える（一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで）",
  str_skill_desc_333096 = "最も近くの火または森属性のマス<color=#00F6FF>4</color>つを水属性に変える（一定確率で<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が出現する。最大2マスまで）。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
