  str_skill_desc_3061031 = "最も近くの水または森属性のマス<color=#00F6FF>5</color>つを火属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_300067 = "このターン、次に受けるダメージ-<color=#00F6FF>30%</color>、最大はアリスHP上限の<color=#00F6FF>2</color>倍減少する",
  str_skill_desc_304067 = "このターン、次に受けるダメージ-<color=#00F6FF>40%</color>、最大はアリスのHP上限の<color=#00F6FF>2</color>倍まで",
  str_skill_desc_320067 = "このターン、次に受けるダメージ-<color=#00F6FF>30%</color>。ダメージを受けた時、失ったチームHPの<color=#00F6FF>10%</color>を即座に回復させる。ダメージ軽減量もHP回復量もアリスのHP上限の<color=#00F6FF>2</color>倍まで",
  str_skill_desc_324067 = "このターン、次に受けるダメージ-<color=#00F6FF>40%</color>。ダメージを受けた時、失ったチームHPの<color=#00F6FF>10%</color>を即座に回復させる。ダメージ軽減量もHP回復量もアリスのHP上限の<color=#00F6FF>2</color>倍まで",
  str_skill_desc_300104 = "敵全体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_310104 = "敵全体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320104 = "敵全体に<color=#00F6FF>{1}%</color>のダメージを与える。命中した敵が2体以下の場合、そのターンに1回再発動できる",
  str_skill_desc_300030 = "自身の周囲<color=#00F6FF>十字方向4マス</color>から1マス選び、その方向の扇形エリアに<color=#00F6FF>{1}%</color>のダメージを与える（敵がサメヤマに近いほどダメージは大きくなる。最高2.5倍）",
  str_skill_desc_306030 = "自身の周囲<color=#00F6FF>十字方向4マス</color>から1マス選び、その方向の扇形エリアに<color=#00F6FF>{1}%</color>のダメージを与える（敵がサメヤマに近いほどダメージは大きくなる。最高3倍）",
  str_skill_desc_320030 = "自身の周囲<color=#00F6FF>十字方向8マス</color>から1マス選び、その方向の扇形エリアに<color=#00F6FF>{1}%</color>のダメージを与える（敵がサメヤマに近いほどダメージは大きくなる。最高2.5倍）。外周のマスを選んだ場合、サメヤマは前へ1マス進んでから技を発動する",
  str_skill_desc_326030 = "自身の周囲<color=#00F6FF>十字方向8マス</color>から1マス選び、その方向の扇形エリアに<color=#00F6FF>{1}%</color>のダメージを与える（敵がサメヤマに近いほどダメージは大きくなる。最高3倍）。外周のマスを選んだ場合、サメヤマは前へ1マス進んでから技を発動する",
  str_skill_desc_330030 = "自身の周囲<color=#00F6FF>十字方向8マス</color>から1マス選び、その方向の扇形エリアに<color=#00F6FF>{1}%</color>のダメージを与える（敵がサメヤマに近いほどダメージは大きくなる。最高2.5倍）。外周のマスを選んだ場合、サメヤマは前へ1マス進んでから技を発動する",
  str_skill_desc_336030 = "自身の周囲<color=#00F6FF>十字方向8マス</color>から1マス選び、その方向の扇形エリアに<color=#00F6FF>{1}%</color>のダメージを与える（敵がサメヤマに近いほどダメージは大きくなる。最高3倍）。外周のマスを選んだ場合、サメヤマは前へ1マス進んでから技を発動する",
  str_skill_desc_300071 = "<color=#00F6FF>十字</color>方向から1マス選択して火属性の強化マスに変える。同時に火龍を放ち、途中のマスに<color=#00F6FF>{1}%</color>のダメージを与える。選択したマスに火龍が到達した後、<color=#00F6FF>左右両側</color>方向の最も遠くまで広がり、80%のダメージを与える",
  str_skill_desc_305071 = "<color=#00F6FF>十字</color>方向から1マス選択して火属性の強化マスに変える。同時に火龍を放ち、途中のマスに<color=#00F6FF>{1}%</color>のダメージを与える。選択したマスに火龍が到達した後、<color=#00F6FF>左右両側</color>方向の最も遠くまで広がり、80%のダメージを与える。さらに最も遠くにあるマスを火属性に変える",
  str_skill_desc_320071 = "<color=#00F6FF>十字</color>方向から1マス選択して火属性の強化マスに変える。同時に火龍を放ち、途中のマスに<color=#00F6FF>{1}%</color>のダメージを与える。選択したマスに火龍が到達した後、<color=#00F6FF>左右両側</color>方向の最も遠くまで広がり、80%のダメージを与える。火龍がダメージを与える前、ターゲットに灼印を付与する",
  str_skill_desc_325071 = "<color=#00F6FF>十字</color>方向から1マス選択して火属性の強化マスに変える。同時に火龍を放ち、途中のマスに<color=#00F6FF>{1}%</color>のダメージを与える。選択したマスに火龍が到達した後、<color=#00F6FF>左右両側</color>方向の最も遠くまで広がり、80%のダメージを与える。さらに最も遠くにあるマスを火属性に変える。火龍がダメージを与える前、ターゲットに灼印を付与する",
  str_skill_desc_300105 = "敵のいるマスを1つ選び、その敵に<color=#00F6FF>40%</color>のダメージを20回与え、敵を撃破した場合、最も近くにいる別の敵を新しいターゲットとして選択する。現在地の<color=#00F6FF>周囲1マス</color>にある雷属性マス1つにつき、能動技のダメージを1回追加。",
  str_skill_desc_306105 = "敵のいるマスを1つ選び、その敵に<color=#00F6FF>40%</color>のダメージを20回与え、敵を撃破した場合、最も近くにいる別の敵を新しいターゲットとして選択する。現在地の<color=#00F6FF>周囲2マス</color>にある雷属性マス1つにつき、能動技のダメージを1回追加。",
  str_skill_desc_330105 = "敵のいるマスを1つ選び、その敵に<color=#00F6FF>40%</color>のダメージを20回与え、ダメージが毎回<color=#00F6FF>0.8%</color>アップする。敵を撃破した場合、最も近くにいる別の敵を新しいターゲットとして選択し、最後に攻撃したターゲットの防御力-10%、1ターン持続。現在地の<color=#00F6FF>周囲1マス</color>にある雷属性マス1つにつき、能動技のダメージを1回追加。",
  str_skill_desc_336105 = "敵のいるマスを1つ選び、その敵に<color=#00F6FF>40%</color>のダメージを20回与え、ダメージが毎回<color=#00F6FF>0.8%</color>アップする。敵を撃破した場合、最も近くにいる別の敵を新しいターゲットとして選択し、最後に攻撃したターゲットの防御力-10%、1ターン持続。現在地の<color=#00F6FF>周囲2マス</color>にある雷属性マス1つにつき、能動技のダメージを1回追加。",
  str_skill_desc_330109 = "フォースを<color=#00F6FF>10</color>消費して残りのフォースをクリアし、選択した方向の途中および隣接するマスにいる敵に<color=#00F6FF><color=#00F6FF>150%</color></color>のダメージを与える。クリアされたフォース1につき最終ダメージ+<color=#00F6FF>8%</color>",
  str_skill_desc_330110 = "フォースを<color=#00F6FF>10</color>消費して残りのフォースをクリアし、敵全体に<color=#00F6FF>150%</color>のダメージを与える。クリアされたフォース1につきダメージ+<color=#00F6FF>15%</color>",
  str_skill_desc_336110 = "フォースを<color=#00F6FF>10</color>消費して残りのフォースをクリアし、敵全体に<color=#00F6FF>150%</color>のダメージを与える。クリアされたフォース1につきダメージ+<color=#00F6FF>15%</color>。さらにターゲットの防御力を<color=#00F6FF>1%</color>無視する",
  str_skill_desc_330107 = "このターンはフォースを<color=#00F6FF>10</color>消費して強化状態になる。通常攻撃で斜め方向に攻撃でき、さらに通常攻撃と連鎖ダメージそれぞれ+<color=#00F6FF>20%</color>（繰り返して発動すると重ね掛け可能）",
  str_skill_desc_333107 = "このターンはフォースを<color=#00F6FF>10</color>消費して強化状態になる。通常攻撃で斜め方向に攻撃でき、さらに通常攻撃と連鎖ダメージそれぞれ+<color=#00F6FF>20%</color>（繰り返して発動すると重ね掛け可能）。強化状態で敵を1体倒すたびに、フォースを2獲得する",
  str_skill_desc_336107 = "このターンはフォースを<color=#00F6FF>10</color>消費して強化状態になる。通常攻撃で斜め方向に攻撃でき、さらに通常攻撃と連鎖ダメージそれぞれ+<color=#00F6FF>20%</color>（繰り返して発動すると重ね掛け可能）。強化状態で敵を1体倒すたびに、フォースを2獲得する",
  str_skill_desc_330108 = "フォースを<color=#00F6FF>10</color>消費して、任意の1マスを選び<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に半分の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。1ターン内に複数回発動できる",
  str_skill_desc_333108 = "フォースを<color=#00F6FF>10</color>消費して、任意の1マスを選び<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に半分の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。1ターン内に複数回発動できる",
  str_skill_desc_336108 = "フォースを<color=#00F6FF>10</color>消費して、任意の1マスを選び<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に半分の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。1回発動するごとに基礎攻撃力+<color=#00F6FF>3%</color>。1ターン内に複数回発動できる",
  str_skill_desc_300112 = "自身の<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>非火属性</color>のマスを全てリセットする",
  str_skill_desc_301112 = "任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>火属性以外</color>のマスを全てリセットする",
  str_skill_desc_303112 = "任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>火属性以外</color>のマスを全てリセットする。敵のいるマス1つ以上を火属性に変える",
  str_skill_desc_320112 = "自身の<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>非火属性</color>のマスを全てリセットする",
  str_skill_desc_321112 = "任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>火属性以外</color>のマスを全てリセットする",
  str_skill_desc_323112 = "任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>火属性以外</color>のマスを全てリセットする。敵のいるマス1つ以上を火属性に変える",
  str_skill_desc_330112 = "自身の<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>非火属性</color>のマスを全てリセットする。<color=#00F6FF>炎のキス</color>の効果発動後、ターゲットの炎のキスの印がクリアされる",
  str_skill_desc_331112 = "任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>火属性以外</color>のマスを全てリセットする。<color=#00F6FF>炎のキス</color>の効果発動後、ターゲットの炎のキスの印がクリアされる",
  str_skill_desc_333112 = "任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>火属性以外</color>のマスを全てリセットする。<color=#00F6FF>炎のキス</color>の効果発動後、ターゲットの炎のキスの印がクリアされる。敵のいるマス1つ以上を火属性に変える",
  str_skill_desc_300113 = "自身の周囲<color=#00F6FF>4</color>方向から1方向を選び、BOSS以外の全ての小型の敵をその方向に1マス強制移動させ、敵全体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_305113 = "自身の周囲<color=#00F6FF>4</color>方向から1方向を選び、BOSS以外の全ての小型の敵をその方向に1マス強制移動させ、敵全体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_330113 = "自身の周囲<color=#00F6FF>4</color>方向から1方向を選び、BOSS以外の全ての小型の敵をその方向に1マス強制移動させ、敵全体に<color=#00F6FF>{1}%</color>のダメージを与える。命中した敵が2体以下の場合、そのターンに1回再発動できる",
  str_skill_desc_335113 = "自身の周囲<color=#00F6FF>4</color>方向から1方向を選び、BOSS以外の全ての小型の敵をその方向に1マス強制移動させ、敵全体に<color=#00F6FF>{1}%</color>のダメージを与える。命中した敵が2体以下の場合、そのターンに1回再発動できる",
  str_skill_desc_300114 = "前後左右の各1方向に２マス進んだ、その左右の8マスいずれかに瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_302114 = "前後左右の各1方向に２マス進んだ、その左右の8マスいずれかに瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。能動技を発動すると、そのターンの連鎖技で範囲内の全ての敵を攻撃できる",
  str_skill_desc_305114 = "前後左右の各1方向に２マス進んだ、その左右の8マスいずれかに瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。能動技を発動すると、そのターンの連鎖技では範囲内の全ての敵を攻撃できる。1体の敵にしか命中しなかった場合、このターンに1回再発動できる",
  str_skill_desc_320114 = "前後左右の各1方向に２マス進んだ、その左右の8マスいずれかに瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。能動技を発動すると、そのターン連鎖技の範囲+1マス",
  str_skill_desc_322114 = "前後左右の各1方向に２マス進んだ、その左右の8マスいずれかに瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。能動技を発動すると、そのターン連鎖技の範囲+1マスおよび範囲内の全ての敵を攻撃できる",
  str_skill_desc_325114 = "前後左右の各1方向に２マス進んだ、その左右の8マスいずれかに瞬間移動し、瞬間移動した位置の<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。能動技を発動すると、そのターンの連鎖技の範囲+1マスおよび範囲内の全ての敵を攻撃できる。1体の敵にしか命中しなかった場合、このターンに1回再発動できる",
  str_skill_desc_300127 = "1マス選んで（深淵マスも選択可）折り鶴を1個置き、そのマスを森属性に転色する。チームが折り鶴を通過すると折り鶴は消える。",
  str_skill_desc_304127 = "1マス選んで（深淵マスも選択可）折り鶴を1個置き、そのマスを森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。チームが折り鶴を通過すると折り鶴は消える。",
  str_skill_desc_320127 = "1マス選んで（深淵マスも選択可）折り鶴を1個置き、そのマスを森属性に転色する。チームが折り鶴を通過すると折り鶴は消える。折り鶴が消えると、下方の深淵マス以外のマスが森属性に転色する。",
  str_skill_desc_324127 = "1マス選んで（深淵マスも選択可）折り鶴を1個置き、そのマスを森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。チームが折り鶴を通過すると折り鶴は消える。折り鶴が消えると、下方の深淵マス以外のマスが森属性に転色する。",
  str_skill_desc_300117 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_303117 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_306117 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。前のターンで能動技が発動可能だった場合、移動範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_3061171 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。前のターンで能動技が発動可能だった場合、このターンの移動範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_320117 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。外側のマスに与えるダメージは内側のマスの1.5倍",
  str_skill_desc_323117 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。外側のマスに与えるダメージは内側のマスの1.5倍",
  str_skill_desc_326117 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。外側のマスに与えるダメージは内側のマスの1.5倍。前のターンで能動技が発動可能だった場合、このターンの移動範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_3261171 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。外側のマスに与えるダメージは内側のマスの1.5倍。前のターンで能動技が発動可能だった場合、このターンの移動範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_330117 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。外側のマスに与えるダメージは内側のマスの1.5倍",
  str_skill_desc_333117 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。外側のマスに与えるダメージは内側のマスの1.5倍",
  str_skill_desc_336117 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。外側のマスに与えるダメージは内側のマスの1.5倍。前のターンで能動技が発動可能だった場合、このターンの移動範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_3361171 = "自身の<color=#00F6FF>周囲菱形12マス</color>以内の任意の位置に瞬間移動し、瞬間移動した位置の<color=#00F6FF>八角形20マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。外側のマスに与えるダメージは内側のマスの1.5倍。前のターンで能動技が発動可能だった場合、このターンの移動範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_300119 = "自身の周囲<color=#00F6FF>4</color>方向から1つを選択し、前方3列の範囲に稲妻を3本放ち、<color=#00F6FF>250%</color>のダメージを与える。稲妻はそれぞれターゲットに命中するたびにダメージ-<color=#00F6FF>40%</color>、最大でダメージを<color=#00F6FF>3</color>回与える",
  str_skill_desc_306119 = "自身の周囲<color=#00F6FF>4</color>方向から1つを選択し、前方3列の範囲に稲妻を3本放ち、<color=#00F6FF>250%</color>のダメージを与える。稲妻はそれぞれターゲットに命中するたびにダメージ-<color=#00F6FF>20%</color>、最大でダメージを<color=#00F6FF>5</color>回与える",
  str_skill_desc_300122 = "1マス選択し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_305122 = "1マス選択し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。さらに範囲内の<color=#00F6FF>マス損傷</color>効果をクリアする",
  str_skill_desc_320122 = "1マス選択し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、選択したマスに防御力無視のダメージを与える",
  str_skill_desc_325122 = "1マス選択し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、選択したマスに防御力無視のダメージを与える。さらに範囲内の<color=#00F6FF>マス損傷</color>効果をクリアする",
  str_skill_desc_330122 = "1マス選択し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、選択したマスに防御力無視のダメージを与える。祝福が10スタックになると能動技の範囲が<color=#00F6FF>縦、横、斜めの最大</color>範囲になる",
  str_skill_desc_3301221 = "1マス選択し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、選択したマスに防御力無視のダメージを与える。祝福が10スタックになると能動技の範囲が<color=#00F6FF>縦、横、斜めの最大</color>範囲になる",
  str_skill_desc_335122 = "1マス選択し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、選択したマスに防御力無視のダメージを与える。さらに範囲内の<color=#00F6FF>マス損傷</color>効果をクリアし、祝福が10スタックになると能動技の範囲が<color=#00F6FF>縦、横、斜めの最大</color>範囲になる",
  str_skill_desc_300121 = "1マス選択し、そのマスを中心として選んだ1方向に藤蔓を端のマスまで伸ばし、範囲内に<color=#00F6FF>360%</color>のダメージを与える。さらに前方<color=#00F6FF>2</color>マスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。藤蔓が1マス広がるごとに、ダメージ+<color=#00F6FF>10%</color>",
  str_skill_desc_306121 = "1マス選択し、そのマスを中心として選んだ1方向に藤蔓を端のマスまで伸ばし、範囲内に<color=#00F6FF>360%</color>のダメージを与える。さらに前方<color=#00F6FF>3</color>マスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。藤蔓が1マス広がるごとに、ダメージ+<color=#00F6FF>15%</color>",
  str_skill_desc_320121 = "1マス選択し、そのマスを中心として選んだ1方向に藤蔓を端のマスまで伸ばし、範囲内に<color=#00F6FF>360%</color>のダメージを与える。さらに前方<color=#00F6FF>2</color>マスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。藤蔓はダメージを与えた後、十字方向にそれぞれ<color=#00F6FF>3</color>マス広がる。藤蔓が広がるのは敵1体につき1回のみ。藤蔓が1マス広がるごとに、ダメージ+<color=#00F6FF>10%</color>",
  str_skill_desc_326121 = "1マス選択し、そのマスを中心として選んだ1方向に藤蔓を端のマスまで伸ばし、範囲内に<color=#00F6FF>360%</color>のダメージを与える。さらに前方<color=#00F6FF>3</color>マスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。藤蔓はダメージを与えた後、十字方向にそれぞれ<color=#00F6FF>3</color>マス広がる。藤蔓が広がるのは敵1体につき1回のみ。藤蔓が1マス広がるごとに、ダメージ+<color=#00F6FF>15%</color>",
  str_skill_desc_300065 = "自身の<color=#00F6FF>周囲2マス</color>と戦場にある水属性の全マスの中から任意の位置を指定して瞬間移動できる",
  str_skill_desc_330065 = "自身の<color=#00F6FF>周囲2マス</color>と戦場にある水属性の全マスの中から任意の位置を指定して瞬間移動できる。極光タイム発動時、もう1回発動できる",
  str_skill_desc_300115 = "指定した位置に瞬間移動し、<color=#00F6FF>周囲2マス</color>および他のマスの一部に対して<link=\"30020\"><#FFAE07><u>浄化</u></color></link>を行う。浄化範囲のうち<color=#00F6FF>3</color>マスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える",
  str_skill_desc_305115 = "指定した位置に瞬間移動し、<color=#00F6FF>周囲2マス</color>および他のマスの一部に対して<link=\"30020\"><#FFAE07><u>浄化</u></color></link>を行う。浄化範囲のうち<color=#00F6FF>4</color>マスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える",
  str_skill_desc_320115 = "指定した位置に瞬間移動し、<color=#00F6FF>周囲3マス</color>および他のマスの一部に対して<link=\"30020\"><#FFAE07><u>浄化</u></color></link>を行う。浄化範囲のうち<color=#00F6FF>4</color>マスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える",
  str_skill_desc_325115 = "指定した位置に瞬間移動し、<color=#00F6FF>周囲3マス</color>および他のマスの一部に対して<link=\"30020\"><#FFAE07><u>浄化</u></color></link>を行う。浄化範囲のうち<color=#00F6FF>5</color>マスを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える",
  str_skill_desc_300126 = "進入可能なマスを1つ選択し、<color=#00F6FF>十字形5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_303126 = "進入可能なマスを1つ選択し、<color=#00F6FF>十字形5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_306126 = "進入可能なマスを1つ選択し、<color=#00F6FF>十字形5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。極光タイム発動時、発動可能になる（各ウェーブ1回まで）",
  str_skill_desc_310126 = "進入可能なマスを1つ選択し、<color=#00F6FF>十字形5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_313126 = "進入可能なマスを1つ選択し、<color=#00F6FF>十字形5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_316126 = "進入可能なマスを1つ選択し、<color=#00F6FF>十字形5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。極光タイム発動時、発動可能になる（各ウェーブ1回まで）",
  str_skill_desc_320126 = "進入可能なマスを1つ選択し、<color=#00F6FF>十字形5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_323126 = "進入可能なマスを1つ選択し、<color=#00F6FF>十字形5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_326126 = "進入可能なマスを1つ選択し、<color=#00F6FF>十字形5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。極光タイム発動時、発動可能になる（各ウェーブ1回まで）",
  str_skill_desc_300129 = "<link=\"30021\"><#FFAE07><u>命の卵</u></color></link>を全て消費して1体の敵にダメージを与える。<link=\"30021\"><#FFAE07><u>命の卵</u></color></link>1個につき<color=#00F6FF>40%</color>のダメージを与える",
  str_skill_desc_303129 = "<link=\"30022\"><#FFAE07><u>命の卵</u></color></link>を全て消費して1体の敵にダメージを与える。<link=\"30022\"><#FFAE07><u>命の卵</u></color></link>1個につき<color=#00F6FF>50%</color>のダメージを与える",
  str_skill_desc_306129 = "<link=\"30023\"><#FFAE07><u>命の卵</u></color></link>を全て消費して1体の敵にダメージを与える。<link=\"30023\"><#FFAE07><u>命の卵</u></color></link>1個につき<color=#00F6FF>50%</color>のダメージを与える",
  str_skill_desc_300055 = "1方向を選んで攻撃し、選んだ方向にいる全ての敵に<color=#00F6FF>160%</color>のダメージを与え、ノックバックする",
  str_skill_desc_302055 = "1方向を選んで攻撃し、選んだ方向にいる全ての敵に<color=#00F6FF>160%</color>のダメージを与え、ノックバックする。前のターンで能動技が発動可能だった場合、このターンの最終ダメージ+<color=#00F6FF>60%</color>",
  str_skill_desc_3020551 = "1方向を選んで攻撃し、選んだ方向にいる全ての敵に<color=#00F6FF>160%</color>のダメージを与え、ノックバックする。前のターンで能動技が発動可能だった場合、このターンの最終ダメージ+<color=#00F6FF>60%</color>",
  str_skill_desc_305055 = "1方向を選んで攻撃し、選んだ方向にいる全ての敵に<color=#00F6FF>160%</color>のダメージを与え、ノックバックする。敵を<color=#00F6FF>1</color>マスノックバックするごとに、最終ダメージ+<color=#00F6FF>5%</color>。前のターンで能動技が発動可能だった場合、このターンの最終ダメージ+<color=#00F6FF>60%</color>",
  str_skill_desc_3050551 = "1方向を選んで攻撃し、選んだ方向にいる全ての敵に<color=#00F6FF>160%</color>のダメージを与え、ノックバックする。敵を<color=#00F6FF>1</color>マスノックバックするごとに、最終ダメージ+<color=#00F6FF>5%</color>。前のターンで能動技が発動可能だった場合、このターンの最終ダメージ+<color=#00F6FF>60%</color>",
  str_skill_desc_300120 = "指定した位置に瞬間移動し、<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲のマスを森属性に変える",
  str_skill_desc_16012001 = "指定位置の縦方向1列の範囲に少量のダメージを与えて敵をノックバックする。さらに攻撃範囲内のマスを森属性に変える",
  str_skill_desc_16012002 = "指定位置の縦方向1列の範囲の敵をノックバックする。さらに攻撃範囲内のマスを森属性に変える",
  str_skill_desc_303120 = "指定した位置に瞬間移動し、<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲のマスを森属性に変える",
  str_skill_desc_300123 = "<color=#00F6FF>周囲1マス</color>以内の敵1体に<color=#00F6FF>{1}％</color>のダメージを与える。同一のターゲットに対して、1回目の命中時に1ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>効果を付与し、2回目の命中時に1ターンの<color=#00F6FF><color=#00F6FF>眩暈</color></color>効果を付与する",
  str_skill_desc_302123 = "<color=#00F6FF>周囲1マス</color>以内の敵1体に<color=#00F6FF>{1}％</color>のダメージを与える。同一のターゲットに対して、1回目の命中時に1ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>効果を付与し、2回目の命中時に1ターンの<color=#00F6FF><color=#00F6FF>眩暈</color></color>効果を付与する",
  str_skill_desc_305123 = "<color=#00F6FF>周囲1マス</color>以内の敵1体に<color=#00F6FF>{1}％</color>のダメージを与える。同じターゲットに対し、2回目まで命中時に<color=#00F6FF>眩暈</color>効果を付与する",
  str_skill_desc_320123 = "<color=#00F6FF>周囲1マス</color>以内の敵1体に<color=#00F6FF>{1}％</color>のダメージを与える。同一のターゲットに対して、1回目の命中時に1ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>効果を付与し、2回目の命中時に1ターンの<color=#00F6FF>眩暈</color>効果を付与する。ターゲットが占有するマス数が多いほど、能動技のダメージが増加する",
  str_skill_desc_322123 = "<color=#00F6FF>周囲1マス</color>以内の敵1体に<color=#00F6FF>{1}％</color>のダメージを与える。同一のターゲットに対して、1回目の命中時に1ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>効果を付与し、2回目の命中時に1ターンの<color=#00F6FF>眩暈</color>効果を付与する。ターゲットが占有するマス数が多いほど、能動技のダメージが増加する",
  str_skill_desc_325123 = "<color=#00F6FF>周囲1マス</color>以内の敵1体に<color=#00F6FF>{1}％</color>のダメージを与える。同一のターゲットに対して、命中時に2回まで1ターンの<color=#00F6FF>眩暈</color>効果を付与する。ターゲットが占有するマス数が多いほど、能動技のダメージが増加する",
  str_skill_desc_300015 = "進入可能なマスを1つ選択し、さらに方向を設定してギンを召喚する。ギンに向かって手榴弾1つを投げる。さらにギンは手榴弾を設定した方向の最遠まで弾く。手榴弾の進行経路にいる敵に<color=#00F6FF>200%</color>のダメージを与える",
  str_skill_desc_330015 = "進入可能なマスを1つ選択し、さらに方向を設定してギンを召喚する。ギンに向かって手榴弾1つを投げる。さらにギンは手榴弾を設定した方向の最遠まで弾く。手榴弾の進行経路にいる敵に<color=#00F6FF>200%</color>のダメージを与える。ギンの方向に斜めを選択できる",
  str_skill_desc_300131 = "ノーヴィオの攻撃力の<color=#00F6FF>220%</color>相当のチームHPを回復し、ノーヴィオのHPの<color=#00F6FF>90%</color>相当のシールドを獲得する。HPの回復量が上限を超えた場合、<color=#00F6FF>菱形12マス</color>の範囲内にいる敵に対して上限を超えた回復量に相当する防御力無視のダメージを与える",
  str_skill_desc_306131 = "ノーヴィオの攻撃力の<color=#00F6FF>220%</color>相当のチームHPを回復し、ノーヴィオのHPの<color=#00F6FF>120%</color>相当のシールドを獲得する。HPの回復量が上限を超えた場合、<color=#00F6FF>菱形12マス</color>の範囲内にいる敵に対して上限を超えた回復量に相当する防御力無視のダメージを与える",
  str_skill_desc_320131 = "ノーヴィオの攻撃力の<color=#00F6FF>220%</color>相当のチームHPを回復し、ノーヴィオのHPの<color=#00F6FF>90%</color>相当のシールドを獲得する。HPの回復量が上限を超えた場合、<color=#00F6FF>周囲2マス</color>の範囲内にいる敵に対して上限を超えた回復量に相当する防御力無視のダメージを与える。極光タイム発動時、シールドがHP上限を超えない分だけHPに変換される",
  str_skill_desc_326131 = "ノーヴィオの攻撃力の<color=#00F6FF>220%</color>相当のチームHPを回復し、ノーヴィオのHPの<color=#00F6FF>120%</color>相当のシールドを獲得する。HPの回復量が上限を超えた場合、<color=#00F6FF>周囲2マス</color>の範囲内にいる敵に対して上限を超えた回復量に相当する防御力無視のダメージを与える。極光タイム発動時、シールドがHP上限を超えない分だけHPに変換される",
  str_skill_desc_300132 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。ターン終了時に対象の敵がまだ生存している場合、その敵は今回の能動技によるダメージと同量のHPを回復する",
  str_skill_desc_302132 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。ターン終了時に対象の敵がまだ生存している場合、その敵は今回の能動技によるダメージと同量のHPを回復する。ターン終了時に今回の能動技による敵回復効果が発動した場合、自身の能動技のCDターン数<color=#00F6FF>-1</color>。",
  str_skill_desc_305132 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。ターン終了時に対象の敵がまだ生存している場合、その敵は今回の能動技によるダメージと同量のHPを回復する。ターン終了時に今回の能動技による敵回復効果が発動した場合、自身の能動技のCDターン数<color=#00F6FF>-1</color>。",
  str_skill_desc_320132 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。ターン終了時に対象の敵がまだ生存している場合、その敵は今回の能動技によるダメージと同量のHPを回復する。極光タイムを発動すると、この技によるターン終了時の敵回復効果が発動しなくなる",
  str_skill_desc_3201321 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。ターン終了時に対象の敵がまだ生存している場合、その敵は今回の能動技によるダメージと同量のHPを回復する。極光タイムを発動すると、この技によるターン終了時の敵回復効果が発動しなくなる",
  str_skill_desc_322132 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。ターン終了時に対象の敵がまだ生存している場合、その敵は今回の能動技によるダメージと同量のHPを回復する。ターン終了時に今回の能動技による敵回復効果が発動した場合、自身の能動技のCDターン数自身の能動技のCDターン数<color=#00F6FF>-1</color>。極光タイムを発動すると、ターン終了時の敵回復効果が発動しなくなる",
  str_skill_desc_3221321 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。ターン終了時に対象の敵がまだ生存している場合、その敵は今回の能動技によるダメージと同量のHPを回復する。ターン終了時に今回の能動技による敵回復効果が発動した場合、自身の能動技のCDターン数<color=#00F6FF>-1</color>。極光タイムを発動すると、ターン終了時の敵回復効果が発動しなくなる",
  str_skill_desc_325132 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。ターン終了時に対象の敵がまだ生存している場合、その敵は今回の能動技によるダメージと同量のHPを回復する。ターン終了時に今回の能動技による敵回復効果が発動した場合、自身の能動技のCDターン数<color=#00F6FF>-1</color>。極光タイムを発動すると、ターン終了時の敵回復効果が発動しなくなる",
  str_skill_desc_3251321 = "任意の敵1体を選択し、<color=#00F6FF>{1}%</color>のダメージを与える。ターン終了時に対象の敵がまだ生存している場合、その敵は今回の能動技によるダメージと同量のHPを回復する。ターン終了時に今回の能動技による敵回復効果が発動した場合、自身の能動技のCDターン数自身の能動技のCDターン数<color=#00F6FF>-1</color>。極光タイムを発動すると、ターン終了時の敵回復効果が発動しなくなる",
  str_skill_desc_300133 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_302133 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_300137 = "任意の敵1体を選択し、その敵の足元の最多<color=#00F6FF>2</color>マスの水属性ではないマスを水属性に転換する",
  str_skill_desc_310137 = "任意の敵1体を選択し、その敵の足元の最多<color=#00F6FF>2</color>マスの水属性ではないマスを水属性に転換する",
  str_skill_desc_304137 = "任意の敵1体を選択し、その敵の足元の最多<color=#00F6FF>3</color>マスの水属性ではないマスを水属性に転換する",
  str_skill_desc_314137 = "任意の敵1体を選択し、その敵の足元の最多<color=#00F6FF>3</color>マスの水属性ではないマスを水属性に転換する",
  str_skill_desc_300135 = "周囲<color=#00F6FF>4</color>方向の中から1方向を選択し、さらにその両側のどちらか1方の方向を選択して、<color=#00F6FF>45度</color>の範囲内に掃射攻撃をし、攻撃力の<color=#00F6FF>340%</color>のダメージを与える。掃射中、ダメージは減退し、最小で初期値の30％まで下がる",
  str_skill_desc_302135 = "周囲<color=#00F6FF>4</color>方向の中から1方向を選択し、さらにその両側のどちらか1方の方向を選択して、<color=#00F6FF>45度</color>の範囲内に掃射攻撃をし、攻撃力の<color=#00F6FF>340%</color>のダメージを与える。掃射中、ダメージは減退し、最小で初期値の30％まで下がる",
  str_skill_desc_305135 = "周囲<color=#00F6FF>4</color>方向の中から1方向を選択し、さらにその両側のどちらか1方の方向を選択して、<color=#00F6FF>45度</color>の範囲内に掃射攻撃をし、攻撃力の<color=#00F6FF>340%</color>のダメージを与える。掃射中、ダメージは減退し、最小で初期値の40％まで下がる",
  str_skill_desc_320135 = "周囲<color=#00F6FF>4</color>方向の中から1方向を選択し、さらにその両側のどちらか1方の方向を選択して、<color=#00F6FF>90度</color>の範囲内に掃射攻撃をし、攻撃力の<color=#00F6FF>340%</color>のダメージを与える。掃射中、ダメージは減退し、最小で初期値の30％まで下がる",
  str_skill_desc_322135 = "周囲<color=#00F6FF>4</color>方向の中から1方向を選択し、さらにその両側のどちらか1方の方向を選択して、<color=#00F6FF>90度</color>の範囲内に掃射攻撃をし、攻撃力の<color=#00F6FF>340%</color>のダメージを与える。掃射中、ダメージは減退し、最小で初期値の30％まで下がる",
  str_skill_desc_325135 = "周囲<color=#00F6FF>4</color>方向の中から1方向を選択し、さらにその両側のどちらか1方の方向を選択して、<color=#00F6FF>90度</color>の範囲内に掃射攻撃をし、攻撃力の<color=#00F6FF>340%</color>のダメージを与える。掃射中、ダメージは減退し、最小で初期値の40％まで下がる",
  str_skill_desc_300134 = "マスを1つ選択し、途中のマスおよび隣接するマスの敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを与え、最も遠い位置までノックバックする",
  str_skill_desc_303134 = "マスを1つ選択し、途中のマスおよび隣接するマスの敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを与え、最も遠い位置までノックバックする",
  str_skill_desc_320134 = "マスを1つ選択し、<color=#00F6FF>途中</color>のマスおよび<color=#00F6FF>隣接</color>するマスの敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを与え、最も遠い位置までノックバックする。そのうち<color=#00F6FF>途中</color>のマスにいる敵は<color=#00F6FF>1.3</color>倍のダメージを受ける",
  str_skill_desc_323134 = "マスを1つ選択し、<color=#00F6FF>途中</color>のマスおよび<color=#00F6FF>隣接</color>するマスの敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを与え、最も遠い位置までノックバックする。そのうち<color=#00F6FF>途中</color>のマスにいる敵は<color=#00F6FF>1.3</color>倍のダメージを受ける",
  str_skill_desc_300136 = "敵全体に<color=#00F6FF>{1}%</color>のダメージを与え、さらに森属性のマスにいる敵に<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。2ターン持続",
  str_skill_desc_302136 = "敵全体に<color=#00F6FF>{1}%</color>のダメージを与え、さらに森属性のマスにいる敵に<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。2ターン持続",
  str_skill_desc_320136 = "敵全体に<color=#00F6FF>{1}%</color>のダメージを与え、さらに森属性のマスにいる敵に<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。2ターン持続。能動技がダメージを与える前に、敵に<color=#00F6FF>2スタック</color>の塵界の印を付与する",
  str_skill_desc_322136 = "敵全体に<color=#00F6FF>{1}%</color>のダメージを与え、さらに森属性のマスにいる敵に<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。2ターン持続。能動技がダメージを与える前に、敵に<color=#00F6FF>2スタック</color>の塵界の印を付与する",
  str_skill_desc_325136 = "敵全体に<color=#00F6FF>{1}%</color>のダメージを与え、さらに森属性のマスにいる敵に<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。2ターン持続。能動技がダメージを与える前に、敵に<color=#00F6FF>3スタック</color>の塵界の印を付与する",
  str_skill_passive_desc_410022 = "能動技のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410051 = "能動技のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410047 = "連鎖技の回復係数+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410049 = "<color=#00F6FF>{1}</color>の確率で連鎖技のダメージ+<color=#00F6FF>50%</color>",
  str_skill_passive_desc_410050 = "連鎖技のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410052 = "能動技が<color=#00F6FF>{1}</color>の確率で敵を<link=\"10006\"><#FFAE07><u>減速</u></color></link>させる。2ターン持続",
  str_skill_passive_desc_410074 = "能動技のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410008 = "能動技を使用すると、このターン内のタイニーの通常攻撃ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410007 = "連鎖技発動時、最初に往復攻撃を加えた敵へのダメージ+<color=#00F6FF>{1}</color>。さらに毒状態を1スタック付与する。2ターン持続",
  str_skill_passive_desc_410032 = "能動技の雷撃がそれぞれ<color=#00F6FF>15%</color>の確率で<color=#00F6FF>{1}</color>の追加ダメージを与える",
  str_skill_passive_desc_410053 = "能動技が発動可能状態の時、連鎖技のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410058 = "ターン終了時に旗槍がまだ残っている場合、エイミーの防御力の<color=#00F6FF>{1}</color>倍相当のチームHPを回復する",
  str_skill_passive_desc_400035 = "移動技使用後、このターン内のカラスの通常攻撃のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410035 = "移動技使用後、このターン内のカラスの通常攻撃のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420035 = "移動技使用後、このターン内のカラスの通常攻撃と連鎖ダメージがそれぞれ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410017 = "味方光霊が敵をノックバックすると、ラビがその敵に攻撃力<color=#00F6FF>{1}</color>の防御力無視のダメージを与える",
  str_skill_passive_desc_430017 = "味方光霊が敵をノックバックすると、ラビがその敵に攻撃力<color=#00F6FF>{1}</color>の防御力無視のダメージを与える。敵を1マスノックバックするごとに防御力無視のダメージ+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_410040 = "毎ターン開始時にビスコースの印を1スタック獲得する。連鎖技が敵に命中すると、1スタックにつき<color=#00F6FF>{1}</color>の確率でターゲットを<link=\"10002\"><#FFAE07><u>火傷</u></color></link>状態にする。Wave開始時に印はすべて消える",
  str_skill_passive_desc_420040 = "毎ターン開始時にビスコースの印を1スタック獲得する。連鎖技が敵に命中すると、1スタックにつき<color=#00F6FF>{1}</color>の確率でターゲットを2ターン<link=\"10002\"><#FFAE07><u>火傷</u></color></link>状態にする。Wave開始時に印はすべて消える",
  str_skill_passive_desc_410041 = "HP最大時、Ms.ブランの攻撃力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420041 = "HPが70%を超える時、Ms.ブランの攻撃力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430041 = "HPが70%を超える時、Ms.ブランの攻撃力+<color=#00F6FF>{1}</color>。さらに出撃している水属性光霊の攻撃力がMs.ブランの攻撃力の<color=#00F6FF>{2}</color>相当上昇する",
  str_skill_passive_desc_410021 = "能動技が発動可能状態ではない時、連鎖技のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420021 = "能動技が発動可能状態ではない時、連鎖技のダメージ+<color=#00F6FF>{1}</color>、通常攻撃のダメージ+<color=#00F6FF>{2}</color>",
  str_skill_passive_desc_410004 = "チームHPの上限+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410073 = "連鎖のスタート位置に追加で連鎖技を1回発動する。ダメージは通常の<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430073 = "連鎖のスタート位置に追加で連鎖技を1回発動する。ダメージは通常の<color=#00F6FF>{1}</color>。連鎖のスタート位置と連鎖技の攻撃範囲が重なった場合、重複エリアへのダメージ+<color=#00F6FF>100%</color>",
  str_skill_passive_desc_410061 = "能動技を発動するごとに消沈の印を1スタック獲得する。最大<color=#00F6FF>3</color>スタックまで。1スタックにつき能動技のダメージ回数+1、最終ダメージ-<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420061 = "能動技を発動するごとに消沈の印を1スタック獲得する。最大<color=#00F6FF>5</color>スタックまで。1スタックにつき能動技のダメージ回数+1、最終ダメージ-<color=#00F6FF>{1}</color>、連鎖ダメージ+<color=#00F6FF>5%</color>",
  str_skill_passive_desc_430061 = "能動技を発動するごとに消沈の印を1スタック獲得する。最大<color=#00F6FF>5</color>スタックまで。1スタックにつき能動技のダメージ回数+1、最終ダメージ-<color=#00F6FF>{1}</color>、連鎖ダメージ+<color=#00F6FF>5%</color>",
  str_skill_passive_desc_414061 = "能動技を発動するごとに消沈の印を1スタック獲得する。最大<color=#00F6FF>3</color>スタックまで。1スタックにつき能動技のダメージ回数+1、最終ダメージ-<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_424061 = "能動技を発動するごとに消沈の印を1スタック獲得する。最大<color=#00F6FF>5</color>スタックまで。1スタックにつき能動技のダメージ回数+1、最終ダメージ-<color=#00F6FF>{1}</color>、連鎖ダメージ+<color=#00F6FF>5%</color>",
  str_skill_passive_desc_434061 = "能動技を発動するごとに消沈の印を1スタック獲得する。最大<color=#00F6FF>5</color>スタックまで。1スタックにつき能動技のダメージ回数+1、最終ダメージ-<color=#00F6FF>{1}</color>、連鎖ダメージ+<color=#00F6FF>5%</color>",
  str_skill_passive_desc_410054 = "持続ターンが終了して提灯が消えるとき、<color=#00F6FF>周囲1マス</color>に光を放ち、<color=#00F6FF>{1}</color>のダメージを与え、<color=#00F6FF>{2}</color>の確率で敵を1ターン<link=\"10005\"><#FFAE07><u>盲目</u></color></link>状態にする",
  str_skill_passive_desc_430054 = "提灯が存在している場合、ターンが終わるたびに光を放ち、<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}</color>のダメージを与え、<color=#00F6FF>{2}</color>の確率で敵を1ターン<link=\"10005\"><#FFAE07><u>盲目</u></color></link>状態にする",
  str_skill_passive_desc_410016 = "雷属性のマスを1つ通過するごとにエネルギーを1スタック獲得する。最大99スタック。1スタックにつき能動技のダメージ+<color=#00F6FF>{1}</color>。能動技を発動するとエネルギーはすべて消える",
  str_skill_passive_desc_410046 = "嘲笑の印1スタックにつき、雷属性光霊の通常攻撃ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430046 = "嘲笑の印が付いた敵を撃破すると、残りの敵全員の印のスタック数<color=#00F6FF>+1</color>。印1スタックにつき雷属性光霊の通常攻撃ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410044 = "連鎖技で全ての敵にダメージを与えると、雷属性光霊はこのターン中、ビビアンの攻撃力の<color=#00F6FF>{1}</color>攻撃力が強化される",
  str_skill_passive_desc_430044 = "連鎖技で全ての敵にダメージを与えると、水・雷属性及び啓光の光霊がビビアンの攻撃力の<color=#00F6FF>{1}</color>相当の攻撃力バフを獲得する。2ターン持続",
  str_skill_passive_desc_410048 = "雷属性のマスにいる敵に対するダイナの与ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430048 = "雷属性のマスにいる敵に対するダイナの与ダメージ+<color=#00F6FF>{1}</color>。チーム内の他の雷属性の光霊がその<color=#00F6FF>半分</color>のダメージ強化を獲得する",
  str_skill_passive_desc_410009 = "毎ターン開始時、<color=#00F6FF>{1}</color>の確率で敵を<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態にする。1ターン持続",
  str_skill_passive_desc_420009 = "毎ターン開始時、<color=#00F6FF>{1}</color>の確率で敵を1ターン<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態にする。<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態の敵を倒すと爆発が起こり、周囲1マスの敵に最大HPの<color=#00F6FF>10%</color>のダメージを与える",
  str_skill_passive_desc_410012 = "連鎖技が敵1体に命中するごとに裁決の印を1スタック獲得する。1スタックにつき自身の防御力+<color=#00F6FF>{1}</color>。ターンが終了すると印は消える",
  str_skill_passive_desc_420012 = "連鎖技が敵1体に命中するごとに裁決の印を1スタック獲得する（能動技は2スタック獲得）。1スタックにつき自身の防御力+<color=#00F6FF>{1}</color>。ターンが終了時、印のスタック数が半分になる",
  str_skill_passive_desc_430012 = "連鎖技が敵1体に命中するごとに裁決の印を1スタック獲得する（能動技は2スタック獲得）。印1スタックにつき自身の攻撃力+<color=#00F6FF>3%</color>、防御力+<color=#00F6FF>{1}</color>。ターン終了時、印のスタック数が半分になる",
  str_skill_passive_desc_410013 = "シールド消失時、残ったシールド値の<color=#00F6FF>{1}</color>をHPに変換する",
  str_skill_passive_desc_430013 = "シールド消失時、残ったシールド値の<color=#00F6FF>{1}</color>をHPに変換する。シールドを持っている場合、ノーアの防御力+<color=#00F6FF>50%</color>",
  str_skill_passive_desc_410018 = "敵との距離が近いほど連鎖技のダメージが大きくなり、最大+<color=#00F6FF>{1}</color>。敵との距離が3マスを超えると効果は無くなる",
  str_skill_passive_desc_420018 = "敵との距離が近いほど能動技と連鎖技のダメージが大きくなり、最大+<color=#00F6FF>{1}</color>。敵との距離が3マスを超えると効果は無くなる",
  str_skill_passive_desc_430018 = "<color=#00F6FF>周囲1マス</color>の範囲内にいる敵1体につき、攻撃力+<color=#00F6FF>5%</color>。敵との距離が近いほど能動技と連鎖技のダメージが大きくなる。最大でダメージ+<color=#00F6FF>{1}</color>。敵との距離が3マスを超えるとダメージ強化がなくなる",
  str_skill_passive_desc_410033 = "バイスがダメージを与えるごとに狙撃の印を1スタック獲得する。1スタックにつきダメージ+<color=#00F6FF>{1}</color>。ターンが終了すると印はすべて消える",
  str_skill_passive_desc_430033 = "バイスがダメージを与えるごとに狙撃の印を1スタック獲得する。印1スタックにつきダメージ+<color=#00F6FF>{1}</color>（連鎖技は+<color=#00F6FF>{2}</color>）。ターンが終了すると印はすべて消える",
  str_skill_passive_desc_410036 = "毎ターン開始時に狼の魂を1つ獲得する。最初の攻撃を受けた時に狼の魂を1つ消費して、ターゲットにヒドライの攻撃力<color=#00F6FF>{1}</color>の防御力無視のダメージを与える。ターンが終了すると狼の魂はクリアされる",
  str_skill_passive_desc_420036 = "毎ターン開始時に狼の魂を1つ獲得する。攻撃を受けた時に狼の魂を1つ消費して、ターゲットにヒドライの攻撃力<color=#00F6FF>{1}</color>の防御力無視のダメージを与える。ターンが終了しても狼の魂は<color=#00F6FF>クリアされない</color>",
  str_skill_passive_desc_410010 = "<link=\"30010\"><#FFAE07><u>極光タイム</u></color></link>が発動すると、ただちにルイスのHP上限の<color=#00F6FF>{1}</color>相当のチームHPを回復する",
  str_skill_passive_desc_420010 = "<link=\"30010\"><#FFAE07><u>極光タイム</u></color></link>が発動すると、ただちにルイスのHP上限の<color=#00F6FF>{1}</color>相当のチームHPを回復する。さらにルイスの防御力+<color=#00F6FF>50%</color>。2ターン持続",
  str_skill_passive_desc_410014 = "出撃メンバーに雷属性か白夜城の光霊がいる場合、1人につきソルラドの防御力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430014 = "出撃メンバーに雷属性か白夜城の光霊がいる場合、1人につきソルラドの防御力+{1}（攻撃力も防御力の増加分と同量アップする）",
  str_skill_passive_desc_410078 = "森属性のマスにいる敵へのロビンの与ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430078 = "森属性のマスにいる敵に対するロビンの与ダメージ+<color=#00F6FF>{1}</color>。チーム内の他の森属性の光霊がその<color=#00F6FF>半分</color>のダメージ強化を獲得する",
  str_skill_passive_desc_410076 = "連鎖発動後、周囲の<color=#00F6FF>十字方向4マス</color>にいるHPが最も低い敵に接触し、そのHPが<color=#00F6FF>{1}</color>未満の場合は<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態を付与する。1ターン持続",
  str_skill_passive_desc_420076 = "連鎖発動後、周囲の<color=#00F6FF>十字方向4マス</color>にいるHPが<color=#00F6FF>{1}</color>未満で最も低い敵に1ターンの<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態を付与する。<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態の敵を撃破すると<color=#00F6FF>50%</color>の確率で周囲の<color=#00F6FF>十字方向4</color>マスの敵を<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態にする",
  str_skill_passive_desc_410042 = "通常攻撃が斜め方向へ射撃可能になり、<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_420042 = "通常攻撃で斜め方向の敵に<color=#00F6FF>{1}</color>のダメージを与え、火力の印を付与する。2ターン持続。印がついている敵に対するバートンの通常攻撃のダメージ+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_430042 = "通常攻撃で斜め方向の敵に<color=#00F6FF>{1}</color>のダメージを与え、火力の印を付与する。2ターン持続。印がついている敵に対するバートンの<color=#00F6FF>全てのダメージ</color>+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_410001 = "戦闘開始時に鏡界の印を獲得する。印の持続中、ナシリスの防御力+<color=#00F6FF>{1}</color>。HPを失うと印が消える。<color=#00F6FF>能動技使用時</color>、印が更新される",
  str_skill_passive_desc_420001 = "戦闘開始時に鏡界の印を獲得する。印の持続中、ナシリスの防御力+<color=#00F6FF>{1}</color>。HPを失うと印が消える。<color=#00F6FF>能動技使用時または極光タイム発動時</color>に印が更新される",
  str_skill_passive_desc_410011 = "通常攻撃で敵に龍牙の印を1スタック付与する。最大<color=#00F6FF>4</color>スタック。1スタックにつきキシローナの連鎖技の最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430011 = "通常攻撃で敵に龍牙の印を1スタック付与する。最大<color=#00F6FF>6</color>スタック。1スタックにつきキシローナの<color=#00F6FF>能動技</color>と連鎖技の最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_440011 = "通常攻撃で敵に龍牙の印を1スタック付与する。最大<color=#00F6FF>7</color>スタック。1スタックにつきキシローナの<color=#00F6FF>能動技</color>と連鎖技の最終ダメージ+<color=#00F6FF>5%</color>",
  str_skill_passive_desc_410019 = "連鎖技が<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態の敵に命中すると、<link=\"10000\"><#FFAE07><u>出血</u></color></link>1スタックにつきビクトリアの最大HPの<color=#00F6FF>{1}</color>のHPを回復できる",
  str_skill_passive_desc_420019 = "連鎖技が<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態の敵に命中すると、<link=\"10000\"><#FFAE07><u>出血</u></color></link>1スタックにつきビクトリアの最大HPの<color=#00F6FF>{1}</color>のHPを回復できる",
  str_skill_passive_desc_430019 = "連鎖技が<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態の敵に命中すると、<link=\"10000\"><#FFAE07><u>出血</u></color></link>1スタックにつきビクトリアの最大HPの<color=#00F6FF>{1}</color>のHPを回復する。チームよりも敵のHP比率のほうが高い場合、回復効果+<color=#00F6FF>50%</color>",
  str_skill_passive_desc_410023 = "連鎖技発動時、戦慄の印を1スタック獲得する。最大<color=#00F6FF>5</color>スタック。印1スタックにつき能動技のダメージ+<color=#00F6FF>{1}</color>。能動技使用時、印のスタック数と同じ数の敵を<color=#00F6FF>1</color>ターン<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態にし、<color=#00F6FF>印は消えない</color>",
  str_skill_passive_desc_430023 = "連鎖技発動時、戦慄の印を1スタック獲得する。最大<color=#00F6FF>5</color>スタック。印1スタックにつき能動技のダメージ+<color=#00F6FF>{1}</color>。能動技使用時、印のスタック数と同じ数の敵を<color=#00F6FF>1</color>ターン<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態にし、<color=#00F6FF>印は消えない</color>。連鎖技使用時、発動前に印を5スタック獲得している場合、連鎖技が追加で最も近くにいる敵1体にダメージを与える",
  str_skill_passive_desc_410002 = "毎ターン開始時にヒイロが居合状態となり、次の通常攻撃で敵に<color=#00F6FF>{1}</color>のダメージを与え、さらにその周囲の<color=#00F6FF>十字方向4マス</color>にいる敵に<color=#00F6FF>{2}</color>のダメージを与える",
  str_skill_passive_desc_420002 = "毎ターン開始時または<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を通過した時にヒイロが居合状態となり、次の通常攻撃で敵に<color=#00F6FF>{1}</color>のダメージを与え、さらにその周囲の<color=#00F6FF>十字方向4マス</color>の敵に<color=#00F6FF>{2}</color>のダメージを与える",
  str_skill_passive_desc_430002 = "毎ターン開始時または<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を通過した時にヒイロが居合状態となり、次の通常攻撃で敵に<color=#00F6FF>{1}</color>のダメージを与え、さらにその周囲の<color=#00F6FF>十字方向4マス</color>の敵に<color=#00F6FF>{2}</color>のダメージを与える。このターン中に居合斬りが発動するたびに、攻撃力+<color=#00F6FF>4%</color>（最大+<color=#00F6FF>20%</color>）",
  str_skill_passive_desc_410005 = "ミヤが能動技で敵を撃破すると、ソウルを1スタック獲得する。最大5スタック。ソウル1スタックごとに敵1体に攻撃力の<color=#00F6FF>{1}</color>の衝撃を1回与える",
  str_skill_passive_desc_420005 = "ミヤが能動技で敵を撃破すると、ソウルを1スタック獲得する。最大5スタック。ソウル1スタックごとに敵1体に攻撃力の<color=#00F6FF>{1}</color>の衝撃を1回与え、ミヤの連鎖ダメージ+<color=#00F6FF>5%</color>、通常攻撃のダメージ+<color=#00F6FF>3%</color>",
  str_skill_passive_desc_430005 = "<color=#00F6FF>光霊</color>が能動技で敵を撃破すると、ソウルを1スタック獲得する。最大<color=#00F6FF>7</color>スタック。ソウル1スタックごとに敵1体に攻撃力の<color=#00F6FF>{1}</color>の衝撃を1回与え、ミヤの連鎖ダメージ+<color=#00F6FF>5%</color>、通常攻撃のダメージ+<color=#00F6FF>3%</color>",
  str_skill_passive_desc_410006 = "水属性のマスの上を1マス移動するごとに、カレンのそのターンの基礎攻撃力+<color=#00F6FF>{1}</color>（最大<color=#00F6FF>{2}</color>）",
  str_skill_passive_desc_420006 = "水属性のマスの上を1マス移動するごとに、カレンのそのターンの基礎攻撃力+<color=#00F6FF>{1}</color>（最大<color=#00F6FF>{2}</color>）。能動技を発動するとバフ効果が2倍になる",
  str_skill_passive_desc_430006 = "水属性のマスの上を1マス移動するごとに、カレンのそのターンの攻撃力+<color=#00F6FF>{1}</color>（最大<color=#00F6FF>{2}</color>）。能動技を発動するとバフ効果が2倍になる。カレンが水属性のマスにいる時、通常攻撃は敵を貫通し、敵の1マス後ろのターゲットに<color=#00F6FF>40%</color>のダメージを与える",
  str_skill_passive_desc_410025 = "通常攻撃に攻撃力<color=#00F6FF>{1}</color>の防御力無視のダメージを付与する",
  str_skill_passive_desc_430025 = "通常攻撃で<color=#00F6FF>斜め方向</color>に攻撃できる。さらに通常攻撃に攻撃力<color=#00F6FF>{1}</color>の防御力無視のダメージを付与する",
  str_skill_passive_desc_410026 = "<link=\"10002\"><#FFAE07><u>火傷</u></color></link>状態1スタックにつき火属性光霊のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430026 = "毎ターン開始時、火属性マスにいる敵に<link=\"10002\"><#FFAE07><u>火傷</u></color></link>状態を1スタック付与する。2ターン持続。<link=\"10002\"><#FFAE07><u>火傷</u></color></link>状態1スタックにつき火属性光霊のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410028 = "マップに水属性のマスが生成される度に、1マスにつきラファエルの最大HPの<color=#00F6FF>{1}</color>相当のチームHPを回復する",
  str_skill_passive_desc_420028 = "マップに水属性のマスが生成される度に、1マスにつきラファエルの最大HPの<color=#00F6FF>{1}</color>相当のチームHPを回復する。チームのHPが低いほど回復効果が高くなり、最大で<color=#00F6FF>+100%</color>",
  str_skill_passive_desc_410029 = "このターン内で森属性のマスを<color=#00F6FF>{1}</color>つ通過するごとに、生成するマスに<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が必ず1つ現れる",
  str_skill_passive_desc_430029 = "このターン内で森属性のマスを<color=#00F6FF>{1}</color>つ通過するごとに、生成するマスに<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>が必ず1つ現れる。さらに森属性のマスを優先的に強化する",
  str_skill_passive_desc_410038 = "3ターンごとに磁気嵐を1回獲得し、次の連鎖技で範囲内の敵1体に追加で<color=#00F6FF>{1}</color>のダメージを与え、1ターン<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>状態にする",
  str_skill_passive_desc_420038 = "3ターンごとに磁気嵐1回を獲得し、次の連鎖技で範囲内の敵1体に追加で<color=#00F6FF>{1}</color>のダメージを与え、1ターン<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>状態にする。<color=#00F6FF>50%</color>の確率でさらに敵1体を攻撃する",
  str_skill_passive_desc_430038 = "戦闘開始時に磁気嵐状態を獲得する（3ターンに1回）。次の連鎖技で範囲内の敵1体に追加で<color=#00F6FF>{1}</color>のダメージを与え、<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>状態にする。<color=#00F6FF>50%</color>の確率でさらに敵1体を攻撃する",
  str_skill_passive_desc_410077 = "能動技を発動した光霊は、このターンの間、ベツレヘムの基礎攻撃力の<color=#00F6FF>{1}</color>の強化を受ける",
  str_skill_passive_desc_420077 = "このターンに能動技を発動した光霊は、ベツレヘムの基礎攻撃力の<color=#00F6FF>{1}</color>の強化を受ける。極光タイムの発動時、そのターン中はチーム全員が追加でベツレヘムの基礎攻撃力の<color=#00F6FF>{2}</color>の強化を受ける",
  str_skill_passive_desc_430077 = "このターンに能動技を発動した光霊は、ベツレヘムの基礎攻撃力の<color=#00F6FF>{1}</color>の強化を受ける。さらにベツレヘムが基礎攻撃力の<color=#00F6FF>{2}</color>の強化を受ける。ベツレヘムが1ターン内に獲得する攻撃力強化は累積できる。極光タイム発動時、このターン中はチーム全員が追加でベツレヘムの基礎攻撃力の<color=#00F6FF>{2}</color>の強化を受ける",
  str_skill_passive_desc_400092 = "マークされていた敵を倒した時、そのHP上限の<color=#00F6FF>{1}</color>相当のHP上限アップと<link=\"30007\"><#FFAE07><u>回復効果</u></color></link>を獲得する",
  str_skill_passive_desc_410092 = "マークされていた敵を倒した時、そのHP上限の<color=#00F6FF>{1}</color>相当のHP上限アップと<link=\"30007\"><#FFAE07><u>回復効果</u></color></link>を獲得する",
  str_skill_passive_desc_420092 = "マークされていた敵を倒した時、そのHP上限の<color=#00F6FF>{1}</color>相当のHP上限アップと<link=\"30007\"><#FFAE07><u>回復効果</u></color></link>を獲得できる。さらに敵のいた位置のマス1つを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変換する",
  str_skill_passive_desc_400075 = "通常攻撃をすると、<color=#00F6FF>{1}</color>の確率で<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_passive_desc_410075 = "通常攻撃をすると、<color=#00F6FF>{1}</color>の確率で<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_passive_desc_430075 = "通常攻撃で<color=#00F6FF>斜め方向の敵を攻撃できる</color>。さらに<color=#00F6FF>{1}</color>の確率で<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_passive_desc_400086 = "森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を通るごとに、直ちにユーライアの防御力の<color=#00F6FF>{1}</color>相当のHPを回復する",
  str_skill_passive_desc_410086 = "森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を通るごとに、直ちにユーライアの防御力の<color=#00F6FF>{1}</color>相当のHPを回復する",
  str_skill_passive_desc_400068 = "光霊の瞬間移動時、スタート位置から着地位置まで1マスごとにウェンディが印を1スタック獲得できる。印1スタックにつきウェンディの次の通常攻撃のダメージ+<color=#00F6FF>{1}</color>。通常攻撃後に印はクリアされる",
  str_skill_passive_desc_410068 = "光霊の瞬間移動時、スタート位置から着地位置までの距離1マスごとにウェンディが印を1スタック獲得できる。印1スタックにつきウェンディの次の通常攻撃のダメージ+<color=#00F6FF>{1}</color>。通常攻撃後に印はクリアされる",
  str_skill_passive_desc_430068 = "光霊の瞬間移動時、スタート位置から着地位置までの距離1マスごとにウェンディが印を1スタック獲得できる。印1スタックにつきウェンディの次の通常攻撃のダメージ+<color=#00F6FF>{1}</color>。通常攻撃後、印のスタック数の<color=#00F6FF>30%</color>が残る",
  str_skill_passive_desc_400082 = "連鎖技を発動すると、<color=#00F6FF>{1}</color>の確率で敵に<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_passive_desc_410082 = "連鎖技を発動すると、<color=#00F6FF>{1}</color>の確率で敵に<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_passive_desc_400057 = "毎ターン開始時、フィリスの攻撃力の<color=#00F6FF>{1}</color>相当のHPとチームの失ったHPの<color=#00F6FF>{2}</color>をチームが回復する",
  str_skill_passive_desc_410057 = "毎ターン開始時、フィリスの攻撃力の<color=#00F6FF>{1}</color>相当のHPとチームの失ったHPの<color=#00F6FF>{2}</color>をチームが回復する",
  str_skill_passive_desc_430057 = "毎ターン開始時、フィリスの攻撃力の<color=#00F6FF>{1}</color>相当のHPとチームの失ったHPの<color=#00F6FF>{2}</color>をチームが回復する。チームがHPの<color=#00F6FF>5%</color>を失うごとに、フィリスの攻撃力+<color=#00F6FF>1%</color>",
  str_skill_passive_desc_400091 = "能動技か連鎖技を発動すると、自分の<color=#00F6FF>周囲1マス</color>にいる敵の攻撃力-<color=#00F6FF>{1}</color>。1ターン持続",
  str_skill_passive_desc_410091 = "能動技か連鎖技を発動すると、自分の<color=#00F6FF>周囲1マス</color>にいる敵の攻撃力-<color=#00F6FF>{1}</color>。1ターン持続",
  str_skill_passive_desc_420091 = "能動技か連鎖技を発動すると、自分の<color=#00F6FF>周囲1マス</color>にいる敵の攻撃力-<color=#00F6FF>{1}</color>。1ターン持続",
  str_skill_passive_desc_430091 = "能動技か連鎖技を発動すると、自分の<color=#00F6FF>周囲2マス</color>以内にいる敵の攻撃力と防御力それぞれ-<color=#00F6FF>{1}</color>。1ターン持続",
  str_skill_passive_desc_400079 = "ターゲットのHP比率が自分より高い状態で攻撃された場合、ミジェンニの攻撃力の<color=#00F6FF>{1}</color>を防御力に変換する",
  str_skill_passive_desc_410079 = "ターゲットのHP比率が自分より高い状態で攻撃された場合、ミジェンニの攻撃力の<color=#00F6FF>{1}</color>を防御力に変換する",
  str_skill_passive_desc_420079 = "ターゲットのHP比率が自分より高い状態で攻撃された場合、ミジェンニの攻撃力の<color=#00F6FF>{1}</color>を防御力に変換する。ミジェンニがダメージを与えると、ミジェンニと同じ比率の防御力を攻撃力に変換する",
  str_skill_passive_desc_400085 = "能動技が敵にダメージを与える時、敵の失っているHP<color=#00F6FF>{1}</color>ごとに、最終ダメージ+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_410085 = "能動技が敵にダメージを与えた場合、敵がHPを<color=#00F6FF>{1}</color>失うごとに、最終ダメージ+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_400089 = "<link=\"30001\"><#FFAE07><u>プリズムマス</u></color></link>を通るごとに、黄金の印を1スタック獲得する。印1スタックごとに連鎖ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410089 = "<link=\"30001\"><#FFAE07><u>プリズムマス</u></color></link>を通るごとに、黄金の印を1スタック獲得する。印1スタックごとに連鎖ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420089 = "<link=\"30001\"><#FFAE07><u>プリズムマス</u></color></link>を通るごとに、黄金の印を1スタック獲得する。印1スタックごとに連鎖ダメージ+<color=#00F6FF>{1}</color>、通常攻撃の与ダメージ+<color=#00F6FF>3%</color>",
  str_skill_passive_desc_430089 = "<link=\"30001\"><#FFAE07><u>プリズムマス</u></color></link>を通るごとに、黄金の印を1スタック獲得する。印1スタックごとに連鎖ダメージ+<color=#00F6FF>{1}</color>、通常攻撃の与ダメージ+<color=#00F6FF>3%</color>。<link=\"30010\"><#FFAE07><u>極光タイム</u></color></link>を発動すると、スタートのマスが<link=\"30001\"><#FFAE07><u>プリズムマス</u></color></link>に変換される",
  str_skill_passive_desc_400027 = "毎ターン開始時に静雷の印を1スタック獲得する。通常攻撃時に印1スタックを消費して、敵に現在のHPの<color=#00F6FF>{1}</color>の追加ダメージを与える",
  str_skill_passive_desc_410027 = "毎ターン開始時に静雷の印を1スタック獲得する。通常攻撃時に印1スタックを消費して、敵に現在のHPの<color=#00F6FF>{1}</color>の追加ダメージを与える",
  str_skill_passive_desc_420027 = "毎ターン開始時、能動技か連鎖技を発動すると静雷の印を1スタック獲得する。通常攻撃時に印を1スタック消費して、敵に現在のHP<color=#00F6FF>{1}</color>の追加ダメージを与える",
  str_skill_passive_desc_400060 = "「真昼」状態で通常攻撃をすると、目標から<color=#00F6FF>十字方向4マス</color>の範囲内にいる敵に<color=#00F6FF>{1}</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_passive_desc_410060 = "「真昼」状態で通常攻撃をすると、目標から<color=#00F6FF>十字方向4マス</color>の範囲内にいる敵に<color=#00F6FF>{1}</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_passive_desc_420060 = "「真昼」状態で通常攻撃のダメージ+<color=#00F6FF>20%</color>。さらに通常攻撃をすると、目標から<color=#00F6FF>十字方向4マス</color>の範囲内にいる敵に<color=#00F6FF>{1}</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_passive_desc_430060 = "「真昼」状態で通常攻撃のダメージ+<color=#00F6FF>20%</color>。さらに通常攻撃をすると、目標から<color=#00F6FF>十字方向4マス</color>の範囲内にいる敵に<color=#00F6FF>{1}</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_passive_desc_400064 = "<link=\"30008\"><#FFAE07><u>弾薬を貯蔵</u></color></link>できる。連鎖技で1回ダメージを与えるごとに弾薬を1発消費する（オーバーロード状態では毎回最大<color=#00F6FF>3</color>発消費）。弾薬を1発消費するごとに最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410064 = "<link=\"30008\"><#FFAE07><u>弾薬を貯蔵</u></color></link>できる。連鎖技で1回ダメージを与えるごとに弾薬を1発消費する（オーバーロード状態では毎回最大<color=#00F6FF>3</color>発消費）。弾薬を1発消費するごとに最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430064 = "<link=\"30009\"><#FFAE07><u>弾薬を貯蔵</u></color></link>できる。連鎖技で1回ダメージを与えるごとに弾薬を1発消費する（オーバーロード状態では毎回最大<color=#00F6FF>3</color>発消費）。弾薬を1発消費するごとに最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_400070 = "通常攻撃をすると、<color=#00F6FF>{1}</color>の確率で赤龍が攻撃を1回行う。ダメージはリオナの通常攻撃のダメージの<color=#00F6FF>50%</color>",
  str_skill_passive_desc_410070 = "通常攻撃をすると、<color=#00F6FF>{1}</color>の確率で赤龍が攻撃を1回行う。ダメージはリオナの通常攻撃のダメージの<color=#00F6FF>50%</color>",
  str_skill_passive_desc_420070 = "通常攻撃をすると、<color=#00F6FF>{1}</color>の確率で赤龍が攻撃を1回行う。ダメージはリオナの通常攻撃のダメージの<color=#00F6FF>50%</color>。さらに<link=\"10002\"><#FFAE07><u>火傷</u></color></link>を1スタック付与、2ターン持続",
  str_skill_passive_desc_400088 = "コンボ数が<color=#00F6FF>10</color>回に達するごとにマギーの連鎖技のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410088 = "コンボ数が<color=#00F6FF>10</color>回に達するごとにマギーの連鎖技のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420088 = "コンボ数が<color=#00F6FF>10</color>回に達するごとにマギーの連鎖技のダメージ+<color=#00F6FF>{1}</color>。さらに連鎖技の発動に必要なマスの数<color=#00F6FF>-1</color>",
  str_skill_passive_desc_430088 = "コンボ数が<color=#00F6FF>8</color>回に達するごとにマギーの連鎖技のダメージ+<color=#00F6FF>{1}</color>。さらに連鎖技の発動に必要なマスの数<color=#00F6FF>-1</color>",
  str_skill_passive_desc_400084 = "連鎖技の発動終了時、自分の<color=#00F6FF>周囲1マス</color>以内の敵の攻撃力-<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410084 = "連鎖技の発動終了時、自分の<color=#00F6FF>周囲1マス</color>以内の敵の攻撃力-<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420084 = "連鎖技の発動終了時、自分の<color=#00F6FF>周囲2マス</color>以内の敵の攻撃力-<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_400090 = "火属性のマスにいる敵に対するバーバラの与ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410090 = "火属性のマスにいる敵に対するバーバラの与ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430090 = "火属性のマスにいる敵に対するバーバラの与ダメージ+<color=#00F6FF>{1}</color>。チーム内の他の火属性の光霊がその<color=#00F6FF>半分</color>のダメージ強化を獲得する",
  str_skill_passive_desc_400045 = "HP比率が低いほど、ネイルスの攻撃力と防御力が高くなる。最大+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410045 = "HP比率が低いほど、ネイルスの攻撃力と防御力が高くなる。最大+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_400081 = "能動技を発動すると、<color=#00F6FF>周囲1マス</color>にいる敵1体につき、火属性光霊の攻撃力がヘールの攻撃力の<color=#00F6FF>{1}</color>相当上昇する",
  str_skill_passive_desc_410081 = "能動技を発動すると、<color=#00F6FF>周囲1マス</color>にいる敵1体につき、火属性光霊の攻撃力がヘールの攻撃力の<color=#00F6FF>{1}</color>相当上昇する",
  str_skill_passive_desc_430081 = "能動技を発動すると、<color=#00F6FF>周囲2マス</color>にいる敵1体につき、火属性光霊の攻撃力がヘールの攻撃力の<color=#00F6FF>{1}</color>相当上昇する",
  str_skill_passive_desc_400083 = "能動技を発動すると<color=#00F6FF>{1}</color>の確率で敵の移動範囲-<color=#00F6FF>50%</color>",
  str_skill_passive_desc_410083 = "能動技を発動すると<color=#00F6FF>{1}</color>の確率で敵の移動範囲-<color=#00F6FF>50%</color>",
  str_skill_passive_desc_430083 = "能動技を発動すると<color=#00F6FF>{1}</color>の確率で敵の移動範囲-<color=#00F6FF>50%</color>",
  str_skill_passive_desc_400059 = "<link=\"30002\"><#FFAE07><u>ピープの印</u></color></link>を獲得できる。最大<color=#00F6FF>{1}</color>スタック。印のスタックと同じ数の周囲のマスが能動技の移動範囲となる。能動技を使うと、印はクリアされる",
  str_skill_passive_desc_410059 = "<link=\"30002\"><#FFAE07><u>ピープの印</u></color></link>を獲得できる。最大<color=#00F6FF>{1}</color>スタック。印のスタックと同じ数の周囲のマスが能動技の移動範囲となる。能動技を使うと、印はクリアされる",
  str_skill_passive_desc_420059 = "<link=\"30003\"><#FFAE07><u>ピープの印</u></color></link>を獲得できる。最大<color=#00F6FF>{1}</color>スタック。印のスタックと同じ数の周囲のマスが能動技の移動範囲となる。能動技を使うと、印はクリアされる",
  str_skill_passive_desc_400080 = "連鎖技の範囲内に敵がいない場合、ユニメートの攻撃力の<color=#00F6FF>{1}</color>相当のチームHPを回復する",
  str_skill_passive_desc_410080 = "連鎖技の範囲内に敵がいない場合、ユニメートの攻撃力の<color=#00F6FF>{1}</color>相当のチームHPを回復する",
  str_skill_passive_desc_400093 = "連鎖技または能動技を発動した後、ターゲットのHPが<color=#00F6FF>{1}</color>以下の場合、そのターゲットに攻撃力の<color=#00F6FF>{2}</color>の防御力無視のダメージを追加で1回与える",
  str_skill_passive_desc_410093 = "連鎖技または能動技を発動した後、ターゲットのHPが<color=#00F6FF>{1}</color>以下の場合、そのターゲットに攻撃力の<color=#00F6FF>{2}</color>の防御力無視のダメージを追加で1回与える",
  str_skill_passive_desc_430093 = "連鎖技または能動技を発動した後、ターゲットのHPが<color=#00F6FF>{1}</color>以下の場合、そのターゲットに攻撃力の<color=#00F6FF>{2}</color>の防御力無視のダメージを追加で1回与える。追加攻撃の後、ターゲットのHPがミジャードの攻撃力より低い場合、そのターゲットを撃破する",
  str_skill_passive_desc_400097 = "通常攻撃が2連続攻撃になり、それぞれのダメージは基本ダメージの<color=#00F6FF>{1}</color>になる",
  str_skill_passive_desc_410097 = "通常攻撃が2連続攻撃になり、それぞれのダメージは基本ダメージの<color=#00F6FF>{1}</color>になる",
  str_skill_passive_desc_420097 = "通常攻撃が2連続攻撃になり、それぞれのダメージは基本ダメージの<color=#00F6FF>{1}</color>になる。それぞれの攻撃が<color=#00F6FF>20%</color>の確率でダメージ+<color=#00F6FF>50%</color>になる",
  str_skill_passive_desc_430097 = "通常攻撃が2連続攻撃になり、それぞれのダメージは基本ダメージの<color=#00F6FF>{1}</color>になる。それぞれの攻撃が<color=#00F6FF>20%</color>の確率でダメージ+<color=#00F6FF>50%</color>になる。コンボ1回につき、発動確率+0.5%、最大+50%",
  str_skill_passive_desc_400095 = "<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態の敵にダメージを与える時、毒状態1スタックにつき、最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410095 = "<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態の敵にダメージを与える時、毒状態1スタックにつき、最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420095 = "<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態の敵にダメージを与える時、毒状態1スタックにつき、最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430095 = "<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態の敵にダメージを与える時、毒状態1スタックにつき、最終ダメージ+<color=#00F6FF>{1}</color>。能動技や連鎖技が毒状態のターゲットに命中すると、毒状態を追加で1スタック付与",
  str_skill_passive_desc_400062 = "通常攻撃、連鎖技、能動技が1体の敵のみにダメージを与える時、そのダメージはターゲットの<color=#00F6FF>{1}</color>の防御力を無視する",
  str_skill_passive_desc_410062 = "通常攻撃、連鎖技、能動技が1体の敵のみにダメージを与える時、そのダメージはターゲットの<color=#00F6FF>{1}</color>の防御力を無視する",
  str_skill_passive_desc_430062 = "通常攻撃、連鎖技、能動技が1体の敵のみにダメージを与える時、そのダメージはターゲットの<color=#00F6FF>{1}</color>の防御力を無視する。戦場に敵が1体しかいない場合、チーム内の他の森属性光霊の能動技でダメージを与える時、その半分の効果を獲得する",
  str_skill_passive_desc_400024 = "火属性のマスにいる敵に対して通常攻撃をすると、<color=#00F6FF>{1}</color>のダメージを追加で与える",
  str_skill_passive_desc_410024 = "火属性のマスにいる敵に対して通常攻撃をすると、<color=#00F6FF>{1}</color>のダメージを追加で与える",
  str_skill_passive_desc_400087 = "連鎖技がターゲットに命中すると、その<color=#00F6FF>周囲1マス</color>のランダムのターゲット<color=#00F6FF>{1}</color>体にダメージを与える（1体のターゲットが受けるダメージは1回のみ）。ダメージは1回ごとに-<color=#00F6FF>{2}</color>",
  str_skill_passive_desc_410087 = "連鎖技がターゲットに命中すると、その<color=#00F6FF>周囲1マス</color>のランダムのターゲット<color=#00F6FF>{1}</color>体にダメージを与える（1体のターゲットが受けるダメージは1回のみ）。ダメージは1回ごとに-<color=#00F6FF>{2}</color>",
  str_skill_passive_desc_420087 = "連鎖技がターゲットに命中すると、その<color=#00F6FF>周囲2マス</color>のランダムのターゲット<color=#00F6FF>{1}</color>体にダメージを与える（1体のターゲットが受けるダメージは1回のみ）。ダメージは1回ごとに-<color=#00F6FF>{2}</color>",
  str_skill_passive_desc_400101 = "戦場の端にいる敵に対して、アンシアの与える全てのダメージが増加（敵が四隅にいる時に最大化）、最大で最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410101 = "戦場の端にいる敵に対して、アンシアの与える全てのダメージが増加（敵が四隅にいる時に最大化）、最大で最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_400102 = "チームの雷属性の光霊が能動技を発動した時、テッサの印を1スタック獲得する。能動技を発動する時、印1スタックにつき、<color=#00F6FF>周囲1マス</color>の敵に<color=#00F6FF>{1}</color>のダメージを与える。能動技発動後、印はクリアされる",
  str_skill_passive_desc_410102 = "チームの雷属性の光霊が能動技を発動した時、テッサの印を1スタック獲得する。能動技を発動する時、印1スタックにつき、<color=#00F6FF>周囲1マス</color>の敵に<color=#00F6FF>{1}</color>のダメージを与える。能動技発動後、印はクリアされる",
  str_skill_passive_desc_420102 = "チームの雷属性の光霊が能動技を発動、またはテッサが連鎖技を発動した時にテッサの印を1スタック獲得する。能動技を発動する時、印1スタックにつき、<color=#00F6FF>周囲1マス</color>の敵に<color=#00F6FF>{1}</color>のダメージを与える。能動技発動後、印はクリアされる",
  str_skill_passive_desc_430102 = "チームの雷属性の光霊が能動技を発動、またはテッサが連鎖技を発動した時にテッサの印を1スタック獲得する。能動技を発動する時、印1スタックにつき、<color=#00F6FF>周囲2マス</color>の敵に<color=#00F6FF>{1}</color>のダメージを与える。能動技発動後、印はクリアされる",
  str_skill_passive_desc_400099 = "魔剣発動中、通常攻撃は敵を貫通し、敵の背後1マスにいるターゲットに<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_410099 = "魔剣発動中、通常攻撃は敵を貫通し、敵の背後1マスにいるターゲットに<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_400100 = "スカーレイが敵に初めて攻撃すると、ターゲットのソウルを刈り、そのターゲットに直ちに攻撃力<color=#00F6FF>{1}</color>の防御力無視ダメージを与える",
  str_skill_passive_desc_410100 = "スカーレイが敵に初めて攻撃すると、ターゲットのソウルを刈り、そのターゲットに直ちに攻撃力<color=#00F6FF>{1}</color>の防御力無視ダメージを与える",
  str_skill_passive_desc_430100 = "スカーレイが敵に初めて攻撃すると、ターゲットのソウルを刈り、そのターゲットに直ちに攻撃力の<color=#00F6FF>{1}</color>および現在のHP<color=#00F6FF>5%</color>の防御力無視ダメージを与える",
  str_skill_passive_desc_400098 = "連鎖技が敵に命中すると、その敵に亀裂の印を1スタック付与する（最大5スタック）。印1スタックごとにクスッタのダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410098 = "連鎖技が敵に命中すると、その敵に亀裂の印を1スタック付与する（最大5スタック）。印1スタックごとにクスッタのダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420098 = "連鎖技が敵に命中すると、その敵に亀裂の印を1スタック付与する（最大5スタック）。印1スタックごとにクスッタのダメージ+<color=#00F6FF>{1}</color>。通常攻撃をすると<color=#00F6FF>30%</color>の確率で印を1スタック付与する",
  str_skill_passive_desc_4200981 = "連鎖技が敵に命中すると、その敵に亀裂の印を1スタック付与する（最大10スタック）。印1スタックごとにクスッタのダメージ+<color=#00F6FF>6%</color>。通常攻撃をすると<color=#00F6FF>30%</color>の確率で印を1スタック付与する",
  str_skill_passive_desc_400094 = "連鎖技がターゲットに命中すると、そのターゲットの攻撃力-<color=#00F6FF>{1}</color>、1ターン持続",
  str_skill_passive_desc_410094 = "連鎖技がターゲットに命中すると、そのターゲットの攻撃力-<color=#00F6FF>{1}</color>、1ターン持続",
  str_skill_passive_desc_400096 = "<link=\"30013\"><#FFAE07><u>シャリーの印</u></color></link>を獲得できる。最大8スタック。印1スタックごとにシャリーの防御力+<color=#00F6FF>{1}</color>。ターン終了時、印のスタック数が半分になる",
  str_skill_passive_desc_410096 = "<link=\"30013\"><#FFAE07><u>シャリーの印</u></color></link>を獲得できる。最大8スタック。印1スタックごとにシャリーの防御力+<color=#00F6FF>{1}</color>。ターン終了時、印のスタック数が半分になる",
  str_skill_passive_desc_420096 = "<link=\"30013\"><#FFAE07><u>シャリーの印</u></color></link>を獲得できる。最大8スタック。印1スタックごとにシャリーの防御力+<color=#00F6FF>{1}</color>。失ったHPにもとづいて防御効果が上昇し、最大で+<color=#00F6FF>50%</color>。ターン終了時、印のスタック数が半分になる",
  str_skill_passive_desc_400056 = "通常攻撃または能動技がダメージを与えると（最高値をとる）、ダメージの<color=#00F6FF>{1}</color>を攻撃力に変換する。現在のターンでのみ有効",
  str_skill_passive_desc_410056 = "通常攻撃または能動技がダメージを与えると（最高値をとる）、ダメージの<color=#00F6FF>{1}</color>を攻撃力に変換する。現在のターンでのみ有効",
  str_skill_passive_desc_430056 = "通常攻撃または能動技がダメージを与えると（最高値をとる）、ダメージの<color=#00F6FF>{1}</color>を攻撃力に変換する。現在のターンでのみ有効。戦場にいる敵が1体のみの場合、水属性の光霊の攻撃力+<color=#00F6FF>5%</color>",
  str_skill_passive_desc_400103 = "3ターンごとに1回、虚ろなる瞳が発動状態になる（使用しなかった場合状態を維持する）。発動状態では連鎖技がエルシーの<color=#00F6FF>{1}</color>攻撃力に応じて防御力無視のダメージを与え、同量のHPを回復する",
  str_skill_passive_desc_410103 = "3ターンごとに1回、虚ろなる瞳が発動状態になる（使用しなかった場合状態を維持する）。発動状態では連鎖技がエルシーの<color=#00F6FF>{1}</color>攻撃力に応じて防御力無視のダメージを与え、同量のHPを回復する",
  str_skill_passive_desc_430103 = "3ターンごとに1回、虚ろなる瞳が発動状態になる（使用しなかった場合は状態を維持する） 。発動状態では連鎖技がエルシーの攻撃力<color=#00F6FF>{1}</color>の防御力無視のダメージを与え、同量のHPを回復する。チームのHPが少ないほど回復効果は上昇する。最大+<color=#00F6FF>50%</color>まで",
  str_skill_passive_desc_410067 = "このターンにHPを回復すると、アリスの基礎防御力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430067 = "このターンにHPを回復すると、アリスの基礎防御力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_400030 = "通常攻撃で<color=#00F6FF>斜め方向への攻撃が可能</color>。さらに斜め方向の通常攻撃はターゲットに崩壊状態を1スタック付与する。最大5スタック。1スタックごとに目標の防御力をサメヤマの基礎防御力の<color=#00F6FF>{1}</color>ダウン。1ターン持続",
  str_skill_passive_desc_410030 = "通常攻撃で<color=#00F6FF>斜め方向への攻撃が可能</color>。さらに斜め方向の通常攻撃はターゲットに崩壊状態を1スタック付与する。最大5スタック。1スタックごとに目標の防御力をサメヤマの基礎防御力の<color=#00F6FF>{1}</color>ダウン。1ターン持続",
  str_skill_passive_desc_430030 = "通常攻撃で<color=#00F6FF>斜め方向への攻撃が可能</color>。さらに斜め方向の通常攻撃、能動技、連鎖技いずれもターゲットに崩壊状態を1スタック付与する。最大5スタック。1スタックごとに目標の防御力をサメヤマの基礎防御力の<color=#00F6FF>{1}</color>ダウン。1ターン持続",
  str_skill_passive_desc_410104 = "能動技が攻撃した敵をマークする。ドーンが能動技か連鎖技でマークした敵を攻撃すると、マークを消費して、今回与えたダメージの<color=#00F6FF>{1}</color>にあたるHPを回復する",
  str_skill_passive_desc_430104 = "能動技が攻撃した敵をマークする。ドーンが能動技か連鎖技でマークした敵を攻撃すると、マークを消費して、今回与えたダメージの<color=#00F6FF>{1}</color>にあたるHPを回復する。チームHPが最大の場合、今回の攻撃の最終ダメージ+<color=#00F6FF>25%</color>",
  str_skill_passive_desc_410071 = "ターン開始時にHPが最も高い敵に灼印を付与し、対象へのタキの与ダメージがすべて<color=#00F6FF>{1}</color>アップする",
  str_skill_passive_desc_430071 = "毎ターン開始時にHP比率が最も高い敵に灼印を付与し、対象へのタキの全ての与ダメージが<color=#00F6FF>{1}</color>アップする。灼印の付与されている敵を倒すたびに、タキの攻撃力+<color=#00F6FF>3%</color>、ただし最大+<color=#00F6FF>30%</color>",
  str_skill_passive_desc_400105 = "能動技、連鎖技、通常攻撃で<color=#00F6FF>10</color>回ダメージを与えるごとに、敵全体に<color=#00F6FF>{1}</color>のダメージを1回与える",
  str_skill_passive_desc_410105 = "能動技、連鎖技、通常攻撃で<color=#00F6FF>10</color>回ダメージを与えるごとに、敵全体に<color=#00F6FF>{1}</color>のダメージを1回与える",
  str_skill_passive_desc_420105 = "能動技、連鎖技、通常攻撃で<color=#00F6FF>8</color>回ダメージを与えるごとに、敵全体に<color=#00F6FF>{1}</color>のダメージを1回与える",
  str_skill_passive_desc_430105 = "能動技、連鎖技、通常攻撃で<color=#00F6FF>8</color>回ダメージを与えるごとに、敵全体に<color=#00F6FF>{1}</color>のダメージを1回与える",
  str_skill_passive_desc_430109 = "毎ターン開始時にフォースを<color=#00F6FF>5</color>獲得する",
  str_skill_passive_desc_433109 = "毎ターン開始時にフォースを<color=#00F6FF>5</color>獲得する。各ターン1回目の通常攻撃でフォースを<color=#00F6FF>1</color>獲得し、その通常攻撃のダメージ+<color=#00F6FF>100%</color>",
  str_skill_passive_desc_430110 = "毎ターン開始時にフォースを<color=#00F6FF>5</color>獲得する。通常攻撃は<color=#00F6FF>30%</color>の確率で自分との距離が最も遠い敵に雷を1回落とす",
  str_skill_passive_desc_433110 = "毎ターン開始時にフォースを<color=#00F6FF>5</color>獲得し、能動技で敵を1体倒すたびにフォースを<color=#00F6FF>2</color>獲得する。通常攻撃は<color=#00F6FF>30%</color>の確率で自身から最も遠くにいる敵に雷撃を1回放つ",
  str_skill_passive_desc_430107 = "戦闘開始時にフォースを10獲得する。ターン終了時に強化状態でなければ、フォースを<color=#00F6FF>5</color>獲得できる（さらにHP損失20%ごとにフォースを1追加獲得）",
  str_skill_passive_desc_436107 = "戦闘開始時にフォースを10獲得する。各ターン開始時、周囲の<color=#00F6FF>十字方向4マス</color>にいる敵1体につき、フォースを<color=#00F6FF>1</color>獲得する。ターン終了時に強化状態でなければ、フォースを<color=#00F6FF>5</color>獲得できる（さらにHP損失20%ごとにフォースを1追加獲得）",
  str_skill_passive_desc_430108 = "毎ターン開始時にフォースを<color=#00F6FF>5</color>獲得する。能動技でターゲットを倒すとフォースを<color=#00F6FF>5</color>獲得する",
  str_skill_passive_desc_400116 = "フェラールがHP残量40%以下の敵に与える全ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410112 = "<color=#00F6FF>それぞれの</color>敵に対するスモーキーの<color=#00F6FF>能動技、連鎖技、各ターン1回目の通常攻撃</color>でいずれも<color=#00F6FF>炎のキス</color>が発動し、追加でスモーキーの攻撃力の<color=#00F6FF>{1}</color>の防御力無視ダメージを与える。繰り返して発動すると効果は徐々に低下し、最低で最初の効果の<color=#00F6FF>20%</color>となる",
  str_skill_passive_desc_420112 = "<color=#00F6FF>それぞれの</color>敵に対するスモーキーの<color=#00F6FF>能動技、連鎖技、各ターン1回目の通常攻撃</color>でいずれも<color=#00F6FF>炎のキス</color>が発動し、追加でスモーキーの攻撃力の<color=#00F6FF>{1}</color>の防御力無視ダメージを与える。繰り返して発動すると効果は徐々に低下し、最低で最初の効果の<color=#00F6FF>20%</color>となる。火属性のマスにいる敵に対する<color=#00F6FF>炎のキス</color>の与ダメージが<color=#00F6FF>2倍</color>になる",
  str_skill_passive_desc_430112 = "<color=#00F6FF>それぞれの</color>敵に対するスモーキーの<color=#00F6FF>能動技、連鎖技、各ターン1回目の通常攻撃</color>でいずれも<color=#00F6FF>炎のキス</color>が発動し、追加でスモーキーの攻撃力の<color=#00F6FF>{1}</color>の防御力無視ダメージを与える。繰り返して発動すると効果は徐々に低下し、最低で最初の効果の<color=#00F6FF>20%</color>となる。火属性のマスにいる敵に対する<color=#00F6FF>炎のキス</color>の与ダメージが<color=#00F6FF>2倍</color>になる",
  str_skill_passive_desc_400113 = "戦闘開始時または能動技使用時に、神鳴りの印を獲得する。印の保有中はボナーズの防御力+<color=#00F6FF>{1}</color>。HPを失うと印は消える",
  str_skill_passive_desc_410113 = "戦闘開始時または能動技使用時に、神鳴りの印を獲得する。印の保有中はボナーズの防御力+<color=#00F6FF>{1}</color>。HPを失うと印は消える",
  str_skill_passive_desc_420113 = "戦闘開始時または能動技使用時に、神鳴りの印を獲得する。印の保有中はボナーズの防御力+<color=#00F6FF>{1}</color>および出撃している雷属性光霊の連鎖技ダメージ+<color=#00F6FF>10%</color>。HPを失うと印は消える",
  str_skill_passive_desc_400114 = "能動技でダメージを与えると、そのダメージの<color=#00F6FF>{1}</color>相当のチームHPを回復する",
  str_skill_passive_desc_410114 = "能動技でダメージを与えると、そのダメージの<color=#00F6FF>{1}</color>相当のチームHPを回復する",
  str_skill_passive_desc_430114 = "能動技でダメージを与えると、そのダメージの<color=#00F6FF>{1}</color>のチームHPを回復し、このターン火属性光霊の連鎖技ダメージが<color=#00F6FF>10%</color>アップする",
  str_skill_passive_desc_410127 = "毎ターン開始時、自分の<color=#00F6FF>周囲2マス以内</color>に敵がいる場合、その中の任意の1体の敵に短刀を投げて<color=#00F6FF>{1}</color>のダメージを与え、<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_passive_desc_430127 = "毎ターン開始時、自分の<color=#00F6FF>周囲2マス以内</color>に敵がいる場合、その中の任意の1体の敵に短刀を投げて<color=#00F6FF>{1}</color>のダメージを与え、<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態を1スタック付与する。2ターン持続。折り鶴を通過した時も短刀投擲効果が発動する",
  str_skill_desc_3351221 = "マスを1つ選択し、<color=#00F6FF>縦、横、斜め16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、選択したマスに防御力無視のダメージを与える。さらに範囲内の<color=#00F6FF>マス損傷</color>効果をクリアし、祝福が10スタックになると能動技の範囲が<color=#00F6FF>縦、横、斜めの最大</color>範囲になる。",
  str_skill_passive_desc_410117 = "<link=\"30016\"><#FFAE07><u>勇敢値</u></color></link>を獲得できる。勇敢値1スタックごとにグラムの基礎攻撃力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430117 = "<link=\"30017\"><#FFAE07><u>勇敢値</u></color></link>を獲得できる。勇敢値1スタックごとにグラムの基礎攻撃力+<color=#00F6FF>{1}</color>。能動技で獲得する勇敢値に上限はなく、ウェーブが終了するとクリアされる。1スタッククリアするごとに、グラムの最大HPの<color=#00F6FF>5%</color>相当のHPを回復する",
  str_skill_passive_desc_410119 = "<link=\"30018\"><#FFAE07><u>大胆値</u></color></link>を獲得できる。大胆値1スタックごとにレビィの基礎攻撃力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420119 = "<link=\"30018\"><#FFAE07><u>大胆値</u></color></link>を獲得できる。大胆値1スタックごとにレビィの基礎攻撃力+<color=#00F6FF>{1}</color>、能動技ダメージ+<color=#00F6FF>5%</color>",
  str_skill_passive_desc_430119 = "<link=\"30018\"><#FFAE07><u>大胆値</u></color></link>を獲得できる。大胆値1スタックごとにレビィの基礎攻撃力+<color=#00F6FF>{1}</color>、能動技ダメージ+<color=#00F6FF>5%</color>。さらに通常攻撃で<color=#00F6FF>斜め方向の敵を攻撃できる</color>",
  str_skill_passive_desc_410122 = "<link=\"30019\"><#FFAE07><u>祝福</u></color></link>を獲得できる。祝福1スタックにつき、アルーラの能動技ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410121 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を通るごとに茨の印を1スタック獲得。印1スタックごとに連鎖技ダメージ+<color=#00F6FF>{1}</color>。ターン終了時、印のスタック数が半分になる",
  str_skill_passive_desc_430121 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を通るごとに茨の印を1スタック獲得。印1スタックごとに連鎖技と通常攻撃のダメージ+<color=#00F6FF>{1}</color>。ターン終了時、印のスタック数が半分になる",
  str_skill_passive_desc_410065 = "連鎖技が敵1体に命中するごとに雀の印を1スタック獲得する。1スタックにつき自身の防御力+<color=#00F6FF>{1}</color>。ターンが終了すると印は消える",
  str_skill_passive_desc_410115 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を通るごとに、碧翠の印を1スタック獲得する。印1スタックにつき、ナルセールの基礎攻撃力+<color=#00F6FF>{1}</color>。ターン終了時、印のスタック数が半分になる",
  str_skill_passive_desc_430115 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を通るごとに、碧翠の印を1スタック獲得する。印1スタックにつき、チーム全員の基礎攻撃力がナルセールの基礎攻撃力の<color=#00F6FF>{1}</color>相当増加する。ターン終了時、印のスタック数が半分になる",
  str_skill_passive_desc_410126 = "能動技で選択したマス上に<link=\"30024\"><#FFAE07><u>フランク</u></color></link>を召喚する。チームの光霊が能動技を発動するたびに、フランクは<color=#00F6FF>咆哮</color>を発動し、<color=#00F6FF>周囲1マス</color>の範囲の敵に<color=#00F6FF>{1}</color>のダメージを与える。フランクは消滅時にも<color=#00F6FF>咆哮</color>を発動する",
  str_skill_passive_desc_420126 = "能動技で選択したマス上に<link=\"30024\"><#FFAE07><u>フランク</u></color></link>を召喚する。チームの光霊が能動技を発動するたびに、フランクは<color=#00F6FF>咆哮</color>し、<color=#00F6FF>周囲1マス</color>の範囲の敵に<color=#00F6FF>{1}</color>のダメージを与える。範囲内にいる敵が1体のみの場合、<color=#00F6FF>爪攻撃</color>に変わり、ダメージ+<color=#00F6FF>50%</color>。フランクは消滅時にも<color=#00F6FF>咆哮</color>を発動する",
  str_skill_passive_desc_410129 = "能動技と連鎖技で1回のダメージを与えるごとに、敵に1スタックの寄生の印を追加する。上限<color=#00F6FF>9</color>スタック。敵が1マス移動する度、寄生の印1スタックごとに<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_420129 = "能動技と連鎖技でダメージを1回与えるごとに、敵に1スタックの寄生の印を追加する。上限<color=#00F6FF>9</color>スタック。敵が1マス移動する度、寄生の印1スタックごとに<color=#00F6FF>{1}</color>のダメージを与える。スタック数の最も多い敵に対するルークの通常攻撃と連鎖ダメージがそれぞれ+<color=#00F6FF>30%</color>",
  str_skill_passive_desc_430129 = "能動技と連鎖技でダメージを1回与えるごとに、敵に1スタックの寄生の印を追加する。上限<color=#00F6FF>9</color>スタック。敵が1マス移動する度、寄生の印1スタックごとに<color=#00F6FF>{1}</color>のダメージを与える。その敵の印のスタック数が戦場で最多だった場合、ダメージは<color=#00F6FF>{2}</color>にアップする。スタック数の最も多い敵に対するルークの通常攻撃と連鎖ダメージがそれぞれ+<color=#00F6FF>30%</color>",
  str_skill_passive_desc_410055 = "攻撃を受けると1スタックの戦痕を獲得できる。最大<color=#00F6FF>15</color>スタック。1スタックの戦痕で攻撃力+<color=#00F6FF>{1}</color>、1ターンごとに戦痕スタック数-50%",
  str_skill_passive_desc_420055 = "攻撃を受けると1スタックの戦痕を獲得できる。最大<color=#00F6FF>15</color>スタック。1スタックの戦痕で攻撃力と防御力それぞれ+<color=#00F6FF>{1}</color>、1ターンごとに戦痕スタック数-50%",
  str_skill_passive_desc_430055 = "攻撃を受けると1スタックの戦痕を獲得できる。最大<color=#00F6FF>15</color>スタック。1スタックの戦痕で攻撃力と防御力それぞれ+<color=#00F6FF>{1}</color>、1ターンごとに戦痕スタック数-50%、ピアタマン最大HPの<color=#00F6FF>12%</color>に相当するシールドを獲得できる",
  str_skill_passive_desc_410120 = "連鎖技と能動技の発動時、ポンペイが出現し、ヘイディに代わって攻撃する。ポンペイの攻撃力はヘイディの攻撃力の<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430120 = "連鎖技と能動技の発動時、ポンペイが出現し、ヘイディに代わって攻撃する。ポンペイの攻撃力はヘイディの攻撃力の<color=#00F6FF>{1}</color>。極光タイム中、1マス連鎖するごとに、ポンペイの攻撃力+<color=#00F6FF>2%</color>、最高+<color=#00F6FF>30%</color>",
  str_skill_passive_desc_410123 = "<color=#00F6FF>周囲菱形12マス</color>の範囲内にいる敵1体につき、攻撃力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430123 = "<color=#00F6FF>周囲2マス</color>以内にいる敵1体につき、攻撃力と防御力それぞれ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410015 = "能動技がダメージを与える前に手榴弾が進んだマスの数1つにつき、最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420015 = "能動技がダメージを与える前に手榴弾が進んだマスの数1つにつき、最終ダメージ+<color=#00F6FF>{1}</color>。連鎖技がダメージを与える前に榴弾が進んだマスの数1つにつき、最終ダメージ+<color=#00F6FF>{2}</color>",
  str_skill_passive_desc_410131 = "通常攻撃前にチームHPが最大でない場合、その通常攻撃の効果が「ノーヴィオの攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復」に変化する",
  str_skill_passive_desc_430131 = "通常攻撃前にチームHPが最大でない場合、その通常攻撃の効果が「ノーヴィオの攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復」に変化する。チームHPが最大の場合、通常攻撃と連鎖ダメージがそれぞれ+<color=#00F6FF>10%</color>、さらにシールドを展開している場合、強化効果が<color=#00F6FF>25%</color>まで上昇する",
  str_skill_passive_desc_410132 = "極光タイムの発動中、攻撃力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430132 = "極光タイムの発動中、攻撃力+<color=#00F6FF>{1}</color>。さらにいずれの属性のマスでも連鎖技を発動できる。この時連鎖技のダメージは常に森属性として扱われる",
  str_skill_passive_desc_410133 = "コンボ数1回につき、連鎖技ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430133 = "コンボ数1回につき、連鎖技ダメージ+<color=#00F6FF>{1}</color>、飛散ダメージ+<color=#00F6FF>{2}</color>",
  str_skill_passive_desc_410137 = "能動技で選択された敵にダメージを与える。敵の足元にある水属性のマス<color=#00F6FF>1</color>マスにつき、ファフニールの攻撃力の<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_430137 = "能動技で選択された敵にダメージを与える。敵の足元にある水属性のマス<color=#00F6FF>1</color>マスにつき、ファフニールの攻撃力の<color=#00F6FF>{1}</color>のダメージを与える。自身以外の『小林さんちのメイドラゴン』コラボキャラの能動技が敵に命中した場合も、同様のダメージ効果が発動する",
  str_skill_passive_desc_410134 = "カンナの能動技を発動する時、エネルギーを3スタック獲得。他の雷属性光霊または『小林さんちのメイドラゴン』コラボユニットが能動技を発動する時、エネルギーを1スタック獲得。最大10スタックまで。エネルギー1スタックごとに、基礎攻撃力が<color=#00F6FF>{1}</color>上昇する。ターン終了後、エネルギーはすべて消える",
  str_skill_passive_desc_430134 = "カンナの能動技を発動する時、エネルギーを3スタック獲得。他の雷属性光霊または『小林さんちのメイドラゴン』コラボユニットが能動技を発動する時、エネルギーを1スタック獲得。最大10スタックまで。エネルギー1スタックごとに、基礎攻撃力が<color=#00F6FF>{1}</color>上昇する。ターン終了時、エネルギーのスタック数が半減する",
  str_skill_passive_desc_416134 = "カンナの能動技を発動する時、エネルギーを3スタック獲得。他の雷属性光霊または『小林さんちのメイドラゴン』コラボユニットが能動技を発動する時、エネルギーを1スタック獲得。最大10スタックまで。エネルギー1スタックごとに、基礎攻撃力が<color=#00F6FF>{1}</color>上昇する。ターン終了後、エネルギーはすべて消える。各ウェーブ開始時、カンナがエネルギーを2スタック獲得する",
  str_skill_passive_desc_436134 = "カンナの能動技を発動する時、エネルギーを3スタック獲得。他の雷属性光霊または『小林さんちのメイドラゴン』コラボユニットが能動技を発動する時、エネルギーを1スタック獲得。最大10スタックまで。エネルギー1スタックごとに、基礎攻撃力が<color=#00F6FF>{1}</color>上昇する。ターン終了時、エネルギーのスタック数が半減する。各ウェーブ開始時、カンナがエネルギーを2スタック獲得する",
  str_skill_passive_desc_410135 = "HP最大時、通常攻撃のダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430135 = "HP最大時、通常攻撃、連鎖技、能動技のダメージがすべて+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_410136 = "連鎖技命中時、対象に塵界の印を付与する。印1スタックにつき、その敵が受けるすべての光霊の能動技ダメージ+<color=#00F6FF>{1}</color>。印は最大<color=#00F6FF>10</color>スタック。そのバトル中持続する",
  str_skill_desc_200501 = "<color=#00F6FF>X形の8マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_210501 = "<color=#00F6FF>X形の8マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200221 = "<color=#00F6FF>十字方向8マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする",
  str_skill_desc_200471 = "ゾーヤの攻撃力の<color=#00F6FF>160%</color>相当のチームHPを回復する",
  str_skill_desc_210471 = "ゾーヤの攻撃力の<color=#00F6FF>210%</color>相当のチームHPを回復する",
  str_skill_desc_200491 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_210491 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
