  str_skill_desc_200521 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200071 = "<color=#00F6FF>十字方向12マス</color>に<color=#00F6FF>{1}%</color>のダメージを<color=#00F6FF>2</color>回与える",
  str_skill_desc_200081 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
