  str_skill_desc_200401 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200411 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200211 = "<color=#00F6FF>十字方向8マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_204211 = "<color=#00F6FF>十字方向8マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。<color=#00F6FF>30%</color>の確率でさらに1スタック追加。2ターン持続",
  str_skill_desc_200041 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200731 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200611 = "<color=#00F6FF>周囲2マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200541 = "ナディーンの攻撃力の<color=#00F6FF>165%</color>相当のチームHPを回復する",
  str_skill_desc_220541 = "ナディーンの攻撃力の<color=#00F6FF>195%</color>相当のチームHPを回復する",
  str_skill_desc_200161 = "最も近くにいる敵1体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_desc_230161 = "最も近くにいる敵1体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>50%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_desc_200461 = "<color=#00F6FF>周囲4マス</color>以内の敵<color=#00F6FF>3</color>体に<color=#00F6FF>{1}%</color>のダメージを与え、嘲笑の印を1スタック付与する（最大8スタック）",
  str_skill_desc_220461 = "<color=#00F6FF>周囲4マス</color>以内の敵<color=#00F6FF>3</color>体に<color=#00F6FF>{1}%</color>のダメージを与え、嘲笑の印を1スタック付与する（最大8スタック）。印1スタックごとに連鎖ダメージ+<color=#00F6FF>5%</color>",
  str_skill_desc_200441 = "<color=#00F6FF>周囲3マス</color>以内の敵<color=#00F6FF>3</color>体に<color=#00F6FF>{1}%</color>のダメージを与える",
