  str_skill_desc_200191 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_200231 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_210231 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_220231 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える。印がスタックされている場合、印1スタックごとに連鎖ダメージ+5%",
  str_skill_desc_200021 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
