  str_skill_desc_200251 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200261 = "<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"10002\"><#FFAE07><u>火傷</u></color></link>状態を1スタック付与する。最大5スタック、2ターン持続",
