  str_skill_desc_200263 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"10002\"><#FFAE07><u>火傷</u></color></link>状態を1スタック付与する。最大5スタック、2ターン持続",
  str_skill_desc_220263 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える。さらに<link=\"10002\"><#FFAE07><u>火傷</u></color></link>状態を1スタック付与し、<color=#00F6FF>30%</color>の確率でさらに1スタック追加する。最大5スタック、2ターン持続",
  str_skill_desc_200283 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
