  str_skill_desc_200383 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200773 = "<color=#00F6FF>縦、横、斜めの最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_210773 = "<color=#00F6FF>縦、横、斜めの最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200923 = "<color=#00F6FF>X形の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、森属性のマスにいる敵に<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。2ターン持続。さらにそのターゲットをマークする",
  str_skill_desc_210923 = "<color=#00F6FF>X形の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、森属性のマスにいる敵に<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。2ターン持続。さらにそのターゲットをマークする",
  str_skill_desc_220923 = "<color=#00F6FF>X形の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、森属性のマスにいる敵に<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。2ターン持続。さらにそのターゲットをマークする",
  str_skill_desc_200753 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える。さらに<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_200573 = "フィリスの攻撃力の<color=#00F6FF>240%</color>相当のチームHPを回復する",
  str_skill_desc_200893 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200273 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200603 = "<color=#00F6FF>周囲4マス</color>以内の敵4体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_200643 = "最も近い敵3体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>にいる敵に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_desc_206643 = "最も近い敵3体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>にいる敵に<color=#00F6FF>50%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_desc_220643 = "最も近い敵3体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>にいる敵に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。オーバーロード状態の場合、飛散の範囲が<color=#00F6FF>周囲1マス</color>に拡大",
