  str_skill_upgrade_desc_15013912 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15013915 = "能動技強化：周囲<color=#FFFF00>8</color>方向を選択できる",
  str_skill_desc_300139 = "自身の周囲<color=#00F6FF>4</color>方向のうち1つを選び、その直線上のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内の<color=#00F6FF>雷属性以外</color>のマスをリセットする",
  str_skill_desc_302139 = "自身の周囲<color=#00F6FF>8</color>方向のうち1つを選び、その直線上のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内の<color=#00F6FF>雷属性以外</color>のマスをリセットする",
  str_skill_desc_320139 = "自身の周囲<color=#00F6FF>4</color>方向のうち1つを選び、その直線上のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与え、さらに直線上にいるランダムな敵1体に1ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>状態を付与する。範囲内の<color=#00F6FF>雷属性以外</color>のマスをリセットする",
  str_skill_desc_322139 = "自身の周囲<color=#00F6FF>8</color>方向のうち1つを選び、その直線上のマスおよび隣接するマスの敵に<color=#00F6FF>{1}%</color>のダメージを与え、さらに直線上にいるランダムな敵1体に1ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>状態を付与する。範囲内の<color=#00F6FF>雷属性以外</color>のマスをリセットする",
  str_skill_desc_2001391 = "<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001392 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001393 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_passive_desc_410139 = "雷属性のマス上の敵にダメージを与える時、その敵との間隔1マスにつき、エリカのダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430139 = "雷属性のマス上の敵にダメージを与える時、その敵との間隔1マスにつき、エリカのダメージ+<color=#00F6FF>{1}</color>。チーム内の他の雷属性の光霊が半分のダメージバフを獲得する",
  str_skill_name_300138 = "八足の領域",
  str_skill_name_320138 = "八足の領域",
  str_skill_name_330138 = "八足の領域",
  str_skill_name_2001381 = "引き裂く蛛行",
  str_skill_name_2001382 = "引き裂く蛛行",
  str_skill_name_2001383 = "引き裂く蛛行",
  str_skill_passive_name_410138 = "蜘蛛糸の盾",
  str_skill_passive_name_416138 = "蜘蛛糸の盾",
  str_skill_upgrade_desc_16013813 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16013816 = "装備技強化：<link=\"30025\"><#FFAE07><u>蜘蛛糸の印</u></color></link>でシールドを獲得時、印のスタック数が10スタック以上の場合、追加でシヴォーンのHPの<color=#00F6FF>15%</color>相当のシールドを獲得する",
  str_skill_desc_300138 = "任意のマスを起点として1マス選択し、さらに2×2または1×4の範囲になるよう終点をタップして指定する。指定範囲内のマスを森属性に変える",
  str_skill_desc_320138 = "任意のマスを起点として1マス選択し、さらに2×2または1×4の範囲になるよう終点をタップして指定する。指定範囲内のマスを森属性に変える。起点と終点は<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変わる",
  str_skill_desc_330138 = "任意のマスを起点として1マス選択し、さらに2×2または1×4の範囲になるよう終点をタップして指定する。指定範囲内のマスを森属性に変える。起点と終点は<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変わる。極光タイム発動中に15連鎖を達成すると、能動技のCDターン数<color=#00F6FF>-1</color>",
  str_skill_desc_2001381 = "<color=#00F6FF>周囲4マス</color>以内の最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001382 = "<color=#00F6FF>周囲4マス</color>以内の最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001383 = "<color=#00F6FF>周囲4マス</color>以内のすべての敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_passive_desc_410138 = "<link=\"30025\"><#FFAE07><u>蜘蛛糸の印</u></color></link>を獲得できる。攻撃を受ける直前にスタック数をクリアし、1スタックにつきシヴォーンの防御力の<color=#00F6FF>{1}</color>相当のシールドを付与する",
  str_skill_passive_desc_416138 = "<link=\"30025\"><#FFAE07><u>蜘蛛糸の印</u></color></link>を獲得できる。攻撃を受ける直前にスタック数をクリアし、1スタックにつきシヴォーンの防御力の<color=#00F6FF>{1}</color>相当のシールドを付与する。<link=\"30025\"><#FFAE07><u>蜘蛛糸の印</u></color></link>でシールドを獲得時、印のスタック数が10スタック以上の場合、追加でシヴォーンのHPの<color=#00F6FF>15%</color>相当のシールドを獲得する",
  str_skill_upgrade_desc_16014113 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16014116 = "能動技強化：足元のマスをタップすると、ノックバックと転色の方向を内向きに切り替えられる",
  str_skill_desc_2001411 = "最も近くにいる敵2体に<color=#00F6FF>115%</color>のダメージを与える。敵が1体しかいない場合、ダメージを2回与える",
  str_skill_desc_2001412 = "最も近くにいる敵2体に<color=#00F6FF>130%</color>のダメージを与える。敵が1体しかいない場合、ダメージを2回与える",
  str_skill_desc_2001413 = "最も近くにいる敵2体に<color=#00F6FF>150%</color>のダメージを与える。敵が1体しかいない場合、ダメージを2回与える",
  str_skill_desc_300141 = "<color=#00F6FF>十字方向の最大</color>または<color=#00F6FF>X字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲内のマスを水属性に変える",
  str_skill_desc_306141 = "<color=#00F6FF>十字方向の最大</color>または<color=#00F6FF>X字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲内のマスを水属性に変える。足元のマスをタップすると、ノックバックと転色の方向を内向きに切り替えられる",
  str_skill_desc_320141 = "<color=#00F6FF>十字方向の最大</color>または<color=#00F6FF>X字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲内のマスを水属性に変える。命中した敵に現在の装備技レベルに基づいたダメージを1回与える",
  str_skill_desc_326141 = "<color=#00F6FF>十字方向の最大</color>または<color=#00F6FF>X字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲内のマスを水属性に変える。足元のマスをタップすると、ノックバックと転色の方向を内向きに切り替えられる。さらに命中した敵に現在の装備技レベルに基づいたダメージを1回与える",
  str_skill_passive_desc_410141 = "連鎖技が同じターゲットにダメージを<color=#00F6FF>3</color>回与えるごとに、ターゲットの現在のHPの<color=#00F6FF>{1}</color>相当の追加ダメージを1回発動する",
  str_skill_passive_desc_420141 = "連鎖技が同じターゲットにダメージを<color=#00F6FF>3</color>回与えるごとに、ターゲットの現在のHPの<color=#00F6FF>{1}</color>相当の追加ダメージを1回発動する",
  str_skill_passive_desc_430141 = "連鎖技が同じターゲットにダメージを<color=#00F6FF>3</color>回与えるごとに、ターゲットの現在のHPの<color=#00F6FF>{1}</color>相当の追加ダメージを1回発動する。このダメージは最低でもルビーの基礎防御力の<color=#00F6FF>{2}</color>",
