  str_skill_desc_2001422 = "<color=#00F6FF>菱形12マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001423 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300142 = "周囲<color=#00F6FF>菱形13マス</color>の中から1マス選択し、選択したマスおよびその<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>BOSS以外の</color>敵を選択したマスの方向に<color=#00F6FF>2</color>マス移動させる。ダメージ係数は周囲1マスごとに53%減少する",
  str_skill_desc_302142 = "周囲<color=#00F6FF>菱形13マス</color>の中から1マス選択し、選択したマスおよびその<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>BOSS以外の</color>敵を選択したマスの方向に<color=#00F6FF>2</color>マス移動させる。ダメージ係数は周囲1マスごとに53%減少する",
  str_skill_desc_320142 = "周囲<color=#00F6FF>菱形13マス</color>の中から1マス選択し、選択したマスおよびその<color=#00F6FF>周囲3マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>BOSS以外の</color>敵を選択したマスの方向に<color=#00F6FF>2</color>マス移動させる。ダメージ係数は周囲1マスごとに53%減少する",
  str_skill_desc_322142 = "周囲<color=#00F6FF>菱形13マス</color>の中から1マス選択し、選択したマスおよびその<color=#00F6FF>周囲3マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内の<color=#00F6FF>BOSS以外の</color>敵を選択したマスの方向に<color=#00F6FF>2</color>マス移動させる。ダメージ係数は周囲1マスごとに53%減少する",
  str_skill_passive_desc_410142 = "<color=#00F6FF>3</color>回ごとに通常攻撃のダメージがターゲットの現在HPに応じて上昇する。ターゲットのHPが最大の時、強化効果は最大の<color=#00F6FF>{1}</color>になる",
  str_skill_passive_desc_420142 = "<color=#00F6FF>3</color>回ごと、および<color=#00F6FF>5</color>回ごとに通常攻撃のダメージがターゲットの現在HPに応じて上昇する。ターゲットのHPが最大の時、強化効果は最大の<color=#00F6FF>{1}</color>になる",
