  str_skill_desc_2001401 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001402 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001403 = "<color=#00F6FF>周囲2マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300140 = "使用すると、そのターンは雷属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての雷属性光霊の攻撃力がフロリナの攻撃力の<color=#00F6FF>80%</color>になる",
  str_skill_desc_306140 = "使用すると、そのターンは雷属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できる。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての雷属性光霊の攻撃力がフロリナの攻撃力の<color=#00F6FF>80%</color>になる",
  str_skill_desc_320140 = "使用すると、そのターンは雷属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できると同時に、雷属性光霊の連鎖技発動に必要なマス数<color=#00F6FF>-1</color>。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての雷属性光霊の攻撃力がフロリナの攻撃力の<color=#00F6FF>80%</color>になる。",
  str_skill_desc_326140 = "使用すると、そのターンは雷属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できると同時に、雷属性光霊の連鎖技発動に必要なマス数<color=#00F6FF>-1</color>。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての雷属性光霊の攻撃力がフロリナの攻撃力の<color=#00F6FF>80%</color>になる。",
  str_skill_desc_330140 = "使用すると、そのターンは雷属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できると同時に、雷属性光霊の連鎖技発動に必要なマス数<color=#00F6FF>-1</color>。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての雷属性光霊の攻撃力がフロリナの攻撃力の<color=#00F6FF>95%</color>になる。",
  str_skill_desc_336140 = "使用すると、そのターンは雷属性光霊の連鎖技を<color=#00F6FF>2</color>回発動できると同時に、雷属性光霊の連鎖技発動に必要なマス数<color=#00F6FF>-1</color>。<color=#00F6FF>2</color>回目の連鎖技が発動中は、全ての雷属性光霊の攻撃力がフロリナの攻撃力の<color=#00F6FF>95%</color>になる。",
  str_skill_passive_desc_410140 = "全ての雷属性光霊の各レベル連鎖技のダメージ係数がそれぞれ<color=#00F6FF>{1}</color>/<color=#00F6FF>{2}</color>/<color=#00F6FF>{3}</color>上昇する",
