  str_skill_name_290200102 = "払い打ち",
  str_skill_desc_290200102 = "敵が自身の周囲2マス以内にいない時、範囲内の敵に遠距離攻撃し、光霊の隊列をランダムに変更する",
  str_skill_name_290200112 = "払い打ち",
  str_skill_desc_290200112 = "敵が自身の周囲2マス以内にいない時、範囲内の敵に遠距離攻撃し、光霊の隊列をランダムに変更する。藤雲信虎とターゲットの距離が遠いほど、ダメージが大きくなる",
