  str_skill_desc_2001432 = "<color=#00F6FF>周囲3マス</color>以内のすべての敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001433 = "<color=#00F6FF>周囲4マス</color>以内のすべての敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300143 = "自身を中心に<color=#00F6FF>周囲2マス</color>の範囲を覆う結界を展開する。2ターン持続。展開時およびターン終了時、ランダムで結界内の火属性ではない<color=#00F6FF>3</color>マスを火属性に転換し、さらに範囲内のすべての火属性マスに対して<link=\"30020\"><#FFAE07><u>浄化</u></color></link>を行う",
  str_skill_desc_306143 = "自身を中心に<color=#00F6FF>周囲2マス</color>の範囲を覆う結界を展開する。2ターン持続。展開時およびターン終了時、ランダムで結界内の火属性ではない<color=#00F6FF>3</color>マスを火属性に転換し、さらに範囲内のすべての火属性マスに対して<link=\"30020\"><#FFAE07><u>浄化</u></color></link>を行う",
  str_skill_desc_330143 = "自身を中心に<color=#00F6FF>周囲2マス</color>の範囲を覆う結界を展開する。2ターン持続。展開時およびターン終了時、ランダムで結界内の火属性ではない<color=#00F6FF>3</color>マスを火属性に転換し、さらに範囲内のすべての火属性マスに対して、<link=\"30020\"><#FFAE07><u>浄化</u></color></link>を行う。結界内にいる場合、リンネの防御力+<color=#00F6FF>50%</color>、その他の火属性光霊の防御力+<color=#00F6FF>10%</color>",
  str_skill_desc_336143 = "自身を中心に<color=#00F6FF>周囲2マス</color>の範囲を覆う結界を展開する。2ターン持続。展開時およびターン終了時、ランダムで結界内の火属性ではない<color=#00F6FF>3</color>マスを火属性に転換し、さらに範囲内のすべての火属性マスに対して、<link=\"30020\"><#FFAE07><u>浄化</u></color></link>を行う。結界内にいる場合、リンネの防御力+<color=#00F6FF>50%</color>、その他の火属性光霊の防御力+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_410143 = "リンネが何らかの方法により隊員から隊長になった時、その時の防御力の<color=#00F6FF>{1}</color>相当のHPを回復する。各ターン<color=#00F6FF>1</color>回まで発動できる",
  str_skill_passive_desc_416143 = "リンネが何らかの方法により隊員から隊長になった時、その時の防御力の<color=#00F6FF>{1}</color>相当のHPを回復する。各ターン<color=#00F6FF>1</color>回まで発動できる。この戦闘における隊長変更回数<color=#00F6FF>+1</color>",
  str_skill_passive_desc_420143 = "リンネが何らかの方法によりメンバーから隊長になった時、リンネのその時の防御力の<color=#00F6FF>{1}</color>相当のHPを回復する。発動後にHPが最大の場合、最も近くにある水属性マスを火属性に転換する。各ターン<color=#00F6FF>1</color>回まで発動できる",
  str_skill_passive_desc_426143 = "リンネが何らかの方法により隊員から隊長になった時、その時の防御力の<color=#00F6FF>{1}</color>相当のHPを回復する。発動後にHPが最大の場合、最も近くにある水属性マスを火属性に転換する。各ターン<color=#00F6FF>1</color>回まで発動できる。この戦闘における隊長変更回数<color=#00F6FF>+1</color>",
  str_skill_name_2001431 = "逐魔の魂魄",
  str_skill_name_2001432 = "逐魔の魂魄",
  str_skill_name_2001433 = "逐魔の魂魄",
  str_skill_name_300143 = "浄めの神楽",
  str_skill_name_306143 = "浄めの神楽",
  str_skill_name_330143 = "浄めの神楽",
  str_skill_name_336143 = "浄めの神楽",
  str_skill_passive_name_410143 = "神楽の道引き",
  str_skill_passive_name_420143 = "神楽の道引き",
  str_skill_upgrade_desc_15014412 = "能動技強化：任意の他の隊員と隊列を交換できる",
  str_skill_upgrade_desc_15014415 = "装備技強化：その戦闘における隊長変更回数<color=#FFFF00>+1</color>",
  str_skill_desc_2001441 = "<color=#00F6FF>周囲2マス</color>以内の敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001442 = "<color=#00F6FF>周囲3マス</color>以内の敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001443 = "<color=#00F6FF>周囲3マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300144 = "現在の隊長と隊列を交換する",
  str_skill_desc_302144 = "選択した他の隊員と隊列を交換する",
  str_skill_desc_305144 = "選択した他の隊員と位置交換する。その回の戦闘における隊長変更回数+<color=#00F6FF>1</color>",
  str_skill_desc_310144 = "現在の隊長と隊列を交換する",
  str_skill_desc_312144 = "選択した他の隊員と隊列を交換する",
  str_skill_desc_315144 = "選択した他の隊員と位置交換する。その回の戦闘における隊長変更回数+<color=#00F6FF>1</color>",
  str_skill_passive_desc_410144 = "自身が隊列の最後尾にいない場合、カヤノは強制的に最後尾まで移動し、その他の光霊は前に1人分ずつ隊列を詰める。現在のターン中に<color=#00F6FF>位置が後退したことのある</color>光霊にカヤノの基礎攻撃力の<color=#00F6FF>{1}</color>に相当する攻撃力強化を付与する（複数回発動した場合は最高値を取る）。",
  str_skill_passive_desc_420144 = "自身が隊列の最後尾にいない場合、カヤノは強制的に最後尾まで移動し、その他の光霊は前に1人分ずつ隊列を詰める。現在のターン中に<color=#00F6FF>位置が後退したことのある</color>光霊にカヤノの基礎攻撃力の<color=#00F6FF>{1}</color>に相当する攻撃力強化を付与する（複数回発動した場合は最高値を取る）。後退距離が長いほど強化値も高くなり、最高で基礎値の2.5倍になる",
  str_skill_passive_desc_430144 = "自身が隊列の最後尾にいない場合、カヤノは強制的に最後尾まで移動し、その他の光霊は前に1人分ずつ隊列を詰める。現在のターン中に<color=#00F6FF>位置が後退したことのある</color>光霊にカヤノの基礎攻撃力の<color=#00F6FF>{1}</color>に相当する攻撃力強化を付与する（複数回発動した場合は最高値を取る）。後退距離が長いほど強化値も高くなり、最高で基礎値の2.5倍になる。現在の隊長はこの効果によるカヤノの強化値と同等の攻撃力強化を受ける",
  str_skill_passive_desc_415144 = "自身が隊列の最後尾にいない場合、カヤノは強制的に最後尾まで移動し、その他の光霊は前に1人分ずつ隊列を詰める。現在のターン中、<color=#00F6FF>位置が後退したことのある</color>光霊にカヤノの基礎攻撃力の<color=#00F6FF>{1}</color>に相当する攻撃力強化を付与する（複数回発動した場合は最高値を取る）。この戦闘における隊長の変更回数<color=#00F6FF>+1</color>。",
  str_skill_passive_desc_425144 = "自身が隊列の最後尾にいない場合、カヤノは強制的に最後尾まで移動し、その他の光霊は前に1人分ずつ隊列を詰める。現在のターン中に<color=#00F6FF>位置が後退したことのある</color>光霊にカヤノの基礎攻撃力の<color=#00F6FF>{1}</color>に相当する攻撃力強化を付与する（複数回発動した場合は最高値を取る）。交代距離が長いほど強化量は高くなり、最高で基礎値の2.5倍になる。この戦闘における隊長の変更回数<color=#00F6FF>+1</color>。",
  str_skill_passive_desc_435144 = "自身が隊列の最後尾にいない場合、カヤノは強制的に最後尾まで移動し、その他の光霊は前に1人分ずつ隊列を詰める。現在のターン中に<color=#00F6FF>位置が後退したことのある</color>光霊にカヤノの基礎攻撃力の<color=#00F6FF>{1}</color>に相当する攻撃力強化を付与する（複数回発動した場合は最高値を取る）。後退距離が長いほど強化値も高くなり、最高で基礎値の2.5倍になる。現在の隊長はこの効果によるカヤノの強化値と同等の攻撃力強化を受ける。この戦闘における隊長の変更回数<color=#00F6FF>+1</color>。",
