  str_skill_name_290190110 = "冥土の幽刀・襲",
  str_skill_desc_290190110 = "プレイヤーの前方に突進して大ダメージを与え、隊長を隊列の最後尾に飛ばす。プレイヤーが十字範囲外かつ距離が遠い場合、遠距離攻撃を行う",
  str_skill_name_290190120 = "冥土の幽刀・撃",
  str_skill_desc_290190120 = "自身の付近にいるプレイヤーをなぎ払い、大ダメージを与える。プレイヤーが十字の範囲外かつ距離が遠い場合、遠距離攻撃を行う",
  str_skill_desc_490190120 = "突進終了後、自身の付近にいるプレイヤーをなぎ払い、大ダメージを与える",
  str_skill_name_290190130 = "冥土の幽刀・落",
  str_skill_desc_290190130 = "フィールドの中心に向かって移動後、銃を取り出し、十字範囲外の近距離にいるプレイヤーに遠距離攻撃を行う",
  str_skill_desc_490190130 = "銃を取り出し、なぎ払いの範囲外にいるプレイヤーに遠距離攻撃を行う",
  str_skill_name_290191110 = "ナギ・狂刃2連",
  str_skill_desc_290191110 = "迫る脅威に対抗するため、横斬りと突きを連続で繰り出す二段連撃",
  str_skill_name_290191120 = "ナギ・狂刃突進",
  str_skill_desc_290191120 = "プレイヤーとの距離が離れている場合、プレイヤーに突進しダメージを与える",
  str_skill_name_290191130 = "ナギ・狂刃瞬爆",
  str_skill_desc_290191130 = "戦場中央まで瞬間移動し、周囲に広範囲ダメージを与える。命中時、隊長を隊列の最後尾に飛ばす",
  str_skill_name_290210101 = "噬魔舌巻",
  str_skill_desc_290210101 = "ターゲットが範囲内にいる場合、前方2マス以内の光霊と「鬼」を呑み込み、光霊にダメージを与える。その後、横に光霊を吐き出し、隊長に呪いをかけ、隊列の最後尾に下げる",
  str_skill_desc_291210101 = "ターゲットが範囲内にいる場合、前方2マス以内の光霊と「鬼」を呑み込み、光霊にダメージを与える。その後、横に光霊を吐き出し、隊長を隊列の最後尾に下げる",
  str_skill_name_290210102 = "噬魔滅鬼",
  str_skill_desc_290210102 = "ターゲットが範囲内にいる時、ターゲットに大ダメージを与え、光霊の隊列を乱し、さらにターゲット周辺の「鬼」を即時に撃破する",
  str_skill_name_290210201 = "噬魔招鬼陣",
  str_skill_desc_290210201 = "ターゲットが範囲内にいる時、大量の「鬼」を召喚し、さらにフィールド上のすべての「鬼」を強化する",
  str_skill_desc_291210201 = "ターゲットが範囲内にいる時、大量の「鬼」を召喚し、さらにフィールド上のすべての「鬼」を強化ならびに回復させる",
  str_skill_name_290210301 = "噬魔舌巻",
  str_skill_desc_290210301 = "ターゲットが範囲内にいる場合、前方2マス以内の光霊と「鬼」を呑み込み、光霊に確定ダメージを与える。呑み込んだ「鬼」の数が多いほどダメージが大きくなる。その後、横に光霊を吐き出し、隊長に呪いをかけ、隊列の最後尾に下げる",
  str_skill_name_290042201 = "引き裂く邪龍",
  str_skill_desc_290042201 = "ハクドーマは前方の空間を切り裂き、攻撃範囲内のターゲットにダメージを与える。",
  str_skill_name_290042211 = "引き裂く邪龍",
  str_skill_desc_290042211 = "ハクドーマは前方の空間を切り裂き、攻撃範囲内のターゲットにダメージを与え、さらにフィールド上の一部のマスを粉砕する。",
  str_skill_name_290042202 = "ハクドーマの輪廻",
  str_skill_desc_290042202 = "ハクドーマが蓄積したエネルギーで翼をはばたかせ、目標をフィールドの端にノックバックし、フィールドにトゲマスを設置する",
  str_skill_name_290042204 = "満潮の使者",
  str_skill_desc_290042204 = "ハクドーマが前方に飛行し、すべてのマスを上方に4マス移動する。その後、固定エリアを爆撃する",
  str_skill_name_290042214 = "満潮の使者",
  str_skill_desc_290042214 = "ハクドーマが前方へ飛び、一定エリアに爆撃を行う。ターゲットに命中したかどうかに関わらず、ターゲットをフィールド端にノックバックする。ハクドーマの着地時、前方にトゲトゲを召喚する",
  str_skill_upgrade_desc_16014513 = "能動技強化：各ウェーブ開始時に忍力<color=#FFFF00>1</color>ポイントを獲得する",
  str_skill_upgrade_desc_16014516 = "装備技強化：その戦闘における隊長変更回数<color=#FFFF00>+1</color>",
  str_skill_name_2001451 = "影討ち",
  str_skill_name_2001452 = "影討ち",
  str_skill_name_2001453 = "影討ち",
  str_skill_desc_2001451 = "<color=#00F6FF>十字方向の8マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001452 = "<color=#00F6FF>菱形12マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える。さらにランダムで範囲内の進入可能なマス<color=#00F6FF>１</color>つに忍刀を1つ配置する",
  str_skill_desc_2001453 = "<color=#00F6FF>周囲1マス</color>と<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える。さらにランダムで範囲内の進入可能なマス<color=#00F6FF>2</color>つに忍刀を1つ配置する",
