  str_skill_desc_300145 = "<link=\"30028\"><#FFAE07><u>忍力</u></color></link>を<color=#00F6FF>2</color>点消費し、進入可能なマス<color=#00F6FF>1</color>つを選択して忍刀を1つ配置する。選択したマスに忍刀がある場合は、その位置に瞬間移動して忍刀を回収し、ただちに<link=\"30028\"><#FFAE07><u>忍力</u></color></link>を<color=#00F6FF>1</color>点獲得する",
  str_skill_desc_330145 = "<link=\"30028\"><#FFAE07><u>忍力</u></color></link>を<color=#00F6FF>2</color>点消費し、進入可能なマス<color=#00F6FF>1</color>つを選択して忍刀を1つ配置する。選択したマスに忍刀がある場合は、その位置に瞬間移動して忍刀を回収し、ただちに<link=\"30028\"><#FFAE07><u>忍力</u></color></link>を<color=#00F6FF>1</color>点獲得する",
  str_skill_desc_303145 = "<link=\"30029\"><#FFAE07><u>忍力</u></color></link>を<color=#00F6FF>2</color>点消費し、進入可能なマス<color=#00F6FF>1</color>つを選択して忍刀を1つ配置する。選択したマスに忍刀がある場合は、その位置に瞬間移動して忍刀を回収し、ただちに<link=\"30029\"><#FFAE07><u>忍力</u></color></link>を<color=#00F6FF>1</color>点獲得する",
  str_skill_desc_333145 = "<link=\"30029\"><#FFAE07><u>忍力</u></color></link>を<color=#00F6FF>2</color>点消費し、進入可能なマス<color=#00F6FF>1</color>つを選択して忍刀を1つ配置する。選択したマスに忍刀がある場合は、その位置に瞬間移動して忍刀を回収し、ただちに<link=\"30029\"><#FFAE07><u>忍力</u></color></link>を<color=#00F6FF>1</color>点獲得する",
  str_skill_passive_name_410145 = "忍び剣風",
