  str_skill_passive_name_436145 = "忍び剣風",
  str_skill_passive_desc_410145 = "能動技で移動後、忍刀をすべて回収する。忍刀を1つ回収するごとに、最も近くにいる敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>の防御無視ダメージを1回与える。距離が遠いほどダメージは低くなり、最低で元のダメージの20%",
  str_skill_passive_desc_413145 = "能動技で移動後、忍刀をすべて回収する。忍刀を1つ回収するごとに、最も近くにいる敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>の防御無視ダメージを1回与える。距離が遠いほどダメージは低くなり、最低で元のダメージの20%",
  str_skill_passive_desc_416145 = "能動技で移動後、忍刀をすべて回収する。忍刀を1つ回収するごとに、最も近くにいる敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>の防御無視ダメージを1回与える。距離が遠いほどダメージは低くなり、最低で元のダメージの20%。この戦闘における隊長変更回数<color=#00F6FF>+1</color>",
  str_skill_passive_desc_420145 = "能動技で移動後、忍刀をすべて回収する。忍刀を1つ回収するごとに、最も近くにいる敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>の防御無視ダメージを1回与える。距離が遠いほどダメージは低くなり、最低で元のダメージの20%。<color=#00F6FF>4</color>つの忍刀を回収した時、改めて<color=#00F6FF>1</color>つ忍刀を配置する",
  str_skill_passive_desc_423145 = "能動技で移動後、忍刀をすべて回収する。忍刀を1つ回収するごとに、最も近くにいる敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>の防御無視ダメージを1回与える。距離が遠いほどダメージは低くなり、最低で元のダメージの20%。<color=#00F6FF>4</color>つの忍刀を回収した時、改めて<color=#00F6FF>1</color>つ忍刀を配置する",
  str_skill_passive_desc_426145 = "能動技で移動後、忍刀をすべて回収する。忍刀を1つ回収するごとに、最も近くにいる敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>の防御無視ダメージを1回与える。距離が遠いほどダメージは低くなり、最低で元のダメージの20%。<color=#00F6FF>4</color>つの忍刀を回収した時、改めて<color=#00F6FF>1</color>つ忍刀を配置する。この戦闘における隊長変更回数<color=#00F6FF>+1</color>",
  str_skill_passive_desc_430145 = "能動技で移動後、忍刀をすべて回収する。忍刀を1つ回収するごとに、最も近くにいる敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>の防御無視ダメージを1回与える。距離が遠いほどダメージは低くなり、最低で元のダメージの20%。<color=#00F6FF>4</color>つの忍刀を回収した時、改めて<color=#00F6FF>1</color>つ忍刀を配置する。アメモリが何らかの方法により隊員から隊長になった時、<color=#00F6FF>1</color>ポイントの<link=\"30028\"><#FFAE07><u>忍力</u></color></link>を獲得する（各ターン<color=#00F6FF>3</color>回まで発動）。",
  str_skill_passive_desc_433145 = "能動技で移動後、忍刀をすべて回収する。忍刀を1つ回収するごとに、最も近くにいる敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>の防御無視ダメージを1回与える。距離が遠いほどダメージは低くなり、最低で元のダメージの20%。<color=#00F6FF>4</color>つの忍刀を回収した時、改めて<color=#00F6FF>1</color>つ忍刀を配置する。アメモリが何らかの方法により隊員から隊長になると、<color=#00F6FF>1</color>ポイントの<link=\"30029\"><#FFAE07><u>忍力</u></color></link>を獲得する（各ターン<color=#00F6FF>3</color>回まで発動）",
  str_skill_passive_desc_436145 = "能動技で移動後、忍刀をすべて回収する。忍刀を1つ回収するごとに、最も近くにいる敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>の防御無視ダメージを1回与える。距離が遠いほどダメージは低くなり、最低で元のダメージの20%。<color=#00F6FF>4</color>つの忍刀を回収した時、改めて<color=#00F6FF>1</color>つ忍刀を召喚する。アメモリが何らかの方法により隊員から隊長になった時、<color=#00F6FF>1</color>ポイントの<link=\"30029\"><#FFAE07><u>忍力</u></color></link>を獲得する（各ターン<color=#00F6FF>3</color>回まで発動）。この戦闘における隊長変更回数<color=#00F6FF>+1</color>",
  str_skill_upgrade_desc_16014613 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16014616 = "装備技強化：その戦闘における隊長変更回数<color=#FFFF00>+1</color>",
  str_skill_name_20014601 = "石錘拳",
