  str_skill_desc_20014601 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_20014602 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_20014603 = "<color=#00F6FF>縦、横、斜めの24マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001461 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える。<color=#00F6FF>隣接する4マス</color>のダメージは2倍",
  str_skill_desc_2001462 = "<color=#00F6FF>縦、横、斜めの16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。<color=#00F6FF>隣接する4マス</color>のダメージは2倍",
  str_skill_desc_2001463 = "<color=#00F6FF>縦、横、斜めの24マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。<color=#00F6FF>隣接する4マス</color>のダメージは2倍",
  str_skill_name_300146 = "天人合一",
