  str_skill_name_333146 = "天人合一",
  str_skill_desc_300146 = "隊長と隊列を交換し、このターンのヨウの連鎖技の<color=#00F6FF>隣接する4マス</color>に対するダメージが倍増する。ターン終了時に最後尾の光霊と位置を入れ替わる",
  str_skill_desc_303146 = "隊長と隊列を交換し、このターンのヨウの連鎖技の<color=#00F6FF>隣接する4マス</color>に対するダメージが倍増する。ターン終了時に最後尾の光霊と位置を入れ替わる",
  str_skill_desc_320146 = "現在の隊長と位置を交換し、<link=\"30026\"><#FFAE07><u>侠心の印</u></color></link>を1スタック獲得、このターンのヨウの連鎖技の<color=#00F6FF>隣接する4マス</color>に対するダメージが倍増する。ターン終了時に最後尾の光霊と位置を入れ替わる",
  str_skill_desc_323146 = "現在の隊長と位置を交換し、<link=\"30026\"><#FFAE07><u>侠心の印</u></color></link>を1スタック獲得、このターンのヨウの連鎖技の<color=#00F6FF>隣接する4マス</color>に対するダメージが倍増する。ターン終了時に最後尾の光霊と位置を入れ替わる",
  str_skill_desc_330146 = "現在の隊長と位置を交換し、<link=\"30026\"><#FFAE07><u>侠心の印</u></color></link>を1スタック獲得、このターンのヨウの連鎖技の<color=#00F6FF>隣接する4マス</color>に対するダメージが倍増する。ターン終了時に最後尾の光霊と位置を入れ替わる",
  str_skill_desc_333146 = "現在の隊長と位置を交換し、<link=\"30026\"><#FFAE07><u>侠心の印</u></color></link>を1スタック獲得、このターンのヨウの連鎖技の<color=#00F6FF>隣接する4マス</color>に対するダメージが倍増する。ターン終了時に最後尾の光霊と位置を入れ替わる",
  str_skill_passive_name_410146 = "経絡開合",
  str_skill_passive_name_416146 = "経絡開合",
  str_skill_passive_name_430146 = "経絡開合",
  str_skill_passive_name_436146 = "経絡開合",
  str_skill_passive_desc_410146 = "<link=\"30026\"><#FFAE07><u>侠心の印</u></color></link>を獲得できる。味方ターン時にヨウが隊長である場合、印1スタックにつき、そのターンにおけるヨウの基礎攻撃力+<color=#00F6FF>{1}</color>され、ターン終了後印がクリアされる",
  str_skill_passive_desc_416146 = "<link=\"30026\"><#FFAE07><u>侠心の印</u></color></link>を獲得できる。味方ターン時にヨウが隊長である場合、印1スタックにつき、そのターンのヨウの基礎攻撃力+<color=#00F6FF>{1}</color>され、ターン終了後印がクリアされる。この戦闘における隊長変更回数<color=#00F6FF>+1</color>",
  str_skill_passive_desc_430146 = "<link=\"30027\"><#FFAE07><u>侠心の印</u></color></link>を獲得できる。味方ターン時にヨウが隊長である場合、印1スタックにつき、そのターンのヨウの基礎攻撃力+<color=#00F6FF>{1}</color>され、ターン終了後印がクリアされる。ヨウが何らかの方法で隊員から隊長になるたびに、<link=\"30027\"><#FFAE07><u>侠心の印</u></color></link>を<color=#00F6FF>1</color>スタック獲得する",
  str_skill_passive_desc_436146 = "<link=\"30027\"><#FFAE07><u>侠心の印</u></color></link>を獲得できる。味方ターン時にヨウが隊長である場合、印1スタックにつき、そのターンのヨウの基礎攻撃力+<color=#00F6FF>{1}</color>し、ターン終了後印がクリアされる。ヨウが何らかの方法で隊員から隊長になるたびに、<link=\"30027\"><#FFAE07><u>侠心の印</u></color></link>を<color=#00F6FF>1</color>スタック獲得する。この戦闘における隊長変更回数<color=#00F6FF>+1</color>",
  str_skill_upgrade_desc_15014712 = "能動技強化：隊長になるたびに、能動技のCDターン<color=#FFFF00>-1</color>。毎ターン最多で<color=#00F6FF>3</color>回まで発動する",
  str_skill_upgrade_desc_15014715 = "装備技強化：その戦闘における隊長変更回数<color=#FFFF00>+1</color>",
  str_skill_desc_2001471 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>150%</color>のダメージを2回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2001472 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>160%</color>のダメージを3回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2001473 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>160%</color>のダメージを4回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_300147 = "<color=#00F6FF>周囲3マス</color>以内の1マスを選択し、<color=#00F6FF>{1}%</color>のダメージを<color=#00F6FF>8</color>回与える",
  str_skill_desc_302147 = "<color=#00F6FF>周囲3マス</color>以内の1マスを選択し、<color=#00F6FF>{1}%</color>のダメージを<color=#00F6FF>8</color>回与える。隊長になるたびに、能動技のCDターン<color=#FFFF00>-1</color>（毎ターン<color=#00F6FF>3</color>回まで発動）",
  str_skill_desc_320147 = "<color=#00F6FF>周囲3マス</color>以内の1マスを選択し、<color=#00F6FF>{1}%</color>のダメージを<color=#00F6FF>8</color>回与える。その後、選択したマスおよびその<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>188%</color>のダメージを1回与える",
  str_skill_desc_322147 = "<color=#00F6FF>周囲3マス</color>以内の1マスを選択し、<color=#00F6FF>{1}%</color>のダメージを<color=#00F6FF>8</color>回与える。その後、選択したマスおよびその<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>188%</color>のダメージを1回与える。隊長になるたびに、能動技のCDターン<color=#FFFF00>-1</color>（毎ターン<color=#00F6FF>3</color>回まで発動）",
  str_skill_passive_desc_410147 = "毎ターン開始時、モモ＆アンズは強制的に隊長になり、他の隊員は1人分ずつ後退する。モモ＆アンズが隊長になるたびに、<link=\"30030\"><#FFAE07><u>「カニ家特製メニュー」</u></color></link>を獲得し、さらに<color=#00F6FF>{1}</color>の確率で<color=#00F6FF>追加で1獲得する</color>",
  str_skill_passive_desc_415147 = "毎ターン開始時、モモ＆アンズは強制的に隊長になり、他の隊員が1人分ずつ後退する。モモ＆アンズが隊長になるたびに、<link=\"30030\"><#FFAE07><u>「カニ家特製メニュー」</u></color></link>を1つ獲得し、さらに<color=#00F6FF>{1}</color>の確率で<color=#00F6FF>追加で1つ獲得する</color>。この戦闘における隊長変更回数<color=#00F6FF>+1</color>",
  str_skill_passive_desc_430147 = "毎ターン開始時、モモ＆アンズは強制的に隊長になり、他の隊員が1人分ずつ後退する。モモ＆アンズが隊長になるたびに、<link=\"30030\"><#FFAE07><u>「カニ家特製メニュー」</u></color></link>を1つ獲得し、<color=#00F6FF>毎回{1}</color>の確率で<color=#00F6FF>追加で1つ獲得する</color>",
  str_skill_passive_desc_435147 = "毎ターン開始時、モモ＆アンズは強制的に隊長になり、他の隊員が1人分ずつ後退する。モモ＆アンズが隊長になるたびに、<link=\"30030\"><#FFAE07><u>「カニ家特製メニュー」</u></color></link>を1つ獲得し、<color=#00F6FF>毎回{1}</color>の確率で<color=#00F6FF>追加で1つ獲得する</color>。この戦闘における隊長変更回数<color=#00F6FF>+1</color>",
