  str_skill_desc_280060103 = "砂煙を巻き上げて周囲1マスにいる敵にダメージを与えて前進し、すべての敵を後方に移動させる。",
  str_skill_desc_280060104 = "エネルギーをすべて消費し、遠くにいる敵を爆撃する。消費エネルギーが多いほど、ダメージと爆発範囲がアップ。",
