  str_skill_desc_336148 = "任意の進入可能なマスを1つ選び、<link=\"30035\"><#FFAE07><u>ミラージュ</u></color></link>を投射する。<color=#00F6FF>毎ターン</color>、ミラージュを操って<link=\"30037\"><#FFAE07><u>ミラージュの衝撃</u></color></link>、または<link=\"30038\"><#FFAE07><u>ミラージュの変転</u></color></link>を発動できる。ミラージュのすでにある位置を選択した場合、即時ダメージ<color=#00F6FF>2.5倍</color>の<color=#00F6FF>ミラージュの衝撃</color>を1回発動する",
