  str_skill_desc_2001511 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。1回ごとに最終ダメージ-<color=#00F6FF>15%</color>",
  str_skill_desc_2001512 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。1回ごとに最終ダメージ-<color=#00F6FF>10%</color>",
  str_skill_desc_2001513 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。1回ごとに最終ダメージ-<color=#00F6FF>5%</color>",
  str_skill_desc_23015101 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25</color>以下の場合、追加で1|2回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>15%</color>",
  str_skill_desc_23015102 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25</color>以下の場合、追加で1|2回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>10%</color>",
  str_skill_desc_23015103 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25</color>以下の場合、追加で1|2回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>5%</color>",
  str_skill_desc_23015161 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25|0</color>以下の場合、追加で1|2|3回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>15%</color>",
  str_skill_desc_23015162 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25|0</color>以下の場合、追加で1|2|3回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>10%</color>",
  str_skill_desc_23015163 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25|0</color>以下の場合、追加で1|2|3回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>5%</color>",
  str_skill_desc_2301511 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25</color>以下の場合、追加で1|2回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>15%</color>",
  str_skill_desc_2301512 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25</color>以下の場合、追加で1|2回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>10%</color>",
  str_skill_desc_2301513 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25</color>以下の場合、追加で1|2回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>5%</color>",
  str_skill_desc_2301514 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25</color>以下の場合、追加で1|2回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>15%</color>",
  str_skill_desc_2301515 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25</color>以下の場合、追加で1|2回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>10%</color>",
  str_skill_desc_2301516 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25</color>以下の場合、追加で1|2回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>5%</color>",
  str_skill_desc_2301517 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25|0</color>以下の場合、追加で1|2|3回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>15%</color>",
  str_skill_desc_2301518 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25|0</color>以下の場合、追加で1|2|3回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>10%</color>",
  str_skill_desc_2301519 = "HP比率の最も低い敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを2回与える。理性値が<color=#00F6FF>60|25|0</color>以下の場合、追加で1|2|3回ダメージを与える。1回ごとに最終ダメージ-<color=#00F6FF>5%</color>",
  str_skill_desc_300151 = "戦闘時、ギルスが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を<color=#00F6FF>15</color>点消費して1マス選択し、隣接する<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。自身のいるマスを選んだ場合、ダメージが2倍になる",
  str_skill_desc_3001510 = "戦闘時、ギルスが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を<color=#00F6FF>15</color>点消費して1マス選択し、隣接する<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。自身のいるマスを選んだ場合、ダメージが2倍になる。能動技でターゲットを倒すと再使用でき、必要な理性値と最終ダメージがいずれも2倍になる",
  str_skill_desc_3001511 = "戦闘時、ギルスが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を<color=#00F6FF>30</color>点消費して1マス選択し、隣接する<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。自身のいるマスを選んだ場合、ダメージが2倍になる。能動技でターゲットを倒すと再使用でき、必要な理性値と最終ダメージがいずれも2倍になる",
  str_skill_desc_3001512 = "戦闘時、ギルスが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を<color=#00F6FF>60</color>点消費して1マス選択し、隣接する<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。自身のいるマスを選んだ場合、ダメージが2倍になる。能動技でターゲットを倒すと再使用でき、必要な理性値と最終ダメージがいずれも2倍になる",
  str_skill_desc_3001513 = "戦闘時、ギルスが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を<color=#00F6FF>120</color>点消費して1マス選択し、隣接する<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。自身のいるマスを選んだ場合、ダメージが2倍になる。能動技でターゲットを倒すと再使用でき、必要な理性値と最終ダメージがいずれも2倍になる",
  str_skill_desc_3001514 = "戦闘時、ギルスが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を<color=#00F6FF>240</color>点消費して1マス選択し、隣接する<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。自身のいるマスを選んだ場合、ダメージが2倍になる。能動技でターゲットを倒すと再使用でき、必要な理性値と最終ダメージがいずれも2倍になる",
  str_skill_passive_desc_410151 = "現在のターンで<color=#00F6FF>敵を倒していると発動</color>。ギルスがダメージを与える時、現在の理性値に応じてダメージが増加する。理性値が低いほど増加量も大きくなり、最大で+<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_413151 = "現在のターンで<color=#00F6FF>敵を倒していると発動</color>。ギルスがダメージを与える時、現在の理性値に応じてダメージが増加する。理性値が低いほど増加量も大きくなり、最大で+<color=#00F6FF>{1}</color>。<color=#00F6FF>「幻覚」</color>を倒すと、強化量が追加で+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_416151 = "現在のターンで<color=#00F6FF>敵を倒していると発動</color>。ギルスがダメージを与える時、現在の理性値に応じてダメージが増加する。理性値が低いほど増加量も大きくなり、最大で+<color=#00F6FF>{1}</color>。<color=#00F6FF>「幻覚」</color>を倒すと、強化量が追加で+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_430151 = "現在のターンで<color=#00F6FF>敵を倒していると発動</color>。ギルスがダメージを与える時、現在の理性値に応じてダメージが増加する。理性値が低いほど増加量も大きくなり、最大で+<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_433151 = "現在のターンで<color=#00F6FF>敵を倒していると発動</color>。ギルスがダメージを与える時、現在の理性値に応じてダメージが増加する。理性値が低いほど増加量も大きくなり、最大で+<color=#00F6FF>{1}</color>。<color=#00F6FF>「幻覚」</color>を倒すと、強化量が追加で+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_436151 = "現在のターンで<color=#00F6FF>敵を倒していると発動</color>。ギルスがダメージを与える時、現在の理性値に応じてダメージが増加する。理性値が低いほど増加量も大きくなり、最大で+<color=#00F6FF>{1}</color>。<color=#00F6FF>「幻覚」</color>を倒すと、強化量が追加で+<color=#00F6FF>10%</color>",
  str_skill_upgrade_desc_16015113 = "装備技強化：<color=#00F6FF>「幻覚」</color>を倒すと、強化効果が追加で+<color=#00F6FF>10%</color>",
  str_skill_upgrade_desc_16015116 = "連鎖技強化：理性値が0のとき、追加で<color=#00F6FF>3</color>回のダメージを与える（覚醒3で有効）",
