  str_skill_desc_300152 = "戦闘時、メイが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。現在のHPの<color=#00F6FF>20%</color>を失い、理性値の<color=#00F6FF>25%</color>を回復する",
  str_skill_desc_302152 = "戦闘時、メイが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。現在のHPの<color=#00F6FF>15%</color>を失い、失った理性値の<color=#00F6FF>25%</color>を回復する",
  str_skill_desc_305152 = "戦闘時に<link=\"30040\"><#FFAE07><u>【理性システム】</u></color></link>が発動、および変化する。理性システムによる弱体化の影響を受けにくくなり、弱体化効果が低下する。現在のHPの<color=#00F6FF>15%</color>を失い、失った理性値の<color=#00F6FF>25%</color>を回復する",
  str_skill_desc_2001521 = "<color=#00F6FF>X形の8マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001522 = "<color=#00F6FF>X形の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001523 = "<color=#00F6FF>X形の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_passive_desc_410152 = "理性値が1下がるごとに、メイの攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復する",
  str_skill_passive_desc_415152 = "理性値が1下がるごとに、メイの攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復する",
  str_skill_passive_desc_420152 = "理性値が1下がるごとに、メイの攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復する。さらにメイの防御力が理性値の低下に応じて上昇する。最大で+<color=#00F6FF>100%</color>",
  str_skill_passive_desc_425152 = "理性値が1下がるごとに、メイの攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復する。さらにメイの防御力が理性値の低下に応じて上昇する。最大で+<color=#00F6FF>100%</color>",
  str_skill_passive_desc_430152 = "理性値が1下がるごとに、メイの攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復する。理性値が低いほど回復量が大きくなり、最大で<color=#00F6FF>100%</color>回復する。さらにメイの防御力が理性値の低下に応じて上昇する。最大で+<color=#00F6FF>100%</color>",
  str_skill_passive_desc_435152 = "理性値が1下がるごとに、メイの攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復する。理性値が低いほど回復量が大きくなり、最大で<color=#00F6FF>100%</color>回復する。さらにメイの防御力が理性値の低下に応じて上昇する。最大で+<color=#00F6FF>100%</color>",
  str_skill_upgrade_desc_15015212 = "能動技強化：現在のHPの<color=#00F6FF>15%</color>を失い、失った理性値の<color=#00F6FF>25%</color>を回復する",
  str_skill_upgrade_desc_15015215 = "理性システムを変更：理性システムによる弱体化の影響を受けにくくなり、弱体化効果も低下する",
