  str_skill_name_3031501 = "血海領域",
  str_skill_passive_name_410150 = "魔偶の呪詛",
  str_skill_upgrade_desc_16015013 = "能動技強化：能動技が1回ダメージを与えるごとに、レノーアの最大HP+<color=#FFFF00>3%</color>",
  str_skill_upgrade_desc_16015016 = "連鎖技強化：理性値が低いほどダメージが大きくなり、最大で+<color=#FFFF00>100%</color>（覚醒3で有効）",
  str_skill_desc_20015011 = "<color=#00F6FF>横方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_20015012 = "<color=#00F6FF>横方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_20015013 = "<color=#00F6FF>横方向5列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_22015011 = "<color=#00F6FF>横方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_22015012 = "<color=#00F6FF>横方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_22015013 = "<color=#00F6FF>横方向5列</color>に<color=#00F6FF>{1}%</color>のダメージを与える。理性値が<color=#00F6FF>75</color>以下の場合、発動条件が<color=#00F6FF>15</color>に減少する。<color=#00F6FF>錯乱状態</color>のとき、<color=#00F6FF>5</color>に減少する",
  str_skill_desc_23015011 = "<color=#00F6FF>横方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与える。理性値が低いほどダメージが大きくなり、最大で+<color=#00F6FF>80%</color>",
  str_skill_desc_23015012 = "<color=#00F6FF>横方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える。理性値が低いほどダメージが大きくなり、最大で+<color=#00F6FF>80%</color>",
  str_skill_desc_23015013 = "<color=#00F6FF>横方向5列</color>に<color=#00F6FF>{1}%</color>のダメージを与える。理性値が<color=#00F6FF>75</color>以下の場合、発動条件が<color=#00F6FF>15</color>に減少する。<color=#00F6FF>錯乱状態</color>のとき、<color=#00F6FF>5</color>に減少する。理性値が低いほどダメージが大きくなり、最大で+<color=#00F6FF>80%</color>",
  str_skill_desc_23615011 = "<color=#00F6FF>横方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与える。理性値が低いほどダメージが大きくなり、最大で+<color=#00F6FF>100%</color>",
  str_skill_desc_23615012 = "<color=#00F6FF>横方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える。理性値が低いほどダメージが大きくなり、最大で+<color=#00F6FF>100%</color>",
  str_skill_desc_23615013 = "<color=#00F6FF>横方向5列</color>に<color=#00F6FF>{1}%</color>のダメージを与える。理性値が<color=#00F6FF>75</color>以下の場合、発動条件が<color=#00F6FF>15</color>に減少する。<color=#00F6FF>錯乱状態</color>のとき、<color=#00F6FF>5</color>に減少する。理性値が低いほどダメージが大きくなり、最大で+<color=#00F6FF>100%</color>",
  str_skill_desc_3001501 = "戦闘時、レノーアが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。1マス選択し、その<color=#00F6FF>周囲2マス</color>の範囲内からさらに1マスを選択して四角形の範囲を定め、そのエリア内のマスに対して<color=#00F6FF>333%</color>のダメージを与える。長方形内のマス1つにつき、理性値-<color=#00F6FF>3</color>。同一の敵にダメージを複数回与える場合、2回目以降は<color=#00F6FF>33%</color>の効果になる",
  str_skill_desc_3031501 = "戦闘時、レノーアが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。1マス選択し、その<color=#00F6FF>周囲2マス</color>の範囲内からさらに1マスを選択して四角形の範囲を定め、そのエリア内のマスに対して<color=#00F6FF>333%</color>のダメージを与える。長方形内のマス1つにつき、理性値-<color=#00F6FF>3</color>。同一の敵にダメージを複数回与える場合、2回目以降は<color=#00F6FF>33%</color>の効果になる。能動技が1回ダメージを与えるごとに、レノーアの最大HP+<color=#00F6FF>3%</color>",
  str_skill_passive_desc_410150 = "毎ターン開始時に<color=#00F6FF>冷静な状態</color>でない場合、すべての敵にチームの最大HPの<color=#00F6FF>{1}</color>相当のダメージを与える。理性値が低いほどダメージが大きくなり、最大でチームの最大HPの<color=#00F6FF>{2}</color>相当まで増加する。",
  str_skill_name_290220101 = "夜の制圧",
  str_skill_desc_290220101 = "範囲内にいる敵に強力な攻撃を行う",
  str_skill_name_290220102 = "夜の憎悪",
  str_skill_desc_290220102 = "周囲2マス以内にいるターゲットに大ダメージを与え、損傷値の50%をHPに変換する。",
  str_skill_name_290220103 = "夜の反撃",
  str_skill_desc_290220103 = "光霊が能動技を発動するごとに周囲2マス以内にいるターゲットに大ダメージを与え、損傷値の50%をHPに変換する。",
  str_skill_name_290220201 = "暗徨の爪",
  str_skill_desc_290220201 = "鋭い爪で頭部近辺の5マス以内にいる敵にダメージを与える",
  str_skill_name_290220202 = "暗徨の突進",
  str_skill_desc_290220202 = "前方の敵に飛び掛かり、着地点の装置を破壊する。さらに周囲1マス以内にいる敵にダメージを与える。",
  str_skill_name_290220203 = "暗徨の旋回",
  str_skill_desc_290220203 = "敵が自身の前方にいない時、直ちに旋回して自身の向きを敵の方向に変える。方向変化後の位置に障害物がある場合、暗徨の空撃を1回直接発動する。",
  str_skill_name_290220204 = "暗徨の空撃",
  str_skill_desc_290220204 = "高く飛び上がり、敵の周辺に襲いかかる。着地時に周囲1マス以内の敵に大ダメージを与えた後、全ての行動を終了する。",
  str_skill_name_29026011 = "遊霊・掃滅",
  str_skill_desc_29026011 = "光霊の方向に移動し、鎌で自身の周囲にいるターゲットにダメージを与える",
  str_skill_name_29026012 = "遊霊・旋鎌",
  str_skill_desc_29026012 = "その場で戦場の端に鎌を呼び出して引き寄せ、縦、横、斜めの範囲内にいるターゲットにダメージを与える",
  str_skill_name_29026021 = "遊霊・刃雨",
  str_skill_desc_29026021 = "光霊の方向に移動した後、光霊が攻撃範囲内にいる場合、前方2マス以内にいるターゲットにダメージを与える。\n攻撃範囲内に光霊がいない場合、潜伏状態に移行し、通常攻撃を回避する（状態異常を受けると潜伏状態は解除される）",
  str_skill_name_29026023 = "遊霊・血号",
  str_skill_desc_29026023 = "その場で全範囲のターゲットにダメージを与える",
  str_skill_name_290270101 = "ノラ・召喚",
  str_skill_desc_290270101 = "ノラが戦場のランダムな位置に暗鬼2体を召喚し、戦闘に参加させる",
  str_skill_name_290270102 = "ノラ・撃退",
  str_skill_desc_290270102 = "ノラが戦場の光霊と他のすべての暗鬼をノックバックし、光霊にダメージを与える",
  str_skill_name_290270103 = "ノラ・凋残",
  str_skill_desc_290270103 = "前のターンに光霊がいた場所およびその周囲1マスに衝撃波を放つ。衝撃波の範囲内にいる光霊に大ダメージを与える",
  str_skill_name_290270111 = "ノラ・暗進",
  str_skill_desc_290270111 = "ノラが戦場に暗域を生成し、光霊の行動範囲を制限する",
  str_skill_upgrade_desc_16015413 = "連鎖技強化：連鎖技最終ダメージ回数<color=#FFFF00>+1</color>",
  str_skill_upgrade_desc_16015416 = "連鎖技強化：連鎖技のダメージ係数+<color=#FFFF00>20%</color>",
  str_skill_name_200154 = "無窮の矢雨",
  str_skill_name_203154 = "無窮の矢雨",
  str_skill_name_206154 = "無窮の矢雨",
  str_skill_name_300154 = "時空の鎖",
  str_skill_name_3001541 = "時空の鎖",
  str_skill_name_320154 = "時空の鎖",
  str_skill_name_330154 = "時空の鎖",
  str_skill_desc_300154 = "任意の敵1体を選択して<color=#00F6FF>ロックオン</color>する。戦場で同時にロックオンできるターゲットは<color=#00F6FF>1</color>体まで。バイス・空の瞳の連鎖技は<color=#00F6FF>そのターゲットのみを攻撃</color>する。選択したターゲットが既にロックオンされている場合、<color=#00F6FF>100%</color>のダメージを1回与える",
  str_skill_desc_330154 = "任意の敵1体を選択して<color=#00F6FF>ロックオン</color>する。戦場に存在できるロックオン状態のターゲットは<color=#00F6FF>1</color>体まで。バイス・空の瞳の連鎖技は常に<color=#00F6FF>そのターゲットを攻撃</color>する。選択したターゲットが既にロックオンされている場合、相手に<color=#00F6FF>100%</color>のダメージを1回与える。ターゲットの<link=\"30042\"><#FFAE07><u>無限時の印</u></color></link>1スタックにつき、追加でダメージ+<color=#00F6FF>5%</color>",
  str_skill_desc_200154 = "連鎖<color=#00F6FF>3</color>マスごとに、最も近くにいるターゲットに<color=#00F6FF>80%</color>のダメージを1回与える。このダメージは連鎖マス数による強化を受けない",
  str_skill_desc_203154 = "連鎖<color=#00F6FF>3</color>マスごとに、最も近くにいるターゲットに<color=#00F6FF>80%</color>のダメージを1回与える。このダメージは連鎖マス数による強化を受けない。連鎖技最終ダメージ回数<color=#00F6FF>+1</color>",
  str_skill_desc_206154 = "連鎖<color=#00F6FF>3</color>マスごとに、最も近くにいるターゲットに<color=#00F6FF>100%</color>のダメージを1回与える。このダメージは連鎖マス数による強化を受けない。連鎖技最終ダメージ回数<color=#00F6FF>+1</color>",
  str_skill_passive_name_410154 = "無限時の印",
  str_skill_passive_name_420154 = "無限時の印",
  str_skill_passive_desc_410154 = "ロックオンしたターゲットに<link=\"30041\"><#FFAE07><u>無限時の印</u></color></link>を付与する。<link=\"30041\"><#FFAE07><u>無限時の印</u></color></link>1スタックにつき、バイス・空の瞳によるターゲットの被ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420154 = "ロックオンしたターゲットに<link=\"30042\"><#FFAE07><u>無限時の印</u></color></link>を付与する。<link=\"30042\"><#FFAE07><u>無限時の印</u></color></link>1スタックにつき、バイス・空の瞳によるターゲットの被ダメージ+<color=#00F6FF>{1}</color>。ロックオンされたターゲットが光霊に<color=#00F6FF>3%</color>のダメージを与えるごとに、バイス・空の瞳が相手に無限時の印を1スタック付与する",
  str_skill_name_300155 = "双剣合身",
  str_skill_name_310155 = "双剣合身",
  str_skill_name_320155 = "双剣合身",
