  str_skill_passive_name_430155 = "孤勇一息",
  str_skill_passive_name_436155 = "孤勇一息",
  str_skill_desc_300155 = "<link=\"30045\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>10</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも10減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_303155 = "<link=\"30046\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>10</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも10減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_306155 = "<link=\"30047\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>10</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも10減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_310155 = "<link=\"30045\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>10</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも10減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_313155 = "<link=\"30046\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>10</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも10減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_316155 = "<link=\"30047\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>10</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも10減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_320155 = "<link=\"30045\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>10</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも10減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_323155 = "<link=\"30046\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>10</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも10減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_326155 = "<link=\"30047\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>10</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも10減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_2001551 = "<color=#00F6FF>通常状態</color>：孤勇値を<color=#00F6FF>3</color>獲得し、<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える\n<color=#00F6FF>孤勇状態</color>：<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>170%</color>のダメージを与える",
  str_skill_desc_2001552 = "<color=#00F6FF>通常状態</color>：孤勇値を<color=#00F6FF>4</color>獲得し、<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える\n<color=#00F6FF>孤勇状態</color>：<color=#00F6FF>縦、横、斜め16マス</color>に<color=#00F6FF>190%</color>のダメージを与える",
  str_skill_desc_2001553 = "<color=#00F6FF>通常状態</color>：孤勇値を<color=#00F6FF>5</color>獲得し、<color=#00F6FF>縦、横、斜め16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える\n<color=#00F6FF>孤勇状態</color>：<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>210%</color>のダメージを与える",
  str_skill_desc_20015510 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_20015520 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_20015530 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_passive_desc_410155 = "<color=#00F6FF>孤勇状態</color>の通常攻撃で自身の<color=#00F6FF>周囲1マス</color>にダメージを与える。ターゲット以外のマスに対しては通常ダメージの<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_416155 = "<color=#00F6FF>孤勇状態</color>の通常攻撃で自身の<color=#00F6FF>周囲1マス</color>にダメージを与える。ターゲット以外のマスに対しては通常ダメージの<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420155 = "<color=#00F6FF>孤勇状態</color>の時、通常攻撃で自身の<color=#00F6FF>周囲1マス</color>にダメージを与える。ターゲット以外のマスに対しては通常ダメージの<color=#00F6FF>{1}</color>。<color=#00F6FF>孤勇状態</color>の時は毎ターン、敵1体ごとの初回の通常攻撃後、追加で1回の通常攻撃を行い、<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_426155 = "<color=#00F6FF>孤勇状態</color>の時、通常攻撃で自身の<color=#00F6FF>周囲1マス</color>にダメージを与える。ターゲット以外のマスに対しては通常ダメージの<color=#00F6FF>{1}</color>。<color=#00F6FF>孤勇状態</color>の時は毎ターン、敵1体ごとの初回の通常攻撃後、追加で1回の通常攻撃を行い、<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_430155 = "通常攻撃で<color=#00F6FF>斜め方向の敵を攻撃できる</color>。<color=#00F6FF>孤勇状態</color>の時、通常攻撃で自身の<color=#00F6FF>周囲1マス</color>にダメージを与える。ターゲット以外のマスに対しては通常ダメージの<color=#00F6FF>{1}</color>。<color=#00F6FF>孤勇状態</color>の時は毎ターン、敵1体ごとの初回の通常攻撃後、追加で1回の通常攻撃を行い、<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_436155 = "通常攻撃で<color=#00F6FF>斜め方向の敵を攻撃できる</color>。<color=#00F6FF>孤勇状態</color>の時、通常攻撃で自身の<color=#00F6FF>周囲1マス</color>にダメージを与える。ターゲット以外のマスに対しては通常ダメージの<color=#00F6FF>{1}</color>。<color=#00F6FF>孤勇状態</color>の時は毎ターン、敵1体ごとの初回の通常攻撃後、追加で1回の通常攻撃を行い、<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_upgrade_desc_16015513 = "能動技強化：戦闘開始時に孤勇値<color=#00F6FF>20</color>を獲得する",
  str_skill_upgrade_desc_16015516 = "能動技強化：能動技使用後、ただちに孤勇値<color=#00F6FF>5</color>を獲得する",
  str_skill_passive_desc_440153 = "通常攻撃で<color=#00F6FF>斜め方向の敵を攻撃できる</color>。<color=#00F6FF>孤勇状態</color>の時、通常攻撃で自身の<color=#00F6FF>周囲1マス</color>にダメージを与える。ターゲット以外のマスに対しては通常ダメージの<color=#00F6FF>65%</color>。<color=#00F6FF>孤勇状態</color>の時は毎ターン、敵1体ごとの初回の通常攻撃後、追加で1回の通常攻撃を行い、<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>65%</color>のダメージを与える",
  str_skill_desc_350155 = "<link=\"30045\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>8</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも8減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_353155 = "<link=\"30046\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>8</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも8減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_356155 = "<link=\"30047\"><#FFAE07><u>孤勇値</u></color></link>を20消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>8</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも8減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_360155 = "<link=\"30045\"><#FFAE07><u>孤勇値</u></color></link>を16消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>8</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも8減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_363155 = "<link=\"30046\"><#FFAE07><u>孤勇値</u></color></link>を16消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>8</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも8減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_desc_366155 = "<link=\"30047\"><#FFAE07><u>孤勇値</u></color></link>を16消費し、このターン<color=#00F6FF>孤勇状態</color>となり、連鎖技の範囲とダメージが上昇する。ターン終了時の孤勇値が<color=#00F6FF>8</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも8減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_upgrade_refine_desc_16015511 = "装備技強化：孤勇状態の時、通常攻撃でターゲット以外のマスに通常ダメージの<color=#00F6FF>65%</color>を与える",
  str_skill_upgrade_refine_desc_16015512 = "能動技強化：ターン終了時の孤勇値が<color=#00F6FF>8</color>以上の場合、残りの孤勇値が<color=#00F6FF>半分に減少</color>（最低でも8減少）し、次のターンも<color=#00F6FF>孤勇状態が継続される</color>",
  str_skill_upgrade_refine_desc_16015513 = "能動技強化：孤勇値<color=#00F6FF>16</color>を消費する",
  str_skill_upgrade_desc_16015313 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる\n装備技強化：戦闘開始時、ただちに終結値を<color=#FFFF00>2</color>獲得する（覚醒1で有効）",
  str_skill_upgrade_desc_16015316 = "能動技強化：技のCDターン<color=#FFFF00>-1</color>。\n装備技強化：濃色マスを通過するごとに、連鎖技ダメージ係数+<color=#FFFF00>2%</color>（覚醒2で有効）",
  str_skill_name_2001531 = "啓明の轟撃",
  str_skill_name_2001532 = "啓明の轟撃",
  str_skill_name_2001533 = "啓明の轟撃",
  str_skill_name_300153 = "終結の明光",
  str_skill_name_306153 = "終結の明光",
  str_skill_name_320153 = "終結の明光",
  str_skill_name_326153 = "終結の明光",
  str_skill_name_330153 = "終結の明光",
  str_skill_name_336153 = "終結の明光",
  str_skill_desc_300153 = "<color=#00F6FF>4</color>マス選択し、<color=#00F6FF>2</color>ターン存続する空爆ビーコンを設置して<color=#00F6FF>終結状態</color>を発動する。2ターン持続。終結状態中は自身の通常攻撃で<color=#00F6FF>斜め方向を攻撃可能</color>。連鎖技が追加で空爆ビーコンのあるマスおよびその隣接する4マスに連鎖技の半分のダメージを与える。同一のマスに複数回のダメージを与える場合、1回ごとに最終ダメージ-<color=#00F6FF>20%</color>",
  str_skill_desc_306153 = "<color=#00F6FF>4</color>マス選択し、<color=#00F6FF>2</color>ターン存続する空爆ビーコンを設置して<color=#00F6FF>終結状態</color>を発動する。2ターン持続。終結状態中は自身の通常攻撃で<color=#00F6FF>斜め方向を攻撃可能</color>。連鎖技が追加で空爆ビーコンのあるマスおよびその隣接する4マスに連鎖技の半分のダメージを与える。同一のマスに複数回のダメージを与える場合、1回ごとに最終ダメージ-<color=#00F6FF>20%</color>",
  str_skill_desc_320153 = "<color=#00F6FF>4</color>マス選択し、<color=#00F6FF>2</color>ターン存続する空爆ビーコンを設置して<color=#00F6FF>終結状態</color>を発動する。2ターン持続。終結状態中は自身の通常攻撃で<color=#00F6FF>斜め方向を攻撃可能</color>。連鎖技が追加で空爆ビーコンのあるマスおよびその隣接する4マスに連鎖技の半分のダメージを与える。同一のマスに複数回のダメージを与える場合、1回ごとに最終ダメージ-<color=#00F6FF>20%</color>。終結状態中は<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を<color=#00F6FF>5</color>獲得できる（上限を超えて獲得可能）",
  str_skill_desc_326153 = "<color=#00F6FF>4</color>マス選択し、<color=#00F6FF>2</color>ターン存続する空爆ビーコンを設置して<color=#00F6FF>終結状態</color>を発動する。2ターン持続。終結状態中は自身の通常攻撃で<color=#00F6FF>斜め方向を攻撃可能</color>。連鎖技が追加で空爆ビーコンのあるマスおよびその隣接する4マスに連鎖技の半分のダメージを与える。同一のマスに複数回のダメージを与える場合、1回ごとに最終ダメージ-<color=#00F6FF>20%</color>。終結状態中は<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を<color=#00F6FF>5</color>獲得できる（上限を超えて獲得可能）",
  str_skill_desc_330153 = "<color=#00F6FF>4</color>マス選択し、<color=#00F6FF>2</color>ターン存続する空爆ビーコンを設置して<color=#00F6FF>終結状態</color>を発動する。2ターン持続。終結状態中は自身の通常攻撃で<color=#00F6FF>斜め方向を攻撃可能</color>。連鎖技が追加で空爆ビーコンのあるマスおよびその隣接する4マスに連鎖技の半分のダメージを与える。同一のマスに複数回のダメージを与える場合、1回ごとに最終ダメージ-<color=#00F6FF>20%</color>。終結状態中は<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を<color=#00F6FF>5</color>獲得できる（上限を超えて獲得可能）",
  str_skill_desc_336153 = "<color=#00F6FF>4</color>マス選択し、<color=#00F6FF>2</color>ターン存続する空爆ビーコンを設置して<color=#00F6FF>終結状態</color>を発動する。2ターン持続。終結状態中は自身の通常攻撃で<color=#00F6FF>斜め方向を攻撃可能</color>。連鎖技が追加で空爆ビーコンのあるマスおよびその隣接する4マスに連鎖技の半分のダメージを与える。同一のマスに複数回のダメージを与える場合、1回ごとに最終ダメージ-<color=#00F6FF>20%</color>。終結状態中は<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を<color=#00F6FF>5</color>獲得できる（上限を超えて獲得可能）",
  str_skill_desc_2001531 = "<color=#00F6FF>周囲3マス</color>以内の最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001532 = "<color=#00F6FF>周囲4マス</color>以内の最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001533 = "<color=#00F6FF>周囲4マス</color>以内のすべての敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_passive_name_410153 = "啓光の力",
  str_skill_passive_name_413153 = "啓光の力",
  str_skill_passive_name_420153 = "啓光の力",
  str_skill_passive_name_423153 = "啓光の力",
  str_skill_passive_name_426153 = "啓光の力",
  str_skill_passive_name_430153 = "啓光の力",
  str_skill_passive_name_433153 = "啓光の力",
  str_skill_passive_name_436153 = "啓光の力",
  str_skill_passive_desc_410153 = "<link=\"30043\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_413153 = "<link=\"30043\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>{1}</color>。戦闘開始時、ただちに終結値を<color=#00F6FF>2</color>獲得する",
  str_skill_passive_desc_420153 = "<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>{1}</color>。濃色マスを通過するたびに、一時的な終結値を<color=#00F6FF>1</color>獲得する（上限を超えて獲得可能）。極光タイム発動時、または味方ターン終了時、追加分のポイントは消失する",
  str_skill_passive_desc_423153 = "<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>{1}</color>。戦闘開始時、ただちに終結値を<color=#00F6FF>2</color>獲得する。濃色マスを通過するたびに、一時的な終結値を<color=#00F6FF>1</color>獲得する（上限を超えて獲得可能）。極光タイム発動時、または味方ターン終了時、追加分のポイントは消失する",
  str_skill_passive_desc_426153 = "<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>{1}</color>。戦闘開始時、ただちに終結値を<color=#00F6FF>2</color>獲得する。濃色マスを通過するたびに、一時的な終結値を<color=#00F6FF>1</color>獲得し（上限を超えて獲得可能）、さらに連鎖技のダメージ係数+<color=#00F6FF>2%</color>。極光タイム発動時、または味方ターン終了時、追加分のポイントは消失する",
  str_skill_passive_desc_430153 = "<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>{1}</color>。チーム内の<color=#00F6FF>雷属性</color>、または<color=#00F6FF>啓光連邦</color>の光霊が<color=#00F6FF>自身の攻撃力</color>に応じて終結値の半分の強化を獲得する。濃色マスを通過するたびに、一時的な終結値を<color=#00F6FF>1</color>獲得する（上限を超えて獲得可能）。極光タイム発動時、または味方ターン終了時、追加分のポイントは消失する",
  str_skill_passive_desc_433153 = "<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>{1}</color>。チーム内の<color=#00F6FF>雷属性</color>、または<color=#00F6FF>啓光連邦</color>の光霊が<color=#00F6FF>自身の攻撃力</color>に応じて終結値の半分の強化を獲得する。戦闘開始時、ただちに終結値を<color=#00F6FF>2</color>獲得する。濃色マスを通過するたびに、一時的な終結値を<color=#00F6FF>1</color>獲得する（上限を超えて獲得可能）。極光タイム発動時、または味方ターン終了時、追加分のポイントは消失する",
  str_skill_passive_desc_436153 = "<link=\"300442\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>{1}</color>。チーム内の<color=#00F6FF>雷属性</color>、または<color=#00F6FF>啓光連邦</color>の光霊が<color=#00F6FF>自身の攻撃力</color>に応じて終結値の半分の強化を獲得する。戦闘開始時、ただちに終結値を<color=#00F6FF>2</color>獲得する。濃色マスを通過するたびに、一時的な終結値を<color=#00F6FF>1</color>獲得し（上限を超えて獲得可能）、さらに連鎖技のダメージ係数+<color=#00F6FF>2%</color>。極光タイム発動時、または味方ターン終了時、追加分のポイントと連鎖技の強化は消失する",
  str_skill_upgrade_refine_desc_16015311 = "能動技強化：終結状態になり、一時的な終結値を<color=#00F6FF>6</color>獲得する",
  str_skill_upgrade_refine_desc_16015312 = "連鎖技強化：ダメージ係数+<color=#00F6FF>10%</color>",
  str_skill_upgrade_refine_desc_16015313 = "能動技強化：終結状態になった後、連鎖技が同一のマスに複数回のダメージを与える場合、1回ごとに最終ダメージ-<color=#00F6FF>15%</color>",
  str_skill_desc_2501531 = "<color=#00F6FF>周囲3マス</color>以内の最も近くにいる敵3体に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_2501532 = "<color=#00F6FF>周囲4マス</color>以内の最も近くにいる敵4体に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2501533 = "<color=#00F6FF>周囲4マス</color>以内の全ての敵に<color=#00F6FF>170%</color>のダメージを与える",
  str_skill_desc_340153 = "<color=#00F6FF>4</color>マス選択し、<color=#00F6FF>2</color>ターン存続する空爆ビーコンを設置して<color=#00F6FF>終結状態</color>を発動する。2ターン持続。終結状態中は自身の通常攻撃で<color=#00F6FF>斜め方向を攻撃可能</color>。連鎖技が追加で空爆ビーコンのあるマスおよびその隣接する4マスに連鎖技の半分のダメージを与える。同一のマスに複数回のダメージを与える場合、1回ごとに最終ダメージ-<color=#00F6FF>20%</color>。終結状態中は<link=\"300443\"><#FFAE07><u>終結値</u></color></link>を<color=#00F6FF>6</color>獲得できる（上限を超えて獲得可能）",
  str_skill_desc_360153 = "<color=#00F6FF>4</color>マス選択し、<color=#00F6FF>2</color>ターン存続する空爆ビーコンを設置して<color=#00F6FF>終結状態</color>を発動する。2ターン持続。終結状態中は自身の通常攻撃で<color=#00F6FF>斜め方向を攻撃可能</color>。連鎖技が追加で空爆ビーコンのあるマスおよびその隣接する4マスに連鎖技の半分のダメージを与える。同一のマスに複数回のダメージを与える場合、1回ごとに最終ダメージ-<color=#00F6FF>15%</color>。終結状態中は<link=\"300443\"><#FFAE07><u>終結値</u></color></link>を<color=#00F6FF>6</color>獲得できる（上限を超えて獲得可能）",
  str_skill_passive_desc_450153 = "<link=\"300443\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>3%</color>。チーム内の<color=#00F6FF>雷属性</color>、または<color=#00F6FF>啓光連邦</color>の光霊が<color=#00F6FF>自身の攻撃力</color>に応じて終結値の半分の強化を獲得する。濃色マスを通過するたびに、一時的な終結値を<color=#00F6FF>1</color>獲得する（上限を超えて獲得可能）。極光タイム発動時、または味方ターン終了時、追加分のポイントは消失する",
  str_skill_passive_desc_453153 = "<link=\"300443\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>3%</color>。チーム内の<color=#00F6FF>雷属性</color>、または<color=#00F6FF>啓光連邦</color>の光霊が<color=#00F6FF>自身の攻撃力</color>に応じて終結値の半分の強化を獲得する。戦闘開始時、ただちに終結値を<color=#00F6FF>2</color>獲得する。濃色マスを通過するたびに、一時的な終結値を<color=#00F6FF>1</color>獲得する（上限を超えて獲得可能）。極光タイム発動時、または味方ターン終了時、追加分のポイントは消失する",
  str_skill_passive_desc_456153 = "<link=\"300443\"><#FFAE07><u>終結値</u></color></link>を獲得できる。終結値1ごとに自身の攻撃力+<color=#00F6FF>3%</color>。チーム内の<color=#00F6FF>雷属性</color>、または<color=#00F6FF>啓光連邦</color>の光霊が<color=#00F6FF>自身の攻撃力</color>に応じて終結値の半分の強化を獲得する。戦闘開始時、ただちに終結値を<color=#00F6FF>2</color>獲得する。濃色マスを通過するたびに、一時的な終結値を<color=#00F6FF>1</color>獲得し（上限を超えて獲得可能）、さらに連鎖技のダメージ係数+<color=#00F6FF>2%</color>。極光タイム発動時、または味方ターン終了時、追加分のポイントと連鎖技の強化は消失する",
  str_skill_name_290230101 = "クローディア・落隕",
  str_skill_name_290230102 = "クローディア・落隕",
  str_skill_name_290230103 = "クローディア・落隕",
  str_skill_name_290230104 = "クローディア・落隕",
  str_skill_name_290230201 = "クローディア・跳斬",
  str_skill_name_290230202 = "クローディア・跳斬",
  str_skill_name_290230203 = "クローディア・跳斬",
  str_skill_name_290230301 = "クローディア・斬絶",
  str_skill_name_290230401 = "台座出現",
  str_skill_name_290240101 = "アーシル・進攻",
  str_skill_desc_290230101 = "クローディアが地上にいる時、敵の十字方向の範囲内すべての台座に突進攻撃させ、敵に複数回のダメージを与える",
  str_skill_desc_290230102 = "クローディアが台座の上に立っている時、敵の十字方向のすべての台座に突進攻撃させる。クローディアがその範囲内にいる場合、敵を眩暈状態にする",
  str_skill_desc_290230103 = "クローディアがアーシルの上にいる時、敵の十字方向のすべての台座に突進攻撃させる。アーシルも範囲内にいる場合、敵を眩暈状態にしてノックバックする",
  str_skill_desc_290230104 = "敵の十字方向の範囲内に台座がない場合、クローディアは戦場の中心の5×5のランダムな位置に台座を4個生成し、戦場内の敵から最も遠い位置に生成された台座に瞬間移動する",
  str_skill_desc_290230201 = "敵が攻撃範囲内にいる場合、クローディアは敵のそばに瞬間移動して大ダメージを与えた後、一定距離後退する。敵が攻撃範囲内にいない場合、戦場の中心の5×5の範囲内に台座を生成し、戦場内の敵から最も遠い位置に瞬間移動する",
  str_skill_desc_290230202 = "敵が攻撃範囲内にいる場合、クローディアは敵のそばに瞬間移動して大ダメージを与えた後、一定距離後退する。敵が攻撃範囲内にいない場合、戦場の中心の5×5の範囲内に台座を生成し、戦場内の敵から最も遠い位置に瞬間移動する",
  str_skill_desc_290230203 = "敵が攻撃範囲内にいる場合、クローディアは敵のそばに瞬間移動して大ダメージを与えた後、一定距離後退する。敵が攻撃範囲内にいない場合、戦場の中心の5×5の範囲内に台座を生成し、戦場内の敵から最も遠い位置に瞬間移動する",
  str_skill_desc_290230301 = "戦場の中央と敵の足下にそれぞれ台座を生成する。台座に瞬間移動して斬撃を繰り出し、全範囲内の敵にダメージを与える",
  str_skill_desc_290230401 = "ターン開始時、フィールドの端に最大10個の台座を生成する",
  str_skill_desc_290240101 = "アーシルが攻撃範囲内の敵に近づいてダメージを1回与え、ルート上のすべての台座を粉砕する。攻撃できる敵がいない場合、その場で潜行状態になる",
  str_skill_name_290250101 = "終の生け贄",
  str_skill_desc_290250101 = "ミノスが戦場をランダムに一定距離移動し、すべてのマスをリセットする。移動終了後、ミノスは射撃で光霊に大ダメージを1回与える",
  str_skill_name_290250102 = "幻像攻撃",
  str_skill_desc_290250102 = "ミノスは移動中に強化マスを通過すると、強化マス上に幻像を召喚し、プレイヤーにダメージを1回与える。ミノスのもつ印のスタック数が多いほど、幻像の与えるダメージが大きくなる",
  str_skill_name_290250201 = "幻像刷新",
  str_skill_desc_290250201 = "ミノスが戦場の強化マスと弱化マスをすべて吸収し、光霊に対して射撃でダメージを与える。強化マスを1つ吸収するごとにダメージを追加で1回与える。ミノスの印のスタック数が多いほど、射撃ダメージが大きくなる",
  str_skill_name_390250101 = "罪業・幻像攻撃",
  str_skill_desc_390250101 = "罪業・ミノスが弱化マスの最も多いルートを5マス移動し、通過した強化マスと弱化マスを吸収する。弱化マスを吸収するたびに幻像を呼び出し、ターゲットにダメージを1回与える。その回の移動で弱化マスを吸収しなかった場合、または戦場に弱化マスが存在しない場合、自身の周囲3マスに弱化マスを7つ召喚する",
  str_skill_name_390250102 = "罪業・終の生け贄",
  str_skill_desc_390250102 = "罪業・ミノスが全範囲内のターゲットをロックして射撃し、ダメージを与える",
  str_skill_name_390310106 = "罪業・スイートキッス",
  str_skill_desc_390310106 = "罪業・バーバラがターゲットから最も離れた位置まで連鎖で移動する。その後、安全エリア以外の広範囲にダメージを与え、さらに安全エリア以外の火属性のマスを粉砕する",
  str_skill_name_390310107 = "罪業・終音・フレアの印",
  str_skill_desc_390310107 = "罪業・バーバラがターゲットから最も離れた位置まで連鎖で移動する。その後、戦場の中心に仲間を呼び出し、全範囲のターゲットにダメージを与えてノックバックする",
  str_skill_name_390320102 = "罪業・戦慄の協奏曲",
  str_skill_name_390320103 = "罪業・アビス轟鳴曲",
  str_skill_desc_390320102 = "罪業・クラリンがターゲットを攻撃可能な最も遠い位置まで連鎖で移動し、周囲2マス以内のすべてのターゲットにダメージを与える。その回の移動でターゲットを攻撃しなかった場合、戦場内のランダムな位置に触手を召喚する",
  str_skill_desc_390320103 = "罪業・クラリンがターゲットから最も離れた位置まで連鎖で移動し、全範囲のターゲットにダメージを与える",
  str_skill_name_390330102 = "罪業・沈黙の花盛り",
  str_skill_name_390330103 = "罪業・血晶の領域",
  str_skill_desc_390330102 = "罪業・ベリエがターゲットを攻撃可能な最も遠い位置まで連鎖で移動し、縦、横、斜めの16マス以内のすべてのターゲットにダメージを与える。その回の移動でターゲットを攻撃しなかった場合、戦場内のランダムな位置に血染めの結晶を召喚する",
  str_skill_desc_390330103 = "罪業・ベリエがターゲットから最も離れた位置まで連鎖で移動し、全範囲のターゲットにダメージを与える",
