  str_skill_passive_name_410156 = "宝物庫の守護者",
  str_skill_passive_name_420156 = "宝物庫の守護者",
  str_skill_desc_2001561 = "<color=#00F6FF>パラソル有り</color>：<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える\n<color=#00F6FF>パラソル無し</color>：最も近くの敵2体に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_2001562 = "<color=#00F6FF>パラソル有り</color>：<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える\n<color=#00F6FF>パラソル無し</color>：最も近くの敵3体に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2001563 = "<color=#00F6FF>パラソル有り</color>：<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える\n<color=#00F6FF>パラソル無し</color>：最も近くの敵4体に<color=#00F6FF>170%</color>のダメージを与える",
  str_skill_desc_2001564 = "<color=#00F6FF>パラソル有り</color>：<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える\n<color=#00F6FF>パラソル無し</color>：最も近くの敵2体に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_2001565 = "<color=#00F6FF>パラソル有り</color>：<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える\n<color=#00F6FF>パラソル無し</color>：最も近くの敵3体に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2001566 = "<color=#00F6FF>パラソル有り</color>：<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える\n<color=#00F6FF>パラソル無し</color>：最も近くの敵4体に<color=#00F6FF>170%</color>のダメージを与える",
  str_skill_desc_300156 = "<color=#00F6FF>パラソル有り</color>：進入可能なマス1つを選択してパラソルを投げ、ルート上のマスに<color=#00F6FF>80%</color>のダメージを与えた後、<color=#00F6FF>パラソル無し状態</color>に変化する\n<color=#00F6FF>パラソル無し</color>：パラソルを回収しルート上のマスに<color=#00F6FF>640%</color>のダメージを与え、<color=#00F6FF>パラソル有り状態</color>に変化する\nパラソルを設置したマスが踏まれるなどの理由でパラソルが除去された場合は<color=#00F6FF>パラソル有り状態</color>に戻る。敵に踏まれた時、技のCDターン数<color=#00F6FF>+1</color>",
  str_skill_desc_3001560 = "<color=#00F6FF>パラソル有り</color>：進入可能なマス1つを選択してパラソルを投げ、ルート上のマスに<color=#00F6FF>80%</color>のダメージを与えた後、<color=#00F6FF>パラソル無し状態</color>に変化する\n<color=#00F6FF>パラソル無し</color>：パラソルを回収しルート上のマスに<color=#00F6FF>640%</color>のダメージを与え、<color=#00F6FF>パラソル有り状態</color>に変化する\nパラソルを設置したマスが踏まれるなどの理由でパラソルが除去された場合は<color=#00F6FF>パラソル有り状態</color>に戻る。敵に踏まれた時、技のCDターン数<color=#00F6FF>+1</color>",
  str_skill_desc_303156 = "<color=#00F6FF>パラソル有り</color>：進入可能なマス1つを選択してパラソルを投げ、ルート上のマスに<color=#00F6FF>80%</color>のダメージを与えた後、<color=#00F6FF>パラソル無し状態</color>に変化する\n<color=#00F6FF>パラソル無し</color>：パラソルを回収しルート上のマスに<color=#00F6FF>640%</color>のダメージを与え、<color=#00F6FF>パラソル有り状態</color>に変化する\nパラソルを設置したマスが踏まれるなどの理由でパラソルが除去された場合は<color=#00F6FF>パラソル有り状態</color>に戻る。敵に踏まれた時、技のCDターン数<color=#00F6FF>+1</color>",
  str_skill_desc_3031560 = "<color=#00F6FF>パラソル有り</color>：進入可能なマス1つを選択してパラソルを投げ、ルート上のマスに<color=#00F6FF>80%</color>のダメージを与えた後、<color=#00F6FF>パラソル無し状態</color>に変化する\n<color=#00F6FF>パラソル無し</color>：パラソルを回収しルート上のマスに<color=#00F6FF>640%</color>のダメージを与え、<color=#00F6FF>パラソル有り状態</color>に変化する\nパラソルを設置したマスが踏まれるなどの理由でパラソルが除去された場合は<color=#00F6FF>パラソル有り状態</color>に戻る。敵に踏まれた時、技のCDターン数<color=#00F6FF>+1</color>",
  str_skill_desc_306156 = "<color=#00F6FF>パラソル有り</color>：進入可能なマス1つを選択してパラソルを投げ、ルート上のマスに<color=#00F6FF>100%</color>のダメージを与えた後、<color=#00F6FF>パラソル無し状態</color>に変化する\n<color=#00F6FF>パラソル無し</color>：パラソルを回収しルート上のマスに<color=#00F6FF>1000%</color>のダメージを与え、<color=#00F6FF>パラソル有り状態</color>に変化する\nパラソルを設置したマスが踏まれるなどの理由でパラソルが除去された場合は<color=#00F6FF>パラソル有り状態</color>に戻る。敵に踏まれた時、技のCDターン数<color=#00F6FF>+1</color>",
  str_skill_desc_3061560 = "<color=#00F6FF>パラソル有り</color>：進入可能なマス1つを選択してパラソルを投げ、ルート上のマスに<color=#00F6FF>100%</color>のダメージを与えた後、<color=#00F6FF>パラソル無し状態</color>に変化する\n<color=#00F6FF>パラソル無し</color>：パラソルを回収しルート上のマスに<color=#00F6FF>1000%</color>のダメージを与え、<color=#00F6FF>パラソル有り状態</color>に変化する\nパラソルを設置したマスが踏まれるなどの理由でパラソルが除去された場合は<color=#00F6FF>パラソル有り状態</color>に戻る。敵に踏まれた時、技のCDターン数<color=#00F6FF>+1</color>",
  str_skill_desc_310156 = "<color=#00F6FF>パラソル有り</color>：進入可能なマス1つを選択してパラソルを投げ、ルート上のマスに<color=#00F6FF>80%</color>のダメージを与えた後、<color=#00F6FF>パラソル無し状態</color>に変化する\n<color=#00F6FF>パラソル無し</color>：パラソルを回収しルート上のマスに<color=#00F6FF>640%</color>のダメージを与え、<color=#00F6FF>パラソル有り状態</color>に変化する\nパラソルを設置したマスが踏まれるなどの理由でパラソルが除去された場合は<color=#00F6FF>パラソル有り状態</color>に戻る。敵に踏まれた時、技のCDターン数<color=#00F6FF>+1</color>",
