  str_skill_desc_3361560 = "<color=#00F6FF>パラソル有り</color>：進入可能なマス1つを選択してパラソルを投げ、ルート上のマスに<color=#00F6FF>100%</color>のダメージを与える。パラソルの着地点に追加で装備技を1回放ち、<color=#00F6FF>パラソル無し状態</color>に変化する\n<color=#00F6FF>パラソル無し</color>：パラソルを回収しルート上のマスに<color=#00F6FF>1000%</color>のダメージを与え、<color=#00F6FF>パラソル有り状態</color>に変化する\nパラソルを設置したマスが踏まれる等の理由でパラソルが除去された場合は<color=#00F6FF>パラソル有り状態</color>に戻る。味方|敵に踏まれた時、技のCDターン数<color=#00F6FF>-1</color>|<color=#00F6FF>+1</color>",
  str_skill_passive_desc_410156 = "<color=#00F6FF>パラソル無し状態</color>から<color=#00F6FF>パラソル有り状態</color>に変化した時、ただちに自身の<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}</color>のダメージを1回与える",
  str_skill_passive_desc_420156 = "<color=#00F6FF>パラソル無し状態</color>の時、通常攻撃で<color=#00F6FF>斜め方向</color>の敵を攻撃できる。<color=#00F6FF>パラソル無し状態</color>から<color=#00F6FF>パラソル有り状態</color>に変化した時、ただちに自身の<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}</color>のダメージを1回与える",
  str_skill_upgrade_desc_16015613 = "能動技強化：投げたパラソルが選択した位置の<color=#00F6FF>周囲1マス</color>に追加で装備技ダメージを1回与える",
  str_skill_upgrade_desc_16015616 = "能動技強化：<color=#00F6FF>パラソル有り</color>状態の能動技ダメージ係数が<color=#00F6FF>100%</color>に増加、<color=#00F6FF>パラソル無し</color>状態は<color=#00F6FF>1000%</color>に増加",
  str_skill_upgrade_desc_15015712 = "能動技強化：戦闘開始時に繰糸値を<color=#00F6FF>2</color>獲得",
  str_skill_upgrade_desc_15015715 = "能動技強化：戦闘開始時に繰糸値を<color=#00F6FF>4</color>獲得",
