  str_skill_passive_name_410157 = "繰り糸の戯れ",
  str_skill_passive_name_420157 = "繰り糸の戯れ",
  str_skill_passive_name_430157 = "繰り糸の戯れ",
  str_skill_desc_2001571 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001572 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001573 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300157 = "1マス選択して<link=\"30050\"><#FFAE07><u>繰糸値</u></color></link>を<color=#00F6FF>3</color>消費し、<color=#00F6FF>マナエ</color>を召喚する。または、<link=\"30050\"><#FFAE07><u>繰糸値</u></color></link>を<color=#00F6FF>1</color>消費して<color=#00F6FF>マナエ</color>を移動させる。光霊ターン終了時にマナエは回収される。連鎖中、マナエはできる限りサナエと<color=#00F6FF>相対的な位置を保って移動する</color>。移動中、衝突したターゲットに<color=#00F6FF>マナエの攻撃力と同値の</color>防御力無視ダメージを与える。マナエの攻撃力はサナエの基礎攻撃力の<color=#00F6FF>70%</color>",
  str_skill_desc_310157 = "1マス選択して<link=\"30050\"><#FFAE07><u>繰糸値</u></color></link>を<color=#00F6FF>3</color>消費し、<color=#00F6FF>マナエ</color>を召喚する。または、<link=\"30050\"><#FFAE07><u>繰糸値</u></color></link>を<color=#00F6FF>1</color>消費して<color=#00F6FF>マナエ</color>を移動させる。光霊ターン終了時にマナエは回収される。連鎖中、マナエはできる限りサナエと<color=#00F6FF>相対的な位置を保って移動する</color>。移動中、衝突したターゲットに<color=#00F6FF>マナエの攻撃力と同値の</color>防御力無視ダメージを与える。マナエの攻撃力はサナエの基礎攻撃力の<color=#00F6FF>70%</color>",
