  str_skill_passive_desc_410157 = "マナエがダメージを与えるごとに繰り糸の印を1スタック獲得する。繰り糸の印1スタックにつき、マナエがサナエから引き継ぐ攻撃力+<color=#00F6FF>{1}</color>、最大30スタックまで",
  str_skill_passive_desc_420157 = "マナエがダメージを与えるごとに繰り糸の印を1スタック獲得する。繰り糸の印1スタックにつき、マナエがサナエから引き継ぐ攻撃力+<color=#00F6FF>{1}</color>、最大30スタック。繰り糸の印が上限に到達、または1ターンでマナエが印を<color=#00F6FF>5</color>スタック以上獲得した時、サナエと<color=#00F6FF>同時に連鎖技を発動できる</color>",
  str_skill_upgrade_desc_16015813 = "装備技強化：ジョーカーが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>",
  str_skill_upgrade_desc_16015816 = "装備技強化：毎ターン1回まで、ジョーカーが隊長と隊員で位置変更された時、隊長変更回数を1獲得する",
  str_skill_desc_300158 = "任意の敵1体を選び、<color=#00F6FF>{1}％</color>のダメージを与え、さらに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>のスタック数を<color=#00F6FF>2倍にする</color>。さらに戦闘時、ジョーカーは<link=\"30051\"><#FFAE07><u>【特別技】</u></color></link>を発動できる。ターゲットが占有するマス数が多いほど、能動技のダメージが増加する",
  str_skill_desc_320158 = "任意の敵1体を選び、<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>のスタック数を<color=#00F6FF>2倍にする</color>。前のターンで能動技が発動可能だった場合、スタック数は<color=#00F6FF>3倍</color>になる。さらに戦闘時、ジョーカーは<link=\"30051\"><#FFAE07><u>【特別技】</u></color></link>を発動できる。ターゲットが占有するマス数が多いほど、能動技のダメージが増加する",
  str_skill_desc_3201580 = "任意の敵1体を選び、<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>のスタック数を<color=#00F6FF>2倍にする</color>。前のターンで能動技が発動可能だった場合、スタック数は<color=#00F6FF>3倍</color>になる。さらに戦闘時、ジョーカーは<link=\"30051\"><#FFAE07><u>【特別技】</u></color></link>を発動できる。ターゲットが占有するマス数が多いほど、能動技のダメージが増加する",
  str_skill_desc_2001581 = "<color=#00F6FF>周囲4マス</color>以内の最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与え、命中した敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>3スタック</color>を付与する",
  str_skill_desc_2001582 = "<color=#00F6FF>周囲4マス</color>以内の最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与え、命中した敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>5スタック</color>を付与する",
  str_skill_desc_2001583 = "<color=#00F6FF>周囲4マス</color>以内のすべての敵に<color=#00F6FF>{1}%</color>のダメージを与え、命中した敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>7スタック</color>を付与する",
  str_skill_passive_desc_410158 = "撃破した敵の<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>スタックを残っている敵ごとに最大<color=#00F6FF>{1}</color>振り分ける",
  str_skill_passive_desc_413158 = "撃破した敵の<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>スタックを残っている敵ごとに最大<color=#00F6FF>{1}</color>振り分ける。ジョーカーが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>",
  str_skill_passive_desc_416158 = "撃破した敵の<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>スタックを残っている敵ごとに最大<color=#00F6FF>{1}</color>振り分ける。ジョーカーが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>。毎ターン1回まで、ジョーカーが隊長と隊員で位置変更された時、隊長変更回数を1獲得する",
  str_skill_passive_desc_430158 = "撃破した敵の<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>スタックを残っている敵ごとに最大<color=#00F6FF>{1}</color>振り分ける。通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与する",
  str_skill_passive_desc_433158 = "撃破した敵の<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>スタックを残っている敵ごとに最大<color=#00F6FF>{1}</color>振り分ける。通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与する。ジョーカーが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>",
  str_skill_passive_desc_436158 = "撃破した敵の<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>スタックを残っている敵ごとに最大<color=#00F6FF>{1}</color>振り分ける。通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与する。ジョーカーが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>。毎ターン1回まで、ジョーカーが隊長と隊員で位置変更された時、隊長変更回数を1獲得する",
  str_skill_upgrade_desc_16015913 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16015916 = "装備技強化：クイーンが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>15%</color>",
  str_skill_desc_300159 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}％</color>のダメージを1回与え、さらに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>6</color>スタックを付与する。さらに戦闘時、クイーンは<link=\"30051\"><#FFAE07><u>【特别技】</u></color></link>を発動できる",
  str_skill_desc_320159 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}％</color>のダメージを1回与え、さらに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>6</color>スタックを付与する。水属性の敵には<color=#00F6FF>12</color>スタック付与する。さらに戦闘時、クイーンは<link=\"30051\"><#FFAE07><u>【特别技】</u></color></link>を発動できる",
  str_skill_desc_2001591 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、命中した敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>2</color>スタックを付与する。水属性の敵には<color=#00F6FF>4</color>スタック付与する",
  str_skill_desc_2001592 = "<color=#00F6FF>縦、横、斜めの16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、命中した敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>3</color>スタックを付与する。水属性の敵には<color=#00F6FF>6</color>スタック付与する",
  str_skill_desc_2001593 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、命中した敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>4</color>スタックを付与する。水属性の敵には<color=#00F6FF>8</color>スタック付与する",
  str_skill_passive_desc_410159 = "通常攻撃が二連撃になる。各ダメージは基本ダメージの<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_416159 = "通常攻撃が二連撃になる。各ダメージは基本ダメージの<color=#00F6FF>{1}</color>。クイーンが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>15%</color>",
  str_skill_passive_desc_430159 = "通常攻撃が二連撃になる。各ダメージは基本ダメージの<color=#00F6FF>{1}</color>。通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与し、水属性の敵には<color=#00F6FF>2</color>スタック付与する",
  str_skill_passive_desc_436159 = "通常攻撃が二連撃になる。各ダメージは基本ダメージの<color=#00F6FF>{1}</color>。通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与し、水属性の敵には<color=#00F6FF>2</color>スタック付与する。クイーンが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>15%</color>",
  str_skill_desc_300160 = "<color=#00F6FF>周囲2マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>9</color>スタックを付与する。さらに戦闘時、フォックスは<link=\"30051\"><#FFAE07><u>【特別技】</u></color></link>を発動できる",
  str_skill_desc_320160 = "周囲<color=#00F6FF>2マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>9</color>スタックを付与する。火属性の敵には<color=#00F6FF>18</color>スタック付与する。さらに戦闘時、フォックスは<link=\"30051\"><#FFAE07><u>【特別技】</u></color></link>を発動できる",
  str_skill_desc_2001601 = "<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、それぞれの敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与する。火属性の敵には<color=#00F6FF>3</color>スタック付与する",
  str_skill_desc_2001602 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、それぞれの敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>2</color>スタックを付与する。火属性の敵には<color=#00F6FF>4</color>スタック付与する",
  str_skill_desc_2001603 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、それぞれの敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>3</color>スタックを付与する。火属性の敵には<color=#00F6FF>6</color>スタック付与する",
  str_skill_passive_desc_410160 = "毎ターン、1回目の通常攻撃の与ダメージが通常ダメージの<color=#00F6FF>{1}</color>倍になる",
  str_skill_passive_desc_415160 = "毎ターン、1回目の通常攻撃の与ダメージが通常の<color=#00F6FF>{1}</color>倍になる。フォックスが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>15%</color>",
  str_skill_passive_desc_430160 = "通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与し、火属性の敵には<color=#00F6FF>2</color>スタック付与する。毎ターン、1回目の通常攻撃の与ダメージと付与する<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>のスタック数が通常の<color=#00F6FF>{1}</color>倍になる。",
  str_skill_passive_desc_435160 = "通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与し、火属性の敵には<color=#00F6FF>2</color>スタック付与する。毎ターン、1回目の通常攻撃の与ダメージと付与する<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>のスタック数が通常の<color=#00F6FF>{1}</color>倍になる。フォックスが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>15%</color>",
  str_skill_upgrade_desc_15016012 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15016015 = "装備技強化：フォックスが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>15%</color>",
  str_skill_desc_300161 = "1マス選択して<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>9</color>スタックを付与する。さらに戦闘時、ヴァイオレットは<link=\"30051\"><#FFAE07><u>【特別技】</u></color></link>を発動できる",
  str_skill_desc_320161 = "1マス選択して<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>9</color>スタックを付与する。さらに戦闘時、ヴァイオレットは<link=\"30051\"><#FFAE07><u>【特別技】</u></color></link>を発動できる。森属性の敵には<color=#00F6FF>18</color>スタック付与する",
  str_skill_desc_2001611 = "<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、それぞれの敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>2</color>スタックを付与する。森属性の敵には<color=#00F6FF>4</color>スタック付与する",
  str_skill_desc_2001612 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、それぞれの敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>3</color>スタックを付与する。森属性の敵には<color=#00F6FF>6</color>スタック付与する",
  str_skill_desc_2001613 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、それぞれの敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>4</color>スタックを付与する。森属性の敵には<color=#00F6FF>8</color>スタック付与する",
  str_skill_passive_desc_410161 = "ヴァイオレットが<color=#00F6FF>WEAK</color>状態の敵に与えるすべてのダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_415161 = "ヴァイオレットが<color=#00F6FF>WEAK</color>状態の敵に与えるすべてのダメージ+<color=#00F6FF>{1}</color>。ヴァイオレットが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>",
  str_skill_passive_desc_430161 = "ヴァイオレットが<color=#00F6FF>WEAK</color>状態の敵に与えるすべてのダメージ+<color=#00F6FF>{1}</color>。通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与し、森属性の敵には<color=#00F6FF>2</color>スタック付与する",
  str_skill_passive_desc_435161 = "ヴァイオレットが<color=#00F6FF>WEAK</color>状態の敵に与えるすべてのダメージ+<color=#00F6FF>{1}</color>。通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与し、森属性の敵には<color=#00F6FF>2</color>スタック付与する。ヴァイオレットが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>",
  str_skill_upgrade_desc_15016112 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15016115 = "装備技強化：ヴァイオレットが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>",
  str_skill_upgrade_desc_15016212 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15016215 = "装備技強化：モナが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>",
  str_skill_desc_3001621 = "1マス選択して、自身からその方向へと伸びるマスとその隣接するマスに<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>5</color>スタックを付与する。さらに戦闘時、モナは<link=\"30051\"><#FFAE07><u>【特別技】</u></color></link>を発動できる",
  str_skill_desc_3201621 = "1マス選択して、自身からその方向へと伸びるマスとその隣接するマスに<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>5</color>スタックを付与する。雷属性の敵には<color=#00F6FF>10</color>スタック付与する。さらに戦闘時、モナは<link=\"30051\"><#FFAE07><u>【特別技】</u></color></link>を発動できる",
  str_skill_desc_2001621 = "<color=#00F6FF>周囲3マス</color>以内の最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与する。雷属性の敵には<color=#00F6FF>3</color>スタック付与する",
  str_skill_desc_2001622 = "<color=#00F6FF>周囲3マス</color>以内の最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>2</color>スタックを付与する。雷属性の敵には<color=#00F6FF>4</color>スタック付与する",
  str_skill_desc_2001623 = "<color=#00F6FF>周囲3マス</color>以内の最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>3</color>スタックを付与する。雷属性の敵には<color=#00F6FF>5</color>スタック付与する",
  str_skill_passive_desc_410162 = "モナが敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>のスタックを付与する時、<color=#00F6FF>{1}</color>の確率で効果が倍増する。また、<color=#00F6FF>{2}</color>の確率で<color=#00F6FF>WEAK</color>状態にする",
  str_skill_passive_desc_415162 = "モナが敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>のスタックを付与する時、<color=#00F6FF>{1}</color>の確率で効果が倍増する。また、<color=#00F6FF>{2}</color>の確率で<color=#00F6FF>WEAK</color>状態にする。モナが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>",
  str_skill_passive_desc_430162 = "モナが敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>のスタックを付与する時、<color=#00F6FF>{1}</color>の確率で効果が倍増する。また、<color=#00F6FF>{2}</color>の確率で<color=#00F6FF>WEAK</color>状態にする。通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与し、雷属性の敵には<color=#00F6FF>2</color>スタック付与する",
  str_skill_passive_desc_435162 = "モナが敵に<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link>のスタックを付与する時、<color=#00F6FF>{1}</color>の確率で効果が倍増する。また、<color=#00F6FF>{2}</color>の確率で<color=#00F6FF>WEAK</color>状態にする。通常攻撃ごとに<link=\"30052\"><#FFAE07><u>弱点暴露</u></color></link><color=#00F6FF>1</color>スタックを付与し、雷属性の敵には<color=#00F6FF>2</color>スタック付与する。モナが初めて隊員から隊長になった時、そのターンの通常攻撃の与ダメージ+<color=#00F6FF>20%</color>",
