  str_skill_desc_4001580 = "出撃しているP5Rコラボ光霊の数に応じて、敵全体にダメージを与える。<color=#00F6FF>WEAK状態</color>の敵にはより大きなダメージを与え、<color=#00F6FF>WEAK状態</color>をクリアする。すべての敵が<color=#00F6FF>WEAK状態</color>の場合、<color=#00F6FF>特別演出</color>が発動する",
  str_skill_desc_1207103 = "前のターンにターゲットのいたマスおよびその周囲2マスに衝撃波を放つ。中心からの距離が近いほどダメージが大きくなり、技の中心にいるターゲットは即撃破される",
  str_skill_desc_12071031 = "前のターンにターゲットのいたマスおよびその周囲2マスに衝撃波を放つ。技の中心および周囲1マスにいるターゲットは即撃破される",
  str_skill_desc_12071032 = "前のターンにターゲットのいたマスおよびその周囲2マスに衝撃波を放つ。技の範囲内にいるターゲットは即撃破される",
