  str_skill_desc_3301652 = "最も近くの森属性のマス<color=#00F6FF>4</color>つを雷属性に変え、<color=#00F6FF>アポロンの雷矢</color>を設置する。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3351652 = "最も近くの森属性のマス<color=#00F6FF>5</color>つを雷属性に変え、<color=#00F6FF>アポロンの雷矢</color>を設置する。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_passive_name_400165 = "アポロンの領域",
  str_skill_passive_desc_400165 = "連鎖技が目標へ<color=#00F6FF>命中するごとに</color>、その<color=#00F6FF>周囲1マス</color>以内のランダムなマスに<color=#00F6FF>アポロンの雷矢</color>を設置する。敵が通過すると<color=#00F6FF>起爆</color>し、<color=#00F6FF>十字5マス</color>の範囲にシエルの攻撃力<color=#00F6FF>{1}</color>の防御力無視のダメージを与える。<color=#00F6FF>アポロンの雷矢</color>は<color=#00F6FF>起爆</color>、または<color=#00F6FF>ターン終了</color>で消滅する",
  str_skill_passive_name_420165 = "アポロンの領域",
