  str_skill_desc_2001643 = "<color=#00F6FF>縦、横、斜めの最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300164 = "<link=\"30053\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>消費して、<color=#00F6FF>十字方向16マス</color>以内の任意の位置に瞬間移動する。移動方向に対して<color=#00F6FF>前後各1マス</color>を火属性に変える",
  str_skill_desc_303164 = "<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>消費し、<color=#00F6FF>十字方向16マス</color>以内の任意の位置に瞬間移動する。移動方向に対して<color=#00F6FF>前後各1マス</color>を火属性に変える",
  str_skill_desc_306164 = "<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>消費し、<color=#00F6FF>十字方向16マス</color>以内の任意の位置に瞬間移動する。移動方向に対して<color=#00F6FF>前後各1マス</color>を火属性に変える",
  str_skill_desc_320164 = "<link=\"30053\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>消費し、<color=#00F6FF>十字方向16マス</color>以内の任意の位置に瞬間移動する。移動方向に対して<color=#00F6FF>前後各1マス</color>を火属性に変える。さらに<color=#00F6FF>経路上のマスおよび前方1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_323164 = "<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>消費し、<color=#00F6FF>十字方向16マス</color>以内の任意の位置に瞬間移動する。移動方向に対して<color=#00F6FF>前後各1マス</color>を火属性に変える。さらに<color=#00F6FF>経路上のマスおよび前方1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_326164 = "<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>消費し、<color=#00F6FF>十字方向16マス</color>以内の任意の位置に瞬間移動する。移動方向に対して<color=#00F6FF>前後各1マス</color>を火属性に変える。さらに<color=#00F6FF>経路上のマスおよび前方1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_330164 = "<link=\"30053\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>消費し、<color=#00F6FF>十字方向16マス</color>以内の任意の位置に瞬間移動する。移動方向に対して<color=#00F6FF>前後各1マス</color>を火属性に変える。さらに<color=#00F6FF>経路上のマスおよび前方1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、各ターン<color=#00F6FF>1</color>回まで、敵に命中した場合<link=\"30053\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>1</color>獲得する",
  str_skill_desc_333164 = "<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>消費し、<color=#00F6FF>十字方向16マス</color>以内の任意の位置に瞬間移動する。移動方向に対して<color=#00F6FF>前後各1マス</color>を火属性に変える。さらに<color=#00F6FF>経路上のマスおよび前方1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、毎ターン<color=#00F6FF>1</color>回まで、敵に命中した場合<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>1</color>獲得する",
  str_skill_desc_336164 = "<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>消費し、<color=#00F6FF>十字方向16マス</color>以内の任意の位置に瞬間移動する。移動方向に対して<color=#00F6FF>前後各1マス</color>を火属性に変える。さらに<color=#00F6FF>経路上のマスおよび前方1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、毎ターン<color=#00F6FF>2</color>回まで、敵に命中した場合<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>1</color>獲得する",
  str_skill_passive_name_410164 = "征伐ノ光耀",
  str_skill_passive_desc_410164 = "カレン・照魂が火属性のマスにいる敵に通常攻撃する時、攻撃力<color=#00F6FF>{1}</color>の防御力無視のダメージを付与する",
  str_skill_upgrade_desc_16016413 = "能動技強化：戦闘開始時に<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>2</color>獲得",
  str_skill_upgrade_desc_16016416 = "能動技強化：毎ターン<color=#00F6FF>2</color>回まで、敵に命中した場合<link=\"30054\"><#FFAE07><u>照魂値</u></color></link>を<color=#00F6FF>1</color>獲得。（覚醒3で有効）",
  str_skill_desc_5220011 = "進入可能なマスを<color=#00F6FF>1</color>つ選択し、<color=#00F6FF>万色マス</color>に変える",
  str_skill_name_2001681 = "高圧放水",
  str_skill_name_2001682 = "高圧放水",
  str_skill_name_2001683 = "高圧放水",
  str_skill_name_300168 = "飛び出す噴流",
  str_skill_name_320168 = "飛び出す噴流",
  str_skill_name_330168 = "飛び出す噴流",
  str_skill_desc_2001681 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える。ターゲットの足下のランダムな1マスに<link=\"30061\"><#FFAE07><u>噴流の印</u></color></link>を生成する",
  str_skill_desc_2001682 = "最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える。ターゲットの足下のランダムな1マスに<link=\"30061\"><#FFAE07><u>噴流の印</u></color></link>を生成する",
  str_skill_desc_2001683 = "最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える。ターゲットの足下のランダムな1マスに<link=\"30061\"><#FFAE07><u>噴流の印</u></color></link>を生成する",
  str_skill_desc_300168 = "戦場のすべての<link=\"30061\"><#FFAE07><u>噴流の印</u></color></link>を解放し、1つにつき<color=#00F6FF>十字5マス</color>に<color=#00F6FF>240%</color>のダメージを与える。同一ターゲットに複数回のダメージを与える時、ダメージが徐々に減少する。最低で当初の効果の<color=#00F6FF>10%</color>",
  str_skill_desc_320168 = "戦場のすべての<link=\"30061\"><#FFAE07><u>噴流の印</u></color></link>を解放し、1つにつき<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>240%</color>のダメージを与える。同一ターゲットに複数回のダメージを与える時、ダメージが徐々に減少する。最低で当初の効果の<color=#00F6FF>10%</color>",
  str_skill_desc_330168 = "戦場のすべての<link=\"30061\"><#FFAE07><u>噴流の印</u></color></link>を解放し、1つにつき<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>240%</color>のダメージを与える。同一ターゲットに複数回のダメージを与える時、ダメージが徐々に減少する。最低で当初の効果の<color=#00F6FF>10%</color>。印の効果範囲が<color=#00F6FF>3</color>つ重なるマスに噴流の印がない場合、新しい噴流の印を1つ生成する",
  str_skill_passive_name_410168 = "水球の盾",
  str_skill_passive_name_415168 = "水球の盾",
  str_skill_passive_desc_410168 = "連鎖で<link=\"30061\"><#FFAE07><u>噴流の印</u></color></link>を通過する時、レインボーの基礎防御力の<color=#00F6FF>{1}</color>相当のシールドを展開する。1ターン持続",
  str_skill_passive_desc_415168 = "連鎖で<link=\"30061\"><#FFAE07><u>噴流の印</u></color></link>を通過する時、レインボーの基礎防御力の<color=#00F6FF>{1}</color>相当のシールドを展開する。1ターン持続。毎ターン開始時、戦場にある水属性のランダムな<color=#00F6FF>1</color>マスに噴流の印を生成する",
  str_skill_upgrade_desc_15016812 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15016815 = "装備技強化：毎ターン開始時、フィールドのランダムな水属性の<color=#00F6FF>1</color>マスに噴流の印を生成する",
  str_skill_name_2001671 = "トップショット",
  str_skill_name_2001672 = "トップショット",
