  str_skill_name_303167 = "マジックハンド",
  str_skill_name_306167 = "マジックハンド",
  str_skill_name_320167 = "マジックハンド",
  str_skill_name_323167 = "マジックハンド",
  str_skill_name_326167 = "マジックハンド",
  str_skill_desc_2001671 = "<color=#00F6FF>周囲3マス</color>以内の最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001672 = "<color=#00F6FF>周囲3マス</color>以内の最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001673 = "<color=#00F6FF>周囲3マス</color>以内のすべての敵に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300167 = "ジェノは<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動し、<link=\"30058\"><#FFAE07><u>【始原のカード】</u></color></link>を使う。理性値を<color=#00F6FF>{1}</color>消費して始原のカードを1枚獲得する。ターン内に再び発動すると理性値の消費+<color=#00F6FF>5</color>",
  str_skill_desc_303167 = "ジェノは<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動し、<link=\"30059\"><#FFAE07><u>【始原のカード】</u></color></link>を使う。理性値を<color=#00F6FF>{1}</color>消費して始原のカードを1枚獲得する。ターン内に再び発動すると理性値の消費+<color=#00F6FF>5</color>",
  str_skill_desc_306167 = "ジェノは<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動し、<link=\"30060\"><#FFAE07><u>【始原のカード】</u></color></link>を使う。理性値を<color=#00F6FF>{1}</color>消費して始原のカードを1枚獲得する。ターン内に再び発動すると理性値の消費+<color=#00F6FF>5</color>",
  str_skill_desc_320167 = "ジェノは<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動し、<link=\"30058\"><#FFAE07><u>【始原のカード】</u></color></link>を使う。理性値を<color=#00F6FF>{1}</color>消費して始原のカードを1枚獲得する。ターン内に再び発動すると理性値の消費+<color=#00F6FF>5</color>。「集う光」と「凌日の星月」の強化を同時に受けている光霊は、理性値が低くなるほど攻撃力上昇が大きくなる。最大で+<color=#00F6FF>66.6%</color>",
  str_skill_desc_323167 = "ジェノは<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動し、<link=\"30059\"><#FFAE07><u>【始原のカード】</u></color></link>を使う。理性値を<color=#00F6FF>{1}</color>消費して始原のカードを1枚獲得する。ターン内に再び発動すると理性値の消費+<color=#00F6FF>5</color>。「集う光」と「凌日の星月」の強化を同時に受けている光霊は、理性値が低くなるほど攻撃力上昇が大きくなる。最大で+<color=#00F6FF>66.6%</color>",
  str_skill_desc_326167 = "ジェノは<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動し、<link=\"30060\"><#FFAE07><u>【始原のカード】</u></color></link>を使う。理性値を<color=#00F6FF>{1}</color>消費して始原のカードを1枚獲得する。ターン内に再び発動すると理性値の消費+<color=#00F6FF>5</color>。「集う光」と「凌日の星月」の強化を同時に受けている光霊は、理性値が低くなるほど攻撃力上昇が大きくなる。最大で+<color=#00F6FF>66.6%</color>",
  str_skill_passive_name_410167 = "ボトムディール",
  str_skill_passive_desc_410167 = "【始原のカード】の効果を発動するごとに、ジェノの基礎攻撃力の<color=#00F6FF>{1}</color>相当のチームHPを回復する。この効果は理性システムの影響を受けない。チームのHPが低いほど回復効果が高くなり、最大で2倍になる",
  str_skill_passive_name_413167 = "ボトムディール",
  str_skill_passive_desc_413167 = "【始原のカード】の効果を発動するごとに、ジェノの基礎攻撃力の<color=#00F6FF>{1}</color>相当のチームHPを回復する。この効果は理性システムの影響を受けない。チームのHPが低いほど回復効果が高くなり、最大で2倍になる。戦闘開始時にランダムな<color=#00F6FF>2</color>枚のカードを獲得する",
  str_skill_passive_name_416167 = "ボトムディール",
  str_skill_passive_desc_416167 = "【始原のカード】の効果を発動するごとに、ジェノの基礎攻撃力の<color=#00F6FF>{1}</color>相当のチームHPを回復する。この効果は理性システムの影響を受けない。チームのHPが低いほど回復効果が高くなり、最大で2倍になる。戦闘開始時にランダムな<color=#00F6FF>2</color>枚のカードを獲得する",
  str_skill_passive_name_430167 = "ボトムディール",
  str_skill_passive_desc_430167 = "【始原のカード】の効果を発動するごとに、ジェノの基礎攻撃力の<color=#00F6FF>{1}</color>相当のチームHPを回復する。この効果は理性システムの影響を受けない。チームのHPが低いほど回復効果が高くなり、最大で2倍になる。極光タイム発動時にランダムな始原のカードを1枚獲得する",
  str_skill_passive_name_433167 = "ボトムディール",
  str_skill_passive_desc_433167 = "【始原のカード】の効果を発動するごとに、ジェノの基礎攻撃力の<color=#00F6FF>{1}</color>相当のチームHPを回復する。この効果は理性システムの影響を受けない。チームのHPが低いほど回復効果が高くなり、最大で2倍になる。戦闘開始時にランダムな<color=#00F6FF>2</color>枚のカードを獲得し、極光タイム発動時にランダムな1枚のカードを獲得する",
  str_skill_passive_name_436167 = "ボトムディール",
  str_skill_passive_desc_436167 = "【始原のカード】の効果を発動するごとに、ジェノの基礎攻撃力の<color=#00F6FF>{1}</color>相当のチームHPを回復する。この効果は理性システムの影響を受けない。チームのHPが低いほど回復効果が高くなり、最大で2倍になる。戦闘開始時にランダムな<color=#00F6FF>2</color>枚のカードを獲得し、極光タイム発動時にランダムな1枚のカードを獲得する",
  str_skill_upgrade_desc_16016713 = "戦闘開始時に<link=\"30059\"><#FFAE07><u>【始原のカード】</u></color></link>をランダムで<color=#00F6FF>2</color>枚獲得する",
  str_skill_upgrade_desc_16016716 = "始原のカード技強化：「異色の双輝」効果が失った理性値の<color=#00F6FF>25%</color>を回復する",
  str_skill_name_3001670 = "凌日の星月",
  str_skill_desc_3001670 = "<color=#00F6FF>現在の最後尾</color>の光霊がジェノの基礎攻撃力の<color=#00F6FF>7%</color>相当の追加攻撃力を獲得する",
  str_skill_name_3001671 = "集う光",
  str_skill_desc_3001671 = "<color=#00F6FF>現在の隊長</color>の光霊がジェノの基礎攻撃力の<color=#00F6FF>8%</color>相当の追加攻撃力を獲得する",
  str_skill_name_3001674 = "異色の双輝",
  str_skill_desc_3001674 = "この戦闘の隊長変更回数+1。さらに失った理性値の<color=#00F6FF>25%</color>を回復する",
  str_skill_name_30016740 = "異色の双輝",
  str_skill_desc_30016740 = "この戦闘の隊長変更回数+1。さらに失った理性値の<color=#00F6FF>18%</color>を回復する",
  str_skill_name_10071413 = "理性の波動",
  str_skill_desc_10071413 = "触手は光霊の理性値に影響する。毎ターン開始時、存在する触手1つにつき理性値-2。撃破時に理性値3回復する",
  str_skill_upgrade_desc_16016613 = "能動技強化：各ウェーブ開始時に撒き餌<color=#00F6FF>1</color>を獲得する",
  str_skill_upgrade_desc_16016616 = "能動技強化：狩猟の印が<color=#00F6FF>2/3</color>ターン持続した時、「キャロ」が<color=#00F6FF>350%/500%</color>のダメージを与える",
  str_skill_passive_name_410166 = "星雲の波",
  str_skill_passive_name_430166 = "星雲の波",
  str_skill_passive_desc_410166 = "フィアが<color=#00F6FF>水属性</color>のマスを移動する時に高速滑走し、隣り合うマスにいる敵にダメージを与える。<link=\"30057\"><#FFAE07><u>カーブ</u></color></link>時は<color=#00F6FF>周囲1マス</color>にダメージを与え、ターゲットに1ターン持続するぬめぬめ効果を付与する：弱点属性から受けるダメージ係数+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_430166 = "フィアが<color=#00F6FF>水属性</color>のマスを移動する時に高速滑走し、隣り合うマスにいる敵にダメージを与える。<link=\"30057\"><#FFAE07><u>カーブ</u></color></link>時は<color=#00F6FF>周囲1マス</color>にダメージを与え、ターゲットに1ターン持続するぬめぬめ効果を付与する：弱点属性から受けるダメージ係数+<color=#00F6FF>{1}</color>。火属性の敵に対する効果は<color=#00F6FF>50%</color>",
  str_skill_name_300166 = "キャロ大作戦",
  str_skill_name_320166 = "キャロ大作戦",
  str_skill_name_303166 = "キャロ大作戦",
  str_skill_name_306166 = "キャロ大作戦",
  str_skill_name_323166 = "キャロ大作戦",
  str_skill_name_326166 = "キャロ大作戦",
  str_skill_desc_300166 = "<link=\"30055\"><#FFAE07><u>撒き餌</u></color></link>を<color=#00F6FF>1</color>消費し、任意の1マスに狩猟の印を設置、または狩猟の印1つを選択して「キャロ」を解放する。狩猟の印が<color=#00F6FF>0/1/2/3</color>ターン持続した時、「キャロ」が<color=#00F6FF>狩猟の印のあるマス/十字5マス/菱形13マス/正方形25マス</color>の範囲に<color=#00F6FF>150%/200%/250%/300%</color>のダメージを与える",
  str_skill_desc_320166 = "<link=\"30055\"><#FFAE07><u>撒き餌</u></color></link>を<color=#00F6FF>1</color>消費し、任意の1マスに狩猟の印を設置、または狩猟の印1つを選択して「キャロ」を解放する。狩猟の印が<color=#00F6FF>0/1/2/3</color>ターン持続した時、「キャロ」が<color=#00F6FF>狩猟の印のあるマス/十字5マス/菱形13マス/正方形25マス</color>の範囲に<color=#00F6FF>150%/200%/250%/300%</color>のダメージを与える。ターン内のターゲットの基礎防御力-<color=#00F6FF>5%</color>。効果は累積可",
  str_skill_desc_303166 = "<link=\"30056\"><#FFAE07><u>撒き餌</u></color></link>を<color=#00F6FF>1</color>消費し、任意の1マスに狩猟の印を設置、または狩猟の印1つを選択して「キャロ」を解放する。狩猟の印が<color=#00F6FF>0/1/2/3</color>ターン持続した時、「キャロ」が<color=#00F6FF>狩猟の印のあるマス/十字5マス/菱形13マス/正方形25マス</color>の範囲に<color=#00F6FF>150%/200%/250%/300%</color>のダメージを与える",
  str_skill_desc_306166 = "<link=\"30056\"><#FFAE07><u>撒き餌</u></color></link>を<color=#00F6FF>1</color>消費し、任意の1マスに狩猟の印を設置、または狩猟の印1つを選択して「キャロ」を解放する。狩猟の印が<color=#00F6FF>0/1/2/3</color>ターン持続した時、「キャロ」が<color=#00F6FF>狩猟の印のあるマス/十字5マス/菱形13マス/正方形25マス</color>の範囲に<color=#00F6FF>150%/200%/350%/500%</color>のダメージを与える",
  str_skill_desc_323166 = "<link=\"30056\"><#FFAE07><u>撒き餌</u></color></link>を<color=#00F6FF>1</color>消費し、任意の1マスに狩猟の印を設置、または狩猟の印1つを選択して「キャロ」を解放する。狩猟の印が<color=#00F6FF>0/1/2/3</color>ターン持続した時、「キャロ」が<color=#00F6FF>狩猟の印のあるマス/十字5マス/菱形13マス/正方形25マス</color>の範囲に<color=#00F6FF>150%/200%/250%/300%</color>のダメージを与える。ターン内のターゲットの基礎防御力-<color=#00F6FF>5%</color>。効果は累積可",
  str_skill_desc_326166 = "<link=\"30056\"><#FFAE07><u>撒き餌</u></color></link>を<color=#00F6FF>1</color>消費し、任意の1マスに狩猟の印を設置、または狩猟の印1つを選択して「キャロ」を解放する。狩猟の印が<color=#00F6FF>0/1/2/3</color>ターン持続した時、「キャロ」が<color=#00F6FF>狩猟の印のあるマス/十字5マス/菱形13マス/正方形25マス</color>の範囲に<color=#00F6FF>150%/200%/350%/500%</color>のダメージを与える。ターン内のターゲットの基礎防御力-<color=#00F6FF>5%</color>。効果は累積可",
