  str_skill_name_29039011 = "一撃一殺・襲",
  str_skill_name_29039013 = "死線・釈",
  str_skill_desc_29039011 = "十字方向の最大範囲内に光霊がいない場合、光霊のいる方向へ移動する。隣接する4マスの範囲に光霊が入った時、攻撃を行う",
  str_skill_desc_290390111 = "縦、横、斜めの最大範囲内に光霊がいない場合、光霊のいる方向へ移動する。光霊の周囲1マス範囲内に入ると攻撃を行う",
  str_skill_desc_29039013 = "十字方向の最大範囲内に光霊がいる場合、その場で技を発動し、光霊にダメージを与える",
  str_skill_desc_290390131 = "縦、横、斜めの最大範囲内に光霊がいる場合、その場で技を発動し、光霊にダメージを与える",
  str_skill_name_291030101 = "ミラー攻撃",
  str_skill_name_291030102 = "ミラー瞬間移動",
  str_skill_name_291030103 = "ミラー召喚",
  str_skill_desc_291030101 = "ニポリスが移動後、ミラーを通じて前方のターゲットにダメージを与える",
  str_skill_desc_291030102 = "ニポリス本体の方が光霊に近い場合、本体とミラーの位置が入れ替わり、その途中にいるターゲットにダメージを与える",
  str_skill_desc_291030103 = "ミラーを召喚し、次のターンにミラーが自爆してランダムな光霊に2ターンの呪い効果を付与する",
  str_skill_name_5220011 = "染色のハマビシ",
