  str_skill_name_2001302 = "吾輩が法だ！",
  str_skill_name_2001303 = "吾輩が法だ！",
  str_skill_desc_2001301 = "<color=#00F6FF>周囲1マス</color>の範囲内の<link=\"30062\"><#FFAE07><u>律法の像</u></color></link>の<color=#00F6FF>レベル+1</color>",
  str_skill_desc_2001302 = "<color=#00F6FF>菱形12マス</color>の範囲内の<link=\"30062\"><#FFAE07><u>律法の像</u></color></link>の<color=#00F6FF>レベル+1</color>",
  str_skill_desc_2001303 = "<color=#00F6FF>周囲2マス</color>の範囲内の<link=\"30062\"><#FFAE07><u>律法の像</u></color></link>の<color=#00F6FF>レベル+1</color>",
  str_skill_name_300130 = "全員入廷！",
  str_skill_desc_300130 = "進入可能なマスを1つ選び、選択したマスと周囲2マス範囲内の<link=\"30062\"><#FFAE07><u>律法の像</u></color></link>をすべて<color=#00F6FF>破壊</color>し、選択したマス上に新たな律法の像を1体生成する。レベルは破壊された律法の像の<color=#00F6FF>レベルの和</color>となる。範囲内に律法の像がない場合、選択したマス上にLv1の律法の像を1体生成する",
  str_skill_passive_name_400130 = "法の報いだ！",
  str_skill_passive_desc_400130 = "連鎖5マスごとに、1つ前のマスの位置にLv1の<link=\"30062\"><#FFAE07><u>律法の像</u></color></link>を生成する。すでに律法の像がある場合、その像の<color=#00F6FF>レベル+1</color>",
  str_skill_name_2001711 = "死線",
