  str_skill_name_3001711 = "獄門",
  str_skill_name_3021711 = "獄門",
  str_skill_name_3051711 = "獄門",
  str_skill_passive_name_400171 = "一撃一殺",
  str_skill_passive_name_430171 = "一撃一殺",
  str_skill_desc_2001711 = "<color=#00F6FF>十字方向の8マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001712 = "<color=#00F6FF>十字方向の12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001713 = "<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2201711 = "<color=#00F6FF>十字方向8マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える。障害物に阻まれた場合、両側に1マスずつ拡散する",
  str_skill_desc_2201712 = "<color=#00F6FF>十字方向12マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える。障害物に阻まれた場合、両側に1マスずつ拡散する",
  str_skill_desc_2201713 = "<color=#00F6FF>十字方向最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える。障害物に阻まれた場合、両側に1マスずつ拡散する",
  str_skill_desc_3001711 = "<link=\"30063\"><#FFAE07><u>銃剣値</u></color></link>を<color=#00F6FF>2</color>消費して残りの銃剣値をクリアし、そのターンの連鎖技終了後、<color=#00F6FF>周囲1マス</color>の範囲に<color=#00F6FF>200%</color>のダメージを与える。銃剣値を１クリアするごとに最終ダメージ+<color=#00F6FF>20%</color>",
  str_skill_desc_3021711 = "<link=\"30064\"><#FFAE07><u>銃剣値</u></color></link>を<color=#00F6FF>2</color>消費して残りの銃剣値をクリアし、そのターンの連鎖技終了後、<color=#00F6FF>周囲1マス</color>の範囲に<color=#00F6FF>200%</color>のダメージを与える。銃剣値を１クリアするごとに最終ダメージ+<color=#00F6FF>20%</color>",
  str_skill_desc_3051711 = "<link=\"30064\"><#FFAE07><u>銃剣値</u></color></link>を<color=#00F6FF>2</color>消費して残りの銃剣値をクリアし、そのターンの連鎖技終了後、<color=#00F6FF>周囲1マス</color>の範囲に<color=#00F6FF>200%</color>のダメージを与える。銃剣値を１クリアするごとに最終ダメージ+<color=#00F6FF>25%</color>",
  str_skill_passive_desc_400171 = "森属性のマス、または強化マスを1マス連鎖するごとに<color=#00F6FF>急所分析</color>値が1増加し、6になると次の通常攻撃がクリティカル攻撃となり、ランダムで<color=#00F6FF>120%～{1}</color>のダメージを与える。その後、すべての<color=#00F6FF>急所分析</color>値をクリアする",
  str_skill_passive_desc_430171 = "森属性のマス、または強化マスを1マス連鎖するごとに<color=#00F6FF>急所分析</color>値が1増加し、6になると次の通常攻撃がクリティカル攻撃となり、ランダムで<color=#00F6FF>120%～{1}</color>のダメージを与える。その後、すべての<color=#00F6FF>急所分析</color>値をクリアし、銃剣値を1獲得する",
  str_skill_upgrade_desc_15017112 = "能動技強化：戦闘開始時に銃剣値<color=#00F6FF>2</color>を獲得する",
  str_skill_upgrade_desc_15017115 = "能動技強化：銃剣値を1クリアするごとに最終ダメージ+<color=#00F6FF>25%</color>",
  str_skill_name_2001701 = "硝煙散る雷雨",
  str_skill_name_2001702 = "硝煙散る雷雨",
  str_skill_name_2001703 = "硝煙散る雷雨",
  str_skill_name_300170 = "詰め寄る弾域",
  str_skill_name_306170 = "詰め寄る弾域",
  str_skill_name_320170 = "詰め寄る弾域",
  str_skill_name_326170 = "詰め寄る弾域",
  str_skill_name_330170 = "詰め寄る弾域",
  str_skill_name_336170 = "詰め寄る弾域",
  str_skill_passive_name_410170 = "歪みなき照星",
  str_skill_passive_name_420170 = "歪みなき照星",
  str_skill_desc_2001701 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001702 = "<color=#00F6FF>周囲1マス以内</color>および、その<color=#00F6FF>十字方向に連鎖する雷属性のマス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001703 = "<color=#00F6FF>周囲1マス以内</color>および、その<color=#00F6FF>8方向に連鎖する雷属性のマス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300170 = "1マス選択し、さらに左右2方向のうち1つを選択する。選択した側のエリア内のすべてのマスの色が選んだ方向に1マス前進する。<color=#00F6FF>選択したマスのある縦1列</color>に雷属性のマスを生成する",
  str_skill_desc_306170 = "1マス選択し、さらに左右2方向のうち1つを選択する。選択した側のエリア内のすべてのマスの色が選んだ方向に1マス前進する。<color=#00F6FF>選択したマスのある縦1列</color>に雷属性のマスを生成する",
  str_skill_desc_320170 = "1マス選択し、さらに左右2方向のうち1つを選択する。選択した側のエリア内のすべてのマスの色が選んだ方向に1マス前進する。<color=#00F6FF>選択したマスのある縦1列</color>に雷属性のマスを生成し、<color=#00F6FF>250%</color>のダメージを与える",
  str_skill_desc_326170 = "1マス選択し、さらに左右2方向のうち1つを選択する。選択した側のエリア内のすべてのマスの色が選んだ方向に1マス前進する。<color=#00F6FF>選択したマスのある縦1列</color>に雷属性のマスを生成し、<color=#00F6FF>250%</color>のダメージを与える",
  str_skill_desc_330170 = "1マス選択し、さらに左右2方向のうち1つを選択する。選択した側のエリア内のすべてのマスの色が選んだ方向に1マス前進する。<color=#00F6FF>選択したマスのある縦1列</color>に雷属性のマスを生成し、<color=#00F6FF>250%</color>のダメージを与える。選択したマスに<color=#00F6FF>大きさが1マスの敵</color>がいた場合、選択した方向に1マス強制移動させる",
  str_skill_desc_336170 = "1マス選択し、さらに左右2方向のうち1つを選択する。選択した側のエリア内のすべてのマスの色が選んだ方向に1マス前進する。<color=#00F6FF>選択したマスのある縦1列</color>に雷属性のマスを生成し、<color=#00F6FF>250%</color>のダメージを与える。選択したマスに<color=#00F6FF>大きさが1マスの敵</color>がいた場合、選択した方向に1マス強制移動させる",
  str_skill_passive_desc_410170 = "連鎖技がダメージを与える時、ターゲットの距離が遠いほどダメージが高くなる。周囲1マスごとに最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420170 = "連鎖技と能動技がダメージを与える時、ターゲットの距離が遠いほどダメージが高くなる。周囲1マスごとに最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_upgrade_desc_16017013 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16017016 = "能動技強化：技のクールダウンターン<color=#FFFF00>-1</color>。",
  str_skill_name_290370121 = "砲台主砲・震撃",
  str_skill_desc_290370121 = "1マス移動後、主砲で前方4マスの範囲内に衝撃波を起こす。範囲内のターゲットにダメージを与え、3マスノックバックする",
  str_skill_desc_290370123 = "主砲で前方4マスの範囲内に衝撃波を起こす。範囲内のターゲットにダメージを与え、3マスノックバックする",
  str_skill_name_290370122 = "超限主砲・震撃",
  str_skill_desc_290370122 = "2マス移動後、主砲で前方4マスの範囲内に衝撃波を起こす。範囲内のターゲットに大ダメージを与え、3マスノックバックする",
  str_skill_name_290370131 = "肩砲掃射・左",
  str_skill_desc_290370131 = "1マス移動後、扇形範囲内にいる敵をロックして攻撃し、一定のダメージを与える",
  str_skill_desc_290370133 = "扇形範囲内にいる敵をロックして連続射撃を繰り出し、一定のダメージを与える",
  str_skill_name_290370132 = "超限肩砲・左",
  str_skill_desc_290370132 = "2マス移動後、扇形範囲内にいる敵をロックして連続射撃を繰り出し、大ダメージを与える",
  str_skill_name_290370141 = "肩砲掃射・右",
  str_skill_desc_290370141 = "1マス移動後、扇形範囲内にいる敵をロックして攻撃し、一定のダメージを与える",
  str_skill_desc_290370143 = "扇形範囲内にいる敵をロックして連続射撃を繰り出し、一定のダメージを与える",
  str_skill_name_290370142 = "超限肩砲・右",
  str_skill_desc_290370142 = "2マス移動後、扇形範囲内にいる敵をロックして連続射撃を繰り出し、大ダメージを与える",
  str_skill_name_290370151 = "リミッター解除",
  str_skill_desc_290370151 = "超限状態となり、移動能力と攻撃力が上昇する",
  str_skill_name_490370401 = "緊急補修",
  str_skill_desc_490370401 = "HPが固定され、緊急修理状態になる。まず主砲で光霊をフィールドの端へノックバックし、さらに自身にシールドを付与する。1ターン経過後、シールドは2倍のHPに変換される",
  str_skill_name_40004451 = "汚染",
  str_skill_desc_40004451 = "範囲内のターゲットを攻撃し、さらにノックバックする",
  str_skill_name_49004213 = "輪廻の使者",
  str_skill_desc_49004213 = "マクガフィモが白夜と満潮の到来に備えてエネルギーを蓄積し、センターを召喚して自身を守る",
  str_skill_name_49004215 = "白夜と満潮",
  str_skill_desc_49004215 = "マクガフィモが戦場の一定エリアに集中爆撃を行い、同時にエリア内のマスをロックする",
  str_skill_name_400060101 = "戦力アップ",
  str_skill_desc_400060101 = "抱擁者は周囲1マス以内の暗鬼に取り付き、シールドを与えると同時に攻撃力と移動力を強化する",
  str_skill_name_400060201 = "回復強化",
  str_skill_desc_400060201 = "ドーンの周囲1マスまで近づくと、体内に溶け込んでHPを回復し、攻撃力を上昇させ、シールドを付与する",
  str_skill_desc_400071502 = "自身の縦、横、斜めの最大方向上のターゲットに、その最大HPを基準とした割合ダメージを与える。自身の周囲8方向にターゲットがいない場合は自身にバリアを付与する",
  str_skill_desc_400072502 = "自身の縦、横、斜めの最大方向上のターゲットに、その最大HPを基準とした割合ダメージを与える。自身の周囲8方向にターゲットがいない場合は味方のHPを回復する",
  str_skill_desc_490050302 = "範囲内のターゲットにダメージを与え、自分の側に引き寄せる。攻撃が命中するしないにかかわらず、自身の周囲2マスをリセットする。ターゲットに攻撃が命中した場合、ターゲットの周囲1マスのマスをロックする",
  str_skill_desc_491050301 = "ターゲットのいる方向に幅2列分の衝撃波を放ち、命中したターゲットにダメージを与える。さらに攻撃範囲内のマスをリセットする",
  str_skill_desc_491050302 = "範囲内のターゲットにダメージを与え、自分の側に引き寄せる。ターゲットに命中するしないに関わらず、自身の周囲3マスをリセットする",
  str_skill_desc_490028304 = "召喚師が4つのビーコンを召喚し、すべてのビーコンのHPを回復させる",
  str_skill_desc_491028304 = "召喚師が4つのビーコンを召喚し、すべてのビーコンのHPを回復させる",
  str_skill_desc_490025102 = "狂暴なゴーストの幻影を生成する。戦場に既に幻影が存在している場合は、既存の幻影を呼び戻してから新たな幻影を召喚する。幻影の呼び戻しに成功すると、ゴースト本体の攻撃力が戦闘終了まで一定量上昇する",
  str_skill_desc_490025201 = "狂暴なゴーストが2回攻撃し、さらに幻影を召喚して自身の戦闘を支援させる",
  str_skill_name_491025203 = "幻影召還",
  str_skill_desc_491025203 = "戦場に幻影が存在している場合、幻影を呼び戻してHPを回復し、さらに攻撃力を増加させる。移動力の上昇効果は失われる。戦場に幻影が存在しない場合、自身の移動力が上がる",
  str_skill_name_215007811 = "通常攻撃",
  str_skill_desc_215007811 = "ロビンが範囲内のターゲットを攻撃する",
