  str_skill_desc_213004911 = "範囲内のターゲットにダメージを与える",
  str_skill_name_213004912 = "激昂咆哮",
  str_skill_desc_213004912 = "周囲1マスの範囲内のターゲットにダメージを与える。範囲内の水属性以外のマスをリセットする",
  str_skill_name_214009111 = "ハープ協奏曲",
  str_skill_desc_214009111 = "発動ターン中、戦場にある水属性のマス1つにつき、味方に0.5%の攻撃力バフを付与する",
  str_skill_name_214009112 = "哀しみの前奏曲",
  str_skill_desc_214009112 = "フィールド内のターゲットにダメージを与える",
  str_skill_name_214009121 = "ハープ協奏曲",
  str_skill_desc_214009121 = "発動ターン中、味方の移動力+1。同時に戦場にある水属性のマス1つにつき、味方に0.5%の攻撃力バフを付与する",
  str_skill_desc_490022306 = "ボアドムが力を凝縮して十字の広範囲への火属性攻撃の発動準備を行う。命中したターゲットにダメージを与え、火傷効果を付与する。力の凝縮中、双剣を召喚して自身を守り、召喚が成功すると戦場のその他の暗鬼の移動力が上昇する",
  str_skill_desc_490022310 = "ボアドムが力を凝縮して十字の広範囲への雷属性攻撃の発動準備を行う。命中したターゲットにダメージを与え、麻痺効果を付与する。力の凝縮中、双剣を召喚して自身を守り、召喚が成功すると戦場のその他の暗鬼の移動力が上昇する",
  str_skill_desc_490064302 = "タルタロスのエネルギーがあふれだし、縦横4列の範囲にダメージを与える",
  str_skill_desc_490060103 = "戦場のランダムな7ヵ所に2×2の範囲ダメージを与え、範囲内に炎上マスを生成する。光霊に命中した場合、その光霊のいる位置の周囲1マスの属性を変化させ、隊長に呪いを付与する",
  str_skill_desc_49006811 = "アモルファスがプレイヤーから遠いフィールド端の位置まで瞬間移動し、遠距離攻撃する。さらに、光霊との直線上の一定範囲内のランダムな位置にヴォイド2匹と爆裂1匹を投下する",
  str_skill_desc_49006812 = "アモルファスが全域のランダムな位置にヴォイド4匹を投下する",
  str_skill_desc_490091202 = "ターゲットが前のターンにいた場所にビームパルスを放ち、途中および目標地点にいるターゲットにダメージを与える。ターゲットに命中した場合、隊長に呪いを付与する",
  str_skill_desc_490091203 = "範囲内のターゲットにダメージを与える",
  str_skill_desc_490006301 = "マクガフィンが前方の空間を歪めて切り裂き、ダメージを与える。光霊に命中すると、光霊が盲目状態になる",
  str_skill_desc_490006302 = "マクガフィンが光霊をノックバックし、高潮の到来に備えてエネルギーを蓄積する",
  str_skill_desc_490006304 = "マクガフィンが一定エリアに集中爆撃を行い、それぞれのエリア内に封印の石碑を設置する",
  str_skill_desc_490006306 = "マクガフィンが一定エリアに集中爆撃を行い、それぞれのエリア内に封印の石碑を設置する",
  str_skill_desc_491006304 = "マクガフィンが一定エリアに集中爆撃を行い、エリア内のマスを粉砕する",
  str_skill_desc_491006305 = "マクガフィンが一定エリアに集中爆撃を行い、エリア内のマスを粉砕する",
  str_skill_desc_491006302 = "マクガフィンが光霊をノックバックし、戦場にセンターを召喚する。さらに高潮の到来に備えてエネルギーを蓄積する",
  str_skill_desc_492006306 = "マクガフィンが一定エリアに集中爆撃を行い、エリア内のマスを粉砕する",
  str_skill_desc_490110101 = "ミュートは自身の前方2マスの長方形最大範囲内に衝撃波を放ち、範囲内のターゲットにダメージを与える。ターゲットに命中すると、自身のHPを回復する",
  str_skill_desc_490110201 = "ミュートは自身の前方2マスの長方形最大範囲内に衝撃波を放ち、範囲内のターゲットにダメージを与える。ターゲットに命中すると、ターゲットが疲労状態になる",
  str_skill_name_490110301 = "ソレイスの号令",
  str_skill_desc_490110301 = "ミュートが戦場にいる暗鬼の攻撃力と移動力を上昇させる",
  str_skill_name_400040101 = "ダーククロス",
  str_skill_desc_400040101 = "召喚師がエネルギーをチャージし、同時にビーコンが十字範囲内のターゲットを攻撃する",
  str_skill_name_810410092 = "暗礁の召喚",
  str_skill_desc_810410092 = "特殊なルーンを2つ設置する。一定ターン経過後、封印の石碑に変わる",
  str_skill_desc_490040103 = "スーモアが雷を起こし、戦場の複数箇所の十字エリアにダメージを与える。十字エリアの中心にいる敵は撃破される",
  str_skill_desc_490040106 = "スーモアが雷を起こし、戦場の複数箇所の十字エリアにダメージを与え、小型暗鬼を数体召喚する",
  str_skill_desc_490040108 = "スーモアは巨像をコントロールして音波攻撃を繰り出し、全域のターゲットを攻撃する。小型暗鬼は即撃破され、暗鬼1体を撃破するごとに1%のHPを回復する",
  str_skill_desc_490067201 = "スーモアは巨像をコントロールして音波攻撃を繰り出し、全域のターゲットを攻撃する。さらに戦場の特定の位置のマスを転色する",
  str_skill_desc_490067202 = "スーモアが強烈なエネルギーを放ち、全域のターゲットを攻撃し、特定の位置のマスを転色する。スーモアとの距離が離れているほど、ターゲットの被ダメージが増加する",
  str_skill_desc_490021101 = "黒蹄が戦場のランダムな位置に岩石を4つ設置する。さらにターン開始時、光霊のいた位置の近くに封印の石碑を1つ設置する",
  str_skill_desc_490021102 = "黒蹄がプレイヤーから遠ざかり、プレイヤーと隣接する位置に岩石を4つ設置する",
  str_skill_name_490310101 = "応援烈火",
  str_skill_desc_490310101 = "敵が周囲2マスの範囲内にいる時、ダメージを与え、1マスノックバックする",
  str_skill_name_490310102 = "応援召喚",
  str_skill_desc_490310102 = "敵が周囲2マス内にいない場合、ヴォイドを4体召喚する",
  str_skill_name_490310105 = "バーバラ通常攻撃",
  str_skill_desc_490310105 = "敵に近づいて攻撃を発動し、ノックバックする",
  str_skill_name_491018101 = "終音・フレア",
  str_skill_desc_491018101 = "敵が自身の周囲1マス以内にいる時、太陽フレアを引き起こし、ダメージを与える。また自身を中心に、命中した敵をノックバックする",
  str_skill_name_491018102 = "レジーナ通常攻撃",
  str_skill_desc_491018102 = "ターゲット付近に移動し、攻撃する",
  str_skill_name_491105101 = "赤眼谷の竜巻・小",
  str_skill_desc_491105101 = "周囲2マスの範囲内に敵がいる場合、敵から一定距離遠ざかって10回のダメージを与える",
  str_skill_name_491105102 = "赤眼谷の竜巻・大",
  str_skill_desc_491105102 = "敵が自身の周囲2マスの範囲外にいる場合、敵に20回のダメージを与える",
  str_skill_name_491030101 = "サメヤマ通常攻撃",
  str_skill_desc_491030101 = "敵に近づいて攻撃する",
  str_skill_name_491030102 = "赤熱の砂炎",
  str_skill_desc_491030102 = "縦、横、斜めの最大範囲に大ダメージを与える",
  str_skill_desc_490060101 = "範囲内のターゲットを自分の周囲まで引き寄せ、自分のいる位置と周囲3マスの属性を変える",
  str_skill_upgrade_desc_16017313 = "能動技強化：能動技が1回ダメージを与えるごとに、凡客の印が1スタック減少する\n装備技強化：凡客の印がクリアされた時の基礎攻撃力強化が+<color=#FFFF00>25%</color>になる\n（覚醒2で有効）",
  str_skill_upgrade_desc_16017316 = "能動技強化：極光タイム発動時、もう<color=#FFFF00>1</color>回発動できる",
  str_skill_name_3001731 = "迅速なる処断",
  str_skill_name_3061731 = "迅速なる処断",
  str_skill_name_3201731 = "迅速なる処断",
  str_skill_name_3231731 = "迅速なる処断",
  str_skill_name_3261731 = "迅速なる処断",
