  str_skill_name_3331731 = "迅速なる処断",
  str_skill_name_3361731 = "迅速なる処断",
  str_skill_desc_3001731 = "1マス選択し、その<color=#00F6FF>周囲2マス</color>からさらに1マスを選択して四角形の範囲を定め、その範囲内の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<link=\"30065\"><#FFAE07><u>吸収</u></color></link>して、範囲内の敵に<color=#00F6FF>100%</color>のダメージを与える。強化マスを1マス吸収するごとに最終ダメージ+<color=#00F6FF>50%</color>",
  str_skill_desc_3061731 = "1マス選択し、その<color=#00F6FF>周囲2マス</color>からさらに1マスを選択して四角形の範囲を定め、その範囲内の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<link=\"30065\"><#FFAE07><u>吸収</u></color></link>して、エリア内の敵に<color=#00F6FF>100%</color>のダメージを与える。強化マスを1マス吸収するごとに最終ダメージ+<color=#00F6FF>50%</color>。極光タイム発動時、もう1回発動できる",
  str_skill_desc_3201731 = "1マス選択し、その<color=#00F6FF>周囲2マス</color>からさらに1マスを選択して四角形の範囲を定め、その範囲内の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<link=\"30065\"><#FFAE07><u>吸収</u></color></link>して、範囲内の敵に<color=#00F6FF>100%</color>のダメージを与える。強化マスを1マス吸収するごとに最終ダメージ+<color=#00F6FF>50%</color>",
  str_skill_desc_3231731 = "1マス選択し、その<color=#00F6FF>周囲2マス</color>からさらに1マスを選択して四角形の範囲を定め、その範囲内の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<link=\"30065\"><#FFAE07><u>吸収</u></color></link>して、範囲内の敵に<color=#00F6FF>100%</color>のダメージを与える。強化マスを1マス吸収するごとに最終ダメージ+<color=#00F6FF>50%</color>。ダメージを1回与えるごとに、凡客の印が追加で1スタック減少する",
  str_skill_desc_3261731 = "1マス選択し、その<color=#00F6FF>周囲2マス</color>からさらに1マスを選択して四角形の範囲を定め、その範囲内の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<link=\"30065\"><#FFAE07><u>吸収</u></color></link>して、範囲内の敵に<color=#00F6FF>100%</color>のダメージを与える。強化マスを1マス吸収するごとに最終ダメージ+<color=#00F6FF>50%</color>。ダメージを1回与えるごとに、凡客の印が追加で1スタック減少する。極光タイム発動時、もう1回発動できる",
  str_skill_desc_3301731 = "1マス選択し、その<color=#00F6FF>周囲2マス</color>からさらに1マスを選択して四角形の範囲を定め、その範囲内の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<link=\"30065\"><#FFAE07><u>吸収</u></color></link>して、範囲内の敵に<color=#00F6FF>100%</color>のダメージを与える。強化マスを1マス吸収するごとに最終ダメージ+<color=#00F6FF>50%</color>。強化マスを1マス吸収するごとに、凡客の印が追加で1スタック減少する",
  str_skill_desc_3331731 = "1マス選択し、その<color=#00F6FF>周囲2マス</color>の範囲内からさらに1マスを選択して四角形の範囲を定め、その範囲内の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<link=\"30065\"><#FFAE07><u>吸収</u></color></link>して、範囲内の敵に<color=#00F6FF>100%</color>のダメージを与える。強化マスを1マス吸収するごとに最終ダメージ+<color=#00F6FF>50%</color>。ダメージを1回与える、または強化マスを1マス吸収するごとに、凡客の印が追加で1スタック減少する",
  str_skill_desc_3361731 = "1マス選択し、その<color=#00F6FF>周囲2マス</color>からさらに1マスを選択して四角形の範囲を定め、その範囲内の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<link=\"30065\"><#FFAE07><u>吸収</u></color></link>して、範囲内の敵に<color=#00F6FF>100%</color>のダメージを与える。強化マスを1マス吸収するごとに最終ダメージ+<color=#00F6FF>50%</color>。ダメージを1回与える、または強化マスを1マス吸収するごとに凡客の印が追加で1スタック減少する。極光タイム発動時、もう1回発動できる",
