  str_skill_desc_2301731 = "最も近くにいる敵と最も遠くにいる敵に<color=#00F6FF>140%</color>のダメージを与える。同一の敵に攻撃する場合、2回目のダメージは<color=#00F6FF>半減</color>する。ターゲットの足下に<color=#00F6FF>最多1マス</color>の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を設置する",
  str_skill_desc_2301732 = "最も近くにいる敵と最も遠くにいる敵に<color=#00F6FF>160%</color>のダメージを与える。同一の敵に攻撃する場合、2回目のダメージは<color=#00F6FF>半減</color>する。ターゲットの足下に<color=#00F6FF>最多1マス</color>の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を設置する",
  str_skill_desc_2301733 = "最も近くにいる敵と最も遠くにいる敵に<color=#00F6FF>180%</color>のダメージを与える。同一の敵に攻撃する場合、2回目のダメージは<color=#00F6FF>半減</color>する。ターゲットの足下に<color=#00F6FF>最多1マス</color>の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を設置する",
  str_skill_passive_name_410173 = "吸収強化",
  str_skill_passive_name_420173 = "吸収強化",
  str_skill_passive_name_423173 = "吸収強化",
  str_skill_passive_desc_410173 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果発動ごとに（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）、直ちにフィールド上のランダムの敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_420173 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果発動ごとに（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）、直ちにフィールド上のランダムな敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>のダメージを与える。戦闘開始時、凡客の印を<color=#00F6FF>33</color>スタック獲得し、強化マスが効果発動するごとに、<color=#00F6FF>1</color>スタック減少する。印がクリアされると、戦闘終了まで強化形態に変化：基礎攻撃力+<color=#00F6FF>20%</color>、通常攻撃で斜め方向に攻撃可能、装備技のダメージが<color=#00F6FF>2.5</color>倍、連鎖技が同一の敵への命中時ダメージ減少しない",
  str_skill_passive_desc_423173 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果発動ごとに（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）、直ちにフィールド上のランダムな敵<color=#00F6FF>1</color>体に<color=#00F6FF>{1}</color>のダメージを与える。戦闘開始時、凡客の印を<color=#00F6FF>33</color>スタック獲得し、強化マスが効果発動するごとに、<color=#00F6FF>1</color>スタック減少する。印がクリアされると、戦闘終了まで強化形態に変化：基礎攻撃力+<color=#00F6FF>25%</color>、通常攻撃で斜め方向に攻撃できる、装備技のダメージが<color=#00F6FF>2.5</color>倍、連鎖技が同一の敵への命中時ダメージ減少しない",
  str_skill_name_2001721 = "セロロ、リテイク！",
  str_skill_name_2001722 = "セロロ、リテイク！",
  str_skill_name_2001723 = "セロロ、リテイク！",
  str_skill_name_2061721 = "セロロ、リテイク！",
  str_skill_name_2061722 = "セロロ、リテイク！",
  str_skill_name_2061723 = "セロロ、リテイク！",
  str_skill_name_3001721 = "フレーム・イン！",
  str_skill_name_3201721 = "フレーム・イン！",
  str_skill_name_3031721 = "フレーム・イン！",
  str_skill_name_3231721 = "フレーム・イン！",
  str_skill_name_3061721 = "フレーム・イン！",
  str_skill_name_3261721 = "フレーム・イン！",
  str_skill_passive_name_410172 = "守りのレンズ",
  str_skill_passive_name_430172 = "守りのレンズ",
  str_skill_desc_2001721 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。<color=#00F6FF>撮影フレーム</color>の外にいる場合、現在の位置に<color=#00F6FF>周囲1マス</color>の範囲をもつ撮影フレームを1つ生成する",
  str_skill_desc_2001722 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。<color=#00F6FF>撮影フレーム</color>の外にいる場合、現在の位置に<color=#00F6FF>周囲1マス</color>の範囲をもつ撮影フレームを1つ生成する",
  str_skill_desc_2001723 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。<color=#00F6FF>撮影フレーム</color>の外にいる場合、現在の位置に<color=#00F6FF>菱形12マス</color>の範囲をもつ撮影フレームを1つ生成する",
  str_skill_desc_3001721 = "<link=\"30066\"><#FFAE07><u>撮影フレーム</u></color></link>の範囲内の任意の位置に瞬間移動する。フィールド上に同時に最多<color=#00F6FF>2</color>つの撮影フレームが存在できる",
  str_skill_desc_3201721 = "<link=\"30066\"><#FFAE07><u>撮影フレーム</u></color></link>の範囲内の任意の位置に瞬間移動し、その<color=#00F6FF>撮影フレーム</color>の範囲内のマスに<color=#00F6FF>{1}%</color>のダメージを与える。フィールド上に同時に最多<color=#00F6FF>2</color>つの撮影フレームが存在できる",
  str_skill_desc_3031721 = "<link=\"30067\"><#FFAE07><u>撮影フレーム</u></color></link>の範囲内の任意の位置に瞬間移動する。フィールド上に同時に最多<color=#00F6FF>3</color>つの撮影フレームが存在できる",
  str_skill_desc_3231721 = "<link=\"30067\"><#FFAE07><u>撮影フレーム</u></color></link>の範囲内の任意の位置に瞬間移動し、その<color=#00F6FF>撮影フレーム</color>の範囲内のマスに<color=#00F6FF>{1}%</color>のダメージを与える。フィールド上に同時に最多<color=#00F6FF>3</color>つの撮影フレームが存在できる",
  str_skill_desc_3061721 = "<link=\"30068\"><#FFAE07><u>撮影フレーム</u></color></link>の範囲内の任意の位置に瞬間移動する。フィールド上に同時に最多<color=#00F6FF>3</color>つの撮影フレームが存在できる",
  str_skill_desc_3261721 = "<link=\"30068\"><#FFAE07><u>撮影フレーム</u></color></link>の範囲内の任意の位置に瞬間移動し、その<color=#00F6FF>撮影フレーム</color>の範囲内のマスに<color=#00F6FF>{1}%</color>のダメージを与える。フィールド上に同時に最多<color=#00F6FF>3</color>つの撮影フレームが存在できる",
  str_skill_passive_desc_410172 = "<color=#00F6FF>撮影フレーム</color>の範囲内を1マス移動するごとに、現在のリリカの防御力の<color=#00F6FF>{1}</color>に相当するシールドを獲得する",
  str_skill_passive_desc_430172 = "<color=#00F6FF>撮影フレーム</color>の範囲内を1マス移動するごとに、現在のリリカの防御力の<color=#00F6FF>{1}</color>に相当するシールドを獲得する。ターン終了時、フィールド上のすべての<color=#00F6FF>撮影フレーム</color>の範囲に現在のシールド値と同量の確定ダメージを与える",
  str_skill_upgrade_desc_16017213 = "能動技強化：フィールド上に同時に最多<color=#00F6FF>3</color>つの撮影フレームが存在できる",
  str_skill_upgrade_desc_16017216 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる。戦闘開始時の最初の位置に<color=#00F6FF>菱形12マス</color>の範囲を持つ撮影フレームを1つ生成する",
  str_skill_name_29038011 = "ここにいたの？",
  str_skill_desc_29038011 = "エスターの周囲に光霊がいた場合、エスターがプレイヤーのいる方に方向転換し、自身の周囲菱形範囲にダメージを与え、さらにノックバックする",
  str_skill_name_29038012 = "逃げるつもり？",
  str_skill_desc_29038012 = "エスターのいる位置の十字範囲内に光霊がいた場合、エスターが方向転換してプレイヤーに向かい、目の前のユニットにダメージを与え、さらにノックバックする",
  str_skill_upgrade_desc_14016912 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_14016915 = "能動技強化：能動技が<color=#FFFF00>3</color>マスノックバックになる",
  str_skill_name_2001691 = "ブレイクビーツ",
  str_skill_name_2001692 = "ブレイクビーツ",
  str_skill_name_2001693 = "ブレイクビーツ",
  str_skill_desc_2001691 = "<color=#00F6FF>十字方向の8マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001692 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001693 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_name_300169 = "ノックアウト",
  str_skill_name_305169 = "ノックアウト",
  str_skill_name_330169 = "ノックアウト",
  str_skill_name_335169 = "ノックアウト",
  str_skill_desc_300169 = "<color=#00F6FF>隣接する十字4マス</color>内にいる敵1体に<color=#00F6FF>300%</color>のダメージを与え、2マスノックバックする。ノックバックを<color=#00F6FF>阻まれた</color>場合、追加で<color=#00F6FF>200%</color>のダメージを与え、1ターンの<color=#00F6FF>眩暈</color>状態にする",
  str_skill_desc_305169 = "<color=#00F6FF>隣接する十字4マス</color>内にいる敵1体に<color=#00F6FF>300%</color>のダメージを与え、3マスノックバックする。ノックバックを<color=#00F6FF>阻まれた</color>場合、追加で<color=#00F6FF>200%</color>のダメージを与え、1ターンの<color=#00F6FF>眩暈</color>状態にする",
  str_skill_desc_330169 = "<color=#00F6FF>隣接する十字4マス</color>内にいる敵1体に<color=#00F6FF>300%</color>のダメージを与え、2マスノックバックする。ノックバックを<color=#00F6FF>阻まれた</color>場合、追加で<color=#00F6FF>200%</color>のダメージを与え、1ターンの<color=#00F6FF>眩暈</color>状態にする。ノックバックを阻んだ障害が別の敵だった場合、その敵にもダメージを与え、眩暈状態にする",
  str_skill_desc_335169 = "<color=#00F6FF>隣接する十字4マス</color>内にいる敵1体に<color=#00F6FF>300%</color>のダメージを与え、3マスノックバックする。ノックバックを<color=#00F6FF>阻まれた</color>場合、追加で<color=#00F6FF>200%</color>のダメージを与え、1ターンの<color=#00F6FF>眩暈</color>状態にする。ノックバックを阻んだ障害が別の敵だった場合、その敵にもダメージを与え、眩暈状態にする",
  str_skill_passive_name_410169 = "バット＆バイヴス",
  str_skill_passive_name_420169 = "バット＆バイヴス",
  str_skill_passive_desc_410169 = "サディの基礎攻撃力+<color=#00F6FF>{1}</color>。サディは連鎖ごとに最多で<color=#00F6FF>3</color>回まで通常攻撃する。4回目以降の通常攻撃は<color=#00F6FF>撃墜値</color>1点の獲得に変化し、撃墜値1点につき、能動技ダメージ係数+<color=#00F6FF>{2}</color>、能動技の発動後にクリアされる",
  str_skill_passive_desc_420169 = "サディの基礎攻撃力+<color=#00F6FF>{1}</color>。サディは連鎖ごとに最多で<color=#00F6FF>3</color>回まで通常攻撃し、3回目の通常攻撃のダメージは2倍になる。4回目以降の通常攻撃は<color=#00F6FF>撃墜値</color>1点の獲得に変化し、撃墜値1点につき、能動技ダメージ係数+<color=#00F6FF>{2}</color>、能動技の発動後クリアされる",
  str_skill_desc_1601751001 = "プリズムマス",
  str_skill_desc_1601751003 = "忍刀",
  str_skill_desc_1601751004 = "空爆ビーコン",
  str_skill_desc_1601751005 = "機蜂",
  str_skill_desc_1601751006 = "アポロンの雷矢",
  str_skill_desc_1601751007 = "旗槍",
  str_skill_desc_1601751008 = "提灯",
  str_skill_desc_1601751009 = "鉄トカゲ",
  str_skill_desc_1601751010 = "濃色マス",
  str_skill_desc_160175101 = "キュービックエネルギーを<color=#00F6FF>2</color>消費して、任意の1マスを選択し、プリズムマスに変える",
  str_skill_desc_160175103 = "キュービックエネルギーを<color=#00F6FF>2</color>消費して、進入可能な忍刀のないマスを1つ選択して、そのマス上に忍刀を1個設置する",
  str_skill_desc_160175104 = "キュービックエネルギーを<color=#00F6FF>1</color>消費して、空爆ビーコンのないマスを1つ選択し、そのマス上に空爆ビーコンを1個設置する",
  str_skill_desc_160175105 = "キュービックエネルギーを<color=#00F6FF>1</color>消費して、周囲3マス内の進入可能な機蜂のないマスを1つ選択し、そのマス上に機蜂を1個設置する。機蜂は同時に最大4個までフィールドに存在できる",
  str_skill_desc_160175106 = "キュービックエネルギーを<color=#00F6FF>1</color>消費して、進入可能なアポロンの雷矢のないマスを1つ選択し、そのマス上にアポロンの雷矢を1個設置する",
  str_skill_desc_160175107 = "キュービックエネルギーを<color=#00F6FF>3</color>消費して、進入可能な旗槍のないマスを1つ選択し、そのマス上に旗槍を1個設置する。旗槍は同時に最大1個までフィールドに存在できる",
  str_skill_desc_160175108 = "キュービックエネルギーを<color=#00F6FF>4</color>消費して、進入可能な提灯のないマスを1つ選択し、そのマス上に提灯を1個設置する。提灯は同時に最大1個までフィールドに存在できる",
  str_skill_desc_160175109 = "キュービックエネルギーを<color=#00F6FF>2</color>消費して、進入可能な鉄トカゲのいないマスを1つ選択し、そのマス上に鉄トカゲを1体召喚する",
  str_skill_desc_160175110 = "キュービックエネルギーを<color=#00F6FF>2</color>消費して、任意の1マスを選択し、濃色マスに変える",
  str_skill_upgrade_desc_16017513 = "能動技強化：戦闘開始時にキュービックエネルギーを<color=#FFFF00>2</color>獲得",
  str_skill_upgrade_desc_16017516 = "能動技強化：ヒーリングボールの光霊通過時の回復係数が存在ターン数0/1/2～に応じて、<color=#FFFF00>40%/100%/250%</color>に上昇する。\n能動技で吸収した時の回復係数が<color=#FFFF00>80%/180%/400%</color>に上昇する",
  str_skill_name_30017511 = "全域偵察",
  str_skill_name_30317511 = "全域偵察",
  str_skill_name_30617511 = "全域偵察",
  str_skill_name_32017511 = "全域偵察",
  str_skill_name_32317511 = "全域偵察",
  str_skill_name_32617511 = "全域偵察",
  str_skill_name_33017511 = "全域偵察",
  str_skill_name_33317511 = "全域偵察",
  str_skill_name_33617511 = "全域偵察",
  str_skill_name_30017513 = "全域偵察",
  str_skill_desc_30017511 = "<link=\"30069\"><#FFAE07><u>キュービックエネルギー</u></color></link>を1消費する。進入可能なマスを1つ選択して<link=\"30072\"><#FFAE07><u>ヒーリングボール</u></color></link>を1個設置する。または、フィールド上に存在するヒーリングボールを選択して吸収し、その存在ターン数に応じてHPを回復する。ヒーリングボールは敵に触れると消失する",
  str_skill_desc_30317511 = "<link=\"30070\"><#FFAE07><u>キュービックエネルギー</u></color></link>を1消費する。進入可能なマスを1つ選択して<link=\"30072\"><#FFAE07><u>ヒーリングボール</u></color></link>を1個設置する。または、フィールド上に存在するヒーリングボールを選択して吸収し、その存在ターン数に応じてHPを回復する。ヒーリングボールは敵に触れると消失する",
  str_skill_desc_30617511 = "<link=\"30070\"><#FFAE07><u>キュービックエネルギー</u></color></link>を1消費する。進入可能なマスを1つ選択して<link=\"30073\"><#FFAE07><u>ヒーリングボール</u></color></link>を1個設置する。または、フィールド上に存在するヒーリングボールを選択して吸収し、その存在ターン数に応じてHPを回復する。ヒーリングボールは敵に触れると消失する",
  str_skill_desc_32017511 = "<link=\"30069\"><#FFAE07><u>キュービックエネルギー</u></color></link>を1消費する。進入可能なマスを1つ選択して<link=\"30072\"><#FFAE07><u>ヒーリングボール</u></color></link>を1個設置する。または、フィールド上に存在するヒーリングボールを選択して吸収し、その存在ターン数に応じてHPを回復する。ヒーリングボールは敵に触れると消失し、キュービックエネルギーが1返還される",
  str_skill_desc_32317511 = "<link=\"30070\"><#FFAE07><u>キュービックエネルギー</u></color></link>を1消費する。進入可能なマスを1つ選択して<link=\"30072\"><#FFAE07><u>ヒーリングボール</u></color></link>を1個設置する。または、フィールド上に存在するヒーリングボールを選択して吸収し、その存在ターン数に応じてHPを回復する。ヒーリングボールは敵に触れると消失し、キュービックエネルギーが1返還される",
  str_skill_desc_32617511 = "<link=\"30070\"><#FFAE07><u>キュービックエネルギー</u></color></link>を1消費する。進入可能なマスを1つ選択して<link=\"30073\"><#FFAE07><u>ヒーリングボール</u></color></link>を1個設置する。または、フィールド上に存在するヒーリングボールを選択して吸収し、その存在ターン数に応じてHPを回復する。ヒーリングボールは敵に触れると消失し、キュービックエネルギーが1返還される",
  str_skill_desc_33017511 = "<link=\"30069\"><#FFAE07><u>キュービックエネルギー</u></color></link>を1消費する。進入可能なマスを1つ選択して<link=\"30072\"><#FFAE07><u>ヒーリングボール</u></color></link>を1個設置する。または、フィールド上のヒーリングボールを選択して吸収し、その存在ターン数に応じてHPを回復する。ヒーリングボールは敵に触れると消失し、キュービックエネルギーが1返還される。また、<link=\"30071\"><#FFAE07><u>スキャンモジュール</u></color></link>を使用して、雷属性光霊の能動技による召喚物の一部を呼び出せる",
  str_skill_desc_33317511 = "<link=\"30070\"><#FFAE07><u>キュービックエネルギー</u></color></link>を1消費する。進入可能なマスを1つ選択して<link=\"30072\"><#FFAE07><u>ヒーリングボール</u></color></link>を1個設置する。または、フィールド上のヒーリングボールを選択して吸収し、その存在ターン数に応じてHPを回復する。ヒーリングボールは敵に触れると消失し、キュービックエネルギーが1返還される。また、<link=\"30071\"><#FFAE07><u>スキャンモジュール</u></color></link>を使用して、雷属性光霊の能動技による召喚物の一部を呼び出せる",
  str_skill_desc_33617511 = "<link=\"30070\"><#FFAE07><u>キュービックエネルギー</u></color></link>を1消費する。進入可能なマスを1つ選択して<link=\"30073\"><#FFAE07><u>ヒーリングボール</u></color></link>を1個設置する。または、フィールド上に存在するヒーリングボールを選択して吸収し、存在ターン数に応じてHPを回復する。ヒーリングボールは敵に触れると消失し、キュービックエネルギーが1返還される。また、<link=\"30071\"><#FFAE07><u>スキャンモジュール</u></color></link>を使用して、雷属性光霊の能動技による召喚物の一部を呼び出せる",
  str_skill_desc_330175111 = "<color=#D1970C><b>キュービックエネルギー</b></color>を1消費し、進入可能なマスを1つ選択してヒーリングボールを1個設置する。または、フィールド上に存在するヒーリングボールを選択して吸収し、その存在ターン数<color=#D1970C><b>0/1/2～</b></color>に応じてアクセリアの攻撃力の<color=#D1970C><b>40%/100%/200%</b></color>相当のHPを回復する。ヒーリングボールは光霊が通過した時、同様の存在ターン数に応じてアクセリアの攻撃力の<color=#D1970C><b>40%/100%/200%</b></color>相当のHPを回復する。ヒーリングボールは敵に触れると消失し、キュービックエネルギーが1返還される",
  str_skill_desc_336175111 = "<color=#D1970C><b>キュービックエネルギー</b></color>を1消費し、進入可能なマスを1つ選択してヒーリングボールを1個設置する。または、フィールド上に存在するヒーリングボールを選択して吸収し、その存在ターン数<color=#D1970C><b>0/1/2～</b></color>に応じてアクセリアの攻撃力の<color=#D1970C><b>80%/180%/400%</b></color>相当のHPを回復する。ヒーリングボールは光霊が通過した時、同様の存在ターン数に応じてアクセリアの攻撃力の<color=#D1970C><b>40%/100%/250%</b></color>相当のHPを回復する。ヒーリングボールは敵に触れると消失し、キュービックエネルギーが1返還される",
  str_skill_passive_name_4101751 = "キュービック切換",
  str_skill_passive_desc_4101751 = "チーム内の雷属性の光霊が能動技を使用した後、アクセリアは切換エネルギーを<color=#00F6FF>1</color>獲得する。連鎖技使用後にすべてクリアされ、切換エネルギー1につき、フィールド上でHPが最も高い敵に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_name_2001751 = "天工の支援",
  str_skill_name_2001752 = "天工の支援",
  str_skill_name_2001753 = "天工の支援",
  str_skill_desc_2001751 = "アクセリアの攻撃力の<color=#00F6FF>135%</color>相当のチームHPを回復する",
  str_skill_desc_2001752 = "アクセリアの攻撃力の<color=#00F6FF>160%</color>相当のチームHPを回復する",
  str_skill_desc_2001753 = "アクセリアの攻撃力の<color=#00F6FF>190%</color>相当のチームHPを回復する",
  str_skill_name_29036011 = "蝕毒",
  str_skill_desc_29036011 = "光霊がディアボラの周囲1マスの範囲内にいる場合、ターゲットに大ダメージを与え、さらに猛毒状態を付与する",
  str_skill_name_29036012 = "誘虫",
  str_skill_desc_29036012 = "光霊がディアボラから離れている時、フィールド外縁のランダムな位置にヨアケバナの精を数体召喚する",
  str_skill_name_20006091 = "強化",
  str_skill_desc_20006091 = "ディアボラの周囲1マスの範囲に近づいて憑依し、ディアボラの攻撃力を上昇させる",
  str_skill_name_200190101 = "照霊・リンク",
  str_skill_desc_200190101 = "照霊の攻撃時に光霊を通り抜けられる場合、光霊にダメージを与え、さらに鎖で光霊とつながる。通り抜けられない場合、光霊にダメージを与え、自身の移動力を上げる",
  str_skill_name_290340101 = "アスモデウス・夢魔鎖",
  str_skill_desc_290340101 = "アスモデウスが範囲内にいる光霊を攻撃する。命中時、夢魔鎖と光霊がつながれる。夢魔鎖につながれた光霊は1マス移動するごとにダメージを受ける。攻撃時、光霊がすでに夢魔鎖につながれていた場合、ダメージが上昇し、さらに吸血する",
  str_skill_name_290341101 = "アスモデウス・夢魔鎖",
  str_skill_desc_290341101 = "アスモデウスが範囲内にいる光霊を攻撃する。命中時、夢魔鎖と光霊をつなぎ、夢魔鎖が切れた時、光霊に大ダメージを与える。攻撃時、光霊がすでに夢魔鎖につながれていた場合、ダメージは上昇し、さらに吸血する",
  str_skill_name_290340102 = "アスモデウス・激化",
  str_skill_desc_290340102 = "アスモデウスが光霊を攻撃できない場合、光霊を攻撃できるようになるまで自身の移動力を上昇させる",
  str_skill_name_290340201 = "アスモデウス・焼身",
  str_skill_desc_290340201 = "アスモデウスが光霊を攻撃できる光霊から最も離れた位置に瞬間移動し、攻撃する",
  str_skill_name_2001761 = "アウストラリスの翅嵐",
  str_skill_name_2001762 = "アウストラリスの翅嵐",
  str_skill_name_2001763 = "アウストラリスの翅嵐",
