  str_skill_name_3021761 = "ボレアリスの閃撃",
  str_skill_name_3051761 = "ボレアリスの閃撃",
  str_skill_name_3201761 = "ボレアリスの閃撃",
  str_skill_name_3221761 = "ボレアリスの閃撃",
  str_skill_name_3251761 = "ボレアリスの閃撃",
  str_skill_name_3301761 = "ボレアリスの閃撃",
  str_skill_name_3321761 = "ボレアリスの閃撃",
  str_skill_name_3351761 = "ボレアリスの閃撃",
  str_skill_passive_name_4101761 = "翅針",
  str_skill_passive_name_4151761 = "翅針",
  str_skill_passive_name_4201761 = "翅針",
  str_skill_passive_name_4251761 = "翅針",
  str_skill_passive_name_4301761 = "翅針",
  str_skill_passive_name_4351761 = "翅針",
  str_skill_desc_2001761 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>60%</color>のダメージを2回ランダムに割り当てて与える。1回のダメージにつき、ターゲットに<color=#00F6FF>アウストラリスの翅針</color>を1スタック付与する。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2001762 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>80%</color>のダメージを3回ランダムに割り当てて与える。1回のダメージにつき、ターゲットに<color=#00F6FF>アウストラリスの翅針</color>を1スタック付与する。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2001763 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>100%</color>のダメージを4回ランダムに割り当てて与える。1回のダメージにつき、ターゲットに<color=#00F6FF>アウストラリスの翅針</color>を1スタック付与する。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_3001761 = "<color=#00F6FF>周囲2マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>80%</color>のダメージを与える",
  str_skill_desc_3021761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>80%</color>のダメージを与える",
  str_skill_desc_3051761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>80%～120%</color>のダメージを与える。ターゲットのHPが低いほどダメージ係数は高くなる",
  str_skill_desc_3201761 = "<color=#00F6FF>周囲2マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>80%</color>のダメージを与え、そのダメージの<color=#00F6FF>10%</color>に相当するHPを回復する",
  str_skill_desc_3221761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>80%</color>のダメージを与え、そのダメージの<color=#00F6FF>10%</color>に相当するHPを回復する",
  str_skill_desc_3251761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>80%～120%</color>のダメージを与え、そのダメージの<color=#00F6FF>10%</color>に相当するHPを回復する。ターゲットのHPが低いほどダメージ係数は高くなる",
  str_skill_desc_3301761 = "<color=#00F6FF>周囲2マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>80%</color>のダメージを与え、そのダメージの<color=#00F6FF>10%～15%</color>に相当するHPを回復する。チームのHPが低いほど回復係数は高くなる",
  str_skill_desc_3321761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>80%</color>のダメージを与え、そのダメージの<color=#00F6FF>10%～15%</color>に相当するHPを回復する。チームのHPが低いほど回復係数は高くなる",
  str_skill_desc_3351761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>80%～120%</color>のダメージを与え、そのダメージの<color=#00F6FF>10%～15%</color>に相当するHPを回復する。ターゲットのHPが低いほどダメージ係数は高くなり、チームのHPが低いほど回復係数は高くなる",
  str_skill_passive_desc_4101761 = "<color=#00F6FF>{1}</color>回ごとに、ベルタの通常攻撃がターゲットに<color=#00F6FF>アウストラリスの翅針</color>を<color=#00F6FF>1</color>スタック付与する",
  str_skill_passive_desc_4151761 = "<color=#00F6FF>{1}</color>回ごとに、ベルタの通常攻撃がターゲットに<color=#00F6FF>アウストラリスの翅針</color>を<color=#00F6FF>1</color>スタック付与する",
  str_skill_passive_desc_4201761 = "<color=#00F6FF>{1}</color>回ごとに、ベルタの通常攻撃がターゲットに<color=#00F6FF>アウストラリスの翅針</color>を<color=#00F6FF>1</color>スタック付与する",
  str_skill_passive_desc_4251761 = "<color=#00F6FF>{1}</color>回ごとに、ベルタの通常攻撃がターゲットに<color=#00F6FF>アウストラリスの翅針</color>を<color=#00F6FF>1</color>スタック付与する",
  str_skill_passive_desc_4301761 = "<color=#00F6FF>{1}</color>回ごとに、ベルタの通常攻撃がターゲットに<color=#00F6FF>アウストラリスの翅針</color>を<color=#00F6FF>1</color>スタック付与する",
  str_skill_passive_desc_4351761 = "<color=#00F6FF>{1}</color>回ごとに、ベルタの通常攻撃がターゲットに<color=#00F6FF>アウストラリスの翅針</color>を<color=#00F6FF>1</color>スタック付与する",
  str_skill_upgrade_desc_15017612 = "能動技強化：技の効果範囲を<color=#FFFF00>周囲3マス</color>に拡大する",
  str_skill_upgrade_desc_15017615 = "能動技強化：ターゲットのHPが低いほど、ダメージ係数が高くなる。ダメージ係数は最高で<color=#00F6FF>40%</color>上昇する",
  str_skill_name_290350103 = "狂蹄・砕衝",
  str_skill_desc_290350103 = "狂蹄は足下のマスを粉砕し、光霊に衝突後、さらにノックバックする。途中に岩石がある場合はそれを破壊する。衝突された光霊は疲労状態になる",
  str_skill_name_290350104 = "狂蹄・撃砕",
  str_skill_desc_290350104 = "狂蹄が移動後、目の前にある2マスを強く撃ち、大ダメージを与え、さらにマスを粉砕する",
  str_skill_desc_290350203 = "狂蹄は足下のマスを粉砕し、光霊に衝突後、さらにノックバックする。途中に岩石がある場合はそれを破壊する",
  str_skill_desc_290350204 = "狂蹄が移動後、目の前にある2マスを強く撃ち、大ダメージを与え、さらにマスを粉砕する。攻撃を受けた光霊は疲労状態になる",
  str_skill_name_216003811 = "メガショック！",
  str_skill_desc_216003811 = "幻影のガルーが縦方向1列にダメージを与える",
  str_skill_name_91001641 = "強化",
  str_skill_desc_91001641 = "自身以外のすべての暗鬼の移動力と攻撃力が増加する。効果は累積される",
  str_skill_name_290290101 = "貪蝕・衝撃破壊",
  str_skill_desc_290290101 = "隣接する位置にいる光霊を押しつぶし、防御力無視の大ダメージを与え、さらに1マスノックバックする。隣接する4マスがすべてふさがれていた場合、光霊はそのまま撃破される",
  str_skill_desc_290291131 = "隣接する位置にいる光霊を押しつぶし、瞬殺する",
  str_skill_name_290290104 = "貪蝕・裂断",
  str_skill_desc_290290104 = "隣接する位置に光霊がいない場合、光霊のいる方向に1マス移動する。その後、頭部の周囲1マス内に範囲ダメージを与える",
  str_skill_name_290290100 = "蝕虫の体躯",
  str_skill_desc_290290100 = "特殊なエネルギーに守られている蝕虫の体。あらゆる攻撃を無効化できる。また、自己複製能力が備わっている",
  str_skill_name_290290102 = "蝕虫の尾",
  str_skill_desc_290290102 = "受けたダメージを頭部に転送する",
