  str_skill_desc_3031801 = "最も近くの水属性のマス<color=#00F6FF>4</color>つを森属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3051801 = "最も近くの水属性のマス<color=#00F6FF>5</color>つを森属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_310180 = "最も近くの水属性のマス<color=#00F6FF>4</color>つを森属性に変え、ランダムで半数の敵に<color=#00F6FF>監視の印</color>を付与する",
