  str_skill_desc_3131801 = "最も近くの水属性のマス<color=#00F6FF>4</color>つを森属性に変え、ランダムで半数の敵に<color=#00F6FF>監視の印</color>を付与する。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3151801 = "最も近くの水属性のマス<color=#00F6FF>5</color>つを森属性に変え、ランダムで半数の敵に<color=#00F6FF>監視の印</color>を付与する。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_330180 = "最も近くの水属性のマス<color=#00F6FF>4</color>つを森属性に変え、ランダムで半数の敵に<color=#00F6FF>監視の印</color>を付与する。そのあと監視の印を持つ敵<color=#00F6FF>3</color>体以内の足下に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を生成する",
  str_skill_desc_333180 = "最も近くの水属性のマス<color=#00F6FF>4</color>つを森属性に変え、ランダムで半数の敵に<color=#00F6FF>監視の印</color>を付与する。そのあと監視の印を持つ敵<color=#00F6FF>3</color>体以内の足下に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を生成する。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_335180 = "最も近くの水属性のマス<color=#00F6FF>5</color>つを森属性に変え、ランダムで半数の敵に<color=#00F6FF>監視の印</color>を付与する。そのあと監視の印を持つ敵<color=#00F6FF>3</color>体以内の足下に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を生成する。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3331801 = "最も近くの水属性のマス<color=#00F6FF>4</color>つを森属性に変え、ランダムで半数の敵に<color=#00F6FF>監視の印</color>を付与する。そのあと監視の印を持つ敵<color=#00F6FF>3</color>体以内の足下に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を生成する。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3351801 = "最も近くの水属性のマス<color=#00F6FF>5</color>つを森属性に変え、ランダムで半数の敵に<color=#00F6FF>監視の印</color>を付与する。そのあと監視の印を持つ敵<color=#00F6FF>3</color>体以内の足下に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を生成する。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_2001801 = "自身から最も近くにいる<color=#00F6FF>体型が一番小さい</color>敵1体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001802 = "自身から最も近くにいる<color=#00F6FF>体型が一番小さい</color>敵1体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001803 = "自身から最も近くにいる<color=#00F6FF>体型が一番小さい</color>敵1体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2201801 = "自身から最も近くにいる<color=#00F6FF>体型が一番小さい</color>敵1体に<color=#00F6FF>{1}%</color>のダメージを与え、同時に<color=#00F6FF>監視の印</color>を付与する",
  str_skill_desc_2201802 = "自身から最も近くにいる<color=#00F6FF>体型が一番小さい</color>敵1体に<color=#00F6FF>{1}%</color>のダメージを与え、同時に<color=#00F6FF>監視の印</color>を付与する",
  str_skill_desc_2201803 = "自身から最も近くにいる<color=#00F6FF>体型が一番小さい</color>敵1体に<color=#00F6FF>{1}%</color>のダメージを与え、同時に<color=#00F6FF>監視の印</color>を付与する",
  str_skill_passive_desc_410180 = "能動技は敵に<color=#00F6FF>監視の印</color>を付与できる：狙撃型の連鎖技で受ける最終ダメージ+<color=#00F6FF>{1}</color>、光霊の行動終了まで持続する",
  str_skill_passive_desc_420180 = "能動技と連鎖技は敵に<color=#00F6FF>監視の印</color>を付与できる：狙撃型の連鎖技で受ける最終ダメージ+<color=#00F6FF>{1}</color>、光霊の行動終了まで持続する",
  str_skill_name_2001781 = "ヒット＆アウェイ",
