  str_skill_name_20017822 = "ヒット＆アウェイ",
  str_skill_name_20017832 = "ヒット＆アウェイ",
  str_skill_name_3001780 = "トライアタック",
  str_skill_desc_2001781 = "フィールド上のランダムな異なる敵3体に<color=#00F6FF>100%</color>のダメージを与える",
  str_skill_desc_2001782 = "フィールド上のランダムな異なる敵3体に<color=#00F6FF>120%</color>のダメージを与える",
  str_skill_desc_2001783 = "フィールド上のランダムな異なる敵3体に<color=#00F6FF>140%</color>のダメージを与える",
  str_skill_desc_20017812 = "フィールド上のランダムな異なる敵3体に<color=#00F6FF>100%</color>のダメージを与える。今回の連鎖が水属性のマスだった場合、召喚する珍獣たちはそれぞれのターゲット（同一ターゲットでも可）を攻撃するように切り替わる",
  str_skill_desc_20017822 = "フィールド上のランダムな異なる敵3体に<color=#00F6FF>120%</color>のダメージを与える。今回の連鎖が水属性のマスだった場合、召喚する珍獣たちはそれぞれのターゲット（同一ターゲットでも可）を攻撃するように切り替わる",
  str_skill_desc_20017832 = "フィールド上のランダムな異なる敵3体に<color=#00F6FF>140%</color>のダメージを与える。今回の連鎖が水属性のマスだった場合、召喚する珍獣たちはそれぞれのターゲット（同一ターゲットでも可）を攻撃するように切り替わる",
  str_skill_desc_3001780 = "3体の珍獣を召喚し、優先的にそれぞれのターゲットに<color=#00F6FF>200%</color>のダメージを与える\nモジャ：状態異常の印が最も多い敵\nビッカー：HPが最も低い敵\nアリガタモドキドリ：最も遠くにいる敵",
  str_skill_passive_name_410178 = "サーチ＆チェイス",
  str_skill_passive_name_420178 = "サーチ＆チェイス",
  str_skill_passive_name_430178 = "サーチ＆チェイス",
  str_skill_passive_name_436178 = "サーチ＆チェイス",
  str_skill_passive_desc_410178 = "今回の連鎖が水属性のマスだった場合、通常攻撃の効果が変わり、1マス移動するごとに、珍獣たちがそれぞれのターゲットに<color=#00F6FF>{1}</color>ダメージの攻撃を1回行う\n珍獣たちの与える全ダメージは連鎖によるボーナスを受けない",
  str_skill_passive_desc_420178 = "今回の連鎖が水属性のマスだった場合、通常攻撃の効果が変わり、1マス移動するごとに、珍獣たちがそれぞれのターゲットに<color=#00F6FF>{1}</color>ダメージの攻撃を1回行う\n珍獣たちの与える全ダメージは連鎖によるボーナスを受けない",
  str_skill_passive_desc_430178 = "今回の連鎖が水属性のマスだった場合、通常攻撃の効果が変わり、1マス移動するごとに、珍獣たちがそれぞれのターゲットに<color=#00F6FF>{1}</color>ダメージの攻撃を1回行う\n珍獣たちの与える全ダメージは連鎖によるボーナスを受けず、ターゲットが対応する条件を満たすと、最終ダメージ+<color=#00F6FF>10%</color>\nモジャ：状態異常の印が<color=#00F6FF>4</color>個以上\nビッカー：現在のHPが<color=#00F6FF>30%</color>未満\nアリガタモドキドリ：距離が<color=#00F6FF>4</color>マス以上",
  str_skill_passive_desc_436178 = "今回の連鎖が水属性のマスだった場合、通常攻撃の効果が変わり、1マス移動するごとに、珍獣たちがそれぞれのターゲットに<color=#00F6FF>{1}</color>ダメージの攻撃を1回行う\n珍獣たちの与える全ダメージは連鎖によるボーナスを受けず、ターゲットが対応する条件を満たすと、最終ダメージ+<color=#00F6FF>30%</color>\nモジャ：状態異常の印が<color=#00F6FF>4</color>個以上\nビッカー：現在のHPが<color=#00F6FF>30%</color>未満\nアリガタモドキドリ：距離が<color=#00F6FF>4</color>マス以上",
  str_skill_upgrade_desc_16017813 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16017816 = "装備技強化：ターゲットが対応する条件を満たすと、珍獣たちの全最終ダメージ+<color=#00F6FF>30%</color>（覚醒3で有効）",
