  str_skill_name_3361771 = "トーンチェンジ",
  str_skill_passive_name_410177 = "ヘブンズメロデイ",
  str_skill_desc_2001771 = "<color=#00F6FF>アイドルモード（5連鎖）</color>：ゴルディの攻撃力×<color=#00F6FF>140%</color>相当のチームHPを回復する\n<color=#00F6FF>バトルソングモード（7連鎖）</color>：敵<color=#00F6FF>全体</color>に<color=#00F6FF>120%</color>のダメージを与える",
  str_skill_desc_2001772 = "<color=#00F6FF>アイドルモード（9連鎖）</color>：ゴルディの攻撃力×<color=#00F6FF>170%</color>相当のチームHPを回復する\n<color=#00F6FF>バトルソングモード（11連鎖）</color>：敵<color=#00F6FF>全体</color>に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_2001773 = "<color=#00F6FF>アイドルモード（13連鎖）</color>：ゴルディの攻撃力×<color=#00F6FF>210%</color>相当のチームHPを回復する\n<color=#00F6FF>バトルソングモード（15連鎖）</color>：敵<color=#00F6FF>全体</color>に<color=#00F6FF>180%</color>のダメージを与える",
  str_skill_desc_2201771 = "<color=#00F6FF>アイドルモード（5連鎖）</color>：ゴルディの攻撃力×<color=#00F6FF>140%</color>相当のチームHPを回復する。さらに<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>1マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>にする\n<color=#00F6FF>バトルソングモード（7連鎖）</color>：敵<color=#00F6FF>全体</color>に<color=#00F6FF>120%</color>のダメージを与える",
  str_skill_desc_2201772 = "<color=#00F6FF>アイドルモード（9連鎖）</color>：ゴルディの攻撃力×<color=#00F6FF>170%</color>相当のチームHPを回復する。さらに<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>2マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>にする\n<color=#00F6FF>バトルソングモード（11連鎖）</color>：敵<color=#00F6FF>全体</color>に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_2201773 = "<color=#00F6FF>アイドルモード（13連鎖）</color>：ゴルディの攻撃力×<color=#00F6FF>210%</color>相当のチームHPを回復する。さらに<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>3マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>にする\n<color=#00F6FF>バトルソングモード（15連鎖）</color>：敵<color=#00F6FF>全体</color>に<color=#00F6FF>180%</color>のダメージを与える",
  str_skill_desc_300177 = "このターン中、<color=#00F6FF>アイドルモード</color>から<color=#00F6FF>バトルソングモード</color>に変化し、<color=#00F6FF>次の連鎖</color>中は敵のいるマスを通過できる\n<color=#00F6FF>アイドルモード</color>：通常攻撃せず、連鎖技はHPを回復する\n<color=#00F6FF>バトルソングモード</color>：通常攻撃を行い、連鎖技は<color=#00F6FF>すべての敵</color>にダメージを与えられるが、発動に必要な連鎖数+2",
  str_skill_desc_303177 = "<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>2マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に転色する。このターン中、<color=#00F6FF>アイドルモード</color>から<color=#00F6FF>バトルソングモード</color>に変化し、<color=#00F6FF>次の連鎖</color>中は敵のいるマスを通過できる\n<color=#00F6FF>アイドルモード</color>：通常攻撃せず、連鎖技はHPを回復する\n<color=#00F6FF>バトルソングモード</color>：通常攻撃を行い、連鎖技は<color=#00F6FF>すべての敵</color>にダメージを与えられるが、発動に必要な連鎖数+2",
  str_skill_desc_306177 = "<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>2マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に転色する。このターン中、<color=#00F6FF>アイドルモード</color>から<color=#00F6FF>バトルソングモード</color>に変化し、<color=#00F6FF>次の連鎖</color>中は敵のいるマスを通過できる。前のターンに能動技が使用可能だった場合、上記効果が極光タイムでも有効となる\n<color=#00F6FF>アイドルモード</color>：通常攻撃せず、連鎖技はHPを回復する\n<color=#00F6FF>バトルソングモード</color>：通常攻撃を行い、連鎖技は<color=#00F6FF>すべての敵</color>にダメージを与えられるが、発動に必要な連鎖数+2",
  str_skill_desc_3061771 = "<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>2マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に転色する。このターン中、<color=#00F6FF>アイドルモード</color>から<color=#00F6FF>バトルソングモード</color>に変化し、<color=#00F6FF>次の連鎖</color>中は敵のいるマスを通過できる。前のターンに能動技が使用可能だった場合、上記効果が極光タイムでも有効となる\n<color=#00F6FF>アイドルモード</color>：通常攻撃せず、連鎖技はHPを回復する\n<color=#00F6FF>バトルソングモード</color>：通常攻撃を行い、連鎖技は<color=#00F6FF>すべての敵</color>にダメージを与えられるが、発動に必要な連鎖数+2",
  str_skill_desc_330177 = "このターン中、<color=#00F6FF>アイドルモード</color>から<color=#00F6FF>バトルソングモード</color>に変化し、<color=#00F6FF>次の連鎖</color>中は敵のいるマスを通過できる。さらにすべての強化マスが一時的に万色マスと見なされる\n<color=#00F6FF>アイドルモード</color>：通常攻撃せず、連鎖技はHPを回復する\n<color=#00F6FF>バトルソングモード</color>：通常攻撃を行い、連鎖技は<color=#00F6FF>すべての敵</color>にダメージを与えられるが、発動に必要な連鎖数+2",
  str_skill_desc_333177 = "<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>2マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に転色する。このターン中、<color=#00F6FF>アイドルモード</color>から<color=#00F6FF>バトルソングモード</color>に変化し、<color=#00F6FF>次の連鎖</color>中は敵のいるマスを通過できる。さらにすべての強化マスが一時的に万色マスと見なされる\n<color=#00F6FF>アイドルモード</color>：通常攻撃せず、連鎖技はHPを回復する\n<color=#00F6FF>バトルソングモード</color>：通常攻撃を行い、連鎖技は<color=#00F6FF>すべての敵</color>にダメージを与えられるが、発動に必要な連鎖数+2",
  str_skill_desc_336177 = "<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>2マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に転色する。このターン中、<color=#00F6FF>アイドルモード</color>から<color=#00F6FF>バトルソングモード</color>に変化し、<color=#00F6FF>次の連鎖</color>中は敵のいるマスを通過できる。さらにすべての強化マスが一時的に万色マスと見なされる。前のターンに能動技が使用可能だった場合、上記効果が極光タイムでも有効となる\n<color=#00F6FF>アイドルモード</color>：通常攻撃せず、連鎖技はHPを回復する\n<color=#00F6FF>バトルソングモード</color>：通常攻撃を行い、連鎖技は<color=#00F6FF>すべての敵</color>にダメージを与えられるが、発動に必要な連鎖数+2",
  str_skill_desc_3361771 = "<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>2マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に転色する。このターン中、<color=#00F6FF>アイドルモード</color>から<color=#00F6FF>バトルソングモード</color>に変化し、<color=#00F6FF>次の連鎖</color>中は敵のいるマスを通過できる。さらにすべての強化マスが一時的に万色マスと見なされる。前のターンに能動技が使用可能だった場合、上記効果が極光タイムでも有効となる\n<color=#00F6FF>アイドルモード</color>：通常攻撃せず、連鎖技はHPを回復する\n<color=#00F6FF>バトルソングモード</color>：通常攻撃を行い、連鎖技は<color=#00F6FF>すべての敵</color>にダメージを与えられるが、発動に必要な連鎖数+2",
  str_skill_passive_desc_410177 = "チームが<link=\"20001\"><#FFAE07><u>強化マス</u></color></link><color=#00F6FF>{1}</color>個を獲得（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）するごとに、最も近くの<color=#00F6FF>森属性以外</color>の1マスを強化マスにする",
  str_skill_upgrade_desc_16017713 = "能動技強化：能動技が<color=#FFFF00>先制攻撃</color>に変わり、戦闘開始後ただちに使用可能となる。<color=#00F6FF>森属性以外</color>のランダムな<color=#00F6FF>2マス</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>にする",
  str_skill_upgrade_desc_16017716 = "能動技強化：スキルのCD<color=#FFFF00>-1</color>。前のターンに能動技が使用可能になっており、なおかつバトルソングモードの場合、<color=#00F6FF>極光タイム</color>でも敵のいるすべてのマスを連鎖で通過でき、さらに<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を万色マスと見なす（覚醒3で有効）",
  str_skill_desc_290420101 = "光霊に向かって移動した後、前足を振り回して前方2マス以内の敵にダメージを与える",
  str_skill_desc_290420102 = "全範囲のターゲットにダメージを与える",
  str_skill_name_200200101 = "毒の膜球",
  str_skill_desc_200200101 = "膜の球を吐いて範囲内のターゲットにダメージを与える。膜の球は十字方向4マスに飛散し、飛散範囲内にいる敵味方を毒状態にする",
  str_skill_name_200210001 = "幽刹・襲刺",
  str_skill_desc_200210001 = "幽泥のカウントダウン終了後、その中に隠れていた幽刹が姿を現して光霊を攻撃する。その後、再び幽泥の中に潜る",
  str_skill_name_200210101 = "幽刹・襲刺",
  str_skill_desc_200210101 = "幽泥のカウントダウン終了後、その中に隠れていた幽刹が姿を現して光霊を攻撃する。その後、再び幽泥の中に潜る",
  str_skill_name_200210102 = "幽刹・襲刺",
  str_skill_desc_200210102 = "幽泥のカウントダウン終了後、その中に隠れていた幽刹が姿を現して光霊を攻撃する。その後、再び幽泥の中に潜る",
  str_skill_name_290400101 = "ベンヌ・力撃",
  str_skill_desc_290400101 = "ベンヌガーディアンが武器を振り回して範囲内のターゲットにダメージを与える",
  str_skill_name_290400102 = "ベンヌ・躍轟",
  str_skill_desc_290400102 = "ベンヌガーディアンがターゲットに向かって跳躍し、着地時にハンマーを地面に振り下ろして周囲1マスのターゲットに大ダメージを与える",
  str_skill_name_290400103 = "ベンヌ・恐爆",
  str_skill_desc_290400103 = "怒り狂ったベンヌガーディアンが強力な技を放ち、全範囲のターゲットにダメージを与える",
  str_skill_name_5220012 = "回復ゾル",
  str_skill_desc_5220012 = "チームの最大HPの<color=#00F6FF>20%</color>を回復する",
  str_skill_name_5220013 = "軌跡分儀",
  str_skill_desc_5220013 = "装置を起動すると、フィールド上の進入可能なマスに転送される",
  str_skill_name_290430101 = "禁衛・風凜",
  str_skill_desc_290430101 = "禁衛座が連鎖時に自身の属性とその場にいるもう1人のエピック光霊の属性の計2属性のマスを通じて移動し、ターゲットに近づいて8方向に通常攻撃を行う。連鎖終了後、周囲1マスにダメージを与える",
  str_skill_name_290440101 = "鎮魂・聖槍",
  str_skill_desc_290440101 = "鎮魂座が連鎖時に自身の属性とその場にいるもう1人のエピック光霊の属性の計2属性のマスを通じて移動し、ターゲットに近づいて4方向に通常攻撃を行う。連鎖終了後、周囲1マスにダメージを与える。通常攻撃3回ごとに、追加でターゲットの最大HPを基準とした割合ダメージを与える",
  str_skill_name_290450101 = "焚霜・隕絶",
  str_skill_desc_290450101 = "焚霜座が連鎖時に自身の属性とその場にいるもう1人のエピック光霊の属性の計2属性のマスを通じて離れたターゲットの位置に向かって移動する。移動終了後、全範囲内のターゲットにダメージを与える",
  str_skill_name_290460101 = "童謡・峻険",
  str_skill_desc_290460101 = "童謡座が連鎖時に自身の属性とその場にいるもう1人のエピック光霊の属性の計2属性のマスを通じて離れたターゲットの位置に向かって移動する。移動終了後、全範囲内のターゲットにダメージを与える",
  str_skill_name_2801101 = "指揮の印",
  str_skill_desc_2801101 = "光霊が通過すると回収され、隊長変更回数が増える",
  str_skill_name_5000881 = "ブレード",
  str_skill_desc_5000881 = "光霊が通過すると回収され、光霊の攻撃力が上昇する",
  str_skill_name_5000891 = "シールド",
  str_skill_desc_5000891 = "光霊が通過すると回収され、光霊の防御力が上昇する",
  str_skill_name_2002101 = "剣バフ",
  str_skill_desc_2002101 = "拾うと沈黙状態になるが、攻撃力が大幅にアップする",
  str_skill_desc_2002201 = "拾うと連鎖技ダメージ+8%",
  str_skill_upgrade_desc_15018312 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15018315 = "能動技強化：効果の繰り返し発動回数が<color=#00F6FF>2～5回</color>になる（覚醒3で有効）",
  str_skill_name_3001831 = "薬毒同源",
  str_skill_name_3051831 = "薬毒同源",
  str_skill_name_3201831 = "薬毒同源",
  str_skill_name_3251831 = "薬毒同源",
  str_skill_desc_3001831 = "任意の敵1体を選択し、敵ターン開始前のその敵のHPを<color=#00F6FF>強制的に1を下回らないようにする</color>。ターゲットの敵にはランダムで次のうち1つの効果が付与される：味方の与える<color=#00F6FF>通常攻撃/連鎖技/能動技</color>の最終ダメージ+<color=#00F6FF>5%/5%/7%</color>",
  str_skill_desc_3201831 = "任意の敵1体を選択し、敵ターン開始前のその敵のHPを<color=#00F6FF>強制的に1を下回らないようにする</color>。ターゲットの敵にはランダムで次のうち1つの効果が付与される：味方の与える<color=#00F6FF>通常攻撃/連鎖技/能動技</color>の最終ダメージ+<color=#00F6FF>5%/5%/7%</color>。この効果は<color=#00F6FF>1~3回</color>繰り返し発動する",
  str_skill_desc_3251831 = "任意の敵1体を選択し、敵ターン開始前のその敵のHPを<color=#00F6FF>強制的に1を下回らないようにする</color>。ターゲットの敵にはランダムで次のうち1つの効果が付与される：味方の与える<color=#00F6FF>通常攻撃/連鎖技/能動技</color>の最終ダメージ+<color=#00F6FF>5%/5%/7%</color>。この効果は<color=#00F6FF>2～5回</color>繰り返し発動する",
  str_skill_name_2001831 = "万応散",
  str_skill_name_2001832 = "万応散",
  str_skill_name_2001833 = "万応散",
  str_skill_desc_2001831 = "リンセイの攻撃力の<color=#00F6FF>155%</color>相当のチームHPを回復する",
  str_skill_desc_2001832 = "リンセイの攻撃力の<color=#00F6FF>190%</color>相当のチームHPを回復する",
  str_skill_desc_2001833 = "リンセイの攻撃力の<color=#00F6FF>225%</color>相当のチームHPを回復する",
  str_skill_passive_desc_410183 = "リンセイの通常攻撃が直接ダメージを与えなくなり、ターゲットに砂灸を1スタック付与する効果に変わる。砂灸はターン終了時に爆発し、1スタックにつき<color=#00F6FF>{1}</color>のダメージを与える。砂灸は<color=#00F6FF>2ターン</color>持続し、かつスタックごとに独立して計算される",
  str_skill_passive_desc_430183 = "リンセイの通常攻撃が直接ダメージを与えなくなり、ターゲットに砂灸を1スタック付与する効果に変わる。砂灸はターン終了時に爆発し、1スタックにつき<color=#00F6FF>{1}</color>のダメージを与え、さらにターゲットに付与された砂灸の全スタックの最終ダメージ+<color=#00F6FF>3%</color>。砂灸は<color=#00F6FF>2ターン</color>持続し、かつスタックごとに独立して計算される",
  str_skill_passive_name_410183 = "滅砂灸",
  str_skill_passive_name_430183 = "滅砂灸",
  str_skill_name_2001821 = "天下洗流",
