  str_skill_name_2361823 = "天下洗流",
  str_skill_name_2361824 = "天下洗流",
  str_skill_name_3001821 = "蛟龍巻渦",
  str_skill_name_3101821 = "蛟龍巻渦",
  str_skill_name_3201821 = "蛟龍巻渦",
  str_skill_desc_2001821 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001822 = "1つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は1つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>180%</color>のダメージを与える",
  str_skill_desc_2001823 = "2つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は2つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>180%</color>のダメージを与える",
  str_skill_desc_2001824 = "3つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は3つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>縦、横、斜めの17マス</color>に<color=#00F6FF>180%</color>のダメージを与える",
  str_skill_desc_2031821 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える。極光タイムの発動中、発動条件は<color=#00F6FF>0</color>マスになる",
  str_skill_desc_2031822 = "1つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は1つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、発動条件が<color=#00F6FF>0</color>マスになる",
  str_skill_desc_2031823 = "2つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は2つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、発動条件が<color=#00F6FF>3</color>マスになる",
  str_skill_desc_2031824 = "3つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は3つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>縦、横、斜めの17マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、発動条件が<color=#00F6FF>7</color>マスになる",
  str_skill_desc_2061821 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える。極光タイムの発動中、発動条件は<color=#00F6FF>0</color>マスになる",
  str_skill_desc_2061822 = "1つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は1つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、発動条件が<color=#00F6FF>0</color>マスになる",
  str_skill_desc_2061823 = "2つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は2つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>縦、横、斜めの17マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、発動条件が<color=#00F6FF>3</color>マスになる",
  str_skill_desc_2061824 = "3つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は3つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>正方形25マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、発動条件が<color=#00F6FF>7</color>マスになる",
  str_skill_desc_2301821 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2301822 = "1つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は1つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、跳躍範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_2301823 = "2つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は2つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、跳躍範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_2301824 = "3つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は3つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>縦、横、斜めの17マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、跳躍範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_2331821 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える。極光タイムの発動中、発動条件は<color=#00F6FF>0</color>マスになる",
  str_skill_desc_2331822 = "1つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は1つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、跳躍範囲が<color=#00F6FF>周囲2マス</color>になり、発動条件が<color=#00F6FF>0</color>マスになる",
  str_skill_desc_2331823 = "2つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は2つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、跳躍範囲が<color=#00F6FF>周囲2マス</color>になり、発動条件が<color=#00F6FF>3</color>マスになる",
  str_skill_desc_2331824 = "3つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は3つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>縦、横、斜めの17マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、跳躍範囲が<color=#00F6FF>周囲2マス</color>になり、発動条件が<color=#00F6FF>7</color>マスになる",
  str_skill_desc_2361821 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える。極光タイムの発動中、発動条件は<color=#00F6FF>0</color>マスになる",
  str_skill_desc_2361822 = "1つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は1つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近く、HPが最も高い敵に跳躍し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、跳躍範囲が<color=#00F6FF>周囲2マス</color>になり、発動条件が<color=#00F6FF>0</color>マスになる",
  str_skill_desc_2361823 = "2つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は2つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近く、HPが最も高い敵に跳躍し、<color=#00F6FF>縦、横、斜めの17マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、跳躍範囲が<color=#00F6FF>周囲2マス</color>になり、発動条件が<color=#00F6FF>3</color>マスになる",
  str_skill_desc_2361824 = "3つ目の「浄龍輝」が点灯している場合、<color=#00F6FF>1段階下</color>の連鎖技の発動判定を行う。そうでない場合は3つ目の「浄龍輝」を点灯し、<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近く、HPが最も高い敵に跳躍し、<color=#00F6FF>正方形25マス</color>に<color=#00F6FF>180%</color>のダメージを与える。極光タイムの発動中、跳躍範囲が<color=#00F6FF>周囲2マス</color>になり、発動条件が<color=#00F6FF>7</color>マスになる",
  str_skill_desc_3001821 = "<color=#00F6FF>3</color>つの<link=\"30074\"><#FFAE07><u>「浄龍輝」</u></color></link>が点灯時、能動技が発動可能になる。1マス選択し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>300%</color>のダメージを与える。発動後、すべての「浄龍輝」が消灯する",
  str_skill_desc_3101821 = "<color=#00F6FF>3</color>つの<link=\"30074\"><#FFAE07><u>「浄龍輝」</u></color></link>が点灯時、能動技が発動可能になる。1マス選択し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>300%</color>のダメージを与える。発動後、すべての「浄龍輝」が消灯する",
  str_skill_desc_3201821 = "<color=#00F6FF>3</color>つの<link=\"30074\"><#FFAE07><u>「浄龍輝」</u></color></link>が点灯時、能動技が発動可能になる。1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>300%</color>のダメージを与える。発動後にすべての「浄龍輝」が消灯する",
  str_skill_passive_name_410182 = "遺月残光",
  str_skill_passive_name_413182 = "遺月残光",
  str_skill_passive_name_423182 = "遺月残光",
  str_skill_passive_name_430182 = "遺月残光",
  str_skill_passive_name_433182 = "遺月残光",
  str_skill_passive_desc_410182 = "能動技発動時、敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_413182 = "能動技発動時、敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_423182 = "能動技発動時、敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_430182 = "能動技発動時、敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_433182 = "能動技発動時、敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_upgrade_desc_16018213 = "連鎖技強化：極光タイムの発動中、連鎖発動条件<color=#00F6FF>-6</color>",
  str_skill_upgrade_desc_16018216 = "連鎖技強化：<color=#00F6FF>2|3|4</color>段階目の連鎖技ダメージ範囲が<color=#00F6FF>菱形13マス|縦、横、斜めの17マス|正方形25マス</color>に拡大する",
  str_skill_name_29041011 = "囲",
  str_skill_desc_29041011 = "イヨウが強大な幻術を発動し、光霊を幻術で作った空間に引き入れる。\nこの状態の間、軌道が固定された攻撃がいくつかフィールド上に飛び、当たると大ダメージを与える。\nまた、プレイヤーは5回任意の移動が可能だが、1回に移動できるのは1マスのみ",
  str_skill_name_29041012 = "束",
  str_skill_desc_29041012 = "フィールド上に弾丸が存在している時、イヨウはすべての弾丸をコントロールして光霊に向けて飛ばし、ダメージを与えることができる。\nフィールド上に弾丸が存在していない時、イヨウは分身を出して、その中に身を隠す。ダメージを受けた時に本物か分身かが分かる",
  str_skill_name_29041013 = "まことの虚像",
  str_skill_desc_29041013 = "フィールド上に弾丸が存在している時、イヨウはすべての弾丸をコントロールして光霊に向けて飛ばし、ダメージを与えることができる。\nフィールド上に弾丸が存在していない時、イヨウは分身を出して、その中に身を隠す。ダメージを受けた時に本物か分身かが分かる",
  str_skill_name_29041014 = "言",
  str_skill_desc_29041014 = "移動後、イヨウとその分身が前方の直線範囲内のターゲットにダメージを与える。その後、元の位置に弾丸を1つ残す",
  str_skill_name_29041015 = "散",
  str_skill_desc_29041015 = "イヨウとその分身が全範囲内のターゲットにダメージを与える",
  str_skill_name_20022013 = "突進攻撃",
  str_skill_desc_20022013 = "「文」が前方の警戒範囲内のターゲットに大ダメージを与える",
  str_skill_name_20022022 = "束",
  str_skill_desc_20022022 = "幻境状態にない時、イヨウは「字」を弾丸にして、光霊に直接命中させる（光霊はこの状態の時、弾丸を消滅させ、ダメージを回避することができる）。",
  str_skill_name_490310106 = "罪業・スイートキッス",
  str_skill_desc_490310106 = "罪業・バーバラが一部安全エリア以外の広範囲にダメージを与え、さらに安全エリア以外の火属性のマスを粉砕する",
  str_skill_name_490310107 = "罪業・終音・フレアの印",
  str_skill_desc_490310107 = "罪業・バーバラがフィールド中心に仲間を召喚し、全範囲のターゲットにダメージを与え、ノックバックする",
  str_skill_desc_490023202 = "フェニィがエネルギーを使って、攻撃範囲内のターゲットに遠距離攻撃を行う。命中した場合、ターゲットは疲労状態になる",
  str_skill_desc_490023212 = "フェニィがエネルギーを使って、攻撃範囲内のターゲットに遠距離攻撃を行う。命中した場合、ターゲットは盲目状態になる",
  str_skill_desc_480043414 = "マラゾールが複数の爆裂をフィールドに召喚する。爆裂の数はマラゾールが初回ウェーブで累積した「爆裂移動」のスタック数によって決まる",
  str_skill_desc_400012401 = "毎ターン爆裂がフィールドに召喚される",
  str_skill_upgrade_desc_16018113 = "装備技強化：戦闘開始時に洞察点を5獲得、各ウェーブ開始時に洞察点を<color=#00F6FF>5</color>獲得",
  str_skill_upgrade_desc_16018116 = "装備技強化：洞察点の獲得条件が「シュウが<color=#00F6FF>任意の属性のマス</color>を通過する」に変わる",
  str_skill_name_2001811 = "無情烈火",
  str_skill_name_2001812 = "無情烈火",
  str_skill_name_2001813 = "無情烈火",
