  str_skill_desc_2001812 = "<color=#00F6FF>周囲3マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001813 = "<color=#00F6FF>周囲4マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_name_3001811 = "熾焔断灰",
