  str_skill_name_330181122 = "戦策天眼",
  str_skill_name_330181123 = "戦策天眼",
  str_skill_desc_3001811 = "<color=#00F6FF>1</color>マス選択して火印を設置し、さらに火属性のマスに変える。火印は敵の足下に設置することができ、その敵と共に移動する。<color=#00F6FF>連鎖移動前</color>、火印の通過したすべてのマスが<color=#00F6FF>火属性に変わる</color>。敵に付与された火印はチームの<color=#00F6FF>連鎖移動後</color>消失する",
  str_skill_desc_30018112 = "洞察点を8消費して、ボス以外の敵1体を1マス強制移動させる。1ターン内に発動は1回まで",
  str_skill_desc_300181121 = "洞察点を7消費して、ボス以外の敵1体を1マス強制移動させる。1ターン内に発動は1回まで",
  str_skill_desc_300181122 = "洞察点を6消費して、ボス以外の敵1体を1マス強制移動させる。1ターン内に発動は1回まで",
  str_skill_desc_300181123 = "洞察点を5消費して、ボス以外の敵1体を1マス強制移動させる。1ターン内に発動は1回まで",
  str_skill_desc_32018112 = "洞察点を8消費して、ボス以外の敵1体を1マス強制移動させる。1ターン内に複数回発動する場合、洞察点の消費量が<color=#00F6FF>8</color>ずつ増加する",
  str_skill_desc_320181121 = "洞察点を7消費して、ボス以外の敵1体を1マス強制移動させる。1ターン内に複数回発動する場合、洞察点の消費量が<color=#00F6FF>7</color>ずつ増加する",
  str_skill_desc_320181122 = "洞察点を6消費して、ボス以外の敵1体を1マス強制移動させる。1ターン内に複数回発動する場合、洞察点の消費量が<color=#00F6FF>6</color>ずつ増加する",
  str_skill_desc_320181123 = "洞察点を5消費して、ボス以外の敵1体を1マス強制移動させる。1ターン内に複数回発動する場合、洞察点の消費量が<color=#00F6FF>5</color>ずつ増加する",
  str_skill_desc_33018112 = "洞察点を8消費して、ボス以外の敵1体を1マス強制移動させる。または洞察点を8消費して、火印を1マス移動させる。1ターン内に複数回発動する場合、<color=#00F6FF>敵/火印</color>を移動する時の洞察点の消費量が<color=#00F6FF>8/8</color>ずつ増加する",
  str_skill_desc_330181121 = "洞察点を7消費して、ボス以外の敵1体を1マス強制移動させる。または洞察点を8消費して、火印を1マス移動させる。1ターン内に複数回発動する場合、<color=#00F6FF>敵/火印</color>を移動する時の洞察点の消費量が<color=#00F6FF>7/8</color>ずつ増加する",
  str_skill_desc_330181122 = "洞察点を6消費して、ボス以外の敵1体を1マス強制移動させる。または洞察点を8消費して、火印を1マス移動させる。1ターン内に複数回発動する場合、<color=#00F6FF>敵/火印</color>を移動する時の洞察点の消費量が<color=#00F6FF>6/8</color>ずつ増加する",
  str_skill_desc_330181123 = "洞察点を5消費して、ボス以外の敵1体を1マス強制移動させる。または洞察点を8消費して、火印を1マス移動させる。1ターン内に複数回発動する場合、<color=#00F6FF>敵/火印</color>を移動する時の洞察点の消費量が<color=#00F6FF>5/8</color>ずつ増加する",
