  str_skill_passive_desc_410181 = "新しい能動技を獲得する：<link=\"30075\"><#FFAE07><u>洞察点</u></color></link>を<color=#00F6FF>{1}</color>消費して、<color=#00F6FF>ボス以外の敵</color>1体を1マス強制移動させる。1ターン内に発動は1回まで。シュウが<color=#00F6FF>火属性のマス</color>を1つ通過するたびに洞察点を1獲得する",
  str_skill_passive_desc_413181 = "新しい能動技を獲得する：<link=\"30076\"><#FFAE07><u>洞察点</u></color></link>を<color=#00F6FF>{1}</color>消費して、<color=#00F6FF>ボス以外の敵</color>1体を1マス強制移動させる。1ターン内に発動は1回まで。シュウが<color=#00F6FF>火属性のマス</color>を1つ通過するたびに洞察点を1獲得する",
  str_skill_passive_desc_416181 = "新しい能動技を獲得する：<link=\"30077\"><#FFAE07><u>洞察点</u></color></link>を<color=#00F6FF>{1}</color>消費して、<color=#00F6FF>ボス以外の敵</color>1体を1マス強制移動させる。1ターン内に発動は1回まで。シュウが<color=#00F6FF>\nマス</color>を1つ通過するたびに洞察点を1獲得する",
  str_skill_passive_desc_420181 = "新しい能動技を獲得する：<link=\"30075\"><#FFAE07><u>洞察点</u></color></link>を<color=#00F6FF>{1}</color>消費して、<color=#00F6FF>ボス以外の敵</color>1体を1マス強制移動させる。1ターン内に複数回発動する場合、洞察点の消費量が<color=#00F6FF>{1}</color>ずつ増加する。シュウが<color=#00F6FF>火属性のマス</color>を1つ通過するたびに洞察点を1獲得する",
  str_skill_passive_desc_423181 = "新しい能動技を獲得する：<link=\"30076\"><#FFAE07><u>洞察点</u></color></link>を<color=#00F6FF>{1}</color>消費して、<color=#00F6FF>ボス以外の敵</color>1体を1マス強制移動させる。1ターン内に複数回発動する場合、洞察点の消費量が<color=#00F6FF>{1}</color>ずつ増加する。シュウが<color=#00F6FF>火属性のマス</color>を1つ通過するたびに洞察点を1獲得する",
  str_skill_passive_desc_426181 = "新しい能動技を獲得する：<link=\"30077\"><#FFAE07><u>洞察点</u></color></link>を<color=#00F6FF>{1}</color>消費して、<color=#00F6FF>ボス以外の敵</color>1体を1マス強制移動させる。1ターン内に複数回発動する場合、洞察点の消費量が<color=#00F6FF>{1}</color>ずつ増加する。シュウが<color=#00F6FF>マス</color>を1つ通過するたびに洞察点を1獲得する",
  str_skill_passive_desc_430181 = "新しい能動技を獲得する：<link=\"30075\"><#FFAE07><u>洞察点</u></color></link>を<color=#00F6FF>{1}</color>消費して、<color=#00F6FF>ボス以外の敵</color>1体を1マス強制移動させる。または洞察点を8消費して、<color=#00F6FF>火印</color>を1マス移動させる。1ターン内に複数回発動する場合、<color=#00F6FF>敵/火印</color>を移動する時の洞察点の消費量が<color=#00F6FF>{1}/8</color>ずつ増加する。シュウが<color=#00F6FF>火属性のマス</color>を1つ通過するたびに洞察点を1獲得する",
  str_skill_passive_desc_433181 = "新しい能動技を獲得する：<link=\"30076\"><#FFAE07><u>洞察点</u></color></link>を<color=#00F6FF>{1}</color>消費して、<color=#00F6FF>ボス以外の敵</color>1体を1マス強制移動させる。または洞察点を8消費して、<color=#00F6FF>火印</color>を1マス移動させる。1ターン内に複数回発動する場合、<color=#00F6FF>敵/火印</color>を移動する時の洞察点の消費量が<color=#00F6FF>{1}/8</color>ずつ増加する。シュウが<color=#00F6FF>火属性のマス</color>を1つ通過するたびに洞察点を1獲得する",
  str_skill_passive_desc_436181 = "新しい能動技を獲得する：<link=\"30077\"><#FFAE07><u>洞察点</u></color></link>を<color=#00F6FF>{1}</color>消費して、<color=#00F6FF>ボス以外の敵</color>1体を1マス強制移動させる。または洞察点を8消費して、<color=#00F6FF>火印</color>を1マス移動させる。1ターン内に複数回発動する場合、<color=#00F6FF>敵/火印</color>を移動する時の洞察点の消費量が<color=#00F6FF>{1}/8</color>ずつ増加する。シュウが<color=#00F6FF>マス</color>を1つ通過するたびに洞察点を1獲得する",
  str_skill_desc_15011312 = "フィールド上のBOSS以外の全ての小型の敵を右方向に1マスノックバックする。さらに全ての敵にダメージを与える",
  str_skill_desc_15011313 = "フィールド上のBOSS以外の全ての小型の敵を上方向に1マスノックバックする。さらに全ての敵にダメージを与える",
  str_skill_desc_15011314 = "フィールド上のBOSS以外の全ての小型の敵を左方向に1マスノックバックする。さらに全ての敵にダメージを与える",
  str_skill_desc_15011315 = "フィールド上のBOSS以外の全ての小型の敵を下方向に1マスノックバックする。さらに全ての敵にダメージを与える",
  str_skill_desc_14008112 = "全ての敵にダメージを与え、さらに自身の周囲に引き寄せる",
  str_skill_desc_15001812 = "太陽フレアを引き起こし、全ての敵にダメージを与える。また命中した敵を、自身を中心にノックバックさせる",
  str_skill_name_200230101 = "静助の治癒",
  str_skill_desc_200230101 = "静助が2マスの範囲内にいる他の暗鬼のHPを回復させる。静助の技の効果範囲内に他の暗鬼が占めるマスの数が多いほど、回復効果が高くなる",
  str_skill_desc_29048011 = "ターゲットのいる地下から飛び出し、ターゲットをノックバックし、ダメージを与える",
  str_skill_upgrade_desc_16018413 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる。初期選択範囲が周囲2マスになる",
  str_skill_upgrade_desc_16018416 = "<color=#FFFF00>新たな能動技</color>を解放：極光タイム発動中に使用できる。周囲1マス内の指定の位置に瞬間移動する",
  str_skill_name_2001841 = "断裂の翼鱗",
  str_skill_name_2001842 = "断裂の翼鱗",
  str_skill_name_2001843 = "断裂の翼鱗",
  str_skill_desc_2001841 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001842 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001843 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_name_2201841 = "断裂の翼鱗",
  str_skill_name_2201842 = "断裂の翼鱗",
  str_skill_name_2201843 = "断裂の翼鱗",
  str_skill_desc_2201841 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2201842 = "<color=#00F6FF>縦、横、斜めの16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内のランダムな位置のマス<color=#00F6FF>1つ</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える",
  str_skill_desc_2201843 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与え、範囲内のランダムな位置のマス<color=#00F6FF>2つ</color>を<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える",
  str_skill_name_300184 = "幻惑の絶塵",
  str_skill_name_303184 = "幻惑の絶塵",
  str_skill_desc_300184 = "<color=#00F6FF>菱形12マス</color>内の指定の位置に瞬間移動する。着地点が<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>だった場合、<color=#00F6FF>菱形12マス</color>の範囲内で再度着地点を選択できる。通過した全ての強化マスを吸収し、1マス吸収するごとに周囲菱形12マスに<color=#00F6FF>100%</color>のダメージを与える",
  str_skill_desc_303184 = "<color=#00F6FF>周囲2マス</color>内の指定の位置に瞬間移動する。着地点が<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>だった場合、<color=#00F6FF>菱形12マス</color>の範囲内で再度着地点を選択できる。通過した全ての強化マスを吸収し、1マス吸収するごとに周囲菱形12マスに<color=#00F6FF>100%</color>のダメージを与える",
  str_skill_name_306184 = "迅幻の絶塵",
  str_skill_desc_306184 = "極光タイム発動中に使用できる：<color=#00F6FF>周囲1マス</color>内の指定の位置に瞬間移動する",
  str_skill_passive_name_410184 = "無言の境地",
  str_skill_passive_name_430184 = "無言の境地",
  str_skill_passive_desc_410184 = "チームが能動技で移動するごとに、周囲<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}</color>のダメージを与える。強化マスを1つ吸収するごとに次の最終ダメージ+<color=#00F6FF>{2}</color>",
  str_skill_passive_desc_430184 = "チームが能動技で移動するごとに、周囲<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}</color>のダメージを与え、範囲内のランダムな位置に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を1つ生成する。強化マスを1つ吸収するごとに次の最終ダメージ+<color=#00F6FF>{2}</color>",
  str_skill_name_280061101 = "ブロック・砲台",
  str_skill_desc_280061101 = "進入可能なマス1つを選択し、空中投下で<color=#00F6FF>砲台装置</color>を設置する",
  str_skill_name_280061102 = "ブロック・牽引",
  str_skill_desc_280061102 = "進入可能なマス1つを選択し、空中投下で<color=#00F6FF>牽引装置</color>を設置する",
  str_skill_name_280061103 = "ブロック・火炎",
  str_skill_desc_280061103 = "進入可能なマス1つを選択し、空中投下で<color=#00F6FF>火炎装置</color>を設置する",
  str_skill_name_280061104 = "ブロック・廃棄",
