  str_skill_name_280061105 = "ブロック・緊急修理",
  str_skill_desc_280061105 = "緊急修理を行い、ブロック8のHPを3回復する",
  str_skill_desc_140127101 = "最多4マスを選択して（深淵マスも選択可）折り鶴を置き、そのマスを万色マスに転換する。チームが折り鶴を通過すると折り鶴は消える",
