  str_skill_desc_2001851 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001852 = "最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001853 = "最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_3001851 = "<color=#00F6FF>十字方向12マス</color>以内の任意の位置に瞬間移動できる",
  str_skill_desc_3001852 = "青影の力を<color=#00F6FF>8</color>スタック累積後に解放：任意の敵1体を選択し、その<color=#00F6FF>周囲1マス</color>内の最も近い位置に瞬間移動する",
  str_skill_desc_3361852 = "青影の力を<color=#00F6FF>5</color>スタック累積後に解放：任意の敵1体を選択し、その<color=#00F6FF>周囲1マス</color>内の最も近い位置に瞬間移動する",
  str_skill_passive_desc_410185 = "チームが能動技で移動するごとに、<color=#00F6FF>周囲1マス</color>内のHPが最も低い敵に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_416185 = "チームが能動技で移動するごとに、<color=#00F6FF>周囲1マス</color>内のHPが最も低い敵に<color=#00F6FF>{1}</color>のダメージを与え、青影の力を<color=#00F6FF>1</color>スタック獲得する。青影の力1スタックごとにダメージ率+<color=#00F6FF>5%</color>",
  str_skill_passive_desc_420185 = "チームが能動技で移動するごとに、<color=#00F6FF>周囲1マス</color>内のHPが最も低い敵に<color=#00F6FF>{1}</color>のダメージを与える。キアの能動技によってこの効果が解放された場合、最終ダメージ+<color=#00F6FF>60%</color>",
  str_skill_passive_desc_426185 = "チームが能動技で移動するごとに、<color=#00F6FF>周囲1マス</color>内のHPが最も低い敵に<color=#00F6FF>{1}</color>のダメージを与え、青影の力を<color=#00F6FF>1</color>スタック獲得する。キアの能動技によってこの効果が解放された場合、最終ダメージ+<color=#00F6FF>60%</color>。青影の力1スタックごとにダメージ率+<color=#00F6FF>5%</color>",
  str_skill_passive_desc_430185 = "チームが能動技で移動するごとに、<color=#00F6FF>周囲1マス</color>内のHPが最も低い敵に<color=#00F6FF>{1}</color>のダメージを与え、青影の力を<color=#00F6FF>1</color>スタック獲得する。キアの能動技によってこの効果が解放された場合、最終ダメージ+<color=#00F6FF>60%</color>",
  str_skill_passive_desc_432185 = "チームが能動技で移動するごとに、<color=#00F6FF>周囲1マス</color>内のHPが最も低い敵に<color=#00F6FF>{1}</color>のダメージを与え、青影の力を<color=#00F6FF>1</color>スタック獲得する。キアの能動技によってこの効果が解放された場合、最終ダメージ+<color=#00F6FF>60%</color>",
  str_skill_passive_desc_436185 = "チームが能動技で移動するごとに、<color=#00F6FF>周囲1マス</color>内のHPが最も低い敵に<color=#00F6FF>{1}</color>のダメージを与え、青影の力を<color=#00F6FF>1</color>スタック獲得する。キアの能動技によってこの効果が解放された場合、最終ダメージ+<color=#00F6FF>60%</color>。青影の力1スタックごとにダメージ率+<color=#00F6FF>5%</color>",
  str_skill_upgrade_desc_15018512 = "能動技強化：青影瞬達の解放に必要なスタック数が<color=#00F6FF>5</color>になる（覚醒3で有効）",
  str_skill_upgrade_desc_15018515 = "装備技強化：装備技を発動するたびに青影の力を<color=#00F6FF>1</color>スタック獲得する。1スタックにつき、キアの装備技のダメージ率+<color=#00F6FF>5%</color>",
  str_skill_name_28005016 = "牽引装置",
  str_skill_desc_28005016 = "牽引装置の前方の小範囲内にいる暗鬼を牽引装置のある位置へ1マス引き寄せる。暗鬼1体につき、毎ターン1回のみ牽引装置による牽引効果を受ける",
  str_skill_name_400054101 = "剛力",
  str_skill_desc_400054101 = "範囲内のターゲットにダメージを与え、範囲内の全てのマスを粉砕する。さらに範囲内にあるブロック8の設置した装置を全て破壊する",
  str_skill_desc_5410100 = "ランスを使って攻撃範囲内にいる暗鬼を攻撃する",
  str_skill_desc_888426101 = "プレイヤーが能動技を連続で3回発動した後、白夜城長槍兵を1体フィールドに召喚する",
  str_skill_desc_4100002 = "火属性の双剣をフィールドに毎ターン召喚する。フィールド上の火属性の双剣の数が4個になると、それ以上召喚できなくなる",
  str_skill_desc_4100004 = "雷属性の双剣をフィールドに毎ターン召喚する。フィールド上の雷属性の双剣の数が4個になると、それ以上召喚できなくなる",
  str_skill_desc_4100005 = "鳴灼をフィールドに毎ターン召喚する。フィールド上の鳴灼の数が2体になると、それ以上召喚できなくなる",
  str_skill_desc_4100006 = "鳴灼をフィールドに毎ターン召喚する。フィールド上に鳴灼がいる場合、それ以上召喚できない",
  str_skill_desc_5401005 = "鳴灼は魔械兵付近のランダムな位置に火雨を召喚し、ターゲットに属性ダメージを与えて火傷状態にする",
  str_skill_name_290470111 = "鎖裁機甲・轟殺",
  str_skill_desc_290470111 = "巨槌で暗力を操り、全範囲のターゲットに大ダメージを与える。光霊が防衛域の範囲内にいる場合、光霊のHPを強制的に1にする",
  str_skill_name_290470121 = "鎖裁機甲・追狩",
  str_skill_desc_290470121 = "ターゲットが防衛域の範囲内にいる場合、ターゲットのそばに移動して近接攻撃を行う。ターゲットが防衛域の範囲内にいない場合、同列範囲内にいるターゲットを自身のそばに引き寄せる",
  str_skill_desc_290470122 = "ターゲットが防衛域の範囲内にいる場合、ターゲットのそばに移動して近接攻撃を行う。ターゲットが防衛域の範囲内にいない場合、同列範囲内にいるターゲットを自身のそばに引き寄せる",
  str_skill_name_290470131 = "鎖裁機甲・震逐",
  str_skill_desc_290470131 = "巨槌を振って干渉エネルギーを放ち、全範囲にダメージを与える。プレイヤーが防衛域の範囲内にいる場合、弾き飛ばされ、フィールドの端までノックバックする",
  str_skill_name_290490101 = "四騎士・輪撃",
  str_skill_desc_290490101 = "ターゲットの最も近くにいる四騎士の対角のマスに移動し（ターゲットの最も近くにいるのが自分の場合はその場にとどまる）、周囲1マスの範囲内にいるターゲットを攻撃する",
  str_skill_desc_290490103 = "ターゲットの最も近くにいる四騎士の対角のマスに移動し（ターゲットの最も近くにいるのが自分の場合はその場にとどまる）、周囲1マスの範囲内にいるターゲットを攻撃し、光霊に耐性弱化を付与する。耐性弱化1スタックごとに光霊の防御力-2%",
  str_skill_desc_290490107 = "周囲1マスの範囲内にいるターゲットを攻撃する",
  str_skill_name_290490102 = "四騎士・閃撃",
  str_skill_desc_290490102 = "他の四騎士と共にフィールドの端まで散開し、ターゲットを攻撃する",
  str_skill_desc_290490108 = "その場にとどまり、ターゲットを攻撃する",
  str_skill_name_290550101 = "魔犬ハーティ・蒼炎",
  str_skill_desc_290550101 = "魔犬ハーティが現在のHPの15%を失い、菱形12マスの範囲内で敵ターゲットに最も近い場所に移動する。その後、周囲1マス以内にいる敵にダメージを与える。ターゲットに命中した場合、失ったHPの15%を回復する",
  str_skill_name_290550111 = "魔犬ハーティ・蒼炎+",
  str_skill_desc_290550111 = "魔犬ハーティが現在のHPの15%を失い、周囲2マスの範囲内で敵ターゲットに最も近い場所に移動する。その後、周囲1マス以内にいる敵にダメージを与える。ターゲットに命中した場合、失ったHPの15%を回復する",
  str_skill_name_290550121 = "魔犬ハーティ・蒼炎++",
  str_skill_desc_290550121 = "魔犬ハーティが現在のHPの15%を失い、周囲2マスの範囲内で敵ターゲットに最も近い場所に移動する。その後、周囲2マス以内にいる敵にダメージを与える。ターゲットに命中した場合、失ったHPの15%を回復する",
  str_skill_name_290550102 = "魔犬ハーティ・幽焔",
  str_skill_desc_290550102 = "魔犬ハーティが光霊のそばに移動し、現在のHPの15%を消費して光霊に大ダメージを与える。光霊に命中した場合、失ったHPの15%を回復する",
