  str_skill_name_3331892 = "爆熱解放",
  str_skill_desc_3001890 = "自身の周囲<color=#00F6FF>十字方向4マス</color>から1マス選び、その方向の<color=#00F6FF>扇形2列</color>に<color=#00F6FF>100%</color>のダメージを与える",
  str_skill_desc_3001891 = "自身の周囲<color=#00F6FF>十字方向4マス</color>から1マス選び、その方向の<color=#00F6FF>扇形2列</color>に<color=#00F6FF>100%</color>のダメージを与える。過熱値により攻撃範囲と倍率が上昇し、最大で<color=#00F6FF>扇形7列</color>に<color=#00F6FF>400%</color>のダメージを与える。技の発動後、過熱値はクリアされる",
  str_skill_desc_3001892 = "自身の周囲<color=#00F6FF>十字方向4マス</color>から1マス選び、その方向の<color=#00F6FF>扇形2列</color>に<color=#00F6FF>100%</color>のダメージを与える。過熱値により攻撃範囲と倍率が上昇し、最大で<color=#00F6FF>扇形7列</color>に<color=#00F6FF>400%</color>のダメージを与える。技の発動後、過熱値はクリアされる",
  str_skill_desc_3061891 = "自身の周囲<color=#00F6FF>十字方向4マス</color>から1マス選び、その方向の<color=#00F6FF>扇形2列</color>に<color=#00F6FF>100%</color>のダメージを与える。過熱値により攻撃範囲と倍率が上昇し、最大で<color=#00F6FF>扇形7列</color>に<color=#00F6FF>400%</color>のダメージを与える。技発動後、過熱値はクリアされる。自身の位置するマスを選択すると、ダメージを与えず、代わりに過熱値<color=#00F6FF>35</color>を獲得する",
  str_skill_desc_3061892 = "自身の周囲<color=#00F6FF>十字方向4マス</color>から1マス選び、その方向の<color=#00F6FF>扇形2列</color>に<color=#00F6FF>100%</color>のダメージを与える。過熱値により攻撃範囲と倍率が上昇し、最大で<color=#00F6FF>扇形7列</color>に<color=#00F6FF>400%</color>のダメージを与える。技発動後、過熱値はクリアされる。自身の位置するマスを選択すると、ダメージを与えず、代わりに過熱値<color=#00F6FF>35</color>を獲得する",
  str_skill_desc_3301892 = "このターン中は爆熱状態でも通常攻撃できる。ターン終了後、過熱値がクリアされる",
  str_skill_desc_3331892 = "過熱値が<color=#00F6FF>100</color>まで上昇し、このターン中は爆熱状態で通常攻撃できる。ターン終了後、過熱値がクリアされる",
