  str_skill_desc_2001901 = "<color=#00F6FF>周囲2マス</color>以内の最も近くにいる敵2体に<color=#00F6FF>140%</color>のダメージを与える",
  str_skill_desc_2001902 = "<color=#00F6FF>周囲2マス</color>以内の最も近くにいる敵2体に<color=#00F6FF>155%</color>のダメージを与える",
  str_skill_desc_2001903 = "<color=#00F6FF>周囲2マス</color>以内の最も近くにいる敵2体に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2001933 = "<color=#00F6FF>周囲2マス</color>内の最も近くにいる敵2体に<color=#00F6FF>160%</color>のダメージを与える。火属性の光霊が能動技を発動するたびに、この技の発動条件<color=#00F6FF>+1</color>し、命中目標+1または攻撃範囲を周囲<color=#00F6FF>1</color>マス分拡大",
  str_skill_desc_3001901 = "最も近くの森属性のマス<color=#00F6FF>4</color>つを火属性に変える",
  str_skill_desc_3001902 = "最も近くの森属性のマス<color=#00F6FF>4</color>つを火属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3001903 = "最も近くの森属性のマス<color=#00F6FF>5</color>つを火属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3021901 = "最も近くの森属性のマス<color=#00F6FF>4</color>つを火属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3051901 = "最も近くの森属性のマス<color=#00F6FF>5</color>つを火属性に変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_passive_name_410189 = "赤熱轟撃",
  str_skill_passive_name_420189 = "赤熱轟撃",
  str_skill_passive_name_430189 = "赤熱轟撃",
  str_skill_passive_name_433189 = "赤熱轟撃",
  str_skill_passive_name_410190 = "輝ける守護者",
  str_skill_passive_name_420190 = "輝ける守護者",
  str_skill_passive_name_430190 = "輝ける守護者",
  str_skill_passive_desc_410189 = "ラインの通常攻撃は<link=\"30078\"><#FFAE07><u>過熱値</u></color></link>によって、最大<color=#00F6FF>{1}</color>のダメージ強化効果を獲得する。過熱値が高いほど、強化率も高くなる。過熱値が<color=#00F6FF>100</color>に達すると爆熱状態になり、通常攻撃が行えなくなる",
  str_skill_passive_desc_420189 = "ラインの通常攻撃は<link=\"30078\"><#FFAE07><u>過熱値</u></color></link>によって、最大<color=#00F6FF>{1}</color>のダメージ強化効果を獲得する。過熱値が高いほど、強化率も高くなる。過熱値が<color=#00F6FF>100</color>に達すると爆熱状態になり、通常攻撃が行えなくなる。ただし、連鎖技の最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_passive_desc_430189 = "ラインの通常攻撃は<link=\"30078\"><#FFAE07><u>過熱値</u></color></link>によって、最大<color=#00F6FF>{1}</color>のダメージ強化効果を獲得する。過熱値が高いほど、強化率も高くなる。過熱値が<color=#00F6FF>100</color>に達すると爆熱状態になり、通常攻撃が行えなくなる。ただし、連鎖技の最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_passive_desc_433189 = "ラインの通常攻撃は<link=\"30078\"><#FFAE07><u>過熱値</u></color></link>によって、最大<color=#00F6FF>{1}</color>のダメージ強化効果を獲得する。過熱値が高いほど、強化率も高くなる。過熱値が<color=#00F6FF>100</color>に達すると爆熱状態になり、通常攻撃が行えなくなる。ただし、連鎖技の最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_passive_desc_410190 = "連鎖技が与えるダメージ量の<color=#00F6FF>50%</color>をシールドに変換する。その値はマシューの攻撃力の<color=#00F6FF>{1}</color>を越えない",
  str_skill_passive_desc_420190 = "連鎖技が与えるダメージ量の<color=#00F6FF>50%</color>をシールドに変換する。その値はマシューの攻撃力の<color=#00F6FF>{1}</color>を越えない。火属性の光霊が能動技を発動するたび、マシューの攻撃力の<color=#00F6FF>10%</color>に相当するシールドを獲得する",
  str_skill_passive_desc_430190 = "連鎖技が与えるダメージ量の<color=#00F6FF>50%</color>をシールドに変換する。その値はマシューの攻撃力の<color=#00F6FF>{1}</color>を越えない。火属性の光霊が能動技を発動するたび、マシューの攻撃力の<color=#00F6FF>10%</color>に相当するシールドを獲得する",
  str_skill_upgrade_desc_16018613 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16018616 = "能動技強化：連鎖可能なマスの数<color=#00F6FF>+1</color>",
  str_skill_name_2001861 = "洞徹の落光",
