  str_skill_desc_2001862 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001863 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_passive_name_410186 = "目映き閃光",
