  str_skill_passive_desc_430186 = "毎ターン、ティナの1回目の与ダメージ+<color=#00F6FF>{1}</color>。前のターンにティナが攻撃していない場合、このターンの効果が2倍になる",
  str_skill_name_3001861 = "安息の聖光",
