  str_skill_name_3261861 = "安息の聖光",
  str_skill_desc_3001861 = "ティナが夢遊状態になり、最大<color=#00F6FF>3</color>連鎖分までマスの色を無視して移動し、<color=#00F6FF>通過したマス</color>を水属性に変え、出発地点に戻る",
  str_skill_desc_3061861 = "ティナが夢遊状態になり、最大<color=#00F6FF>4</color>連鎖分までマスの色を無視して移動し、<color=#00F6FF>通過したマス</color>を水属性に変え、出発地点に戻る",
  str_skill_desc_3201861 = "ティナが夢遊状態になり、最大<color=#00F6FF>3</color>連鎖分までマスの色を無視して移動し、<color=#00F6FF>出発地点と通過したマス</color>を水属性に変え、出発地点に戻る。さらに連鎖の終点を敵のいるマスに追加で伸ばすことができ、その場合敵に<color=#00F6FF>200%</color>のダメージを与え、出発地点に戻らない",
  str_skill_desc_3261861 = "ティナが夢遊状態になり、最大<color=#00F6FF>4</color>連鎖分までマスの色を無視して移動し、<color=#00F6FF>出発地点と通過したマス</color>を水属性に変え、出発地点に戻る。さらに連鎖の終点を敵のいるマスに追加で伸ばすことができ、その場合対象の敵に<color=#00F6FF>200%</color>のダメージを与え、出発地点に戻らない",
  str_skill_upgrade_desc_16018913 = "能動技強化：爆熱解放を<color=#FFFF00>先制攻撃</color>に変更する。発動後、過熱値が<color=#00F6FF>100</color>まで上昇する（覚醒3で有効）",
  str_skill_upgrade_desc_16018916 = "能動技強化：自身のいるマスを選択して、ダメージを与えず、代わりに過熱値を<color=#00F6FF>35</color>獲得できる（覚醒1で有効）",
  str_skill_upgrade_desc_15019012 = "能動技強化：前のターンで技が発動可能だった場合、このターンの転色数<color=#FFFF00>+1</color>。",
  str_skill_upgrade_desc_15019015 = "能動技強化：変換するマスの数が<color=#FFFF00>1つ</color>増える。",
  str_skill_upgrade_refine_desc_16001111 = "装備技強化：敵に龍牙の印を最大<color=#00F6FF>7</color>スタック付与する",
  str_skill_upgrade_refine_desc_16001112 = "<color=#00F6FF>能動技変異Ⅰを追加</color>：<color=#FFFF00>発動後の技のCDターン-1</color>。<color=#FFFF00>周囲3マス</color>以内の指定位置に瞬間移動し、<color=#FFFF00>周囲1マス</color>に<color=#FFFF00>200%</color>のダメージを与え、龍牙の印を2スタック付与する（敵を撃破した場合、範囲内の他の敵のスタック数を最大限まで増加させる）",
  str_skill_upgrade_refine_desc_16001113 = "<color=#00F6FF>能動技変異Ⅱを追加</color>：<color=#FFFF00>発動後の技のCDターン+1</color>。<color=#FFFF00>任意の</color>位置に瞬間移動し、<color=#FFFF00>周囲3マス</color>以内に<color=#FFFF00>360%</color>のダメージを与え、龍牙の印を2スタック付与する（敵を撃破した場合、範囲内の他の敵のスタック数を最大まで増加させる）",
  str_skill_desc_3300111 = "<color=#FFFF00>発動後の技のCDターン-1</color>。<color=#FFFF00>周囲3マス</color>以内の指定位置に瞬間移動し、<color=#FFFF00>周囲1マス</color>に<color=#FFFF00>200%</color>のダメージを与え、龍牙の印を2スタック付与する（敵を撃破した場合、範囲内の他の敵のスタック数を最大まで増加させる）",
  str_skill_desc_3300112 = "<color=#FFFF00>発動後の技のCDターン+1</color>。<color=#FFFF00>任意の</color>位置に瞬間移動し、<color=#FFFF00>周囲3マス</color>以内に<color=#FFFF00>360%</color>のダメージを与え、龍牙の印を2スタック付与する（敵を撃破した場合、範囲内の他の敵のスタック数を最大まで増加させる）",
  str_skill_upgrade_desc_16019113 = "新しい能動技を獲得する：現在のチームHPの<color=#00F6FF>10%</color>を消費し、<color=#00F6FF>周囲1マス</color>に250%のダメージを与える",
  str_skill_upgrade_desc_16019116 = "能動技強化：技のCDターン数-1",
