  str_skill_desc_2001912 = "<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2001913 = "<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>170%</color>のダメージを与える",
  str_skill_desc_2301911 = "<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>150%</color>のダメージを与える。HPが40%未満の場合、跳躍範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_2301912 = "<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>160%</color>のダメージを与える。HPが40%未満の場合、跳躍範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_2301913 = "<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>170%</color>のダメージを与える。HPが40%未満の場合、跳躍範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_name_3001911 = "追跡の幽焔",
  str_skill_name_3201911 = "追跡の幽焔",
  str_skill_name_32019111 = "追跡の幽焔",
  str_skill_desc_3001911 = "<color=#00F6FF>菱形24マス</color>の範囲内にいる敵1体を選択し、その敵から最も近いマスに移動して<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_3201911 = "<color=#00F6FF>菱形24マス</color>の範囲内にいる敵1体を選択し、その敵から最も近いマスに移動して敵に<color=#00F6FF>150%</color>のダメージを与える。前のターンで能動技が発動可能だった場合、このターンの選択範囲が<color=#00F6FF>周囲4マス</color>に拡大される",
  str_skill_desc_32019112 = "<color=#00F6FF>菱形24マス</color>の範囲内にいる敵1体を選択し、その敵から最も近いマスに移動して敵に<color=#00F6FF>150%</color>のダメージを与える。前のターンで能動技が発動可能だった場合、このターンの選択範囲が<color=#00F6FF>周囲4マス</color>に拡大され、ダメージが<color=#00F6FF>200%</color>に増加する",
  str_skill_desc_32019113 = "<color=#00F6FF>菱形24マス</color>の範囲内にいる敵1体を選択し、その敵から最も近いマスに移動して十字方向5マスに<color=#00F6FF>150%</color>のダメージを与える。前のターンで能動技が発動可能だった場合、このターンの選択範囲が<color=#00F6FF>周囲4マス</color>に拡大され、ダメージが<color=#00F6FF>200%</color>に増加する",
  str_skill_name_3001912 = "戦慄の幽焔",
  str_skill_name_3061912 = "戦慄の幽焔",
  str_skill_desc_3001912 = "現在のチームHPの<color=#00F6FF>10%</color>を消費し、<color=#00F6FF>周囲1マス</color>に{1}%のダメージを与える",
  str_skill_passive_name_410191 = "魂燃の鋭爪",
  str_skill_passive_desc_410191 = "チームHPが低くなるほど、ハーティの与ダメージが上昇する。チームHPが<color=#00F6FF>30%</color>以下のとき、最大で+<color=#00F6FF>{1}</color>に到達する",
  str_skill_passive_desc_4101911 = "チームHPが低くなるほど、ハーティの与ダメージが上昇する。チームHPが<color=#00F6FF>30%</color>以下のとき、最大で+<color=#00F6FF>60%</color>に到達する",
  str_skill_upgrade_refine_desc_16019111 = "装備技強化：チームHPが30%以下のとき、最大<color=#00F6FF>60%</color>のダメージ強化を獲得する",
  str_skill_upgrade_refine_desc_16019112 = "能動技追加効果：前のターンで技が発動可能だった場合、このターンの索敵範囲が周囲4マスに拡大し、<color=#00F6FF>ダメージが200%まで上昇</color>する",
  str_skill_upgrade_refine_desc_16019113 = "能動技強化：「ターゲット1体にダメージを与える」から「<color=#00F6FF>ターゲットを中心に十字方向5マス</color>にダメージを与える」に変更される",
  str_skill_name_2001931 = "逆巻く波濤",
  str_skill_name_2001932 = "逆巻く波濤",
  str_skill_name_20019333 = "逆巻く波濤",
  str_skill_name_2201931 = "逆巻く波濤",
  str_skill_name_2201932 = "逆巻く波濤",
  str_skill_name_2201933 = "逆巻く波濤",
  str_skill_name_3001931 = "天衝く海嘯",
  str_skill_name_3051931 = "天衝く海嘯",
  str_skill_name_3301931 = "天衝く海嘯",
  str_skill_name_3351931 = "天衝く海嘯",
  str_skill_name_3401931 = "天衝く海嘯・変異Ⅰ",
  str_skill_name_3451931 = "天衝く海嘯・変異Ⅰ",
  str_skill_name_3401932 = "天衝く海嘯・変異Ⅱ",
  str_skill_desc_2001931 = "<color=#00F6FF>十字方向の8マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001932 = "<color=#00F6FF>菱形12マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_20019333 = "<color=#00F6FF>周囲1マス以内</color>と<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2201931 = "<color=#00F6FF>十字方向の8マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える。十字方向の敵に対するダメージ+30%",
  str_skill_desc_2201932 = "<color=#00F6FF>菱形12マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える。十字方向の敵に対するダメージ+30%",
  str_skill_desc_2201933 = "<color=#00F6FF>周囲1マス以内</color>と<color=#00F6FF>十字方向の最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える。十字方向の敵に対するダメージ+30%",
  str_skill_desc_3001931 = "1方向を選んで攻撃し、選んだ方向にいる全ての敵に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_3051931 = "1方向を選んで攻撃し、選んだ方向にいる全ての敵に<color=#00F6FF>200%</color>のダメージを与える",
  str_skill_desc_3301931 = "1方向を選んで攻撃し、選んだ方向にいる全ての敵に<color=#00F6FF>160%</color>のダメージを与える。ターゲットとの距離が離れているほどダメージが大きくなり、1マスにつき最終ダメージ+<color=#00F6FF>10%</color>",
  str_skill_desc_3351931 = "1方向を選んで攻撃し、選んだ方向にいる全ての敵に<color=#00F6FF>200%</color>のダメージを与える。ターゲットとの距離が離れているほどダメージが大きくなり、1マスにつき最終ダメージ+<color=#00F6FF>10%</color>",
  str_skill_desc_3401931 = "<color=#FFFF00>発動後の技のCDターン+1</color>。1方向を選んで攻撃し、選んだ方向にいる全ての敵に160%のダメージを与え、チーム内の<color=#FFFF00>1つ前にいる</color>隊員と位置を入れ替わる。ターゲットとの距離が離れているほどダメージが大きくなり、1マスにつき最終ダメージ+10%。<color=#FFFF00>外周のマスを選んだ場合、クリステンが前方に1マス移動して技を放つ</color>",
  str_skill_desc_3451931 = "<color=#FFFF00>発動後の技のCDターン+1</color>。1方向を選んで攻撃し、選んだ方向にいる全ての敵に200%のダメージを与え、チーム内の<color=#FFFF00>1つ前にいる</color>隊員と位置を入れ替わる。ターゲットとの距離が離れているほどダメージが大きくなり、1マスにつき最終ダメージ+10%。<color=#FFFF00>外周のマスを選んだ場合、クリステンが前方に1マス移動して技を放つ</color>",
  str_skill_desc_3401932 = "<color=#FFFF00>発動後の技のCDターン-1</color>。<color=#FFFF00>攻撃を行わず</color>、チーム内の<color=#FFFF00>1つ後にいる</color>隊員と位置を入れ替わる。<color=#FFFF00>次の能動技の与ダメージ+50%</color>。技を繰り返し発動してもダメージ強化は累積されない",
  str_skill_passive_name_410193 = "貫く噴流",
  str_skill_passive_name_430193 = "貫く噴流",
  str_skill_passive_desc_410193 = "通常攻撃が敵を貫通し、敵の背後1マスにいるターゲットに<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_430193 = "通常攻撃が敵を貫通し、敵の背後1マスにいるターゲットに<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_4401933 = "通常攻撃が敵を貫通し、敵の背後1マスにいるターゲットに<color=#00F6FF>60%</color>のダメージを与える。クリステンのチーム内での位置が変更されると、隊長変更回数<color=#00F6FF>+1</color>。発動は1ターンに1回まで",
  str_skill_upgrade_refine_desc_15019311 = "<color=#00F6FF>能動技変異Ⅰを追加</color>：<color=#FFFF00>発動後の技のCDターン+1</color>。1方向を選んで攻撃し、選んだ方向にいる全ての敵にダメージを与え、チーム内の<color=#FFFF00>1つ前にいる</color>隊員と位置を入れ替わる。ターゲットとの距離が離れているほどダメージが大きくなり、1マスにつき最終ダメージ+10%。<color=#FFFF00>外周のマスを選んだ場合、クリステンが前方に1マス移動して技を放つ</color>",
  str_skill_upgrade_refine_desc_15019312 = "<color=#00F6FF>能動技変異Ⅱを追加</color>：<color=#FFFF00>発動後の技のCDターン-1</color>。<color=#FFFF00>攻撃を行わず</color>、チーム内の<color=#FFFF00>1つ後にいる</color>隊員と位置を入れ替わる。<color=#FFFF00>次の能動技の与ダメージ+50%</color>。技を繰り返し発動してもダメージ強化は累積されない",
  str_skill_upgrade_refine_desc_15019313 = "装備技強化：クリステンのチーム内での位置が変更されると、隊長変更回数1回獲得。発動は1ターンに1回まで",
  str_skill_upgrade_desc_15019312 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15019315 = "能動技強化：能動技のダメージ+<color=#FFFF00>40%</color>",
  str_skill_upgrade_refine_desc_14004811 = "装備技強化：敵の足元にある雷属性のマス1つにつき、ダメージ強化<color=#00F6FF>+1%</color>",
  str_skill_upgrade_refine_desc_14004812 = "能動技強化：範囲の中心のマスのダメージが2倍になる",
  str_skill_upgrade_refine_desc_14004813 = "能動技強化：前のターンで能動技が発動可能だった場合、このターンの選択範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_passive_desc_4400481 = "雷属性のマスにいる敵に対するダイナの与ダメージ+<color=#00F6FF>10%</color>。敵の足元にある雷属性のマス1つにつき、ダメージ強化+<color=#00F6FF>1%</color>。チーム内の他の雷属性の光霊がその<color=#00F6FF>半分</color>のダメージ強化を獲得する",
  str_skill_name_3400482 = "鵲・一閃",
  str_skill_name_3420482 = "鵲・一閃",
  str_skill_name_3400483 = "鵲・一閃",
  str_skill_name_3420483 = "鵲・一閃",
  str_skill_desc_3400482 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>250%</color>のダメージを与え、中心のマスに2倍のダメージを与える",
  str_skill_desc_3420482 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>250%</color>のダメージを与え、中心のマスに2倍のダメージを与える。さらに敵のいるマス1つを雷属性に変える",
  str_skill_desc_3400483 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>250%</color>のダメージを与え、中心のマスに2倍のダメージを与える。前のターンで能動技が発動可能だった場合、このターンの選択範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_3420483 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>250%</color>のダメージを与え、中心のマスに2倍のダメージを与える。さらに敵のいるマス1つを雷属性に変える。前のターンで能動技が発動可能だった場合、このターンの選択範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_upgrade_refine_desc_15009811 = "連鎖技強化：連鎖技のダメージ係数+<color=#00F6FF>15%/20%/20%</color>",
  str_skill_upgrade_refine_desc_15009812 = "装備技強化：亀裂の印が最大<color=#00F6FF>10スタック</color>。1スタックにつきダメージ+6%",
  str_skill_upgrade_refine_desc_15009813 = "能動技強化：能動技のダメージ係数が<color=#00F6FF>500%</color>に上昇する。能動技で選択した敵が位置を移動しなかった場合、発動後の<color=#00F6FF>技のCDターン-1</color>",
  str_skill_desc_2009811 = "<color=#00F6FF>周囲3マス</color>以内の敵3体に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_2009821 = "<color=#00F6FF>周囲3マス</color>以内の敵4体に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2009831 = "<color=#00F6FF>周囲3マス</color>以内の全ての敵に<color=#00F6FF>170%</color>のダメージを与える",
  str_skill_desc_3300981 = "自身の<color=#00F6FF>周囲3マス</color>以内から敵1体を選択し、<color=#00F6FF>500%</color>のダメージを与える。その敵が小型でノックバックが可能な場合、攻撃範囲内の選択した位置に移動させる。敵をノックバックできない場合、発動後の<color=#00F6FF>技のCDターン-1</color>。印のあるターゲットを倒すと、その<color=#00F6FF>周囲1マス</color>の敵にクスッタの攻撃力の<color=#00F6FF>40%</color>の防御力無視のダメージを与える",
  str_skill_desc_3350981 = "敵1体を選択し、<color=#00F6FF>500%</color>のダメージを与える。その敵が小型でノックバックが可能な場合、攻撃範囲内の選択した位置に移動させる。敵をノックバックできない場合、発動後の<color=#00F6FF>技のCDターン-1</color>。印のあるターゲットを倒すと、その<color=#00F6FF>周囲1マス</color>の敵にクスッタの攻撃力の<color=#00F6FF>40%</color>の防御力無視のダメージを与える",
  str_skill_desc_3200331 = "戦場のランダムな敵に<color=#00F6FF>95%</color>のダメージを<color=#00F6FF>5</color>回与え、現在地の<color=#00F6FF>周囲1マス</color>にある水属性のマス1つにつき、追加で1回攻撃する。各ターゲットに対して1回目に与えるダメージが<color=#00F6FF>2倍</color>になる",
  str_skill_desc_3250331 = "戦場のランダムな敵に<color=#00F6FF>95%</color>のダメージを<color=#00F6FF>6</color>回与え、現在地の<color=#00F6FF>周囲12マス</color>以内にある水属性のマス1つにつき、追加で1回攻撃する。各ターゲットに対して1回目に与えるダメージが<color=#00F6FF>2倍</color>になる",
  str_skill_passive_desc_4300331 = "バイスがダメージを与えるごとに狙撃の印を1スタック獲得する。印1スタックにつきダメージ+<color=#00F6FF>2.5%</color>（連鎖技は+<color=#00F6FF>5%</color>）。ターンが終了すると印はすべて消える",
  str_skill_passive_desc_4300332 = "バイスがダメージを与えるごとに狙撃の印を1スタック獲得する。印1スタックにつきダメージ+<color=#00F6FF>2.5%</color>（連鎖技は+<color=#00F6FF>5%</color>）。さらにバイスの基礎攻撃力+0.5%。ターンが終了すると印はすべて消える",
  str_skill_upgrade_refine_desc_15003311 = "装備技強化：印1スタックにつきダメージ+<color=#00F6FF>2.5%</color>（連鎖技は+<color=#00F6FF>5%</color>）",
  str_skill_upgrade_refine_desc_15003312 = "能動技強化：各ターゲットに対して1回目に与えるダメージが<color=#00F6FF>2倍</color>になる",
  str_skill_upgrade_refine_desc_15003313 = "装備技強化：印1スタックにつき、基礎攻撃力+<color=#00F6FF>0.5%</color>",
  str_skill_desc_340093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>250%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは2倍になる。敵1体を撃破するごとに最終ダメージ+<color=#00F6FF>15%</color>。10回まで累積できる。敵を5体撃破するごとに、瞬間移動の選択可能範囲+1マス",
  str_skill_desc_346093 = "<color=#00F6FF>周囲3マス</color>以内の任意の位置に瞬間移動し、<color=#00F6FF>周囲1マス</color>以内の敵に<color=#00F6FF>250%</color>のダメージを与える。範囲内に敵が1体のみの場合、ダメージは2倍になる。敵1体を撃破するごとに最終ダメージ+<color=#00F6FF>15%</color>。10回まで累積できる。能動技で敵を撃破すると1ターン1回のみ再使用できる。敵を5体撃破するごとに、瞬間移動の選択可能範囲+1マス",
  str_skill_passive_desc_4300931 = "連鎖技または能動技を発動した後、ターゲットのHPが<color=#00F6FF>30%</color>以下の場合、そのターゲットに攻撃力の<color=#00F6FF>120%</color>の防御力無視のダメージを追加で1回与える。追加攻撃の後、ターゲットのHPがミジャードの攻撃力より低い場合、そのターゲットを撃破する",
  str_skill_passive_desc_4300932 = "連鎖技または能動技を発動した後、ターゲットのHPが<color=#00F6FF>30%</color>以下の場合、そのターゲットに攻撃力の<color=#00F6FF>120%</color>の防御力無視のダメージを追加で1回与える。追加攻撃の後、ターゲットのHPがミジャードの攻撃力の250%より低い場合、そのターゲットを撃破する",
  str_skill_upgrade_refine_desc_16009311 = "装備技強化：追加攻撃のダメージが<color=#00F6FF>120%</color>に上昇",
  str_skill_upgrade_refine_desc_16009312 = "能動技強化：能動技がダメージ強化を<color=#00F6FF>5回</color>獲得するごとに、選択範囲+<color=#00F6FF>1マス</color>",
  str_skill_upgrade_refine_desc_16009313 = "装備技強化：追加攻撃の後、ターゲットのHPがミジャードの攻撃力の<color=#00F6FF>250%</color>より低い場合、そのターゲットを撃破する",
  str_skill_upgrade_refine_desc_15001811 = "装備技強化：敵との距離が近いほど能動技と連鎖技の与ダメージが大きくなる。ダメージは最大で+<color=#00F6FF>110%</color>",
  str_skill_upgrade_refine_desc_15001812 = "連鎖技強化：連鎖技のダメージ係数+<color=#00F6FF>10%/15%/20%</color>",
  str_skill_upgrade_refine_desc_15001813 = "装備技強化：装備技の有効範囲が<color=#00F6FF>5マス</color>以内に拡大する",
  str_skill_passive_desc_440018 = "<color=#00F6FF>周囲1マス</color>の範囲内にいる敵1体につき、攻撃力+<color=#00F6FF>5%</color>。敵との距離が近いほど能動技と連鎖技のダメージが大きくなる。最大でダメージ+<color=#00F6FF>110%</color>。敵との距離が3マスを超えるとダメージ強化がなくなる",
  str_skill_passive_desc_450018 = "<color=#00F6FF>周囲1マス</color>の範囲内にいる敵1体につき、攻撃力+<color=#00F6FF>5%</color>。敵との距離が近いほど能動技と連鎖技のダメージが大きくなる。最大でダメージ+<color=#00F6FF>110%</color>。敵との距離が5マスを超えるとダメージ強化がなくなる",
  str_skill_desc_2400181 = "<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>115%</color>のダメージを与える",
  str_skill_desc_2400182 = "<color=#00F6FF>縦方向3列</color>の範囲に<color=#00F6FF>125%</color>のダメージを与える",
  str_skill_desc_2400183 = "<color=#00F6FF>縦方向5列</color>に<color=#00F6FF>130%</color>のダメージを与える",
  str_skill_upgrade_refine_desc_16006411 = "能動技強化：戦闘開始時、技のCDターン<color=#00F6FF>-2</color>",
  str_skill_upgrade_refine_desc_16006412 = "装備技強化：自身の能動技発動時に弾薬<color=#00F6FF>5</color>発を貯蔵できる。どの属性の光霊が能動技を発動しても弾薬<color=#00F6FF>1</color>発を貯蔵できる",
  str_skill_upgrade_refine_desc_16006413 = "装備技強化：連鎖技での弾薬消費の有無を手動で変更できる",
  str_skill_passive_desc_440064 = "<link=\"30079\"><#FFAE07><u>弾薬を貯蔵</u></color></link>できる。連鎖技で1回ダメージを与えるごとに弾薬を1発消費する（オーバーロード状態では毎回最大<color=#00F6FF>3</color>発消費）。弾薬を1発消費するごとに最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_desc_341064 = "オーバーロード状態になり、ラスの連鎖技ダメージ+<color=#00F6FF>50%</color>、かつ最も近くの敵1体にダメージを2回与える。2ターン持続。戦闘開始時、技のCDターン<color=#00F6FF>-2</color>",
  str_skill_upgrade_refine_desc_16001911 = "戦闘開始時、ビクトリアが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。\n<color=#00F6FF>能動技変異Ⅰを追加</color>：<color=#FFFF00>発動後の技のCDターン-1</color>。範囲内にいる敵最大3体に<color=#FFFF00>300%</color>のダメージを与える。敵が1体のみの場合、<color=#FFFF00>300%</color>の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの一定比率のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を失う</color>",
  str_skill_upgrade_refine_desc_16001912 = "能動技強化：能動技が追加で敵を1体攻撃できる",
  str_skill_upgrade_refine_desc_16001913 = "<color=#00F6FF>能動技変異Ⅱを追加</color>：<color=#FFFF00>発動後の技のCDターン+1</color>。範囲内にいる敵最大4体に250%のダメージを与える。敵が1体のみの場合、250%の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの一定比率のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を回復する</color>",
  str_skill_desc_3200192 = "<color=#FFFF00>発動後の技のCDターン-1</color>。周囲3マス以内にいる敵最大3体に<color=#FFFF00>300%</color>のダメージを与える。敵が1体のみの場合、<color=#FFFF00>300%</color>の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの25%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を失う</color>",
  str_skill_desc_3200191 = "<color=#FFFF00>発動後の技のCDターン+1</color>。周囲3マス以内にいる敵最大3体に250%のダメージを与える。敵が1体のみの場合、250%の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの25%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を回復する</color>",
  str_skill_desc_3230192 = "<color=#FFFF00>発動後の技のCDターン-1</color>。周囲3マス以内にいる敵最大3体に<color=#FFFF00>300%</color>のダメージを与える。敵が1体のみの場合、<color=#FFFF00>300%</color>の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの35%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を失う</color>",
  str_skill_desc_3230191 = "<color=#FFFF00>発動後の技のCDターン+1</color>。周囲3マス以内にいる敵最大3体に250%のダメージを与える。敵が1体のみの場合、250%の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの35%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を回復する</color>",
  str_skill_desc_3260192 = "<color=#FFFF00>発動後の技のCDターン-1</color>。最も近くにいる敵最大3体に<color=#FFFF00>300%</color>のダメージを与える。敵が1体のみの場合、<color=#FFFF00>300%</color>の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの35%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を失う</color>",
  str_skill_desc_3260191 = "<color=#FFFF00>発動後の技のCDターン+1</color>。最も近くにいる敵最大3体に250%のダメージを与える。敵が1体のみの場合、250%の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの35%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を回復する</color>",
  str_skill_desc_32001922 = "<color=#FFFF00>発動後の技のCDターン-1</color>。周囲3マス以内にいる敵最大4体に<color=#FFFF00>300%</color>のダメージを与える。敵が1体のみの場合、<color=#FFFF00>300%</color>の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの25%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を失う</color>",
  str_skill_desc_32001912 = "<color=#FFFF00>発動後の技のCDターン+1</color>。周囲3マス以内にいる敵最大4体に250%のダメージを与える。敵が1体のみの場合、250%の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの25%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を回復する</color>",
  str_skill_desc_32301922 = "<color=#FFFF00>発動後の技のCDターン-1</color>。周囲3マス以内にいる敵最大4体に<color=#FFFF00>300%</color>のダメージを与える。敵が1体のみの場合、<color=#FFFF00>300%</color>の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの35%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を失う</color>",
  str_skill_desc_32301912 = "<color=#FFFF00>発動後の技のCDターン+1</color>。周囲3マス以内にいる敵最大4体に250%のダメージを与える。敵が1体のみの場合、250%の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの35%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を回復する</color>",
  str_skill_desc_32601922 = "<color=#FFFF00>発動後の技のCDターン-1</color>。最も近くにいる敵最大4体に<color=#FFFF00>300%</color>のダメージを与える。敵が1体のみの場合、<color=#FFFF00>300%</color>の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの35%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を失う</color>",
  str_skill_desc_32601912 = "<color=#FFFF00>発動後の技のCDターン+1</color>。最も近くにいる敵最大4体に250%のダメージを与える。敵が1体のみの場合、250%の防御力無視のダメージを与える。ターゲットは出血状態1スタックにつき最終ダメージ+10%。今回のダメージの35%のHPを回復し、<color=#FFFF00>今回のHP回復比率に等しい理性値を回復する</color>",
  str_skill_desc_340019 = "<color=#00F6FF>周囲3マス</color>にいる最大4体の敵に<color=#00F6FF>250%</color>のダメージを与える。敵が1体だけの場合は<color=#00F6FF>250%</color>の防御力無視のダメージを与え、ターゲットは出血状態1スタックにつき最終ダメージ+10%。そのダメージの25%のHPを回復する",
  str_skill_desc_343019 = "<color=#00F6FF>周囲3マス</color>にいる最大4体の敵に<color=#00F6FF>250%</color>のダメージを与える。敵が1体だけの場合は<color=#00F6FF>250%</color>の防御力無視のダメージを与え、ターゲットは出血状態1スタックにつき最終ダメージ+10%。そのダメージの35%のHPを回復する",
  str_skill_desc_346019 = "最も近くにいる最大4体の敵に<color=#00F6FF>250%</color>のダメージを与える。敵が1体だけの場合は<color=#00F6FF>250%</color>の防御力無視のダメージを与え、ターゲットは出血状態1スタックにつき最終ダメージ+10%。そのダメージの35%のHPを回復する",
  str_skill_name_290510101 = "ドリルフィールド・発動",
  str_skill_desc_290510101 = "ドリルがランダムに比較的何もないエリアを選んで移動し、その移動中、隣接する4マスに放電しダメージを与える。移動終了時、周囲2マスの範囲内にエネルギーマスとサポートマスを一定数生成する",
  str_skill_desc_290511102 = "ドリルがランダムに比較的何もないエリアを選んで移動し、その移動中、隣接する4マスに放電しダメージを与える。移動終了時、エネルギーマスとサポートマスを一定数生成する",
  str_skill_desc_290511103 = "行動開始時、周囲にエネルギーマスとサポートマスを一定数生成する",
  str_skill_name_290510102 = "ドリル・フィールド構築",
  str_skill_desc_290510102 = "ドリルがフィールド上のエネルギーマスを吸収してその場にプラットフォームを生成し、さらに全範囲ダメージを与える。",
  str_skill_name_290510203 = "ドリル・協撃",
  str_skill_desc_290510203 = "ドリルがプラットフォームを使って光霊をロックし、プレイヤーから最も距離の近い5つのサポートマスを反応させてプレイヤーにダメージを与える。エネルギー蓄積のカウントダウン2",
  str_skill_desc_290510213 = "ドリルがプラットフォームを使って光霊をロックし、プレイヤーから最も距離の近い3つのサポートマスを反応させてプレイヤーにダメージを与える。エネルギー蓄積のカウントダウン1",
  str_skill_name_290510204 = "プラットフォーム自爆",
  str_skill_desc_290510204 = "エネルギーの蓄積を完了させたプラットフォームが自爆し、全範囲に大ダメージを与える",
  str_skill_name_290510123 = "作業中",
  str_skill_desc_290510123 = "ドリルはプラットフォームに隠れて作業する。ドリルとドリルのプラットフォームのHPはそれぞれ独立して計算される。",
  str_skill_desc_290511101 = "ドリルがプレイヤーのいる位置に向かって移動し、その移動中、隣接する4マスに放電しダメージを与える。移動終了時、隣接する4マスにサポートマスを生成する",
  str_skill_desc_290511203 = "ドリルがプラットフォームを使って光霊をロックし、すべてのサポートマスを反応させてプレイヤーにダメージを与える。サポートマスの数が多いほど、プレイヤーの被ダメージが大きくなる",
  str_skill_desc_290512101 = "ドリルがターン開始時、近接する範囲に少量のエネルギーマスとサポートマスを生成する",
  str_skill_upgrade_desc_16019913 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16019916 = "装備技強化：インゲルが開放傷のスタックされたターゲットにダメージを与える時、開放傷1スタックにつき、<color=#00F6FF>5%</color>の防御力を無視する（覚醒3で有効）",
  str_skill_name_2001991 = "精密射撃",
  str_skill_name_2001992 = "精密射撃",
  str_skill_name_2001993 = "精密射撃",
  str_skill_desc_2001991 = "最も近くにいる敵1体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001992 = "最も近くにいる敵1体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001993 = "最も近くにいる敵1体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_name_2201991 = "精密射撃",
  str_skill_name_2201992 = "精密射撃",
  str_skill_name_2201993 = "精密射撃",
  str_skill_desc_2201991 = "開放傷が最も多く、かつHPが最も高い敵1体に<color=#00F6FF>{1}%</color>のダメージを与える。それ以外の場合、最も近くの敵を攻撃する",
  str_skill_desc_2201992 = "開放傷が最も多く、かつHPが最も高い敵1体に<color=#00F6FF>{1}%</color>のダメージを与える。それ以外の場合、最も近くの敵を攻撃する",
  str_skill_desc_2201993 = "開放傷が最も多く、かつHPが最も高い敵1体に<color=#00F6FF>{1}%</color>のダメージを与える。それ以外の場合、最も近くの敵を攻撃する",
  str_skill_name_3001991 = "定点共鳴",
  str_skill_desc_3001991 = "マスを1つ選択し、雷属性の<link=\"30080\"><#FFAE07><u>クロスプリズムマス</u></color></link>に変える",
  str_skill_passive_name_410199 = "特殊弾頭装填",
  str_skill_passive_name_420199 = "特殊弾頭装填",
  str_skill_passive_name_430199 = "特殊弾頭装填",
  str_skill_passive_name_436199 = "特殊弾頭装填",
  str_skill_passive_desc_410199 = "インゲルの通常攻撃によるダメージ倍率が<color=#00F6FF>1回おきに</color><color=#00F6FF>{1}</color>に上昇する",
  str_skill_passive_desc_420199 = "インゲルの通常攻撃のダメージ倍率が<color=#00F6FF>1回おきに</color><color=#00F6FF>{1}</color>まで上昇し、さらに開放傷を1スタック付与する（最大20まで）。インゲルが開放傷のスタックされたターゲットにダメージを与える時、1スタックにつき連鎖技の最終ダメージ+<color=#00F6FF>3%</color>",
  str_skill_passive_desc_430199 = "インゲルの通常攻撃のダメージ倍率が<color=#00F6FF>1回おきに</color><color=#00F6FF>{1}</color>まで上昇し、さらに開放傷を1スタック付与する（最大20まで）。インゲルが開放傷のスタックされたターゲットにダメージを与える時、1スタックにつき<color=#00F6FF>3%</color>の防御力を無視し、さらに連鎖技の最終ダメージ+<color=#00F6FF>3%</color>",
  str_skill_passive_desc_436199 = "インゲルの通常攻撃のダメージ倍率が<color=#00F6FF>1回おきに</color><color=#00F6FF>{1}</color>まで上昇し、さらに開放傷を1スタック付与する（最大20まで）。インゲルが開放傷のスタックされたターゲットにダメージを与える時、1スタックにつき<color=#00F6FF>5%</color>の防御力を無視し、さらに連鎖技の最終ダメージ+<color=#00F6FF>3%</color>",
  str_skill_desc_1601751002 = "クロスプリズムマス",
  str_skill_desc_160175102 = "キュービックエネルギーを<color=#00F6FF>3</color>消費して、任意の1マスを選択し、クロスプリズムマスに変える",
  str_skill_name_3400231 = "アビス轟鳴曲・変異Ⅰ",
  str_skill_name_3430231 = "アビス轟鳴曲・変異Ⅰ",
  str_skill_name_3400232 = "アビス轟鳴曲・変異Ⅱ",
  str_skill_name_3430232 = "アビス轟鳴曲・変異Ⅱ",
  str_skill_desc_3400231 = "<color=#FFFF00>発動後技のCDターン-2</color>。全ての敵に<color=#FFFF00>250%</color>のダメージを与える。この変異では装備技の恐怖効果を発動できない",
  str_skill_desc_3430231 = "<color=#FFFF00>発動後技のCDターン-2</color>。全ての敵に<color=#FFFF00>250%</color>のダメージを与える。この変異では装備技の恐怖効果を発動できない",
  str_skill_desc_3400232 = "<color=#FFFF00>発動後技のCDターン+2</color>。全ての敵に<color=#FFFF00><link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態を1ターン付与</color>し、さらに<color=#FFFF00>550%</color>のダメージを与える",
  str_skill_desc_3430232 = "<color=#FFFF00>発動後技のCDターン+2</color>。全ての敵に<color=#FFFF00><link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態を1ターン付与</color>し、さらに<color=#FFFF00>550%</color>のダメージを与える",
  str_skill_passive_desc_440023 = "連鎖技発動時、戦慄の印を1スタック獲得する。最大<color=#00F6FF>5</color>スタック。印1スタックにつき能動技のダメージ+<color=#00F6FF>20%</color>。能動技使用時、印のスタック数と同じ数の敵を<color=#00F6FF>1</color>ターン<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態にし、<color=#00F6FF>印は消えない</color>。連鎖技使用時、発動前に印を5スタック獲得している場合、連鎖技が追加で最も近くにいる敵1体にダメージを与える。クラリンが<link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態の敵に与える最終ダメージ+15%",
  str_skill_upgrade_refine_desc_16002311 = "<color=#00F6FF>能動技変異Ⅰを追加</color>：<color=#FFFF00>発動後技のCD-2ターン</color>。全ての敵に<color=#FFFF00>250%</color>のダメージを与える。この変異では装備技の恐怖効果を発動できない",
  str_skill_upgrade_refine_desc_16002312 = "装備技強化：クラリンが恐怖状態の敵に与える<color=#00F6FF>最終ダメージ+15%</color>",
  str_skill_upgrade_refine_desc_16002313 = "<color=#00F6FF>能動技変異Ⅱを追加</color>：<color=#FFFF00>発動後技のCD+2ターン</color>。全ての敵に<color=#FFFF00><link=\"10003\"><#FFAE07><u>恐怖</u></color></link>状態を1ターン付与</color>し、さらに<color=#FFFF00>550%</color>のダメージを与える",
  str_skill_name_290520101 = "猛禽の襲撃",
  str_skill_desc_290520101 = "光霊に向かって移動し、大ダメージを与える。その後ターゲットから離れた位置に移動する。",
  str_skill_name_290520102 = "猛禽の襲撃",
  str_skill_desc_290520102 = "移動後、範囲内の光霊にダメージを与える。",
  str_skill_name_200250101 = "行進・射撃",
  str_skill_desc_200250101 = "範囲内のターゲットに1回遠距離攻撃を行う",
  str_skill_name_200250102 = "襲進・剣刃",
  str_skill_desc_200250102 = "範囲内のターゲットに1回近接攻撃を行う。",
  str_skill_name_290500122 = "クモの卵",
  str_skill_desc_290500122 = "スパイダークイーンの生んだ卵。短期間で新たにベビーがふ化する",
  str_skill_name_3400901 = "スイートキッス・変異Ⅰ",
