  str_skill_name_3400902 = "スイートキッス・変異Ⅱ",
  str_skill_name_3420902 = "スイートキッス・変異Ⅱ",
  str_skill_desc_3400901 = "<color=#FFFF00>発動後技のCDターン+1</color>。全ての敵に<color=#FFFF00>{1}%</color>のダメージを与え、<color=#FFFF00>さらに眩暈状態にする</color>",
  str_skill_desc_3420901 = "<color=#FFFF00>発動後技のCDターン+1</color>。全ての敵に<color=#FFFF00>{1}%</color>のダメージを与え、<color=#FFFF00>さらに眩暈状態にする</color>",
  str_skill_desc_3400902 = "<color=#FFFF00>発動後技のCDターン-1</color>。全ての敵に<color=#FFFF00>{1}%</color>のダメージを与える",
  str_skill_desc_3420902 = "<color=#FFFF00>発動後技のCDターン-1</color>。全ての敵に<color=#FFFF00>{1}%</color>のダメージを与える",
  str_skill_passive_desc_440090 = "火属性のマスにいる敵に対するバーバラの与ダメージ+<color=#00F6FF>10%</color>。敵の足元にある火属性のマス1つにつき、ダメージ強化+<color=#00F6FF>1%</color>。チーム内の他の火属性の光霊がその<color=#00F6FF>半分</color>のダメージ強化を獲得する",
  str_skill_upgrade_refine_desc_15009011 = "装備技強化：敵の足元にある火属性のマス1つにつき、ダメージ強化<color=#00F6FF>+1%</color>",
  str_skill_upgrade_refine_desc_15009012 = "<color=#00F6FF>能動技変異Ⅰを追加</color>：<color=#FFFF00>発動後技のCDターン+1</color>。全ての敵に<color=#FFFF00>600%</color>のダメージを与え、<color=#FFFF00>さらに眩暈状態にする</color>",
  str_skill_upgrade_refine_desc_15009013 = "<color=#00F6FF>能動技変異Ⅱを追加</color>：<color=#FFFF00>発動後技のCDターン-1</color>。全ての敵に<color=#FFFF00>450%</color>のダメージを与える",
  str_skill_name_5000961 = "リンク",
  str_skill_desc_5000961 = "光霊がトゲトゲから2マス以内に入った時に自動的にリンクされ、トゲトゲから4マス以内の範囲から出るとリンクが切断される。リンク中、トゲトゲが光霊のダメージの50%を代わりに受ける",
  str_skill_desc_4001531 = "3マス以内にいる敵を1マスノックバックし、その足元のマスを雷属性に変換する",
  str_skill_desc_4001751 = "技の発動後、光霊がこのターン内にダメージを1回受けるごとに、隊長と同じ属性のマスを1つ更新する。さらにチームが少量のHPを回復する。",
  str_skill_name_2001921 = "全面突破",
  str_skill_name_2001922 = "全面突破",
  str_skill_name_2001923 = "全面突破",
