  str_skill_name_3301921 = "侵襲の躍撃",
  str_skill_name_3301922 = "侵襲の躍撃",
  str_skill_name_3301923 = "侵襲の躍撃",
  str_skill_name_3401921 = "棘印の金矛",
  str_skill_desc_2001921 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001922 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2001923 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_3001920 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に攻撃力の<color=#00F6FF>270%</color>のダメージを与える",
  str_skill_desc_34019200 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に攻撃力の<color=#00F6FF>270%</color>のダメージを与える。攻撃範囲内のランダムな位置に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<color=#00F6FF>2</color>つ生成する。さらに現在の<color=#00F6FF>棘印</color>の数に応じて技効果が強化される：\n<color=#00F6FF>>10</color>スタック以上：攻撃範囲が正方形25マスに拡大する。\n<color=#00F6FF>>20</color>スタック以上：技のCDターン-1。\n<color=#00F6FF>>30</color>スタック以上：この技を発動する時、全ての敵に270%のダメージを与える",
  str_skill_desc_34019201 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に攻撃力の<color=#00F6FF>270%</color>のダメージを与える。攻撃範囲内のランダムな位置に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<color=#00F6FF>2</color>つ生成する。さらに現在の<color=#00F6FF>棘印</color>の数に応じて技効果が強化される：\n<color=#00F6FF>>10</color>スタック以上：攻撃範囲が正方形25マスに拡大する。\n<color=#00F6FF>>20</color>スタック以上：技のCDターン-1。\n<color=#00F6FF>>30</color>スタック以上：この技を発動する時、全ての敵に270%のダメージを与える",
  str_skill_desc_34019202 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に攻撃力の<color=#00F6FF>270%</color>のダメージを与える。攻撃範囲内のランダムな位置に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<color=#00F6FF>2</color>つ生成する。さらに現在の<color=#00F6FF>棘印</color>の数に応じて技効果が強化される：\n<color=#00F6FF>>10</color>スタック以上：攻撃範囲が正方形25マスに拡大する。\n<color=#00F6FF>>20</color>スタック以上：技のCDターン-1。\n<color=#00F6FF>>30</color>スタック以上：この技を発動する時、全ての敵に270%のダメージを与える",
  str_skill_desc_34019203 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に攻撃力の<color=#00F6FF>270%</color>のダメージを与える。攻撃範囲内のランダムな位置に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<color=#00F6FF>2</color>つ生成する。さらに現在の<color=#00F6FF>棘印</color>の数に応じて技効果が強化される：\n<color=#00F6FF>>10</color>スタック以上：攻撃範囲が正方形25マスに拡大する。\n<color=#00F6FF>>20</color>スタック以上：技のCDターン-1。\n<color=#00F6FF>>30</color>スタック以上：この技を発動する時、全ての敵に270%のダメージを与える",
  str_skill_desc_3301920 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に攻撃力の<color=#00F6FF>270%</color>のダメージを与える。さらに現在の<color=#00F6FF>棘印</color>の数に応じて技効果が強化される：\n<color=#00F6FF>>10</color>スタック以上：攻撃範囲が正方形25マスに拡大する。\n<color=#00F6FF>>20</color>スタック以上：技のCDターン-1。\n<color=#00F6FF>>30</color>スタック以上：この技を発動する時、全ての敵に270%のダメージを与える",
  str_skill_desc_3301921 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に攻撃力の<color=#00F6FF>270%</color>のダメージを与える。さらに現在の<color=#00F6FF>棘印</color>の数に応じて技効果が強化される：\n<color=#00F6FF>>10</color>スタック以上：攻撃範囲が正方形25マスに拡大する。\n<color=#00F6FF>>20</color>スタック以上：技のCDターン-1。\n<color=#00F6FF>>30</color>スタック以上：この技を発動する時、全ての敵に270%のダメージを与える",
  str_skill_desc_3301922 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に攻撃力の<color=#00F6FF>270%</color>のダメージを与える。さらに現在の<color=#00F6FF>棘印</color>の数に応じて技効果が強化される：\n<color=#00F6FF>>10</color>スタック以上：攻撃範囲が正方形25マスに拡大する。\n<color=#00F6FF>>20</color>スタック以上：技のCDターン-1。\n<color=#00F6FF>>30</color>スタック以上：この技を発動する時、全ての敵に270%のダメージを与える",
  str_skill_desc_3301923 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に攻撃力の<color=#00F6FF>270%</color>のダメージを与える。さらに現在の<color=#00F6FF>棘印</color>の数に応じて技効果が強化される：\n<color=#00F6FF>>10</color>スタック以上：攻撃範囲が正方形25マスに拡大する。\n<color=#00F6FF>>20</color>スタック以上：技のCDターン-1。\n<color=#00F6FF>>30</color>スタック以上：この技を発動する時、全ての敵に270%のダメージを与える",
  str_skill_desc_3401921 = "棘印を<color=#00F6FF>5</color>スタック消費する：このターン斜め方向へ通常攻撃が可能になり、通常攻撃のダメージ+<color=#00F6FF>20%</color>（繰り返して発動すると重ね掛け可能）。能動技の発動と見なされない",
  str_skill_passive_name_410192 = "棘の刻印",
  str_skill_passive_name_416192 = "棘の刻印",
  str_skill_passive_name_430192 = "棘の刻印",
  str_skill_passive_name_436192 = "棘の刻印",
  str_skill_passive_desc_410192 = "チームが<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果を得る（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）ごとに、<color=#00F6FF>棘印</color>を1スタック獲得する。棘印1スタックにつき連鎖技のダメージ率+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_416192 = "チームが<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果を得る（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）ごとに<color=#00F6FF>棘印</color>を1スタック獲得する。棘印1スタックにつき連鎖技のダメージ率+<color=#00F6FF>{1}</color>。各ウェーブ開始時に棘印を<color=#00F6FF>5</color>スタック獲得する",
  str_skill_passive_desc_430192 = "チームが<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果を得る（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）ごとに、<color=#00F6FF>棘印</color>を1スタック獲得する。棘印1スタックにつき連鎖技のダメージ率+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_436192 = "チームが<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果を得る（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）ごとに<color=#00F6FF>棘印</color>を1スタック獲得する。棘印1スタックにつき連鎖技のダメージ率+<color=#00F6FF>{1}</color>。各ウェーブ開始時に棘印を<color=#00F6FF>5</color>スタック獲得する",
  str_skill_passive_desc_440192 = "チームが<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果を得る（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）ごとに、<color=#00F6FF>棘印</color>を1スタック獲得する。棘印1スタックにつき連鎖技のダメージ率+<color=#00F6FF>3%</color>",
  str_skill_passive_desc_446192 = "チームが<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果を得る（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）ごとに<color=#00F6FF>棘印</color>を1スタック獲得する。棘印1スタックにつき連鎖技のダメージ率+<color=#00F6FF>3%</color>。各ウェーブ開始時に棘印を<color=#00F6FF>5</color>スタック獲得する",
  str_skill_upgrade_refine_desc_16019211 = "装備技強化：棘印1スタックにつき、連鎖技のダメージ率+<color=#00F6FF>3%</color>",
  str_skill_upgrade_refine_desc_16019212 = "装備技強化：戦闘開始時に棘印<color=#00F6FF>5</color>スタックを獲得する",
  str_skill_upgrade_refine_desc_16019213 = "能動技強化：攻撃範囲内のランダムな位置に<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>を<color=#00F6FF>2</color>つ生成する",
  str_skill_passive_desc_440193 = "チームが<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果を得る（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）ごとに<color=#00F6FF>棘印</color>を1スタック獲得する。棘印1スタックにつき連鎖技のダメージ率+<color=#00F6FF>3%</color>。戦闘開始時に棘印を<color=#00F6FF>5</color>スタック獲得する",
  str_skill_passive_desc_446193 = "チームが<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果を得る（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）ごとに<color=#00F6FF>棘印</color>を1スタック獲得する。棘印1スタックにつき連鎖技のダメージ率+<color=#00F6FF>3%</color>。戦闘開始時と各ウェーブ開始時に棘印を<color=#00F6FF>5</color>スタック獲得する",
  str_skill_upgrade_desc_16019213 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16019216 = "装備技強化：各ウェーブ開始時に棘印<color=#00F6FF>5</color>スタックを獲得する",
  str_skill_name_5010152 = "鼓舞",
  str_skill_desc_5010152 = "暗影は味方ユニットが最も多いエリアに移動し、フィールド上の味方すべてに強勢の印を付与する。印を得た味方は攻撃力が上昇する。",
  str_skill_name_888450061 = "暗礁の攻撃",
  str_skill_desc_888450061 = "幽刹を1体召喚する。2ターン経過するごとに幽刹が光霊を攻撃する",
  str_skill_desc_888450081 = "摂魂輪が自身及び周囲1マス内の同属性のマスのエネルギーを吸収し、エネルギーボールで敵全体を攻撃する。吸収したマスが多いほどダメージは大きくなる。光霊に命中後2ターン経過すると、光霊のいる位置に危険エリアを生成する",
  str_skill_upgrade_refine_desc_13004611 = "装備技強化：キーティンの通常攻撃ダメージ強化効果が自身に対して<color=#00F6FF>2倍</color>になる",
  str_skill_upgrade_refine_desc_13004613 = "装備技強化：キーティンが通常攻撃するごとに、<color=#00F6FF>35%</color>の確率で敵に嘲笑の印を1スタック付与する",
  str_skill_passive_desc_4400461 = "嘲笑の印が付いた敵を撃破した時、残りの敵全員の印のスタック数<color=#00F6FF>+1</color>。印1スタックにつき雷属性光霊の通常攻撃ダメージ+<color=#00F6FF>1.8%</color>。キーティン自身への強化効果はその<color=#00F6FF>2倍</color>となる",
  str_skill_desc_340046 = "戦闘開始時、技のCDターン<color=#00F6FF>-2</color>。任意の1マスに分身を置き、その<color=#00F6FF>周囲3マス</color>以内の敵を引き寄せる。また印を5スタック持っている敵に2ターンの<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。",
  str_skill_desc_342046 = "戦闘開始時、技のCDターン<color=#00F6FF>-2</color>。任意の1マスに分身を置き、その<color=#00F6FF>周囲3マス</color>以内の敵を引き寄せる。また印を4スタック持っている敵には2ターンの<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与し、印を6スタック持っている敵には1ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>状態を付与する",
  str_skill_desc_345046 = "戦闘開始時、技のCDターン<color=#00F6FF>-2</color>。任意の1マスに分身を置き、<color=#00F6FF>全ての</color>敵を引き寄せる。また印を4スタック持っている敵には2ターンの<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与し、印を6スタック持っている敵には<color=#00F6FF>1</color>ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>状態を付与する",
  str_skill_passive_desc_4400463 = "嘲笑の印が付いた敵を撃破した時、残りの敵全員の印のスタック数<color=#00F6FF>+1</color>。印1スタックにつき雷属性光霊の通常攻撃ダメージ+<color=#00F6FF>2%</color>。キーティン自身への強化効果はその<color=#00F6FF>2倍</color>になる。キーティンが通常攻撃するごとに、<color=#00F6FF>35%</color>の確率で敵に嘲笑の印を1スタック付与する",
  str_skill_upgrade_refine_desc_16006011 = "装備技強化：「真昼」状態の時、通常攻撃の飛散ダメージが<color=#00F6FF>60%</color>に上昇する",
  str_skill_upgrade_refine_desc_16006012 = "装備技強化：「真昼」状態の時、通常攻撃のダメージが追加で+<color=#00F6FF>5%</color>",
  str_skill_upgrade_refine_desc_16006013 = "装備技強化：「真昼」状態の時、連鎖技の範囲が1マス分拡大する",
  str_skill_passive_desc_4400601 = "「真昼」状態の時、通常攻撃のダメージ+<color=#00F6FF>20%</color>。さらに通常攻撃時、目標から<color=#00F6FF>十字方向4マス</color>の範囲内にいる敵に<color=#00F6FF>60%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_passive_desc_4400602 = "「真昼」状態の時、通常攻撃のダメージ+<color=#00F6FF>25%</color>。さらに通常攻撃時、目標から<color=#00F6FF>十字方向4マス</color>の範囲内にいる敵に<color=#00F6FF>60%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_desc_243601 = "<color=#00F6FF>周囲2マス</color>以内の敵4体に<color=#00F6FF>155%</color>のダメージを与える。「真昼」状態の時、範囲が1マス分拡大する",
  str_skill_desc_243602 = "<color=#00F6FF>周囲3マス</color>以内の敵4体に<color=#00F6FF>160%</color>のダメージを与える。「真昼」状態の時、範囲が1マス分拡大する",
  str_skill_desc_243603 = "<color=#00F6FF>周囲4マス</color>以内の敵4体に<color=#00F6FF>175%</color>のダメージを与える。「真昼」状態の時、範囲が1マス分拡大する",
