  str_skill_passive_name_430200 = "弱点分析",
  str_skill_desc_2002001 = "<color=#00F6FF>周囲3マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002002 = "<color=#00F6FF>周囲4マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002003 = "最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2102001 = "<color=#00F6FF>周囲3マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2102002 = "<color=#00F6FF>周囲4マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2102003 = "最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_300200 = "最大2体の任意の敵に<color=#00F6FF>{1}%</color>のダメージを与える。選択したマスおよび中間のマスにいる敵がその範囲の中心に向かって<link=\"30081\"><#FFAE07><u>集結する</u></color></link>。選択した敵が1体の場合、その敵はダメージのみをうけ、移動しない。",
  str_skill_desc_305200 = "最大2体の任意の敵に<color=#00F6FF>{1}%</color>のダメージを与える。選択したマスおよび中間のマスにいる敵がその範囲の中心に向かって<link=\"30081\"><#FFAE07><u>集結する</u></color></link>。選択した敵が1体の場合、その敵はダメージのみをうけ、移動しない。敵が<color=#00F6FF>1</color>マス引き寄せられるごとに、最終ダメージ+<color=#00F6FF>10%</color>",
  str_skill_desc_320200 = "最大2体の任意の敵に<color=#00F6FF>{1}%</color>のダメージを与える。選択したマスおよび中間のマスにいる敵がその範囲の中心に向かって<link=\"30081\"><#FFAE07><u>集結する</u></color></link>。選択した敵が1体の場合、アナトリア自身をもう1体のターゲットとし、中心に向かって集結する",
  str_skill_desc_325200 = "最大2体の任意の敵に<color=#00F6FF>{1}%</color>のダメージを与える。選択したマスおよび中間のマスにいる敵がその範囲の中心に向かって<link=\"30081\"><#FFAE07><u>集結する</u></color></link>。選択した敵が1体の場合、アナトリア自身をもう1体のターゲットとし、中心に向かって集結する。敵が<color=#00F6FF>1</color>マス引き寄せられるごとに、最終ダメージ+<color=#00F6FF>10%</color>",
  str_skill_passive_desc_410200 = "アナトリアの連鎖技がターゲットに隣接するランダムの敵に追加で<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_430200 = "アナトリアの連鎖技がターゲットに隣接するランダムの敵に追加で<color=#00F6FF>{1}</color>のダメージを与える。チーム全員のすべての<color=#00F6FF>ターゲット1体にダメージを与えるタイプ</color>の連鎖技が<link=\"30082\"><#FFAE07><u>集合</u></color></link>している敵に与える最終ダメージ+<color=#00F6FF>7%</color>",
  str_skill_upgrade_desc_15020012 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15020015 = "能動技強化：敵を<color=#00F6FF>1</color>マス引き寄せるごとに最終ダメージ+<color=#00F6FF>10%</color>",
  str_skill_name_290530101 = "恐愕の印",
  str_skill_desc_290530101 = "ターゲットに直接ダメージを与え、ターゲットのいるマスに印を生成する",
  str_skill_name_290530102 = "恐愕の衝突",
  str_skill_desc_290530102 = "ターゲットのいる方向に最大2マス突進し、途中と到着地点の十字方向4マス以内のターゲットにダメージを与える。恐愕の衝突がターゲットに命中しなかった場合、ヘリオスは追加で恐愕の印を発動する",
  str_skill_desc_290530312 = "ターゲットのいる方向に最大2マス突進し、途中と到着地点の十字方向4マス以内のターゲットにダメージを与える",
  str_skill_name_290530103 = "恐愕の跳躍",
  str_skill_desc_290530103 = "ターゲットが技の範囲内にいる場合、ヘリオスはその付近まで跳躍し、着地時ターゲットに大ダメージを与え、さらにノックバックする。恐愕の跳躍がターゲットに命中しなかった場合、またはターゲットが恐愕の跳躍の技範囲内にいない場合、ヘリオスは追加で恐愕の印を発動する",
  str_skill_name_290530104 = "恐愕の狂襲",
  str_skill_desc_290530104 = "ヘリオスが恐愕の印の生成順に従って、順次印の位置まで突進し、その後ターゲット周囲に突進して途中および到着地点の一定範囲内のターゲットに大ダメージを与える。また、ヘリオスが一部の損傷値をHPに変換する",
  str_skill_name_215009011 = "通常攻撃",
  str_skill_desc_215009011 = "移動後、範囲内の敵を1回攻撃する",
  str_skill_name_11150713 = "危険域の源泉",
  str_skill_desc_11150713 = "危険エリアにいる時、HPを一部回復する。さらに永久的に自身を強化する",
  str_skill_name_290530302 = "恐愕の衝突",
  str_skill_desc_290530302 = "ターゲットのいる方向に最大2マス突進し、途中と到着地点の十字方向4マス以内のターゲットにダメージを与える",
  str_skill_desc_11150313 = "神秘的な光の結晶。マス上を通過すると発動。発動すると雷を呼び出し、光霊を含むすべてのターゲットを攻撃する",
  str_skill_name_290500102 = "捕食",
  str_skill_name_290500112 = "捕食・産卵",
  str_skill_name_290500103 = "巻狩",
  str_skill_name_290500113 = "巻狩＋",
  str_skill_name_290500104 = "群れの召集",
  str_skill_name_290500114 = "群れの召集＋",
  str_skill_desc_290500102 = "スパイダークイーンが獲物に飛び掛かる。クモの巣を張ってマスをロックし、光霊にダメージを与える。",
  str_skill_desc_290500112 = "スパイダークイーンが獲物に飛び掛かる。クモの巣を張ってマスをロックし、光霊にダメージを与える。さらにフィールド上にクモの卵を設置する",
  str_skill_desc_290500103 = "スパイダークイーンがクモの巣で光霊の周囲のマスをロックする。さらにクイーンに呼び出されたスパイダーベビーが光霊に飛び掛かり、ダメージを与える。",
  str_skill_desc_290500113 = "スパイダークイーンがクモの巣で光霊の周囲のマスをロックする。さらにクイーンに呼び出されたスパイダーベビーが光霊に飛び掛かり、ダメージを与える。ロックされたマスは1ターン後、元に戻る",
  str_skill_desc_290500104 = "スパイダークイーンがベビーを呼び出して攻撃する。スパイダーベビーはクモの巣を張り、大量のマスをロックする。",
  str_skill_desc_290500114 = "スパイダークイーンがベビーを呼び出して攻撃する。スパイダーベビーはクモの巣を張り、大量のマスをロックする。ロックされたマスは1ターン後、元に戻る",
  str_skill_name_200240102 = "巡視",
  str_skill_name_200240103 = "捕食",
  str_skill_name_200240104 = "群れの召集",
  str_skill_desc_200240102 = "スパイダベビーがクモの巣の範囲内を巡回し、敵を発見すると即刻攻撃する。",
  str_skill_desc_200240103 = "スパイダベビーが獲物に飛び掛かり、力ずくで相手を一撃で仕留める。",
  str_skill_desc_200240104 = "スパイダークイーンの号令で、スパイダーベビーが群れとなって襲い掛かる。",
  str_skill_name_290530204 = "恐愕の狂襲",
  str_skill_desc_290530204 = "ヘリオスが恐愕の印の生成順に従って、順次印の位置まで突進し、その後ターゲット周囲に突進して途中および到着地点の一定範囲内のターゲットに大ダメージを与える。また、ヘリオスがフィールド上の恐愕の印をクリアし、さらに恐愕の印の数に応じて一部の損傷値をHPに変換する",
  str_skill_name_290530404 = "恐愕の狂襲",
  str_skill_desc_290530404 = "ヘリオスが恐愕の印の生成順に従って、順次印の位置まで突進し、その後ターゲット周囲に突進して途中および到着地点の一定範囲内のターゲットに大ダメージを与える。また、ヘリオスが一部の損傷値をHPに変換する",
  str_skill_upgrade_desc_16020113 = "能動技強化：<color=#FFFF00>「旧魂召喚」</color>を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16020116 = "能動技強化：<color=#FFFF00>「バーバ・ヤーガの破繭」</color>のCD<color=#FFFF00>ターン-1</color>",
  str_skill_upgrade_refine_desc_16020111 = "装備技強化：シールドを展開している場合、ダメージの基礎強化効果が<color=#FFFF00>15%</color>まで上昇する",
  str_skill_upgrade_refine_desc_16020112 = "能動技強化：<color=#FFFF00>「旧魂召喚」</color>で獲得するシールドが自身のHPの<color=#FFFF00>90%</color>まで上昇する",
  str_skill_upgrade_refine_desc_16020113 = "装備技強化：HPが最低値の時の追加ダメージ強化効果の最高値が<color=#00F6FF>10%</color>になる",
  str_skill_name_2002011 = "焼尽の業火",
  str_skill_name_2002012 = "焼尽の業火",
  str_skill_name_2002013 = "焼尽の業火",
  str_skill_desc_2002011 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002012 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002013 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_passive_name_410201 = "ヴェロニカの援助",
  str_skill_passive_desc_410201 = "シールドを展開している場合、ミヤ・浄魂が与える全てのダメージ+<color=#00F6FF>{1}</color>。さらにシールド値に応じて追加のダメージ強化効果を獲得する。シールド値がチーム最大HPの50%の時、最高である<color=#00F6FF>10%</color>の強化効果を獲得する",
  str_skill_passive_name_420201 = "ヴェロニカの援助",
  str_skill_passive_desc_420201 = "シールドを展開している場合、ミヤ・浄魂が与える全てのダメージ+<color=#00F6FF>{1}</color>。さらにシールド値とその時のHPの割合に応じて、追加のダメージ強化効果を獲得する。シールド値がチーム最大HPの50%の時、最高である<color=#00F6FF>10%</color>の強化効果を獲得する。HPが最低値の時、最高である<color=#00F6FF>5%</color>の強化効果を獲得する。",
  str_skill_passive_desc_4202011 = "シールドを展開している場合、ミヤ・浄魂が与える全てのダメージ+<color=#00F6FF>15%</color>。さらにシールド値とその時のHPの割合に応じて、追加のダメージ強化効果を獲得する。シールド値がチーム最大HPの50%の時、最高である<color=#00F6FF>10%</color>の強化効果を獲得する。HPが最低値の時、最高である<color=#00F6FF>5%</color>の強化効果を獲得する",
  str_skill_passive_desc_4432011 = "シールドを展開している場合、ミヤ・浄魂が与える全てのダメージ+<color=#00F6FF>15%</color>。さらにシールド値とその時のHPの割合に応じて、追加のダメージ強化効果を獲得する。シールド値がチーム最大HPの50%の時、最高である<color=#00F6FF>10%</color>の強化効果を獲得する。HPが最低値の時、最高である<color=#00F6FF>10%</color>の強化効果を獲得する",
  str_skill_name_300201 = "旧魂召喚",
  str_skill_name_330201 = "バーバ・ヤーガの破繭",
  str_skill_name_336201 = "バーバ・ヤーガの破繭",
  str_skill_name_340201 = "バーバ・ヤーガの破繭",
  str_skill_name_346201 = "バーバ・ヤーガの破繭",
  str_skill_desc_300201 = "浄魂状態の時、基礎攻撃力+<color=#00F6FF>15%</color>、かつ通常攻撃で斜め方向に攻撃できる。効果は1ターン持続。ただちにミヤ・浄魂のHP<color=#00F6FF>75%</color>相当のシールドを獲得する",
  str_skill_desc_342201 = "浄魂状態の時、基礎攻撃力+<color=#00F6FF>15%</color>、かつ通常攻撃で斜め方向に攻撃できる。効果は1ターン持続。ただちにミヤ・浄魂のHP<color=#00F6FF>90%</color>相当のシールドを獲得する",
  str_skill_desc_330201 = "<color=#00F6FF>現在のチームHPの7%</color>を消費し、自身の攻撃力の<color=#00F6FF>150%</color>相当のシールドに変える",
  str_skill_desc_336201 = "<color=#00F6FF>現在のチームHPの7%</color>を消費し、自身の攻撃力の<color=#00F6FF>150%</color>相当のシールドに変える",
  str_skill_desc_340201 = "<color=#00F6FF>現在のチームHPの7%</color>を消費し、自身の攻撃力の<color=#00F6FF>150%</color>相当のシールドに変える",
  str_skill_desc_346201 = "<color=#00F6FF>現在のチームHPの7%</color>を消費し、自身の攻撃力の<color=#00F6FF>150%</color>相当のシールドに変える",
