  str_skill_name_3222031 = "占い任せです！",
  str_skill_name_3252031 = "占い任せです！",
  str_skill_desc_3002031 = "チーム最大HPの<color=#00F6FF>15%</color>を消費し、このターンの連鎖時の起点のマスを<color=#00F6FF>火属性のマス</color>と見なす。HPが不足している場合、発動できない",
  str_skill_desc_3022031 = "チーム最大HPの<color=#00F6FF>15%</color>を消費し、このターンの連鎖時の起点のマスを<color=#00F6FF>火属性のマス</color>と見なす。HPが不足している場合、発動できない",
  str_skill_desc_3052031 = "チーム最大HPの<color=#00F6FF>10%</color>を消費し、このターンの連鎖時の起点のマスを<color=#00F6FF>火属性のマス</color>と見なす。HPが不足している場合、発動できない",
  str_skill_desc_3202031 = "チーム最大HPの<color=#00F6FF>15%</color>を消費し、このターンの連鎖時の起点のマスを<color=#00F6FF>万色マス</color>と見なす。HPが不足している場合、発動できない",
  str_skill_desc_3222031 = "チーム最大HPの<color=#00F6FF>15%</color>を消費し、このターンの連鎖時の起点のマスを<color=#00F6FF>万色マス</color>と見なす。HPが不足している場合、発動できない",
  str_skill_desc_3252031 = "チーム最大HPの<color=#00F6FF>10%</color>を消費し、このターンの連鎖時の起点のマスを<color=#00F6FF>万色マス</color>と見なす。HPが不足している場合、発動できない",
  str_skill_passive_name_410203 = "護ってください！",
  str_skill_passive_name_430203 = "護ってください！",
  str_skill_passive_desc_410203 = "チームが<color=#00F6FF>光霊の能動技の効果によってHPを失う</color>たび、ジャキーニの基礎攻撃力の<color=#00F6FF>{1}</color>に相当するシールドを獲得する",
  str_skill_passive_desc_430203 = "チームが<color=#00F6FF>光霊の能動技の効果によってHPを失う</color>たび、ジャキーニの基礎攻撃力の<color=#00F6FF>{1}</color>に相当するシールドを獲得する。ジャキーニ自身がこの効果を発動した場合、シールドの量は<color=#00F6FF>2倍</color>になる",
  str_skill_name_2002021 = "君臨する栄光",
  str_skill_name_2002022 = "君臨する栄光",
