  str_skill_name_3002021 = "永久なる日輪",
  str_skill_name_3032021 = "永久なる日輪",
  str_skill_name_3202021 = "永久なる日輪",
  str_skill_name_3232021 = "永久なる日輪",
  str_skill_name_3402021 = "永久なる日輪",
  str_skill_name_3432021 = "永久なる日輪",
  str_skill_name_3402023 = "永久なる日輪",
  str_skill_name_3432023 = "永久なる日輪",
  str_skill_name_3302022 = "破闇の閃撃",
  str_skill_name_3362022 = "破闇の閃撃",
  str_skill_desc_2002021 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002022 = "<color=#00F6FF>縦、横、斜めの24マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002023 = "<color=#00F6FF>縦、横、斜めの最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える。さらに最も遠い位置にある進入可能なマスのうち、ランダムで1つに滅闇の断刃を設置する。この効果は毎ターン、最多で1回発動",
  str_skill_desc_3002021 = "戦闘開始時、技のCDターン<color=#00F6FF>-3</color>。自身の<color=#00F6FF>周囲3マス</color>内にある敵のいるマスを1つ選び、<color=#00F6FF>500%</color>のダメージを与える。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。滅闇の断刃を1本回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3032021 = "自身の<color=#00F6FF>周囲3マス</color>内の敵のいるマスを1つ選び、<color=#00F6FF>500%</color>のダメージを与える。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。滅闇の断刃を1本回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3202021 = "戦闘開始時、技のCDターン<color=#00F6FF>-3</color>。自身の<color=#00F6FF>周囲3マス</color>内の敵のいるマスを1つ選び、<color=#00F6FF>500%</color>のダメージを与える。さらにターゲットの<color=#00F6FF>最大</color>HP<color=#00F6FF>4%</color>に相当するダメージを与える（追加ダメージは属性相性の影響を受ける）。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。滅闇の断刃を1本回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3232021 = "自身の<color=#00F6FF>周囲3マス</color>内の敵のいるマスを1つ選び、<color=#00F6FF>500%</color>のダメージを与える。さらにターゲットの<color=#00F6FF>最大</color>HP<color=#00F6FF>4%</color>に相当するダメージを与える（追加ダメージは属性相性影響を受ける）。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。滅闇の断刃を1本回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3402021 = "戦闘開始時、技のCDターン<color=#00F6FF>-3</color>。自身の<color=#00F6FF>周囲3マス</color>内の敵のいるマスを1つ選び、<color=#00F6FF>500%</color>のダメージを与える。さらにターゲットの<color=#00F6FF>最大</color>HP<color=#00F6FF>4%</color>に相当するダメージを与える（追加ダメージは属性相性の影響を受ける）。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。滅闇の断刃を1本拾得/回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3432021 = "自身の<color=#00F6FF>周囲3マス</color>内の敵のいるマスを1つ選び、<color=#00F6FF>500%</color>のダメージを与える。さらにターゲットの<color=#00F6FF>最大</color>HP<color=#00F6FF>4%</color>に相当するダメージを与える（追加ダメージは属性相性影響を受ける）。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。滅闇の断刃を1本拾得/回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3402022 = "戦闘開始時、技のCDターン<color=#00F6FF>-3</color>。自身の<color=#00F6FF>周囲3マス</color>内の敵のいるマスを1つ選び、<color=#00F6FF>650%</color>のダメージを与える。さらにターゲットの<color=#00F6FF>最大</color>HP<color=#00F6FF>4%</color>に相当するダメージを与える（追加ダメージは属性相性の影響を受ける）。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。滅闇の断刃を1本拾う/回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3432022 = "自身の<color=#00F6FF>周囲3マス</color>内の敵のいるマスを1つ選び、<color=#00F6FF>650%</color>のダメージを与える。さらにターゲットの<color=#00F6FF>最大</color>HP<color=#00F6FF>4%</color>に相当するダメージを与える（追加ダメージは属性相性の影響を受ける）。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。滅闇の断刃を1本拾得/回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3402023 = "戦闘開始時、技のCDターン<color=#00F6FF>-3</color>。自身の<color=#00F6FF>周囲3マス</color>内の敵のいるマスを1つ選び、<color=#00F6FF>650%</color>のダメージを与える。さらにターゲットの<color=#00F6FF>最大</color>HP<color=#00F6FF>4%</color>に相当するダメージを与える（追加ダメージは属性相性の影響を受ける）。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。ターゲットを撃破した場合、ターゲットの位置にも滅闇の断刃を1本設置する。滅闇の断刃を1本拾得/回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3432023 = "自身の<color=#00F6FF>周囲3マス</color>内の敵のいるマスを1つ選び、<color=#00F6FF>650%</color>のダメージを与える。さらにターゲットの<color=#00F6FF>最大</color>HP<color=#00F6FF>4%</color>に相当するダメージを与える（追加ダメージは属性相性の影響を受ける）。その後、選択したマスの周囲2マス内にある進入可能なマスのうち、ランダムで<color=#00F6FF>3</color>マスに滅闇の断刃を設置する。ターゲットを撃破した場合、ターゲットの位置にも滅闇の断刃を1本設置する。滅闇の断刃を1本拾得/回収するたびに、技のCDターン<color=#00F6FF>-1</color>",
  str_skill_desc_3302022 = "滅闇の断刃を<color=#00F6FF>1</color>本選択し、回収する",
  str_skill_desc_3362022 = "滅闇の断刃を<color=#00F6FF>1</color>本選択し、回収する",
  str_skill_passive_name_410202 = "あまねき光",
  str_skill_passive_name_420202 = "あまねき光",
  str_skill_passive_name_430202 = "あまねき光",
  str_skill_passive_desc_410202 = "滅闇の断刃を回収するたびに砕夜の光耀を1スタック獲得し、次の通常攻撃で砕夜の光耀を1スタック消費してターゲットに追加で<color=#00F6FF>現在</color>のHP<color=#00F6FF>{1}</color>に相当するダメージを与える（追加ダメージは基礎攻撃力の<color=#00F6FF>{2}</color>以上、<color=#00F6FF>{3}</color>以下）",
  str_skill_passive_desc_420202 = "滅闇の断刃を回収するたびに砕夜の光耀を1スタック獲得し、次の通常攻撃で砕夜の光耀を1スタック消費してターゲットに追加で<color=#00F6FF>現在</color>のHP<color=#00F6FF>{1}</color>に相当するダメージを与える（追加ダメージは基礎攻撃力の<color=#00F6FF>{2}</color>以上、<color=#00F6FF>{3}</color>以下）",
  str_skill_passive_desc_430202 = "滅闇の断刃を拾得/回収するたびに砕夜の光耀を1スタック獲得し、次の通常攻撃で砕夜の光耀を1スタック消費してターゲットに追加で<color=#00F6FF>現在</color>のHP<color=#00F6FF>{1}</color>に相当するダメージを与える（追加ダメージは基礎攻撃力の<color=#00F6FF>{2}</color>以上、<color=#00F6FF>{3}</color>以下）",
  str_skill_passive_desc_440202 = "滅闇の断刃を習得/回収するたびに、砕夜の光耀を1スタック獲得し、次の通常攻撃で砕夜の光耀を1スタックを消費してターゲットに追加で<color=#00F6FF>現在</color>のHP<color=#00F6FF>4%</color>に相当するダメージを与える（追加ダメージは基礎攻撃力の<color=#00F6FF>150%</color>以上、<color=#00F6FF>600%</color>以下）",
  str_skill_upgrade_desc_16020213 = "能動技強化：<color=#FFFF00>「永久なる日輪」</color>を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16020216 = "能動技強化：<color=#FFFF00>「破闇の閃撃」</color>のCDターン<color=#FFFF00>-1</color>（覚醒3で有効）",
  str_skill_upgrade_refine_desc_16020211 = "装備技強化：追加ダメージの上限が自身の攻撃力の<color=#00F6FF>600%</color>以下まで上昇する",
  str_skill_upgrade_refine_desc_16020212 = "能動技強化：ダメージが<color=#00F6FF>650%</color>に上昇する",
  str_skill_upgrade_refine_desc_16020213 = "能動技強化：ターゲットを撃破した場合、ターゲットの位置にも滅闇の断刃を1本設置する",
  str_skill_upgrade_refine_desc_15007811 = "装備技強化：敵の足元にある森属性のマス1つにつき、ダメージ強化+<color=#00F6FF>1%</color>",
  str_skill_upgrade_refine_desc_15007812 = "能動技強化：範囲の中心のマスのダメージが2倍になる",
  str_skill_upgrade_refine_desc_15007813 = "能動技強化：前のターンで能動技が発動可能だった場合、このターンの選択範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_passive_desc_4400781 = "森属性のマスにいる敵に対するロビンの与ダメージ+<color=#00F6FF>10%</color>。敵の足元にある森属性のマス1つにつき、ダメージ強化+<color=#00F6FF>1%</color>。チーム内の他の森属性の光霊がその<color=#00F6FF>半分</color>のダメージ強化を獲得する",
