  str_skill_desc_3420782 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>250%</color>のダメージを与え、中心のマスには2倍のダメージを与える。さらに敵のいるマス1つを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える",
  str_skill_desc_3400783 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>250%</color>のダメージを与え、中心のマスに2倍のダメージを与える。前のターンで能動技が発動可能だった場合、このターンの選択範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_desc_3420783 = "1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>250%</color>のダメージを与え、中心のマスには2倍のダメージを与える。さらに敵のいるマス1つを<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。前のターンで能動技が発動可能だった場合、このターンの選択範囲が<color=#00F6FF>周囲2マス</color>になる",
  str_skill_upgrade_refine_desc_15007511 = "装備技強化：通常攻撃に毒状態を付与する確率が<color=#00F6FF>80%</color>まで上昇する。",
