  str_skill_desc_352075 = "<color=#00F6FF>周囲3マス</color>以内にいる敵に攻撃力の500%のダメージを与え、2ターン持続する<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態にする。さらに2ターン持続する<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を2スタック付与する。戦闘開始時、技のCDターン<color=#00F6FF>-2</color>",
  str_skill_desc_355075 = "<color=#00F6FF>全て</color>の敵に攻撃力の500%のダメージを与え、2ターン持続する<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態にする。さらに2ターン持続する<link=\"10001\"><#FFAE07><u>毒</u></color></link>状態を2スタック付与する。戦闘開始時、技のCDターン<color=#00F6FF>-2</color>",
