  str_skill_desc_2202041 = "最も近くにいるターゲット2体に<color=#00F6FF>{1}%</color>のダメージを与える。ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>50%</color>",
  str_skill_desc_2202042 = "最も近くにいるターゲット2体に<color=#00F6FF>{1}%</color>のダメージを与える。ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>50%</color>",
  str_skill_desc_2202043 = "最も近くにいるターゲット2体に<color=#00F6FF>{1}%</color>のダメージを与える。ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>50%</color>",
  str_skill_desc_2302041 = "最も近くにいるターゲット2体に<color=#00F6FF>{1}%</color>のダメージを与える。3マス以内にいるターゲットに対するダメージ+<color=#00F6FF>30%</color>。ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>50%</color>",
  str_skill_desc_2302042 = "最も近くにいるターゲット2体に<color=#00F6FF>{1}%</color>のダメージを与える。3マス以内にいるターゲットに対するダメージ+<color=#00F6FF>30%</color>。ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>50%</color>",
  str_skill_desc_2302043 = "最も近くにいるターゲット2体に<color=#00F6FF>{1}%</color>のダメージを与える。3マス以内にいるターゲットに対するダメージ+<color=#00F6FF>30%</color>。ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>50%</color>",
  str_skill_desc_2502041 = "最も近くにいるターゲット2体に<color=#00F6FF>140%</color>のダメージを与える。3マス以内にいるターゲットに対するダメージ+<color=#00F6FF>30%</color>。ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>65%</color>",
  str_skill_desc_2502042 = "最も近くにいるターゲット2体に<color=#00F6FF>155%</color>のダメージを与える。3マス以内にいるターゲットに対するダメージ+<color=#00F6FF>30%</color>。ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>65%</color>",
  str_skill_desc_2502043 = "最も近くにいるターゲット2体に<color=#00F6FF>170%</color>のダメージを与える。3マス以内にいるターゲットに対するダメージ+<color=#00F6FF>30%</color>。ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>65%</color>",
  str_skill_desc_3002041 = "ターゲットを1体選択し、相手を<link=\"30083\"><#FFAE07><u>聖裁</u></color></link>状態にした上で、<color=#00F6FF>ヨシュアの攻撃力の200%</color>と同等の聖裁値を加える。最大HPがないターゲットに対しては、<color=#00F6FF>200%</color>の防御力無視のダメージを直接与える。繰り返し発動すると聖裁値は累積される。ターゲットの聖裁値が現在のHPを超えた時、シールド無視の即死ダメージを与える（ただし、HP固定の影響を受ける）",
  str_skill_desc_3032041 = "ターゲットを1体選択し、相手を<link=\"30083\"><#FFAE07><u>聖裁</u></color></link>状態にした上で、<color=#00F6FF>ヨシュアの攻撃力の250%</color>と同等の聖裁値を加える。最大HPがないターゲットに対しては、<color=#00F6FF>250%</color>の防御力無視のダメージを直接与える。繰り返し発動すると聖裁値は累積される。ターゲットの聖裁値が現在のHPを超えた時、シールド無視の即死ダメージを与える（ただし、HP固定の影響を受ける）",
  str_skill_desc_3062041 = "ターゲットを1体選択し、相手を<link=\"30083\"><#FFAE07><u>聖裁</u></color></link>状態にした上で、<color=#00F6FF>ヨシュアの攻撃力の250%+ターゲットの最大HPの3%</color>と同等（ヨシュアの攻撃力の<color=#00F6FF>120%</color>を下回らない）の聖裁値を加える。最大HPがないターゲットに対しては、<color=#00F6FF>370%</color>の防御力無視のダメージを直接与える。繰り返し発動すると聖裁値は累積される。ターゲットの聖裁値が現在のHPを超えた時、シールド無視の即死ダメージを与える（ただし、HP固定の影響を受ける）",
  str_skill_passive_desc_4102041 = "<link=\"30083\"><#FFAE07><u>聖裁</u></color></link>状態の敵に対してヨシュアが<color=#00F6FF>{1}</color>の攻撃を行い、すべてのシールドを無視し、そのダメージを聖裁値に変換して与える",
  str_skill_upgrade_refine_desc_16020411 = "装備技強化：聖裁状態のターゲットに対する全ダメージが<color=#00F6FF>124%</color>に上昇する",
  str_skill_upgrade_refine_desc_16020412 = "連鎖技強化：ターゲットが1体しかいない場合、ダメージ+<color=#00F6FF>65%</color>",
  str_skill_upgrade_refine_desc_16020413 = "能動技強化：聖裁状態のターゲットを撃破すると、ただちに能動技のCDが更新される",
  str_skill_desc_3502041 = "ターゲットを1体選択し、相手を<link=\"30083\"><#FFAE07><u>聖裁</u></color></link>状態にした上で、<color=#00F6FF>ヨシュアの攻撃力の200%</color>と同等の聖裁値を加える。最大HPがないターゲットに対しては、<color=#00F6FF>200%</color>の防御力無視のダメージを直接与える。繰り返し発動すると聖裁値は累積される。ターゲットの聖裁値が現在のHPを超えた時、シールド無視の即死ダメージを与える（ただし、HP固定の影響を受ける）。聖裁状態のターゲットを撃破すると、ただちに能動技のCDが更新される",
  str_skill_desc_3532041 = "ターゲットを1体選択し、相手を<link=\"30083\"><#FFAE07><u>聖裁</u></color></link>状態にした上で、<color=#00F6FF>ヨシュアの攻撃力の250%</color>と同等の聖裁値を加える。最大HPがないターゲットに対しては、<color=#00F6FF>250%</color>の防御力無視のダメージを直接与える。繰り返し発動すると聖裁値は累積される。ターゲットの聖裁値が現在のHPを超えた時、シールド無視の即死ダメージを与える（ただし、HP固定の影響を受ける）。聖裁状態のターゲットを撃破すると、ただちに能動技のCDが更新される",
  str_skill_desc_3562041 = "ターゲットを1体選択し、相手を<link=\"30083\"><#FFAE07><u>聖裁</u></color></link>状態にした上で、<color=#00F6FF>ヨシュアの攻撃力の250%+ターゲットの最大HPの3%</color>と同等（ヨシュアの攻撃力の<color=#00F6FF>120%</color>を下回らない）の聖裁値を加える。最大HPがないターゲットに対しては、<color=#00F6FF>370%</color>の防御力無視のダメージを直接与える。繰り返し発動すると聖裁値は累積される。ターゲットの聖裁値が現在のHPを超えた時、シールド無視の即死ダメージを与える（ただし、HP固定の影響を受ける）。聖裁状態のターゲットを撃破すると、ただちに能動技のCDが更新される",
  str_skill_passive_desc_4502041 = "<link=\"30083\"><#FFAE07><u>聖裁</u></color></link>状態の敵に対してヨシュアが<color=#00F6FF>124%</color>の攻撃を行い、あらゆるシールドを無視し、そのダメージを聖裁値に変換して与える",
