  str_skill_desc_2302052 = "<color=#00F6FF>縦、横、斜めの16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内の損傷マスの持続ターン<color=#00F6FF>-2</color>",
  str_skill_desc_2302053 = "<color=#00F6FF>縦、横、斜めの24マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内の損傷マスの持続ターン<color=#00F6FF>-3</color>",
  str_skill_desc_2362051 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内の損傷マスの持続ターン<color=#00F6FF>-2</color>",
  str_skill_desc_2362052 = "<color=#00F6FF>縦、横、斜めの16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内の損傷マスの持続ターン<color=#00F6FF>-3</color>",
  str_skill_desc_2362053 = "<color=#00F6FF>縦、横、斜めの24マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内の損傷マスの持続ターン<color=#00F6FF>-4</color>",
  str_skill_desc_3002051 = "損傷マス以外の1マスを選び、その位置に9ターン持続する損傷マスを1つ作り出す。その後、そのマスと<color=#00F6FF>十字方向に隣接する4マス</color>を水属性のマスに変える",
  str_skill_desc_3052051 = "損傷マス以外の1マスを選び、その位置に9ターン持続する損傷マスを1つ作り出す。その後、そのマスと<color=#00F6FF>十字方向に隣接する4マス</color>を水属性のマスに変える",
  str_skill_passive_name_410205 = "面会の作法",
  str_skill_passive_name_430205 = "面会の作法",
  str_skill_passive_desc_410205 = "ブラン・洗心は水属性のマス上にいる時、通常攻撃を行わない。水属性のマスを1マス通過するごとに、そのマスと<color=#00F6FF>十字方向に隣接する4マス</color>に敵がいる場合、面会の印を1スタック獲得する。印1スタックにつき、連鎖技のダメージ倍率+<color=#00F6FF>{1}</color>。また、連鎖技発動条件<color=#00F6FF>-1</color>。連鎖技を発動すると印はクリアされる",
  str_skill_passive_desc_430205 = "ブラン・洗心は水属性のマス上にいる時、通常攻撃を行わない。水属性のマスを1マス通過するごとに、そのマスと<color=#00F6FF>十字方向に隣接する4マス</color>に敵がいる、または損傷マスがある場合、面会の印を1スタック獲得する。印1スタックにつき、連鎖技のダメージ倍率+<color=#00F6FF>{1}</color>。また、連鎖技発動条件<color=#00F6FF>-1</color>。連鎖技を発動すると印はクリアされる",
  str_skill_upgrade_desc_15020512 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15020515 = "連鎖技強化：連鎖技の範囲内にある損傷マスの持続ターン-<color=#FFFF00>2/3/4</color>（覚醒2で有効）",
  str_skill_passive_desc_440097 = "通常攻撃が2連続攻撃になり、それぞれのダメージは基本ダメージの<color=#00F6FF>60%</color>になる。それぞれの攻撃が<color=#00F6FF>20%</color>の確率でダメージ+<color=#00F6FF>50%</color>になる。コンボ1回につき、発動確率+<color=#00F6FF>1%</color>、最大+50%",
  str_skill_name_3400971 = "抜骨・変異Ⅰ",
  str_skill_name_3400972 = "抜骨・変異Ⅱ",
  str_skill_name_3420971 = "抜骨・変異Ⅰ",
  str_skill_name_3420972 = "抜骨・変異Ⅱ",
  str_skill_desc_3400971 = "<color=#FFFF00>発動後、CD+1</color>。任意の位置に瞬間移動し、移動前と移動後の地点を結ぶ四角形の範囲内の敵にダメージを与える。四角形の面積が小さいほど与えるダメージは大きくなり、最大で<color=#00F6FF>600%</color>のダメージを与える",
  str_skill_desc_3400972 = "<color=#FFFF00>発動後、CD-1</color>。<color=#FFFF00>周囲3マス</color>の任意の位置に瞬間移動し、移動前と移動後の地点を結ぶ四角形の範囲内の敵にダメージを与える。四角形の面積が小さいほど与えるダメージは大きくなり、最大で<color=#00F6FF>360%</color>のダメージを与える",
  str_skill_desc_3420971 = "<color=#FFFF00>発動後、CD+1</color>。任意の位置に瞬間移動し、移動前と移動後の地点を結ぶ四角形の範囲内の敵にダメージを与える。四角形の面積が小さいほど与えるダメージは大きくなり、最大で<color=#00F6FF>720%</color>のダメージを与える",
  str_skill_desc_3420972 = "<color=#FFFF00>発動後、CD-1</color>。<color=#FFFF00>周囲3マス</color>の任意の位置に瞬間移動し、移動前と移動後の地点を結ぶ四角形の範囲内の敵にダメージを与える。四角形の面積が小さいほど与えるダメージは大きくなり、最大で<color=#00F6FF>480%</color>のダメージを与える",
  str_skill_upgrade_refine_desc_15009711 = "<color=#00F6FF>能動技変異Ⅰ追加</color>：<color=#FFFF00>発動後、CD+1</color>。任意の位置に瞬間移動し、移動前と移動後の地点を結ぶ四角形の範囲内の敵にダメージを与える。四角形の面積が小さいほど与えるダメージは大きくなり、能動技の与ダメージ+<color=#FFFF00>120%</color>",
  str_skill_upgrade_refine_desc_15009712 = "装備技強化：コンボ1回につき、ダメージ増加発動確率が追加で+<color=#00F6FF>1%</color>、最大50%",
  str_skill_upgrade_refine_desc_15009713 = "<color=#00F6FF>能動技変異Ⅱ追加</color>：<color=#FFFF00>発動後、CD-1</color>。<color=#FFFF00>周囲3マス</color>の任意の位置に瞬間移動し、移動前と移動後の地点を結ぶ四角形の範囲内の敵にダメージを与える。四角形の面積が小さいほど与えるダメージは大きくなり、能動技の与ダメージ-<color=#FFFF00>120%</color>",
  str_skill_upgrade_refine_desc_16002711 = "能動技強化：能動技のダメージ係数が<color=#00F6FF>360%</color>に上昇",
  str_skill_upgrade_refine_desc_16002712 = "装備技強化：能動技発動時に静雷の印<color=#00F6FF>2</color>スタックを獲得する",
  str_skill_upgrade_refine_desc_16002713 = "装備技強化：通常攻撃時に静雷の印を1スタック消費し、敵に現在のHPの<color=#00F6FF>2.5%</color>の追加ダメージを与える。このダメージはミカエルの攻撃力の<color=#00F6FF>50%</color>を下回らない",
  str_skill_desc_3400271 = "選択した位置までダッシュし、途中のマスおよび隣接するマスの敵に<color=#00F6FF>360%</color>のダメージを与える。さらに敵の現在のHPの<color=#00F6FF>5%</color>のダメージを追加で与える",
  str_skill_desc_3430271 = "選択した位置までダッシュし、途中のマスおよび隣接するマスの敵に<color=#00F6FF>360%</color>のダメージを与える。さらに敵の現在のHPの<color=#00F6FF>5%</color>のダメージを追加で与え、移動距離に応じて選択した位置で連鎖技を1回発動する",
  str_skill_desc_3400272 = "選択した位置までダッシュし、途中のマスおよび隣接するマスの敵に<color=#00F6FF>360%</color>のダメージを与える。さらに敵の現在のHPの<color=#00F6FF>5%</color>のダメージを追加で与える",
  str_skill_desc_3430272 = "選択した位置までダッシュし、途中のマスおよび隣接するマスの敵に<color=#00F6FF>360%</color>のダメージを与える。さらに敵の現在のHPの<color=#00F6FF>5%</color>のダメージを追加で与え、移動距離に応じて選択した位置で連鎖技を1回発動する",
  str_skill_desc_4400271 = "静雷の印を毎ターン開始時および連鎖技の発動時に1スタック、能動技発動時に2スタック獲得する。通常攻撃時に印を1スタック消費して、敵に現在のHP<color=#00F6FF>2.5%</color>の追加ダメージを与える",
  str_skill_desc_440027 = "静雷の印を毎ターン開始時および連鎖技発動時に1スタック、能動技発動時に2スタック獲得する。通常攻撃時に印を1スタック消費して、敵に現在のHP<color=#00F6FF>2.5%</color>の追加ダメージを与える。このダメージはミカエルの攻撃力の<color=#00F6FF>50%</color>を下回らない",
  str_skill_name_490250101 = "末極・幻像刷新",
  str_skill_desc_490250101 = "末極・ミノスが周囲2マス内の弱化マスと強化マスを吸収し、周囲1マス内のターゲットにダメージを与える。その時吸収したマスの数に応じてダメージが増幅する",
  str_skill_name_490250102 = "末極・終の生け贄",
  str_skill_desc_490250102 = "末極・ミノスがフィールド上にあるすべての弱化マスと強化マスを吸収した後光霊に向かって射撃し、ダメージを与える。1マス吸収するごとに追加で1回のダメージを与える",
  str_skill_name_490250103 = "末極・幻像刷新+",
  str_skill_desc_490250103 = "末極・ミノスが周囲2マス内の弱化マスと強化マスを吸収し、周囲1マス内のターゲットにダメージを与える。その時吸収したマスの数に応じてダメージが増幅する",
  str_skill_name_490250104 = "末極・終の生け贄+",
  str_skill_desc_490250104 = "末極・ミノスがフィールド上にあるすべての弱化マスと強化マスを吸収した後光霊に向かって射撃し、ダメージを与える。1マス吸収するごとに追加で1回のダメージを与える",
  str_skill_upgrade_refine_desc_16002811 = "装備技強化：回復係数が<color=#00F6FF>1.8%</color>に上昇",
  str_skill_upgrade_refine_desc_16002812 = "能動技強化：回復係数が<color=#00F6FF>250%</color>に上昇",
  str_skill_upgrade_refine_desc_16002813 = "能動技強化：チームHPが低いほど回復効果が高くなり、最大で<color=#00F6FF>100%加算</color>される",
  str_skill_passive_desc_450028 = "マップに水属性のマスが生成される度に、1マスにつきラファエルの最大HPの<color=#00F6FF>1.8%</color>相当のチームHPを回復する。チームのHPが低いほど回復効果が高くなり、最大で<color=#00F6FF>+100%</color>",
  str_skill_desc_350028 = "ラファエルの攻撃力の<color=#00F6FF>250%</color>相当のチームHPを回復し、<color=#00F6FF>全ての非水属性</color>のマスをリセットする",
  str_skill_desc_356028 = "ラファエルの攻撃力の<color=#00F6FF>250%</color>相当のチームHPを回復する。さらに<color=#00F6FF>全ての非水属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で水属性のマスに変える",
  str_skill_desc_360028 = "ラファエルの攻撃力の<color=#00F6FF>250%</color>相当のチームHPを回復する。さらに<color=#00F6FF>全ての非水属性</color>のマスをリセットする。チームHPが低いほど回復効果が高くなり、最大で<color=#00F6FF>100%増加</color>する",
  str_skill_desc_366028 = "ラファエルの攻撃力の<color=#00F6FF>250%</color>相当のチームHPを回復する。さらに<color=#00F6FF>全ての非水属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で水属性のマスに変える。チームHPが低いほど回復効果が高くなり、最大で<color=#00F6FF>100%増加</color>する",
  str_skill_upgrade_refine_desc_15007011 = "能動技強化：ダメージ係数が<color=#00F6FF>100%</color>に上昇",
  str_skill_upgrade_refine_desc_15007012 = "装備技強化：ダメージ係数が<color=#00F6FF>60%</color>に上昇",
  str_skill_upgrade_refine_desc_15007013 = "能動技強化：ダメージを与えるごとに<color=#00F6FF>25%</color>の確率で敵に<link=\"10002\"><#FFAE07><u>火傷</u></color></link>を1スタック付与する",
  str_skill_desc_350070 = "戦場のランダムな敵に<color=#00F6FF>100%</color>のダメージを<color=#00F6FF>5</color>回与え、現在地の<color=#00F6FF>周囲1マス</color>にある火属性のマス1つにつき、追加で1回攻撃する",
  str_skill_desc_355070 = "戦場のランダムな敵に<color=#00F6FF>100%</color>のダメージを<color=#00F6FF>6</color>回与え、現在地の<color=#00F6FF>菱形12マス</color>以内にある火属性のマス1つにつき、追加で1回攻撃する",
  str_skill_desc_360070 = "戦場のランダムな敵に<color=#00F6FF>100%</color>のダメージを<color=#00F6FF>5</color>回与え、現在地の<color=#00F6FF>周囲1マス</color>にある火属性のマス1つにつき、追加で1回攻撃する。ダメージを与えるごとに<color=#00F6FF>25%</color>の確率で敵に<link=\"10002\"><#FFAE07><u>火傷</u></color></link>を1スタック付与する",
  str_skill_desc_365070 = "戦場のランダムな敵に<color=#00F6FF>100%</color>のダメージを<color=#00F6FF>6</color>回与え、現在地の<color=#00F6FF>菱形12マス</color>にある火属性のマス1つにつき、追加で1回攻撃する。ダメージを与えるごとに<color=#00F6FF>25%</color>の確率で敵に<link=\"10002\"><#FFAE07><u>火傷</u></color></link>を1スタック付与する",
  str_skill_passive_desc_450070 = "通常攻撃時、<color=#00F6FF>75%</color>の確率で赤龍が攻撃を1回行う。ダメージはリオナの通常攻撃のダメージの<color=#00F6FF>60%</color>。さらに<link=\"10002\"><#FFAE07><u>火傷</u></color></link>を1スタック付与、2ターン持続",
  str_skill_desc_400140110 = "光霊が移動を開始した後、触手を縮めて攻撃を回避し、ミレン・ゴーティエのHPを回復させる",
  str_skill_upgrade_desc_16020713 = "装備技強化：発動に必要な水紋のスタック数が5に低下。消費する水紋のスタック数が5の倍数に低下（覚醒1で有効）",
  str_skill_upgrade_desc_16020716 = "能動技強化：選択したマスを水属性に変える",
  str_skill_name_2002071 = "苦楽共生",
  str_skill_name_2002072 = "苦楽共生",
  str_skill_name_2002073 = "苦楽共生",
  str_skill_desc_2002071 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002072 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002073 = "<color=#00F6FF>縦、横、斜めの16マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_name_3002071 = "醒夢の舞踏",
  str_skill_name_3062071 = "醒夢の舞踏",
  str_skill_name_3202071 = "醒夢の舞踏",
  str_skill_name_3262071 = "醒夢の舞踏",
  str_skill_name_3302071 = "醒夢の舞踏",
  str_skill_name_3362071 = "醒夢の舞踏",
  str_skill_desc_3002071 = "1マス選択し、その列上の水属性のマスを選択したマスの方向に<link=\"30084\"><#FFAE07><u>集合</u></color></link>させる",
  str_skill_desc_3062071 = "1マス選択し、そのマスを水属性に変え、その列上の水属性のマスを選択したマスの方向に<link=\"30084\"><#FFAE07><u>集合</u></color></link>させる",
  str_skill_desc_3202071 = "1マス選択し、その列上の水属性のマスを選択したマスの方向に<link=\"30084\"><#FFAE07><u>集合</u></color></link>させる。繰り返しタップすると範囲の<color=#00F6FF>行/列</color>を切り替えられる",
  str_skill_desc_3262071 = "1マス選択し、そのマスを水属性に変え、その列上の水属性のマスを選択したマスの方向に<link=\"30084\"><#FFAE07><u>集合</u></color></link>させる。繰り返しタップすると範囲の<color=#00F6FF>行/列</color>を切り替えられる",
  str_skill_desc_3302071 = "1マス選択し、その列上の水属性のマスを選択したマスの方向に<link=\"30084\"><#FFAE07><u>集合</u></color></link>させる。繰り返しタップすると範囲の<color=#00F6FF>行/列</color>を切り替えられる。能動技の範囲内にある水属性のマス1つにつき、水紋を1スタック獲得する",
  str_skill_desc_3362071 = "1マス選択し、そのマスを水属性に変え、その列上の水属性のマスを選択したマスの方向に<link=\"30084\"><#FFAE07><u>集合</u></color></link>させる。繰り返しタップすると範囲の<color=#00F6FF>行/列</color>を切り替えられる。能動技の範囲内にある水属性のマス1つにつき、水紋を1スタック獲得する",
  str_skill_passive_name_410207 = "蜻蛉とさざ波",
  str_skill_passive_desc_410207 = "チーム内の光霊がこのターンで初めて能動技を発動するとき、セナが<link=\"30085\"><#FFAE07><u>水紋</u></color></link>を1スタック獲得する。獲得時に水紋が7スタック以上の場合、水紋を消費してセナの最大HPの<color=#00F6FF>{1}</color>相当のHPを回復する",
  str_skill_passive_name_416207 = "蜻蛉とさざ波",
  str_skill_passive_desc_416207 = "チーム内の光霊がこのターンで初めて能動技を発動するとき、セナが<link=\"30086\"><#FFAE07><u>水紋</u></color></link>を1スタック獲得する。獲得時に水紋が5スタック以上の場合、水紋を消費してセナの最大HPの<color=#00F6FF>{1}</color>相当のHPを回復する",
  str_skill_desc_350025 = "<color=#00F6FF>3列</color>または<color=#00F6FF>3行</color>を選択し、<color=#00F6FF>300%</color>のダメージを与え、敵をノックバックする。中央の行か列のダメージは両側の1.7倍。範囲内の<color=#00F6FF>非火属性</color>のマスをリセットする",
  str_skill_desc_356025 = "<color=#00F6FF>3列</color>または<color=#00F6FF>3行</color>を選択し、<color=#00F6FF>300%</color>のダメージを与え、敵をノックバックする。中央の行か列のダメージは両側の1.7倍。範囲内の<color=#00F6FF>非火属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で火属性のマスに変える",
  str_skill_desc_360025 = "<color=#00F6FF>3列</color>か<color=#00F6FF>3行</color>かを選んで、<color=#00F6FF>340%</color>のダメージを与え、敵をノックバックする。中央の行か列のダメージは両側の1.7倍。範囲内の<color=#00F6FF>非火属性</color>のマスをリセットする",
  str_skill_desc_366025 = "<color=#00F6FF>3列</color>または<color=#00F6FF>3行</color>を選択し、<color=#00F6FF>340%</color>のダメージを与え、敵をノックバックする。中央の行か列のダメージは両側の1.7倍。範囲内の<color=#00F6FF>非火属性</color>のマスをリセットし、<color=#00F6FF>低確率</color>で火属性のマスに変える",
  str_skill_passive_desc_440025 = "通常攻撃で<color=#00F6FF>斜め方向</color>に攻撃できる。さらに通常攻撃に攻撃力<color=#00F6FF>12%</color>の防御力無視のダメージを付与する",
  str_skill_upgrade_refine_desc_16002511 = "装備技強化：ダメージ係数が<color=#00F6FF>12%</color>に上昇する",
  str_skill_upgrade_refine_desc_16002512 = "能動技強化：中央の行か列のダメージが<color=#00F6FF>1.7</color>倍になる",
  str_skill_upgrade_refine_desc_16002513 = "能動技強化：ダメージ係数が<color=#00F6FF>340%</color>に上昇する",
  str_skill_name_2002061 = "キャピタライズ",
  str_skill_name_2002062 = "キャピタライズ",
  str_skill_name_2002063 = "キャピタライズ",
  str_skill_desc_2002061 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002062 = "<color=#00F6FF>周囲1マス以内</color>およびその<color=#00F6FF>十字方向に連鎖する</color>火属性のマスに<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002063 = "<color=#00F6FF>周囲1マス以内</color>およびその<color=#00F6FF>8方向に連鎖する</color>火属性のマスに<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_name_3002061 = "ジャックポット",
  str_skill_name_3062061 = "ジャックポット",
  str_skill_desc_3002061 = "1マス選択し、<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲のマスを火属性に変える",
  str_skill_desc_3062061 = "1マス選択し、<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与え、敵をノックバックする。さらに攻撃範囲のマスを火属性に変える",
  str_skill_passive_name_410206 = "リスクヘッジ",
  str_skill_passive_name_420206 = "リスクヘッジ",
  str_skill_passive_name_430206 = "リスクヘッジ",
  str_skill_passive_desc_410206 = "新能動技獲得：先制攻撃、<color=#00F6FF>十字方向に隣接する</color>マスから1つ選択し、そのマスを火属性に変える。さらに<color=#00F6FF>{1}</color>のダメージを与え、マスを粉砕する",
  str_skill_passive_desc_420206 = "新能動技獲得：先制攻撃、<color=#00F6FF>十字方向に隣接する</color>マスから1つ選択し、そのマスを火属性に変える。さらに<color=#00F6FF>{1}</color>のダメージを与え、マスを粉砕する。ターゲットの現在のHPが低いほど与ダメージが大きくなる。最大で+<color=#00F6FF>250%</color>",
