  str_skill_desc_33020624 = "新能動技獲得：先制攻撃、<color=#00F6FF>周囲1マス</color>から1つ選択し、そのマスを火属性に変える。さらに<color=#00F6FF>{1}%</color>のダメージを与え、マスを粉砕する。ターゲットの現在のHPが低いほど与ダメージが大きくなる。最大で+<color=#00F6FF>250%</color>",
  str_skill_upgrade_desc_16020613 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16020616 = "能動技強化：技のクールダウンターン<color=#FFFF00>-1</color>。",
  str_skill_upgrade_refine_desc_15002411 = "装備技強化：ダメージ係数が<color=#00F6FF>65%</color>に上昇する",
  str_skill_upgrade_refine_desc_15002412 = "能動技強化：2ヵ所の連鎖技の最終ダメージがいずれも+<color=#00F6FF>35%</color>",
  str_skill_upgrade_refine_desc_15002413 = "連鎖技強化：能動技を発動したターンで、連鎖を発動させるのに必要なマス数が<color=#00F6FF>-1</color>",
  str_skill_passive_desc_440024 = "火属性のマスにいる敵に対して通常攻撃をすると、<color=#00F6FF>65%</color>のダメージを追加で与える",
  str_skill_desc_340024 = "マス1つをマークする。今回の連鎖マスの数が連鎖技発動に必要な数の<color=#00F6FF>1.5</color>倍に到達すると、マークした位置でも連鎖技を1回発動する（2ヵ所の連鎖技の最終ダメージはいずれも+<color=#00F6FF>35%</color>）",
  str_skill_desc_342024 = "マス1つをマークする。今回の連鎖マスの数が連鎖技発動に必要な数の<color=#00F6FF>1.5</color>倍に到達すると、マークした位置でも連鎖技を1回発動する（2ヵ所の連鎖技の最終ダメージはいずれも+<color=#00F6FF>35%</color>）",
  str_skill_desc_345024 = "マス1つをマークする。今回の連鎖マスの数が連鎖技発動に必要な数の<color=#00F6FF>1.5</color>倍に到達すると、マークした位置でも連鎖技を1回発動する（2ヵ所の連鎖技の最終ダメージはいずれも+<color=#00F6FF>35%</color>）",
  str_skill_desc_240241 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>140%</color>のダメージを与える。能動技を発動したターン中、連鎖発動に必要なマス数が<color=#00F6FF>-1</color>",
  str_skill_desc_240242 = "<color=#00F6FF>菱形12マス</color>以内に<color=#00F6FF>145%</color>のダメージを与える。能動技を発動したターン中、連鎖発動に必要なマス数が<color=#00F6FF>-1</color>",
  str_skill_desc_240243 = "<color=#00F6FF>縦、横、斜めの16マス</color>以内に<color=#00F6FF>155%</color>のダメージを与える。能動技を発動したターン中、連鎖発動に必要なマス数が<color=#00F6FF>-1</color>",
  str_skill_name_290560101 = "メガミチョウ・藤棘",
  str_skill_desc_290560101 = "光霊に向かって移動した後、前方1行か1列の範囲内にいるターゲットに大ダメージを与える",
  str_skill_name_290560102 = "メガミチョウ・授粉",
  str_skill_desc_290560102 = "光霊に向かって移動した後、自身の周囲菱形12マスの範囲内にいるすべてのターゲットにダメージを与え、毒素を付与する。さらに範囲内の植物の生長を促す",
  str_skill_name_290560103 = "メガミチョウ・広爆",
  str_skill_desc_290560103 = "光霊に狙いを定め、その光霊の周囲菱形12マスの範囲内にいるすべてのターゲットにダメージを与え、毒素を付与する。さらに範囲内の植物の生長を促す（必中）",
  str_skill_name_200260101 = "サダスの妖草・休眠",
  str_skill_desc_200260101 = "休眠期にあり、光霊の攻撃を受けない",
  str_skill_name_200260201 = "サダスの妖草・成長",
  str_skill_desc_200260201 = "変態期にあり、光霊からの攻撃を受けるが、光霊を攻撃することはできない",
  str_skill_name_200260301 = "サダスの妖草・醒",
  str_skill_desc_200260301 = "光霊を狙い、ダメージを与える。さらに毒素を付与する",
  str_skill_name_53310002 = "メガミチョウ・授粉",
  str_skill_desc_53310002 = "自身の周囲菱形12マス以内の植物の生長を促す",
  str_skill_desc_3300051 = "<color=#FFFF00>発動後の技のCDターン+1</color>。\n敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）。ソウル1スタックが与える衝撃のダメージが130%になる",
  str_skill_desc_3300052 = "<color=#FFFF00>発動後の技のCDターン-1</color>。\n敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）。光霊の能動技で敵を撃破してもソウルを獲得できない",
  str_skill_desc_3360051 = "<color=#FFFF00>発動後の技のCDターン+1</color>。\n敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）。ソウル1スタックが与える衝撃のダメージが130%になる",
  str_skill_desc_3360052 = "<color=#FFFF00>発動後の技のCDターン-1</color>。\n敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵のHP比率が低いほどダメージが大きくなる（最大+100%）。光霊の能動技で敵を撃破してもソウルを獲得できない",
  str_skill_passive_desc_443005 = "<color=#00F6FF>光霊</color>が能動技で敵を撃破すると、ソウルを1スタック獲得する。最大<color=#00F6FF>8</color>スタック。ソウル1スタックごとに敵1体に攻撃力の<color=#00F6FF>100%</color>の衝撃を1回与え、ミヤの連鎖ダメージ+<color=#00F6FF>5%</color>、通常攻撃のダメージ+<color=#00F6FF>3%</color>",
  str_skill_upgrade_refine_desc_16000511 = "<color=#00F6FF>能動技変異Ⅰを追加</color>：<color=#FFFF00>発動後の技のCDターン+1</color>。ソウル1スタックが与える衝撃のダメージが130%になる",
  str_skill_upgrade_refine_desc_16000512 = "<color=#00F6FF>能動技変異Ⅱを追加</color>：<color=#FFFF00>発動後の技のCDターン-1</color>。光霊の能動技で敵を撃破してもソウルを獲得できない",
  str_skill_upgrade_refine_desc_16000513 = "装備技強化：ソウルのスタック数上限が<color=#00F6FF>8</color>に増える",
  str_skill_desc_8001201 = "即座にシャドウボールを付近に1体召喚する",
  str_skill_desc_8001441 = "全域に大量の灰虫を召喚し、攻撃力を強化するエネルギーの印を30スタック自身に蓄積する",
  str_skill_desc_800128107 = "召喚師がターゲット付近に瞬間移動するとともに一定数のシールドを獲得し、さらに広範囲攻撃発動の準備をする。そのターン、召喚師の防御力が大幅に低下する",
  str_skill_desc_8001391 = "太い尾で攻撃範囲内にいるターゲットを攻撃し、ダメージを2回与える",
  str_skill_desc_800141 = "尾に集めたエネルギーニードルで攻撃範囲内にいるターゲットに遠距離攻撃を行い、ダメージを2回与える",
  str_skill_desc_800139 = "太い尾で攻撃範囲内にいるターゲットを攻撃する",
  str_skill_desc_800140 = "尾に集めたエネルギーニードルで攻撃範囲内のターゲットに遠距離攻撃を行う",
  str_skill_name_52200191 = "醒転・域",
  str_skill_desc_52200191 = "任意のマスを起点として1マス選択し、さらに2×2または1×4の範囲になるよう終点をタップして指定する。指定範囲内のマスを万色マスに変える",
  str_skill_name_5220021 = "醒転・雷鳴",
  str_skill_desc_5220021 = "任意のマスを選択し、正方形9マスの範囲内にランダムで万色マスを5つ生成する",
  str_skill_name_5220024 = "醒転・撃染",
  str_skill_desc_5220024 = "任意のマスを選択し、そのマスの最も近くにある万色マスでも雷属性マスでもない6マスを雷属性3マス3つと万色マス3つに変える",
  str_skill_desc_52200241 = "任意のマスを選択し、そのマスの最も近くにある万色マスでない6マスを万色マスに変える",
  str_skill_name_5220022 = "醒転・断雷",
  str_skill_desc_5220022 = "任意のマスを選択し、隣接する4マスを雷属性マスに変える",
  str_skill_desc_52200221 = "任意のマスを選択し、隣接する4マスを万色マスに変える",
  str_skill_name_5220023 = "醒転・轟雷",
  str_skill_desc_5220023 = "任意の5つのマスを雷属性に変える",
  str_skill_desc_52200231 = "任意の5つのマスを万色マスに変える",
  str_skill_desc_5010421 = "従者が自身の周囲2マス以内にいるターゲットに大量の破裂の印を付与する。印1スタックにつき、ターゲットの防御力が一定程度減少。印のスタック数が多いほど防御力が下がる",
  str_skill_desc_5010821 = "ランダムな位置に移動できない従者を多数召喚する",
  str_skill_desc_5010831 = "範囲内のターゲットに攻撃を加え、破裂の印を10スタック付与する。印のスタック数が多いほどターゲットの防御力が下がる",
  str_skill_desc_5010832 = "範囲内のターゲットに攻撃を加え、破裂の印を1スタック付与する。印のスタック数が多いほどターゲットの防御力が下がる",
  str_skill_desc_5010841 = "咆吼し、範囲内の敵ターゲットに破裂の印を20スタック付与する。印のスタック数が多いほどターゲットの防御力が下がる",
  str_skill_desc_5010842 = "咆吼し、範囲内の敵ターゲットに破裂の印を2スタック付与する。印のスタック数が多いほどターゲットの防御力が下がる",
  str_skill_desc_5010851 = "ターゲットの破裂の印を爆破させ、そのターゲットに大ダメージを与える。印のスタック数が多いほどダメージが大きくなる",
  str_skill_desc_5010871 = "ランダムなエリアに従者を3体召喚する。従者は移動できない",
  str_skill_desc_5010881 = "範囲内のターゲットに2回猛攻撃を加え、破裂の印を多数付与する。スタック数が多いほどターゲットの防御力が下がる",
  str_skill_desc_5010891 = "死に際の咆吼とともに範囲内のターゲットに破裂の印を多数付与する。スタック数が多いほどターゲットの防御力が下がる",
  str_skill_desc_533500601 = "範囲内のターゲットにダメージを与え、さらに広い範囲内の全てのマスを粉砕する",
  str_skill_desc_990050211 = "末極・チェンジが全域にダメージを与える",
  str_skill_desc_990050212 = "末極・チェンジはターゲットの方向へ幅2マスの衝撃波を1発放ち、命中したターゲットにダメージを与える。",
  str_skill_name_990050211 = "拡散",
  str_skill_name_1002802 = "高速離脱",
  str_skill_desc_1002802 = "自身に最も近い転移の虫穴に向かって移動し、フィールド間を高速で移動する",
