  str_skill_desc_300208 = "進入可能なマスを1つ選択し、<link=\"30087\"><#FFAE07><u>鉄トカゲ</u></color></link>を召喚する。<color=#00F6FF>暗鬼のターン開始前</color>、鉄トカゲが<color=#00F6FF>周囲2マス</color>以内にいる敵を自身の方向へ1マス引き寄せる",
  str_skill_desc_305208 = "進入可能なマスを1つ選択し、<link=\"30087\"><#FFAE07><u>鉄トカゲ</u></color></link>を召喚する。鉄トカゲの<color=#00F6FF>出現時</color>と<color=#00F6FF>暗鬼のターン開始前</color>、<color=#00F6FF>周囲2マス</color>以内にいる敵を自身の方向へ1マス引き寄せる",
  str_skill_desc_310208 = "進入可能なマスを1つ選択し、<link=\"30087\"><#FFAE07><u>鉄トカゲ</u></color></link>を召喚する。<color=#00F6FF>暗鬼のターン開始前</color>、鉄トカゲが<color=#00F6FF>周囲2マス</color>以内にいる敵を自身の方向へ1マス引き寄せる",
  str_skill_desc_315208 = "進入可能なマスを1つ選択し、<link=\"30087\"><#FFAE07><u>鉄トカゲ</u></color></link>を召喚する。鉄トカゲの<color=#00F6FF>出現時</color>と<color=#00F6FF>暗鬼のターン開始前</color>、<color=#00F6FF>周囲2マス</color>以内にいる敵を自身の方向へ1マス引き寄せる",
  str_skill_desc_320208 = "進入可能なマスを1つ選択し、<link=\"30088\"><#FFAE07><u>鉄トカゲ</u></color></link>を召喚する。<color=#00F6FF>暗鬼のターン開始前</color>、鉄トカゲが<color=#00F6FF>周囲2マス</color>以内にいる敵を自身の方向へ1マス引き寄せる。鉄トカゲが<link=\"30089\"><#FFAE07><u>「リードコール」</u></color></link>を使用可能になる",
  str_skill_desc_325208 = "進入可能なマスを1つ選択し、<link=\"30088\"><#FFAE07><u>鉄トカゲ</u></color></link>を召喚する。鉄トカゲの<color=#00F6FF>出現時</color>と<color=#00F6FF>暗鬼のターン開始前</color>、<color=#00F6FF>周囲2マス</color>以内にいる敵を自身の方向へ1マス引き寄せる。鉄トカゲが<link=\"30089\"><#FFAE07><u>「リードコール」</u></color></link>を使用可能になる",
  str_skill_desc_330208 = "進入可能なマスを1つ選択し、<link=\"30088\"><#FFAE07><u>鉄トカゲ</u></color></link>を召喚する。<color=#00F6FF>暗鬼のターン開始前</color>、鉄トカゲが<color=#00F6FF>周囲2マス</color>以内にいる敵を自身の方向へ1マス引き寄せる。鉄トカゲが<link=\"30089\"><#FFAE07><u>「リードコール」</u></color></link>と<link=\"30090\"><#FFAE07><u>「フラッドプル」</u></color></link>を使用可能になる",
  str_skill_desc_335208 = "進入可能なマスを1つ選択し、<link=\"30088\"><#FFAE07><u>鉄トカゲ</u></color></link>を召喚する。鉄トカゲの<color=#00F6FF>出現時</color>と<color=#00F6FF>暗鬼のターン開始前</color>、<color=#00F6FF>周囲2マス</color>以内にいる敵を自身の方向へ1マス引き寄せる。鉄トカゲが<link=\"30089\"><#FFAE07><u>「リードコール」</u></color></link>と<link=\"30090\"><#FFAE07><u>「フラッドプル」</u></color></link>を使用可能になる",
