  str_skill_name_290600106 = "哀念・イブ回復",
  str_skill_desc_290600103 = "「イブ」・哀念がターゲットの十字形最大範囲内の最も遠いマスに瞬間移動し、その後ターゲットを攻撃する",
  str_skill_desc_290600104 = "「イブ」・哀念がフィールド中央の広範囲にダメージを与える",
  str_skill_desc_290600105 = "「イブ」・哀念が大量の暗力を獲得し、そのスタック数に応じてダメージ軽減効果を獲得する。攻撃を受けるたび、暗力のスタック数が減少する。",
  str_skill_desc_290600106 = "「イブ」・哀念がターゲットをロックし、ダメージを与える。その後、残りの暗力のスタック数に応じて、大量のHPを回復する",
  str_skill_name_291600103 = "「イブ」・哀念がターゲットから最も近い位置に瞬間移動し、その後ターゲットを攻撃する",
  str_skill_name_291600104 = "「イブ」・哀念がフィールド中央の広範囲にダメージを与える",
  str_skill_name_291600105 = "「イブ」・哀念が一定数の暗力を獲得し、そのスタック数に応じてダメージ軽減効果を獲得する。攻撃を受けるたび、暗力のスタック数が減少する。",
  str_skill_name_291600106 = "「イブ」・哀念がターゲットをロックし、ダメージを与える。その後、残りの暗力のスタック数に応じて、大量のHPを回復する",
