  str_skill_name_200310102 = "先鋒士官",
  str_skill_desc_200310102 = "敵に斬りかかってダメージを与えた後、蹴りで再度少量のダメージを与え、さらに敵をノックバックする",
  str_skill_name_200310103 = "戦友の激励",
  str_skill_desc_200310103 = "周囲2マス以内の啓光兵士の移動力が上昇する。自身と範囲内にいる啓光兵士の蓄積した損傷値の一部をHPに変換する",
  str_skill_name_200290103 = "L5型機関銃制圧",
  str_skill_desc_200290103 = "敵が八角形20マスの範囲内にいる時、連装銃でダメージを与える",
  str_skill_name_200290104 = "L5型突撃",
  str_skill_desc_200290104 = "敵が八角形20マスの範囲内にいない時、十字方向の範囲で敵に最も近い位置に突進し、その後到着地点前方の敵にダメージを与え、さらに2マスノックバックする",
  str_skill_name_200300101 = "扇状火炎放射",
  str_skill_desc_200300101 = "前方扇形範囲内のすべてのターゲットにダメージを与え、火傷効果を1スタック付与する。さらに範囲内の進入可能なマス上に火炎を生成する",
  str_skill_name_200340103 = "汚惑掃戦",
