  str_skill_name_200270101 = "啓光式戦場救援法",
  str_skill_desc_200270101 = "自身を中心にした十字方向4マス内にいる、HPが最も低い啓光兵士のHPを回復する。自身が蓄積した損傷値の一部をHPに変換する",
  str_skill_name_200280101 = "応援要請",
  str_skill_desc_200280101 = "啓光兵士を1体フィールド上に召喚する",
  str_skill_upgrade_desc_16020913 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16020916 = "能動技強化：技のクールダウンターン<color=#FFFF00>-1</color>。",
  str_skill_name_2002091 = "巡行突撃",
  str_skill_name_2002092 = "巡行突撃",
  str_skill_name_2002093 = "巡行突撃",
  str_skill_name_2002094 = "巡行突撃",
  str_skill_desc_2002091 = "<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>正方形9マス</color>に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_2002092 = "<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2002093 = "<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>縦、横、斜め17マス</color>に<color=#00F6FF>170%</color>のダメージを与える",
  str_skill_desc_2002094 = "<color=#00F6FF>菱形12マス</color>の範囲内の最も距離が近くHPが最も高い敵に跳躍し、<color=#00F6FF>正方形25マス</color>に<color=#00F6FF>200%</color>のダメージを与える。1回の連鎖ごとにダメージを1回与えるたび、発動条件-1",
  str_skill_name_3002091 = "巡行雷鳴",
  str_skill_name_3002092 = "巡行雷鳴・変異Ⅱ",
  str_skill_name_3002093 = "巡行雷鳴・変異Ⅰ",
  str_skill_name_3062091 = "巡行雷鳴",
  str_skill_name_3062092 = "巡行雷鳴・変異Ⅱ",
  str_skill_name_3062093 = "巡行雷鳴・変異Ⅰ",
  str_skill_desc_3002091 = "1マス選択して正方形25マスに<color=#00F6FF>200%</color>のダメージを与える。自身が選択した範囲内にいる場合、最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_desc_3002092 = "<color=#FFFF00>発動後の技のCDターン-1</color>。1マス選択して正方形9マスに<color=#00F6FF>100%</color>のダメージを与える。自身が選択した範囲内にいる場合、最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_desc_3002093 = "<color=#FFFF00>発動後の技のCDターン+1</color>。すべてのマスに300%のダメージを与え、最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_desc_3062091 = "1マス選択して正方形25マスに<color=#00F6FF>200%</color>のダメージを与える。自身が選択した範囲内にいる場合、最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_desc_3062092 = "<color=#FFFF00>発動後の技のCDターン-1</color>。1マス選択して正方形9マスに<color=#00F6FF>100%</color>のダメージを与える。自身が選択した範囲内にいる場合、最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_desc_3062093 = "<color=#FFFF00>発動後の技のCDターン+1</color>。すべてのマスに<color=#00F6FF>300%</color>のダメージを与え、最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_passive_name_410209 = "轟く雷霆",
  str_skill_passive_name_420209 = "轟く雷霆",
  str_skill_passive_name_430209 = "轟く雷霆",
  str_skill_passive_desc_410209 = "能動技で攻撃した敵が<color=#00F6FF>2ターン</color>持続する雷鳴状態になる。味方が連鎖で1マス移動するごとに、周囲<color=#00F6FF>菱形12マス</color>の範囲内にいる雷鳴状態のターゲットに<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_420209 = "能動技で攻撃した敵が<color=#00F6FF>2ターン</color>持続する雷鳴状態になる。味方が連鎖で1マス移動するごとに、周囲<color=#00F6FF>菱形12マス</color>の範囲内にいる雷鳴状態のターゲットに<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_430209 = "通常攻撃で<color=#00F6FF>十字方向8マス</color>の敵に攻撃できる。能動技で攻撃した敵が<color=#00F6FF>2ターン</color>持続する雷鳴状態になる。味方が連鎖で1マス移動するごとに、周囲<color=#00F6FF>菱形12マス</color>の範囲内にいる雷鳴状態のターゲットに<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_440209 = "通常攻撃で<color=#00F6FF>十字方向8マス</color>の敵に攻撃できる。能動技で攻撃した敵が<color=#00F6FF>2ターン</color>持続する雷鳴状態になる。味方が連鎖で1マス移動するごとに、周囲<color=#00F6FF>菱形12マス</color>の範囲内にいる雷鳴状態のターゲットに<color=#00F6FF>50%</color>のダメージを与える",
  str_skill_upgrade_refine_desc_16020911 = "装備技強化：ダメージ係数が<color=#00F6FF>50%</color>に上昇",
  str_skill_upgrade_refine_desc_16020912 = "<color=#00F6FF>能動技変異Ⅰを追加</color>：<color=#FFFF00>発動後技のCDターン+1</color>。すべてのマスに<color=#00F6FF>300%</color>のダメージを与え、最終ダメージ+<color=#00F6FF>30%</color>",
  str_skill_upgrade_refine_desc_16020913 = "<color=#00F6FF>能動技変異Ⅱを追加</color>：<color=#FFFF00>発動後技のCDターン-1</color>。1マス選択して正方形9マスに<color=#00F6FF>100%</color>のダメージを与える。自身が選択した範囲内にいる場合、最終ダメージ+30%",
  str_skill_desc_320116 = "任意の敵1体を選び、<color=#00F6FF>{1}%</color>のダメージを与え、さらにそのターゲットをマークする。フェラールがこのターンに連鎖技を発動すると、マークされたターゲットは追加ダメージを1回受ける。前のターンで能動技が発動可能だった場合、このターンの最終ダメージ+<color=#00F6FF>35%</color>",
  str_skill_desc_323116 = "任意の敵1体を選び、<color=#00F6FF>{1}%</color>のダメージを与え、さらにそのターゲットをマークする。フェラールがこのターンに連鎖技を発動すると、マークされたターゲットは追加ダメージを1回受ける。前のターンで能動技が発動可能だった場合、このターンの最終ダメージ+<color=#00F6FF>35%</color>",
  str_skill_upgrade_desc_16011113 = "装備技強化：晶鉱の生成範囲が周囲1/2/3/マス以内になる",
  str_skill_upgrade_desc_16011116 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_desc_300111 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵が少ないほど与えるダメージは高くなる。ダメージは最大2倍まで",
  str_skill_desc_303111 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵が少ないほど与えるダメージは高くなる。ダメージは最大2倍まで",
  str_skill_desc_320111 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵が少ないほど与えるダメージは高くなる。ダメージは最大2倍まで。<color=#00F6FF>能動技の発動</color>および<color=#00F6FF>極光タイム発動時</color>に現在の位置をマークする。そのターン中、装備技を発動して晶鉱を生成する時、マークした位置でも装備技の効果が1回発動する",
  str_skill_desc_323111 = "敵<color=#00F6FF>全体</color>に<color=#00F6FF>{1}%</color>のダメージを与える。敵が少ないほど与えるダメージは高くなる。ダメージは最大2倍まで。<color=#00F6FF>能動技の発動</color>および<color=#00F6FF>極光タイム発動時</color>に現在の位置をマークする。そのターン中、装備技を発動して晶鉱を生成する時、マークした位置でも装備技の効果が1回発動する",
  str_skill_passive_name_416111 = "ブラッディセンサー",
  str_skill_passive_name_436111 = "ブラッディセンサー",
  str_skill_passive_desc_410111 = "敵ターン開始前、このターン中にベリエが連鎖技を発動している場合、<color=#00F6FF>連鎖技の範囲内</color>のマスに晶鉱を生成する。1ターン持続。敵は晶鉱に<link=\"30091\"><#FFAE07><u>接触</u></color></link>すると、<color=#00F6FF>{1}</color>の防御力無視のダメージを受ける（このダメージは属性相性の影響を受ける）",
  str_skill_passive_desc_430111 = "敵ターン開始前、このターン中にベリエが連鎖技を発動している場合、<color=#00F6FF>連鎖技の範囲内</color>のマスに晶鉱を生成する。1ターン持続。敵は晶鉱に<link=\"30091\"><#FFAE07><u>接触</u></color></link>すると、<color=#00F6FF>{1}</color>の防御力無視のダメージを受ける（このダメージは属性相性の影響を受ける）。連鎖が1マス増えるごとに、接触のダメージ+<color=#00F6FF>10%</color>、20マスに到達すると、それ以上増加しなくなる",
  str_skill_passive_desc_416111 = "敵ターン開始前、このターン中にベリエが連鎖技を発動している場合、自身の<color=#00F6FF>周囲1/2/3マスの範囲内</color>に晶鉱を生成する。1ターン持続。敵は晶鉱に<link=\"30091\"><#FFAE07><u>接触</u></color></link>すると、<color=#00F6FF>{1}</color>の防御力無視のダメージを受ける（このダメージは属性相性の影響を受ける）",
  str_skill_passive_desc_436111 = "敵ターン開始前、このターン中にベリエが連鎖技を発動している場合、自身の<color=#00F6FF>周囲1/2/3マスの範囲内</color>に晶鉱を生成する。1ターン持続。敵は晶鉱に<link=\"30091\"><#FFAE07><u>接触</u></color></link>すると、<color=#00F6FF>{1}</color>の防御力無視のダメージを受ける（このダメージは属性相性の影響を受ける）。連鎖が1マス増えるごとに、接触のダメージ+<color=#00F6FF>10%</color>、20マスに到達すると、それ以上増加しなくなる",
  str_skill_desc_2001161 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_desc_2001162 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_desc_2001163 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える",
  str_skill_desc_2061161 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。マークした目標を攻撃する場合、そのすべての防御力を無視する",
