  str_skill_desc_2061163 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。マークした目標を攻撃する場合、そのすべての防御力を無視する",
  str_skill_desc_2201161 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。マークした目標を攻撃する場合、その40%の防御力を無視する",
  str_skill_desc_2201162 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。マークした目標を攻撃する場合、その40%の防御力を無視する",
  str_skill_desc_2201163 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。マークした目標を攻撃する場合、その40%の防御力を無視する",
  str_skill_name_2201161 = "アレンの拳骨",
  str_skill_name_2201162 = "アレンの拳骨",
  str_skill_name_2201163 = "アレンの拳骨",
  str_skill_desc_300116 = "任意の敵1体を選び、<color=#00F6FF>{1}%</color>のダメージを与え、さらにそのターゲットをマークする。フェラールの連鎖技はこのターン、マークしたターゲットに追加ダメージを1回与える",
  str_skill_desc_303116 = "任意の敵1体を選び、<color=#00F6FF>{1}%</color>のダメージを与え、さらにそのターゲットをマークする。フェラールの連鎖技はこのターン、マークしたターゲットに追加ダメージを1回与える。<color=#00F6FF>極光タイム発動時</color>、もしくは<color=#00F6FF>マークしたターゲットが撃破</color>された場合、能動技を再度発動できる",
  str_skill_passive_name_400116 = "マシンマスター",
  str_skill_passive_name_410116 = "マシンマスター",
  str_skill_passive_name_430116 = "マシンマスター",
  str_skill_passive_desc_410116 = "フェラールがHP残量50%以下の敵に与える全ダメージ+<color=#00F6FF>{1}</color>（ターゲットにHPの上限がない場合も、この効果は有効になる）",
  str_skill_passive_desc_430116 = "フェラールがHP残量50%未満の敵に与える全ダメージ+<color=#00F6FF>{1}</color>（ターゲットにHPの上限がない場合も、この効果は有効になる）。マークしたターゲットを攻撃する時、追加で+<color=#00F6FF>{2}</color>",
  str_skill_upgrade_desc_16011613 = "連鎖技強化：連鎖技でマークした目標を攻撃する場合、そのすべての防御力を無視する（覚醒2で有効になる）",
  str_skill_upgrade_desc_16011616 = "能動技強化：極光タイム発動時、またはマークしたターゲットが撃破された場合、再度発動できる",
