  str_skill_passive_name_410210 = "無瑕の残影",
  str_skill_passive_name_415210 = "無瑕の残影",
  str_skill_desc_20021011 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>130%</color>のダメージを2回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2002102 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>135%</color>のダメージを3回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2002103 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>140%</color>のダメージを4回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_3002101 = "周囲<color=#00F6FF>4</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える",
  str_skill_desc_3102101 = "周囲<color=#00F6FF>4</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える",
  str_skill_desc_3202101 = "周囲<color=#00F6FF>4</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>菱形12マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_3302101 = "周囲<color=#00F6FF>4</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える。このダメージと装備技が発動するダメージはマスを1マス貫通でき、貫通したマスに<color=#00F6FF>半分</color>のダメージを与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>菱形12マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_3022101 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える",
  str_skill_desc_3122101 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える",
  str_skill_desc_3222101 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>菱形12マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_3322101 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える。このダメージと装備技が発動するダメージはマスを1マス貫通でき、貫通したマスに<color=#00F6FF>半分</color>のダメージを与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>菱形12マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_3152101 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える",
  str_skill_desc_3252101 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>菱形12マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_3352101 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>{1}%</color>のダメージを1回与える。このダメージと装備技が発動するダメージはマスを1マス貫通でき、貫通したマスに<color=#00F6FF>半分</color>のダメージを与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>菱形12マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_passive_desc_410210 = "ジョセリンの通常攻撃または連鎖技が命中した敵に残影を1スタック付与する。最大<color=#00F6FF>6</color>スタックまで。能動技が<color=#00F6FF>目の前の1マス</color>にいる敵に追加で攻撃力の<color=#00F6FF>{1}</color>に相当するダメージを、ターゲットの残影スタック数分の回数与える。その後、スタック数はクリアされる",
  str_skill_passive_desc_415210 = "ジョセリンの通常攻撃または連鎖技が命中した敵に残影を1スタック付与する。最大<color=#00F6FF>8</color>スタックまで。能動技が<color=#00F6FF>目の前の1マス</color>にいる敵に追加で攻撃力の<color=#00F6FF>{1}</color>に相当するダメージを、ターゲットが持っている残影スタック数分の回数与える。その後、スタック数はクリアされる",
  str_skill_upgrade_desc_15021012 = "能動技強化：周囲<color=#FFFF00>8</color>方向のうち1方向を選んでダッシュする",
  str_skill_upgrade_desc_15021015 = "装備技強化：残影のスタック数上限が<color=#FFFF00>8</color>に増える",
  str_skill_name_200330110 = "霊感制御",
  str_skill_desc_200330110 = "呪惧はプレイヤーのいる位置から遠ざかる。チームの移動終了後、ただちにチームの位置をずらし、連鎖技の発動位置に影響をおよぼす",
  str_skill_name_200330121 = "血の生けにえ",
  str_skill_desc_200330121 = "呪惧は自身のHPを残り1になるまで燃焼させ、プレイヤーに防御力無視の確定ダメージを与える。燃焼したHPの値が最終ダメージを決定する。技の発動は1回まで",
  str_skill_upgrade_refine_desc_15021011 = "装備技強化：ダメージ係数が<color=#00F6FF>36%</color>に上昇。",
  str_skill_upgrade_refine_desc_15021012 = "能動技強化：ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>周囲2マス</color>の範囲内のすべての敵に120%のダメージを1回与える",
  str_skill_upgrade_refine_desc_15021013 = "能動技強化：能動技と装備技の貫通したマスに与えるダメージが減衰しない",
  str_skill_passive_desc_440210 = "ジョセリンの通常攻撃または連鎖技が命中した敵に残影を1スタック付与する。最大<color=#00F6FF>8</color>スタックまで。能動技が<color=#00F6FF>目の前の1マス</color>にいる敵に追加で攻撃力の<color=#00F6FF>36%</color>に相当するダメージを、ターゲットが持っている残影スタック数分の回数与える。その後、スタック数はクリアされる",
  str_skill_passive_desc_445210 = "ジョセリンの通常攻撃または連鎖技が命中した敵に残影を1スタック付与する。最大<color=#00F6FF>8</color>スタックまで。能動技が<color=#00F6FF>目の前の1マス</color>にいる敵に追加で攻撃力の<color=#00F6FF>36%</color>に相当するダメージを、ターゲットが持っている残影スタック数分の回数与える。その後、スタック数はクリアされる",
  str_skill_desc_34021011 = "周囲<color=#00F6FF>4</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>80%</color>のダメージを1回与える。このダメージと装備技が発動するダメージはマスを1マス貫通し、貫通したマスに<color=#00F6FF>半分</color>のダメージを与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>周囲2マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_34221011 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>80%</color>のダメージを1回与える。このダメージと装備技が発動するダメージはマスを1マス貫通し、貫通したマスに<color=#00F6FF>半分</color>のダメージを与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>周囲2マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_34521011 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>80%</color>のダメージを1回与える。このダメージと装備技が発動するダメージはマスを1マス貫通し、貫通したマスに<color=#00F6FF>半分</color>のダメージを与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>周囲2マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_34021012 = "周囲<color=#00F6FF>4</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>80%</color>のダメージを1回与える。このダメージと装備技が発動するダメージはマスを1マス貫通し、貫通したマスにも<color=#00F6FF>減衰なしの</color>ダメージを与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>周囲2マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_34221012 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>80%</color>のダメージを1回与える。このダメージと装備技が発動するダメージはマスを1マス貫通し、貫通したマスにも<color=#00F6FF>減衰なしの</color>ダメージを与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>周囲2マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_desc_34521012 = "周囲<color=#00F6FF>8</color>方向のうち1方向を選んでダッシュする。障害物に阻まれると停止し、<color=#00F6FF>目の前の1マス</color>にいる敵に<color=#00F6FF>80%</color>のダメージを1回与える。このダメージと装備技が発動するダメージはマスを1マス貫通し、貫通したマスにも<color=#00F6FF>減衰なしの</color>ダメージを与える。ターゲットがもつ残影4スタックごとに、自身を中心とした<color=#00F6FF>周囲2マス</color>の範囲内のすべての敵に追加で<color=#00F6FF>120%</color>のダメージを1回与える",
  str_skill_name_70010981 = "末極・巨像鋒鋭",
  str_skill_name_70010982 = "末極・雷電の力",
  str_skill_name_70010983 = "末極・巨像音鳴",
  str_skill_desc_70010981 = "末極・グリードスーモアが十字範囲内のターゲットにダメージを与える",
  str_skill_desc_70010982 = "末極・グリードスーモアが雷を起こし、フィールド上の複数のエリアにダメージを与え、さらに麻痺効果を付与する",
  str_skill_desc_70010983 = "末極・グリードスーモアが巨像をコントロールして音波攻撃を繰り出し、全域のターゲットを攻撃する。さらに光霊を周囲に引き寄せる",
