  str_skill_desc_290610101 = "前方範囲内に敵が存在する場合、ゆっくりと前に進み、痛烈な一撃を与える",
  str_skill_name_290610102 = "エンジン加速",
  str_skill_desc_290610102 = "前方が開けている場合、出力を上げ猛スピードで進む",
  str_skill_name_290610103 = "全方位爆撃",
  str_skill_desc_290610103 = "アーマー周囲の光霊にダメージを与え、ノックバックする。さらに防壁にダメージを与える",
  str_skill_name_290610104 = "高熱噴射",
  str_skill_desc_290610104 = "強力な攻城を行い、前方にいる光霊と防壁に大ダメージを与える",
  str_skill_name_290610105 = "汚惑の機関士",
  str_skill_desc_290610105 = "スタン状態になると自身の兵装の修理を行う。修理終了後、行動を再開する",
  str_skill_name_280240101 = "猛撃駆逐",
  str_skill_desc_280240101 = "要塞のゲート前にいる敵を攻撃し、その敵をスタン状態にする",
  str_skill_name_290570101 = "マッドバンドル・潜撃",
  str_skill_name_290570102 = "マッドバンドル・噴沼",
  str_skill_name_290570103 = "マッドバンドル・渦沼",
  str_skill_desc_290570101 = "マッドバンドルが大きく広がったぬかるみの中に潜り込み、光霊に最も近い位置から飛び出して周囲2マス以内にダメージを与える。さらにフィールド上に複数のぬかるみを生成する",
  str_skill_desc_290570102 = "マッドバンドルが大きく広がったぬかるみの中に潜り込み、光霊に最も近い位置から飛び出して前方2列にダメージを与える。さらに複数のぬかるみを生成する",
  str_skill_desc_290570103 = "すべてのマスを吸い込み、さらに光霊にダメージを与える。その後、すべてのマスをリセットし、光霊をランダムにぬかるみの上に移動させる",
  str_skill_desc_290570104 = "マラゾールがフィールド上に呪惧を2体召喚する",
  str_skill_upgrade_desc_16021213 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる\n能動技の定めた四角形の範囲内にある森属性以外のランダムな2マスを森属性に変える",
  str_skill_upgrade_desc_16021216 = "能動技強化：2回目の選択範囲が<color=#00F6FF>周囲4マス</color>に拡大する",
  str_skill_desc_3002121 = "1マス選択し、その<color=#00F6FF>周囲3マス</color>の範囲内からさらに1マスを選択して四角形の範囲を定め、選択した2マスを森属性に変える。チームが四角形の範囲内にいた場合、アントニーの攻撃力の<color=#00F6FF>250%</color>に相当するチームHPを回復する",
  str_skill_desc_3032121 = "1マス選択し、その<color=#00F6FF>周囲3マス</color>の範囲内からさらに1マスを選択して四角形の範囲を定め、選択した2マスを森属性に変える。さらに四角形の範囲内にある森属性以外のランダムな2マスを森属性に変える。チームが四角形の範囲内にいた場合、アントニーの攻撃力の<color=#00F6FF>250%</color>に相当するチームHPを回復する",
  str_skill_desc_3062121 = "1マス選択し、その<color=#00F6FF>周囲4マス</color>の範囲内からさらに1マスを選択して四角形の範囲を定め、選択した2マスを森属性に変える。さらに四角形の範囲内にある森属性以外のランダムな2マスを森属性に変える。チームが四角形の範囲内にいた場合、アントニーの攻撃力の<color=#00F6FF>250%</color>に相当するチームHPを回復する",
  str_skill_desc_3202121 = "1マス選択し、その<color=#00F6FF>周囲3マス</color>の範囲内からさらに1マスを選択して四角形の範囲を定め、選択した2マスを森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。チームが四角形の範囲内にいた場合、アントニーの攻撃力の<color=#00F6FF>250%</color>に相当するチームHPを回復する",
  str_skill_desc_3232121 = "1マス選択し、その<color=#00F6FF>周囲3マス</color>の範囲内からさらに1マスを選択して四角形の範囲を定め、選択した2マスを森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。さらに四角形の範囲内にある森属性以外のランダムな2マスを森属性に変える。チームが四角形の範囲内にいた場合、アントニーの攻撃力の<color=#00F6FF>250%</color>に相当するチームHPを回復する",
  str_skill_desc_3262121 = "1マス選択し、その<color=#00F6FF>周囲4マス</color>の範囲内からさらに1マスを選択して四角形の範囲を定め、選択した2マスを森属性の<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>に変える。さらに四角形の範囲内にある森属性以外のランダムな2マスを森属性に変える。チームが四角形の範囲内にいた場合、アントニーの攻撃力の<color=#00F6FF>250%</color>に相当するチームHPを回復する",
  str_skill_desc_2002121 = "<color=#00F6FF>縦方向1列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002122 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002123 = "<color=#00F6FF>縦方向3列</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_passive_desc_410212 = "チームが森属性のマスを連鎖で1マス移動、あるいはその他の方法で1マス<link=\"30092\"><#FFAE07><u>位置移動</u></color></link>するたびに、アントニーの攻撃力の<color=#00F6FF>{1}</color>に相当するチームHPを回復する",
  str_skill_passive_desc_430212 = "チームが森属性のマスを連鎖で1マス移動、あるいはその他の方法で1マス<link=\"30092\"><#FFAE07><u>位置移動</u></color></link>するたびに、アントニーの攻撃力の<color=#00F6FF>{1}</color>に相当するチームHPを回復する。チームのHPが低いほど回復効果は高くなり、最大で<color=#00F6FF>100%</color>上昇する",
