  str_skill_desc_8002001 = "任意のマスを起点として1マス選択し、さらに2×2または1×4の範囲になるよう終点をタップして指定する。指定範囲内のマスを万色マスに変え、さらに強化マスを生成する",
  str_skill_desc_8002002 = "任意のマスを1マス選択し、方形9マスの範囲内のランダムな5マスを万色マスに変え、さらに強化マスを5マス生成する",
  str_skill_desc_8002003 = "任意のマスを選択し、そのマスの最も近くにある万色マスでない6マスを万色マスに変え、さらに強化マスを生成する",
