  str_skill_name_80020042 = "迫撃",
  str_skill_desc_80020042 = "光霊が自身の縦、横、斜めの範囲内にいる時、光霊の近くに移動し、ダメージを与えて光霊をノックバックする。攻撃は障害物にブロックされる",
