  str_skill_desc_30021101 = "最も近くの雷属性のマス<color=#00F6FF>2</color>つを水属性に変える。技の発動後、「刻影の樹氷」のCDターン+1",
  str_skill_desc_30021102 = "最も近くの森属性のマス<color=#00F6FF>2</color>つを水属性に変える。技の発動後、「染霜の天穹」のCDターン+1",
  str_skill_desc_30021103 = "最も近くの雷属性のマス<color=#00F6FF>3</color>つを水属性に変える。技の発動後、「刻影の樹氷」のCDターン+1",
  str_skill_desc_30021104 = "最も近くの森属性のマス<color=#00F6FF>3</color>つを水属性に変える。技の発動後、「染霜の天穹」のCDターン+1",
  str_skill_desc_30021105 = "最も近くの雷属性のマス<color=#00F6FF>4</color>つを水属性に変える。技の発動後、「刻影の樹氷」のCDターン+1",
  str_skill_desc_30021106 = "最も近くの森属性のマス<color=#00F6FF>4</color>つを水属性に変える。技の発動後、「染霜の天穹」のCDターン+1",
  str_skill_desc_30321101 = "最も近くの雷属性のマス<color=#00F6FF>2</color>つを水属性に変える。技の発動後、次の能動技で属性を変換できるマスの数が<color=#00F6FF>3</color>に増える。「刻影の樹氷」のCDターン+1",
  str_skill_desc_30321102 = "最も近くの森属性のマス<color=#00F6FF>2</color>つを水属性に変える。技の発動後、次の能動技で属性を変換できるマスの数が<color=#00F6FF>3</color>に増える。「染霜の天穹」のCDターン+1",
  str_skill_desc_30621103 = "最も近くの雷属性のマス<color=#00F6FF>3</color>つを水属性に変える。技の発動後、「刻影の樹氷」のCDターン+1。ターン開始時、2つの能動技がいずれも発動可能でない場合、チームから最も近い水属性以外のマスを<color=#00F6FF>1</color>つ水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える",
  str_skill_desc_30621104 = "最も近くの森属性のマス<color=#00F6FF>3</color>つを水属性に変える。技の発動後、「染霜の天穹」のCDターン+1。ターン開始時、2つの能動技がいずれも発動可能でない場合、チームから最も近い水属性以外のマスを<color=#00F6FF>1</color>つ<color=#00F6FF>水属性</color>の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える",
  str_skill_passive_name_410211 = "雪域の治癒",
  str_skill_passive_name_420211 = "雪域の治癒",
  str_skill_passive_name_430211 = "雪域の治癒",
  str_skill_passive_desc_410211 = "通常攻撃が2連続攻撃になり、それぞれのダメージは基本ダメージの<color=#00F6FF>半分</color>になる。通常攻撃<color=#00F6FF>7</color>回ごとに、自身の攻撃力<color=#00F6FF>{1}</color>に相当するチームHPを回復する",
  str_skill_passive_desc_420211 = "通常攻撃が2連続攻撃になり、それぞれのダメージは基本ダメージの<color=#00F6FF>半分</color>になる。通常攻撃<color=#00F6FF>7</color>回ごとに、自身の攻撃力<color=#00F6FF>{1}</color>に相当するチームHPを回復する。極光タイムが発動すると、ただちに自身の攻撃力<color=#00F6FF>100%</color>に相当するチームHPを回復する",
  str_skill_passive_desc_430211 = "通常攻撃で斜め方向に攻撃できる。十字方向の敵への通常攻撃は2連続攻撃になり、それぞれのダメージは基本ダメージの<color=#00F6FF>半分</color>になる。通常攻撃<color=#00F6FF>7</color>回ごとに、自身の攻撃力<color=#00F6FF>{1}</color>に相当するチームHPを回復する。極光タイムが発動すると、ただちに自身の攻撃力<color=#00F6FF>100%</color>に相当するチームHPを回復する",
  str_skill_upgrade_desc_16021113 = "能動技強化：変換するマスの数が<color=#FFFF00>3マス</color>に増える",
  str_skill_upgrade_desc_16021116 = "能動技強化：ターン開始時、2つの能動技がいずれも<color=#00F6FF>発動可能でない</color>場合、チームから最も近い水属性以外のマスを1つ水属性の濃色マスに変える",
  str_skill_name_200350101 = "震地",
  str_skill_name_200350102 = "痛撃",
  str_skill_name_200350103 = "砕頭",
  str_skill_name_200350104 = "舐血",
  str_skill_desc_200350101 = "氷獣は地面を叩きつけ、十字方向の最大範囲内の敵に複数回のダメージを与え、さらに最も遠い位置までノックバックする",
  str_skill_desc_200350102 = "敵が自身の周囲1マス範囲内にいる場合、氷獣は敵にダメージを与え、さらに1マスノックバックする",
  str_skill_desc_200350103 = "敵が氷獣の周囲の特定範囲内に位置し、かつ対応する十字方向の範囲に障害物がない場合、氷獣は敵に急接近し、強力な攻撃でダメージを与える。中心エリアにいる敵にはより大きなダメージを与え、さらに眩暈効果を付与する",
  str_skill_desc_200350104 = "付近に敵がいない場合、氷獣がHPを回復する",
  str_skill_name_200360102 = "レッドエビル・迫逐",
  str_skill_desc_200360102 = "プレイヤーの近くに瞬間移動し、目の前の1マス範囲内にいるターゲットに複数回ダメージを与え、さらにノックバックする。瞬間移動の距離が長いほど、攻撃回数は少なくなる",
  str_skill_name_290213101 = "永存の遺跡",
  str_skill_name_290213102 = "守護者の裁定",
  str_skill_name_290213103 = "定点制圧",
  str_skill_desc_290213101 = "瞬間移動し、ダメージを与える。その後、ランダムで光霊の周囲1マス以内にある3マスを森属性に変える",
  str_skill_desc_290213102 = "瞬間移動し、ダメージを与える。その後、ランダムで光霊の周囲1マス以内にある3マスを雷属性に変える",
  str_skill_desc_290213103 = "自身の周囲2マス内にある水属性マスのエネルギーを吸収し、光霊を攻撃する（吸収したマスの数が多いほど、ダメージが大きくなる）",
  str_skill_desc_200270201 = "啓光通信歩兵のHPを回復する。自身が蓄積した損傷値の一部をHPに変換する",
  str_skill_desc_200280201 = "啓光兵士を2体フィールド上に召喚する",
