  str_skill_name_111807113 = "巻物の拾得者",
  str_skill_desc_111807113 = "フィールド上の古の巻物を拾う",
  str_skill_name_111807111 = "巻物の召喚者",
  str_skill_desc_111807111 = "フィールド上のランダムな位置に古の巻物を3つ設置する",
  str_skill_name_111807212 = "巻物の召喚者",
  str_skill_desc_111807212 = "フィールド上のランダムな位置に古の巻物を5つ設置する",
  str_skill_name_2002131 = "定点制圧",
  str_skill_name_2102131 = "定点制圧",
  str_skill_desc_2002131 = "最も近くの敵1体に<color=#00F6FF>{1}%</color>のダメージを与える。連鎖数に応じてダメージ強化効果を獲得する",
  str_skill_desc_2102131 = "最も近くの敵1体にダメージを3回与える。1回のダメージは元のダメージの30%。自身がそのターン内に発動した通常攻撃の回数に応じて強化効果を獲得する",
  str_skill_name_300213 = "領域管制",
  str_skill_desc_300213 = "マスを1つ選択し、一時的にそのマスの属性を空にする。その後選んだマスを中心に<color=#00F6FF>正方形25マス</color>を範囲とし、<color=#00F6FF>15秒</color>のカウントダウン中、空マスと隣接するマスの属性をタップで交換できる。カウントダウン終了時、空マスを<color=#00F6FF>雷属性</color>に変える。戦闘ごとに1回のみ発動可能",
  str_skill_name_302213 = "領域管制",
  str_skill_desc_302213 = "マスを1つ選択し、一時的にそのマスの属性を空にする。その後選んだマスを中心に<color=#00F6FF>正方形25マス</color>を範囲とし、<color=#00F6FF>15秒</color>のカウントダウン中、空マスと隣接するマスの属性をタップで交換できる。カウントダウン終了時、空マスを<color=#00F6FF>雷属性</color>に変える。戦闘開始時/第2ウェーブ開始時に1回発動回数を獲得する",
  str_skill_name_305213 = "領域管制",
  str_skill_desc_305213 = "マスを1つ選択し、一時的にそのマスの属性を空にする。その後選んだマスを中心に<color=#00F6FF>正方形25マス</color>を範囲とし、<color=#00F6FF>15秒</color>のカウントダウン中、空マスと隣接するマスの属性をタップで交換できる。カウントダウン終了時、空マスを<color=#00F6FF>雷属性</color>に変える。戦闘開始時/第2ウェーブ開始時/第7ターン開始時に1回発動回数を獲得する",
  str_skill_passive_name_410213 = "粉砕装置",
  str_skill_passive_desc_410213 = "連撃数が<color=#00F6FF>{1}</color>に達した場合、その回の連鎖技が3段攻撃になる。1回のダメージは元のダメージの30%。自身がそのターン内に発動した通常攻撃の回数に応じて強化効果を獲得する",
  str_skill_passive_name_420213 = "粉砕装置",
  str_skill_passive_desc_420213 = "連撃数が<color=#00F6FF>{1}</color>に達した場合、その回の連鎖技が3段攻撃になる。1回のダメージは元のダメージの30%。自身がそのターン内に発動した通常攻撃の回数に応じて強化効果を獲得し、かつ<color=#00F6FF>連鎖の属性が何でも</color>発動できる。",
  str_skill_passive_name_430213 = "粉砕装置",
  str_skill_passive_desc_430213 = "連撃数が<color=#00F6FF>{1}</color>に達した場合、その回の連鎖技が3段攻撃になる。1回のダメージは元のダメージの30%。自身がそのターン内に発動した通常攻撃の回数に応じて強化効果を獲得し、かつ<color=#00F6FF>連鎖の属性を問わず</color>発動できる。連鎖後のマス補充時、その回の連鎖のNマス目を雷属性に変える。Nは残りのターン数。",
  str_skill_upgrade_desc_15021312 = "能動技強化：第2ウェーブ開始時、発動回数を1回獲得する",
  str_skill_upgrade_desc_15021315 = "能動技強化：第7ターン開始時、発動回数を1回獲得する",
  str_skill_name_53520212 = "召喚",
  str_skill_desc_53520212 = "自身の周囲に光霊がいる場合、攻撃を優先する。そうでない場合、さらに多くの白夜城長槍兵を召喚する",
  str_skill_name_53520213 = "鼓舞",
  str_skill_desc_53520213 = "自身の周囲に光霊がいる場合、攻撃を優先する。そうでない場合、自身の周囲にいる白夜城長槍兵を鼓舞し、その攻撃力を上昇させる",
  str_skill_name_53520411 = "定点制圧",
  str_skill_desc_53520411 = "自身の周囲2マス内にある水属性マスを吸収した後、敵にダメージを与える。吸収したマスの数が多いほど、ダメージが大きくなる",
  str_skill_name_53520412 = "定点制圧",
  str_skill_desc_53520412 = "自身の周囲2マス内にある火属性マスを吸収した後、敵にダメージを与える。吸収したマスの数が多いほど、ダメージが大きくなる",
  str_skill_name_53520413 = "定点制圧",
  str_skill_desc_53520413 = "自身の周囲2マス内にある森属性マスを吸収した後、敵にダメージを与える。吸収したマスの数が多いほど、ダメージが大きくなる",
  str_skill_name_5352031 = "致命的爆発",
  str_skill_desc_5352031 = "一定時間が経過するたびに爆発し、フィールド上のすべてのユニットにダメージを与える",
  str_skill_name_29089011 = "「裁判長」のガベル",
  str_skill_name_29089012 = "「裁判長」の判定",
  str_skill_name_29089014 = "「裁判長」のガベル",
  str_skill_desc_29089011 = "ターゲットが前のターンにいた場所に聖光を放ち、途中および隣接するマスのターゲットにダメージを与える。ダメージはターゲットの「固定観念」スタック数に応じて増える",
  str_skill_desc_29089012 = "ターゲット位置をロックして大量のダメージを与える。ダメージはターゲットの「固定観念」スタック数に応じて増える",
  str_skill_desc_29089014 = "ターゲットが前のターンにいた場所に聖光を放ち、途中および隣接するマスのターゲットにダメージを与える。ダメージはターゲットの「固定観念」スタック数に応じて増える。固定の位置に陪審の聖像を召喚する",
  str_skill_name_29089021 = "「裁判長」のガベル",
