  str_skill_desc_300188 = "選択した<color=#00F6FF>2</color>マスを火属性に変え、その中間のマスと隣接するマスに<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_306188 = "選択した<color=#00F6FF>2</color>マスを火属性に変え、その中間のマスと隣接するマスに<color=#00F6FF>{1}%</color>のダメージを与え、範囲内にいるHP<color=#00F6FF>15%</color>未満のボス以外の敵を撃破する",
  str_skill_passive_desc_410188 = "このターン内、各方向に対する1回目の通常攻撃がクリティカルになり、<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_420188 = "このターン内、各方向に対する1回目の通常攻撃がクリティカルになり、<color=#00F6FF>{1}</color>のダメージを与える。極光タイム発動時、すべての方向の通常攻撃のクリティカル数がリセットされる",
  str_skill_passive_desc_430188 = "通常攻撃で<color=#00F6FF>斜め方向への攻撃が可能</color>。このターン内、各方向に対する1回目の通常攻撃がクリティカルになり、<color=#00F6FF>{1}</color>のダメージを与える。極光タイム発動時、すべての方向の通常攻撃のクリティカル数がリセットされる",
  str_skill_upgrade_desc_16018813 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16018816 = "能動技強化：ダメージ率が<color=#FFFF00>360%</color>になり、範囲内のHP15%未満のボス以外の敵を撃破する",
  str_skill_desc_1501301061 = "移動後、最も近くにいる敵にダメージを与える",
