  str_skill_desc_2201342 = "<color=#00F6FF>周囲3マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える。カンナが能動技を発動した後、このターンの連鎖技の範囲+<color=#00F6FF>1マス</color>",
