  str_skill_desc_22013421 = "<color=#00F6FF>周囲3マス</color>以内の敵3体に<color=#00F6FF>{1}%</color>のダメージを与える。カンナが能動技を発動した後、このターンの連鎖技の範囲+<color=#00F6FF>1マス</color>",
  str_skill_desc_22013431 = "<color=#00F6FF>周囲3マス</color>以内の敵4体に<color=#00F6FF>{1}%</color>のダメージを与える。カンナが能動技を発動した後、このターンの連鎖技の範囲+<color=#00F6FF>1マス</color>",
  str_skill_desc_30013411 = "進入可能なマスを1つ選択して技発動の起点とし、さらに任意の1マスを選択して2マスの<color=#00F6FF>中間</color>のマスおよびそれに<color=#00F6FF>隣接</color>するマスの敵に攻撃力の<color=#00F6FF>{1}%</color>のダメージを与え、最も遠い位置までノックバックする。そのうち<color=#00F6FF>中間</color>のマスにいる敵は<color=#00F6FF>1.3</color>倍のダメージを受ける",
