  str_skill_name_2361332 = "熔壊レーザー",
  str_skill_name_2361333 = "熔壊レーザー",
  str_skill_desc_2301331 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>130%</color>のダメージを2回ランダムに割り当てて与える。さらに、その周囲<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>25%</color>の\n<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する。トールが能動技を1回発動するごとに、連鎖技のダメージ回数<color=#00F6FF>+1</color>",
  str_skill_desc_2301332 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>140%</color>のダメージを3回ランダムに割り当てて与える。さらに、その周囲<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>25%</color>の\n<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する。トールが能動技を1回発動するごとに、連鎖技のダメージ回数<color=#00F6FF>+1</color>",
  str_skill_desc_2301333 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>145%</color>のダメージを4回ランダムに割り当てて与える。さらに、その周囲<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>25%</color>の\n<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する。トールが能動技を1回発動するごとに、連鎖技のダメージ回数<color=#00F6FF>+1</color>",
  str_skill_desc_2361331 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>130%</color>のダメージを2回ランダムに割り当てて与える。さらに、その周囲<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の\n<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する。トールが能動技を1回発動するごとに、連鎖技のダメージ回数<color=#00F6FF>+1</color>",
  str_skill_desc_2361332 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>140%</color>のダメージを3回ランダムに割り当てて与える。さらに、その周囲<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の\n<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する。トールが能動技を1回発動するごとに、連鎖技のダメージ回数<color=#00F6FF>+1</color>",
  str_skill_desc_2361333 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>145%</color>のダメージを4回ランダムに割り当てて与える。さらに、その周囲<color=#00F6FF>十字方向4マス</color>に<color=#00F6FF>30%</color>の\n<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する。トールが能動技を1回発動するごとに、連鎖技のダメージ回数<color=#00F6FF>+1</color>",
  str_skill_desc_16013311 = "技を発動してダメージを5回与え、同時に周囲1マスの雷属性以外のマスをリセットする",
  str_skill_name_16013411 = "粉砕変化",
  str_skill_desc_16013411 = "自身に隣接する4マスを火属性の粉砕マスに変える。光霊が隣接する4マスを通過すると、1マスにつきコンボ数+10",
  str_skill_name_390040311 = "強化",
  str_skill_desc_390040311 = "その場で強化技を発動し、防御力が大幅に上昇する。位置を移動させられると強化が無効になる",
  str_skill_name_5362003 = "奪命の熱矛",
  str_skill_desc_5362003 = "発動時に上にいるターゲットに確定ダメージを与える",
  str_skill_desc_5362004 = "ミラーが変化したもの。ミラーは敵から最も遠い光の壁の中に隠れている（その光の壁は攻撃可能）。すべての光の壁を破壊すると勝利",
  str_skill_desc_5362005 = "ミラーが移動し、範囲内のターゲットに遠距離攻撃を行う。さらに毎ターン幻影2体とセンター1体を戦場の端に召喚する",
  str_skill_desc_5362006 = "ミラーがターゲットの近くに移動してダメージを与える。さらにターゲットの周囲に幻影2体とセンター1体を召喚する",
  str_skill_name_5362011 = "通常攻撃",
  str_skill_name_5362012 = "通常攻撃",
  str_skill_desc_5362011 = "移動後、周囲1マス以内にいるターゲットを攻撃する",
  str_skill_desc_5362012 = "移動後、縦方向3列の範囲内にいるターゲットにダメージを与える",
  str_skill_desc_5362013 = "移動後、縦方向3列の範囲内にいるターゲットにダメージを与える。ターゲットが光霊の場合、相手に毒状態を付与する",
  str_skill_desc_5362014 = "敵全体にダメージを与える",
  str_skill_desc_5362015 = "光霊を3マスノックバックし、ダメージを与える",
  str_skill_name_290900101 = "王者の覇気",
  str_skill_name_290900102 = "狂怒の海潮",
  str_skill_name_290900112 = "一時の休息",
  str_skill_desc_290900101 = "移動後、光霊を攻撃し、1マスノックバックする",
  str_skill_desc_290900102 = "光霊にダメージを与え、最も遠い位置までノックバックする",
  str_skill_desc_290900112 = "少し休憩だ。どれだけ強いか観察させてもらおう",
  str_skill_desc_290900114 = "光霊から離れた位置に向かって移動する",
  str_skill_desc_290900124 = "光霊のいるマスと同じ縦または横列で最も遠い位置へ瞬間移動し、水流を起こして光霊を最も遠くまでノックバックさせる",
  str_skill_name_20090011 = "大砲出撃",
  str_skill_name_21090011 = "大砲出撃",
  str_skill_desc_20090011 = "3マス以内にいる敵を攻撃する。範囲内にターゲットがいない場合、攻撃力を上げて自身を強化する",
  str_skill_desc_21090011 = "3マス以内にいる敵を攻撃する。範囲内にターゲットがいない場合、攻撃力を上げて自身を強化し、さらに魚人の王のHPを回復させる",
  str_skill_upgrade_desc_15021512 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_15021515 = "装備技強化：追加のダメージ係数が<color=#00F6FF>150%</color>に上昇する（覚醒2で有効）",
  str_skill_passive_name_410215 = "愉悦の刻",
  str_skill_passive_name_420215 = "愉悦の刻",
  str_skill_passive_name_430215 = "愉悦の刻",
  str_skill_passive_name_425215 = "愉悦の刻",
  str_skill_passive_name_435215 = "愉悦の刻",
  str_skill_passive_desc_410215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃が<color=#00F6FF>{1}</color>のダメージを3回与える",
  str_skill_passive_desc_420215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃が<color=#00F6FF>{1}</color>のダメージを3回与える。イーサの通常攻撃が同一の敵に累計で<color=#00F6FF>7回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>100%</color>のダメージを追加で1回与える",
  str_skill_passive_desc_430215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃が<color=#00F6FF>{1}</color>のダメージを3回与える。イーサの通常攻撃、連鎖技が同一の敵に累計で<color=#00F6FF>7回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>100%</color>のダメージを追加で1回与える。能動技がターゲットに命中した後、ただちに追加でダメージを1回与える",
  str_skill_passive_desc_425215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃が<color=#00F6FF>{1}</color>のダメージを3回与える。イーサの通常攻撃が同一の敵に累計で<color=#00F6FF>7回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>150%</color>のダメージを追加で1回与える",
  str_skill_passive_desc_435215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃が<color=#00F6FF>{1}</color>のダメージを3回与える。イーサの通常攻撃、連鎖技が同一の敵に累計で<color=#00F6FF>7回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>150%</color>のダメージを追加で1回与える。能動技がターゲットに命中した後、ただちに追加でダメージを1回与える",
  str_skill_name_2002151 = "雷鞭の怒号",
  str_skill_name_2002152 = "雷鞭の怒号",
  str_skill_name_2002153 = "雷鞭の怒号",
  str_skill_desc_2002151 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002152 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002153 = "<color=#00F6FF>縦、横、斜めの24マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_name_300215 = "刈取の心得",
  str_skill_desc_300215 = "敵の足元のマスを1つ選び、その周囲4方向から1方向を選択する。BOSS以外の敵を選択した方向に1マス強制移動させて{1}%のダメージを与える。同時に、選択したマスに<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を生成する",
  str_skill_upgrade_refine_desc_15021511 = "装備技強化：<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上の通常攻撃がダメージを3回与え、各回のダメージ係数が<color=#00F6FF>65%</color>に上昇する",
  str_skill_upgrade_refine_desc_15021512 = "装備技新効果：イーサとレベッカ（覚醒1以上）がチームにいるとき、イーサの装備技による追加ダメージでターゲットに<color=#00F6FF>侵食を1スタック付与</color>する",
  str_skill_upgrade_refine_desc_15021513 = "装備技強化：追加ダメージの発動条件が<color=#00F6FF>6回に減少</color>する",
  str_skill_passive_desc_440215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃が<color=#00F6FF>65%</color>のダメージを3回与える。イーサの通常攻撃、連鎖技が同一の敵に累計で<color=#00F6FF>7回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>100%</color>のダメージを追加で1回与える。能動技がターゲットに命中した後、ただちに追加でダメージを1回与える",
  str_skill_passive_desc_445215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃が<color=#00F6FF>65%</color>のダメージを3回与える。イーサの通常攻撃、連鎖技が同一の敵に累計で<color=#00F6FF>7回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>150%</color>のダメージを追加で1回与える。能動技がターゲットに命中した後、ただちに追加でダメージを1回与える",
  str_skill_passive_desc_450215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃は<color=#00F6FF>65%</color>のダメージを3回与える。イーサの通常攻撃、連鎖技が同一の敵に累計で<color=#00F6FF>7回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>100%</color>のダメージを追加で1回与える。能動技がターゲットに命中した後、ただちに追加でダメージを1回与える。イーサとレベッカ（覚醒1以上）がチームにいる場合、ダメージを与えた時に<color=#00F6FF>侵食を1スタック付与</color>する",
  str_skill_passive_desc_455215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃は<color=#00F6FF>65%</color>のダメージを3回与える。イーサの通常攻撃、連鎖技が同一の敵に累計で<color=#00F6FF>7回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>150%</color>のダメージを追加で1回与える。能動技がターゲットに命中した後、ただちに追加でダメージを1回与える。イーサとレベッカ（覚醒1以上）がチームにいる場合、ダメージを与えた時に<color=#00F6FF>侵食を1スタック付与</color>する",
  str_skill_passive_desc_460215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃は<color=#00F6FF>65%</color>のダメージを3回与える。イーサの通常攻撃、連鎖技が同一の敵に累計で<color=#00F6FF>6回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>100%</color>のダメージを追加で1回与える。能動技がターゲットに命中した後、ただちに追加でダメージを1回与える。イーサとレベッカ（覚醒1以上）がチームにいる場合、ダメージを与えた時に<color=#00F6FF>侵食を1スタック付与</color>する",
  str_skill_passive_desc_465215 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>上のイーサの通常攻撃は<color=#00F6FF>65%</color>のダメージを3回与える。イーサの通常攻撃、連鎖技が同一の敵に累計で<color=#00F6FF>6回</color>のダメージを与えた時、イーサの攻撃力の<color=#00F6FF>150%</color>のダメージを追加で1回与える。能動技がターゲットに命中した後、ただちに追加でダメージを1回与える。イーサとレベッカ（覚醒1以上）がチームにいる場合、ダメージを与えた時に<color=#00F6FF>侵食を1スタック付与</color>する",
  str_skill_name_70011101 = "末極・蝕毒",
