  str_skill_desc_2202142 = "<color=#00F6FF>縦、横、斜めの16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内のターゲットに侵食を<color=#00F6FF>1</color>スタック付与する",
  str_skill_desc_2202143 = "<color=#00F6FF>縦、横、斜めの最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内のターゲットに侵食を<color=#00F6FF>1</color>スタック付与する",
  str_skill_desc_2302141 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内のターゲットに侵食を<color=#00F6FF>1</color>スタック付与する",
  str_skill_desc_2302142 = "<color=#00F6FF>縦、横、斜めの16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内のターゲットに侵食を<color=#00F6FF>1</color>スタック付与する",
  str_skill_desc_2302143 = "<color=#00F6FF>縦、横、斜めの最大</color>範囲に<color=#00F6FF>{1}%</color>のダメージを与える。範囲内のターゲットに侵食を<color=#00F6FF>1</color>スタック付与する",
  str_skill_desc_2402141 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>145%</color>のダメージを与える。範囲内のターゲットに侵食を<color=#00F6FF>2</color>スタック付与する",
  str_skill_desc_2402142 = "<color=#00F6FF>縦、横、斜めの16マス</color>に<color=#00F6FF>160%</color>のダメージを与える。範囲内のターゲットに侵食を<color=#00F6FF>2</color>スタック付与する",
  str_skill_desc_2402143 = "<color=#00F6FF>縦、横、斜めの最大</color>範囲に<color=#00F6FF>165%</color>のダメージを与える。範囲内のターゲットに侵食を<color=#00F6FF>2</color>スタック付与する",
  str_skill_desc_3002141 = "1マス選択して水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える。さらにそのマスから最も近くにある<color=#00F6FF>3</color>つの水属性マスを水属性の濃色マスに変える",
  str_skill_desc_3062141 = "1マス選択して水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える。さらにそのマスから最も近くにある<color=#00F6FF>5</color>つの水属性マスを水属性の濃色マスに変える",
  str_skill_passive_name_410214 = "毒液拡散",
  str_skill_passive_desc_410214 = "濃色マスを通過するたびに、<color=#00F6FF>菱形12マス</color>の範囲に<link=\"30094\"><#FFAE07><u>侵食</u></color></link>効果を付与する。暗鬼のターン開始時、侵食1スタックにつき、ターゲットに攻撃力の<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_name_430214 = "毒液拡散",
  str_skill_passive_desc_430214 = "濃色マスを通過するたびに、<color=#00F6FF>菱形12マス</color>の範囲に<link=\"30094\"><#FFAE07><u>侵食</u></color></link>効果を付与する。暗鬼のターン開始時、侵食1スタックにつき、ターゲットに攻撃力の<color=#00F6FF>{1}</color>のダメージを与える。連鎖技で攻撃された敵はこのターンの侵食ダメージが防御力無視になる",
  str_skill_upgrade_desc_16021413 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16021416 = "能動技強化：選択したマスから最も近い<color=#FFFF00>5</color>つの水属性マスを濃色マスに変える",
  str_skill_upgrade_refine_desc_16021411 = "装備技強化：侵食1スタックにつき、ターゲットにレベッカの攻撃力の<color=#00F6FF>40%</color>のダメージを与える",
  str_skill_upgrade_refine_desc_16021412 = "連鎖技強化：連鎖技で範囲内のターゲットに侵食を<color=#00F6FF>2</color>スタック付与する",
  str_skill_upgrade_refine_desc_16021413 = "能動技強化：能動技発動時、侵食効果を持つターゲットに2倍のダメージを1回与える。",
  str_skill_passive_desc_440214 = "濃色マスを通過するたびに、<color=#00F6FF>菱形12マス</color>の範囲に<link=\"30094\"><#FFAE07><u>侵食</u></color></link>効果を付与する。暗鬼のターン開始時、侵食1スタックにつき、ターゲットに攻撃力の<color=#00F6FF>40%</color>のダメージを与える。連鎖技で攻撃された敵はこのターンの侵食ダメージが防御力無視になる",
  str_skill_desc_3402141 = "1マス選択して水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える。さらにそのマスから最も近くにある<color=#00F6FF>3</color>つの水属性マスを水属性の濃色マスに変える。その後、全範囲の侵食効果を持つターゲットに2倍のダメージを1回与える。",
  str_skill_desc_3462141 = "1マス選択して水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える。さらにそのマスから最も近くにある<color=#00F6FF>5</color>つの水属性マスを水属性の濃色マスに変える。その後、全範囲の侵食効果を持つターゲットに2倍のダメージを1回与える。",
