  str_skill_name_290910103 = "蝶影の毒群",
  str_skill_name_290910104 = "召蝶の毒襲",
  str_skill_desc_290910102 = "移動後、十字方向2マスの範囲内にいる敵を攻撃し、「融体」効果を2スタック付与する。毎ターン開始時、「融体」効果1スタックにつき、レベッカ・毒沼の攻撃力と一定の比率に応じてダメージを与える",
  str_skill_desc_290910103 = "ターゲットから離れ、ダメージを与えて「融体」効果を1スタック付与する。毎ターン開始時、「融体」効果1スタックにつき、レベッカ・毒沼の攻撃力と一定の比率に応じてダメージを与える",
  str_skill_desc_290910104 = "移動後、固定範囲にダメージを与え、「融体」効果を3スタック付与する。範囲内にランダムで複数の「毒痕」を生成する",
  str_skill_name_200390101 = "機械的打撃",
  str_skill_desc_200390101 = "最も近くにいる敵ターゲットを攻撃する。自身のHP比率が40%未満の場合、遠くに移動した後で自身のHPを一定割合回復する",
  str_skill_name_200390102 = "治療続攻",
  str_skill_desc_200390102 = "自身のHPを一定割合回復する",
  str_skill_name_200410101 = "暗殺進攻",
  str_skill_desc_200410101 = "移動後、ターゲットを2回攻撃し、最大2マス後退する。範囲内にターゲットがいない場合、次のターンの移動力が上昇する",
