  str_skill_name_200140111 = "触手・ダメージ回避",
  str_skill_desc_200140111 = "ダメージを受けた時、ダメージをタコニャン本体に伝える。光霊が連鎖技を発動しようとすると、触手は引っ込み、攻撃を避ける",
  str_skill_name_5000591 = "黒金者・退散",
