  str_skill_name_5000593 = "逃亡者",
  str_skill_desc_5000593 = "光霊の能動技発動後、移動し、さらにランダムで雷属性マスを火属性マスに変える",
  str_skill_name_5000594 = "集団意識",
  str_skill_desc_5000594 = "どこにいても、常に黒金者の所へ集まっていく",
  str_skill_name_29092001 = "鈎刺旋斬",
  str_skill_desc_29092001 = "蠍が自身の周囲1マス以内にいるターゲットに2回ダメージを与え、さらに出血効果を付与する",
  str_skill_desc_290920011 = "蠍が自身の周囲1マス以内にいるターゲットに2回ダメージを与える。さらに出血効果と回復無効を付与する",
  str_skill_name_29092002 = "鉄躯の衝撃",
  str_skill_desc_29092002 = "蠍が十字方向のうちプレイヤーのいる方向のフィールドの端、または最も近くにある障害物までダッシュし、途中にいるターゲットをノックバックする。また、移動経路の両側1マスの範囲にいるターゲットに追加ダメージを与え、さらに出血効果を付与する",
  str_skill_name_29092003 = "機雷燃心",
  str_skill_desc_29092003 = "蠍が尾からエネルギーを放出し、ターゲットに大ダメージを1回与える",
  str_skill_name_29092004 = "毒血の刺撃",
  str_skill_desc_29092004 = "蠍が後方にジャンプして1マス下がり、前方のターゲットにダメージを与え、出血効果と毒効果を付与する",
  str_skill_name_29092005 = "縦横突進",
  str_skill_desc_29092005 = "蠍が縦横2回連続でダッシュし、目の前のターゲットにダメージを与える。さらに出血効果と毒効果を付与する",
  str_skill_name_29092006 = "鏡蝶反射",
  str_skill_desc_29092006 = "蠍が鏡蝶に雷光を放ち、鏡蝶の反射光と合わせた三角形のルート上にダメージを与える",
  str_skill_name_2002161 = "奇傘引機",
  str_skill_name_2002162 = "奇傘引機",
  str_skill_name_2002163 = "奇傘引機",
  str_skill_name_2202161 = "奇傘引機",
  str_skill_name_2202162 = "奇傘引機",
  str_skill_name_2202163 = "奇傘引機",
  str_skill_name_300216 = "雷光奇制",
  str_skill_name_303216 = "雷光奇制",
  str_skill_passive_name_410216 = "紛華銅蜻蜓",
  str_skill_passive_name_430216 = "紛華銅蜻蜓",
  str_skill_desc_2002161 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002162 = "最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002163 = "最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2202161 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える。その後、ランダムで「四方布雷陣」内の敵1体にダメージを1回与える",
  str_skill_desc_2202162 = "最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える。その後、ランダムで「四方布雷陣」内の敵1体にダメージを1回与える",
  str_skill_desc_2202163 = "最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える。その後、ランダムで「四方布雷陣」内の敵1体にダメージを1回与える",
  str_skill_desc_300216 = "<link=\"30095\"><#FFAE07><u>機械設計図</u></color></link>を3枚消費して、1マス選択し、<color=#00F6FF>正方形9マス</color>の範囲内に「四方布雷陣」を設置する。<color=#00F6FF>2</color>ターン持続。「四方布雷陣」内では、センキョクが通常攻撃で<color=#00F6FF>斜め方向に攻撃できる</color>",
  str_skill_desc_303216 = "<link=\"30095\"><#FFAE07><u>機械設計図</u></color></link>を3枚消費して、1マス選択し、<color=#00F6FF>正方形25マス</color>の範囲内に「四方布雷陣」を設置する。<color=#00F6FF>3</color>ターン持続。「四方布雷陣」内では、センキョクが通常攻撃で<color=#00F6FF>斜め方向に攻撃できる</color>",
  str_skill_passive_desc_410216 = "センキョクが「四方布雷陣」内で与えるダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_416216 = "センキョクが「四方布雷陣」内で与えるダメージ+<color=#00F6FF>{1}</color>。フィールド上に「四方布雷陣」が1つ増えるたび、追加でダメージ+<color=#00F6FF>5%</color>。ターン終了時、センキョクが「四方布雷陣」内にいる場合、機械設計図を1枚獲得する",
  str_skill_passive_desc_430216 = "センキョクが「四方布雷陣」内で与えるダメージ+<color=#00F6FF>{1}</color>。センキョクが「四方布雷陣」内で連鎖技を発動した場合、1回の発動につき、基礎攻撃力+<color=#00F6FF>4%</color>。この効果は最高で5スタック重ね掛けできる。ターン終了時、「四方布雷陣」内にいない場合、スタック数が半減する",
  str_skill_passive_desc_436216 = "センキョクが「四方布雷陣」内で与えるダメージ+<color=#00F6FF>{1}</color>。フィールド上に「四方布雷陣」が1つ増えるたび、追加でダメージ+<color=#00F6FF>5%</color>。ターン終了時、センキョクが「四方布雷陣」内にいる場合、機械設計図を1枚獲得する。センキョクが「四方布雷陣」内で連鎖技を発動した場合、1回の発動につき、基礎攻撃力+<color=#00F6FF>4%</color>。この効果は最高で5スタック重ね掛けできる。ターン終了時、「四方布雷陣」内にいない場合、スタック数が半減する",
  str_skill_upgrade_desc_16021613 = "能動技強化：「四方布雷陣」の範囲が<color=#00F6FF>正方形25マス</color>に拡大する。<color=#00F6FF>3</color>ターン持続。",
  str_skill_upgrade_desc_16021616 = "装備技強化：フィールド上に「四方布雷陣」が1つ増えるたび、追加でダメージ+<color=#00F6FF>5%</color>。ターン終了時、センキョクが「四方布雷陣」内にいる場合、機械設計図を1枚獲得する",
  str_skill_name_53820323 = "光霊が近づくと爆発する。近づく光霊がいない場合、一定ターン後自爆し、近くに若干数の火炎マスを設置する",
  str_skill_name_200400103 = "腹炎の突撃",
  str_skill_name_200400104 = "腹炎の突撃",
  str_skill_desc_200400103 = "横向きに移動し、炎を噴射して前方のターゲットにダメージを与える。障害物に当たると移動を停止する。",
  str_skill_desc_200400104 = "横向きに移動し、炎を噴射して前方のターゲットにダメージを与える。障害物に当たると移動を停止する。",
  str_skill_name_290570123 = "マッドバンドル・呑食",
  str_skill_desc_290570123 = "マッドバンドルがぬかるみの中心に現れてすべてを飲み込み、光霊にダメージを与える",
  str_skill_name_290620102 = "空間切断・緯",
  str_skill_desc_290620102 = "邪剣が味方付近まで突進して斬りつけ、ダメージを与える。また、味方の周囲に横方向3マスの長さの禁壁を設置し、自身は別の位置に瞬間移動する",
  str_skill_name_290620104 = "空間切断・経",
  str_skill_desc_290620104 = "邪剣が味方付近まで突進して斬りつけ、ダメージを与える。また、味方の周囲に縦方向3マスの長さの禁壁を設置し、自身は別の位置に瞬間移動する",
  str_skill_name_290620106 = "生者払い",
  str_skill_desc_290620106 = "邪剣が周囲1マス以内の敵にダメージを与え、最遠までノックバックする。また、自身の周囲1マス範囲の境界に禁壁を設置する",
  str_skill_name_800400011 = "退邪装置",
  str_skill_desc_800400011 = "退邪装置のあるマスを通過すると、フィールド上のすべての禁壁を消去できる",
  str_skill_desc_2900273 = "任意の位置にいる光霊にダメージを与え、黒金者を召喚する",
  str_skill_desc_2000303 = "黒金者の周囲1マス範囲に近づき、コインを上納して、HPを回復する",
  str_skill_desc_2000304 = "イスタバンの周囲1マス範囲に近づき、コインを上納して、HPを回復する",
  str_skill_desc_200381101 = "移動範囲が広がり、ターゲットの近くへ移動して相手にダメージを2回与える。障害物を乗り越えて移動できる",
  str_skill_desc_200411101 = "移動後、ターゲットを2回攻撃し、ノックバックして爆弾を残す。その後、最大3マス後退する。範囲内にターゲットがいない場合、次のターンの移動力が上昇する",
  str_skill_desc_200371101 = "十字方向の距離3マス以内の敵にダメージを与え、ノックバックする。ノックバックされる前の位置に爆弾を残す",
  str_skill_upgrade_desc_16021913 = "能動技強化：戦闘開始時に影の天賦を<color=#00F6FF>5</color>Pt獲得する\n装備技強化：【落棋】の選択範囲が周囲2マスに拡大される",
  str_skill_upgrade_desc_16021916 = "新能動技獲得：<color=#00F6FF>2</color>マス選択し、そのマス上の濃色マスを入れ替える。選択したマスに影棋が含まれている場合、影棋はもう一方のマスへ移動する",
  str_skill_name_2002191 = "セブンスランク",
  str_skill_name_2002192 = "セブンスランク",
  str_skill_name_2002193 = "セブンスランク",
  str_skill_desc_2002191 = "<color=#00F6FF>周囲2マス</color>以内の最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002192 = "<color=#00F6FF>周囲3マス</color>以内の最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002193 = "<color=#00F6FF>周囲4マス</color>以内の最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_name_3002191 = "キャスリング",
  str_skill_name_3302191 = "キャスリング",
  str_skill_name_3032191 = "キャスリング",
  str_skill_name_3332191 = "キャスリング",
  str_skill_name_3062191 = "アンパッサン",
  str_skill_desc_3002191 = "<color=#00F6FF>味方のチームメンバー</color>を1名選び、<link=\"30096\"><#FFAE07><u>影の天賦</u></color></link>を<color=#00F6FF>2</color>Pt消費して、このターン中のその光霊の<color=#00F6FF>連鎖技発動回数+1</color>（効果は累積されない）。追加の連鎖技発動時はチームメンバーの攻撃力がイスタバン・積痕の攻撃力の<color=#00F6FF>100%</color>になる。同時に、イスタバン・積痕はこのターン中、連鎖技を発動できなくなる。この戦闘中、同一のチームメンバーに能動技を1回使用するごとに、影の天賦の消費+1",
  str_skill_desc_3302191 = "<color=#00F6FF>味方のチームメンバー</color>を1名選び、<link=\"30096\"><#FFAE07><u>影の天賦</u></color></link>を<color=#00F6FF>2</color>Pt消費して、このターン中のその光霊の<color=#00F6FF>連鎖技発動回数+1</color>（効果は累積されない）。追加の連鎖技発動時はチームメンバーの攻撃力がイスタバン・積痕の攻撃力の<color=#00F6FF>100%</color>になる。同時にイスタバン・積痕はこのターン中、連鎖技を発動できなくなる。または影の天賦を<color=#00F6FF>2</color>Pt消費し、フィールド上の影棋を選択して能動技を発動すると、このターンは影棋がイスタバン・積痕の代わりに連鎖技を発動し、最終ダメージ+<color=#00F6FF>50%</color>。影棋に対して発動するとき、影の天賦の消費は常に2になる。この戦闘中、同一のチームメンバーに能動技を1回使用するごとに、影の天賦の消費+1",
  str_skill_desc_3032191 = "<color=#00F6FF>味方のチームメンバー</color>を1名選び、<link=\"30097\"><#FFAE07><u>影の天賦</u></color></link>を<color=#00F6FF>2</color>Pt消費して、このターン中のその光霊の<color=#00F6FF>連鎖技発動回数+1</color>（効果は累積されない）。追加の連鎖技発動時はチームメンバーの攻撃力がイスタバン・積痕の攻撃力の<color=#00F6FF>100%</color>になる。同時にイスタバン・積痕はこのターン中、連鎖技を発動できなくなる。この戦闘中、同一のチームメンバーに能動技を1回使用するごとに、影の天賦の消費+1",
  str_skill_desc_3332191 = "<color=#00F6FF>味方のチームメンバー</color>を1名選び、<link=\"30097\"><#FFAE07><u>影の天賦</u></color></link>を<color=#00F6FF>2</color>Pt消費して、このターン中のその光霊の<color=#00F6FF>連鎖技発動回数+1</color>（効果は累積されない）。追加の連鎖技発動時はチームメンバーの攻撃力がイスタバン・積痕の攻撃力の<color=#00F6FF>100%</color>になる。同時にイスタバン・積痕はこのターン中、連鎖技を発動できなくなる。または影の天賦を<color=#00F6FF>2</color>Pt消費し、フィールド上の影棋を選択して能動技を発動すると、このターンは影棋がイスタバン・積痕の代わりに連鎖技を発動し、最終ダメージ+<color=#00F6FF>50%</color>。影棋に対して発動するとき、影の天賦の消費は常に2になる。この戦闘中、同一のチームメンバーに能動技を1回使用するごとに、影の天賦の消費+1",
  str_skill_desc_3062191 = "<color=#00F6FF>2</color>マス選択し、2個のマス上の濃色マスを入れ替える。選択したマスに影棋が含まれている場合、影棋はもう一方のマスへ移動する",
  str_skill_passive_name_410219 = "プロモーション",
  str_skill_passive_name_420219 = "プロモーション",
  str_skill_passive_name_403219 = "プロモーション",
  str_skill_passive_name_423219 = "プロモーション",
  str_skill_passive_desc_410219 = "戦闘開始時にイスタバン・積痕がチームの周りに影棋を1体呼び出し、影棋を操って技を発動できる\n【落棋】：周囲の<color=#00F6FF>菱形12マス</color>以内の移動可能なマスに瞬間移動し、<color=#00F6FF>周囲2マス</color>の範囲内で最も近くにいる敵4体に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_420219 = "戦闘開始時にイスタバン・積痕がチームの周りに影棋を1体呼び出し、影棋を操って技を発動できる。ターン終了時に影棋がいる場所に<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を生成する\n【落棋】：周囲の<color=#00F6FF>菱形12マス</color>以内の移動可能なマスに瞬間移動し、<color=#00F6FF>周囲2マス</color>の範囲内で最も近くにいる敵4体に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_403219 = "戦闘開始時にイスタバン・積痕がチームの周りに影棋を1体呼び出し、影棋を操って技を発動できる\n【落棋】：周囲<color=#00F6FF>2マス</color>以内の移動可能なマスに瞬間移動し、<color=#00F6FF>周囲2マス</color>の範囲内で最も近くにいる敵4体に<color=#00F6FF>{1}</color>のダメージを与える",
