  str_skill_upgrade_refine_desc_16021911 = "装備技強化：【落棋】の技ダメージが<color=#00F6FF>110%</color>に上昇",
  str_skill_upgrade_refine_desc_16021912 = "能動技強化：影棋を選択して能動技を発動したとき、ターン内で影棋が放つ連鎖技の最終ダメージ強化効果が<color=#00F6FF>60%</color>に上昇",
