  str_skill_passive_desc_450219 = "戦闘開始時にイスタバン・積痕がチームの周りに影棋を1体呼び出し、影棋を操って技を発動できる。ターン終了時に影棋がいる場所に<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を生成する\n【落棋】：周囲の<color=#00F6FF>菱形12マス</color>以内の移動可能なマスに瞬間移動し、<color=#00F6FF>周囲2マス</color>の範囲内で最も近くにいる敵4体に<color=#00F6FF>110%</color>のダメージを与える",
  str_skill_passive_desc_453219 = "戦闘開始時にイスタバン・積痕がチームの周りに影棋を1体呼び出し、影棋を操って技を発動できる。ターン終了時に影棋がいる場所に<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を生成する\n【落棋】：周囲<color=#00F6FF>2マス</color>以内の移動可能なマスに瞬間移動し、<color=#00F6FF>周囲2マス</color>の範囲内で最も近くにいる敵4体に<color=#00F6FF>110%</color>のダメージを与える",
  str_skill_desc_3602191 = "<link=\"30096\"><#FFAE07><u>影の天賦</u></color></link>を<color=#00F6FF>2</color>Pt消費し、<color=#00F6FF>味方のチームメンバー</color>を1名選び、このターン中のその光霊の<color=#00F6FF>連鎖技発動回数+1</color>（効果は累積されない）。追加の連鎖技発動時はチームメンバーの攻撃力がイスタバン・積痕の攻撃力の<color=#00F6FF>100%</color>になる。同時にイスタバン・積痕はこのターン中、連鎖技を発動できなくなる。または影の天賦を<color=#00F6FF>2</color>Pt消費し、フィールド上の影棋を選択して能動技を発動すると、このターンは影棋がイスタバン・積痕の代わりに連鎖技を発動し、最終ダメージ+<color=#00F6FF>60%</color>。影棋に対して発動したとき、影の天賦の消費は常に2になる。この戦闘中、同一のチームメンバーに能動技を1回使用するごとに、影の天賦の消費+1",
  str_skill_desc_3632191 = "<link=\"30097\"><#FFAE07><u>影の天賦</u></color></link>を<color=#00F6FF>2</color>Pt消費し、<color=#00F6FF>味方のチームメンバー</color>を1名選び、このターン中のその光霊の<color=#00F6FF>連鎖技発動回数+1</color>（効果は累積されない）。追加の連鎖技発動時はチームメンバーの攻撃力がイスタバン・積痕の攻撃力の<color=#00F6FF>100%</color>になる。同時にイスタバン・積痕はこのターン中、連鎖技を発動できなくなる。または影の天賦を<color=#00F6FF>2</color>Pt消費し、フィールド上の影棋を選択して能動技を発動すると、このターンは影棋がイスタバン・積痕の代わりに連鎖技を発動し、最終ダメージ+<color=#00F6FF>60%</color>。影棋に対して発動したとき、影の天賦の消費は常に2になる。この戦闘中、同一のチームメンバーに能動技を1回使用するごとに、影の天賦の消費+1",
  str_skill_desc_3702191 = "<link=\"30099\"><#FFAE07><u>影の天賦</u></color></link>を<color=#00F6FF>2</color>Pt消費し、<color=#00F6FF>味方のチームメンバー</color>を1名選び、このターン中のその光霊の<color=#00F6FF>連鎖技発動回数+1</color>（効果は累積されない）。追加の連鎖技発動時にチームメンバーの攻撃力はイスタバン・積痕の攻撃力の<color=#00F6FF>100%</color>になる。同時にイスタバン・積痕はこのターン中、連鎖技を発動できなくなる。または影の天賦を<color=#00F6FF>2</color>Pt消費し、フィールド上の影棋を選択して能動技を発動すると、このターンは影棋がイスタバン・積痕の代わりに連鎖技を発動し、最終ダメージ+<color=#00F6FF>60%</color>。影棋に対して発動したとき、影の天賦の消費は常に2になる。この戦闘中、同一のチームメンバーに能動技を1回使用するごとに、影の天賦の消費+1",
  str_skill_desc_3732191 = "<link=\"30098\"><#FFAE07><u>影の天賦</u></color></link>を<color=#00F6FF>2</color>Pt消費し、<color=#00F6FF>味方のチームメンバー</color>を1名選び、このターン中のその光霊の<color=#00F6FF>連鎖技発動回数+1</color>（効果は累積されない）。追加の連鎖技発動時はチームメンバーの攻撃力がイスタバン・積痕の攻撃力の<color=#00F6FF>100%</color>になる。同時にイスタバン・積痕はこのターン中、連鎖技を発動できなくなる。または影の天賦を<color=#00F6FF>2</color>Pt消費し、フィールド上の影棋を選択して能動技を発動すると、このターンは影棋がイスタバン・積痕の代わりに連鎖技を発動し、最終ダメージ+<color=#00F6FF>60%</color>。影棋に対して発動したとき、影の天賦の消費は常に2になる。この戦闘中、同一のチームメンバーに能動技を1回使用するごとに、影の天賦の消費+1",
