  str_skill_name_3022201 = "八方美品",
  str_skill_desc_20022011 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>125%</color>のダメージを2回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2002202 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>130%</color>のダメージを3回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2002203 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>135%</color>のダメージを4回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_3002201 = "最も近くの雷属性のマス<color=#00F6FF>2</color>つを水属性の濃色マスに変える",
  str_skill_desc_3002202 = "最も近くの雷属性のマス<color=#00F6FF>2</color>つを水属性の濃色マスに変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3052201 = "最も近くの雷属性のマス<color=#00F6FF>3</color>つを水属性の濃色マスに変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_desc_3052202 = "最も近くの雷属性のマス<color=#00F6FF>3</color>つを水属性の濃色マスに変える。前のターンで能動技が発動可能だった場合、このターンの転色数<color=#00F6FF>+1</color>",
  str_skill_passive_name_410220 = "珠玉の輝き",
  str_skill_passive_name_420220 = "珠玉の輝き",
  str_skill_passive_name_430220 = "珠玉の輝き",
  str_skill_passive_desc_410220 = "毎ターン開始時、フィールド上の最も遠くにいる敵1体に<color=#00F6FF>鑑定</color>効果を付与する。1ターン持続。鑑定効果を持つターゲットは単体ダメージタイプの連鎖技攻撃を1回受けるごとに、追加でバージルの攻撃力の<color=#00F6FF>{1}</color>相当のダメージを1回受ける",
  str_skill_passive_desc_420220 = "毎ターン開始時、フィールド上の最も遠くにいる敵1体に<color=#00F6FF>鑑定</color>効果を付与する。1ターン持続。極光タイム発動時、この効果が追加で1回有効になる。鑑定効果を持つターゲットは単体ダメージタイプの連鎖技攻撃を1回受けるごとに、追加でバージルの攻撃力の<color=#00F6FF>{1}</color>相当のダメージを1回受ける",
  str_skill_passive_desc_430220 = "毎ターン開始時、フィールド上の最も遠くにいる敵1体に<color=#00F6FF>鑑定</color>効果を付与する。1ターン持続。極光タイム発動時、この効果が追加で1回有効になる。鑑定効果を持つターゲットは単体ダメージタイプの連鎖技攻撃を1回受けるごとに、追加でバージルの攻撃力の<color=#00F6FF>{1}</color>相当のダメージで追撃を1回受ける。ターゲットがバージルの連鎖技攻撃を受けたとき、追加攻撃のダメージが2倍になる",
  str_skill_upgrade_desc_15022012 = "能動技強化：前のターンで技が発動可能だった場合、追加で雷属性のマス1つを水属性の濃色マスに変える",
  str_skill_upgrade_desc_15022015 = "能動技強化：水属性の濃色マスへの変換数+1",
  str_skill_desc_290910114 = "移動後、固定範囲にダメージを与え、「融体」効果を3スタック付与する",
  str_skill_desc_290910124 = "移動後、固定範囲にダメージを与え、「融体」効果を3スタック付与する。さらに大量の「毒痕」を生成する",
