  str_skill_passive_name_430218 = "資本分析",
  str_skill_passive_name_433218 = "資本分析",
  str_skill_passive_name_436218 = "資本分析",
  str_skill_desc_2002181 = "固定された順序で<color=#00F6FF>周囲2マス</color>の範囲内にいる敵に<color=#00F6FF>150%</color>のダメージを3回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する",
  str_skill_desc_2002182 = "固定された順序で<color=#00F6FF>周囲3マス</color>の範囲内にいる敵に<color=#00F6FF>155%</color>のダメージを4回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する",
  str_skill_desc_2002183 = "固定された順序で<color=#00F6FF>周囲3マス</color>の範囲内にいる敵に<color=#00F6FF>165%</color>のダメージを5回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する",
  str_skill_desc_2002184 = "固定された順序で<color=#00F6FF>周囲2マス</color>の範囲内にいる敵に<color=#00F6FF>150%</color>のダメージを3回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する。さらに最も遠くにいるターゲットにダメージを1回与える",
  str_skill_desc_2002185 = "固定された順序で<color=#00F6FF>周囲3マス</color>の範囲内にいる敵に<color=#00F6FF>155%</color>のダメージを4回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する。さらに最も遠くにいるターゲットにダメージを1回与える",
  str_skill_desc_2002186 = "固定された順序で<color=#00F6FF>周囲3マス</color>の範囲内にいる敵に<color=#00F6FF>165%</color>のダメージを5回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する。さらに最も遠くにいるターゲットにダメージを1回与える",
  str_skill_desc_2202181 = "固定された順序で<color=#00F6FF>周囲2マス</color>の範囲内にいる敵に<color=#00F6FF>150%</color>のダメージを3回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する。濃色マスを1つ通過するごとに、その連鎖による連鎖技の範囲が1マス拡大する",
  str_skill_desc_2202182 = "固定された順序で<color=#00F6FF>周囲3マス</color>の範囲内にいる敵に<color=#00F6FF>155%</color>のダメージを4回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する。濃色マスを1つ通過するごとに、その連鎖による連鎖技の範囲が1マス拡大する",
  str_skill_desc_2202183 = "固定された順序で<color=#00F6FF>周囲3マス</color>の範囲内にいる敵に<color=#00F6FF>165%</color>のダメージを5回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する。濃色マスを1つ通過するごとに、その連鎖による連鎖技の範囲が1マス拡大する",
  str_skill_desc_2202184 = "固定された順序で<color=#00F6FF>周囲2マス</color>の範囲内にいる敵に<color=#00F6FF>150%</color>のダメージを3回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する。さらに最も遠くにいるターゲットに減少回数をカウントしないダメージを1回与える。濃色マスを1つ通過するごとに、その連鎖による連鎖技の範囲が1マス拡大する",
  str_skill_desc_2202185 = "固定された順序で<color=#00F6FF>周囲3マス</color>の範囲内にいる敵に<color=#00F6FF>155%</color>のダメージを4回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する。さらに最も遠くにいるターゲットに減少回数をカウントしないダメージを1回与える。濃色マスを1つ通過するごとに、その連鎖による連鎖技の範囲が1マス拡大する",
  str_skill_desc_2202186 = "固定された順序で<color=#00F6FF>周囲3マス</color>の範囲内にいる敵に<color=#00F6FF>165%</color>のダメージを5回与える。同一ターゲットに複数回ダメージを与える場合、2回目以降はダメージが半減する。さらに最も遠くにいるターゲットに減少回数をカウントしないダメージを1回与える。濃色マスを1つ通過するごとに、その連鎖による連鎖技の範囲が1マス拡大する",
  str_skill_desc_3002181 = "選択した1マスを水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、<color=#00F6FF>十字方向5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_30021811 = "選択した1マスを水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_3402181 = "<color=#FFFF00>発動後の技のCDターン-1</color>。マスを1個選択し、<color=#00F6FF>十字方向5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_3412181 = "<color=#FFFF00>発動後の技のCDターン-1</color>。マスを1個選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_3402182 = "選択した1マスを水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、<color=#00F6FF>十字方向5マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。保有する資本5Ptにつき、追加で配当1Ptを獲得する",
  str_skill_desc_3412182 = "選択した1マスを水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。保有する資本5Ptにつき、追加で配当1Ptを獲得する",
  str_skill_desc_30021812 = "選択した1マスを水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、<color=#00F6FF>十字方向5マス</color>に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_300218112 = "選択した1マスを水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_34021812 = "<color=#FFFF00>発動後の技のCDターン-1</color>。マスを1個選択し、<color=#00F6FF>十字方向5マス</color>に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_34121812 = "<color=#FFFF00>発動後の技のCDターン-1</color>。マスを1個選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_34021822 = "選択した1マスを水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、<color=#00F6FF>十字方向5マス</color>に<color=#00F6FF>150%</color>のダメージを与える。保有する資本5Ptにつき、追加で配当1Ptを獲得する",
  str_skill_desc_34121822 = "選択した1マスを水属性の<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>150%</color>のダメージを与える。保有する資本5Ptにつき、追加で配当1Ptを獲得する",
  str_skill_passive_desc_410218 = "戦闘開始後、シェオルは<link=\"510218\"><#FFAE07><u>【投資戦略】</u></color></link>を展開し、資本を蓄積することで戦闘能力を選んで獲得できる（「駆り立てる霧」「大一番」「投機攻撃」は装備がLv3/6/10以上で解放）",
  str_skill_passive_desc_413218 = "戦闘開始後、シェオルは<link=\"513218\"><#FFAE07><u>【投資戦略】</u></color></link>を展開し、資本を蓄積することで戦闘能力を選んで獲得できる。2巡目の投資終了後、その後に獲得する投資1Ptにつき、シェオルの攻撃力+1%、最大で40Ptまで換算（「駆り立てる霧」「大一番」「投機攻撃」は装備がLv3/6/10以上で解放）",
  str_skill_passive_desc_416218 = "戦闘開始後、シェオルは<link=\"516218\"><#FFAE07><u>【投資戦略】</u></color></link>を展開し、資本を蓄積することで戦闘能力を選んで獲得できる。戦闘開始時に資本5Ptを保有し、2巡目の投資終了後、その後に獲得する投資1Ptにつき、シェオルの攻撃力+1%、最大で40Ptまで換算（「駆り立てる霧」「大一番」「投機攻撃」は装備がLv3/6/10以上で解放）",
  str_skill_passive_desc_430218 = "戦闘開始後、シェオルは<link=\"530218\"><#FFAE07><u>【投資戦略】</u></color></link>を展開し、資本を蓄積することで戦闘能力を選んで獲得できる。1巡目の投資終了後、2巡目の投資を続けることができ、1巡目の投資で未獲得の戦闘能力を獲得できる。（「駆り立てる霧」「大一番」「投機攻撃」は装備がLv3/6/10以上で解放）",
  str_skill_passive_desc_433218 = "戦闘開始後、シェオルは<link=\"533218\"><#FFAE07><u>【投資戦略】</u></color></link>を展開し、資本を蓄積することで戦闘能力を選んで獲得できる。1巡目の投資終了後、2巡目の投資を続けることができ、1巡目の投資で未獲得の戦闘能力を獲得できる。2巡目の投資終了後、その後に獲得する投資1Ptにつき、シェオルの攻撃力+1%、最大で40Ptまで換算（「駆り立てる霧」「大一番」「投機攻撃」は装備がLv3/6/10以上で解放）",
  str_skill_passive_desc_436218 = "戦闘開始後、シェオルは<link=\"536218\"><#FFAE07><u>【投資戦略】</u></color></link>を展開し、資本を蓄積することで戦闘能力を選んで獲得できる。1巡目の投資終了後、2巡目の投資を続けることができ、1巡目の投資で未獲得の戦闘能力を獲得できる。戦闘開始時に資本5Ptを保有し、2巡目の投資終了後、その後に獲得する投資1Ptにつき、シェオルの攻撃力+1%、最大で40Ptまで換算（「駆り立てる霧」「大一番」「投機攻撃」は装備がLv3/6/10以上で解放）",
  str_skill_upgrade_desc_16021813 = "装備技強化：2回目の投資終了後、その後に獲得する投資1Ptにつき、シェオルの攻撃力+1%、最大で40Ptまで換算（覚醒3で解放）",
  str_skill_upgrade_desc_16021816 = "戦闘開始時に資本5Ptを獲得し、能動技発動時に保有する資本5Ptにつき、追加で配当1Ptを獲得する",
  str_skill_name_53920111 = "通常攻撃",
  str_skill_desc_53920111 = "移動後、敵に通常攻撃を放ち、大ダメージを与える",
  str_skill_desc_53920112 = "移動後、周囲2マスの範囲内にいる敵にダメージを与える",
  str_skill_desc_53920214 = "チームが濃色マスを通過した後、シェオルが周囲2マスの範囲内にいる敵にダメージを2回与える",
  str_skill_upgrade_refine_desc_16021811 = "<color=#00F6FF>能動技変異を追加</color>：<color=#FFFF00>発動後の技のCDターン-1</color>。能動技で水属性の濃色マスを生成せず、ダメージのみを与える",
  str_skill_upgrade_refine_desc_16021812 = "能動技強化：ダメージ+<color=#00F6FF>30%</color>",
  str_skill_upgrade_refine_desc_16021813 = "装備技強化：投資戦略の2巡目の必要資本-1Pt",
  str_skill_name_70011191 = "末極・噬魔舌巻",
  str_skill_desc_70011191 = "ターゲットが範囲内にいる場合、前方2マス以内の光霊と「鬼」を呑み込み、光霊にダメージを与える。その後、横に光霊を吐き出す",
  str_skill_name_70011192 = "末極・噬魔滅鬼",
  str_skill_desc_70011192 = "ターゲットが範囲内にいる時、ターゲットに大ダメージを与え、さらにターゲット周辺の「鬼」を即時に撃破する",
  str_skill_name_70011193 = "末極・噬魔招鬼陣",
  str_skill_desc_70011193 = "ターゲットが範囲内にいる時、大量の「鬼」を召喚し、さらにフィールド上のすべての「鬼」を強化する",
  str_skill_name_70011195 = "末極・噬魔舌巻",
  str_skill_desc_70011195 = "ターゲットが範囲内にいる場合、前方2マス以内の光霊と「鬼」を呑み込み、光霊に確定ダメージを与える。呑み込んだ「鬼」の数が多いほどダメージが大きくなる。その後、横に光霊を吐き出す",
  str_skill_name_200440103 = "断裂打撃",
  str_skill_name_200450103 = "連続爆破",
  str_skill_name_200460103 = "武装急襲",
  str_skill_name_200460104 = "全滅打撃",
  str_skill_desc_200440103 = "武器を振るい、光霊にダメージを与える",
  str_skill_desc_200450103 = "十字形の最大範囲内にいる光霊にダメージを与える",
  str_skill_desc_200460103 = "移動後、光霊にダメージを与える",
  str_skill_desc_200460104 = "移動後、光霊のいる場所に向けて貫通攻撃を放つ。敵味方関係なくダメージを与え、自身の一定のHPを失う",
  str_skill_name_8004003 = "光霊が近づくと爆発する。近づく光霊がいない場合、一定ターン後自爆し、近くに長さ1マスの禁壁を設置する",
  str_skill_desc_8004039 = "このターンのダメージが大幅上昇：双剣がブレードを手にして攻撃範囲内にいるターゲットを2回攻撃する。極めて大きいダメージ",
  str_skill_name_8004039 = "二段斬り+",
  str_skill_desc_8004055 = "邪剣が味方付近まで突進して斬りつけ、ダメージを与える。また、味方の周囲に横方向5マスの長さの禁壁を設置し、自身は別の位置に瞬間移動する",
  str_skill_desc_8004057 = "邪剣が味方付近まで突進して斬りつけ、ダメージを与える。また、味方の周囲に縦方向5マスの長さの禁壁を設置し、自身は別の位置に瞬間移動する",
  str_skill_desc_8004051 = "邪剣が味方付近まで突進して斬りつけ、ダメージを与える。また、味方の周囲に横方向3マスの長さの禁壁を設置し、自身は元の位置に瞬間移動する",
  str_skill_desc_8004053 = "邪剣が味方付近まで突進して斬りつけ、ダメージを与える。また、味方の周囲に縦方向3マスの長さの禁壁を設置し、自身は元の位置に瞬間移動する",
  str_skill_name_8004012 = "召喚・追蜂&プローバノス+",
  str_skill_desc_8004012 = "毎ターン、フィールド上に追蜂とプローバノスを1体ずつ召喚する",
  str_skill_desc_8004022 = "退邪装置のあるマスを通過すると、次のターンから光霊の周囲の禁壁が周囲3マスに再び拡大する",
  str_skill_desc_8004040 = "退邪装置のあるマスを通過すると、敵の周囲に禁壁を生成できる",
  str_skill_desc_8004050 = "退邪装置のあるマスを通過すると、周囲2マスの範囲内にある禁壁を消去できる",
  str_skill_name_290640101 = "万物蹂躙",
  str_skill_name_290640102 = "エネルギー出力",
  str_skill_name_290640103 = "モジュール変更",
  str_skill_desc_290640101 = "移動後、自身の一定割合のHPおよびすべての機械装甲のスタック数を消費し、前方2マスの範囲内にいるターゲットを攻撃する。ターゲットとブローガムが隣接している場合はターゲットを1マスノックバックする。攻撃後、消費した機械装甲のスタック数に応じて自身のHPを回復する",
  str_skill_desc_290640102 = "前方の扇形の範囲内にいるすべてのターゲットにダメージを与える。ターゲットとの距離が近いほどダメージが大きくなる",
  str_skill_desc_290640103 = "ブローガムが力を蓄積して自身の攻撃力、防御力、最大HPを戦闘終了まで上昇させる。さらに機械装甲のスタック数を一定程度獲得する",
  str_skill_name_29063011 = "風速圧迫",
  str_skill_name_29063012 = "光霊のいる位置に狙いをつけ、フィールドの端までダッシュする。さらに途中の範囲内にいる敵にダメージを与える",
  str_skill_name_29063013 = "肉体改造",
  str_skill_desc_29063011 = "光霊に向かって移動した後、前方2マスの範囲内にいるターゲットにダメージを与える",
  str_skill_desc_29063012 = "データ攻撃",
  str_skill_desc_29063013 = "ユリシーズがガーディアン・プロトタイプを利用して任意の位置にいる光霊にダメージを与える",
  str_skill_name_2002211 = "バイナリーツリー",
  str_skill_name_2002212 = "バイナリーツリー",
