  str_skill_desc_2002212 = "ブールが<color=#00F6FF>縦、横、斜めの16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002213 = "ブールが<color=#00F6FF>縦、横、斜めの24マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_name_300221 = "デッドリーコード",
