  str_skill_name_346221 = "デッドリーコード",
  str_skill_desc_300221 = "1マス選択し、その<color=#00F6FF>周囲1マス</color>から3マスを選んで<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、ブールがその範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_306221 = "1マス選択し、その周囲<color=#00F6FF>菱形12マス</color>から4マスを選んで<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変え、ブールがその範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320221 = "1マス選択し、その<color=#00F6FF>周囲1マス</color>から3マスを選んで<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える。ブールがその範囲に<color=#00F6FF>{1}%</color>のダメージを与え、ダメージを与えるたびに演算値を1Pt獲得する",
  str_skill_desc_326221 = "1マス選択し、その周囲<color=#00F6FF>菱形12マス</color>から4マスを選んで<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える。ブールがその範囲に<color=#00F6FF>{1}%</color>のダメージを与え、ダメージを与えるたびに演算値を1Pt獲得する",
  str_skill_desc_340221 = "1マス選択し、その<color=#00F6FF>周囲1マス</color>から3マスを選んで<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える。ブールがその範囲に<color=#00F6FF>250%</color>のダメージを与え、ダメージを与えるたびに演算値を1Pt獲得する",
  str_skill_desc_346221 = "1マス選択し、その周囲<color=#00F6FF>菱形12マス</color>から4マスを選んで<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>に変える。ブールがその範囲に<color=#00F6FF>250%</color>のダメージを与え、ダメージを与えるたびに演算値を1Pt獲得する",
  str_skill_passive_name_410221 = "ナノマジック",
  str_skill_passive_name_430221 = "ナノマジック",
  str_skill_passive_name_440221 = "ナノマジック",
  str_skill_passive_name_443221 = "ナノマジック",
  str_skill_passive_desc_410221 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するごとに演算値を1Pt獲得する。演算値1ポイントにつきブールのダメージ+<color=#00F6FF>{1}</color>。ターン終了時に演算値は半減する",
  str_skill_passive_desc_430221 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するごとに演算値を1Pt獲得する。演算値1ポイントにつきブールのダメージ+<color=#00F6FF>{1}</color>。ターン終了時に演算値は半減する。行動終了時に演算値が<color=#00F6FF>3</color>以上ある場合、ブールからの被ダメージ回数が最も多い敵にブールが<color=#00F6FF>100%</color>の追加ダメージを与える",
  str_skill_passive_desc_440221 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するごとに演算値を1Pt獲得する。演算値1ポイントにつきブールのダメージ+<color=#00F6FF>6%</color>。ターン終了時に演算値は半減する。行動終了時に演算値が<color=#00F6FF>3</color>以上ある場合、ブールからの被ダメージ回数が最も多い敵にブールが<color=#00F6FF>100%</color>の追加ダメージを与える",
  str_skill_passive_desc_443221 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するごとに演算値を1Pt獲得する。演算値1ポイントにつきブールのダメージ+<color=#00F6FF>6%</color>。ターン終了時に演算値は半減する。行動終了時に演算値が<color=#00F6FF>3</color>以上ある場合、ブールからの被ダメージ回数が最も多い敵にブールが<color=#00F6FF>120%</color>の追加ダメージを与える",
  str_skill_upgrade_refine_desc_16022111 = "装備技強化：演算値1ポイントにつき、ブールのダメージ+<color=#00F6FF>6%</color>",
  str_skill_upgrade_refine_desc_16022112 = "能動技強化：能動技のダメージ係数+<color=#00F6FF>30%</color>",
  str_skill_upgrade_refine_desc_16022113 = "装備技強化：ブールの追加ダメージが<color=#00F6FF>120%</color>に上昇する",
  str_skill_upgrade_desc_16022113 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16022116 = "能動技強化：範囲が菱形13マスに拡大し、選択数が4に増える",
