  str_skill_name_802404 = "奇技・感震",
  str_skill_name_802405 = "奇技・失魂",
  str_skill_desc_802401 = "空間さえ折りたたむ金属。進入可能な任意のマスへ転送できる",
  str_skill_desc_802402 = "都市を滅ぼす土石流の残滓。任意の1マスの鉱石や禁壁を除去できる",
  str_skill_desc_802403 = "星が動く時したたる露。使用後、光霊の行動値+7",
  str_skill_desc_802404 = "はるか東方より伝わる火薬武器。1マスの範囲内の敵を最も遠い位置までノックバックし、ダメージを与える",
  str_skill_desc_802405 = "薬草は薬にも毒にもなる。ターゲットを1ターン眩暈状態にする",
  str_skill_desc_80240131 = "シャドウボールのルーンを1回で3つ設置する。3ターン後に治療能力を持つシャドウボールに変わる",
  str_skill_desc_8024441 = "弥染が範囲内のターゲットを攻撃する。攻撃したターゲットの行動値-2",
  str_skill_name_802431111 = "邪心・召喚",
  str_skill_desc_802431111 = "付近の少数の暗鬼を召喚して加勢させる",
  str_skill_desc_8024150 = "吸収装置が周囲の敵に自身のHP上限の30%分のダメージを与える。行動値-5",
  str_skill_desc_8024151 = "吸収装置が自己修復を行い、HP上限の25%分のHPを回復する。行動値-3",
  str_skill_desc_8024152 = "吸収装置がエネルギー物質を放出し、ダメージを防ぐ3重シールドを形成する。行動値-1",
  str_skill_name_80242801 = "身隠しの籠",
  str_skill_desc_80242801 = "壊れにくい頑丈なケージ。中にいる暗鬼がダメージを受けると一部が中核の暗鬼に伝わる。行動値を3消費するとケージから暗鬼を放出できる。",
  str_skill_upgrade_desc_16022313 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16022316 = "能動技強化：技のCD<color=#FFFF00>-1</color>。濃色マスの生成数が5に増加する",
