  str_skill_passive_name_410223 = "絡鱗龍",
  str_skill_passive_name_420223 = "絡鱗龍",
  str_skill_passive_name_430223 = "絡鱗龍",
  str_skill_desc_2002231 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002232 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002233 = "<color=#00F6FF>菱形24マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_3002231 = "自身の周囲8方向から1方向を選び、その方向の前後方向<color=#00F6FF>すべてのマス</color>を雷属性に変える。さらに選択した方向を優先して<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を<color=#00F6FF>3</color>マス生成する",
  str_skill_desc_3062231 = "自身の周囲8方向から1方向を選び、その方向の前後方向<color=#00F6FF>すべてのマス</color>を雷属性に変える。さらに選択した方向を優先して<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を<color=#00F6FF>5</color>マス生成する",
  str_skill_passive_desc_410223 = "シンゲイの通常攻撃が、現在のフィールド上でチームのHP比率との差が最も大きいターゲットに変更され、チームの平均攻撃力の<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_desc_420223 = "シンゲイの通常攻撃が、現在のフィールド上でチームのHP比率との差が最も大きいターゲットに変更され、チームの平均攻撃力の<color=#00F6FF>{1}</color>のダメージを与える。<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するごとに、追加で<color=#00F6FF>1.5</color>倍のダメージ効果を1回発動する",
  str_skill_passive_desc_430223 = "シンゲイの通常攻撃が、現在のフィールド上でチームのHP比率との差が最も大きいターゲットに変更され、チームの平均攻撃力の<color=#00F6FF>{1}</color>のダメージを与える。<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するごとに、追加で<color=#00F6FF>1.5</color>倍のダメージ効果を1回発動する。ダメージ発生時、ターゲットとチームのHP比率との差が大きいほど、このダメージが大きくなる。最大で+<color=#00F6FF>50%</color>",
  str_skill_name_70011211 = "末極・王者の覇気",
  str_skill_name_70011212 = "末極・狂怒の海潮",
  str_skill_upgrade_desc_15022412 = "能動技が<color=#FFFF00>先制攻撃</color>に変わり、戦闘開始後、即時使用可能となる。また、戦闘開始後に守祟浄火を10獲得する",
  str_skill_upgrade_desc_15022415 = "装備技強化：どの属性のマスを通過しても守祟浄火を獲得できる",
  str_skill_name_2002241 = "祟火の炎槌",
  str_skill_name_2002242 = "祟火の炎槌",
  str_skill_name_2002243 = "祟火の炎槌",
  str_skill_name_300224 = "突撃体勢",
  str_skill_name_3002241 = "突撃体勢・変異Ⅰ",
  str_skill_name_3002242 = "突撃体勢・変異Ⅱ",
  str_skill_passive_name_410224 = "一致団結",
  str_skill_passive_name_412224 = "一致団結",
  str_skill_passive_name_415224 = "一致団結",
  str_skill_desc_2002241 = "アテイを投げ、自分から最も近くにいる敵のマスに<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002242 = "アテイを投げ、自分から最も近くにいる敵のマスに<color=#00F6FF>{1}%</color>のダメージを与える。さらにその周囲の<color=#00F6FF>十字方向4マス</color>に30%の飛散ダメージを与える",
  str_skill_desc_2002243 = "アテイを投げ、自分から最も近くにいる敵のマスに<color=#00F6FF>{1}%</color>のダメージを与える。さらにその<color=#00F6FF>周囲1マス</color>に30%の飛散ダメージを与える",
  str_skill_desc_300224 = "自身がこのターンで発動する連鎖技の中心位置として1マス選択し、さらにこのターンの連鎖技の発動条件-3",
  str_skill_desc_3002241 = "<color=#FFFF00>発動後の技のCDターン-1</color>。発動後、そのターンは連鎖技を発動できないが、通常攻撃で斜め方向を攻撃できる。通常攻撃をするごとに、守祟浄火を2獲得する",
  str_skill_desc_3002242 = "<color=#FFFF00>発動後の技のCDターン+1</color>。1マス選択して、自身がこのターンで発動する連鎖技の中心位置とし、さらに<color=#00F6FF>100%</color>のダメージを与える。守祟浄火1につき、ダメージ+10%。このターンでの自身の連鎖技発動条件-3、さらにノックバック効果を付与する",
  str_skill_passive_desc_410224 = "火属性のマスを1マス移動するごとに、守祟浄火を1獲得する。守祟浄火1につき、次回の連鎖技のダメージ+<color=#00F6FF>{1}</color>。連鎖技の発動後はリセットされる。",
  str_skill_passive_desc_412224 = "火属性のマスを1マス移動するごとに、守祟浄火を1獲得する。守祟浄火1につき、次回の連鎖技のダメージ+<color=#00F6FF>{1}</color>。連鎖技の発動後はリセットされる。戦闘開始時に、守祟浄火を10獲得する",
  str_skill_passive_desc_415224 = "1マス移動するごとに、守祟浄火を1獲得する。守祟浄火1につき、次回の連鎖技のダメージ+<color=#00F6FF>{1}</color>。連鎖技の発動後はリセットされる。戦闘開始時に、守祟浄火を10獲得する",
  str_skill_desc_9997040 = "選択した2マスを万色マスに変える。1マス消去するごとに、エネルギーを1獲得する。エネルギーを60獲得すると使用回数が1回増える。使用回数は最大で2回まで蓄積できる",
  str_skill_desc_9997041 = "3×3の範囲を選択し、その中の水属性のマスを消去する。1マス消去するごとに、エネルギーを1獲得する。エネルギーを50獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_desc_9997042 = "3×3の範囲を選択し、その中の火属性のマスを消去する。1マス消去するごとに、エネルギーを1獲得する。エネルギーを50獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_desc_9997043 = "3×3の範囲を選択し、その中の森属性のマスを消去する。1マス消去するごとに、エネルギーを1獲得する。エネルギーを50獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_desc_9997044 = "3×3の範囲を選択し、その中の雷属性のマスを消去する。1マス消去するごとに、エネルギーを1獲得する。エネルギーを50獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_desc_9997045 = "フィールド上のマスをリセットする。1マス消去するごとに、エネルギーを1獲得する。エネルギーを80獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_desc_9997046 = "属性を1つ選択し、フィールド上にあるその属性のマスをリセットする。1マス消去するごとに、エネルギーを1獲得する。エネルギーを80獲得すると使用回数が1回増える。使用回数は最大で2回まで蓄積できる",
  str_skill_desc_9997047 = "1マス選択し、そのマスから最も近い同じ属性のマスを4つリセット消去する。1マス消去するごとに、エネルギーを1獲得する。エネルギーを60獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_name_5066101 = "万色の宝石",
  str_skill_desc_5066101 = "フィールド上のすべてのマスを万色マスに変える",
  str_skill_name_5060801 = "壁を破る者",
  str_skill_desc_5060801 = "2ターン消費して、ただちにLv.2の陣営サポートスキルを1回発動する。1ターンに1回のみ使用可能",
  str_skill_name_20047011 = "削壁貫通",
  str_skill_desc_20047011 = "移動後、隣接する十字方向4マスのターゲットを攻撃し、さらにターゲットを貫通してその周囲のマスに移動する。ターゲットの後ろの1マスを優先的に選択する",
  str_skill_name_5412015 = "召喚・シャドウマン",
  str_skill_desc_5412015 = "毎ターン、シャドウマンが召喚される",
  str_skill_name_9997040 = "光輝大剣",
  str_skill_name_9997046 = "光輝の盾",
  str_skill_name_9997047 = "光輝ランス",
  str_skill_desc_5064701 = "5×5の範囲を選択し、その中の水属性のマスを消去する。1マス消去するごとに、エネルギーを1獲得する。エネルギーを40獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_desc_5064702 = "5×5の範囲を選択し、その中の火属性のマスを消去する。1マス消去するごとに、エネルギーを1獲得する。エネルギーを40獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_desc_5064703 = "5×5の範囲を選択し、その中の森属性のマスを消去する。1マス消去するごとに、エネルギーを1獲得する。エネルギーを40獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_desc_5064704 = "5×5の範囲を選択し、その中の雷属性のマスを消去する。1マス消去するごとに、エネルギーを1獲得する。エネルギーを40獲得すると使用回数が1回増える。使用回数は最大で3回まで蓄積できる",
  str_skill_name_5411002 = "龍護の舞",
  str_skill_desc_5411002 = "菱形24マスの範囲にダメージを与える",
  str_skill_name_5411003 = "召喚・祟霊",
  str_skill_desc_5411003 = "フィールドに祟霊・ネズミを2体召喚する",
  str_skill_desc_5411012 = "マクガフィモが白夜と満潮の到来に備えてエネルギーを蓄積し、自身の前にシャドウマンを数体召喚する",
  str_skill_desc_5411020 = "グスドがランダム位置に、移動できないグスドの従者を4体召喚する",
  str_skill_desc_5411021 = "グスドが範囲内のターゲットに攻撃を加え、破裂の印を1スタック付与する。印のスタック数が多いほどターゲットの防御力が下がる。さらにグスドの従者を2体召喚する",
  str_skill_desc_5411022 = "グスドが咆吼し、範囲内の敵ターゲットに破裂の印を2スタック付与する。印スタック数が多いほどターゲットの防御力が下がる。さらにグスドの従者を2体召喚する",
  str_skill_desc_5411023 = "グスドがターゲットの破裂の印を爆破させ、そのターゲットに大ダメージを与える。印のスタック数が多いほどダメージが大きくなる。さらにグスドの従者を2体召喚する",
  str_skill_desc_5411025 = "グスドがランダムなエリアに従者を4体召喚する。従者は移動できない。",
  str_skill_desc_5411026 = "グスドが範囲内のターゲットに2回猛攻撃を加え、破裂の印を2スタック付与する。スタック数が多いほどターゲットの防御力が下がる。さらにグスドの従者を2体召喚する",
  str_skill_desc_5411027 = "グスドが死に際の咆吼とともに範囲内のターゲットに破裂の印を3スタック付与する。スタック数が多いほどターゲットの防御力が下がる。さらにグスドの従者を2体召喚する",
  str_skill_desc_5411004 = "身隠しの籠を設置する",
  str_skill_name_5411031 = "困",
  str_skill_desc_5411031 = "幻の中では虚実入り混ざる…",
