  str_skill_name_5064702 = "「烈陽」浮遊器",
  str_skill_name_5064703 = "「葉植」浮遊器",
  str_skill_name_5064704 = "「雷霆」浮遊器",
  str_skill_name_5065501 = "ダメージ増強装置",
  str_skill_name_5065601 = "ドロップ缶",
  str_skill_name_5065801 = "移動エネルギー器",
  str_skill_desc_5065501 = "消去後、このターン中の連鎖技ダメージ+35%",
  str_skill_desc_5065601 = "消去後、ランダムな空の末裔の特殊装備1つの使用回数が1増える",
  str_skill_desc_5065801 = "消去後、総ターン数が3増える",
  str_skill_name_29093013 = "新年の歩調",
  str_skill_desc_29093013 = "年獣が前方に3マス跳躍し、着地位置の周囲1マスの範囲にダメージを与えて両側にノックバックする。入口まで跳躍すると門を破壊して中に入る",
  str_skill_name_7001125103 = "末極・怒号",
  str_skill_desc_7001125103 = "末極・狂蹄がフィールド全体の光霊にダメージを与え、自身の移動力を上昇させて岩石を生成する",
  str_skill_name_7001125104 = "末極・砕衝",
  str_skill_desc_7001125104 = "末極・狂蹄が弱化マスをいくつか生成し、光霊に衝突後、さらにノックバックする。途中に岩石がある場合はそれを破壊する",
  str_skill_name_7001125105 = "末極・撃砕",
  str_skill_desc_7001125105 = "末極・狂蹄が移動後、目の前にある2マスを強く撃ち、大ダメージを与え、さらに弱化マスを生成する",
  str_skill_name_7001126103 = "末極・ダークマインド放出",
  str_skill_desc_7001126103 = "末極・チャンドラは光霊から離れて移動した後、周囲2マスの範囲内にいる光霊にダメージを与える",
  str_skill_name_7001126104 = "末極・ネガティブ感情投射",
  str_skill_desc_7001126104 = "末極・チャンドラがフィールド全体の光霊にダメージを与える",
  str_skill_name_80150311 = "鉱石",
  str_skill_desc_80150311 = "ここで十分に阻害した鉱石を、行動値を2消費して除去する",
  str_skill_name_290940103 = "怪火の槍",
  str_skill_desc_290940103 = "アイラが光霊にダメージを与え、さらに光霊の十字方向の最大範囲内で、フィールドの最も外側に怪火を生成する",
  str_skill_name_290940104 = "灼熱爆破",
  str_skill_desc_290940104 = "アイラが自身の周囲2マス以内にいる光霊にダメージを与える",
  str_skill_name_290940105 = "激憤隕石",
  str_skill_desc_290940105 = "アイラが前のターンに光霊がいた位置に隕石を降らせ、致死ダメージを与える。範囲内の中心マスを破壊すると同時に、十字方向4マスに損傷マスを生成する",
  str_skill_name_200480103 = "禁魂怪火",
  str_skill_desc_200480103 = "怪火が範囲内の光霊にダメージを与え、さらにフィールドの反対側に瞬間移動する。プレイヤーを攻撃できなかった場合、フィールドの最も外側を時計回りに2マス瞬間移動する",
  str_skill_name_300226 = "世界をカエル",
  str_skill_name_200226 = "カエルに金棒",
  str_skill_passive_name_400226 = "カエルに染まる",
  str_skill_desc_300226 = "夢境では、火山の噴火を鎮め、天の裂け目を繕うことができるカエル王子。現実でも自分の魅力で仲間を癒したいと思っているのだが…何の役に立つのかって？可愛いだけで十分でしょ！",
  str_skill_desc_200226 = "カエル王子の渾身の一声が、アストラ全土に響き渡る！…何の役に立つのかって？可愛いだけで十分でしょ！",
  str_skill_passive_desc_400226 = "このカエルの鳴き声は、大自然の鼓動であると同時に、アストラの呼吸、さらには果てなき暗闇を照らす光でもある。カエルの賛歌を共に歌い、皆で盛大に祝おう！…何の役に立つのかって？みんなで合唱できたら、それで十分でしょ！",
  str_skill_name_54350081 = "大砲の護衛",
  str_skill_desc_54350081 = "国王をお守りするのは、大砲の責務だ！大砲は光霊の連鎖発動後に退場する",
  str_skill_upgrade_desc_16022513 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始と同時に使用可能になる。範囲内の敵に追加で1ヶ所破綻を生じさせる",
  str_skill_upgrade_desc_16022516 = "装備技強化：<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過した時、50%の確率で破綻を追加で1つ生成する",
