  str_skill_passive_name_4462253 = "雷天一色",
  str_skill_desc_2002251 = "自身を中心に、最も近くにいる敵をターゲットにして、ルート上の列に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002252 = "自身を中心に、最も近くにいる敵をターゲットにして、ルート上および隣接する列に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002253 = "自身を中心に、最も近くにいる敵をターゲットにして、ルート上および隣接する列に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2102251 = "自身を中心に、最も近くにいる敵をターゲットにして、ルート上の列に<color=#00F6FF>{1}%</color>のダメージを与えると同時に、その方向にある破綻を1つ撃破する",
  str_skill_desc_2102252 = "自身を中心に、最も近くにいる敵をターゲットにして、ルート上および隣接する列に<color=#00F6FF>{1}%</color>のダメージを与えると同時に、その方向にある破綻を1つ撃破する",
  str_skill_desc_2102253 = "自身を中心に、最も近くにいる敵をターゲットにして、ルート上および隣接する列に<color=#00F6FF>{1}%</color>のダメージを与えると同時に、その方向にある破綻を最大2つ撃破する",
  str_skill_desc_2302251 = "自身を中心に、最も近くにいる敵をターゲットにして、ルート上の列に<color=#00F6FF>{1}%</color>のダメージを与えると同時に、その方向にある破綻を1つ撃破する",
  str_skill_desc_2302252 = "自身を中心に、最も近くにいる敵をターゲットにして、ルート上および隣接する列に<color=#00F6FF>{1}%</color>のダメージを与えると同時に、その方向にある破綻を1つ撃破する",
  str_skill_desc_2302253 = "自身を中心に、最も近くにいる敵をターゲットにして、ルート上および隣接する列に<color=#00F6FF>{1}%</color>のダメージを与えると同時に、その方向にある破綻を最大2つ撃破する",
  str_skill_desc_300225 = "1マス選択し、その方向の扇形範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_303225 = "1マス選択し、その方向の扇形範囲に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_320225 = "1マス選択し、その方向の扇形範囲に<color=#00F6FF>{1}%</color>のダメージを与え、かつ範囲内の敵に破綻を1つ与える",
  str_skill_desc_323225 = "1マス選択し、その方向の扇形範囲に<color=#00F6FF>{1}%</color>のダメージを与え、かつ範囲内の敵に破綻を2つ与える",
  str_skill_desc_340225 = "1マス選択し、その方向の扇形範囲に<color=#00F6FF>250%</color>のダメージを与え、かつ範囲内の敵に破綻を1つ与える",
  str_skill_desc_343225 = "1マス選択し、その方向の扇形範囲に<color=#00F6FF>250%</color>のダメージを与え、かつ範囲内の敵に破綻を2つ与える",
  str_skill_passive_desc_410225 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、ティアラがフィールド上でHPが最も高い敵に対して自分から最も近い方向に破綻を1つ与える。通常攻撃と連鎖技でこの方向からダメージを与えるたびに、破綻を撃破して<color=#00F6FF>{1}</color>のダメージを与える。敵を倒すと破綻は最も近くにいる他の敵に移る。敵のどの方向にも破綻がある場合、さらに破綻を与えると撃破の半分のダメージを与える",
  str_skill_passive_desc_416225 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、ティアラがフィールド上でHPが最も高い敵に対して自分から最も近い方向に破綻を1つ与える（50%の確率でさらに1つ与える）。通常攻撃と連鎖技でこの方向からダメージを与えるたびに、破綻を撃破して<color=#00F6FF>{1}</color>のダメージを与える。敵を倒すと破綻は最も近くにいる他の敵に移る。敵のどの方向にも破綻がある場合、さらに破綻を与えると撃破の半分のダメージを与える",
  str_skill_passive_desc_430225 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、ティアラがフィールド上でHPが最も高い敵に対して自分から最も近い方向に破綻を1つ与える。通常攻撃と連鎖技でこの方向からダメージを与えるたびに、破綻を撃破して<color=#00F6FF>{1}</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与え、飛散範囲に<color=#00F6FF>{2}</color>のダメージを与える。敵を倒すと破綻は最も近くにいる他の敵に移る。敵のどの方向にも破綻がある場合、さらに破綻を与えると撃破の半分のダメージを与える",
  str_skill_passive_desc_436225 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、ティアラがフィールド上でHPが最も高い敵に対して自分から最も近い方向に破綻を1つ与える（50%の確率でさらに1つ与える）。通常攻撃と連鎖技でこの方向からダメージを与えるたびに、破綻を撃破して<color=#00F6FF>{1}</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与え、飛散範囲に<color=#00F6FF>{2}</color>のダメージを与える。敵を倒すと破綻は最も近くにいる他の敵に移る。敵のどの方向にも破綻がある場合、さらに破綻を与えると撃破の半分のダメージを与える",
  str_skill_passive_desc_440225 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、ティアラがフィールド上でHPが最も高い敵に対して自分から最も近い方向に破綻を1つ与える。通常攻撃と連鎖技でこの方向からダメージを与えるたびに、破綻を撃破して<color=#00F6FF>230%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与え、飛散範囲に<color=#00F6FF>100%</color>のダメージを与える。敵を倒すと破綻は最も近くにいる他の敵に移る。敵のどの方向にも破綻がある場合、さらに破綻を与えると撃破の半分のダメージを与える",
  str_skill_passive_desc_446225 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、ティアラがフィールド上でHPが最も高い敵に対して自分から最も近い方向に破綻を1つ与える（50%の確率でさらに1つ与える）。通常攻撃と連鎖技でこの方向からダメージを与えるたびに、破綻を撃破して<color=#00F6FF>230%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与え、飛散範囲に<color=#00F6FF>100%</color>のダメージを与える。敵を倒すと破綻は最も近くにいる他の敵に移る。敵のどの方向にも破綻がある場合、さらに破綻を与えると撃破の半分のダメージを与える",
  str_skill_passive_desc_4402253 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>通過時と極光タイム発動時、ティアラがフィールド上でHPが最も高い敵に対して自分から最も近い方向に破綻を1つ与える。通常攻撃と連鎖技でこの方向からダメージを与えるたびに、破綻を撃破して<color=#00F6FF>230%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与え、飛散範囲に<color=#00F6FF>100%</color>のダメージを与える。敵を倒すと破綻は最も近くにいる他の敵に移る。敵のどの方向にも破綻がある場合、さらに破綻を与えると撃破の半分のダメージを与える",
  str_skill_passive_desc_4462253 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>通過時と極光タイム発動時、ティアラがフィールド上でHPが最も高い敵に対して自分から最も近い方向に破綻を1つ与える（50%の確率でさらに1つ与える）。通常攻撃と連鎖技でこの方向からダメージを与えるたびに、破綻を撃破して<color=#00F6FF>230%</color>の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与え、飛散範囲に<color=#00F6FF>100%</color>のダメージを与える。敵を倒すと破綻は最も近くにいる他の敵に移る。敵のどの方向にも破綻がある場合、さらに破綻を与えると撃破の半分のダメージを与える",
  str_skill_upgrade_refine_desc_16022511 = "装備技強化：破綻を撃破して与えるダメージが<color=#00F6FF>230%</color>に上がる",
  str_skill_upgrade_refine_desc_16022512 = "能動技強化：能動技のダメージ係数+<color=#00F6FF>50%</color>",
  str_skill_upgrade_refine_desc_16022513 = "装備技強化：極光タイム発動時、フィールド上でHPが最も高い敵に対し自分から最も近い方向に1つ破綻を与える",
  str_skill_desc_70011272 = "タルタロスのエネルギーがあふれだし、縦横4列の範囲にダメージを与える",
  str_skill_desc_70011273 = "タルタロスがムーンリングとなり、範囲内のターゲットにダメージを与え、フィールドの反対側に移動する。移動後、自身の周囲1マスをロックする。ロックされたマスは転色されない",
  str_skill_name_290501142 = "末極・捕食",
  str_skill_name_290501143 = "末極・巻狩",
  str_skill_name_290501144 = "末極・群れの召集",
  str_skill_desc_290501142 = "スパイダークイーンが獲物に飛び掛かる。クモの巣を張ってマスをロックし、光霊にダメージを与える。ロックされたマスは1ターン後、元に戻る",
  str_skill_desc_290501143 = "スパイダークイーンがクモの巣で光霊の周囲のマスをロックする。さらにクイーンに呼び出されたスパイダーベビーが光霊に飛び掛かり、ダメージを与える。ロックされたマスは1ターン後、元に戻る",
  str_skill_desc_290501144 = "スパイダークイーンがベビーを呼び出して攻撃する。スパイダーベビーはクモの巣を張り、大量のマスをロックする。ロックされたマスは1ターン後、元に戻る",
  str_skill_desc_9011062 = "獲得時にCDターン数が最も多い光霊のスキルターン数-1",
  str_skill_name_290420209 = "鎌攻撃",
  str_skill_desc_290420209 = "遊霊の幻影が移動後、前方のターゲットにダメージを与える",
  str_skill_desc_510233 = "出撃中の光霊のスキルターン数-2",
  str_skill_desc_520233 = "ランダムな光霊1人の技のCDを終了させる",
  str_skill_desc_530233 = "出撃中の全光霊の技のCDを終了させる",
  str_skill_desc_292600105 = "「イブ」・哀念が大量の暗力を獲得し、そのスタック数に応じて攻撃強化効果を獲得する。攻撃を受けるたび、暗力のスタック数が減少する",
  str_skill_desc_292600106 = "「イブ」・哀念がターゲットをロックし、ダメージを与える",
