  str_skill_name_290950108 = "根竜巻",
  str_skill_name_290950109 = "根打",
  str_skill_desc_290950105 = "人参・棘根が光霊にダメージを複数回与える。光霊のHPが低いほど、ダメージが大きくなる",
  str_skill_desc_290950106 = "人参・棘根が高速で旋回し、自身の周囲にダメージを複数回与える。ダメージ毎に一定確率で光霊を反時計回り、または外側に1マスノックバックする。命中すると、以降のダメージが低下する",
  str_skill_desc_290950107 = "人参・棘根が光霊にダメージを複数回与える。光霊のHPが低いほど、ダメージが大きくなる",
  str_skill_desc_290950108 = "光霊が根打のスキル効果範囲内にいない場合、人参・棘根が高速で旋回し、自身の周囲にダメージを複数回与える。ダメージ毎に一定確率で光霊を反時計回り、または外側に1マスノックバックする。命中すると、以降のダメージが低下する",
  str_skill_desc_290950109 = "光霊が根打のスキル効果範囲内にいる場合、人参・棘根は巨大なニンジンを下に向かって叩きつけ、光霊にダメージを与え、さらに2マスノックバックする",
  str_skill_name_80060401 = "矛盾のトゲ",
  str_skill_desc_80060401 = "ターン終了時にトゲの上にいる暗鬼に大ダメージを与え、追加で創傷効果を1スタック付与する。見覚えのあるようなトゲだが、今回は通過してもダメージを受けない",
  str_skill_name_80060501 = "召喚・狂犬",
  str_skill_name_80060502 = "召喚・プローバー",
  str_skill_name_80060503 = "召喚・摂魂輪",
  str_skill_desc_80060501 = "狂犬をフィールドに召喚する",
  str_skill_desc_80060502 = "プローバーをフィールドに召喚する",
  str_skill_desc_80060503 = "摂魂輪をフィールドに召喚する",
  str_skill_desc_800637101 = "正確で隠密性が高く、技術的にとても優れた射撃を行い、十字方向の最大範囲内のターゲットに命中させられる",
  str_skill_desc_800638101 = "優れた身のこなしでターゲットから遠ざかった後、ターゲットにダメージを2回与える",
  str_skill_desc_80062201 = "チームの毎ターンの行動値回復量+1",
