  str_skill_name_3032272 = "破滅の製図・消耗",
  str_skill_name_3062272 = "破滅の製図・消耗",
  str_skill_name_3062271 = "破滅の製図",
  str_skill_desc_2002271 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002272 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002273 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_20022712 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える。消耗状態でも発動できるが、その場合はダメージは与えずにターゲットに鷹爪の印を1スタック付与する",
  str_skill_desc_20022722 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える。消耗状態でも発動できるが、その場合はダメージは与えずにターゲットに鷹爪の印を2スタック付与する",
  str_skill_desc_20022732 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える。消耗状態でも発動できるが、その場合はダメージは与えずにターゲットに鷹爪の印を3スタック付与する",
  str_skill_desc_2202271 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える。消耗状態でも発動できるが、その場合はダメージは与えずにターゲットに鷹爪の印を1スタック付与する",
  str_skill_desc_2202272 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える。消耗状態でも発動できるが、その場合はダメージは与えずにターゲットに鷹爪の印を2スタック付与する",
  str_skill_desc_2202273 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える。消耗状態でも発動できるが、その場合はダメージは与えずにターゲットに鷹爪の印を3スタック付与する",
  str_skill_desc_3002271 = "最も近くの雷属性ではないマス<color=#00F6FF>3</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>1</color>つの位置に濃色マスを生成する。\n能動技は次の発動可能状態を待たずに再び発動でき、発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3032271 = "最も近くの雷属性ではないマス<color=#00F6FF>3</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>1</color>つの位置に濃色マスを生成する。\n能動技は次の発動可能状態を待たずに再び発動でき、転色マス数<color=#00F6FF>+2</color>、生成濃色マス数<color=#00F6FF>+1</color>。発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3062271 = "最も近くの雷属性ではないマス<color=#00F6FF>3</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>2</color>つの位置に濃色マスを生成する。\n能動技は次の発動可能状態を待たずに再び発動でき、転色マス数<color=#00F6FF>+2</color>、生成濃色マス数<color=#00F6FF>+1</color>。発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3002272 = "最も近くの雷属性ではないマス<color=#00F6FF>3</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>1</color>つの位置に濃色マスを生成する。\n発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3032272 = "最も近くの雷属性ではないマス<color=#00F6FF>5</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>2</color>つの位置に濃色マスを生成する。\n発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3062272 = "最も近くの雷属性ではないマス<color=#00F6FF>5</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>3</color>つの位置に濃色マスを生成する。\n発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_passive_name_410227 = "大三角陣形",
  str_skill_passive_name_420227 = "大三角陣形",
  str_skill_passive_name_430227 = "大三角陣形",
  str_skill_passive_desc_410227 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>3</color>スタック付与する。敵のターン開始時、印1スタックにつき、ターゲットにレイチェルの現在の攻撃力の<color=#00F6FF>{1}</color>のダメージを与える。ターン終了時にスタック数は半減する。ターゲットが倒されると、鷹爪の印の半分が最も近くにいる他の敵に移る",
  str_skill_passive_desc_420227 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>3</color>スタック付与する。敵のターン開始時、印1スタックにつき、ターゲットにレイチェルの現在の攻撃力の<color=#00F6FF>{1}</color>のダメージを与える。ターン終了時にスタック数は半減する。ターゲットが倒されると、鷹爪の印の半分が最も近くにいる他の敵に移る",
  str_skill_passive_desc_430227 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>3</color>スタック付与する。敵のターン開始時、印1スタックにつき、ターゲットにレイチェルの現在の攻撃力の<color=#00F6FF>{1}</color>のダメージを与える。ターン終了時にスタック数は半減する。ターゲットが倒されると、鷹爪の印の半分が最も近くにいる他の敵に移る。レイチェルが<color=#00F6FF>消耗状態</color>のとき、連鎖1マスごとに自身の攻撃力+<color=#00F6FF>3%</color>",
  str_skill_passive_desc_440227 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>3</color>スタック付与する。敵のターン開始時、印1スタックにつき、ターゲットにレイチェルの現在の攻撃力の<color=#00F6FF>80%</color>のダメージを与える。ターン終了時にスタック数は半減する。ターゲットが倒されると、鷹爪の印の半分が最も近くにいる他の敵に移る。レイチェルが<color=#00F6FF>消耗状態</color>のとき、連鎖1マスごとに自身の攻撃力+<color=#00F6FF>3%</color>",
  str_skill_passive_desc_460227 = "<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するとき、最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>3</color>スタック付与する。敵のターン開始時、印1スタックにつき、ターゲットにレイチェルの現在の攻撃力の<color=#00F6FF>80%</color>のダメージを与える。ターン終了時にスタック数は半減する。ターゲットが倒されると、鷹爪の印の半分が最も近くにいる他の敵に移る。レイチェルが<color=#00F6FF>消耗状態</color>のとき、連鎖1マスごとに自身の攻撃力+<color=#00F6FF>4%</color>",
  str_skill_desc_3502271 = "最も近くの雷属性ではないマス<color=#00F6FF>3</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>1</color>つの位置に濃色マスを生成し、さらに最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>2</color>スタック付与する。\n能動技は次の発動可能状態を待たずに再び発動でき、発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3532271 = "最も近くの雷属性ではないマス<color=#00F6FF>3</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>1</color>つの位置に濃色マスを生成し、さらに最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>2</color>スタック付与する。\n能動技は次の発動可能状態を待たずに再び発動でき、転色マス数<color=#00F6FF>+2</color>、生成濃色マス数<color=#00F6FF>+1</color>。発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3562271 = "最も近くの雷属性ではないマス<color=#00F6FF>3</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>2</color>つの位置に濃色マスを生成し、さらに最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>2</color>スタック付与する。\n能動技は次の発動可能状態を待たずに再び発動でき、転色マス数<color=#00F6FF>+2</color>、生成濃色マス数<color=#00F6FF>+1</color>。発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3502272 = "最も近くの雷属性ではないマス<color=#00F6FF>3</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>1</color>つの位置に濃色マスを生成し、さらに最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>2</color>スタック付与する。\n発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3532272 = "最も近くの雷属性ではないマス<color=#00F6FF>5</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>2</color>つの位置に濃色マスを生成し、さらに最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>2</color>スタック付与する。\n発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_desc_3562272 = "最も近くの雷属性ではないマス<color=#00F6FF>5</color>つを雷属性に変え、そのうちランダムの<color=#00F6FF>3</color>つの位置に濃色マスを生成し、さらに最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>2</color>スタック付与する。\n発動後は能動技CDターン+1、レイチェルが<color=#00F6FF>消耗状態</color>になる。この状態になると通常攻撃と連鎖技を発動できない。能動技が発動可能になると消耗状態が解除される",
  str_skill_upgrade_desc_16022713 = "能動技強化：能動技を次の発動可能状態を待たずに再び発動し、転色マス数<color=#FFFF00>+2</color>、生成濃色マス数<color=#FFFF00>+1</color>",
  str_skill_upgrade_desc_16022716 = "能動技強化：生成濃色マス数<color=#FFFF00>+1</color>",
  str_skill_upgrade_refine_desc_16022711 = "装備技強化：敵のターン開始時、印1スタックにつきターゲットにレイチェルの現在の攻撃力の<color=#00F6FF>80%</color>のダメージを与える",
  str_skill_upgrade_refine_desc_16022712 = "能動技強化：発動後、最も近くにいるターゲットに鷹爪の印を<color=#00F6FF>2</color>スタック付与する",
  str_skill_upgrade_refine_desc_16022713 = "装備技強化：レイチェルが消耗状態の場合、連鎖1マスごとに自身の攻撃力+<color=#00F6FF>4%</color>",
  str_skill_upgrade_desc_15022812 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変え、戦闘開始後ただちに使用できる\n【華麗なる秘技】<color=#FFFF00>先制攻撃</color>が覚醒1で開放",
  str_skill_upgrade_desc_15022815 = "能動技【ミックス爆撃】強化：選択可能なマスの数<color=#FFFF00>+1</color>",
  str_skill_desc_10071120 = "ターゲットが前のターンにいた位置に光線を放ち、目標位置とその途中にいるターゲットにダメージを与える",
  str_skill_desc_10071130 = "範囲内のターゲットをフィールドの中央までノックバックする",
  str_skill_name_54550920 = "触手・ダメージ回避",
  str_skill_desc_54550920 = "光霊が連鎖技を発動する時、触手を縮こめることで攻撃を躱し、同時に自分がいる位置の強化マスを呑み込む",
  str_skill_name_29097013 = "通常攻撃",
  str_skill_desc_29097013 = "移動後、前方にいる光霊にダメージを与える",
  str_skill_name_29097014 = "溶岩衝撃",
  str_skill_desc_29097014 = "光霊のいる方向の扇形エリアに広範囲のダメージを与え、岩石を生成する",
  str_skill_name_29097015 = "灼熱の咆哮",
  str_skill_desc_29097015 = "全範囲に対してダメージを3回与え、毎回1マスノックバックする。ノックバック不可の場合は受けるダメージが増加する",
  str_skill_name_2002281 = "スイート奇襲",
  str_skill_name_2002282 = "スイート奇襲",
  str_skill_name_2002283 = "スイート奇襲",
  str_skill_desc_2002281 = "ゼタが「クナン」を放つ。「クナン」は周囲の菱形12マスの範囲内で最も近くにいる敵を探し出し、ルートを定めて向かい、自爆して十字5マスに<color=#00F6FF>150%</color>のダメージを与える",
  str_skill_desc_2002282 = "ゼタが「クナン」を放つ。「クナン」は周囲の菱形12マスの範囲内で最も近くにいる敵を探し出し、ルートを定めて向かい、自爆して十字5マスに<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2002283 = "ゼタが「クナン」を放つ。「クナン」は周囲の菱形24マスの範囲内で最も近くにいる敵を探し出し、ルートを定めて向かい、自爆して十字方向5マスに<color=#00F6FF>160%</color>のダメージを与える。\nゼタが3段階目の連鎖技を放つとき、能動技【華麗なる秘技】によって召喚された「クナン」のダメージ範囲が周囲1マスに拡大される",
  str_skill_name_3002281 = "ミックス爆撃",
  str_skill_name_3052281 = "ミックス爆撃",
  str_skill_name_3102281 = "ミックス爆撃",
  str_skill_name_3152281 = "ミックス爆撃",
  str_skill_desc_3002281 = "マスを3つ選択し、色をリセットして浄化する。リセット時に水属性のマスを残す",
  str_skill_desc_3052281 = "マスを4つ選択し、色をリセットして浄化する。リセット時に水属性のマスを残す",
  str_skill_desc_3102281 = "マスを3つ選択し、マスの色を<link=\"30100\"><#FFAE07><u>パレット</u></color></link>に入れた後、その色をリセットして浄化する。リセット時に水属性のマスを残す",
  str_skill_desc_3152281 = "マスを4つ選択し、マスの色を<link=\"30100\"><#FFAE07><u>パレット</u></color></link>に入れた後、その色をリセットして浄化する。リセット時に水属性のマスを残す",
  str_skill_name_3002282 = "華麗なる秘技",
  str_skill_desc_3002282 = "色を全て埋めた<link=\"30100\"><#FFAE07><u>パレット</u></color></link>を消費し、進入可能なマスを1つ選んで「クナン」を置く。そのターンでゼタが最初に連鎖技を放つとき、「クナン」もシンクロして索敵し、攻撃を仕掛ける",
  str_skill_passive_name_410228 = "カラフル爆破",
  str_skill_passive_name_420228 = "カラフル爆破",
  str_skill_passive_name_430228 = "カラフル爆破",
  str_skill_passive_desc_410228 = "ゼタが能動技【華麗なる秘技】と<link=\"30100\"><#FFAE07><u>パレット</u></color></link>を獲得する。華麗なる秘技で召喚した「クナン」は、ゼタが連鎖技を放つときに<color=#00F6FF>自分の周囲の敵を探して攻撃する</color>。索敵範囲は連鎖技と<color=#00F6FF>同じ</color>で、与ダメージは連鎖技ダメージの<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_420228 = "ゼタが能動技【華麗なる秘技】と<link=\"30100\"><#FFAE07><u>パレット</u></color></link>を獲得する。華麗なる秘技で召喚した「クナン」は、ゼタが連鎖技を放つときに<color=#00F6FF>自分の周囲の敵を探して攻撃する</color>。索敵範囲は連鎖技と<color=#00F6FF>同じ</color>で、与ダメージは連鎖技ダメージの<color=#00F6FF>{1}</color>\nゼタが3段階目の連鎖技を放つとき、能動技【華麗なる秘技】によって召喚された「クナン」のダメージ範囲が<color=#00F6FF>周囲1マス</color>に拡大される",
  str_skill_passive_desc_430228 = "ゼタが能動技【華麗なる秘技】と<link=\"30100\"><#FFAE07><u>パレット</u></color></link>を獲得する。華麗なる秘技で召喚した「クナン」は、ゼタが連鎖技を放つときに<color=#00F6FF>自分の周囲の敵を探して攻撃する</color>。索敵範囲は連鎖技と<color=#00F6FF>同じ</color>で、与ダメージは連鎖技ダメージの<color=#00F6FF>{1}</color>\nゼタが3段階目の連鎖技を放つとき、能動技【華麗なる秘技】によって召喚された「クナン」のダメージ範囲が<color=#00F6FF>周囲1マス</color>に拡大される。パレットが全て埋まるたびに、チームがゼタの最大HPの<color=#00F6FF>12%</color>相当のHPを回復する",
  str_skill_name_2002291 = "「出口よ出ろ！」",
  str_skill_name_2002292 = "「出口よ出ろ！」",
  str_skill_name_2002293 = "「出口よ出ろ！」",
  str_skill_name_3002291 = "「全消し！」",
  str_skill_name_3202291 = "「全消し！」",
  str_skill_name_3302291 = "「全消し！」",
  str_skill_name_3232291 = "「全消し！」",
  str_skill_name_3262291 = "「全消し！」",
  str_skill_name_3332291 = "「全消し！」",
  str_skill_name_3362291 = "「全消し！」",
  str_skill_passive_name_4002291 = "「充電持って！」",
  str_skill_desc_2002291 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002292 = "最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002293 = "最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2202291 = "最も近くにいる敵2体に<color=#00F6FF>{1}%</color>のダメージを与え、さらに火傷状態を1スタック付与する",
  str_skill_desc_2202292 = "最も近くにいる敵3体に<color=#00F6FF>{1}%</color>のダメージを与え、さらに火傷状態を1スタック付与する",
  str_skill_desc_2202293 = "最も近くにいる敵4体に<color=#00F6FF>{1}%</color>のダメージを与え、さらに火傷状態を1スタック付与する",
  str_skill_desc_3002291 = "戦闘開始時にバティアが<link=\"30110\"><#FFAE07><u>【フォールブロック】</u></color></link>を発動する。1マス選択し、【フォールブロック】の形状と同じマスを火属性に変える",
  str_skill_desc_3202291 = "戦闘開始時にバティアが<link=\"30111\"><#FFAE07><u>【フォールブロック】</u></color></link>を発動する。1マス選択し、【フォールブロック】の形状と同じマスを火属性に変える。エネルギーを<color=#00F6FF>5</color>消費して、【フォールブロック】でブロックの形状をシャッフルでき、火属性のマスを通過するとエネルギーを<color=#00F6FF>1</color>チャージできる。次に能動技を発動するまで、シャッフルするごとに消費エネルギーが<color=#00F6FF>5</color>ずつ増える",
  str_skill_desc_3232291 = "戦闘開始時にバティアが<link=\"30112\"><#FFAE07><u>【フォールブロック】</u></color></link>を発動する。1マス選択し、【フォールブロック】の形状と同じマスを火属性に変える。エネルギーを<color=#00F6FF>5</color>消費して、【フォールブロック】の形状をシャッフルできる。初期エネルギーは<color=#00F6FF>10</color>で、火属性のマスを通過するとエネルギーを<color=#00F6FF>1</color>チャージできる。次に能動技を発動するまで、シャッフルするごとに消費エネルギーが<color=#00F6FF>5</color>ずつ増える",
  str_skill_desc_3262291 = "戦闘開始時にバティアが<link=\"30113\"><#FFAE07><u>【フォールブロック】</u></color></link>を発動する。1マス選択し、【フォールブロック】の形状と同じマスを火属性に変える。エネルギーを<color=#00F6FF>5</color>消費して、【フォールブロック】の形状をシャッフルできる。初期エネルギーは<color=#00F6FF>10</color>で、火属性のマスを通過するとエネルギーを<color=#00F6FF>1</color>チャージできる",
  str_skill_desc_3302291 = "戦闘開始時にバティアが<link=\"30114\"><#FFAE07><u>【フォールブロック】</u></color></link>を発動する。1マス選択し、【フォールブロック】の形状と同じマスを火属性に変える。エネルギーを<color=#00F6FF>5</color>消費して、【フォールブロック】の形状をシャッフルできる。火属性のマスを通過するとエネルギーを<color=#00F6FF>1</color>チャージできる。次に能動技を発動するまで、シャッフルするごとに消費エネルギーが<color=#00F6FF>5</color>ずつ増える。【フォールブロック】の形状をロックできる。ロックした後はブロックの形状がシャッフルしなくなる。ロック状態でシャッフル機能を使用すると、現在のブロックを強化できる。強化するたびに、能動技を発動したとき、追加でその中のランダムな1カ所に濃色マスを生成する",
  str_skill_desc_3332291 = "戦闘開始時にバティアが<link=\"30115\"><#FFAE07><u>【フォールブロック】</u></color></link>を発動する。1マス選択し、【フォールブロック】の形状と同じマスを火属性に変える。エネルギーを<color=#00F6FF>5</color>消費して、【フォールブロック】の形状をシャッフルできる。初期エネルギーは<color=#00F6FF>10</color>で、火属性のマスを通過するとエネルギーを<color=#00F6FF>1</color>チャージできる。次に能動技を発動するまで、シャッフルするごとに消費エネルギーが<color=#00F6FF>5</color>ずつ増える。【フォールブロック】の形状をロックできる。ロックした後はブロックの形状がシャッフルしなくなる。ロック状態でシャッフル機能を使用すると、現在のブロックを強化できる。強化するたびに、能動技を発動したとき、追加でその中のランダムな1カ所に濃色マスを生成する",
  str_skill_desc_3362291 = "戦闘開始時にバティアが<link=\"30116\"><#FFAE07><u>【フォールブロック】</u></color></link>を発動する。1マス選択し、【フォールブロック】と同じ形状のマスを火属性に変える。また、エネルギーを<color=#00F6FF>5</color>消費して【フォールブロック】の形状をシャッフルできる。初期エネルギーは<color=#00F6FF>10</color>で、火属性のマスを通過するごとにエネルギーを<color=#00F6FF>1</color>チャージできる。【フォールブロック】の形状をロックでき、ロックした後はブロックの形状がシャッフルしなくなる。ロック状態でシャッフル機能を使用すると、現在のブロックを強化できる。強化するたびに、能動技を発動したとき、追加でその中のランダムな1カ所に濃色マスを生成する",
  str_skill_passive_desc_4002291 = "チーム内の光霊がターゲットに対して付与した火傷状態が<color=#00F6FF>蓄熱状態</color>に変わり、1スタックごとにターゲットに対してチームの平均攻撃力の<color=#00F6FF>{1}</color>のダメージを与える。ターゲットのHPが高いほどダメージが大きくなり、最大で2倍。最大5スタックまで累積可。2ターン持続。<link=\"30093\"><#FFAE07><u>濃色マス</u></color></link>を通過するたびに、最も近くにいるターゲットに対して蓄熱状態を<color=#00F6FF>1</color>スタック付与する",
  str_skill_upgrade_desc_16022913 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる。【フォールブロック】は初期エネルギーを10保有（覚醒2で有効）",
  str_skill_upgrade_desc_16022916 = "能動技強化：【フォールブロック】の形状のシャッフルに必要なエネルギー消費が増加しなくなる（覚醒2で開放）",
  str_skill_name_28002414 = "プレッシャー",
  str_skill_desc_28002414 = "ノラが強大な術を使い、光霊をノックバックする",
  str_skill_name_28002415 = "召喚",
  str_skill_desc_28002415 = "ノラがフィールドのランダムな位置に暗鬼を召喚する",
  str_skill_name_1003003 = "ロック",
  str_skill_desc_1003003 = "毎ターン、シャドウボールが最も近くのランダムな1マスをロックマスに変える",
  str_skill_name_29102421 = "燃焼",
  str_skill_desc_29102421 = "自身の前方4列の範囲内にいる光霊に対してダメージを与え、ランダムな位置に火炎を生成する",
  str_skill_name_29102422 = "烈火の大地",
  str_skill_desc_29102422 = "火炎を放って全範囲にダメージを与え、さらに戦場の端から3行の範囲内のターゲットに比較的大きな追加ダメージを1回与える",
  str_skill_name_15017611 = "アウストラリスの翅嵐",
  str_skill_desc_15017611 = "自身のアウストラリスの翅針の印のスタック数に応じて周囲3マス以内にいる光霊に対して複数回のダメージを与える。各ダメージごとにターゲットにアウストラリスの翅針を1スタック付与する。ターゲットを攻撃できない場合、自身にアウストラリスの翅針の印を3スタック追加する",
  str_skill_name_15017612 = "ボレアリスの閃撃",
  str_skill_desc_15017612 = "周囲2マスの範囲内にいる敵からアウストラリスの翅針を抜き、翅針1スタックにつきターゲットに20%のダメージを与える。ターゲットを攻撃できない場合、自身にアウストラリスの翅針の印を3スタック追加する",
  str_skill_name_15020011 = "援護爆撃",
  str_skill_desc_15020011 = "周囲3マス以内にいる敵にダメージを与える",
  str_skill_name_15020012 = "攪乱投射",
  str_skill_desc_15020012 = "光霊と啓光兵士を両者の中心に向かって近づけさせる",
  str_skill_name_547100101 = "レインハト通常攻撃",
  str_skill_desc_547100101 = "レインハトが敵に近づいて攻撃する",
  str_skill_name_547100102 = "啓明の轟撃",
  str_skill_desc_547100102 = "レインハトが敵に対して大ダメージを与える",
  str_skill_name_290980101 = "邪念穿威",
  str_skill_name_290980102 = "落魂の審判",
  str_skill_name_290980103 = "潮鳴の電撃",
  str_skill_name_290980104 = "エナジードラゴンブレス",
  str_skill_desc_290980101 = "X字の範囲内に敵が存在する場合、その敵にダメージを与え、末端ユニットを召喚する。範囲内に敵が存在しない場合、自身の周囲に末端ユニットを召喚する",
  str_skill_desc_290980102 = "十字の範囲内に敵が存在する場合、その敵にダメージを与え、末端ユニットを召喚する。範囲内に敵が存在しない場合、自身の周囲に末端ユニットを召喚する",
  str_skill_desc_290980103 = "自身の周囲に末端ユニットを召喚する",
  str_skill_desc_290980104 = "全範囲にダメージを与えて敵をノックバックし、その周囲に末端ユニットを召喚する",
  str_skill_name_200510101 = "挑発の電光",
  str_skill_desc_200510101 = "挑発の末端が敵に近づいて攻撃する",
  str_skill_name_290520111 = "末極・猛禽の襲撃",
  str_skill_desc_290520111 = "フィジェロが光霊に向かって移動し、大ダメージを与える。その後ターゲットから離れた位置に移動する",
  str_skill_name_290520112 = "末極・猛禽の攻撃",
  str_skill_desc_290520112 = "フィジェロが移動後、範囲内の光霊にダメージを与える",
  str_skill_name_290940113 = "末極・怪火の槍",
  str_skill_desc_290940113 = "アイラが光霊の現在のHPの40%のダメージを与える。このダメージにもとづいてチームの最大HPを上昇させ、光霊の十字方向の最大範囲内で、フィールドの最も外側に怪火を生成する",
  str_skill_name_290940114 = "末極・灼熱爆破",
  str_skill_desc_290940114 = "アイラが自身の周囲2マス以内にいる光霊にダメージを与える",
  str_skill_name_290940115 = "末極・激憤隕石",
  str_skill_desc_290940115 = "アイラが前のターンに光霊がいた位置に隕石を降らせ、致死ダメージを与える。範囲内の中心マスを破壊すると同時に、十字方向4マスに損傷マスを生成する",
  str_skill_upgrade_refine_desc_17010711 = "能動技強化：強化状態のとき連鎖技のダメージ+<color=#00F6FF>25%</color>",
  str_skill_upgrade_refine_desc_17010712 = "装備技強化：毎ターン開始時、<color=#00F6FF>周囲1マス</color>にいる敵1体につき、フォースを1獲得する",
  str_skill_upgrade_refine_desc_17010713 = "装備技強化：<color=#00F6FF>ターン終了時</color>にフォースを5獲得できる（HP損失<color=#00F6FF>15%</color>ごとに、追加で1獲得）",
  str_skill_desc_346107 = "このターンはフォースを<color=#00F6FF>10</color>消費して強化状態になる。通常攻撃で斜め方向に攻撃でき、さらに通常攻撃/連鎖ダメージそれぞれ+<color=#00F6FF>20%/25%</color>（繰り返して発動すると重ね掛け可能）。強化状態で敵を1体倒すたびに、フォースを2獲得する",
  str_skill_passive_desc_456107 = "戦闘開始時にフォースを10獲得する。各ターン開始時、<color=#00F6FF>周囲1マス</color>にいる敵1体につき、フォースを<color=#00F6FF>1</color>獲得する。ターン終了時に強化状態でなければ、フォースを<color=#00F6FF>5</color>獲得できる（さらにHP損失20%ごとに追加でフォースを1獲得）",
  str_skill_passive_desc_466107 = "戦闘開始時にフォースを10獲得する。各ターン開始時、<color=#00F6FF>周囲1マス</color>にいる敵1体につき、フォースを<color=#00F6FF>1</color>獲得する。ターン終了時にフォースを<color=#00F6FF>5</color>獲得できる（さらにHP損失15%ごとに追加でフォースを1獲得）",
  str_skill_upgrade_refine_desc_17010811 = "<color=#00F6FF>能動技変異Ⅰを追加</color>：フォースを<color=#00F6FF>15</color>消費し、選択した1マスに<color=#00F6FF>480%</color>のダメージを与える。1回発動するごとに、基礎攻撃力+<color=#00F6FF>3%</color>。1ターンに複数回発動できる",
  str_skill_upgrade_refine_desc_17010812 = "能動技強化：1回発動するごとに、能動技の最終ダメージ+<color=#00F6FF>3%</color>",
  str_skill_upgrade_refine_desc_17010813 = "能動技強化：HPが<color=#00F6FF>10%</color>未満のターゲットに対して<color=#00F6FF>3倍</color>のダメージを与える",
  str_skill_name_366108 = "天岩の墜",
  str_skill_name_33610801 = "天岩の墜・変異Ⅰ",
  str_skill_name_36610801 = "天岩の墜・変異Ⅰ",
  str_skill_desc_33610801 = "フォースを<color=#00F6FF>15</color>消費し、選択した1マスに<color=#00F6FF>480%</color>のダメージを与える。1回発動するごとに、基礎攻撃力+<color=#00F6FF>3%</color>。1ターンに複数回発動できる",
  str_skill_desc_356108 = "フォースを<color=#00F6FF>10</color>消費して、任意の1マスを選び<color=#00F6FF>240%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に半分の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。1回発動するごとに基礎攻撃力+<color=#00F6FF>3%</color>、能動技の最終ダメージ+<color=#00F6FF>3%</color>。1ターン内に複数回発動できる",
  str_skill_desc_35610801 = "フォースを<color=#00F6FF>15</color>消費し、選択した1マスに<color=#00F6FF>480%</color>のダメージを与える。1回発動するごとに、基礎攻撃力+<color=#00F6FF>3%</color>、能動技の最終ダメージ+<color=#00F6FF>3%</color>。1ターンに複数回発動できる",
  str_skill_desc_366108 = "フォースを<color=#00F6FF>10</color>消費して、任意の1マスを選び<color=#00F6FF>240%</color>のダメージを与え、その周囲の<color=#00F6FF>十字方向4マス</color>に半分の<link=\"30015\"><#FFAE07><u>飛散</u></color></link>ダメージを与える。1回発動するごとに基礎攻撃力+<color=#00F6FF>3%</color>、能動技の最終ダメージ+<color=#00F6FF>3%</color>。1ターン内に複数回発動できる。HPが<color=#00F6FF>10%</color>未満のターゲットに対して<color=#00F6FF>3倍</color>のダメージを与える",
  str_skill_desc_36610801 = "フォースを<color=#00F6FF>15</color>消費し、選択した1マスに<color=#00F6FF>480%</color>のダメージを与える。1回発動するごとに、基礎攻撃力+<color=#00F6FF>3%</color>、能動技の最終ダメージ+<color=#00F6FF>3%</color>。1ターンに複数回発動できる。HPが<color=#00F6FF>10%</color>未満のターゲットに対して<color=#00F6FF>3倍</color>のダメージを与える",
  str_skill_upgrade_refine_desc_17010911 = "能動技強化：能動技が<color=#00F6FF>全範囲内の任意の1マス</color>に変わり、さらに<color=#00F6FF>背後のターゲット</color>を攻撃できる",
  str_skill_upgrade_refine_desc_17010912 = "装備技強化：各ターン<color=#00F6FF>最初の2回</color>の通常攻撃でフォースを<color=#00F6FF>1</color>獲得でき、その通常攻撃のダメージ+<color=#00F6FF>100%</color>",
  str_skill_upgrade_refine_desc_17010913 = "能動技追加：フォースを<color=#00F6FF>10</color>消費し、このターン内の連鎖技のターゲット<color=#00F6FF>+1</color>（繰り返して発動すると重ね掛け可能）",
  str_skill_name_340109 = "月夜の狩り",
  str_skill_desc_340109 = "フォースを<color=#00F6FF>10</color>消費して残りのフォースをクリアする。1マス選択し、選択したマスへの前後方向のルート上および隣接するマスにいる敵に<color=#00F6FF><color=#00F6FF>150%</color></color>のダメージを与える。クリアされたフォース1につき最終ダメージ+<color=#00F6FF>8%</color>",
  str_skill_passive_desc_453109 = "毎ターン開始時にフォースを<color=#00F6FF>5</color>獲得する。各ターン<color=#00F6FF>最初の2回</color>の通常攻撃でフォースを<color=#00F6FF>1</color>獲得し、その通常攻撃のダメージ+<color=#00F6FF>100%</color>",
  str_skill_name_360109 = "林の影狩り",
  str_skill_desc_360109 = "フォースを<color=#00F6FF>10</color>消費し、このターン内の連鎖技のターゲット<color=#00F6FF>+1</color>（繰り返して発動すると重ね掛け可能）",
  str_skill_upgrade_refine_desc_17011011 = "装備技強化：通常攻撃をするとき、<color=#00F6FF>35%</color>の確率で自身から最も遠い敵に対して雷を1回落とす",
  str_skill_upgrade_refine_desc_17011012 = "装備技強化：雷を落とす時にフォースが5未満だと、フォースを1獲得する",
  str_skill_upgrade_refine_desc_17011013 = "能動技強化：雷を落とすたびに、鎮魂の印を1スタック獲得する。能動技を発動すると鎮魂の印をすべてクリアし、1スタッククリアするごとに能動技のダメージ係数+10%",
  str_skill_passive_desc_443110 = "毎ターン開始時にフォースを<color=#00F6FF>5</color>獲得し、能動技で敵を1体倒すたびにフォースを<color=#00F6FF>2</color>獲得する。通常攻撃は<color=#00F6FF>35%</color>の確率で自身から最も遠くにいる敵に雷撃を1回放つ",
  str_skill_passive_desc_453110 = "毎ターン開始時にフォースを<color=#00F6FF>5</color>獲得し、能動技で敵を1体倒すたびにフォースを<color=#00F6FF>2</color>獲得する。通常攻撃は<color=#00F6FF>35%</color>の確率で自身から最も遠くにいる敵に雷撃を1回放つ。雷を落とす時にフォースが5未満だと、フォースを1獲得する",
  str_skill_desc_366110 = "フォースを<color=#00F6FF>10</color>消費して残りのフォースと<link=\"30117\"><#FFAE07><u>鎮魂の印</u></color></link>をクリアし、敵全体に<color=#00F6FF>150%</color>のダメージを与える。クリアされたフォース1につきダメージ+<color=#00F6FF>15%</color>。さらにターゲットの防御力を<color=#00F6FF>1%</color>無視する。鎮魂の印を1スタッククリアするごとに、能動技のダメージ係数+<color=#00F6FF>10%</color>",
  str_skill_upgrade_desc_16023013 = "装備技強化：理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える",
  str_skill_upgrade_desc_16023014 = "能動技、装備技強化：ダメージを与えるとき、チームのHP損失に<color=#00F6FF>4000</color>を追加で計上する",
  str_skill_upgrade_desc_16023015 = "装備技強化：真主の契約を保有する敵に対してビクトリア・墓歌の与えるすべてのダメージがチームHPの低下に反比例して増加し、チームHPが50%になったときに最大値<color=#00F6FF>15%</color>に達する",
  str_skill_name_2002301 = "深紅の牢獄",
