  str_skill_passive_name_4362301 = "全知の赦し",
  str_skill_desc_2002301 = "最も近くにいる敵3体に対して<color=#00F6FF>{1}%</color>のダメージを与え、真主の契約を保有する敵に<color=#00F6FF>同倍率</color>のダメージを1回与える",
  str_skill_desc_2002302 = "最も近くにいる敵3体に対して<color=#00F6FF>{1}%</color>のダメージを与え、真主の契約を保有する敵に<color=#00F6FF>同倍率</color>のダメージを1回与える",
  str_skill_desc_2002303 = "最も近くにいる敵3体に対して<color=#00F6FF>{1}%</color>のダメージを与え、真主の契約を保有する敵に<color=#00F6FF>同倍率</color>のダメージを1回与える",
  str_skill_desc_3002301 = "戦闘開始時、ビクトリア・墓歌が<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を10消費してターゲットを1体選択し、その相手に<link=\"30118\"><#FFAE07><u>真主の契約</u></color></link>を付与するとともに、チームのHP損失の<color=#00F6FF>200%</color>の防御力無視ダメージを与える",
  str_skill_desc_3042301 = "戦闘開始時、ビクトリア・墓歌が<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を10消費してターゲットを1体選択し、その相手に<link=\"30118\"><#FFAE07><u>真主の契約</u></color></link>を付与するとともに、チームのHP損失の<color=#00F6FF>200%</color>の防御力無視ダメージを与える。ダメージを与えるとき、チームのHP損失に4000を追加で計上する",
  str_skill_desc_3002302 = "チームHPと理性値の現在の比率を入れ替える。理性値が0になると発動できなくなる。戦闘開始時に発動チャンスを1回獲得する",
  str_skill_passive_desc_4102301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>{1}</color>相当の防御力無視ダメージを1回与える",
  str_skill_passive_desc_4302301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>{1}</color>相当の防御力無視ダメージを1回与える。ビクトリア・墓歌が真主の契約を保有する敵にダメージを与えるとき、失った理性値を<color=#00F6FF>3%</color>回復する（少なくとも1回復）",
  str_skill_passive_desc_4132301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>{1}</color>相当の防御力無視ダメージを1回与える。理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える",
  str_skill_passive_desc_4332301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>{1}</color>相当の防御力無視ダメージを1回与える。ビクトリア・墓歌が真主の契約を保有する敵にダメージを与えるとき、失った理性値を<color=#00F6FF>3%</color>回復する（少なくとも1回復）。理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える",
  str_skill_passive_desc_4142301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>{1}</color>相当の防御力無視ダメージを1回与える。ダメージを与えるとき、チームのHP損失に<color=#00F6FF>4000</color>を追加で計上する。理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える",
  str_skill_passive_desc_4342301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>{1}</color>相当の防御力無視ダメージを1回与える。ビクトリア・墓歌が真主の契約を保有する敵にダメージを与えるとき、失った理性値を<color=#00F6FF>3%</color>回復する（少なくとも1回復）。理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える",
  str_skill_passive_desc_4162301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>{1}</color>相当の防御力無視ダメージを1回与える。ダメージを与えるとき、チームのHP損失に<color=#00F6FF>4000</color>を追加で計上する。理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える。真主の契約を保有する敵に対してビクトリア・墓歌の与えるすべてのダメージがチームHPの低下に反比例して増加し、チームHPが50%になったときに最大値<color=#00F6FF>15%</color>に達する",
  str_skill_passive_desc_4362301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>{1}</color>相当の防御力無視ダメージを1回与える。ビクトリア・墓歌が真主の契約を保有する敵にダメージを与えるとき、失った理性値を<color=#00F6FF>3%</color>回復する（少なくとも1回復）。理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える。真主の契約を保有する敵に対してビクトリア・墓歌の与えるすべてのダメージがチームHPの低下に反比例して増加し、チームHPが50%になったときに最大値<color=#00F6FF>15%</color>に達する",
  str_skill_upgrade_refine_desc_16023011 = "装備技強化：ダメージ係数が<color=#00F6FF>35%</color>に上昇する",
  str_skill_upgrade_refine_desc_16023012 = "連鎖技強化：真主の契約を保有する敵に対する与ダメージが<color=#00F6FF>1.1倍</color>に上昇する",
  str_skill_upgrade_refine_desc_16023013 = "能動技強化：発動回数<color=#00F6FF>+1</color>",
