  str_skill_passive_desc_4432301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>35%</color>相当の防御力無視ダメージを1回与える。ビクトリア・墓歌が真主の契約を保有する敵にダメージを与えるとき、失った理性値を<color=#00F6FF>3%</color>回復する（少なくとも1回復）。理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える",
  str_skill_passive_desc_4442301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>35%</color>相当の防御力無視ダメージを1回与える。ビクトリア・墓歌が真主の契約を保有する敵にダメージを与えるとき、失った理性値を<color=#00F6FF>3%</color>回復する（少なくとも1回復）。理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える",
  str_skill_passive_desc_4462301 = "毎ターン開始時、または濃色マスを通過するたびに、真主の契約を保有する敵に対して、チームのHP損失の<color=#00F6FF>35%</color>相当の防御力無視ダメージを1回与える。ビクトリア・墓歌が真主の契約を保有する敵にダメージを与えるとき、失った理性値を<color=#00F6FF>3%</color>回復する（少なくとも1回復）。理性値が50以上から50未満、あるいは50未満から50以上に変化するたびに、チームから最も近くにある火属性以外のマスを<color=#00F6FF>火属性の濃色マス</color>に変える。真主の契約を保有する敵に対してビクトリア・墓歌の与えるすべてのダメージがチームHPの低下に反比例して増加し、チームHPが50%になったときに最大値<color=#00F6FF>15%</color>に達する",
  str_skill_desc_2502301 = "最も近くにいる敵3体に対して<color=#00F6FF>135%</color>のダメージを与え、真主の契約を保有する敵に<color=#00F6FF>1.1倍</color>のダメージを1回与える",
  str_skill_desc_2502302 = "最も近くにいる敵3体に対して<color=#00F6FF>150%</color>のダメージを与え、真主の契約を保有する敵に<color=#00F6FF>1.1倍</color>のダメージを1回与える",
  str_skill_desc_2502303 = "最も近くにいる敵3体に対して<color=#00F6FF>165%</color>のダメージを与え、真主の契約を保有する敵に<color=#00F6FF>1.1倍</color>のダメージを1回与える",
  str_skill_desc_3602302 = "チームHPと理性値の現在の比率を入れ替える。理性値が0になると発動できなくなる。戦闘開始時に発動チャンスを2回獲得する",
