  str_skill_name_3232311 = "堕淵",
  str_skill_name_3302312 = "キスマーク",
  str_skill_desc_2002311 = "自分の<color=#00F6FF>周囲2マス</color>以内にいる敵に<color=#00F6FF>130%</color>のダメージを3回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2002312 = "自分の<color=#00F6FF>周囲2マス</color>以内にいる敵に<color=#00F6FF>140%</color>のダメージを4回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_2002313 = "自分の<color=#00F6FF>周囲3マス</color>以内にいる敵に<color=#00F6FF>150%</color>のダメージを5回ランダムに割り当てて与える。同一ターゲットにダメージを複数回与える場合、2回目からは毎回ダメージが半減する",
  str_skill_desc_3002311 = "戦闘開始時、ヴィルヘルムが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。1マス選択し、<color=#00F6FF>周囲2マス</color>の範囲内でさらに1マス選択して長方形のエリアを確定する。選択したマスが水属性の濃色マスに変わり、長方形内のマス1つにつき理性値を<color=#00F6FF>2</color>消費する",
  str_skill_desc_3032311 = "戦闘開始時、ヴィルヘルムが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。1マス選択し、<color=#00F6FF>周囲3マス</color>の範囲内でさらに1マス選択して長方形のエリアを確定する。選択したマスが水属性の濃色マスに変わり、長方形内のマス1つにつき理性値を<color=#00F6FF>2</color>消費する",
  str_skill_desc_3202311 = "戦闘開始時、ヴィルヘルムが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。1マス選択し、<color=#00F6FF>周囲2マス</color>の範囲内でさらに1マス選択して長方形のエリアを確定する。選択したマスが水属性の濃色マスに変わり、長方形内のマス1つにつき理性値を<color=#00F6FF>2</color>消費する。このエリア内にいるすべての敵に対して血暈状態を<color=#00F6FF>1</color>スタック付与する。発動後の理性値が<color=#00F6FF>50</color>未満の場合、さらに1スタック付与する",
  str_skill_desc_3232311 = "戦闘開始時、ヴィルヘルムが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。1マス選択し、<color=#00F6FF>周囲3マス</color>の範囲内でさらに1マス選択して長方形のエリアを確定する。選択したマスが水属性の濃色マスに変わり、長方形内のマス1つにつき理性値を<color=#00F6FF>2</color>消費する。このエリア内にいるすべての敵に対して血暈状態を<color=#00F6FF>1</color>スタック付与する。発動後の理性値が<color=#00F6FF>50</color>未満の場合、さらに1スタック付与する",
  str_skill_desc_3302312 = "理性値を20回復する。発動後、最大理性値-20。最大理性値が0でない場合、連続で発動できる",
  str_skill_passive_name_4002311 = "夜葬",
  str_skill_passive_name_4062311 = "夜葬",
  str_skill_passive_desc_4002311 = "チーム内の光霊がターゲットに対して付与した恐怖状態が<color=#00F6FF>血暈状態</color>に変わり、1スタックにつきターゲットの防御力-<color=#00F6FF>{1}</color>、最大3スタックまで累積可。2ターン持続。スタック数が消失（ターゲットの撃破を含む）または上限を超えて付与しようとするとき、1スタックにつき理性値を1回復する。ヴィルヘルムの連鎖技がダメージを与えるごとに、ターゲットに<color=#00F6FF>血暈状態</color>を1スタック付与する",
  str_skill_passive_desc_4062311 = "チーム内の光霊がターゲットに対して付与した恐怖状態が<color=#00F6FF>血暈状態</color>に変わり、1スタックにつきターゲットの防御力-<color=#00F6FF>{1}</color>、最大3スタックまで累積可。2ターン持続。スタック数が消失（ターゲットの撃破を含む）または上限を超えて付与しようとするとき、1スタックにつき理性値を2回復する。ヴィルヘルムの連鎖技がダメージを与えるごとに、ターゲットに<color=#00F6FF>血暈状態</color>を1スタック付与する",
  str_skill_upgrade_desc_16023113 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる。2ステップ目のマス選択範囲が周囲3マスに拡大される",
  str_skill_upgrade_desc_16023116 = "装備技強化：血暈状態が消失または上限を超えて付与しようとするとき、1スタックにつき理性値を2回復する",
  str_skill_name_2002321 = "聖血の洗礼",
  str_skill_name_2002322 = "聖血の洗礼",
  str_skill_name_2002323 = "聖血の洗礼",
  str_skill_name_3002321 = "救世の血",
  str_skill_name_3202322 = "救世の血・変異",
  str_skill_name_3022321 = "救世の血",
