  str_skill_name_3322321 = "救世の血",
  str_skill_name_3322322 = "救世の血・変異",
  str_skill_passive_name_4002321 = "赦しの酒",
  str_skill_passive_name_4052321 = "赦しの酒",
  str_skill_desc_2002321 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_2002322 = "<color=#00F6FF>縦、横、斜め16マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_2002323 = "<color=#00F6FF>周囲2マス以内</color>に<color=#00F6FF>{1}%</color>のダメージを与え、<link=\"10000\"><#FFAE07><u>出血</u></color></link>状態を1スタック付与する。2ターン持続",
  str_skill_desc_3002321 = "チームの最大HPの<color=#00F6FF>10%</color>を消費し、選択した<color=#00F6FF>1</color>マスを濃色マスに変える。HPが足りない場合は発動できない",
  str_skill_desc_3202322 = "<color=#FFFF00>発動後、技のCDターン+1</color>。チームの最大HPの<color=#00F6FF>25%</color>を消費し、選択した<color=#00F6FF>2</color>マスを濃色マスに変える。HPが足りない場合は発動できない",
  str_skill_desc_3022321 = "チームの最大HPの<color=#00F6FF>10%</color>を消費し、選択した<color=#00F6FF>1</color>マスを濃色マスに変える。HPが足りない場合は発動できない",
  str_skill_desc_3222322 = "<color=#FFFF00>発動後、技のCDターン+1</color>。チームの最大HPの<color=#00F6FF>25%</color>を消費し、選択した<color=#00F6FF>2</color>マスを濃色マスに変える。HPが足りない場合は発動できない",
  str_skill_desc_3302321 = "チームの最大HPの<color=#00F6FF>10%</color>を消費し、選択した<color=#00F6FF>1</color>マスを濃色マスに変える。HPが足りない場合は発動できない。発動後のチームHPが<color=#00F6FF>30%</color>未満の場合、最初に選択したマスが火属性の濃色マスに変わる",
  str_skill_desc_3302322 = "<color=#FFFF00>発動後、技のCDターン+1</color>。チームの最大HPの<color=#00F6FF>25%</color>を消費し、選択した<color=#00F6FF>2</color>マスを濃色マスに変える。HPが足りない場合は発動できない。発動後のチームHPが<color=#00F6FF>30%</color>未満の場合、最初に選択したマスが火属性の濃色マスに変わる",
  str_skill_desc_3322321 = "チームの最大HPの<color=#00F6FF>10%</color>を消費し、選択した<color=#00F6FF>1</color>マスを濃色マスに変える。HPが足りない場合は発動できない。発動後のチームHPが<color=#00F6FF>30%</color>未満の場合、最初に選択したマスが火属性の濃色マスに変わる",
  str_skill_desc_3322322 = "<color=#FFFF00>発動後、技のCDターン+1</color>。チームの最大HPの<color=#00F6FF>25%</color>を消費し、選択した<color=#00F6FF>2</color>マスを濃色マスに変える。HPが足りない場合は発動できない。発動後のチームHPが<color=#00F6FF>30%</color>未満の場合、最初に選択したマスが火属性の濃色マスに変わる",
  str_skill_passive_desc_4002321 = "現在のHP比率が<color=#00F6FF>50%</color>以下になったとき、最も近くにある火属性の進入可能な1マスに真紅の祝福を1つ生成し、通過時にネイルス・祭礼の攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復する",
  str_skill_passive_desc_4052321 = "現在のHP比率が<color=#00F6FF>50%</color>以下になったとき、最も近くにある火属性の進入可能な1マスに真紅の祝福を1つ生成し、通過時にネイルス・祭礼の攻撃力の<color=#00F6FF>{1}</color>相当のHPを回復する。真紅の祝福を通過したとき、濃色マスを通過したものと見なされる",
  str_skill_passive_desc_4402321 = "現在のHP比率が<color=#00F6FF>50%</color>以下になったとき、最も近くにある火属性の進入可能な1マスに真紅の祝福を1つ生成し、通過時にネイルス・祭礼の攻撃力の<color=#00F6FF>110%</color>相当のHPを回復する",
  str_skill_passive_desc_4452321 = "現在のHP比率が<color=#00F6FF>50%</color>以下になったとき、最も近くにある火属性の進入可能な1マスに真紅の祝福を1つ生成し、通過時にネイルス・祭礼の攻撃力の<color=#00F6FF>110%</color>相当のHPを回復する。真紅の祝福を通過したとき、濃色マスを通過したものと見なされる",
  str_skill_passive_desc_4502321 = "現在のHP比率が<color=#00F6FF>50%</color>以下になったとき、最も近くにある火属性の進入可能な1マスに真紅の祝福を1つ生成し、通過時にネイルス・祭礼の攻撃力の<color=#00F6FF>110%</color>相当のHPおよび失ったHPの<color=#00F6FF>5%</color>を回復する",
  str_skill_passive_desc_4552321 = "現在のHP比率が<color=#00F6FF>50%</color>以下になったとき、最も近くにある火属性の進入可能な1マスに真紅の祝福を1つ生成し、通過時にネイルス・祭礼の攻撃力の<color=#00F6FF>110%</color>相当のHPおよび失ったHPの<color=#00F6FF>5%</color>を回復する。真紅の祝福を通過したとき、濃色マスを通過したものと見なされる",
  str_skill_passive_desc_4602321 = "現在のHP比率が<color=#00F6FF>50%</color>以下、<color=#00F6FF>30%</color>以下になったとき、それぞれ最も近くにある火属性の進入可能な1マスに真紅の祝福を1つ生成し、通過時にネイルス・祭礼の攻撃力の<color=#00F6FF>110%</color>相当のHPおよび失ったHPの<color=#00F6FF>5%</color>を回復する",
  str_skill_passive_desc_4652321 = "現在のHP比率が<color=#00F6FF>50%</color>以下、<color=#00F6FF>30%</color>以下になったとき、それぞれ最も近くにある火属性の進入可能な1マスに真紅の祝福を1つ生成し、通過時にネイルス・祭礼の攻撃力の<color=#00F6FF>110%</color>相当のHPおよび失ったHPの<color=#00F6FF>5%</color>を回復する。真紅の祝福を通過したとき、濃色マスを通過したものと見なされる",
  str_skill_upgrade_desc_15023212 = "能動技強化：技のクールダウンターン<color=#FFFF00>-1</color>。",
  str_skill_upgrade_desc_15023215 = "装備技強化：真紅の祝福を通過したとき、濃色マスを通過したものと見なされる",
  str_skill_upgrade_refine_desc_15023211 = "装備技強化：真紅の祝福通過時にネイルス・祭礼の攻撃力の<color=#00F6FF>110%</color>相当のHPを回復する",
  str_skill_upgrade_refine_desc_15023212 = "装備技強化：真紅の祝福通過時に失ったHPの<color=#00F6FF>5%</color>を追加で回復する",
  str_skill_upgrade_refine_desc_15023213 = "装備技強化：現在のHP比率が<color=#00F6FF>30%</color>以下になったとき、最も近くにある火属性の進入可能な1マスに真紅の祝福を1つ生成する",
  str_skill_name_29101011 = "死徒召喚",
