  str_skill_name_29101012 = "嗜血回復",
  str_skill_desc_29101012 = "前方1マスの範囲内にいる光霊にダメージを与え、HPを回復する。命中できなかった場合、その場で自身のHPを大量に回復する",
  str_skill_name_20052011 = "理性吸収",
