  str_skill_desc_3302331 = "<link=\"30119\"><#FFAE07><u>AP</u></color></link>を20消費し、任意のマスを1つ選び、それを中心とした21マスに<color=#00F6FF>300%</color>のダメージを与える。範囲内のすべての濃色マスを<link=\"30124\"><#FFAE07><u>吸收</u></color></link>し、火属性に変える。吸収前の濃色マスが火属性の場合、追加で濃色マスを1つ吸収したものと見なす",
  str_skill_desc_3332331 = "<link=\"30120\"><#FFAE07><u>AP</u></color></link>を20消費し、任意のマスを1つ選び、それを中心とした21マスに<color=#00F6FF>300%</color>のダメージを与える。範囲内のすべての濃色マスを<link=\"30124\"><#FFAE07><u>吸收</u></color></link>し、火属性に変える。吸収前の濃色マスが火属性の場合、追加で濃色マスを1つ吸収したものと見なす",
  str_skill_desc_3362331 = "<link=\"30121\"><#FFAE07><u>AP</u></color></link>を20消費し、任意のマスを1つ選び、それを中心とした21マスに<color=#00F6FF>300%</color>のダメージを与える。範囲内のすべての濃色マスを<link=\"30124\"><#FFAE07><u>吸收</u></color></link>し、火属性に変える。吸収前の濃色マスが火属性の場合、追加で濃色マスを1つ吸収したものと見なす",
