  str_skill_desc_2002332 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002333 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2032332 = "<color=#00F6FF>菱形12マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える。さらに範囲内のランダムな位置に濃色マスを<color=#00F6FF>1</color>つ生成する",
  str_skill_desc_2032333 = "<color=#00F6FF>周囲2マス</color>の範囲に<color=#00F6FF>{1}%</color>のダメージを与える。さらに範囲内のランダムな位置に濃色マスを<color=#00F6FF>1</color>つ生成する",
