  str_skill_passive_desc_4102331 = " 『ライザのアトリエ２』コラボキャラに戦闘時<link=\"30122\"><#FFAE07><u>【戦術システム】</u></color></link>が適用され、ライザが能動技を発動するたびに戦術値を<color=#00F6FF>{1}</color>獲得する",
  str_skill_passive_desc_4202331 = " 『ライザのアトリエ２』コラボキャラに戦闘時<link=\"30122\"><#FFAE07><u>【戦術システム】</u></color></link>が適用され、ライザが能動技を発動するたびに戦術値を<color=#00F6FF>{1}</color>、濃色マスを通過するたびに戦術値を<color=#00F6FF>3</color>獲得する",
  str_skill_passive_desc_4402331 = " 『ライザのアトリエ２』コラボキャラに戦闘時<link=\"30122\"><#FFAE07><u>【戦術システム】</u></color></link>が適用され、ライザが能動技を発動するたびに戦術値を<color=#00F6FF>20</color>、濃色マスを通過するたびに戦術値を<color=#00F6FF>3</color>獲得する",
  str_skill_passive_desc_4502331 = " 『ライザのアトリエ２』コラボキャラに戦闘時<link=\"30122\"><#FFAE07><u>【戦術システム】</u></color></link>が適用され、ライザが能動技を発動するたびに戦術値を<color=#00F6FF>20</color>、濃色マスを通過するたびに戦術値を<color=#00F6FF>5</color>獲得する",
