  str_skill_desc_2202341 = "最も近くにいる敵2体に対して<color=#00F6FF>{1}%</color>のダメージを与える。実際に命中したターゲットの数が技のターゲットの数を下回る場合、最も近くにいるターゲットの周囲に濃色マスを1つ生成する",
  str_skill_desc_2202342 = "最も近くにいる敵3体に対して<color=#00F6FF>{1}%</color>のダメージを与える。実際に命中したターゲットの数が技のターゲットの数を下回る場合、最も近くにいるターゲットの周囲に濃色マスを1つ生成する",
  str_skill_desc_2202343 = "最も近くにいる敵4体に対して<color=#00F6FF>{1}%</color>のダメージを与える。実際に命中したターゲットの数が技のターゲットの数を下回る場合、最も近くにいるターゲットの周囲に濃色マスを1つ生成する",
  str_skill_desc_2302341 = "最も近くにいる敵2体に対して<color=#00F6FF>{1}%</color>のダメージを与える。1ターン内に濃色マスを通過するたびに連鎖技のターゲット数<color=#00F6FF>+1</color>。実際に命中したターゲットの数が技のターゲットの数を下回る場合、最も近くで命中したターゲットの周囲に濃色マスを1つ生成する",
  str_skill_desc_2302342 = "最も近くにいる敵3体に対して<color=#00F6FF>{1}%</color>のダメージを与える。1ターン内に濃色マスを通過するたびに連鎖技のターゲット数<color=#00F6FF>+1</color>。実際に命中したターゲットの数が技のターゲットの数を下回る場合、最も近くで命中したターゲットの周囲に濃色マスを1つ生成する",
  str_skill_desc_2302343 = "最も近くにいる敵4体に対して<color=#00F6FF>{1}%</color>のダメージを与える。1ターン内に濃色マスを通過するたびに連鎖技のターゲット数<color=#00F6FF>+1</color>。実際に命中したターゲットの数が技のターゲットの数を下回る場合、最も近くで命中したターゲットの周囲に濃色マスを1つ生成する",
  str_skill_desc_2602341 = "最も近くにいる敵2体に対して<color=#00F6FF>165%</color>のダメージを与える。1ターン内に濃色マスを通過するたびに連鎖技のターゲット数<color=#00F6FF>+1</color>。ダメージ係数+<color=#00F6FF>5%</color>。実際に命中したターゲットの数が技のターゲットの数を下回る場合、最も近くで命中したターゲットの周囲に濃色マスを1つ生成する",
  str_skill_desc_2602342 = "最も近くにいる敵3体に対して<color=#00F6FF>170%</color>のダメージを与える。1ターン内に濃色マスを通過するたびに連鎖技のターゲット数<color=#00F6FF>+1</color>。ダメージ係数+<color=#00F6FF>5%</color>。実際に命中したターゲットの数が技のターゲットの数を下回る場合、最も近くで命中したターゲットの周囲に濃色マスを1つ生成する",
  str_skill_desc_2602343 = "最も近くにいる敵4体に対して<color=#00F6FF>175%</color>のダメージを与える。1ターン内に濃色マスを通過するたびに連鎖技のターゲット数<color=#00F6FF>+1</color>。ダメージ係数+<color=#00F6FF>5%</color>。実際に命中したターゲットの数が技のターゲットの数を下回る場合、最も近くで命中したターゲットの周囲に濃色マスを1つ生成する",
