  str_skill_passive_desc_440234 = "『ライザのアトリエ２』コラボキャラに戦闘時<link=\"30122\"><#FFAE07><u>【戦術システム】</u></color></link>が適用され、クラウディアが能動技を発動するたびに戦術値を<color=#00F6FF>20</color>獲得する",
  str_skill_upgrade_refine_desc_16023411 = "装備技強化：クラウディアが能動技を発動するたびに戦術値を<color=#00F6FF>20</color>獲得する",
  str_skill_upgrade_refine_desc_16023412 = "能動技強化：大型暗鬼に対するダメージ増加系の強化効果+<color=#00F6FF>50%</color>",
  str_skill_upgrade_refine_desc_16023413 = "連鎖技強化：1ターン内に濃色マスを通過するたびに連鎖技ダメージ係数+<color=#00F6FF>5%</color>",
  str_skill_desc_240461 = "<color=#00F6FF>周囲4マス</color>以内の敵<color=#00F6FF>3</color>体に<color=#00F6FF>120%</color>のダメージを与え、嘲笑の印を1スタック付与する（最大8スタック）。印1スタックごとに連鎖ダメージ+<color=#00F6FF>7%</color>",
  str_skill_desc_240462 = "<color=#00F6FF>周囲4マス</color>以内の敵<color=#00F6FF>3</color>体に<color=#00F6FF>140%</color>のダメージを与え、嘲笑の印を2スタック付与する（最大8スタック）。印1スタックごとに連鎖ダメージ+<color=#00F6FF>7%</color>",
  str_skill_desc_240463 = "<color=#00F6FF>周囲4マス</color>以内の敵<color=#00F6FF>3</color>体に<color=#00F6FF>155%</color>のダメージを与え、嘲笑の印を3スタック付与する（最大8スタック）。印1スタックごとに連鎖ダメージ+<color=#00F6FF>7%</color>",
  str_skill_upgrade_refine_desc_13004612 = "装備技強化：嘲笑の印1スタックごとに連鎖ダメージ+<color=#00F6FF>7%</color>",
  str_skill_desc_300046 = "任意の1マスにララを置き、ララを中心として、<color=#00F6FF>全て</color>の敵を引き寄せる。また印を5スタック持っている敵に<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与する。2ターン持続",
  str_skill_desc_302046 = "任意の1マスにララを置き、ララを中心として、<color=#00F6FF>全て</color>の敵を引き寄せる。また印を4スタック持っている敵には２ターンの<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与し、印を6スタック持っている敵には1ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>状態を付与する",
  str_skill_desc_305046 = "任意の1マスにララを置き、ララを中心として、<color=#00F6FF>全て</color>の敵を引き寄せる。また印を4スタック持っている敵には２ターンの<link=\"10006\"><#FFAE07><u>減速</u></color></link>状態を付与し、印を6スタック持っている敵には<color=#00F6FF>1</color>ターンの<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>状態を付与する",
