  str_skill_name_2302371 = "揺りかごが捕まえる夢",
  str_skill_name_2302372 = "揺りかごが捕まえる夢",
  str_skill_name_2302373 = "揺りかごが捕まえる夢",
  str_skill_name_3002371 = "夢浪招来",
  str_skill_name_3032371 = "夢浪招来",
  str_skill_name_3202371 = "夢浪招来",
  str_skill_name_3232371 = "夢浪招来",
  str_skill_desc_2002371 = "<color=#00F6FF>菱形12マス</color>の範囲に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2002372 = "<color=#00F6FF>菱形12マス</color>の範囲内で最も近くにいる敵を中心に、<color=#00F6FF>菱形13マス</color>の範囲に<color=#00F6FF>170%</color>のダメージを与える",
  str_skill_desc_2002373 = "<color=#00F6FF>周囲2マス</color>の範囲内で最も近くにいる敵を中心に、<color=#00F6FF>菱形13マス</color>の範囲に<color=#00F6FF>180%</color>のダメージを与える",
  str_skill_desc_2302371 = "<color=#00F6FF>菱形12マス</color>の範囲に<color=#00F6FF>160%</color>のダメージを与える",
  str_skill_desc_2302372 = "<color=#00F6FF>菱形12マス</color>の範囲内で最も近くにいる敵を中心に、<color=#00F6FF>菱形13マス</color>の範囲に<color=#00F6FF>170%</color>のダメージを与え、その敵がいる位置にシャイニーバブルを1体召喚する",
  str_skill_desc_2302373 = "<color=#00F6FF>周囲2マス</color>の範囲内で最も近くにいる敵を中心に、<color=#00F6FF>菱形13マス</color>の範囲に<color=#00F6FF>180%</color>のダメージを与え、その敵がいる位置にシャイニーバブルを1体召喚する",
  str_skill_desc_3002371 = "<color=#00F6FF>菱形12マス</color>の範囲内にある進入可能なマスから1つを選んで起点とし、障害物を無視して<color=#00F6FF>水属性マス</color>を任意の数連鎖させたあと、連鎖の終点マスに瞬間移動する。終点マスに敵がいる場合、その敵に<color=#00F6FF>200%</color>のダメージを与え、自身はその敵の周囲のマスに移動する",
  str_skill_desc_3032371 = "<color=#00F6FF>菱形12マス</color>の範囲内にある進入可能なマスから1つを選んで起点とし、障害物を無視して<color=#00F6FF>水属性マス</color>を任意の数連鎖させたあと、連鎖の終点マスに瞬間移動する。終点マスに敵がいる場合、その敵に<color=#00F6FF>300%</color>のダメージを与え、自身はその敵の周囲のマスに移動する",
  str_skill_desc_3202371 = "<color=#00F6FF>菱形12マス</color>の範囲内にある進入可能なマスから1つを選んで起点とし、障害物を無視して<color=#00F6FF>水属性マス、濃色マス、シャイニーバブルがいるマス</color>を任意の数連鎖させたあと、連鎖の終点マスに瞬間移動する。終点マスに敵がいる場合、その敵に<color=#00F6FF>200%</color>のダメージを与え、自身はその敵の周囲のマスに移動する",
  str_skill_desc_3232371 = "<color=#00F6FF>菱形12マス</color>の範囲内にある進入可能なマスから1つを選んで起点とし、障害物を無視して<color=#00F6FF>水属性マス、濃色マス、シャイニーバブルがいるマス</color>を任意の数連鎖させたあと、連鎖の終点マスに瞬間移動する。終点マスに敵がいる場合、その敵に<color=#00F6FF>300%</color>のダメージを与え、自身はその敵の周囲のマスに移動する",
  str_skill_passive_name_4102371 = "鏡花水月",
  str_skill_passive_desc_4102371 = "毎ターン開始時、フィールド上のランダムな<color=#00F6FF>2</color>つの進入可能なマスにシャイニーバブルを召喚する。3ターン持続。連鎖移動、または能動技による連鎖でシャイニーバブルを通過すると、<color=#00F6FF>周囲3マス</color>の範囲内にいる敵3体に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_name_4402371 = "鏡花水月",
  str_skill_passive_desc_4402371 = "毎ターン開始時、フィールド上のランダムな<color=#00F6FF>2</color>つの進入可能なマスにシャイニーバブルを召喚する。3ターン持続。連鎖移動、または能動技による連鎖でシャイニーバブルを通過すると、<color=#00F6FF>周囲3マス</color>の範囲内にいる敵3体に<color=#00F6FF>140%</color>のダメージを与える",
  str_skill_passive_name_4502371 = "鏡花水月",
  str_skill_passive_desc_4502371 = "毎ターン開始時、フィールド上のランダムな<color=#00F6FF>2</color>つの進入可能なマスにシャイニーバブルを召喚する。3ターン持続。連鎖移動、または能動技による連鎖でシャイニーバブルを通過すると、<color=#00F6FF>周囲3マス</color>の範囲内にいる敵4体に<color=#00F6FF>140%</color>のダメージを与える",
  str_skill_passive_name_4602371 = "鏡花水月",
  str_skill_passive_desc_4602371 = "毎ターン開始時、フィールド上のランダムな<color=#00F6FF>2</color>つの進入可能なマスにシャイニーバブルを召喚する。3ターン持続。連鎖移動、または能動技による連鎖でシャイニーバブルを通過すると、<color=#00F6FF>周囲3マス</color>の範囲内にいる敵4体に<color=#00F6FF>140%</color>のダメージを与える。濃色マス、またはシャイニーバブルを通過すると幻影エネルギーが1スタックされ、幻影エネルギー1ごとに連鎖技ダメージ+<color=#00F6FF>1%</color>",
  str_skill_passive_name_4162371 = "鏡花水月",
  str_skill_passive_desc_4162371 = "毎ターン開始時、フィールド上のランダムな<color=#00F6FF>3</color>つの進入可能なマスにシャイニーバブルを召喚する。5ターン持続。連鎖移動、または能動技による連鎖でシャイニーバブルを通過すると、<color=#00F6FF>周囲3マス</color>の範囲内にいる敵3体に<color=#00F6FF>{1}</color>のダメージを与える",
  str_skill_passive_name_4462371 = "鏡花水月",
  str_skill_passive_desc_4462371 = "毎ターン開始時、フィールド上のランダムな<color=#00F6FF>3</color>つの進入可能なマスにシャイニーバブルを召喚する。5ターン持続。連鎖移動、または能動技による連鎖でシャイニーバブルを通過すると、<color=#00F6FF>周囲3マス</color>の範囲内にいる敵3体に<color=#00F6FF>140%</color>のダメージを与える",
  str_skill_passive_name_4562371 = "鏡花水月",
  str_skill_passive_desc_4562371 = "毎ターン開始時、フィールド上のランダムな<color=#00F6FF>3</color>つの進入可能なマスにシャイニーバブルを召喚する。5ターン持続。連鎖移動、または能動技による連鎖でシャイニーバブルを通過すると、<color=#00F6FF>周囲3マス</color>の範囲内にいる敵4体に<color=#00F6FF>140%</color>のダメージを与える",
  str_skill_passive_name_4662371 = "鏡花水月",
  str_skill_passive_desc_4662371 = "毎ターン開始時、フィールド上のランダムな<color=#00F6FF>3</color>つの進入可能なマスにシャイニーバブルを召喚する。5ターン持続。連鎖移動、または能動技による連鎖でシャイニーバブルを通過すると、<color=#00F6FF>周囲3マス</color>の範囲内にいる敵4体に<color=#00F6FF>140%</color>のダメージを与える。濃色マス、またはシャイニーバブルを通過すると幻影エネルギーが1スタックされ、幻影エネルギー1ごとに連鎖技ダメージ+<color=#00F6FF>1%</color>",
  str_skill_upgrade_refine_desc_16023711 = "装備技強化：シャイニーバブル接触時に与えるダメージが<color=#00F6FF>140%</color>に上昇する",
  str_skill_upgrade_refine_desc_16023712 = "装備技強化：シャイニーバブルに接触時、範囲内にいる敵<color=#00F6FF>4</color>体にダメージを与える",
  str_skill_upgrade_refine_desc_16023713 = "装備技強化：濃色マス、またはシャイニーバブルを通過すると幻影エネルギーが1スタックされ、幻影エネルギー1ごとに連鎖技ダメージ+<color=#00F6FF>1%</color>",
  str_skill_upgrade_desc_16023713 = "能動技強化：技のCDターン数<color=#FFFF00>-1</color>。終点マスに敵がいる場合、その敵に<color=#FFFF00>300%</color>のダメージを与える",
  str_skill_upgrade_desc_16023716 = "装備技強化：シャイニーバブルの持続時間が5ターンに増加し、毎ターン開始時に召喚されるシャイニーバブルの数+1",
  str_skill_name_291020103 = "苦境からの追撃",
  str_skill_name_291020104 = "愛の渇望",
  str_skill_name_291020105 = "セイレーンの悲鳴",
  str_skill_desc_291020103 = "光霊にダメージを与え、光霊の周囲に大砲を設置する。自身のHPが70%/40%未満になると、それぞれ設置数+1",
  str_skill_desc_291020104 = "自身の周囲1マスの範囲内で光霊から最も離れているマスにデマンドを設置する。自身のHPが50%未満になると、設置数+1",
  str_skill_desc_291020105 = "光霊に合計3回の徐々に増加するダメージを与え、フィールドの端までノックバックする",
  str_skill_desc_291020113 = "光霊にダメージを与え、光霊の周囲に大砲を召喚する。",
  str_skill_passive_desc_443173 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果発動ごとに（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）、直ちにフィールド上のランダムな敵<color=#00F6FF>1</color>体に<color=#00F6FF>85%</color>のダメージを与える。戦闘開始時、凡客の印を<color=#00F6FF>33</color>スタック獲得し、強化マスが効果発動するごとに、<color=#00F6FF>1</color>スタック減少する。印がクリアされると、戦闘終了まで強化形態に変化：基礎攻撃力+<color=#00F6FF>25%</color>、通常攻撃で斜め方向に攻撃可能、装備技のダメージが<color=#00F6FF>2.5</color>倍、連鎖技が同一の敵への命中時ダメージ減少しない",
  str_skill_passive_desc_453173 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果発動ごとに（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）、直ちにフィールド上のランダムな敵<color=#00F6FF>1</color>体に<color=#00F6FF>85%</color>のダメージを与える。戦闘開始時、凡客の印を<color=#00F6FF>33</color>スタック獲得し、強化マスが効果発動するごとに、<color=#00F6FF>1</color>スタック減少する。印がクリアされると、戦闘終了まで強化形態に変化：基礎攻撃力+<color=#00F6FF>25%</color>、通常攻撃で斜め方向に攻撃可能、装備技のダメージが<color=#00F6FF>2.5</color>倍、連鎖技の発動条件がそれぞれ<color=#00F6FF>1/2/3</color>減少し、同一の敵への命中時ダメージ減少しない",
  str_skill_passive_desc_463173 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果発動ごとに（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）、直ちにフィールド上のランダムな敵<color=#00F6FF>1</color>体に<color=#00F6FF>85%</color>のダメージを与える。戦闘開始時、凡客の印を<color=#00F6FF>33</color>スタック獲得し、強化マスが効果発動するごとに、<color=#00F6FF>1</color>スタック減少する。印がクリアされると、戦闘終了まで強化形態に変化：基礎攻撃力+<color=#00F6FF>25%</color>、通常攻撃で斜め方向に攻撃可能、装備技のダメージが<color=#00F6FF>2.5</color>倍、連鎖技の発動条件がそれぞれ<color=#00F6FF>1/2/3</color>減少し、同一の敵への命中時ダメージ減少しない。さらに能動技ダメージ係数が<color=#00F6FF>200%</color>に上昇",
  str_skill_passive_desc_440173 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果発動ごとに（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）、直ちにフィールド上のランダムな敵<color=#00F6FF>1</color>体に<color=#00F6FF>85%</color>のダメージを与える。戦闘開始時、凡客の印を<color=#00F6FF>33</color>スタック獲得し、強化マスが効果発動するごとに、<color=#00F6FF>1</color>スタック減少する。印がクリアされると、戦闘終了まで強化形態に変化：基礎攻撃力+<color=#00F6FF>20%</color>、通常攻撃で斜め方向に攻撃可能、装備技のダメージが<color=#00F6FF>2.5</color>倍、連鎖技が同一の敵への命中時ダメージ減少しない",
  str_skill_passive_desc_450173 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果発動ごとに（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）、直ちにフィールド上のランダムな敵<color=#00F6FF>1</color>体に<color=#00F6FF>85%</color>のダメージを与える。戦闘開始時、凡客の印を<color=#00F6FF>33</color>スタック獲得し、強化マスが効果発動するごとに、<color=#00F6FF>1</color>スタック減少する。印がクリアされると、戦闘終了まで強化形態に変化：基礎攻撃力+<color=#00F6FF>20%</color>、通常攻撃で斜め方向に攻撃可能、装備技のダメージが<color=#00F6FF>2.5</color>倍、連鎖技の発動条件がそれぞれ<color=#00F6FF>1/2/3</color>減少し、同一の敵への命中時ダメージ減少しない",
  str_skill_passive_desc_460173 = "<link=\"20001\"><#FFAE07><u>強化マス</u></color></link>の効果発動ごとに（<link=\"30065\"><#FFAE07><u>吸収</u></color></link>を含む）、直ちにフィールド上のランダムな敵<color=#00F6FF>1</color>体に<color=#00F6FF>85%</color>のダメージを与える。戦闘開始時、凡客の印を<color=#00F6FF>33</color>スタック獲得し、強化マスが効果発動するごとに、<color=#00F6FF>1</color>スタック減少する。印がクリアされると、戦闘終了まで強化形態に変化：基礎攻撃力+<color=#00F6FF>20%</color>、通常攻撃で斜め方向に攻撃可能、装備技のダメージが<color=#00F6FF>2.5</color>倍、連鎖技の発動条件がそれぞれ<color=#00F6FF>1/2/3</color>減少し、同一の敵への命中時ダメージ減少しない。さらに能動技ダメージ係数が<color=#00F6FF>200%</color>に上昇",
  str_skill_upgrade_refine_desc_16017311 = "装備技強化：ダメージ係数が85%に上昇する",
  str_skill_upgrade_refine_desc_16017312 = "装備技強化：強化形態に変化後、連鎖技の発動条件がそれぞれ1/2/3減少する",
  str_skill_upgrade_refine_desc_16017313 = "装備技強化：強化形態に変化後、能動技のダメージ係数が200%に上昇する",
  str_skill_upgrade_refine_desc_14016911 = "装備技強化：サディの基礎攻撃力+<color=#00F6FF>33%</color>。撃墜値1点につき、能動技ダメージ係数+<color=#00F6FF>22%</color>",
  str_skill_upgrade_refine_desc_14016912 = "装備技強化：濃色マスを通過するたびに<color=#00F6FF>撃墜値</color>+1",
  str_skill_upgrade_refine_desc_14016913 = "能動技強化：選択可能範囲が<color=#00F6FF>周囲1マス</color>に拡大する",
  str_skill_passive_desc_440169 = "サディの基礎攻撃力+<color=#00F6FF>33%</color>。サディは連鎖ごとに最大で<color=#00F6FF>3</color>回まで通常攻撃し、3回目の通常攻撃のダメージは2倍になる。4回目以降は通常攻撃の代わりに<color=#00F6FF>撃墜値</color>を1点獲得し、撃墜値1点につき、能動技ダメージ係数+<color=#00F6FF>22%</color>。撃墜値は能動技発動後にクリアされる",
  str_skill_passive_desc_450169 = "サディの基礎攻撃力+<color=#00F6FF>33%</color>。サディは連鎖ごとに最大で<color=#00F6FF>3</color>回まで通常攻撃し、3回目の通常攻撃のダメージは2倍になる。4回目以降は通常攻撃の代わりに<color=#00F6FF>撃墜値</color>を1点獲得し、撃墜値1点につき、能動技ダメージ係数+<color=#00F6FF>22%</color>。撃墜値は能動技発動後にクリアされる。濃色マスを通過するたびに、追加で<color=#00F6FF>撃墜値</color>+1",
  str_skill_name_360169 = "ノックアウト",
  str_skill_name_365169 = "ノックアウト",
  str_skill_desc_360169 = "<color=#00F6FF>周囲1マス</color>内にいる敵1体に<color=#00F6FF>300%</color>のダメージを与え、2マスノックバックする。ノックバックを<color=#00F6FF>阻まれた</color>場合、追加で<color=#00F6FF>200%</color>のダメージを与え、1ターンの<color=#00F6FF>眩暈</color>状態にする。ノックバックを阻んだ障害が別の敵だった場合、その敵にもダメージを与え、眩暈状態にする",
  str_skill_desc_365169 = "<color=#00F6FF>周囲1マス</color>内にいる敵1体に<color=#00F6FF>300%</color>のダメージを与え、3マスノックバックする。ノックバックを<color=#00F6FF>阻まれた</color>場合、追加で<color=#00F6FF>200%</color>のダメージを与え、1ターンの<color=#00F6FF>眩暈</color>状態にする。ノックバックを阻んだ障害が別の敵だった場合、その敵にもダメージを与え、眩暈状態にする",
  str_skill_name_20053011 = "深海の囁き",
  str_skill_desc_20053011 = "自身の周囲1マスの範囲内にいる敵にダメージを与える。",
  str_skill_name_20054011 = "接触",
  str_skill_desc_20054011 = "自身の周囲2マスの範囲内に光霊がいると、光霊の近くに自身の戦闘を助けるための暗鬼を1体召喚する。",
  str_skill_upgrade_desc_17023613 = "能動技強化：毎ターン開始時にフォースを5獲得する",
  str_skill_upgrade_desc_17023616 = "能動技追加：祭剣座が離脱状態時に発動できる。ただちにチームに復帰し、途中のマスに<color=#00F6FF>550%</color>のダメージを与える",
  str_skill_passive_name_4102361 = "運命への怒号",
  str_skill_name_2002361 = "チェルニーの奇跡",
  str_skill_name_2002362 = "チェルニーの奇跡",
