  str_skill_name_2002364 = "チェルニーの奇跡",
  str_skill_name_3302361 = "切り開く決意",
  str_skill_name_3302362 = "帰ってきた流星",
  str_skill_desc_3302361 = "戦闘中<link=\"30125\"><#FFAE07><u>フォース</u></color></link>を獲得できる。技を発動すると祭剣座は特殊な出撃モードに入り、このモード中は祭剣座単独に対して<link=\"30127\"><#FFAE07><u>連鎖操作</u></color></link>を行える。連鎖が完了すると祭剣座は<link=\"30128\"><#FFAE07><u>離脱状態</u></color></link>となり、連鎖の終点位置に<link=\"30129\"><#FFAE07><u>残影</u></color></link>を残し、次に能動技を発動するときの連鎖の起点とする",
  str_skill_desc_3332361 = "戦闘中<link=\"30126\"><#FFAE07><u>フォース</u></color></link>を獲得できる。技を発動すると祭剣座は特殊な出撃モードに入り、このモード中は祭剣座単独に対して<link=\"30127\"><#FFAE07><u>連鎖操作</u></color></link>を行える。連鎖が完了すると祭剣座は<link=\"30128\"><#FFAE07><u>離脱状態</u></color></link>となり、連鎖の終点位置に<link=\"30129\"><#FFAE07><u>残影</u></color></link>を残し、次に能動技を発動するときの連鎖の起点とする",
  str_skill_desc_3302362 = "祭剣座が離脱状態時に発動できる。ただちにチームに復帰し、途中のマスに<color=#00F6FF>550%</color>のダメージを与える",
  str_skill_desc_2002361 = "<color=#00F6FF>隣接する4マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002362 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。離脱状態でない場合はフォースを3獲得する",
  str_skill_desc_2002363 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える。離脱状態でない場合はフォースを4獲得する",
  str_skill_desc_2002364 = "<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>175%</color>のダメージを与える。離脱状態でない場合はフォースを5獲得する",
  str_skill_passive_desc_4102361 = "祭剣座は<color=#00F6FF>無属性</color>の光霊であり、攻撃/被攻撃時の属性相性係数はすべて<color=#00F6FF>100%</color>となる。<color=#00F6FF>隊長の時は常に出撃しているが、隊員の時は連鎖したマスがすべて万色マスだった場合のみ出撃する</color>。能動技でフォースを1消費するたびに星の力を1スタック獲得し、星の力は1スタックにつきダメージ+<color=#00F6FF>{1}</color>。最大99スタック",
  str_skill_passive_desc_4402361 = "祭剣座は<color=#00F6FF>無属性</color>の光霊であり、攻撃/被攻撃時の属性相性係数はすべて<color=#00F6FF>100%</color>となる。<color=#00F6FF>隊長の時は常に出撃しているが、隊員の時は連鎖したマスがすべて万色マスだった場合のみ出撃する</color>。能動技でフォースを1消費するたびに星の力を1スタック獲得し、星の力は1スタックにつきダメージ+<color=#00F6FF>1.1%</color>。最大99スタック",
  str_skill_passive_desc_4602361 = "祭剣座は<color=#00F6FF>無属性</color>の光霊であり、攻撃/被攻撃時の属性相性係数はすべて<color=#00F6FF>100%</color>となる。<color=#00F6FF>隊長の時は常に出撃しているが、隊員の時は連鎖したマスがすべて万色マスだった場合のみ出撃する</color>。能動技でフォースを1消費するたびに星の力を2スタック獲得し、星の力は1スタックにつきダメージ+<color=#00F6FF>1.1%</color>。最大99スタック",
  str_skill_upgrade_refine_desc_17023611 = "装備技強化：係数が<color=#00F6FF>1.1%</color>に上昇する",
  str_skill_upgrade_refine_desc_17023612 = "<color=#00F6FF>4</color>段階目の連鎖技追加：必要な連鎖マスの数は12マス、周囲2マスに175%のダメージを与える。離脱状態でない場合はフォースを5獲得する",
  str_skill_upgrade_refine_desc_17023613 = "装備技強化：獲得する星の力のスタック数が<color=#FFFF00>2倍</color>になる",
  str_skill_upgrade_desc_16023813 = "能動技強化：能動技を<color=#FFFF00>先制攻撃</color>に変更する。戦闘開始後、即時使用可能になる",
  str_skill_upgrade_desc_16023816 = "能動技強化：選択可能なマスの数<color=#00F6FF>+1</color>",
  str_skill_name_2002381 = "羽隠しの刃",
  str_skill_desc_2002381 = "<color=#00F6FF>最も近くにいる敵1体</color>に羽刃を投げて170%のダメージを与え、その後さらに<color=#00F6FF>その敵から最も近い</color>別の敵を攻撃する。ターゲットまでの距離1マスごとに最終ダメージ+10%、最大+50%。連鎖数に応じてダメージ強化効果を獲得する",
  str_skill_name_3002381 = "導きのことば",
  str_skill_name_3062381 = "導きのことば",
  str_skill_name_3302381 = "導きのことば・変異Ⅰ",
  str_skill_name_3362381 = "導きのことば・変異Ⅰ",
  str_skill_desc_3002381 = "選択した<color=#00F6FF>5</color>マスを強化マスにする",
  str_skill_desc_3062381 = "選択した<color=#00F6FF>6</color>マスを強化マスにする",
  str_skill_desc_3302381 = "<color=#FFFF00>発動後、技のCDターン-1</color>。マスを<color=#00F6FF>3</color>つ選び、強化マスを生成する",
  str_skill_desc_3362381 = "<color=#FFFF00>発動後、技のCDターン-1</color>。マスを<color=#00F6FF>4</color>つ選び、強化マスを生成する",
  str_skill_passive_name_4102381 = "受け継ぎし星光",
  str_skill_passive_name_4162381 = "受け継ぎし星光",
  str_skill_passive_desc_4102381 = "<color=#00F6FF>強化マスを1マス</color>獲得するたびに、<color=#00F6FF>星光の印を1スタック</color>獲得する。連鎖技でダメージを与えるたびに、星光の印のスタック数の<color=#00F6FF>3分の1</color>を消費し、1スタックにつきチーム全員の平均攻撃力の<color=#00F6FF>{1}</color>のダメージを追加で与える",
  str_skill_passive_desc_4162381 = "<color=#00F6FF>強化マスを1マス</color>獲得するたびに、<color=#00F6FF>星光の印を1スタック</color>獲得する。連鎖技でダメージを与えるたびに、星光の印のスタック数の<color=#00F6FF>3分の1</color>を消費し、1スタックにつきチーム全員の平均攻撃力の<color=#00F6FF>{1}</color>のダメージを追加で与える。ターン内に強化マスを1マス獲得するたびに、連鎖技の発動条件-1",
  str_skill_upgrade_refine_desc_15017611 = "装備技強化：ベルタは通常攻撃を<color=#00F6FF>4</color>回行うごとに、現在のターゲットにアウストラリスの翅嵐を1スタック付与する",
  str_skill_upgrade_refine_desc_15017612 = "能動技強化：アウストラリスの翅嵐1つにつき、ターゲットに<color=#00F6FF>100%</color>のダメージを与える",
  str_skill_upgrade_refine_desc_15017613 = "能動技強化：ターゲットにダメージを与えたとき、アウストラリスの翅嵐1スタックつにつき、そのダメージの<color=#00F6FF>15%～22.5%</color>に相当するHPを回復する",
  str_skill_passive_desc_4401761 = "ベルタは通常攻撃を<color=#00F6FF>4</color>回行うごとに、現在のターゲットに<color=#00F6FF>アウストラリスの翅嵐</color>を<color=#00F6FF>1</color>スタック付与する",
  str_skill_passive_desc_4451761 = "ベルタは通常攻撃を<color=#00F6FF>4</color>回行うごとに、現在のターゲットに<color=#00F6FF>アウストラリスの翅嵐</color>を<color=#00F6FF>1</color>スタック付与する",
  str_skill_desc_3501761 = "<color=#00F6FF>周囲2マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>100%</color>のダメージを与え、そのダメージの<color=#00F6FF>10%～15%</color>に相当するHPを回復する。チームのHPが低いほど回復係数は高くなる",
  str_skill_desc_3521761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>100%</color>のダメージを与え、そのダメージの<color=#00F6FF>10%～15%</color>に相当するHPを回復する。チームのHPが低いほど回復係数は高くなる",
  str_skill_desc_3551761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>100%～120%</color>のダメージを与え、そのダメージの<color=#00F6FF>10%～15%</color>に相当するHPを回復する。ターゲットのHPが低いほどダメージ係数は高くなり、チームのHPが低いほど回復係数は高くなる",
  str_skill_desc_3601761 = "<color=#00F6FF>周囲2マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>100%</color>のダメージを与え、そのダメージの<color=#00F6FF>15%～22.5%</color>に相当するHPを回復する。チームのHPが低いほど回復係数は高くなる",
  str_skill_desc_3621761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>100%</color>のダメージを与え、そのダメージの<color=#00F6FF>15%～22.5%</color>に相当するHPを回復する。チームのHPが低いほど回復係数は高くなる",
  str_skill_desc_3651761 = "<color=#00F6FF>周囲3マス</color>の範囲内にいるすべての敵から<color=#00F6FF>アウストラリスの翅針</color>を抜き取り、1スタックにつき<color=#00F6FF>100%～120%</color>のダメージを与え、そのダメージの<color=#00F6FF>15%～22.5%</color>に相当するHPを回復する。ターゲットのHPが低いほどダメージ係数は高くなり、チームのHPが低いほど回復係数は高くなる",
  str_skill_name_3501821 = "蛟龍巻渦・変異Ⅰ",
  str_skill_name_3601821 = "蛟龍巻渦・変異Ⅱ",
  str_skill_desc_3501821 = "<color=#00F6FF>2</color>つの<link=\"30074\"><#FFAE07><u>「浄龍輝」</u></color></link>が点灯時、能動技が発動可能になり、<color=#FFFF00>発動後に2つの「浄龍輝」が消灯する</color>。1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>400%</color>のダメージを与え、装備技「遺月残光」を発動しない",
  str_skill_desc_3601821 = "<color=#00F6FF>3</color>つの<link=\"30074\"><#FFAE07><u>「浄龍輝」</u></color></link>が点灯時、能動技が発動可能になり、<color=#FFFF00>発動後に2つの「浄龍輝」が消灯する</color>。装備技「遺月残光」を発動し、敵<color=#00F6FF>全体</color>に<color=#00F6FF>300%</color>のダメージを与える",
  str_skill_upgrade_refine_desc_16018211 = "能動技強化：ダメージ係数が400%まで上昇する",
  str_skill_upgrade_refine_desc_16018212 = "<color=#00F6FF>能動技変異Ⅰを追加</color>：2つの「浄龍輝」が点灯時、能動技が発動可能になり、発動後に2つの「浄龍輝」が消灯する。1マス選択し、菱形13マスに400%のダメージを与え、装備技「遺月残光」を発動しない",
  str_skill_upgrade_refine_desc_16018213 = "<color=#00F6FF>能動技変異Ⅱを追加</color>：2つの「浄龍輝」が点灯時、能動技が発動可能になり、発動後に2つの「浄龍輝」が消灯する。装備技「遺月残光」を発動し、敵全体に300%のダメージを与える",
  str_skill_desc_3401821 = "<color=#00F6FF>3</color>つの<link=\"30074\"><#FFAE07><u>「浄龍輝」</u></color></link>が点灯時、能動技が発動可能になる。1マス選択し、<color=#00F6FF>菱形13マス</color>に<color=#00F6FF>400%</color>のダメージを与える。発動後にすべての「浄龍輝」が消灯する",
  str_skill_upgrade_desc_16024113 = "能動技強化：能動技のCDターン数<color=#00F6FF>-1</color>。ダメージ係数+<color=#00F6FF>50%</color>",
  str_skill_upgrade_desc_16024116 = "能動技変異追加：消費する理性値と与ダメージが<color=#00F6FF>2倍になり</color>、濃色マスを最大<color=#00F6FF>3</color>マス生成する",
  str_skill_name_2002411 = "自由への爆轟",
  str_skill_name_2002412 = "自由への爆轟",
  str_skill_name_2002413 = "自由への爆轟",
  str_skill_name_2302411 = "自由への爆轟",
  str_skill_name_2302412 = "自由への爆轟",
  str_skill_name_2302413 = "自由への爆轟",
  str_skill_name_3002411 = "狂華の舞い",
  str_skill_name_3032411 = "狂華の舞い",
  str_skill_name_3062411 = "狂華の舞い・変異Ⅰ",
  str_skill_desc_2002411 = "<color=#00F6FF>周囲1マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002412 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2002413 = "<color=#00F6FF>周囲2マス</color>以内に<color=#00F6FF>{1}%</color>のダメージを与える",
  str_skill_desc_2302411 = "<color=#00F6FF>周囲1マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、隣接する4マス内の濃色マスを<link=\"30124\"><#FFAE07><u>吸収</u></color></link>する",
  str_skill_desc_2302412 = "<color=#00F6FF>菱形12マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、周囲1マス内の濃色マスを<link=\"30124\"><#FFAE07><u>吸収</u></color></link>する",
  str_skill_desc_2302413 = "<color=#00F6FF>周囲2マス</color>に<color=#00F6FF>{1}%</color>のダメージを与え、周囲菱形12マス内の濃色マスを<link=\"30124\"><#FFAE07><u>吸収</u></color></link>する",
  str_skill_desc_3002411 = "戦闘時、ペピータが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を<color=#00F6FF>15</color>消費して選択した敵1体に150%のダメージを与え、足元にランダムで濃色マスを1マス生成する",
  str_skill_desc_3032411 = "戦闘時、ペピータが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を<color=#00F6FF>15</color>消費して選択した敵1体に200%のダメージを与え、足元にランダムで濃色マスを1マス生成する",
  str_skill_desc_3062411 = "戦闘時、ペピータが<link=\"30039\"><#FFAE07><u>【理性システム】</u></color></link>を発動する。理性値を<color=#00F6FF>30</color>消費して選択した敵1体に400%のダメージを与え、足元にランダムで濃色マスを最大3マス生成する",
  str_skill_passive_name_4102411 = "心炎の躍動",
  str_skill_passive_name_4202411 = "心炎の躍動",
  str_skill_passive_desc_4102411 = "濃色マスを獲得するたびに、ペピータが心の炎を<color=#00F6FF>1</color>スタック獲得する。最大<color=#00F6FF>7</color>スタックまで。現在の隊長が通常攻撃を繰り出すたび、心の炎を1スタック消費し、その通常攻撃の最終ダメージ+<color=#00F6FF>{1}</color>",
  str_skill_passive_desc_4202411 = "濃色マスを獲得するたびに、ペピータが心の炎を<color=#00F6FF>1</color>スタック獲得する。最大<color=#00F6FF>7</color>スタックまで。現在の隊長が通常攻撃を繰り出すたび、心の炎を1スタック消費し、その通常攻撃の最終ダメージ+<color=#00F6FF>{1}</color>。毎ターン開始時、フィールド上のすべての敵の足元にランダムで濃色マスを<color=#00F6FF>2</color>マス生成する",
  str_skill_eng_name_300050 = "BLOODY DEVOUR",
  str_skill_eng_name_320050 = "BLOODY DEVOUR",
